export const REVIEW_CARDS: ReviewSubject[] = 
[{"s":"القلبية","topics":[{"t":"التظاهرات السريرية","cards":[{"f":"الخناق الصدري المستقر (Stable angina): صفات الألم الكلاسيكية؟","b":"ألم ضاغط/عاصر خلف القص (Heaviness/pressure) يثار بالجهد أو الانفعال ويزول بالراحة أو النتروغليسرين تحت اللسان خلال دقائق؛ قد ينتشر للذراع اليسرى أو الفك أو الظهر — ليس طاعنًا ولا يتغير بالتنفس أو الجس."},{"f":"ما الذي يميز ألم المتلازمة الإكليلية الحادة عن الخناق المستقر؟","b":"أشد وأطول (>20 دقيقة)، قد يحدث بالراحة أو بجهد أقل من المعتاد، جديد الظهور أو متزايد الشدة والتكرار، ويحتاج غالبًا عدة جرعات نتروغليسرين أو راحة مطولة للزوال."},{"f":"علامة ليفاين (Levine sign)؟","b":"قبضة اليد المطبقة على الصدر لوصف الألم العاصر — إيماءة كلاسيكية تشير لألم إقفاري قلبي."},{"f":"ضيق النفس الاضطجاعي (Orthopnea) وضيق النفس الاشتدادي الليلي (PND): الآلية والدلالة؟","b":"احتقان رئوي بسب فشل البطين الأيسر: الاستلقاء يعيد توزيع الدم للأوعية الرئوية فيظهر ضيق النفس؛ الـPND يوقظ المريض بعد 1-2 ساعة نوم لتراكم الوذمة الخلالية — كلاهما يدل على احتقان رئوي."},{"f":"تصنيف NYHA لقصور القلب؟","b":"I: لا أعراض مع النشاط المعتاد. II: أعراض خفيفة مع النشاط المعتاد. III: أعراض مع أقل من النشاط المعتاد. IV: أعراض بالراحة."},{"f":"الغشي الوعائي المبهمي (Vasovagal): المحرضات والآلية؟","b":"محرضات: الوقوف المطول، الحرارة، الألم، رؤية الدم. الآلية: منعكس مبهمي ← توسع وعائي + بطء قلب ← نقص تروية دماغية عابر؛ يسبقه غالبًا غثيان وتعرق وشحوب."},{"f":"الغشي الظرفي (Situational syncope): أمثلة؟","b":"مرتبط بتمدد أحشاء جوفاء: التبول، التغوط، السعال، ما بعد الجهد — منعكس مبهمي يسبب توسعًا وعائيًا وبطء قلب."},{"f":"غشي الجيب السباتي (Carotid sinus syncope): لمن يحدث؟","b":"أقل من 1% من الغشي عمومًا لكنه يفسر 25-50% من الغشي غير المفسر بعد سن 50؛ فرط حساسية مستقبلات الضغط السباتية — محرضات: الحلاقة، تدوير الرأس، ربطة عنق ضيقة."},{"f":"الخفقان (Palpitations): متى يوحي بخطورة؟","b":"بدء/توقف مفاجئ، ترافق مع غشي أو ألم صدر أو ضيق نفس، قصة عائلية للموت المفاجئ — توحي باضطراب نظم (رجفان أذيني، تسرع بطيني، WPW)."},{"f":"الوذمة القلبية: صفاتها؟","b":"انطباعية (Pitting)، متناظرة، تبدأ بالكاحلين وتتصاعد نهارًا وتخف ليلًا؛ مع احتقان وريدي ودي (JVD) وضخامة كبد — تدل على فشل القلب الأيمن أو احتقان جهازي."}]},{"t":"قصور القلب","cards":[{"f":"تعريف HFrEF وHFpEF وHFmrEF حسب الكسر القذفي (EF)؟","b":"HFrEF: ‏EF ≤40%. HFmrEF: ‏EF 41-49%. HFpEF: ‏EF ≥50% مع أدلة احتقان/خلل انبساطي."},{"f":"الأعمدة الأربعة للعلاج الموجه بالدلائل (GDMT) في HFrEF؟","b":"1) مثبط ACE أو ARNI (ساكوبيتريل/فالسارتان). 2) حاصر بيتا (كارفيديلول/ميتوبرولول/بيسوبرولول). 3) مضاد ألدوستيرون MRA (سبيرونولاكتون/إبليرينون). 4) مثبط SGLT2 (داباغليفلوزين/إمباغليفلوزين)."},{"f":"عند التحويل من مثبط ACE إلى ARNI: ما فترة الغسيل ولماذا؟","b":"36 ساعة على الأقل بين إيقاف مثبط ACE وبدء ARNI لتجنب الوذمة الوعائية (Angioedema) — الساكوبيتريل يثبط النيبريليزين الذي يستقلب البراديكينين."},{"f":"تجربة PARADIGM-HF: ماذا أثبتت؟","b":"الساكوبيتريل/فالسارتان (ARNI) خفّض الوفيات القلبية الوعائية والاستشفاء لقصور القلب مقارنة بالإنالابريل في HFrEF بنسبة ~20%."},{"f":"تجربتا DAPA-HF وDELIVER: ماذا أثبتتا؟","b":"الداباغليفلوزين خفّض الوفاة القلبية الوعائية والاستشفاء لقصور القلب في HFrEF (DAPA-HF) وأيضًا في HFpEF/HFmrEF (DELIVER) — فائدة مستقلة عن السكري."},{"f":"HFpEF: الصفات الديموغرافية المميزة؟","b":"أكبر سنًا، غالبية إناث، مع ارتفاع ضغط، سكري، بدانة، رجفان أذيني، قصور كلوي مزمن — الأعراض لا تُميَّز عن HFrEF."},{"f":"معايير فرامنغهام لتشخيص قصور القلب: أمثلة كبرى وصغرى؟","b":"كبرى: ضيق نفس اشتدادي ليلي، انتفاخ أوردة الرقبة، خراخر رئوية، ضخامة قلب شعاعيًا، وذمة رئة حادة، صوت S3، ارتفاع ضغط وريدي مركزي >16. صغرى: وذمة كاحلين، سعال ليلي، ضيق جهد، ضخامة كبد، انصباب جنب. التشخيص: معياران كبيران أو كبير+صغيران."},{"f":"الصوت القلبي الثالث (S3): دلالته؟","b":"صوت انبساطي مبكر منخفض التردد يدل على امتلاء بطيني سريع — مرضي عند البالغين ويشير لقصور قلب/حمل زائد حجمي."},{"f":"دور المدرات في قصور القلب الحاد اللا تعويضي؟","b":"المدرات العروية الوريدية (فوروسيميد) هي حجر الأساس لعلاج الاحتقان الحاد — تخفف الأعراض الاحتقانية لكنها لا تحسّن البقيا."},{"f":"استطبابات جهاز إعادة التزامن القلبي (CRT)؟","b":"HFrEF مع ‏EF ≤35% وأعراض NYHA II-IV رغم GDMT المثالي، ونظم جيبي مع QRS عريض — الأفضل: حصار غصن أيسر LBBB وQRS ≥150 ms."},{"f":"استطباب مزيل الرجفان القابل للزرع (ICD) للوقاية الأولية؟","b":"HFrEF مع ‏EF ≤35% وأعراض NYHA II-III رغم ≥3 أشهر من GDMT المثالي، مع توقع بقيا >سنة — للوقاية من الموت المفاجئ."},{"f":"دور الديجوكسين في قصور القلب الحديث؟","b":"لا يحسّن البقيا؛ يُستخدم لتخفيف الأعراض وتقليل الاستشفاء، ولضبط معدل البطين في الرجفان الأذيني — هامش علاجي ضيق (سمية: اضطرابات نظم، غثيان، اضطراب رؤية بالألوان)."},{"f":"BNP / NT-proBNP في قصور القلب؟","b":"يُفرز من البطينين عند تمددهما/زيادة الضغط الجداري — قيمته التشخيصية عالية بالنفي (قيمة منخفضة تنفي قصور القلب الحاد غالبًا)؛ يرتفع أيضًا بالعمر والقصور الكلوي والرجفان الأذيني."},{"f":"موانع استخدام موسعات الأوعية (كالنتروغليسرين) في قصور القلب؟","b":"تضيق الأبهر الشديد، اعتلال العضلة الضخامي الانسدادي (HOCM)، الدكاك القلبي — لأن خفض التحميل القبلي يفاقم الانسداد/نقص النتاج."}]},{"t":"الداء الإكليلي","cards":[{"f":"تشخيص احتشاء STEMI على التخطيط: معايير ارتفاع ST؟","b":"ارتفاع ST ≥1 مم في مسريين متجاورين بالأطراف أو ≥2 مم بالصدر (V2-V3: ≥2 مم للرجال ≥40 سنة، ≥2.5 مم للرجال <40، ≥1.5 مم للنساء) أو حصار غصن أيسر جديد — مع ألم صدري إقفاري."},{"f":"توطين الاحتشاء على التخطيط: أمامي/سفلي/وحشي/خلفي؟","b":"أمامي: V1-V4 (الشريان الأمامي النازل LAD). سفلي: II وIII وaVF (الأيمن RCA غالبًا). وحشي: I وaVL وV5-V6 (المنعطف LCx). خلفي: R عالية بـV1-V3 مع انخفاض ST أمامي (مرآة)."},{"f":"احتشاء البطين الأيمن: العلامات المميزة والعلاج؟","b":"ثالوث: انخفاض ضغط + انتفاخ أوردة الرقبة + رئتان صافيتان؛ ارتفاع ST بـV4R. العلاج: سوائل وريدية، تجنب النترات والمدرات (تخفض التحميل القبلي)."},{"f":"التروبونين: متى يرتفع ومتى يبلغ ذروته؟","b":"يرتفع خلال 3-6 ساعات من بدء الألم، يبلغ الذروة 12-24 ساعة، ويبقى مرتفعًا 7-10 أيام (تروبونين I) — الأكثر نوعية لتنخر العضلة القلبية."},{"f":"العلاج الأمثل لاحتشاء STEMI الحاد؟","b":"إعادة التروية الإسعافية: قثطرة تداخلية أولية (Primary PCI) خلال 90-120 دقيقة من أول تماس طبي؛ إن تعذرت خلال 120 دقيقة يُعطى حالّ الخثرة (Fibrinolysis) خلال 30 دقيقة من الوصول."},{"f":"موانع حالّات الخثرة المطلقة؟","b":"نزف داخل القحف سابق، سكتة إقفارية خلال 3 أشهر، ورم/تشوه وعائي دماغي، نزف نشط، تشريح أبهر مشتبه، رضّ رأسي/وجهي شديد خلال 3 أشهر."},{"f":"الفرق بين NSTEMI والخناق غير المستقر؟","b":"كلاهما بلا ارتفاع ST؛ الـNSTEMI مع ارتفاع تروبونين (تنخر)، والخناق غير المستقر بتروبونين طبيعي (إقفار بلا تنخر) — التدبير الأولي متشابه (مضادات صفيحات + هيبارين + قثطرة مبكرة عالي الخطورة)."},{"f":"علامات الخطورة العالية في NSTE-ACS تستدعي قثطرة عاجلة؟","b":"عدم استقرار ديناميكي، ألم صدري مستمر رغم العلاج، اضطراب نظم مهدد، تغيرات ST ديناميكية ≥0.5 مم، ارتفاع تروبونين، قصور قلب حاد."},{"f":"مدة العلاج المزدوج المضاد للصفيحات (DAPT) بعد دعامة دوائية؟","b":"أسبرين + مثبط P2Y12 (كلوبيدوغريل/تيكاغريلور) لمدة 12 شهرًا بعد ACS؛ قد تُقصَّر لـ6 أشهر أو تطول حسب خطر النزف/الإقفار."},{"f":"متلازمة دريسلر (Dressler): ما هي ومتى تحدث؟","b":"التهاب تامور مناعي ذاتي بعد احتشاء عضلة قلبية (أو جراحة قلب) بأسابيع — حمى + ألم تاموري + انصباب جنب؛ تُعالج بالأسبرين/مضادات الالتهاب."},{"f":"تمزق الحاجز بين البطينين بعد الاحتشاء: التوقيت والعلامات؟","b":"يحدث عادة 3-5 أيام بعد احتشاء أمامي؛ نفخة انقباضية شاملة جديدة على الحد القصي الأيسر السفلي + تدهور ديناميكي + تحويلة يسار-يمين — إسعاف جراحي."},{"f":"تمزق العضلة الحليمية الحاد بعد الاحتشاء: العلامات؟","b":"يحدث 2-7 أيام بعد احتشاء سفلي/خلفي؛ نفخة قلس تاجي انقباضية شاملة جديدة بالقمة تنتشر للإبط + وذمة رئة حادة — إسعاف جراحي."},{"f":"علامة ويلنز (Wellens) على التخطيط: دلالتها؟","b":"موجات T مقلوبة متناظرة عميقة أو ثنائية الطور بـV2-V3 مع ألم زال — تضيق حرج بالـLAD القريب؛ تحذير من احتشاء أمامي وشيك (لا يُجرى اختبار جهد)."},{"f":"عوامل الخطورة الإكليلية الكبرى؟","b":"تدخين، سكري، ارتفاع ضغط، خلل شحوم (LDL مرتفع)، قصة عائلية مبكرة، عمر (رجال >45/نساء >55)، بدانة، خمول."}]},{"t":"أمراض الشغاف والصمامات","cards":[{"f":"معايير ديوك (Duke) المعدلة لتشخيص التهاب الشغاف الخمجي المؤكد سريريًا؟","b":"معياران كبيران، أو كبير + 3 صغار، أو 5 صغار. الكبيران: زرع دم إيجابي بجرثوم نموذجي + دليل إصابة شغافية (نباتات/خراج/قلس جديد بالإيكو)."},{"f":"الظواهر الوعائية والمناعية في التهاب الشغاف (أمثلة)؟","b":"وعائية: آفات جانواي (غير مؤلمة)، نزوف ملتحمة، احتشاءات. مناعية: عقد أوسلر (مؤلمة)، بقع روث، التهاب كبيبات، عامل روماتوئيدي."},{"f":"عقد أوسلر مقابل آفات جانواي: الفرق السريري؟","b":"عقد أوسلر: مؤلمة على رؤوس الأصابع (مناعية). آفات جانواي: غير مؤلمة على الراحتين والأخمصين (صمّية وعائية)."},{"f":"أشيع مسبب لالتهاب الشغاف الحاد على صمام طبيعي؟","b":"المكورات العنقودية الذهبية (S. aureus) — عدوانية وتخرب الصمام سريعًا؛ على الصمامات المتأذية/بعد إجراءات سنية: العقديات المخضرة (Viridans)."},{"f":"الوقاية بالمضادات من التهاب الشغاف: لمن ومتى؟","b":"للمرضى عالي الخطورة فقط (صمام اصطناعي، شغاف سابق، أمراض خلقية مزرقة) قبل الإجراءات السنية الغازية: أموكسيسيلين 2غ فموي قبل ساعة."},{"f":"ثالوث تضيق الأبهر العرضي الكلاسيكي؟","b":"خناق صدري + غشي جهدي + ضيق نفس (فشل قلب) — ظهور الأعراض ينذر بسوء الإنذار ويستدعي تبديل الصمام."},{"f":"نفخة تضيق الأبهر: صفاتها؟","b":"انقباضية قذفية (Crescendo-decrescendo) بالحيز الوربي الثاني الأيمن تنتشر للسباتيين، تزداد بالجلوس/الانحناء للأمام؛ S2 مفرد/متناقص الانقسام."},{"f":"نفخة قلس الأبهر: صفاتها؟","b":"انبساطية نافخة متناقصة (Decrescendo) بالحيز الثالث الأيسر، تُسمع أفضل بالانحناء للأمام مع حبس النفس بالزفير؛ نبض متسارع وضغط انبساطي منخفض."},{"f":"نفخة تضيق التاجي: صفاتها؟","b":"انبساطية منخفضة التردد بالقمة (تُسمع بالجرس بوضعية الاستلقاء الجانبي الأيسر)، يسبقها صوت انفتاح (Opening snap) وS1 عالٍ؛ ترتافق غالبًا بالرجفان الأذيني."},{"f":"نفخة قلس التاجي: صفاتها؟","b":"انقباضية شاملة (Holosystolic) بالقمة تنتشر للإبط، تزداد بقبضة اليد (زيادة التحميل البعدي) — S3 قد يُسمع بالقلس الشديد."},{"f":"نفخة غراهام ستيل (Graham Steell): متى تُسمع؟","b":"نفخة انبساطية نافخة متناقصة بعد P2 تزداد بالشهيق — قلس رئوي وظيفي بسبب ارتفاع الضغط الرئوي الشديد (PASP >70)."},{"f":"معايير جونز المعدلة للحمى الرثوية الحادة؟","b":"كبرى: التهاب قلب، التهاب مفاصل متنقل، رقاص سيدنهام، حمامى هامشية، عقد تحت جلد. صغرى: حمى، ألم مفصلي، ESR/CRP مرتفع، PR متطاول. التشخيص: 2 كبرى أو 1 كبرى+2 صغرى + دليل عدوى عقدية سابقة (ASO)."},{"f":"الوقاية الثانوية للحمى الرثوية؟","b":"بنزاثين بنسلين عضلي كل 3-4 أسابيع لسنوات (حتى 10 سنوات أو عمر 40 حسب إصابة القلب) لمنع النكس وتفاقم الداء الصمامي."},{"f":"تدبير هبوط الصمام التاجي (MVP) العرضي؟","b":"غالبًا سليم؛ حاصرات بيتا للخفقان/ألم الصدر؛ وقاية شغاف غير لازمة إلا بوجود قلس مهم — المتابعة بالإيكو الدوري."},{"f":"متى يُفضَّل TAVI على الجراحة بتضيق الأبهر الشديد؟","b":"للمرضى كبار السن/عالي الخطورة الجراحية أو المتوسطي الخطورة؛ الجراحة تبقى مفضلة للشباب وصغار السن ومن لديهم داء إكليلي/صمامي مرافق يحتاج تداخلًا."}]},{"t":"اضطرابات النظم والنقل","cards":[{"f":"الرجفان الأذيني: الصورة التخطيطية؟","b":"نظم غير منتظم تمامًا (Irregularly irregular)، غياب موجات P مع خط أساس متموج (f waves)، QRS ضيقة غالبًا — الأكثر شيوعًا بارتفاع الضغط والداء الصمامي التاجي."},{"f":"متى تُفضَّل استراتيجية ضبط النظم (Rhythm control) بالرجفان الأذيني؟","b":"للمرضى العرضيين رغم ضبط المعدل، الشباب، أول نوبة، قصور قلب بتسرع مُحدث (Tachycardia-mediated)، صعوبة ضبط المعدل — بالأدوية (أميودارون/فليكاينيد) أو التقويم الكهربائي أو الاستئصال."},{"f":"التقويم الكهربائي للرجفان الأذيني: شرط الأمان من الخثرة؟","b":"إن تجاوزت النوبة 48 ساعة: إما تمييع علاجي ≥3 أسابيع قبل التقويم + 4 أسابيع بعده، أو إيكو عبر المريء (TEE) لنفي خثرة الأذين الأيسر ثم التقويم مع التمييع."},{"f":"مكونات CHA2DS2-VASc لتقدير خطر السكتة بالرجفان الأذيني؟","b":"قصور قلب، ارتفاع ضغط، عمر ≥75 (نقطتان)، سكري، سكتة/خثرة سابقة (نقطتان)، داء وعائي، عمر 65-74، جنس أنثى. ≥2 للرجال/≥3 للنساء = تمييع فموي."},{"f":"الرفرفة الأذينية (Atrial flutter): الصورة التخطيطية والعلاج الحاد؟","b":"موجات F منشارية (Sawtooth) بمعدل ~300/دقيقة بتوصيل 2:1 غالبًا؛ العلاج الحاد: حاصرات العقدة AV (حاصر بيتا/فيراباميل) أو التقويم الكهربائي — الاستئصال بالقثطرة شافٍ للنمط المعتمد على البرزخ."},{"f":"علاج التسرع فوق البطيني الانتيابي (SVT) الحاد؟","b":"مناورات مبهمية أولًا (فالسالفا)، ثم أدينوزين وريدي (6 ثم 12 ملغ) — يشخص ويعالج التسرعات المعتمدة على العقدة AV."},{"f":"متلازمة WPW: العلامة التخطيطية والخطر الدوائي؟","b":"PR قصير + موجة دلتا (صعود متثلم لـQRS) + QRS عريض = حزمة كِنت الإضافية الظاهرة. بالرجفان الأذيني + WPW: ممنوع حاصرات العقدة AV (فيراباميل/ديجوكسين) — قد تسرّع التوصيل بالحزمة وتسبب رجفان بطيني؛ العلاج: بروكاييناميد أو تقويم كهربائي."},{"f":"حصار القلب من الدرجة الأولى والثانية (موبيتز I) مقابل موبيتز II والثالث؟","b":"الأول (PR>200ms) وموبيتز I (تطاول PR تدريجي ثم QRS ساقط — ظاهرة وينكباخ) غالبًا عقدي وحميد. موبيتز II (QRS ساقط فجائي بـPR ثابت) والثالث (انفصال أذيني بطيني تام) مرضيان تحت عقديين ويستلزمان ناظمة دائمة."},{"f":"استطبابات الناظمة الدائمة (Pacemaker)؟","b":"حصار أذيني بطيني تام أو موبيتز II عرضي، خلل العقدة الجيبية العرضي (متلازمة العقدة المريضة)، بطء قلبي عرضي غير قابل للعكس."},{"f":"التسرع البطيني مقابل فوق البطيني مع انحراف: كيف نفرق سريريًا؟","b":"انفصال أذيني بطيني (موجات P مستقلة)، قبضات اندماجية/التقاطية، QRS >140ms، محور متطرف — كلها لصالح بطيني؛ عند الشك يُعامَل كتسرع بطيني (أميودارون/تقويم)."},{"f":"تورساد دي بوان (Torsades): السبب والعلاج الإسعافي؟","b":"تسرع بطيني متعدد الأشكال مع QT متطاول (أدوية/نقص K أو Mg) — العلاج: كبريتات المغنزيوم وريدية 1-2غ، تصحيح الشوارد، إيقاف المسبب."},{"f":"التسمم بالديجوكسين: العلامات والترياق؟","b":"غثيان/قيء، اضطراب رؤية (هالات صفراء-خضراء)، اضطرابات نظم (تسرع أذيني مع حصار، بطء)، يُفاقَم بنقص K. الترياق: أضداد الديجوكسين Fab بالحالات المهددة."},{"f":"الأميودارون: الآثار الجانبية التي تُراقَب؟","b":"تليف رئوي، قصور/فرط درق (يحوي يود)، ترسبات قرنية، تلون جلد رمادي-أزرق، اعتلال كبد، اعتلال أعصاب — مراقبة دورية لوظائف الرئة والدرق والكبد."}]},{"t":"ارتفاع الضغط الرئوي","cards":[{"f":"تعريف ارتفاع الضغط الرئوي (PH) وارتفاع الضغط الشرياني الرئوي (PAH)؟","b":"PH: متوسط ضغط الشريان الرئوي mPAP >20 مم زئبق بالراحة. PAH (المجموعة 1): مع ضغط إسفيني رئوي طبيعي (≤15) ومقاومة وعائية رئوية مرتفعة."},{"f":"مجموعات WHO الخمس لارتفاع الضغط الرئوي؟","b":"1) شرياني PAH. 2) بسبب داء قلب أيسر. 3) بسبب داء رئوي/نقص أكسجة. 4) خثاري مزمن CTEPH. 5) غير واضح/متعدد العوامل."},{"f":"متلازمة أيزنمنغر (Eisenmenger): الآلية والعلامات؟","b":"تحويلة يسار-يمين خلقية غير مُصححة ← ارتفاع مقاومة رئوية ← انعكاس التحويلة يمين-يسار: زرقة مركزية، تعجر أصابع، كثرة حمر ثانوية — موانع: الحمل والجراحة التصحيحية المتأخرة."},{"f":"أدوية PAH: الأصناف الثلاثة الأساسية؟","b":"1) محرضات البروستاسيكلين (إيبوبروستينول). 2) مضادات الإندوثيلين (بوسنتان). 3) مثبطات PDE5 (سيلدينافيل) أو محرضات الغوانيلات (ريوسيغوات)."},{"f":"القلب الرئوي المزمن (Cor pulmonale): التعريف والسبب الأشيع؟","b":"تضخم/فشل البطين الأيمن ثانوي لارتفاع ضغط رئوي بسبب داء رئوي — أشيع سبب: COPD."},{"f":"الفحص السريري بارتفاع الضغط الرئوي الشديد؟","b":"P2 مرتفع (وأحيانًا مجسوس)، نفخة غراهام ستيل، علامات فشل أيمن: انتفاخ أوردة رقبة، وذمة، ضخامة كبد نابضة."},{"f":"الاستقصاء الذهبي لتشخيص PAH؟","b":"القسطرة القلبية اليمنى: قياس مباشر لـmPAP وضغط الإسفين والمقاومة الوعائية — الإيكو مسح أولي فقط."},{"f":"ارتفاع الضغط الرئوي الخثاري المزمن (CTEPH): العلاج الشافي؟","b":"استئصال بطانة الشريان الرئوي (Pulmonary endarterectomy) — الوحيد القابل للشفاء؛ وإلا: ريوسيغوات/علاج دوائي."},{"f":"لماذا يُمنع الحمل بارتفاع الضغط الشرياني الرئوي؟","b":"وفيات أمومية عالية جدًا (30-50%) بسبب عدم قدرة البطين الأيمن على تحمل زيادة الحجم القلبي — يُنصح بتجنب الحمل قطعًا."},{"f":"اختبار المشي 6 دقائق بارتفاع الضغط الرئوي: دلالته؟","b":"مسافة <300 متر تنذر بسوء الإنذار؛ يُستخدم لتقييم الشدة والاستجابة للعلاج."}]},{"t":"أمراض العضلة القلبية","cards":[{"f":"الأنماط الثلاثة لاعتلال العضلة القلبية؟","b":"متوسعة (DCM): توسع وضعف انقباض — أشيع. ضخامية (HCM): ضخامة لا متناظرة. مقيدة (RCM): خلل امتلاء انبساطي بجدران صلبة (نشواني/تليف)."},{"f":"اعتلال العضلة الضخامي الانسدادي (HOCM): صفات النفخة؟","b":"نفخة انقباضية قذفية بالحد القصي الأيسر تزداد بمناورة فالسالفا والوقوف (تقلل التحميل القبلي) وتخف بالقرفصاء ورفع الساقين — عكس معظم النفخات."},{"f":"علاج HOCM العرضي: الخط الأول والممنوعات؟","b":"الخط الأول: حاصرات بيتا (أو فيراباميل). ممنوع: النترات والمدرات وموسعات الأوعية (تفاقم انسداد المخرج) — الحالات الشديدة: استئصال حاجزي أو مزيل رجفان."},{"f":"متلازمة SAM باعتلال العضلة الضخامي؟","b":"حركة أمامية انقباضية للوريقة التاجية الأمامية (Systolic Anterior Motion) تسبب انسداد مخرج البطين الأيسر وقلس تاجي — أساس الفيزيولوجيا بـHOCM."},{"f":"التهاب العضلة القلبية الحاد: التظاهرات؟","b":"ألم صدري يحاكي الاحتشاء، اضطرابات نظم/حصار، قصور قلب حاد — بعد إنتان فيروسي غالبًا (كوكساكي)؛ التروبونين مرتفع بتاج طبيعي."},{"f":"اعتلال تاكوتسوبو (Takotsubo): ما يميزه؟","b":"اعتلال قلبي إجهادي عابر بشكل (انتفاخ قمي) بعد شدة عاطفية/جسدية — يحاكي STEMI لكن الشرايين سليمة؛ يتحسن خلال أسابيع."},{"f":"النشواني القلبي: الثالوث التشخيصي؟","b":"جدران بطينية ثخينة بالإيكو + فولطية منخفضة بالتخطيط + قصور قلب مع أعراض نفق رسغي/بيلة بروتينية — التشخيص: خزعة أو ومضان PYP."},{"f":"اعتلال العضلة المتوسعة: أشيع سبب؟","b":"مجهول السبب غالبًا؛ ثانويًا: إقفاري، كحولي، فيروسي/التهابي، أدوية (أنثراسيكلين)، حول الولادة."}]},{"t":"أمراض القلب الخلقية","cards":[{"f":"الفتحة بين البطينين (VSD): أشيع خلقية والنفخة؟","b":"أشيع آفة خلقية؛ نفخة انقباضية شاملة على الحد القصي الأيسر السفلي — الصغيرة قد تُغلق عفويًا، الكبيرة تسبب قصور قلب وفشل نمو بالرضع."},{"f":"الفتحة بين الأذينين (ASD): الصورة السريرية؟","b":"غالبًا لا عرضية بالطفولة؛ انقسام S2 ثابت لا يتغير بالتنفس + نفخة انقباضية قذفية رئوية — الإغلاق قبل ظهور ارتفاع ضغط رئوي."},{"f":"القناة الشريانية السالكة (PDA): العلامات؟","b":"نفخة مستمرة (آلية) تحت الترقوة اليسرى + نبض محيطي نابض (Bounding) — الخدج: إندوميتاسين/إيبوبروفين للإغلاق؛ البالغ: إغلاق بالقثطرة."},{"f":"رباعية فالو: المكونات الأربعة ونوبة الزرقة؟","b":"تضيق رئوي + VSD + تجاوز أبهر + ضخامة بطين أيمن. نوبة الزرقة (Tet spell): بكاء/جهد ← تفاقم انسداد المخرج ← زرقة شديدة؛ العلاج: وضعية القرفصاء/الركبة-صدر + أكسجين + مورفين."},{"f":"تضيق برزخ الأبهر (Coarctation): العلامات المميزة؟","b":"ارتفاع ضغط بالأطراف العلوية + ضعف/تأخر نبض الفخذ + فرق ضغط >20 مم زئبق بين العلوية والسفلية؛ صورة شعاعية: تآكل الأضلاع (Rib notching)."},{"f":"التبدل الكبير للشرايين (TGA): التظاهر والتدبير الإسعافي؟","b":"زرقة شديدة منذ الولادة بدائرتين متوازيتين؛ الإسعاف: بروستاغلاندين E1 لإبقاء القناة الشريانية مفتوحة ثم عملية التبديل الشرياني."},{"f":"شذوذ إبشتاين (Ebstein): ما يميزه؟","b":"انزياح سفلي للوريقة التاجية الثلاثية الشرف ← أذينة بطينية؛ يترافق مع WPW بنسبة 10-25% — صورة: قلب بشكل صندوق بالإشعاع."},{"f":"لماذا يُمنع إغلاق التحويلة بعد تطور أيزنمنغر؟","b":"لأن التحويلة يمين-يسار أصبحت صمام أمان للبطين الأيمن؛ إغلاقها يسبب فشل بطين أيمن حاد مميت."},{"f":"الوقاية من التهاب الشغاف بعد إصلاح خلقي بالقثطرة؟","b":"مضاد حيوي وقائي 6 أشهر بعد الإغلاق بجهاز حتى اكتمال التبطين، ثم لا لزوم إلا بوجود تسرب متبقٍّ."}]},{"t":"أمراض التامور","cards":[{"f":"التهاب التامور الحاد: الصورة السريرية والتخطيطية؟","b":"ألم صدري طاعن يزداد بالاستلقاء والشهيق ويخف بالانحناء للأمام + احتكاك تاموري. التخطيط: ارتفاع ST منتشر مقعر + انخفاض PR منتشر (عكس الاحتشاء الموضعي)."},{"f":"علاج التهاب التامور الحاد؟","b":"مضادات الالتهاب غير الستيروئيدية (أسبرين/إيبوبروفين) + كولشيسين 3 أشهر لمنع النكس؛ الستيروئيدات للحالات المعندة فقط."},{"f":"ثالوث بيك (Beck) بالدكاك القلبي؟","b":"انتفاخ أوردة الرقبة + أصوات قلب بعيدة/خافتة + انخفاض ضغط — مع نبض متناقض (Pulsus paradoxus) >10 مم زئبق."},{"f":"النبض المتناقض (Pulsus paradoxus): التعريف والآلية؟","b":"هبوط ضغط انقباضي >10 مم زئبق بالشهيق؛ بالدكاك: الشهيق يزيد عود البطين الأيمن فيزيح الحاجز لليسار فيقل نتاج الأيسر."},{"f":"علامات الدكاك بالإيكو والعلاج الإسعافي؟","b":"انهيار الأذين الأيمن انبساطيًا + تأرجح القلب (Swinging heart) بانصباب كبير. العلاج: بزل تاموري إسعافي موجه بالإيكو."},{"f":"التهاب التامور المضيق (Constrictive): العلامات المميزة؟","b":"علامة كوسماول (ارتفاع JVD بالشهيق)، قرعة تامورية (Pericardial knock) انبساطية مبكرة، تكلس تاموري شعاعيًا — العلاج: استئصال التامور."},{"f":"الفرق بين القرعة التامورية وصوت S3؟","b":"القرعة أعلى ترددًا وتُسمع بالحجاب وتحدث أبكر من S3 — تميز التامور المضيق عن قصور القلب."},{"f":"متلازمة دريسلر مقابل التهاب التامور بعد الاحتشاء المبكر؟","b":"المبكر (أيام): نضحي موضعي. دريسلر (أسابيع-شهور): مناعي ذاتي مع حمى وانصباب جنب — كلاهما يُعالج بمضادات الالتهاب."},{"f":"أسباب التهاب التامور: الأشيع؟","b":"فيروسية (كوكساكي) مجهولة السبب أشيع؛ ثم: احتشاء، يوريميا، سلّ، أورام، مناعية ذاتية (ذأب)، بعد جراحة قلب."},{"f":"انصباب التامور اليوريميائي: العلاج؟","b":"تكثيف الغسيل الكلوي (ديال) — يستجيب غالبًا دون بزل إلا عند الدكاك."}]},{"t":"المداواة القلبية","cards":[{"f":"النترات: آلية العمل والاستخدام والمحاذير؟","b":"موسعات وريدية (تخفض التحميل القبلي) وشريانية خفيفة؛ للخناق والاحتقان الحاد. ممنوعة مع مثبطات PDE5 (سيلدينافيل) لخطر هبوط شديد؛ تسبب صداعًا وتحملًا بالاستخدام المستمر."},{"f":"حاصرات بيتا القلبية: الاستطبابات والموانع؟","b":"خناق، احتشاء، قصور قلب (كارفيديلول/ميتوبرولول/بيسوبرولول)، اضطرابات نظم، ارتفاع ضغط. موانع: ربو شديد، حصار AV عالي، صدمة قلبية، بطء عرضي."},{"f":"الفرق بين حاصرات الكالسيوم ثنائية الهيدروبيريدين وغيرها؟","b":"ثنائية الهيدروبيريدين (أملوديبين): موسعة وعائية — لارتفاع الضغط والخناق. غير ثنائية (فيراباميل/ديلتيازيم): تبطئ العقدة AV — لاضطرابات النظم فوق البطينية؛ تجنبها بقصور القلب الانقباضي."},{"f":"الستاتينات: متى تُعطى بجرعة عالية الشدة؟","b":"بعد ACS، داء إكليلي مثبت، سكري 40-75 سنة بعوامل خطورة، LDL ≥190 — الهدف خفض LDL ≥50% (أتروفساتاتين 40-80/روزوفاستاتين 20-40)."},{"f":"مضادات الصفيحات: أسبرين مقابل كلوبيدوغريل؟","b":"الأسبرين (مثبط COX دائم) أساس الوقاية الثانوية؛ كلوبيدوغريل (مثبط P2Y12) بديل عند التحسس أو ضمن DAPT بعد الدعامات."},{"f":"الوارفارين: متى يُفضَّل على مضادات التخثر الفموية المباشرة؟","b":"صمام ميكانيكي، تضيق تاجي رثوي مع رجفان، متلازمة أضداد الفوسفوليبيد — يُراقَب بـINR (هدف 2-3 غالبًا، 2.5-3.5 للصمام الميكانيكي التاجي)."},{"f":"الإيبوبروفين/مضادات الالتهاب وقصور القلب: ما المشكلة؟","b":"تحبس الصوديوم والماء وتفاقم قصور القلب وترفع الضغط وتؤذي الكلية — تُتجنَّب بمرضى قصور القلب."},{"f":"الديجوكسين: متى يُراقَب مستواه؟","b":"عند الاشتباه بسمية (غثيان/اضطراب نظم/اضطراب رؤية)، قصور كلوي، تفاعلات دوائية (أميودارون/فيراباميل يرفعانه) — المجال العلاجي 0.5-2 نانوغرام/مل."}]},{"t":"جراحة الصدر والأوعية","cards":[{"f":"استطبابات جراحة المجازة الإكليلية (CABG) المفضلة على القثطرة؟","b":"تضيق الجذع الأيسر، داء ثلاثي الأوعية مع سكري، داء متعدد مع خلل بطين أيسر — الشريان الثديي الداخلي للـLAD هو المعيار الذهبي."},{"f":"تشريح الأبهر: تصنيف ستانفورد والعلاج؟","b":"A: يشمل الأبهر الصاعد — جراحة إسعافية. B: يبدأ بعد تحت الترقوة اليسرى — علاج دوائي (خفض ضغط ونبض: إسمولول + نتروبروسيد) إلا باختلاط."},{"f":"ألم تشريح الأبهر: صفاته المميزة؟","b":"ألم صدري/ظهري ممزق مفاجئ شديد منذ البداية (بلغ ذروته فورًا) قد ينتشر للظهر أو البطن — مع فرق ضغط/نبض بين الطرفين."},{"f":"أم الدم الأبهرية البطنية (AAA): عتبة التداخل والمسح؟","b":"التداخل عند ≥5.5 سم (رجال) أو نمو >0.5 سم/6 أشهر أو عرضية؛ المسح بالإيكو لمدخنين 65-75 سنة."},{"f":"استئصال باطنة السباتي (Carotid endarterectomy): متى؟","b":"تضيق سباتي عرضي 70-99% أو لا عرضي 70-80% عالي الخطورة — للوقاية من السكتة."},{"f":"الداء الشرياني المحيطي: العلامة السريرية والعلاج الأول؟","b":"عرج متقطع (ألم ربلة بالجهد يزول بالراحة) + نبض محيطي ضعيف؛ العلاج الأول: مشي مُشرَف + أسبرين + ستاتين + إقلاع تدخين."}]}]},{"s":"الصدرية (باطنة)","topics":[{"t":"أعراض الأمراض التنفسية","cards":[{"f":"نفث الدم (Hemoptysis): الأسباب الأشيع؟","b":"التهاب قصبات مزمن، توسع قصبات، سلّ، سرطان قصبي، صمّة رئوية، تضيق تاجي — الكمية الغزيرة (>600 مل/24 سا) مهددة للحياة (اختناق لا نزف)."},{"f":"تعجر الأصابع (Clubbing): أسباب صدرية؟","b":"توسع قصبات، تليف رئوي، سرطان قصبي، دبيلة، ورم المتوسطة — آليته: تحويلة دموية/عوامل نمو؛ يتراجع بعد علاج السبب أحيانًا."},{"f":"الصرير (Stridor) مقابل الأزيز (Wheeze): الفرق؟","b":"الصرير: صوت شهيقي عالي بانسداد مجرى علوي (حنجرة/رغامى). الأزيز: صوت زفيري موسيقي بانسداد قصبي سفلي (ربو/COPD) — قد يكون شهيقيًا بتضيق شديد."},{"f":"ألم الصدر الجنبي (Pleuritic): صفاته وأسبابه؟","b":"ألم طاعن حاد يزداد بالشهيق العميق والسعال؛ أسبابه: التهاب جنب، صمّة رئوية، ذات رئة، استرواح هواء."},{"f":"أنماط القشع الدالة تشخيصيًا؟","b":"صدئ (ذات رئة بالمكورات الرئوية)، هلام الكشمش (كليبسيلا)، قيحي غزير كريه (توسع قصبات/خراج)، وردي رغوي (وذمة رئة)، مخاطي لزج (ربو)."},{"f":"الزرقة المركزية مقابل المحيطية؟","b":"مركزية: نقص أكسجة شرياني (رئوي/قلبي) — تشمل الشفاه واللسان ولا تتحسن بالتدفئة. محيطية: ركودة محيطية (برد/قصور قلب) — بالأطراف فقط وتتحسن بالتدفئة."},{"f":"ضيق النفس الاضطجاعي بوجهة صدرية: ما أسبابه غير القلبية؟","b":"شلل حجاب أحادي، بدانة مفرطة، استسقاء ضاغط، داء رئوي خلالي متقدم — لكن الأشيع قلبي."},{"f":"السعال المزمن (>8 أسابيع): الأسباب الثلاثة الأشيع؟","b":"تنقيط أنفي خلفي، ربو/سعال متغير، قلس معدي مريئي — ثم: مثبطات ACE، التهاب قصبات مزمن، توسع قصبات."},{"f":"بصاق الدم الكاذب: ما الذي يُنفى أولًا؟","b":"نزف أنفي/لثوي/معدي (قيء دموي) — نفث الدم الحقيقي: دم أحمر رغوي مع سعال."},{"f":"تسرع التنفس (Tachypnea) الحاد: أول ما يُفكَّر به؟","b":"صمّة رئوية، وذمة رئة حادة، استرواح، حماض استقلابي، قلق — مع تقييم الأكسجة فورًا."}]},{"t":"الأمراض الرئوية الانسدادية","cards":[{"f":"تشخيص COPD وظيفيًا: المعيار الذهبي؟","b":"FEV1/FVC < 0.7 بعد موسع قصبي مع أعراض/تعرض (تدخين) — الانسداد غير عكوس كليًا."},{"f":"تصنيف GOLD الجديد ABE: ما هو؟","b":"A: أعراض قليلة + هجمات 0-1 خفيفة. B: أعراض كثيرة + هجمات 0-1. E: هجمات ≥2 متوسطة أو ≥1 شديدة (استشفاء) بغض النظر عن الأعراض — دُمجت C وD بـE منذ 2023."},{"f":"العلاج الأولي لـCOPD حسب المجموعة؟","b":"A: موسع واحد (LAMA أو LABA). B: ثنائي LAMA+LABA. E: ثنائي LAMA+LABA، ويُضاف ICS (ثلاثي) إذا حمضات ≥300."},{"f":"متى يُعطى الأكسجين المديد (LTOT) بـCOPD؟","b":"PaO2 ≤55 مم زئبق أو SpO2 ≤88% بالراحة، أو 56-59 مع احتقان/كثرة حمر/قلب رئوي — ≥15 ساعة/يوميًا ويُحسّن البقيا."},{"f":"علاج هجمة COPD الحادة؟","b":"موسعات قصبية قصيرة المفعول + ستيروئيد جهازي (بردنيزولون 40 ملغ 5 أيام) + مضاد حيوي عند تغير القشع (قيحي) أو الحاجة لتهوية — أكسجين مضبوط بهدف SpO2 88-92%."},{"f":"أقوى منبئ بهجمات COPD المستقبلية؟","b":"عدد الهجمات بالسنة السابقة — حتى هجمة واحدة ترفع الخطر، و≥2 ترفعه أكثر."},{"f":"تشخيص الربو: الاختبار الوظيفي المميز؟","b":"عكوسية الانسداد: تحسن FEV1 ≥12% و≥200 مل بعد موسع قصبي، أو تقلبية ذروة الجريان اليومية ≥10% — مع أعراض متغيرة (أزيز/سعال ليلي)."},{"f":"نظام MART بالربو: ما هو ولماذا يُفضَّل؟","b":"علاج صيانة وإنقاذ واحد: فورموتيرول+ICS (التركيبة الوحيدة الصالحة) — يقلل الهجمات مقارنة بالصيانة + SABA، ونظام أبسط (المسار 1 بـGINA)."},{"f":"الربو الحاد الشديد: العلاج الإسعافي؟","b":"أكسجين + سالبوتامول إرذاذ متكرر + إبراتروبيوم + ستيروئيد جهازي مبكر (هيدروكورتيزون/بردنيزولون) + كبريتات المغنزيوم وريديًا بالشديد — لا مهدئات."},{"f":"علامات الخطر بالربو الحاد (تستدعي عناية مركزة)؟","b":"صمت صدري، زرقة، اضطراب وعي، PEF <33%، PaCO2 طبيعي/مرتفع (تعب)، نبض >120، تنفس >30."},{"f":"توسع القصبات (Bronchiectasis): العلامات المميزة؟","b":"سعال مزمن بقشع قيحي غزير + تعجر + هجمات متكررة؛ التشخيص: طبقي عالي الدقة (علامة خاتم الختم Signet ring) — العلاج: تصريف وضعي + مضادات عند الهجمات."},{"f":"التهاب القصبات المزمن مقابل النفاخ: الفرق السريري؟","b":"التهاب قصبات: سعال منتج ≥3 أشهر/سنتين متتاليتين (مزرق منتفخ Blue bloater). نفاخ: ضيق جهد مع صدر برميلي (زهري ملهث Pink puffer) — كلاهما COPD."},{"f":"عوز ألفا-1 أنتي تربسين: متى يُشتبه به؟","b":"COPD بعمر <45 أو غير مدخن أو عائلي، نفاخ بالفصوص السفلية، داء كبدي — التشخيص: مستوى المصل ثم نمط جيني."},{"f":"اللقاحات الموصى بها لمرضى COPD؟","b":"إنفلونزا سنويًا + رئويات (مكورات) + كوفيد — تقلل الهجمات والاستشفاء."},{"f":"إعادة التأهيل الرئوي: لمن وفائدته؟","b":"لمرضى COPD العرضيين (B وE) — يحسن ضيق النفس والتحمل ونوعية الحياة ويقلل الاستشفاء."}]},{"t":"الأمراض الرئوية الخلالية","cards":[{"f":"التليف الرئوي مجهول السبب (IPF): الصورة الشعاعية والعلاج؟","b":"نمط UIP: تليف قاعدي محيطي مع تعسيل (Honeycombing) بالطبقي عالي الدقة؛ العلاج المضاد للتليف: بيرفنيدون أو نينتيدانيب (يبطئان التدهور) — لا ستيروئيد."},{"f":"الساركوئيد: العلامة الشعاعية الكلاسيكية؟","b":"ضخامة عقد لمفية سرية ثنائية الجانب متناظرة (Bilateral hilar adenopathy) — مع حمامى عقدة (Löfgren: حمامى + التهاب مفاصل + حمى = إنذار جيد)."},{"f":"تشخيص الساركوئيد: الفحوص الداعمة؟","b":"ارتفاع ACE (غير نوعي)، خزعة تظهر حبيبومات غير متجبنة، فرط كالسيوم/كالسيوريا — العلاج: ستيروئيد للحالات العرضية/المتقدمة."},{"f":"التهاب الرئة بفرط التحسس (Hypersensitivity pneumonitis): السبب والعلاج؟","b":"استنشاق مستضدات عضوية (طيور، عفن، قش) — سعال وضيق وحمى بعد ساعات من التعرض؛ العلاج: تجنب المستضد + ستيروئيد بالحاد."},{"f":"السحار السيليسي: العلامة الشعاعية المميزة؟","b":"عقد صغيرة علوية + تكلس قشرة البيضة للعقد السريّة (Eggshell calcification) — يرفع خطر السلّ."},{"f":"داء الأسبست: العلامات الجنبية؟","b":"لويحات جنبية متكلسة + تليف سفلي — الاختلاط الأخطر: ورم المتوسطة الخبيث (خبيث، كمون 20-40 سنة)."},{"f":"الأدوية المسببة لداء رئوي خلالي (أمثلة)؟","b":"أميودارون، نيتروفورانتوين، ميثوتركسات، بليوميسين — صورة: سعال جاف وضيق + ارتشاحات خلالية."},{"f":"التهاب الرئة الخلالي الحاد (AIP/Hamman-Rich): ما يميزه؟","b":"فشل تنفسي حاد مجهول السبب بنمط DAD — إنذار سيئ ووفيات عالية رغم الستيروئيد."},{"f":"الفحص السريري بالداء الخلالي: العلامتان؟","b":"خراخر شهيقية ناعمة قاعدية (Velcro crackles) + تعجر أصابع."},{"f":"اختبارات الوظيفة بالداء الخلالي: النمط؟","b":"نمط مقيِّد: انخفاض TLC وFVC مع FEV1/FVC طبيعي أو مرتفع + انخفاض قدرة الانتشار DLCO."}]},{"t":"أخماج الجهاز التنفسي","cards":[{"f":"ذات الرئة المكتسبة مجتمعيًا: أشيع مسبب؟","b":"المكورات الرئوية (S. pneumoniae) — قشع صدئ، اندفاع فصي."},{"f":"مكونات CURB-65؟","b":"تخليط (Confusion)، يوريا >7، تنفس ≥30، ضغط منخفض (انقباضي <90 أو انبساطي ≤60)، عمر ≥65 — كل واحدة نقطة: 0-1 خارجي، 2 استشفاء، ≥3 عناية."},{"f":"ذات الرئة اللانمطية: المسببات والعلامات؟","b":"مفطورة (Mycoplasma: راصّات باردة، ذات رئة جوّالة)، فيلقيات (Legionella: نقص صوديوم، إسهال، من مكيفات)، متدثرات — ارتشاحات خلالية، تستجيب للماكروليد."},{"f":"ذات رئة كليبسيلا: ما يميزها؟","b":"قشع هلام الكشمش (Currant-jelly)، فص علوي، مدمنو كحول — نخرية تميل للخراج."},{"f":"ذات الرئة الاستنشاقية: المسبب والعلاج؟","b":"لاهوائيات فموية (اضطراب بلع/وعي) — فص علوي أيمن أو سفلي؛ العلاج: أموكسيسيلين-كلافولانات أو كليندامايسين."},{"f":"خراج الرئة: الصورة والعلاج؟","b":"حمى + قشع قيحي كريه + مستوى سائل-هواء شعاعيًا؛ العلاج: مضاد لاهوائيات مطول (كليندامايسين) — الجراحة نادرًا."},{"f":"ذات الرئة بالمتكيس الرئوي (PCP): متى وأين؟","b":"CD4 <200 بالإيدز؛ صورة: ضيق متدرج + زجاج مصنفر ثنائي + LDH مرتفع + نقص أكسجة جهدي؛ العلاج/الوقاية: تريميثوبريم-سلفاميثوكسازول."},{"f":"السلّ الرئوي الأولي: العلامات؟","b":"عقدة غون + ضخامة عقد سرية = معقد غون (Ghon complex)؛ قد يتكلس (عقدة رانكه) — غالبًا لا عرضي عند المناعيين."},{"f":"السلّ الدخني: الصورة؟","b":"انتشار دموي بعوز مناعي: عقد دخنية منتشرة + حمى + تعرق ليلي + إصابة أعضاء (سحايا/كبد) — إسعاف علاجي."},{"f":"علاج السلّ الحساس: النظام والمدة؟","b":"RIPE: ريفامبيسين+إيزونيازيد+بيرازيناميد+إيثامبوتول شهرين ثم ريفامبيسين+إيزونيازيد 4 أشهر (مجموع 6) — مع بيريدوكسين للوقاية من التهاب أعصاب الإيزونيازيد."},{"f":"الدبيلة (Empyema): التشخيص والعلاج؟","b":"قيح بالجنب: pH <7.2 + غلوكوز منخفض + LDH مرتفع؛ العلاج: تصريف أنبوبي + مضادات — التأخر يستلزم تنظير/جراحة."},{"f":"ذات الرئة المكتسبة من المشفى: المسببات والعلاج التجريبي؟","b":"عصيات سلبية الغرام (زائفة، كليبسيلا) + MRSA؛ العلاج: بيتالاكتام واسع (بيبراسيلين-تازوباكتام/ميروبينيم) ± فانكوميسين."},{"f":"التهاب القصيبات بالرضع: المسبب والعلاج؟","b":"فيروس RSV شتاءً؛ العلاج داعم (أكسجين/سوائل) — لا مضاد ولا ستيروئيد روتينيًا."},{"f":"الإنفلونزا: العلاج النوعي ومتى؟","b":"أوسيلتاميفير خلال 48 ساعة من البدء (أو لاحقًا للمرضى عالي الخطورة/المستشفين) — اللقاح سنوي."}]},{"t":"أمراض الأوعية الرئوية","cards":[{"f":"الصمّة الرئوية: الأعراض الأشيع؟","b":"ضيق نفس مفاجئ + ألم جنبي + تسرع قلب/تنفس — قد تكون صامتة؛ الضخمة: صدمة/توقف."},{"f":"اختبار D-dimer: متى يُستخدم؟","b":"لنفي الصمّة باحتمال سريري منخفض/متوسط (Wells) فقط — حساس عالٍ ونوعية منخفضة (يرتفع بالحمل/الالتهاب/الورم)."},{"f":"الاستقصاء المؤكد للصمّة الرئوية؟","b":"الطبقي الوعائي (CTPA) — يرى الخثرة مباشرة؛ البديل: ومضان تهوية-تروية عند موانع الطبقي."},{"f":"علاج الصمّة الرئوية غير الضخمة؟","b":"تمييع: هيبارين ثم وارفارين أو DOAC (ريفاروكسابان/أبيكسابان) 3 أشهر على الأقل — الضخمة غير المستقرة: حالّ خثرة."},{"f":"علامات التخطيط بالصمّة الرئوية الضخمة؟","b":"S1Q3T3 (غير نوعي)، حصار غصن أيمن جديد، انقلاب T بـV1-V4، تسرع جيبي — تدل على إجهاد أيمن حاد."},{"f":"التهاب الأوعية الحبيبي (GPA/فيغنر): الثالوث؟","b":"جيوب/أنف (سرج الأنف) + رئة (عقد متنخرة) + كلية (كبيبات) — c-ANCA موجب؛ العلاج: ستيروئيد + سيكلوفوسفاميد/ريتوكسيماب."},{"f":"متلازمة غودباستشر: ما يميزها؟","b":"نزف سنخي (نفث دم) + التهاب كبيبات سريع + أضداد الغشاء القاعدي anti-GBM — العلاج: فصادة بلازما + مثبطات مناعة."},{"f":"التهاب الأوعية المرافق للربو والحمضات؟","b":"شيرغ-ستراوس (EGPA): ربو متأخر + حمضات + التهاب أعصاب وحيد متعدد — p-ANCA قد يكون موجبًا."},{"f":"ارتفاع الضغط الرئوي الخثاري المزمن: التشخيص؟","b":"ومضان تروية يظهر عيوبًا إسفينية + قثطرة يمنى — العلاج الشافي: استئصال بطانة الشريان الرئوي."},{"f":"الوقاية من الخثار الوريدي بالمستشفى؟","b":"هيبارين منخفض الجرعة/إينوكسابارين + تحريك مبكر + جوارب ضاغطة — للمرضى عالي الخطورة."}]},{"t":"أمراض الجنب","cards":[{"f":"معايير لايت (Light) للانصباب النضحي؟","b":"نضحي إذا تحقق واحد: بروتين جنب/مصل >0.5، LDH جنب/مصل >0.6، LDH جنب > ثلثي الحد الأعلى المصلي — وإلا رشحي."},{"f":"أسباب الانصباب الرشحي (Transudate) الأشيع؟","b":"قصور قلب (الأشيع)، تشمع كبدي، متلازمة نفروزية، انصمام رئوي (15% رشحي) — بروتين جنب <30 غ/ل."},{"f":"أسباب الانصباب النضحي الأشيع؟","b":"ذات رئة/دبيلة، سلّ، ورم خبيث، انصمام رئوي (>80% نضحي)، التهاب بنكرياس."},{"f":"انصباب جنب سلّي: صفات السائل؟","b":"نضحي لمفاوي مع غلوكوز منخفض وADA مرتفع — التشخيص: خزعة جنب (حبيبومات)."},{"f":"الاسترواح الصدري الضاغط (Tension): العلامات؟","b":"ضيق شديد + انحراف رغامى للجهة المقابلة + أوردة رقبة منتفخة + غياب أصوات تنفسية + انخفاض ضغط — إسعاف: إبرة بالحيز الثاني ثم أنبوب."},{"f":"علاج الاسترواح العفوي الأولي الصغير؟","b":"مراقبة + أكسجين (يسرّع الامتصاص) إذا <2 سم ولا أعراض؛ الأكبر أو العرضي: شفط/أنبوب صدري."},{"f":"الفحص السريري للانصباب الجنبي؟","b":"حركة صدر ناقصة + قرع أصم + غياب/نقص أصوات تنفسية + احتكاك جنبي قد يُسمع بالتهاب."},{"f":"متى يُبزل الانصباب الجنبي تشخيصيًا؟","b":"كل انصباب جديد غير واضح السبب (غير قصور قلب واضح مستجيب) — بروتين/LDH/غلوكوز/pH/خلايا/زرع."},{"f":"تسمك الجنب الليفي (Fibrothorax): متى؟","b":"بعد دبيلة/انصباب مدمّى مهمل — يقيّد التوسع؛ العلاج: تقشير جنب جراحي."},{"f":"ورم المتوسطة: الارتباط والإنذار؟","b":"مرتبط بالأسبست بكمون 20-40 سنة؛ انصباب نضحي مدمّى متكرر — إنذار سيئ."}]},{"t":"أورام الرئة والقصبات","cards":[{"f":"سرطان الرئة صغير الخلايا مقابل غير صغير: الفرق العلاجي؟","b":"صغير الخلايا: سريع الانتشار، حساس للكيماوي/شعاعي — جراحة نادرًا. غير صغير (غدي/حرشفي/كبير): الجراحة شافية بالمبكر."},{"f":"ورم بانكوست (Pancoast): الموقع والعلامات؟","b":"قمة الرئة: ألم كتف/ذراع + متلازمة هورنر (تدلي جفن/تقبض حدقة/لا تعرق) + ضمور عضلات اليد — غالبًا حرشفي."},{"f":"متلازمة الوريد الأجوف العلوي: العلامات؟","b":"تورم وجه ورقبة وأطراف علوية + أوردة صدر متوسعة + ضيق — إسعاف: ستيروئيد + شعاعي/دعامة."},{"f":"متلازمات نظيرة الورم بسرطان الرئة (أمثلة)؟","b":"صغير الخلايا: SIADH (نقص صوديوم) وACTH (كوشينغ). حرشفي: فرط كالسيوم (PTHrP). أي نوع: لامبرت-إيتون (وهن عضلي يتحسن بالتكرار)."},{"f":"العقدة الرئوية المنفردة: متى تُراقَب ومتى تُستأصل؟","b":"<6 مم منخفض الخطورة: مراقبة طبقية. >8 مم أو نمو/حواف شوكية: PET ثم خزعة/استئصال."},{"f":"السرطان الغدي الرئوي: الصفات؟","b":"أشيع نمط (40%)، محيطي، يصيب غير المدخنين والنساء — قد يعبر عن EGFR/ALK (علاج موجه)."},{"f":"السرطان الحرشفي: الصفات؟","b":"مركزي، مدخنون بشراهة، يتمركز ويتجوف — فرط كالسيوم نظير ورمي شائع."},{"f":"الورم السرطاوي القصبي (Carcinoid): ما يميزه؟","b":"بطيء، يفرز سيروتونين: متلازمة سرطاوية (توهج/إسهال/تشنج قصبي) — الأوكتريوتيد للعلاج العرضي."},{"f":"المسح بسرطان الرئة: لمن؟","b":"طبقي منخفض الجرعة سنويًا لمدخنين 50-80 سنة ≥20 علبة-سنة (حاليين أو أقلعوا <15 سنة)."},{"f":"انتقالات الرئة الأشيع مصدرًا؟","b":"ثدي، قولون، كلية، رأس/رقبة، ورم ميلانيني — عقد متعددة محيطية (قذائف مدفعية)."},{"f":"انصباب جنب خبيث: التشخيص؟","b":"سائل نضحي مدمّى مع خلايا خبيثة بالفحص الخلوي — التثبيت الجنبي (Pleurodesis) للتخفيف."},{"f":"ألم العظام وفرط الكالسيوم بسرطان رئة: التفسير؟","b":"انتقالات عظمية حالة للعظم + PTHrP نظير ورمي — العلاج: سوائل + بيسفوسفونات + علاج الورم."}]}]},{"s":"الخمجية","topics":[{"t":"الحمى المالطية (البروسيلا)","cards":[{"f":"الحمى المالطية: العامل وطريق العدوى؟","b":"جراثيم البروسيلا (Brucella spp.) — حيواني المصدر: حليب/ألبان غير مبسترة أو تماس مباشر مع حيوانات مصابة (أبقار/ماعز) — تسمى أيضًا الحمى المتموجة والحمى المتوسطية."},{"f":"التظاهر السريري الكلاسيكي للبروسيلا؟","b":"حمى متموجة (Undulant) مسائية + تعرق ليلي + ألم مفصلي/عضلي + وهن — قد تصبح مزمنة بانتكاسات."},{"f":"الاختلاط المفصلي الأشيع بالبروسيلا؟","b":"التهاب المفصل العجزي الحرقفي (Sacroiliitis) أحادي الجانب — ثم التهاب فقار."},{"f":"تشخيص البروسيلا مخبريًا؟","b":"زرع الدم (بطيء النمو — يُحضن مطولًا) + تفاعل رايت/تثبيت المتممة (أضداد) — ارتفاع الوحيدات شائع."},{"f":"علاج البروسيلا؟","b":"دوكسيسيكلين + ريفامبيسين 6 أسابيع (أو دوكسيسيكلين + ستربتوميسين/جنتاميسين) — العلاج الأحادي ينتكس."},{"f":"اختلاطات البروسيلا الخطيرة؟","b":"التهاب شغاف (أخطرها)، التهاب سحايا، التهاب خصية/بربخ، التهاب كبد حبيبي."},{"f":"الوقاية من البروسيلا؟","b":"بسترة الحليب + وقاية العاملين مع الحيوانات (قفازات/كمامات) + تلقيح القطعان — لا لقاح بشري."},{"f":"لماذا تُسمى الحمى المتموجة؟","b":"نمط حموي يرتفع وينخفض بأمواج على أسابيع — مميز للبروسيلا غير المعالجة."},{"f":"البروسيلا والحمل؟","b":"قد تسبب إسقاطًا — تُتجنَّب الدوكسيسيكلين والريفامبيسين بحذر؛ العلاج: تريميثوبريم-سلفاميثوكسازول + ريفامبيسين باستشارة."},{"f":"الفرق بين البروسيلا الحادة والمزمنة؟","b":"الحادة: حمى وتعرق. المزمنة (>سنة): وهن واكتئاب وآلام مبهمة بلا حمى واضحة — صعبة التشخيص."}]},{"t":"الحمى التيفية (السالمونيلا التيفية)","cards":[{"f":"الحمى التيفية: العامل وطريق العدوى؟","b":"السالمونيلا التيفية (S. Typhi) — برازي-فموي: ماء/طعام ملوث؛ الإنسان المستودع الوحيد."},{"f":"التظاهر السريري الكلاسيكي للتيفوئيد؟","b":"حمى متدرجة سُلَّمية + بطء قلب نسبي (Faget) + بقع وردية جذعية (Rose spots) + ضخامة طحال + إمساك (أو إسهال بالأطفال)."},{"f":"علامة فاجيه (Faget): ما هي؟","b":"بطء قلب نسبي رغم الحمى (النبض لا يرتفع 10/درجة) — تُرى بالتيفوئيد والحمى الصفراء والبروسيلا."},{"f":"تشخيص التيفوئيد: الاستقصاء الأفضل حسب الأسبوع؟","b":"الأسبوع الأول: زرع الدم (الأعلى حساسية). لاحقًا: زرع نخاع العظم (يبقى إيجابيًا رغم المضاد) — فيدال قديم وغير نوعي."},{"f":"علاج الحمى التيفية؟","b":"سيفترياكسون أو أزيثروميسين (للمقاومة) أو فلوروكينولون بالحساسة — 10-14 يومًا."},{"f":"اختلاطات التيفوئيد الخطيرة ومتى؟","b":"الأسبوع 3-4: انثقاب معي/نزف معوي، التهاب سحايا، التهاب رئة — تستدعي جراحة/عناية."},{"f":"حامل التيفوئيد المزمن: أين تستوطن الجراثيم؟","b":"المرارة (حصيات) — تُعالج باستئصال مرارة + مضاد مطول."},{"f":"الوقاية من التيفوئيد؟","b":"لقاح (فموي حي Ty21a أو حقني Vi) للمسافرين + نظافة ماء/غذاء."},{"f":"الفرق بين التيفية ونظيرة التيفية؟","b":"نظيرة التيفية (Paratyphi A/B) أخف وأقل اختلاطات — نفس العلاج والوقاية."}]},{"t":"الأخماج الهضمية والإسهالات والتسمم الغذائي","cards":[{"f":"الكوليرا: العامل والتظاهر والعلاج؟","b":"ضمة الكوليرا (ذيفان يرفع cAMP) — إسهال مائي غزير كمياه الأرز + جفاف سريع؛ العلاج الأساس: إماهة فموية ORS — دوكسيسيكلين يقصر المدة."},{"f":"الشيغيلا: ما يميزها؟","b":"زحار: إسهال مدمّى مخاطي + زحير + حمى — جرعة ممرضة ضئيلة (10-100)؛ العلاج: سيبروفلوكساسين/أزيثروميسين بالشديد."},{"f":"العطيفة (Campylobacter): الاختلاط المناعي؟","b":"أشيع سبب جرثومي للإسهال (دواجن) — قد يعقبها متلازمة غيّان-باريه (شلل صاعد)."},{"f":"الإشريكية القولونية O157:H7: الخطر العلاجي؟","b":"تسبب إسهالًا مدمّى ومتلازمة انحلال الدم اليوريمية HUS — ممنوع المضادات ومضادات الحركة (ترفع خطر HUS)."},{"f":"المطثية العسيرة (C. difficile): العلامات والعلاج؟","b":"إسهال بعد مضادات (كليندامايسين/فلوروكينولون) + أغشية كاذبة بالتنظير + ذيفان بالبراز؛ العلاج: فيداكسوميسين أو فانكوميسين فموي — ميترونيدازول لم يعد أولًا."},{"f":"السالمونيلا غير التيفية: متى يُعطى مضاد؟","b":"غالبًا محدودة ذاتيًا — مضاد فقط للشديد/المجرثم/عوز المناعة (سيبروفلوكساسين/أزيثروميسين)."},{"f":"الجيارديا: التظاهر والعلاج؟","b":"إسهال دهني مزمن + انتفاخ بعد ماء ملوث؛ التشخيص: أكياس/أتروفة بالبراز أو مستضد؛ العلاج: ميترونيدازول."},{"f":"المتحول الحالّ للنسج: العلامتان المميزتان؟","b":"قرحات بشكل قارورة بالقولون + خراج كبدي (قيح كمعجون الأنشوفة) — العلاج: ميترونيدازول ثم باروموميسين."},{"f":"التسمم الوشيقي الغذائي: الآلية والعلاج؟","b":"ذيفان المطثية الوشيقية (معلبات) يمنع تحرر الأستيل كولين ← شلل رخو هابط + توسع حدقة؛ العلاج: مضاد ذيفان + دعم تنفسي."},{"f":"التسمم بالمكورات العنقودية الغذائي: ما يميزه؟","b":"ذيفان مسبق التكون (أطعمة ملوثة) — قيء عنيف خلال 1-6 ساعات؛ محدود ذاتيًا."},{"f":"نوروفيروس: صفاته؟","b":"أشيع سبب التهاب معدة-أمعاء فيروسي بالبالغين (سفن/مشافٍ) — شديد العدوى، محدود ذاتيًا، العلاج داعم."}]},{"t":"الأخماج الفيروسية التنفسية (الإنفلونزا)","cards":[{"f":"الإنفلونزا A مقابل B: الفرق الوبائي؟","b":"A: تسبب جوائح (تحول مستضدي Shift) وطيور/خنازير مستودع. B: بشرية فقط، انحراف Drift — كلاهما موسمي شتاءً."},{"f":"علاج الإنفلونزا النوعي: متى؟","b":"أوسيلتاميفير خلال 48 ساعة من البدء؛ لاحقًا للمستشفين/عالي الخطورة — لا فائدة بعد 5 أيام غالبًا."},{"f":"اختلاطات الإنفلونزا الخطيرة؟","b":"ذات رئة فيروسية أولية + ذات رئة جرثومية ثانوية (مكورات/عنقوديات) + التهاب عضلة قلب."},{"f":"لقاح الإنفلونزا: لمن؟","b":"سنويًا: >65 سنة، حوامل، أمراض مزمنة، عاملون صحيون — معطّل وآمن بالحمل."},{"f":"كوفيد-19: العلاج النوعي؟","b":"نيرماتريلفير/ريتونافير (باكسلوفيد) خلال 5 أيام لعالي الخطورة؛ ريمديسيفير/ستيروئيد للمستشفين المحتاجين أكسجين."},{"f":"RSV عند البالغين: أهميته؟","b":"يسبب هجمات تنفسية شديدة بالمسنين/المناعيين — لقاح متوفر >60 سنة."}]},{"t":"الحصبة والنكاف","cards":[{"f":"الحصبة: العلامة البادرية المميزة؟","b":"بقع كوبليك (بيضاء على مخاطية الخد) قبل الطفح + سعال/زكام/التهاب ملتحمة (3Cs) — طفح بقعي حطاطي يبدأ خلف الأذن."},{"f":"اختلاطات الحصبة؟","b":"التهاب أذن/رئة، التهاب دماغ حاد، والتهاب دماغ شامل مصلب تحت حاد SSPE بعد سنوات — فيتامين A يخفف الشدة."},{"f":"النكاف: التظاهر والاختلاط الأشيع؟","b":"التهاب غدة نكفية مؤلم ثنائي؛ الاختلاط: التهاب خصية (عقم نادر)، التهاب سحايا/بنكرياس."},{"f":"لقاح MMR: مكوناته وموانعه؟","b":"حصبة/نكاف/حصبة ألمانية — حي مضعف: ممنوع بالحمل وعوز المناعة الشديد."},{"f":"الحصبة الألمانية الخلقية: الثالوث؟","b":"سادّ + صمم حسي عصبي + داء قلبي (قناة شريانية/تضيق رئوي) — إصابة الأم بالثلث الأول."},{"f":"علاج الحصبة؟","b":"داعم + فيتامين A للأطفال — لا مضاد فيروسي نوعي؛ العزل التنفسي."},{"f":"التهاب الدماغ بالحصبة: متى؟","b":"1/1000 خلال أيام من الطفح — صداع/اختلاج/سبات."}]},{"t":"فيروسات الحلأ (الحماق، داء المنطقة، الحلأ البسيط، المضخم للخلايا، وحيدات النوى)","cards":[{"f":"داء المنطقة (Herpes zoster): التظاهر والعلاج؟","b":"طفح حويصلي مؤلم جلدي (Dermatomal) بعد إعادة تنشيط VZV — العلاج: أسيكلوفير/فالاسيكلوفير خلال 72 ساعة؛ الألم العصبي التالٍ يُعالج بمسكنات أعصاب."},{"f":"متلازمة رامزي-هانت؟","b":"داء منطقة أذني: شلل وجهي + حويصلات بالأذن + دوار — ستيروئيد + مضاد فيروسي."},{"f":"الحلأ البسيط التناسلي: العلاج والقمع؟","b":"أسيكلوفير/فالاسيكلوفير للنوبة؛ قمع يومي للناكس المتكرر (≥6/سنة) — الولادة القيصرية عند آفات نشطة."},{"f":"التهاب الدماغ بالحلأ البسيط: العلامات والعلاج؟","b":"حمى + تغير سلوك/اختلاج + آفة فص صدغي بالرنين؛ العلاج: أسيكلوفير وريدي إسعافي قبل التأكيد."},{"f":"داء وحيدات النوى (EBV): الثالوث والعلامة المخبرية؟","b":"حمى + التهاب بلعوم + ضخامة عقد/طحال؛ لمفاويات شاذة + أضداد غيرية (Monospot) — الأمبيسيلين يسبب طفحًا."},{"f":"تحذير الطحال بداء وحيدات النوى؟","b":"تجنب الرياضات العنيفة 4-6 أسابيع لخطر تمزق الطحال."},{"f":"الفيروس المضخم للخلايا (CMV): متى يمرض؟","b":"بالمناعيين (زرع/إيدز): التهاب شبكية/قولون/رئة؛ خلقيًا: صمم وتخلف — التشخيص: خلايا عين البومة؛ العلاج: غانسيكلوفير."},{"f":"الحماق عند الحامل/الوليد: الخطر؟","b":"إصابة الأم قبل الولادة بـ5 أيام-بعدها بيومين: حماق ولادي شديد — غلوبولين مناعي VZIG للمخالطين عالي الخطورة."},{"f":"لقاح داء المنطقة؟","b":"لقاح مؤتلف (شينغريكس) >50 سنة — يقي من الداء والألم التالي."}]},{"t":"الإيدز وفيروس عوز المناعة البشري","cards":[{"f":"تشخيص HIV: الاختبار الأول؟","b":"اختبار الجيل الرابع (مستضد p24 + أضداد) — التأكيد: تمييز الأضداد/RNA."},{"f":"عتبات CD4 والعدوى الانتهازية؟","b":"<200: متكيس رئوي PCP. <100: مقوسات دماغية. <50: معقد المتفطرات الطيرية MAC والفيروس المضخم."},{"f":"العلاج المضاد للفيروس (ART): متى يبدأ؟","b":"فور التشخيص بغض النظر عن CD4 — ثلاثي (مثبط إنتيغراز + 2 NRTI)؛ الهدف: حمولة غير مقروءة = غير معدٍ."},{"f":"الوقاية قبل التعرض (PrEP) وبعده (PEP)؟","b":"PrEP: تينوفوفير/إمتريسيتابين يوميًا لعالي الخطورة. PEP: ثلاثي خلال 72 ساعة (أبكر أفضل) لـ28 يومًا."},{"f":"المقوسات الدماغية بالإيدز: الصورة والعلاج؟","b":"CD4 <100: آفات حلقية معززة متعددة + صداع/اختلاج؛ العلاج: بيريميثامين+سلفاديازين."},{"f":"التهاب السحايا بالمستخفيات: التشخيص؟","b":"CD4 منخفض: صداع + ارتفاع ضغط داخل القحف؛ مستضد المستخفية CrAg — العلاج: أمفوتيريسين B + فلوكونازول."},{"f":"متلازمة الاسترداد المناعي (IRIS)؟","b":"تفاقم التهابي بعد بدء ART مع ارتفاع CD4 — تُعالَج بالستيروئيد مع إكمال ART."},{"f":"الوقاية من PCP؟","b":"تريميثوبريم-سلفاميثوكسازول عند CD4 <200 — يقي أيضًا من المقوسات."}]},{"t":"فيروسات أخرى (داء الكلب، بارفوفيروس B19)","cards":[{"f":"داء الكلب: الوقاية بعد التعرض؟","b":"غسل الجرح + غلوبولين مناعي حول الجرح + لقاح (4 جرعات) — فورًا؛ بعد ظهور الأعراض مميت تقريبًا."},{"f":"علامات داء الكلب السريرية؟","b":"رهاب ماء/هواء + هياج + شلل — حضانة أسابيع-أشهر (أقرب للرأس أسرع)."},{"f":"بارفوفيروس B19 عند الأطفال: التظاهر؟","b":"الحمامى العدوائية: طفح خد مصفوع + شبكي بالأطراف — محدود ذاتيًا."},{"f":"بارفوفيروس B19: خطران نوعيان؟","b":"أزمة لا تنسجية بفقر الدم الانحلالي + استسقاء جنيني بالحمل (موه)."},{"f":"علاج داء الكلب العرضي؟","b":"داعم/تلطيفي فقط — الوقاية بعد التعرض هي العلاج الفعال الوحيد."}]},{"t":"التهاب الكبد الفيروسي","cards":[{"f":"التهابات الكبد A-E: طرق العدوى؟","b":"A وE: برازي-فموي (لا مزمنة). B وC وD: دموي/جنسي — B وC قد يزمنان؛ D يحتاج B."},{"f":"مصلية التهاب الكبد B الحاد؟","b":"HBsAg موجب + anti-HBc IgM موجب + HBeAg قد يكون موجبًا — الشفاء: anti-HBs."},{"f":"ماذا يعني HBsAg موجب + anti-HBs سالب + anti-HBc موجب؟","b":"إصابة مزمنة (حامل) — تُقيَّم الحمولة وإنزيمات الكبد."},{"f":"علاج التهاب الكبد B المزمن؟","b":"تينوفوفير أو إنتيكافير (مثبطات نوكليوتيد) — تثبط التكاثر ولا تشفي غالبًا."},{"f":"علاج التهاب الكبد C؟","b":"مضادات فيروسية مباشرة (سوفوسبوفير/فيلباتاسفير) 8-12 أسبوعًا — شفاء >95%."},{"f":"التهاب الكبد E والحمل؟","b":"وفيات عالية بالثلث الثالث (حتى 20%) — داعم فقط."},{"f":"التهاب الكبد D: شرطه؟","b":"لا يتكاثر إلا بوجود B (عدوى مشتركة أو فوقية) — يفاقم الشدة."},{"f":"لقاحات الكبد المتوفرة؟","b":"A وB (روتينية) — لا لقاح لـC وD وE (E بلقاح صيني محدود)."}]},{"t":"الاستجابة الالتهابية الحادة والصدمة الإنتانية","cards":[{"f":"تعريف الإنتان (Sepsis-3)؟","b":"خلل وظيفي عضوي مهدد للحياة بسبب استجابة مضيفة غير منظمة للعدوى — يُقاس بزيادة SOFA ≥2."},{"f":"تعريف الصدمة الإنتانية؟","b":"إنتان + حاجة لمقويات وعائية للحفاظ على MAP ≥65 رغم السوائل + لاكتات >2 — وفيات ~40%."},{"f":"qSOFA: مكوناته؟","b":"تنفس ≥22، تغير وعي (GCS <15)، ضغط انقباضي ≤100 — ≥2 = خطر عالٍ (مسح سريع خارج العناية)."},{"f":"حزمة الساعة الأولى بالإنتان؟","b":"قياس لاكتات + زرع دم قبل المضاد + مضاد واسع خلال ساعة + سوائل بلورية 30 مل/كغ + مقوٍّ وعائي عند الحاجة."},{"f":"المقوي الوعائي الأول بالصدمة الإنتانية؟","b":"نورإبينفرين — ثم يُضاف فازوبريسين؛ إبينفرين عند خلل قلبي مرافق."},{"f":"هدف الضغط الشرياني الوسطي (MAP) بالصدمة؟","b":"≥65 مم زئبق — أعلى لمرضى ارتفاع الضغط المزمن."},{"f":"متى تُضيَّق المضادات الحيوية؟","b":"بعد 48-72 ساعة حسب الزرع والحساسية (De-escalation) — والمدة 7-10 أيام غالبًا."},{"f":"دور اللاكتات بالإنتان؟","b":"علامة نقص تروية نسيجية — يُعاد قياسه لتوجيه الإنعاش (الهدف: تناقصه لا تطبيعه قسرًا بالسوائل)."}]},{"t":"الحميات واضطرابات الحرارة","cards":[{"f":"تعريف حمى مجهولة السبب (FUO)؟","b":"حمى >38.3 لأكثر من 3 أسابيع بلا تشخيص رغم فحص 3 أيام مشفى/3 زيارات — أسباب: خمج/ورم/مناعي."},{"f":"نمط الحمى السُلَّمية؟","b":"ارتفاع تدريجي يوميًا — كلاسيكي بالتيفوئيد."},{"f":"الحمى الدوائية: صفاتها؟","b":"حمى مع بطء قلب نسبي + طفح أحيانًا بعد دواء (بيتالاكتام/فينيتوين) — تزول بإيقافه خلال 48-72 ساعة."},{"f":"ضربة الشمس مقابل الإنهاك الحراري؟","b":"ضربة الشمس: حرارة >40 + اضطراب وعي + جلد جاف — إسعاف تبريدي. الإنهاك: تعرق ووهن بوعي سليم."},{"f":"انخفاض الحرارة (Hypothermia): درجاته؟","b":"خفيف 32-35، متوسط 28-32، شديد <28 — القلب عرضة للرجفان بالتدفئة السريعة."},{"f":"حمى النفاس: أشيع سبب؟","b":"التهاب بطانة الرحم (عقديات/لاهوائيات) — كليندامايسين+جنتاميسين."}]},{"t":"الكزاز (التيتانوس)","cards":[{"f":"الكزاز: العامل والآلية؟","b":"المطثية الكزازية (ذيفان تيتانوسبازمين) من جرح ملوث بالتراب — يمنع تحرر GABA/غليسين المثبط ← تشنج."},{"f":"العلامات السريرية للكزاز؟","b":"كزاز فكي (Lockjaw) + ابتسامة ساخرة (Risus sardonicus) + تقوس ظهري (Opisthotonos) + تشنجات بالمحرضات — الوعي سليم."},{"f":"علاج الكزاز؟","b":"غلوبولين مناعي بشري HTIG + ميترونيدازول + تنظيف الجرح + دعم تنفسي + ديازيبام للتشنج."},{"f":"الوقاية من الكزاز بعد جرح؟","b":"لقاح معزز إذا >5-10 سنوات + غلوبولين مناعي للجروح الملوثة بملقحين ناقصًا."},{"f":"هل الإصابة بالكزاز تمنح مناعة؟","b":"لا — كمية الذيفان الممرضة أقل من الممنعة؛ يجب التلقيح بعد الشفاء."},{"f":"الكزاز الوليدي: سببه؟","b":"قطع حبل سري بأدوات ملوثة بأم غير ملقحة — وقايته: لقاح الأم."},{"f":"التشخيص التفريقي للكزاز؟","b":"تسمم ستركنين، التهاب سحايا، كزاز نقص الكالسيوم — الكزاز: تشنجات بوعي سليم."}]},{"t":"الأخماج الجرثومية (ذوات الرئة اللانمطية، المكورات)","cards":[{"f":"المكورات الرئوية: العلامات المميزة والوقاية؟","b":"ذات رئة فصية بقشع صدئ + التهاب سحايا + التهاب أذن؛ التشخيص: مستضد بول؛ الوقاية: لقاح رئويات."},{"f":"المكورات العنقودية الذهبية: الذيفانات؟","b":"متلازمة الصدمة التسممية (TSST)، متلازمة الجلد المسلوق، تسمم غذائي — MRSA: فانكوميسين/لينزوليد."},{"f":"العقديات المقيحة (A): الاختلاطان المناعيان؟","b":"الحمى الرثوية (قلب/مفاصل) والتهاب الكبيبات الحاد — الوقاية: علاج التهاب البلعوم بالبنسلين."},{"f":"التهاب اللفافة الناخر: العامل والعلاج؟","b":"عقديات A (أو متعدد) — ألم شديد لا يتناسب + فقاعات + سمية؛ العلاج: تنظيف جراحي إسعافي + بنسلين+كليندامايسين."},{"f":"المكورات السحائية: العلامة الجلدية والاختلاط؟","b":"فرفرية/نزوف جلدية + صدمة (ووترهاوس-فريدريكسن: نزف كظري) — سيفترياكسون إسعافي + وقاية مخالطين."},{"f":"المفطورة الرئوية: ما يميزها؟","b":"ذات رئة جوّالة بالشباب + راصّات باردة + فقر دم انحلالي — ماكروليد/دوكسيسيكلين."},{"f":"الفيلقيات: المصدر والعلامات؟","b":"مكيفات/مياه — ذات رئة + نقص صوديوم + إسهال + تخليط؛ مستضد بول؛ أزيثروميسين."}]},{"t":"الأخماج المكتسبة من المستشفى","cards":[{"f":"الأخماج المرتبطة بالرعاية: الأنواع الأربعة؟","b":"ذات رئة بالتهوية VAP، إنتان قثطرة CLABSI، إنتان بولي بقثطرة CAUTI، إنتان جرح جراحي SSI."},{"f":"الوقاية من VAP؟","b":"رفع رأس السرير 30-45° + نظافة فموية + إيقاف تهدئة يوميًا + تجنب إفراط السوائل."},{"f":"MRSA وVRE: الاحتياطات؟","b":"عزل تلامسي + نظافة يدين كحولية + مسح أنفي للتقصي — فانكوميسين لـMRSA."},{"f":"أهم تدبير مفرد للوقاية من أخماج المشفى؟","b":"نظافة اليدين — تخفض الانتقال أكثر من أي تدبير."},{"f":"إنتان القثطرة البولية: الوقاية؟","b":"تجنب القثطرة غير الضرورية + إزالة مبكرة + تقنية عقيمة."}]},{"t":"الأخماج الفطرية (المبيضات، المستخفيات)","cards":[{"f":"المبيضات الفموية: متى تُثير القلق؟","b":"بالبالغ غير الرضيع: عوز مناعة/ستيروئيد/سكري/مضادات — نستاتين موضعي أو فلوكونازول."},{"f":"التهاب المريء بالمبيضات: لمن والعلاج؟","b":"إيدز/مثبطات مناعة: عسر بلع + لويحات؛ العلاج: فلوكونازول جهازي."},{"f":"المستخفيات: التشخيص المميز؟","b":"التهاب سحايا بإيدز: مستضد CrAg + حبر هندي/كبسولة — ارتفاع ضغط داخل القحف يُدبَّر ببزل متكرر."},{"f":"الرشاشيات الغازية: لمن والعلامة؟","b":"نقص عدلات مطول: عقد رئوية بهالة + غالاكتومانان موجب — فوريكونازول."},{"f":"الفطار العفني (Mucormycosis): العلامة والعلاج؟","b":"سكري بحماض/مثبطات: نخر أنفي-حجاجي أسود؛ العلاج: أمفوتيريسين B + تنظيف جراحي."},{"f":"داء البنسيلات/المنسوجات: أين؟","b":"كازمات رئوية مزمنة بكهوف سلّية قديمة — كرة فطرية (Aspergilloma) قد تنفث دمًا."},{"f":"علاج المبيضات الدموية؟","b":"إيكينوكاندين (كاسبوفونجين) أولًا + إزالة القثطرة — فلوكونازول للخطوة اللاحقة."}]},{"t":"الأخماج الطفيلية (التوكسوبلاسموز، الليشمانيا، البلهارسيا)","cards":[{"f":"المقوسات (Toxoplasmosis): طريق العدوى والوقاية بالحمل؟","b":"لحم نيء/براز قطط — الحامل: تجنب لحم نيء وتراب قطط؛ إصابة الثلث الأول أخطر جنينيًا."},{"f":"المقوسات الخلقية: العلامات؟","b":"استسقاء رأس + تكلسات دماغية + التهاب شبكية (ثالوث) — سبيراميسين للأم."},{"f":"الليشمانيا الحشوية (كالا-آزار): الناقل والتظاهر؟","b":"ذبابة الرمل؛ حمى + ضخامة طحال/كبد + قلة كريات شاملة — التشخيص: خزعة نخاع/طحال؛ العلاج: أمفوتيريسين شحمي."},{"f":"الليشمانيا الجلدية: التظاهر والعلاج؟","b":"قرحة جلدية مزمنة غير مؤلمة (حبة حلب) — ستيبوغلوكونات الصوديوم أو علاج موضعي."},{"f":"البلهارسيا البولية مقابل المعوية: الفرق؟","b":"دموية (S. haematobium): بيلة دموية ← سرطان مثانة حرشفي. معوية (S. mansoni): تليف بابي ← ارتفاع ضغط بابي."},{"f":"علاج البلهارسيا؟","b":"برازيكوانتيل — وحيد الجرعة غالبًا."},{"f":"الملاريا المنجلية: ما يميزها؟","b":"P. falciparum: حمى غير منتظمة + ملاريا دماغية + فقر شديد — العلاج: أرتيسونات وريدي بالشديد."},{"f":"الملاريا النوبية (Vivax/Ovale): الميزة العلاجية؟","b":"أطوار كبدية نائمة (Hypnozoites) تسبب نكسًا — بريماكين للشفاء الجذري (بعد نفي عوز G6PD)."}]},{"t":"اللقاحات والتمنيع","cards":[{"f":"لقاحات حية مقابل معطلة: أمثلة؟","b":"حية: MMR، جدري ماء، BCG، شلل فموي. معطلة: كزاز/دفتيريا، شلل حقني، إنفلونزا، كبد A/B."},{"f":"موانع اللقاحات الحية؟","b":"الحمل وعوز المناعة الشديد (إيدز متقدم/مثبطات) — تُعطى المعطلة بأمان."},{"f":"لقاح الكزاز-الدفتيريا: جدول التعزيز؟","b":"معزز كل 10 سنوات (Td) — وبعد جرح ملوث إذا >5 سنوات."},{"f":"لقاح المكورات الرئوية: لمن؟","b":">65 سنة + أمراض مزمنة/عوز مناعة + استئصال طحال."},{"f":"مناعة القطيع: ما معناها؟","b":"حماية غير الملقحين بتغطية مجتمعية عالية (>90-95% بالحصبة) — تحمي من لا يُلقَّح."}]}]},{"s":"الهضمية","topics":[{"t":"اضطرابات التغذية","cards":[{"f":"عرّف سوء التغذية (Malnutrition) وأنواعه الرئيسية.","b":"حالة نقص أو زيادة المغذيات نسبةً لاحتياج الجسم تؤدي لخلل وظيفي. الأنواع: الهزال Marasmus (نقص بروتين-طاقة مع ضمور الشحم والعضلات دون وذمة) وكواشيوركور Kwashiorkor (سعرات كافية لكن بروتين ناقص كمًّا ونوعًا — مع وذمة)."},{"f":"ما أبسط أدوات التقييم السريري للحالة التغذوية؟","b":"التقييم الذاتي الشامل SGA (Subjective Global Assessment) والتقييم المصغّر MNA (Mini Nutritional Assessment) — أدوات سريرية بسيطة معتمدة (قصة وزن، مدخول، أعراض هضمية، فحص سريري) تنبئ بالاختلاطات كالمخبر أو أفضل."},{"f":"أي البروتينات البلازمية الأكثر حساسية للتغيرات التغذوية الحادة؟","b":"البري ألبومين Prealbumin (عمر نصفي 2–3 أيام) الأكثر حساسية؛ الألبومين عمره النصفي ~18–21 يومًا فيتأخر انخفاضه ولا يعكس التغيرات الحادة."},{"f":"عوز الثيامين (B1): التظاهرات والفئة الأشيع والتدبير الإسعافي.","b":"البري بري الجاف: اعتلال أعصاب محيطي؛ الرطب: قصور قلب عالِي النتاج؛ Wernicke-Korsakoff: رنح + رأرأة/شلل عضلات العين + فقد ذاكرة وتلفيق. الأشيع عند مدمني الكحول — يُعطى الثيامين وريديًا قبل الغلوكوز (الفموي ضعيف الامتصاص)."},{"f":"عوز النياسين (B3): المرض والتظاهرات (قاعدة 3D).","b":"البلاغرا Pellagra = 3D: إسهال Diarrhea + التهاب جلد Diarmatitis (مصبّغ) + خرف Dementia. السمية: احمرار، فرط سكر الدم، خلل كبدي."},{"f":"عوز فيتامين C: المرض والتظاهرات.","b":"الإسقربوط Scurvy: ضعف التئام الجروح، نزف حول الجريبات، التهاب اللثة وعيوب الأسنان، فقر دم، ألم مفاصل."},{"f":"عوز فيتامين A وD وK: أهم تظاهرة لكل منها.","b":"A: العمى الليلي وجفاف القرنية (xerosis)؛ D: الكساح عند الأطفال وتلين العظام عند الكبار؛ K: سهولة الكدمات وتطاول زمن البروثرومبين PT (يُصحَّح بإعطاء K قبل اعتبار التطاول كبديًا)."},{"f":"متلازمة إعادة التغذية Refeeding syndrome: متى تحدث وأخطر اضطراباتها؟","b":"اختلاط استقلابي مهدد للحياة عند إعادة التغذية (فموية أو وريدية) بعد تجويع مطوّل؛ خلال ~4 أيام يهبط الفوسفات (<0.50 mmol/L) مع البوتاسيوم والمغنيزيوم → انحلال عضلي وقصور قلبي واضطراب كريات الدم. الوقاية: ثيامين وريدي عالي الجرعة قبل البدء ومراقبة الشوارد."}]},{"t":"التظاهرات السريرية والاستقصاءات","cards":[{"f":"صنّف عسر البلع سريريًا: ميكانيكي مقابل حركي.","b":"ميكانيكي (تضيق/كتلة): عسر للصلب فقط؛ حركي (اضطراب حركة): للصلب والسوائل معًا (كاللاإرخائية Achalasia). عسر البلع علامة إنذار دائمًا — ليس طبيعيًا مع التقدم بالعمر ويستوجب التقييم."},{"f":"سمات عسر البلع البلعومي الفموي (الفموي-البلعومي) وأشيع أسبابه.","b":"صعوبة نقل اللقمة للبلعوم الخلفي: سعال وشرقة، قلس أنفي، سيلان لعاب، بحة، ذات رئة استنشاقية. ~80% من الأسباب عصبية-عضلية عند كبار السن وأشيعها السكتة الدماغية (≥25% من مرضى السكتة)."},{"f":"عرّف: ألم البلع (Odynophagia) وإحساس اللقمة (Globus).","b":"Odynophagia: ألم مع البلع قد يرافق عسر البلع أو يستقل (يوحي بالتهاب/تقرح). Globus: إحساس جسم أجنبي/لقمة في الحلق بين الوجبات دون عسر بلع أو ألم بلع."},{"f":"فرّق بين: قيء دموي، تغوط أسود (Melena)، تغوط دموي (Hematochezia).","b":"Melena (براز أسود قيري): نزف هضمي علوي غالبًا (فوق رباط Treitz)؛ Hematochezia (دم أحمر): نزف سفلي غالبًا لكن النزف العلوي الغزير قد يسببه؛ القيء الدموي يؤكد مصدرًا علويًا."},{"f":"فرّق بين الإسهال الأسموزي والإفرازي سريريًا ومخبريًا.","b":"الأسموزي (سوء امتصاص لاكتوز، مسهلات أسموزية): يتوقف بالصيام، فجوة أسموزية برازية عالية. الإفرازي (ذيفانات، أورام مفرزة): يستمر مع الصيام، فجوة أسموزية منخفضة. الالتهابي: دم/قيح + حمى."},{"f":"ما علامات الإنذار في الإسهال/الألم البطني المزمن؟","b":"فقد وزن غير مقصود، نزف هضمي، فقر دم بعوز حديد، حمى، بدء بعد عمر 50، قصة عائلية لسرطان قولون/داء معوي التهابي، أعراض ليلية توقظ المريض — تستوجب التنظير لا الاكتفاء بالتشخيص الوظيفي."},{"f":"ALT أم AST: أيهما أنوع للكبد؟ وماذا يعني ارتفاع >1000؟","b":"ALT أنوع للكبد من AST (كلاهما يوجد في العضلات). ارتفاع >1000 وحدة: فيروسي أو دوائي غالبًا؛ >5000: تسمم باراسيتامول أو إقفار. التهاب كبد كحولي: قيم <400 عادة مع AST/ALT >2."},{"f":"كيف تميز النمط الركودي (Cholestatic) عن الخلوي (Hepatocellular)؟","b":"الخلوي: ارتفاع ALT/AST أساسًا. الركودي: ارتفاع الفوسفاتاز القلوية ALP أساسًا + ارتفاع GGT المرافق يؤكد المنشأ الكبدي (لأن ALP قد تكون عظمية/مشيمية)."},{"f":"ماذا يعني وجود البيلوروبين في البول؟","b":"البيلوروبين غير المقترن مرتبط بالألبومين فلا يظهر في البول؛ وجود بيلوروبين في البول = بيلوروبين مقترن = مرض كبدي/ركودي. فرط غير مقترن وحده مع بول سلبي يوحي بانحلال دم."},{"f":"ما أقرب اختبار مخبري حقيقي للوظيفة الكبدية؟","b":"زمن البروثرومبين PT/INR — يعكس قدرة الكبد على تصنيع عوامل التخثر (أعمارها النصفية بالساعات)؛ يجب تعويض عوز فيتامين K أولًا قبل نسب التطاول للكبد. الألبومين مؤشر تصنيعي لكنه بطيء (عمر نصفي ~21 يومًا)."},{"f":"SAAG: التعريف والقيمة الفاصلة.","b":"المدرج ألبومين المصل ناقص ألبومين سائل الحبن. ≥1.1 g/dL = فرط توتر وريد الباب (تشمع)؛ <1.1 = غير بابي (سل، خباثة، التهاب بنكرياس). بروتين السائل <1 g/dL = خطر مرتفع لالتهاب الصفاق الجرثومي العفوي."},{"f":"متى يبدأ التحري عن سرطان القولون والمستقيم؟ وبماذا؟","b":"من عمر 45 سنة للأشخاص متوسطي الخطورة: تنظير قولون كل 10 سنوات أو اختبار دم خفي برازي سنويًا؛ إيجابية الدم الخفي تستوجب تنظيرًا كاملًا."},{"f":"اختبار اليوريا التنفسي (Urea breath test): لماذا يُستخدم؟","b":"الكشف عن الملوية البوابية H. pylori (تشخيصًا وتأكيدًا للاستئصال بعد العلاج) — يعتمد على إنتاج الجرثوم لليورياز الذي يحوّل اليوريا الموسومة إلى CO2 يُقاس بالزفير."},{"f":"الكالبروتكتين البرازي: ما فائدته التشخيصية؟","b":"واسم التهابي برازي مرتفع في الداء المعوي الالتهابي (كرون/التهاب قولون تقرحي) وطبيعي في القولون الهيوج IBS — يميز العضوي عن الوظيفي ويقلل الحاجة للتنظير."},{"f":"أنواع فقر الدم المرتبطة بالنزف الهضمي المزمن الخفي.","b":"فقر دم بعوز الحديد (نزف مزمن خفي — عند كبار السن يستوجب تنظيرًا علويًا وسفليًا)، وفقر الدم الناجم عن الأمراض المزمنة؛ نقص B12/الفولات في سوء الامتصاص المعوي."}]},{"t":"أمراض المريء","cards":[{"f":"تعريف داء الجزر المعدي المريئي GERD وخط العلاج الأول.","b":"قلس محتويات المعدة مسببًا أعراضًا مزعجة (حرقة/قلس) أو اختلاطات (تآكلات، باريت). العلاج الأول: مثبطات مضخة البروتون PPI + إنقاص الوزن ورفع رأس السرير؛ علامات الإنذار (عسر بلع، فقد وزن، نزف، فقر دم) تستوجب التنظير."},{"f":"مريء باريت Barrett: التعريف وخطر السرطان والمتابعة.","b":"استبدال الظهارة الحرشفية بظهارة عمودية معوية (حؤول معوي) نتيجة الجزر المزمن. خطر التحول لسرطانة غدية ~0.5% سنويًا — يستوجب تنظير مراقبة دوري مع خزعات."},{"f":"اللاإرخائية Achalasia: التعريف والسمتان الأساسيتان.","b":"اضطراب حركة مريئي أولي: مصرة مريئية سفلية سيئة الارتخاء + غياب التمعج (Aperistalsis) في الثلثين القاصيين. السبب: فقد العصبونات المثبطة (أكسيد النتريك/VIP) في ضفيرة Auerbach."},{"f":"اللاإرخائية: الاستقصاء الأول والأهم والعلامة الشعاعية.","b":"الأول: بلعة الباريوم بالتنظير التألقي — مريء متوسع مع تضيق مخروطي ناعم بشكل منقار الطير Bird-beak. الأهم للتأكيد: قياس ضغط المريء Manometry (المعيار الذهبي عالي الدقة HRM)."},{"f":"التهاب المريء اليوزيني Eosinophilic esophagitis: الفئة والتظاهر.","b":"أشيع سبب للانحشار الغذائي الحاد؛ شاب/رجل مع عسر بلع متقطع للصلب وحلقات مريئية. التشخيص: خزعة تظهر ارتشاحًا يوزينيًا؛ العلاج: PPI وموسعات وستيروئيدات موضعية مبتلَعة."},{"f":"التهاب المريء الدوائي Pill esophagitis: أشيع الأدوية والوقاية.","b":"الدوكسيسيكلين، مضادات الالتهاب اللاستيروئيدية، البيسفوسفونات، كلوريد البوتاسيوم. الوقاية: بلع الدواء بكمية كافية من الماء والبقاء بوضعية قائمة ≥30 دقيقة."},{"f":"التهاب المريء بالمبيضات: الفئة والعلاج.","b":"يُصيب مثبطي المناعة (إيدز، ستيروئيدات، سكري): ألم بلع مع لويحات بيضاء. العلاج: فلوكونازول جهازي. الفيروسي (HSV/CMV): قرح عميقة — CMV عند الإيدز (غانسيكلوفير)، HSV (أسيكلوفير)."},{"f":"دوالي المريء النازفة: التدبير قبل التنظير.","b":"إنعاش + أوكتريوتيد (يخفض ضغط وريد الباب) + صادات وقائية (سيفترياكسون) ثم ربط الدوالي Band ligation بالتنظير العاجل. الوقاية الأولية/الثانوية: حاصرات بيتا غير انتقائية (بروبرانولول) أو الربط."},{"f":"فرّق بين تمزق مالوري-ويس ومتلازمة بورهاف.","b":"Mallory-Weiss: تمزق مخاطي طولي بعد قيء/تقؤ متكرر ثم قيء دموي — غالبًا يتوقف عفويًا. Boerhaave: تمزق كامل الجدار: ألم صدري شديد + نفاخ تحت الجلد (فرقعة) + استرواح منصف وانصباب جنبي أيسر — إسعاف جراحي."},{"f":"ثالوث بلمر-فنسن Plummer-Vinson.","b":"شبكة مريئية (Esophageal web) + فقر دم بعوز الحديد + التهاب لسان — يترافق بخطر مرتفع لسرطانة المريء الحرشفية."},{"f":"رتج زنكر Zenker: الموقع والاستقصاء الأفضل.","b":"جيب مخاطي في البلعوم السفلي فوق العضلة الحلقية البلعومية مباشرة (نقص ارتخائها). الأعراض: عسر بلع بلعومي مع قلس متأخر ورائحة فم كريهة. الأفضل: بلعة باريوم."},{"f":"سرطان المريء: النمطان وموقع كل منهما.","b":"الحرشفي SCC: الثلث العلوي/الأوسط — مرتبط بالكحول والتدخين والآفات الكاوية؛ الغدي Adenocarcinoma: الثلث السفلي — على أرضية باريت. التظاهر: عسر بلع مترقٍّ للصلب ثم السوائل مع فقد وزن."},{"f":"تشنج المريء المنتشر DES: التظاهر والتشخيص.","b":"ألم صدري غير قلبي + عسر بلع متقطع؛ قياس الضغط: تقلصات متزامنة غير تمعجية عالية السعة. النوتكراكر/جاكهامر: تقلصات مفرطة السعة."},{"f":"حلقة شاتزكي Schatzki ring: التظاهر.","b":"حلقة مخاطية في الوصل المعدي المريئي تسبب عسر بلع متقطع للصلب (متلازمة اللحم والخبز Steakhouse syndrome) — تُعالج بالتوسيع."}]},{"t":"أمراض المعدة والعفج","cards":[{"f":"الملوية البوابية H. pylori: أهميتها وكيف تُشخَّص وتُستأصل؟","b":"جرثومة منتجة لليورياز — تسبب التهاب معدة مزمنًا وقرحة هضمية ولمفوما MALT وسرطان معدة. التشخيص: اختبار اليوريا التنفسي أو مستضد البراز أو الخزعة؛ تأكيد الاستئصال بالتنفسي/البراز بعد 4 أسابيع من العلاج."},{"f":"القرحة الهضمية: السببان الأشيع.","b":"الملوية البوابية ومضادات الالتهاب اللاستيروئيدية (تثبط البروستاغلاندين الحامي للمخاطية). الوقاية عند المعرضين: PPI أو ميزوبروستول مع الـNSAID."},{"f":"اختلاطات القرحة العفجية حسب موقعها: أمامية مقابل خلفية.","b":"الخلفية: تنخر الشريان العفجي المعدي GDA ← نزف غزير. الأمامية: انثقاب ← بطن حاد (هواء حر تحت الحجاب). القرحة المعدية الكبيرة المزمنة: خطر التسرطن يستوجب خزعات متعددة."},{"f":"متلازمة زولينجر-إليسون: السبب والثالوث والاختبار التأكيدي.","b":"ورم غاستريني (غالبًا بنكرياسي/عفجي) — ضمن MEN1. فرط غاسترين → فرط حمض → قرحات متعددة/ناكسة + إسهال. التأكيد: اختبار تحفيز السيكريتين (ارتفاع متناقض للغاسترين). العلاج: PPI عالي الجرعة + استئصال الورم."},{"f":"لمفوما MALT المعدية: العلاقة بالملوية والعلاج.","b":"لمفوما نسيج لمفاوي مخاطي منخفضة الدرجة تُحرَّض بالملوية البوابية المزمنة — استئصال الجرثومة بالمضادات قد يشفي اللمفوما المحدودة دون علاج كيميائي."},{"f":"سرطان المعدة: النوع الأشيع وعوامل الخطورة.","b":"السرطانة الغدية (النمط المعوي). عوامل الخطورة: H. pylori، التدخين، الأطعمة المدخنة/المملحة، فقر الدم الوبيل، مرض مينترييه. Linitis plastica: نمط منتشر متليف (معدة جلدية)."},{"f":"خزل المعدة Gastroparesis: أشيع سبب والعلاج.","b":"أشيع سبب: السكري (اعتلال أعصاب مبهمي). الأعراض: غثيان/قيء مبكر وشبع مبكر. العلاج: ميتوكلوبراميد (محفز حركة) + ضبط السكر + وجبات صغيرة قليلة الدسم."},{"f":"الوقاية من قرحة الشدة Stress ulcer: لمن تُعطى؟","b":"لمرضى العناية المشددة عالي الخطورة (تهوية آلية >48h، اعتلال تخثر، صدمة، حروق واسعة): PPI أو حاصر H2 وريديًا."},{"f":"التهاب المعدة المناعي الذاتي: الآلية والاختلاطان.","b":"أضداد ضد الخلايا الجدارية/العامل الداخلي → التهاب جسم المعدة المزمن → فقر دم وبيل (عوز B12) + فرط غاسترين → أورام سرطاوية معدية؛ وخطر سرطانة غدية."},{"f":"مرض مينترييه Ménétrier: السمات.","b":"طيات معدية عملاقة (>8 مم) بفرط تنسج الظهارة الحفرية مع فقد الغدد الحمضية → نقص بروتين الدم (اعتلال معوي مضيع للبروتين) ونقص حمض. التشخيص التفريقي للطيات العملاقة: زولينجر-إليسون ولمفوما."},{"f":"عسر الهضم الوظيفي: متى يكفي العلاج التجريبي؟","b":"بعمر <55 دون علامات إنذار: اختبار واستئصال H. pylori أو PPI تجريبي. علامات الإنذار (عسر بلع، فقد وزن، قيء متكرر، فقر دم، كتلة، قصة عائلية) تستوجب تنظيرًا عاجلًا."},{"f":"نزف القرحة الهضمية: التدبير الأولي.","b":"إنعاش وريدي + PPI وريدي عالي الجرعة قبل التنظير + تنظير علاجي عاجل (حقن/تخثير/مشابك). إعادة النزف: إعادة التنظير ثم تداخل شعاعي/جراحة."},{"f":"ما العلاقة بين مضادات الالتهاب والوقاية القلبية بالأسبرين؟","b":"الأسبرين منخفض الجرعة للوقاية القلبية يرفع خطر القرحة والنزف — يُشارك مع PPI عند المرضى عالي الخطورة (مسنين، قرحة سابقة، مميعات مرافقة)."}]},{"t":"أمراض الأمعاء الدقيقة","cards":[{"f":"الداء الزلاقي Celiac: الاختبار التشخيصي المفضل والتأكيدي.","b":"التشخيصي: أضداد الترانسغلوتاميناز النسيجي IgA anti-tTG (حساسية/نوعية ~95% إذا IgA طبيعي)؛ التأكيدي: خزعة العفج (ضمور زغابات). DQ2/DQ8 سلبيته تنفي المرض بقوة. العلاج: حمية خالية من الغلوتين مدى الحياة."},{"f":"الداء الزلاقي: المظاهر خارج المعوية والمرتبطات.","b":"التهاب الجلد الحلئي الشكل Dermatitis herpetiformis (حكة وحويصلات على المرفقين والركب)، عوز IgA الانتقائي، السكري نمط 1، التهاب درق هاشيموتو. غير المعالج: لمفوما معوية T-cell وفقر دم."},{"f":"داء كرون مقابل التهاب القولون التقرحي: الفروق النسيجية.","b":"كرون: التهاب عبر الجدار Transmural، آفات متقطعة Skip lesions، تقرحات عميقة (حصوية Cobblestone)، نواسير وتضيقات، يصيب أي جزء (الأشيع اللفائفي النهائي). التقرحي: مخاطي سطحي مستمر يبدأ من المستقيم، خراجات خفية."},{"f":"التدخين وداء الأمعاء الالتهابي.","b":"التدخين يُفاقم داء كرون (يزيد النكس والحاجة للجراحة) بينما يبدو واقيًا نسبيًا في التهاب القولون التقرحي — والإقلاع عنه قد يُظهر التقرحي."},{"f":"فرط النمو الجرثومي SIBO: الآلية والعلامة المخبرية المميزة.","b":"جراثيم قولونية في الأمعاء الدقيقة تستهلك B12 (نقصه) وتُنتج الفولات (ارتفاعه) — نقص B12 مع ارتفاع فولات علامة مميزة. المعيار الذهبي: زرع رشافة العفج >10^5 CFU/mL؛ العلاج: ريفاكسيمين."},{"f":"متلازمة الأمعاء القصيرة: متى تصبح التغذية المعوية وحدها مستحيلة؟","b":"طول الأمعاء ~600 سم؛ البقاء مستحيل بالتغذية المعوية وحدها إذا بقي <قدمين (~60 سم) مع قولون وصمام لفائفي أعور سليمين، أو <5 أقدام (~150 سم) بدونهما. فقد اللفائفي القاصي = سوء امتصاص B12 والأملاح الصفراوية."},{"f":"داء ويبل Whipple: العامل والتشخيص والعلاج.","b":"Tropheryma whipplei (عصية إيجابية الغرام). التهاب مفاصل مهاجر سيرونجاتي سلبي قد يسبق الأعراض المعوية بسنوات + إسهال دهني ونقص وزن. التشخيص: بلعمات PAS إيجابية في خزعة الأمعاء. العلاج: سيفترياكسون أسبوعين ثم TMP-SMX لأكثر من سنة."},{"f":"عوز اللاكتاز: التشخيص.","b":"نفخة وإسهال أسموزي بعد الحليب. التشخيص: اختبار الهيدروجين التنفسي بعد اللاكتوز؛ العلاج: تجنب اللاكتوز أو أنزيم اللاكتاز."},{"f":"رتج ميكل Meckel: قاعدة الـ2 والاستقصاء.","b":"بقايا القناة المحية: 2% من السكان، 2 قدم من الصمام، 2 بوصة طولًا، 2% عرضيًا، بعمر <2 سنة غالبًا، نسيجان منتبذان (معدي/بنكرياسي). الاستقصاء: مسح ميكل بالتكنيشيوم Tc-99m (يلتقط المخاطية المعدية المنتبذة)."},{"f":"الورم السرطاوي المعوي Carcinoid: المفرزات والمتلازمة.","b":"يفرز السيروتونين: احمرار (Flushing) + إسهال + تليف صمامات القلب اليمنى في المتلازمة السرطاوية (مع نقائل كبدية). التشخيص: 5-HIAA في بول 24 ساعة."},{"f":"إقفار الأمعاء الحاد: السبب الأشيع والعلامة المخبرية.","b":"الأشيع: صمة شريانية منشؤها القلب (رجفان أذيني) تصيب الشريان المساريقي العلوي. ألم شديد لا يتناسب مع الفحص + حماض لبني مرتفع. العلاج: إصلاح وعائي عاجل/هيبارين."}]},{"t":"أمراض البنكرياس","cards":[{"f":"التهاب البنكرياس الحاد: السببان الأشيع عالميًا.","b":"الحصيات المرارية والكحول (عند الرجال: الكحول ~50%؛ عند النساء: الحصيات ~50%). ذاكرة الأسباب: GET SMASHED. التشخيص: ألم شرسوفي منتشر للظهر + ليباز >3 أضعاف الطبيعي + تصوير."},{"f":"التهاب البنكرياس الحاد: متى يُستطب ERCP عاجل؟","b":"عند وجود التهاب طرق صفراوية صاعد (ثالوث شاركو) أو انسداد صفراوي مستمر — ERCP خلال 24–72 ساعة. دون ذلك لا يُستطب روتينيًا."},{"f":"تقييم شدة التهاب البنكرياس الحاد: معايير BISAP.","b":"BUN>25، اضطراب وعي، SIRS، عمر>60، انصباب جنبي — كل معيار نقطة؛ ≥3 = وفيات مرتفعة. النخر البنكرياسي (~20% من الحالات) وفياته ~15%."},{"f":"الكيسة الكاذبة البنكرياسية مقابل النخر المسيّج Walled-off necrosis.","b":"الكيسة الكاذبة: تجمع سائلي بلا نخر بجدار ليفي بعد ≥4 أسابيع — تُراقب وتُصرَّف إذا عرضية/مختلطة. النخر المسيّج: يحوي نسيجًا نخريًا ويحتاج تصريفًا تداخليًا أوسع."},{"f":"التهاب البنكرياس المزمن: السبب الأشيع والثالوث السريري.","b":"الأشيع: الكحول المزمن. الثالوث: ألم شرسوفي مزمن + سوء امتصاص دهني (إسهال دهني) + سكري (تدمير جزر لانغرهانس). التكلسات البنكرياسية بالتصوير علامة مميزة."},{"f":"قصور البنكرياس الإفرازي: العلاج.","b":"إنزيمات بنكرياسية فموية مع الوجبات (ليباز كافٍ) + حمية قليلة الدسم + تعويض الفيتامينات الذوابة بالدسم A/D/E/K."},{"f":"التهاب البنكرياس المناعي الذاتي: الواسم والعلاج.","b":"مرض مرتبط بـIgG4 (ارتفاعه بالدم) — كتلة بنكرياسية تحاكي السرطان لكنها تستجيب للستيروئيدات؛ قد يترافق بالتهاب طرق صفراوية مصلب."},{"f":"سرطان البنكرياس: التظاهر الكلاسيكي لورم الرأس.","b":"يرقان غير مؤلم مترقٍّ + فقد وزن + حكة. علامة كورفوازييه: مرارة مجسوسة متوسعة مع يرقان (انسداد خبيث — المرارة السليمة تتوسع). متلازمة تروسو: خثار وريدي مهاجر."},{"f":"سرطان البنكرياس: الواسم الورمي والإنذار.","b":"CA19-9 (قد يرتفع أيضًا بالركودة الصفراوية الحميدة). معظم الحالات سرطانة غدية قنوية تُكتشف متأخرة — الاستئصال الجراحي (ويبل) ممكن فقط في المحدود القابل للاستئصال."},{"f":"الورم الغاستريني/الأنسولينوما: ثالوث ويبل.","b":"ثالوث ويبل في الأنسولينوما: أعراض نقص سكر + سكر دم <70 mg/dL + زوال الأعراض بالطعام. التشخيص: أنسولين مرتفع مع نقص سكر أثناء الصيام."},{"f":"الأورام الكيسية البنكرياسية: أيها السابق للخباثة؟","b":"الورم المخاطي الحليمي داخل القنوات IPMN والورم المخاطي الكيسي Mucinous cystic — آفات سابقة للخباثة تستوجب متابعة/استئصالًا؛ الكيسة المصلية Serous حميدة غالبًا (مظهر قرص العسل)."},{"f":"فرط شحوم الدم والتهاب البنكرياس: العتبة.","b":"شحوم ثلاثية >1000 mg/dL قد تُحدث التهاب بنكرياس حادًا — تُعالج بالصيام والسوائل والفيبرات/الأنسولين عند الشديد."},{"f":"التغذية في التهاب البنكرياس الحاد الشديد.","b":"التغذية المعوية المبكرة (أنفية صائمية) مفضلة على الإراحة المعوية الكاملة والتغذية الوريدية — أقل اختلاطات إنتانية. تُستطب الدعم التغذوي إذا تعذر الطعام >4–5 أيام."}]},{"t":"أمراض القولون والمستقيم","cards":[{"f":"التهاب القولون التقرحي: العلاج الأول للحالة الخفيفة-المتوسطة.","b":"ميزالامين (5-ASA) فمويًا/شرجيًا حسب الامتداد. الناكس الشديد: ستيروئيدات ثم مثبطات مناعة/بيولوجي (إنفليكسيماب). الاختلاط المهدد: تضخم القولون السمي Toxic megacolon (توسع >6 سم + سمية جهازية) يستوجب جراحة عاجلة."},{"f":"التهاب القولون التقرحي: متى يرتفع خطر سرطان القولون؟","b":"بعد 8–10 سنوات من بدء الأعراض في التهاب القولون الشامل — يُبدأ تنظير مراقبة دوري مع خزعات؛ وجود خلل تنسج عالي الدرجة يستوجب استئصال القولون."},{"f":"داء كرون القولوني: الخط الأول للعلاج.","b":"الخفيف: بوديزونيد/ميزالامين؛ المتوسط-الشديد: ستيروئيدات ثم آزاثيوبرين/ميثوتريكسات والبيولوجي (مضادات TNF). النواسير حول الشرج: سيتون + إنفليكسيماب."},{"f":"السلائل الغدية: أيها الأخطر؟","b":"الخطورة تزداد مع: الحجم >1 سم، المكون الزغابي Villous، خلل التنسج عالي الدرجة، العدد ≥3. التسلسل: سلالة غدية ← سرطانة (10–15 سنة) — الاستئصال التنظيري يقي من السرطان."},{"f":"داء السلائل العائلي FAP: الجين والتدبير.","b":"طفرة APC (صبغي 5) — مئات-آلاف السلائل الغدية بالمراهقة، والتحول السرطاني حتمي تقريبًا بعمر ~40. التدبير: استئصال قولون وقائي. متلازمة غاردنر: FAP + أورام عظمية/جلدية."},{"f":"متلازمة لينش Lynch: الجينات والمعايير.","b":"طفرات إصلاح عدم التطابق MMR (MLH1/MSH2/MSH6/PMS2) — سرطان قولون يميني بعمر مبكر + أورام بطانة رحم/مبيض/مسالك. التشخيص: عدم استقرار الميكروساتلايت MSI بالورم."},{"f":"النزف من الرتوج Diverticular bleeding: السمات.","b":"أشيع سبب لنزف هضمي سفلي غزير غير مؤلم عند كبار السن — غالبًا قولون أيمن/صاعد. يتوقف عفويًا غالبًا؛ الناكس يستوجب تنظيرًا أو تداخلًا شعاعيًا."},{"f":"التهاب الرتوج Diverticulitis: التظاهر والاستقصاء.","b":"ألم حفرة حرقفية يسرى + حمى + إيلام موضعي. الاستقصاء: طبقي محوري بالصباغ (سماكة جدار + التهاب محيط). المضاعفات: خراج/ناسور/تضيق. العلاج: صادات + راحة معوية؛ الخراج الكبير: تصريف."},{"f":"القولون الهيوج IBS: معايير روما والتدبير.","b":"ألم بطني ناكس مرتبط بالتغوط/تغير العادات ≥3 أيام شهريًا لآخر 3 أشهر دون علامات إنذار أو شذوذ عضوي. العلاج: طمأنة + ألياف/مضادات تشنج + علاج الإمساك/الإسهال السائد."},{"f":"عدوى المطثية العسيرة C. difficile: المحرض والعلاج.","b":"تُحرَّض بالصادات (كلينداميسين، فلوروكينولونات، سيفالوسبورينات): إسهال مائي ± غشاء كاذب بالتنظير. العلاج: فانكوميسين أو فيداكسوميسين فمويًا؛ الناكس المتكرر: زرع براز FMT."},{"f":"التهاب القولون المجهري Microscopic: السمات والعلاج.","b":"إسهال مائي مزمن عند مسنات مع تنظير طبيعي — التشخيص بالخزعة (لمفاوي/كولاجيني). العلاج: بوديزونيد."}]},{"t":"أمراض الكبد والطرق الصفراوية","cards":[{"f":"التهابات الكبد الفيروسية: أيها ينتقل بالطريق البرازي-الفموي وأيها مزمن؟","b":"A وE: برازي-فموي، حادان ولا يزمنان (E خطير على الحامل). B وC وD: دموي/جنسي؛ B وC قد يزمنان (B: 90% مزمنية عند حديثي الولادة، 5% عند البالغين)."},{"f":"مصلية التهاب الكبد B: ماذا يعني كل واسم؟","b":"HBsAg: إصابة فعالة؛ anti-HBs: مناعة (لقاح/شفاء)؛ anti-HBc IgM: حاد؛ HBeAg: تكاثر فيروسي عالٍ. العلاج المزمن: تينوفوفير أو إنتيكافير."},{"f":"التهاب الكبد C: التحري والعلاج.","b":"تحرٍّ مرة واحدة بالعمر لمواليد 1945–1965 (وفق التوصيات) وللمعرضين. العلاج: مضادات الفيروس مباشرة الفعل DAA (سوفوسبوفير/ليديباسفير...) — شفاء >95%."},{"f":"التهاب الكبد الكحولي: السمات المخبرية وقرار الستيروئيد.","b":"AST/ALT >2 مع قيم <400 غالبًا + يرقان. دالة مادري التمييزية MDF = 4.6×(PT-الشاهد)+بيلوروبين ≥32: بريدنيزولون 40 ملغ/يوم 28 يومًا (ما لم يوجد نزف/إنتان/قصور كلى)."},{"f":"داء ترسب الأصبغة الدموية Hemochromatosis: الجين والعلاج.","b":"طفرة C282Y في HFE (~85–90%): فرط امتصاص الحديد وترسبه بالكبد/البنكرياس/القلب. التشخيص: إشباع الترانسفيرين مرتفع + فيريتين. العلاج: الفصد الدوري Phlebotomy. الثلاثية: تشمع + سكري برونزي + اعتلال مفاصل."},{"f":"داء ويلسون Wilson: الجين والتشخيص والعلاج.","b":"متنحٍّ — ATP7B (صبغي 13): تراكم النحاس. الشباب + كبد/عصبية (رعاش)/حلقات كايزر-فلايشر. التشخيص: سيرولوبلازمين منخفض + نحاس بول 24 ساعة مرتفع. العلاج: بنيسيلامين/ترينتين أو زنك."},{"f":"التهاب الكبد المناعي الذاتي: الواسمات والعلاج.","b":"ANA/SMA إيجابية + IgG مرتفع + خزعة بالتهاب واجهي. العلاج: بريدنيزولون ثم آزاثيوبرين؛ البوديزونيد مع الآزاثيوبرين خيار في الخفيف غير المتشمع."},{"f":"التشمع الصفراوي الأولي PBC: الفئة والواسم والعلاج.","b":"نساء متوسطات العمر: حكة + يرقان ركودي مزمن. الواسم: AMA (ضد المتقدرات) إيجابي >95%. العلاج: حمض الأورسوديوكسيكوليك UDCA."},{"f":"التهاب الطرق الصفراوية المصلب الأولي PSC: المرتبطات والاختلاط.","b":"رجال + داء معوي التهابي (التهاب قولون تقرحي غالبًا)؛ p-ANCA قد يكون إيجابيًا. التصوير: تضيقات متقطعة بشكل مسبحة Beading. الاختلاط الأخطر: سرطان الطرق الصفراوية Cholangiocarcinoma."},{"f":"التهاب الصفاق الجرثومي العفوي SBP: التشخيص والعلاج.","b":"عدلات سائل الحبن ≥250/مم³. العلاج: سيفترياكسون + ألبومين وريدي (يقي من المتلازمة الكبدية الكلوية). الوقاية الثانوية: نورفلوكساسين."},{"f":"استسقاء التشمع: الخط الأول للعلاج.","b":"حمية قليلة الملح + سبيرونولاكتون (± فوروسيميد بنسبة 100:40). الاستسقاء المعنّد/المتوتر: بزل علاجي كبير مع ألبومين."},{"f":"الاعتلال الدماغي الكبدي: المحرضات والعلاج.","b":"المحرضات: نزف هضمي، إنتان، إمساك، مدرات، مهدئات. العلاج: لاكتولوز (إسهال 2–3 مرات/يوم) ± ريفاكسيمين للوقاية من النكس."},{"f":"حصيات المرارة: النوع الأشيع وثالوث شاركو وخماسية رينولدز.","b":"الأشيع: حصيات كوليسترول. ثالوث شاركو (التهاب طرق صفراوية صاعد): حمى + ألم ربع علوي أيمن + يرقان — يستوجب ERCP إسعافيًا. خماسية رينولدز تضيف: هبوط ضغط + تشوش (إنتان). علامة مورفي: التهاب مرارة حاد."},{"f":"سرطان الخلايا الكبدية HCC: المراقبة والتشخيص.","b":"على أرضية تشمع غالبًا. المراقبة: إيكو كبد كل 6 أشهر ± AFP. التشخيص: تعزيز شرياني مع غسل وريدي بالتصوير؛ العلاج الجذري: استئصال/زرع كبد في المبكر."},{"f":"متلازمة باد-خياري Budd-Chiari: الآلية والسبب الأشيع.","b":"انسداد الأوردة الكبدية (خثار): ألم + استسقاء + ضخامة كبد. الأسباب: حالات فرط تخثر (JAK2/كثرة الحمر، موانع حمل فموية). التشخيص: دوبلر/تصوير أوردة."}]}]},{"s":"الكلية والشوارد","topics":[{"t":"التهابات المسالك وأمراض البروستات","cards":[{"f":"التهاب المثانة غير المعقد عند النساء: العلاج الأول.","b":"نيتروفورانتوين أو فوسفوميسين (جرعة وحيدة) — علاج قصير 3 أيام. التشخيص سريري (حرقة تبول + إلحاح + تكرار دون حمى/ألم خاصرة)."},{"f":"التهاب الحويضة والكلية الحاد: التظاهر والعلاج.","b":"حمى + ألم خاصرة + إيلام زاوية ضلعية فقرية CVA مع أعراض سفلية. العلاج: فلوروكينولون (سيبروفلوكساسين) أو سيفالوسبورين 7–14 يومًا؛ الحامل: تجنب الفلوروكينولون."},{"f":"البيلة الجرثومية اللاعرضية: متى تُعالَج؟","b":"تُعالَج فقط عند الحوامل وقبل إجراءات المسالك البولية — لا تُعالَج في غيرهما (علاجها يزيد المقاومة دون فائدة)."},{"f":"التهاب البروستات الجرثومي الحاد: العلاج والمحظور.","b":"حمى + ألم عجاني + عسر تبول. العلاج: فلوروكينولون 2–4 أسابيع. محظور: مساج البروستات العنيف (خطر إنتان دم)."},{"f":"ضخامة البروستات الحميدة BPH: خطا العلاج الدوائي.","b":"حاصرات ألفا (تامسولوسين — تحسن سريع للأعراض) ومثبطات 5-ألفا ريدوكتاز (فيناستيريد — تصغير الحجم، مفعول بطيء شهور، يخفض PSA للنصف). الجراحة (TURP) للمعنّد/المختلط."},{"f":"التهاب الإحليل: السببان الأشيع والعلاج.","b":"السيلاني (إفراز قيحي): سيفترياكسون عضلي؛ المتدثرة (إفراز مخاطي): دوكسيسيكلين. يُعالَج الشريك أيضًا."},{"f":"التهابات المسالك الناكسة عند النساء: الوقاية.","b":"تبول بعد الجماع، علاج الإمساك، وفي الناكس المتكرر: نيتروفورانتوين وقائي منخفض الجرعة أو بعد الجماع."},{"f":"متى يُشتبه بالتهاب كلية درني (سل بولي)؟","b":"بيلة قيحية عقيمة (قيح دون نمو جرثومي) + بيلة دموية + أعراض مزمنة — التشخيص: زرع بول صباحي 3 أيام للمتفطرات."},{"f":"التهاب المثانة الخلالي/متلازمة ألم المثانة: السمات.","b":"ألم فوق عاني + إلحاح/تكرار مزمن مع زرع سلبي — تشخيص بالإقصاء؛ العلاج: تعديل سلوكي وأميتريبتيلين."},{"f":"احتباس البول الحاد عند مسن: السبب الأشيع والتدبير.","b":"الأشيع: ضخامة بروستات حميدة (أو أدوية مضادة كولين). التدبير: قثطرة بولية فورية ثم معالجة السبب."},{"f":"البيلة الدموية اللامؤلمة عند مدخن مسن: الاشتباه الأول.","b":"سرطان المثانة (الانتقالي) حتى يثبت العكس — يستوجب تنظير مثانة وتصويرًا. الأشيع عند المدخنين والمتعرضين للأنيلين."}]},{"t":"المظاهر السريرية والفحوصات","cards":[{"f":"البيلة الدموية الكبيبية مقابل البولية: الفرق.","b":"الكبيبية: كريات مشوهة + أسطوانات كرية حمراء + بروتينية مرافقة. البولية (حصاة/ورم): كريات طبيعية الشكل دون أسطوانات كرية. البول الكوكاكولي بعد التهاب بلعوم = التهاب كبيبات حاد."},{"f":"راسب البول: ماذا تعني كل أسطوانة؟","b":"أسطوانات كرية حمراء: التهاب كبيبات؛ بيضاء: التهاب خلالي؛ بنية موحلة Muddy brown: نخر أنبوبي حاد ATN؛ دهنية/شمعية: متلازمة نفروزية؛ هيالينية: طبيعية/تجفاف."},{"f":"البول الرغوي: ماذا يعني؟","b":"بروتينية غزيرة (تخفض التوتر السطحي) — علامة مبكرة للمتلازمة النفروزية والاعتلال السكري."},{"f":"فرّق مخبريًا بين القصور الكلوي قبل الكلوي والنخر الأنبوبي الحاد.","b":"قبل كلوي: FENa <1%، صوديوم بول <20، يوريا/كرياتينين >10، كثافة نوعية >1.020. ATN: FENa >2%، صوديوم بول >40، يوريا/كرياتينين <15، أسطوانات بنية موحلة."},{"f":"تصوير الكلى الأولي ومتى يُطلب؟","b":"الإيكو: الخط الأول (حجم الكلى، توسع حويضي، انسداد). الكلى الصغيرة المنكمشة = مزمن لا رجعة فيه؛ الطبيعية/المتضخمة مع قصور حاد = حاد."},{"f":"متى تُستطب خزعة الكلية؟","b":"متلازمة نفروزية عند بالغ، التهاب كبيبات مترقٍّ/مجهول السبب، قصور حاد غير مفسر، بيلة بروتينية غزيرة مستمرة — لتحديد النمط النسيجي والعلاج."},{"f":"ارتفاع الكرياتينين الحاد: ما أول خطوة؟","b":"مراجعة الأدوية السامة للكلى (NSAID، أمينوغليكوزيد، مثبطات ACE) + حالة الحجم + إيكو لنفي الانسداد — قبل أي إجراء آخر."},{"f":"الوذمة الكلوية: صفاتها.","b":"وذمة انطباعية تبدأ حول العين صباحًا (نفروزية) أو معممة مع ارتفاع ضغط (التهاب كبيبات حاد) — تترافق ببروتينية."},{"f":"ارتفاع ضغط الدم الكلوي: السمات المميزة.","b":"شاب/مقاوم للعلاج + نفخة بطنية + نقص بوتاسيوم (تضيق شريان كلوي)؛ أو مع قصور وبيلة بروتينية (مرض كبيبي مزمن)."},{"f":"نسبة البولة/كرياتينين: ماذا تفيد؟","b":">20 (بوحدات متوافقة): سبب قبل كلوي (إعادة امتصاص يوريا)؛ <10–15: نخر أنبوبي/كبيبي. تُفسَّر مع FENa."},{"f":"البيلة البروتينية الدقيقة Microalbuminuria: أهميتها.","b":"أبكر علامة للاعتلال الكلوي السكري ومؤشر خطر قلبي وعائي — تُكشف بنسبة ألبومين/كرياتينين البول البقعية؛ تسبق البروتينية الظاهرة بسنوات."},{"f":"الكثافة النوعية للبول: ماذا تعني القيمة الثابتة 1.010؟","b":"فقد القدرة على التركيز والتخفيف (بيلة متساوية الكثافة Isosthenuria) — علامة قصور كلوي مزمن متقدم."},{"f":"متى يكون البوتاسيوم الكاذب الارتفاع؟","b":"انحلال العينة، صفيحات مرتفعة جدًا، عاصبة مطولة — يُعاد السحب بأنبوب هيبارين قبل علاج 'فرط بوتاسيوم' وهمي."},{"f":"اليوريا المرتفعة دون كرياتينين: أسباب.","b":"نزف هضمي علوي، ستيروئيدات، حمية عالية البروتين، تجفاف — ليست قصورًا كلويًا بذاتها."},{"f":"اختبار وظيفة الكلية الأدق سريريًا.","b":"معدل الرشح الكبيبي المقدر eGFR (معادلة CKD-EPI بالكرياتينين) — الكرياتينين وحده يُضلِّل عند كبار السن وناقصي الكتلة العضلية."}]},{"t":"قصور الكلى الحاد","cards":[{"f":"صنّف أسباب القصور الكلوي الحاد الثلاثة.","b":"قبل كلوي: نقص تروية (تجفاف، صدمة، قصور قلب). كلوي: نخر أنبوبي حاد، التهاب كبيبات/خلالي، انصمام. بعد كلوي: انسداد (حصاة، بروستات، ورم) — توسع حويضي بالإيكو."},{"f":"النخر الأنبوبي الحاد ATN: السببان والعلامة الرسوبية.","b":"إقفاري (صدمة/جراحة) أو سمي (أمينوغليكوزيد، ظليل). الراسب: أسطوانات بنية موحلة Muddy brown + خلايا ظهارية أنبوبية؛ FENa >2%."},{"f":"اعتلال الكلية بالظليل: الوقاية.","b":"إماهة وريدية كافية قبل وبعد الظليل + أقل جرعة ظليل ممكنة + إيقاف NSAID مؤقتًا. عالي الخطورة: سكري + قصور مزمن."},{"f":"انحلال العضلات Rhabdomyolysis: الآلية الكلوية والعلاج.","b":"الميوغلوبين يسد الأنابيب + سمية مباشرة (بول داكن + CPK مرتفع جدًا). العلاج: إماهة وريدية غزيرة مبكرة ± بيكربونات لقلونة البول."},{"f":"فرط بوتاسيوم الدم مع تغيرات تخطيطية: التدبير الإسعافي.","b":"غلوكونات الكالسيوم 10% وريديًا (حماية قلبية — لا تخفض البوتاسيوم) + أنسولين 10 وحدات مع غلوكوز 50% + سالبوتامول إرذاذ ± بيكربونات؛ ثم غسيل كلى عاجل."},{"f":"تخطيط القلب في فرط البوتاسيوم: التتابع.","b":"T مدببة → تطاول PR وتسطح P → توسع QRS → موجة جيبية Sine wave → رجفان بطيني/توقف. أي تغير = كالسيوم فوري."},{"f":"استطبابات الغسيل الكلوي العاجل (AEIOU).","b":"A: حماض لا يستجيب؛ E: فرط بوتاسيوم/كالسيوم معند؛ I: تسمم (ساليسيلات، ميثانول، ليثيوم)؛ O: فرط حجم رئوي؛ U: أعراض يوريمية (التهاب تامور، اعتلال دماغي)."},{"f":"متلازمة الانحلال الورمي: الوقاية.","b":"إماهة غزيرة + ألوبورينول/راسبوريكاز قبل العلاج الكيميائي للأورام عالية الانقسام (لمفوما/ابيضاض) — تمنع فرط حمض بول ويوريا وبوتاسيوم."},{"f":"التهاب الكلية الخلالي الحاد الدوائي: الأشيع والعلامة.","b":"البنسلينات، NSAID، مثبطات PPI. حمى + طفح + ألم خاصرة + أسطوانات بيضاء/حمضات بالبول. العلاج: إيقاف الدواء ± ستيروئيد."},{"f":"القصور بعد الكلوي: علامة سريرية سريعة.","b":"انقطاع/تناقص بول + مثانة مجسوسة منتفخة أو تضخم بروستات؛ الإيكو يظهر توسعًا حويضيًا — القثطرة/تصريف عاجل قد يعيد الوظيفة كاملة."}]},{"t":"أمراض الكبيبات والأوعية","cards":[{"f":"فرّق بين المتلازمة النفروزية والالتهابية الكبيبية.","b":"النفروزية: بروتينية >3.5غ/يوم + نقص ألبومين + وذمة + فرط شحوم (خثار وإنتان كمضاعفات). الالتهابية: بيلة دموية كبيبية + أسطوانات كرية + ارتفاع ضغط + قلة بول."},{"f":"التهاب الكبيبات الحاد بعد العقديات: السمات.","b":"بعد 1–3 أسابيع من التهاب بلعوم/جلد عقدي: بيلة دموية + وذمة + ارتفاع ضغط. ASO مرتفع + C3 منخفض (يعود طبيعيًا بأسابيع). العلاج داعم غالبًا."},{"f":"اعتلال الكلية بالـIgA (داء بيرغر): السمة المميزة.","b":"بيلة دموية متزامنة مع التهاب بلعوم (Synpharyngitic) — ترسب IgA بالمساريق. الأشيع عالميًا؛ قد يتظاهر أيضًا ببروتينية مزمنة."},{"f":"التهاب الكبيبات المترقي السريع RPGN: النمط النسيجي والأسباب.","b":"أهلة خلوية Crescentic. الأسباب: مضاد GBM (غودباستشر: رئة+كلى)، ANCA (حبيبي ويغنر)، ومناعي معقد (ذئبة). إسعاف: ستيروئيد نبضي + سيكلوفوسفاميد ± فصادة بلازما."},{"f":"المتلازمة النفروزية عند الأطفال: السبب الأشيع والعلاج.","b":"الداء طفيف التبدلات Minimal change — بروتينية انتقائية (ألبومين فقط)، يستجيب للستيروئيدات بامتياز. الخزعة: طبيعية بالمجهر الضوئي، اندماج أقدام الخلايا بالمجهر الإلكتروني."},{"f":"التصلب الكبيبي القطعي البؤري FSGS: المرتبطات.","b":"السمنة، الإيدز (النمط المنهار)، الهيروين، الارتجاع. بروتينية غير انتقائية + مقاومة نسبية للستيروئيد."},{"f":"التهاب الكبيبات الغشائي: الواسم.","b":"أضداد مستقبل الفوسفوليباز A2 (anti-PLA2R) إيجابية في الأولي مجهول السبب — سماكة الغشاء القاعدي بشويكات Spikes بالخزعة."},{"f":"الاعتلال الكلوي السكري: التتابع والوقاية.","b":"بيلة ألبومين دقيقة ← بروتينية ظاهرة ← قصور. الوقاية/الإبطاء: ضبط سكر وضغط + مثبط ACE/ARB + مثبط SGLT2."},{"f":"تضيق الشريان الكلوي: الفئتان والعلاج.","b":"تصلب عصيدي (مسنون) وخلل تنسج ليفي عضلي (شابات). الثلاثية: ارتفاع ضغط مقاوم + نقص بوتاسيوم + تدهور كرياتينين مع ACEi. العلاج: رأب وعائي/دعامة للكلية الوحيدة أو الثنائي."},{"f":"لماذا يُمنع مثبط ACE في تضيق الشريان الكلوي الثنائي؟","b":"لأنه يزيل التضيق الوعائي الصادر المعتمد على الأنجيوتنسين فينخفض ضغط الرشح الكبيبي ← قصور حاد. (أحادي الجانب: مقبول بحذر)."},{"f":"التهاب الكلية الذئبي: الصنف الأخطر.","b":"الصنف IV المنتشر الأكثر شدة وشيوعًا عرضيًا — بروتينية + رسوبيات مناعية كاملة House Full (IgG/IgA/IgM/C3/C1q). العلاج: ستيروئيد + ميكوفينولات/سيكلوفوسفاميد."},{"f":"متلازمة انحلال الدم اليوريمية HUS: الثلاثية والسبب الأشيع عند الأطفال.","b":"فقر دم انحلالي باعتلال الأوعية الدقيقة + نقص صفيحات + قصور كلى حاد. عند الأطفال: الإشريكية القولونية O157:H7 (تُتجنب الصادات)."},{"f":"خثار الوريد الكلوي: متى يُشتبه؟","b":"ألم خاصرة مفاجئ + بيلة دموية + تدهور وظيفة لدى مريض متلازمة نفروزية (خاصة الغشائي) — التشخيص: تصوير أوردة/طبقي."}]},{"t":"قصور الكلى المزمن","cards":[{"f":"تصنيف القصور الكلوي المزمن KDIGO.","b":"حسب GFR (G1–G5: من ≥90 إلى <15) وحسب الألبومينية (A1–A3). G5 (<15) = داء كلوي بمرحلته النهائية يستوجب تحضيرًا للمعالجة المعيضة."},{"f":"فقر دم القصور المزمن: الآلية والعلاج.","b":"عوز إريثروبويتين (وفقر حديد وظيفي). العلاج: حديد أولًا (فموي/وريدي) ثم محفزات الإريثروبويتين ESA بهدف هيموغلوبين 10–11.5."},{"f":"اضطراب العظم والمعادن في القصور المزمن CKD-MBD: التتابع.","b":"احتباس فوسفات ← نقص كالسيوم وفيتامين D ← فرط جارات درق ثانوي ← تلين/تليف عظمي وتكلس وعائي. العلاج: مقيدات فوسفات + فيتامين D فعال + كالسيميميتيك."},{"f":"الحماض الاستقلابي في القصور المزمن: العلاج.","b":"بيكربونات فموية عند HCO3 <22 — تبطئ تدهور الوظيفة وتحسن التغذية والعضلات."},{"f":"فرط بوتاسيوم الدم المزمن: التدبير.","b":"حمية قليلة البوتاسيوم + مراجعة الأدوية (مثبطات ACE، سبيرونولاكتون) + مقيدات بوتاسيوم جديدة (باتيرومير/سيكلوسيليكات الزركونيوم)."},{"f":"الأعراض اليوريمية المنذرة بضرورة بدء الغسيل.","b":"التهاب تامور يوريمي، اعتلال دماغي، نزف يوريمي (خلل صفيحات)، غثيان/حكة معندة — مع GFR <10–15."},{"f":"ارتفاع ضغط الدم في القصور المزمن: الهدف والخط الأول.","b":"الهدف <130/80 غالبًا. الخط الأول: مثبط ACE أو ARB (خاصة مع بيلة بروتينية/سكري) — مع مراقبة بوتاسيوم وكرياتينين."},{"f":"مثبطات SGLT2 في القصور المزمن: الفائدة.","b":"تبطئ تدهور GFR وتقلل البيلة الألبومينية والخطورة القلبية — حتى عند غير السكريين في بعض الاستطبابات."},{"f":"التطعيمات في القصور المزمن/الغسيل.","b":"لقاح التهاب الكبد B (جرعات مضاعفة)، الإنفلونزا السنوي، المكورات الرئوية — الاستجابة المناعية أضعف في اليوريميا."},{"f":"قصور القلب والقصور الكلوي: العلاقة العلاجية.","b":"متلازمة قلبية كلوية — مدرات العروة بحذر، وتُتابَع الوظيفة عند بدء مثبطات RAAS؛ تجنب NSAID."},{"f":"الحكة اليوريمية: العلاج.","b":"غسيل كافٍ + مرطبات + مضادات هيستامين؛ المعندة: غابابنتين."},{"f":"متى يُحال مريض القصور المزمن لجراح الأوعية؟","b":"عند GFR <30 أو التدهور المتسارع — لإنشاء وصلة شريانية وريدية مبكرًا (تحتاج 6 أسابيع–6 أشهر للنضج) قبل الحاجة للغسيل."},{"f":"الأدوية الممنوعة/المعدلة في القصور المزمن.","b":"تُجنَّب NSAID والأمينوغليكوزيد؛ تُعدَّل جرعات: ديجوكسين، ألوبورينول، ميتفورمين (يُوقف عند GFR <30)، معظم الصادات."}]},{"t":"الأمراض الخلالية والكيسية والحصوات","cards":[{"f":"الداء الكلوي متعدد الكيسات السائد ADPKD: الجين والاختلاط الأخطر.","b":"PKD1 (الأشيع والأشد)/PKD2 — كلى متضخمة ثنائية + كيسات كبد/بنكرياس. الأخطر: أم دم داخل القحف (4–10% — يُتحرى عند قصة عائلية)؛ الأشيع: ارتفاع ضغط مبكر وحصيات (20%)."},{"f":"الكيسة الكلوية البسيطة مقابل المعقدة: التصنيف.","b":"بوسنياك Bosniak: I–II حميدة (مراقبة)؛ IIF متابعة؛ III–IV مشتبهة/خبيثة (جراحة). الجدار السميك والعقد والتعزيز = خباثة."},{"f":"التهاب الكلية الخلالي المزمن: السببان الأشيع.","b":"المسكنات المزمنة (اعتلال كلية مسكني: حليمات متكلسة) والليثيوم (سكري كاذب كلوي المنشأ + تليف)."},{"f":"حصيات الكلية: النوع الأشيع والاستقصاء الذهبي.","b":"الأشيع: أكسالات الكالسيوم. الذهبي: طبقي محوري غير ظليل (يكشف كل الأنواع عدا الإندينافير). حصيات حمض البول: شفافة شعاعيًا وتذوب بقلونة البول."},{"f":"المغص الكلوي: التدبير الدوائي المساعد للطرح.","b":"حصاة حالب قاصية <10 مم: تامسولوسين (حاصر ألفا) يسرّع الطرح + NSAID للألم + إماهة. الاستطباب العاجل: إنتان + انسداد (تصريف فوري)."},{"f":"حصيات الستروفيت: السياق.","b":"تتشكل ببول قلوي مع جراثيم منتجة لليورياز (Proteus) — حصيات قرن الوعل Staghorn المرجانية."},{"f":"كلية الإسفنج النخاعي: السمات.","b":"توسع قنوات جامعة قبل الحليمات — حصيات متكررة + بيلة دموية + التهابات؛ التشخيص: تصوير بفرشاة الرسم (باقة زهور)."},{"f":"النخر الحليمي الكلوي: الأسباب.","b":"السكري + المسكنات المزمنة + فقر دم منجلي — ألم خاصرة + بيلة دموية + قطع حليمية بالبول."},{"f":"التهاب الحويضة المزمن/الارتجاع: الاختلاط.","b":"ارتجاع مثاني حالبي عند الأطفال → ندب كلوية → ارتفاع ضغط وقصور مزمن. التشخيص: تصوير مثاني إحليلي أثناء التبول VCUG."}]},{"t":"تأثير الأمراض الجهازية والأدوية","cards":[{"f":"الاعتلال الكلوي بالسكري: أول علامة والتدخل الأهم.","b":"بيلة ألبومين دقيقة. التدخل: ضبط سكر/ضغط + ACEi/ARB + SGLT2i — يبطئ التدهور حتى قبل ظهور البروتينية الظاهرة."},{"f":"التصلب الكلوي بارتفاع الضغط: السمات.","b":"ارتفاع ضغط مزمن طويل → شرايين كلوية متصلبة + بروتينية خفيفة + قصور متدرج. العلاج: ضبط ضغط صارم."},{"f":"الكلية في الذئبة: متى تُجرى الخزعة؟","b":"عند أي بروتينية >0.5غ/يوم أو رسوبية فعالة أو تدهور وظيفة — لتحديد الصنف (IV الأخطر) وتوجيه التثبيط المناعي."},{"f":"الداء النشواني الكلوي: النمط والتشخيص.","b":"متلازمة نفروزية + ضخامة كلى. التشخيص: خزعة (دهن تحت جلد البطن أو كلية) بصبغة أحمر الكونغو + استقطاب (تفاحة خضراء)."},{"f":"كلية الورم النقوي (المايلوما): الآليتان.","b":"كلية القوالب (سلاسل خفيفة تسد الأنابيب — تُفاقَم بالتجفاف والظليل) والداء النشواني AL. العلاج: إماهة + علاج المايلوما."},{"f":"مضادات الالتهاب اللاستيروئيدية والكلية: الأذيتان.","b":"قصور حاد (تثبيط بروستاغلاندين → نقص تروية) والتهاب خلالي حاد/نخر حليمي مزمن. عالية الخطورة عند: مسنين، تجفاف، قصور قلب/كلى."},{"f":"الأمينوغليكوزيدات والكلية: السمية والوقاية.","b":"نخر أنبوبي حاد غير قليل البول بعد 5–7 أيام (مغنيزيوم منخفض أيضًا). الوقاية: جرعة وحيدة يومية + إماهة + مراقبة مستويات."},{"f":"الليثيوم والكلية: التأثيران.","b":"سكري كاذب كلوي المنشأ (عطاش/بوال مقاوم للفازوبريسين) + تليف خلالي مزمن مع الاستعمال الطويل."},{"f":"مثبطات ACE: التأثيران الكلويان المراقَبان عند البدء.","b":"ارتفاع بوتاسيوم وارتفاع كرياتينين (<30% مقبول) — يُعاد التقييم إذا تجاوز 30% أو فرط بوتاسيوم شديد (اشتباه تضيق شرياني)."},{"f":"التهاب الأوعية الصغيرة والكلية (ANCA): التظاهر.","b":"التهاب كبيبات مترقٍّ سريع + أعراض جهازية (جيوب/رئة) — التشخيص: ANCA + خزعة؛ العلاج: ستيروئيد + ريتوكسيماب/سيكلوفوسفاميد."}]},{"t":"الغسيل الكلوي وزرع الكلية","cards":[{"f":"الغسيل الدموي مقابل الصفاقي: الفروق الأساسية.","b":"الدموي: 3 جلسات أسبوعيًا بالمركز عبر وصلة شريانية وريدية — أسرع وأكفأ. الصفاقي: منزلي يومي عبر قثطار بطن — أنسب للراغبين بالاستقلالية ومحافظ على الوظيفة المتبقية."},{"f":"اختلاطات الغسيل الدموي الحادة.","b":"هبوط ضغط أثناء الجلسة (الأشيع)، تشنجات عضلية، متلازمة عدم التوازن (أولى الجلسات)، تلوث الوصلة."},{"f":"التهاب الصفاق في الغسيل الصفاقي: التشخيص والعلاج.","b":"ألم بطني + سائل عكر + عدلات >100/مم³. العلاج: صادات داخل الصفاق (سيفازولين/سيفترياكسون) — الأشيع العنقوديات البشروية."},{"f":"زرع الكلية: لماذا هو الأفضل؟","b":"أفضل معالجة معيضة: بقيا أطول ونوعية حياة أفضل وتكلفة أقل من الغسيل المزمن — المتبرع الحي أفضل من المتوفى."},{"f":"التثبيط المناعي بعد الزرع: الثلاثي الأساسي.","b":"مثبط كالسينيورين (تاكروليموس) + مضاد استقلاب (ميكوفينولات) + ستيروئيد — مع تحريض أولي. المراقبة: مستويات تاكروليموس + وظيفة الكلية."},{"f":"رفض الطعم الكلوي: الأنواع.","b":"خلوي حاد (أيام-أسابيع: ارتفاع كرياتينين — يُعالَج بنبض ستيروئيد)، خلطي بالأضداد (DSA إيجابي)، ومزمن (تليف تدريجي)."},{"f":"أهم إنتانات ما بعد الزرع المبكرة.","b":"الشهر الأول: جرثومية (جرح/بول)؛ 1–6 أشهر: فيروسية (CMV — وقاية بالغانسيكلوفير، BK)؛ بعدها: المجتمعية + خباثات (PTLD)."},{"f":"موانع الزرع المطلقة.","b":"خباثة فعالة، إنتان فعال، مرض قلبي رئوي شديد يمنع الجراحة، عدم الالتزام بالعلاج."}]}]},{"s":"الغدية والسكري","topics":[{"t":"مقدمة وفحص الغدد الصم","cards":[{"f":"مبدأ التغذية الراجعة في الغدد الصم: مثال.","b":"هرمون الغدة المستهدفة يثبط الهرمون المحفِّز النخامي (مثال: T4 يثبط TSH). عوز الغدة ← ارتفاع المحفِّز (قصور درقي أولي: TSH مرتفع)؛ وفرطه ← انخفاضه."},{"f":"اختبار التحفيز مقابل اختبار التثبيط: متى يُستخدم كل منهما؟","b":"التحفيز (كاختبار ACTH القصير/سيناكتن): لكشف العوز — الارتفاع غير الكافي يعني قصور الغدة. التثبيط (كديكساميتازون): لكشف الفرط — عدم التثبيط يعني فرطًا مستقلًا (كوشينغ)."},{"f":"علامات سريرية توجه للغدة: تصبغ الثنيات ويدا المعزقة.","b":"تصبغ ثنيات الجلد: قصور كظر أولي (أديسون — فرط ACTH). يدان كبيرتان كالمعزقة: ضخامة النهايات (فرط GH)."},{"f":"فحص الغدة الدرقية: ما الذي يُجسّ؟","b":"الحجم والتناظر والعقد والقوام، البلعومية (تتحرك مع البلع)، العقد اللمفية، علامات العين في غريفز، ورعشة اليدين."},{"f":"أشيع شكوى توجه لاضطراب غدي عام.","b":"تغير الوزن غير المفسر + تعب: زيادة (قصور درق/كوشينغ) أو نقص (فرط درق/أديسون/سكري) — مع أعراض نوعية لكل غدة."},{"f":"متى يُعاد تحليل الهرمونات بعد تعديل الجرعة؟","b":"بعد 6–8 أسابيع (مثال: TSH بعد تعديل ليفوثيروكسين) — لبلوغ الحالة المستقرة الجديدة."},{"f":"التداخلات الدوائية الشائعة في تحاليل الغدد.","b":"البيوتين (مكملات الشعر) يُزيف تحاليل الدرق المناعية؛ الإستروجين يرفع الغلوبولين الرابط فيُغير T4 الكلي دون الحر."},{"f":"فرط/عوز هرمون واحد قد يخفي آخر: مثال.","b":"تصحيح قصور الدرق قبل تقييم قصور الكظر قد يُظهر أزمة كظرية (الليفوثيروكسين يسرّع استقلاب الكورتيزول) — عالج الكظر أولًا عند الشك المزدوج."},{"f":"الهرمونات المدارية Tropic: أمثلة.","b":"TSH (للدرق)، ACTH (للكظر)، FSH/LH (للمناسل)، GH والبرولاكتين (مباشرة) — كلها نخامية أمامية."}]},{"t":"اضطرابات النخامية والوطاء","cards":[{"f":"أشيع ورم نخامي والعلاج الأول.","b":"البرولاكتينوما — العلاج الأول دوائي: منبهات الدوبامين (كابيرغولين/بروموكريبتين) تصغّر الورم وتعيد الخصوبة؛ الجراحة للمعنّد."},{"f":"ضخامة النهايات Acromegaly: التحري والتأكيد.","b":"التحري: IGF-1 مرتفع. التأكيد: عدم تثبيط GH باختبار تحمل الغلوكوز الفموي. العلاج: استئصال عبر الوتدي ± سوماتوستاتين/بغفيسومانت."},{"f":"داء كوشينغ Cushing disease مقابل متلازمة كوشينغ.","b":"الداء: ورم نخامي مفرز ACTH (أشيع سبب داخلي). المتلازمة: أي فرط كورتيزول (خارجي بالستيروئيدات هو الأشيع عمومًا، أو كظر/MEN)."},{"f":"قصور النخامية: أي محور يتأثر أولًا عند الأطفال؟","b":"هرمون النمو GH أول المتأثرين (قصر قامة)، ثم الهرمونات الجنسية؛ ACTH وTSH متأخران لكن عوزهما مهدد للحياة ويُعوَّض أولًا."},{"f":"البيلة التفهة المركزية مقابل الكلوية: التفريق والعلاج.","b":"عطاش وبوال مائي غزير. اختبار الحرمان من الماء: المركزية تستجيب للديسموبريسين (بول مركز)، الكلوية لا تستجيب (ليثيوم، فرط كالسيوم)."},{"f":"متلازمة شيهان Sheehan: الآلية.","b":"نزف ولادي غزير → نقص تروية النخامية المتضخمة حمليًا → نخر وقصور نخامية (فشل إرضاع، انقطاع طمث، قصور درق/كظر ثانوي)."},{"f":"السكتة النخامية Pituitary apoplexy: التظاهر.","b":"صداع مفاجئ شديد + اضطراب بصري (انضغاط التصالب) ± شلل عصب قحفي — إسعاف: ستيروئيد عالي الجرعة ± جراحة."},{"f":"فرط برولاكتين الدم: الأسباب غير الورمية.","b":"الأدوية (مضادات الذهان/ميتوكلوبراميد)، قصور الدرق الأولي، الحمل والرضاعة، قصور الكلى المزمن."},{"f":"متلازمة الإفراز غير المناسب لـADH (SIADH): السمات والعلاج.","b":"نقص صوديوم مع بول مركز وإدرار طبيعي دون وذمة (أورام/أدوية/رئوية). العلاج: تقييد السوائل؛ الشديد العرضي: محلول ملحي مفرط التوتر بحذر."}]},{"t":"أمراض الغدة الدرقية","cards":[{"f":"فسّر: TSH مرتفع + T4 حر منخفض / TSH منخفض + T4 حر مرتفع.","b":"الأول: قصور درقي أولي. الثاني: فرط درقي أولي. TSH مرتفع + T4 طبيعي = قصور تحت سريري؛ TSH منخفض + T4 طبيعي = فرط تحت سريري."},{"f":"التهاب الدرق لهاشيموتو: الواسم والعلاج.","b":"أشيع سبب لقصور الدرق: أضداد anti-TPO إيجابية. العلاج: ليفوثيروكسين (على الريق، يُعاد TSH بعد 6–8 أسابيع)."},{"f":"داء غريفز: الثلاثية المميزة.","b":"فرط درق + اعتلال عيني (جحوظ) + وذمة مخاطية أمام الظنبوب — بأضداد مستقبل TSH (TRAb). العلاج: كاربيمازول/يود مشع/جراحة."},{"f":"العاصفة الدرقية Thyroid storm: المحرضات والعلاج.","b":"تفاقم مهدد للحياة (وفيات ~10%): حمى مرتفعة + تسرع شديد + هياج/قصور قلب — يُحرَّض بإنتان/جراحة/يود مشع. العلاج: كاربيمازول + بروبرانولول + يود (بعد مضاد الدرق) + هيدروكورتيزون."},{"f":"السبات الوذمي المخاطي Myxedema coma: التظاهر والعلاج.","b":"قصور درقي شديد مهمل + محرض (إنتان/برد/مهدئات): هبوط حرارة + بطء قلب + وسن. العلاج: ليفوثيروكسين وريدي + هيدروكورتيزون (قبل التأكد من الكظر)."},{"f":"العقدة الدرقية: متى تُجرى الرشفة بالإبرة؟","b":"عقدة ≥1 سم مشبوهة بالإيكو (ناقصة الصدى، حواف غير منتظمة، تكلسات دقيقة، أطول من عريضة) — الرشفة بالإبرة الرفيعة FNA هي المعيار."},{"f":"سرطان الدرق الحليمي: السمات.","b":"الأشيع (~80%) وأحسنه إنذارًا — أجسام رملية Psammoma، ينتشر لمفيًا. العلاج: استئصال + يود مشع عند الخطورة."},{"f":"سرطان الدرق النخاعي Medullary: الواسم والمرتبطة.","b":"من خلايا C — الواسم: كالسيتونين مرتفع. مرتبط بـMEN2 (طفرة RET): يُتحرى ورم القواتم وفرط جارات الدرق."},{"f":"السرطانة غير المتمايزة Anaplastic: السمة.","b":"الأشرس والأسرع نموًا عند كبار السن — كتلة عنقية سريعة مع بحة/عسر بلع؛ الإنذار سيئ جدًا."},{"f":"العقدة الساخنة Hot nodule: ماذا تعني؟","b":"عقدة مفرزة مستقلة (تثبط باقي الغدة بالمسح) — نادرًا خبيثة؛ تسبب فرط درق (داء بلامر). العلاج: يود مشع/جراحة."},{"f":"الأميودارون والدرق: التأثيران.","b":"قد يسبب فرط درق (يود زائد/التهاب) أو قصور درق (تثبيط) — يُراقَب TSH كل 6 أشهر أثناء العلاج."},{"f":"التهاب الدرق بعد الولادة: المسار.","b":"فرط عابر (1–3 أشهر) ثم قصور عابر ثم شفاء غالبًا — بأضداد TPO؛ يُفرَّق عن غريفز (قبطة يود منخفضة)."},{"f":"قصور الدرق والحمل: القاعدة العلاجية.","b":"الليفوثيروكسين آمن وواجب — تُرفع الجرعة ~25–50% أثناء الحمل ويُحافَظ على TSH منخفض-طبيعي لحماية نمو دماغ الجنين."},{"f":"فرط الدرق تحت السريري عند المسنين: الخطر.","b":"TSH منخفض + T4 طبيعي — يرفع خطر الرجفان الأذيني وهشاشة العظام؛ يُعالَج عند كبار السن والأعراض."},{"f":"التهاب الدرق تحت الحاد (دي كيرفان): السمة.","b":"ألم درقي شديد + حمى بعد إنتان فيروسي؛ فرط عابر ثم قصور عابر؛ ESR مرتفع جدًا وقبطة يود منخفضة. العلاج: NSAID/ستيروئيد."}]},{"t":"جارات الدرق واستقالب الكالسيوم","cards":[{"f":"فرط جارات الدرق الأولي: الثلاثية المخبرية والرباعية السريرية.","b":"مخبريًا: كالسيوم مرتفع + فوسفات منخفض + PTH مرتفع. سريريًا: حصيات كلوية، آلام عظمية، آلام بطنية (قرحة/التهاب بنكرياس)، أعراض نفسية — 'حصيات وعظام وأنين بطني ونفسية'. العلاج: استئصال الغدة الورمية."},{"f":"قصور جارات الدرق: الثلاثية المخبرية والعلامتان.","b":"كالسيوم منخفض + فوسفات مرتفع + PTH منخفض (أشيع سبب: بعد جراحة الدرق). العلامتان: خفوستك (نقر العصب الوجهي) وتروسو (تشنج اليد بعاصبة الضغط). العلاج الحاد: كالسيوم وريدي."},{"f":"فرط كالسيوم الدم: السببان الأشيع والتدبير الإسعافي.","b":"الأشيع: فرط جارات الدرق الأولي والخباثة (نقائل عظمية/PTHrP). الإسعاف: إماهة وريدية غزيرة + بيسفوسفونات وريدي (زوليدرونات) ± كالسيتونين."},{"f":"عوز فيتامين D: التظاهرات والعلاج.","b":"كساح عند الأطفال وتلين عظام وآلام عضلية عند الكبار + PTH ثانوي مرتفع. العلاج: تعويض فيتامين D مع كالسيوم كافٍ."},{"f":"هشاشة العظام: التشخيص والخط الأول للعلاج.","b":"التشخيص: امتصاصية DEXA (T-score ≤-2.5). الخط الأول: بيسفوسفونات (أليندرونات أسبوعيًا — يُؤخذ على الريق بوضعية قائمة) + كالسيوم وفيتامين D."},{"f":"فرط جارات الدرق الثانوي: السياق.","b":"قصور كلى مزمن أو عوز فيتامين D مزمن: كالسيوم منخفض/طبيعي + فوسفات مرتفع + PTH مرتفع — يُعالَج السبب لا الاستئصال."},{"f":"نقص مغنيزيوم الدم: علاقته بالكالسيوم والبوتاسيوم.","b":"نقص المغنيزيوم يسبب نقص كالسيوم (مقاومة PTH) ونقص بوتاسيوم معندًا — عالج المغنيزيوم أولًا."},{"f":"الكالسيتونين: المصدر والاستخدام.","b":"من خلايا C الدرقية — يخفض الكالسيوم؛ يُستخدم رذاذًا/حقنًا في داء باجيت وهشاشة العظام وفرط كالسيوم الدم الحاد (مفعول سريع قصير)."},{"f":"داء باجيت العظمي: الواسم والعلاج.","b":"فوسفاتاز قلوية مرتفعة جدًا مع كالسيوم طبيعي. العلاج: بيسفوسفونات."}]},{"t":"اضطرابات الغدة الكظرية","cards":[{"f":"داء أديسون: السبب الأشيع والعلامة الجلدية.","b":"الأشيع: التهاب مناعي ذاتي. العلامة: فرط تصبغ الثنيات والأغشية (فرط ACTH). مخبريًا: صوديوم منخفض + بوتاسيوم مرتفع + سكر منخفض + ACTH مرتفع."},{"f":"اختبار سيناكتن القصير: ماذا يثبت؟","b":"المعيار الذهبي لقصور الكظر: حقن ACTH صناعي — عدم ارتفاع الكورتيزول الكافي = قصور كظر. يفرق الأولي (ACTH مرتفع) عن الثانوي (ACTH منخفض)."},{"f":"الأزمة الكظرية: المحرض والعلاج.","b":"إنتان/جراحة/إيقاف ستيروئيد مفاجئ عند قصور كظر: هبوط ضغط + صدمة. العلاج: هيدروكورتيزون وريدي عالي الجرعة + سوائل + سكر — لا تنتظر التحاليل."},{"f":"مضاعفة جرعة الستيروئيد (Stress dosing): متى؟","b":"عند أي مرض حاد/جراحة/حمى لدى مريض على ستيروئيد مزمن أو قصور كظر — تُضاعَف جرعة الهيدروكورتيزون 2–3 مرات."},{"f":"متلازمة كوشينغ: أشيع سبب عمومًا وأشيع سبب داخلي.","b":"عمومًا: الستيروئيدات الخارجية (دوائية). داخليًا: داء كوشينغ النخامي (ACTH مرتفع)، ثم ورم كظر مفرز (ACTH منخفض)، ثم خارج رحمي."},{"f":"اختبارات كوشينغ: التحرّي والتفريق.","b":"التحري: كورتيزول بول 24 ساعة حر أو لعاب ليلي أو تثبيط ديكساميتازون 1 ملغ. التفريق: ACTH مرتفع = معتمد عليه (نخامي/خارج رحمي)، منخفض = كظري."},{"f":"سمات كوشينغ السريرية الخمس.","b":"سمنة مركزية + وجه قمري + خطوط أرجوانية + حداب جاموسي + ضعف عضلي قريب — مع ارتفاع ضغط وسكري وهشاشة."},{"f":"ألدوستيرونية أولية (كون): الثلاثية والاختبار.","b":"ارتفاع ضغط + نقص بوتاسيوم + قلاء استقلابي. التحري: نسبة ألدوستيرون/رينين مرتفعة. السبب: ورم غدي كظري (يُستأصل) أو فرط تنسج (سبيرونولاكتون)."},{"f":"ورم القواتم Pheochromocytoma: الخماسية والتشخيص.","b":"نوبات: صداع + تعرق + خفقان + ارتفاع ضغط انتيابي + شحوب. التشخيص: ميتانفرينات البلازما/البول. القاعدة الذهبية: حصر ألفا (فينوكسيبنزامين) قبل الجراحة — لا تبدأ بحاصر بيتا وحده."},{"f":"ورم القواتم المرتبط بالمتلازمات.","b":"MEN2 (RET: درق نخاعي + قواتم + فرط جارات)، فون هيبل-لينداو، الورم العصبي الليفي NF1."},{"f":"فرط تنسج الكظر الخلقي: العوز الأنزيمي الأشيع.","b":"عوز 21-هيدروكسيلاز: غموض تناسلي عند الإناث + إضاعة ملح (نقص صوديوم/ارتفاع بوتاسيوم) + فرط أندروجين. العلاج: هيدروكورتيزون ± فلودروكورتيزون."},{"f":"الورم الكظري العرضي Incidentaloma: خطوات التقييم.","b":"نفي فرط وظيفة: كورتيزول (كوشينغ)، ميتانفرينات (قواتم)، ألدوستيرون/رينين (عند ارتفاع ضغط) + تقييم خباثة بالحجم والتصوير."},{"f":"لماذا يُعطى الفلودروكورتيزون في أديسون؟","b":"لتعويض الألدوستيرون المفقود (احتباس صوديوم وطرح بوتاسيوم) — الهيدروكورتيزون وحده لا يكفي للتوازن الملحي."},{"f":"سحب الستيروئيد المزمن: القاعدة.","b":"التدرج البطيء بعد استعمال >3 أسابيع — السحب المفاجئ قد يفجر أزمة كظرية (تثبيط المحور)."}]},{"t":"الغدد التناسلية والنمو","cards":[{"f":"قصور المناسل الذكري: أولي مقابل ثانوي مخبريًا.","b":"الأولي (خصية): تستوستيرون منخفض + LH/FSH مرتفعان. الثانوي (نخامي): تستوستيرون منخفض + LH/FSH منخفضان/طبيعيان."},{"f":"متلازمة تيرنر: الصيغة والسمات.","b":"45,XO: قصر قامة + رقبة مجنحة + انقطاع طمث أولي (شريطان ليفيان) + تضيق برزخ الأبهر. ذكاء طبيعي غالبًا."},{"f":"متلازمة كلاينفلتر: الصيغة والسمات.","b":"47,XXY: طول زائد + تثدي + خصيتان صغيرتان صلبتان + عقم (لا نطاف) + LH/FSH مرتفعان."},{"f":"متلازمة تكيس المبايض PCOS: معايير روتردام.","b":"اثنان من ثلاثة: انقطاع/قلة إباضة + فرط أندروجين (شعرانية) + مبايض متعددة الكيسات بالإيكو. العلاج: إنقاص وزن + ميتفورمين ± موانع حمل فموية."},{"f":"الشعرانية: أشيع سبب والتحري.","b":"الأشيع: PCOS ومجهول السبب. التحري: تستوستيرون حر، DHEAS (كظري)، 17-OH بروجسترون (فرط تنسج خلقي) — البدء المفاجئ الشديد يوحي بورم."},{"f":"قصر القامة عند الأطفال: أشيع سبب والتحري الهرموني.","b":"الأشيع: قصر قامة عائلي/تأخر نمو بنيوي. الهرموني: عوز GH — التحري: IGF-1 ثم اختبار تحفيز GH."},{"f":"البلوغ المبكر المركزي: التعريف والعلاج.","b":"علامات بلوغ قبل 8 سنوات (إناث)/9 (ذكور) باعتماد GnRH. العلاج: منبهات GnRH (توقف البلوغ)."},{"f":"انقطاع الطمث الأولي: الأسباب الهرمونية.","b":"عوز مبيضي (تيرنر/فشل مبكر: FSH مرتفع) أو مركزي (FSH منخفض) أو تشريحي (رحم) — يُقاس FSH/LH أولًا."},{"f":"التثدي عند الرجال: الأسباب الدوائية.","b":"سبيرونولاكتون، سيميتيدين، مضادات أندروجين، كحول/تشمع، إعادة تغذية بعد تجويع."},{"f":"ضعف الانتصاب السكري: الآلية.","b":"اعتلال أعصاب لاإرادي + اعتلال وعائي — يُعالَج بمثبطات PDE5 (سيلدينافيل) مع ضبط السكر."}]},{"t":"الداء السكري ومضاعفاته","cards":[{"f":"معايير تشخيص السكري الأربعة.","b":"HbA1c ≥6.5% أو سكر صيامي ≥126 ملغ/دل أو تحمل فموي ساعتين ≥200 أو سكر عشوائي ≥200 مع أعراض كلاسيكية (بوال/عطاش/نقص وزن)."},{"f":"السكري نمط 1 مقابل نمط 2: الفروق الجوهرية.","b":"نمط 1: مناعي ذاتي (أضداد GAD/IA-2)، بداية شابة نحيفة، حماض كيتوني، أنسولين منذ البداية. نمط 2: مقاومة أنسولين، بدانة، تدريجي، ميتفورمين أولًا."},{"f":"الحماض الكيتوني السكري DKA: معايير التشخيص.","b":"سكر ≥11 مليمول/ل (≥200 ملغ/دل) + كيتون ≥3 مليمول/ل + pH <7.3 أو بيكربونات <15. (قد يحدث بسكر طبيعي مع مثبطات SGLT2 أو حمل أو تجويع)."},{"f":"علاج الحماض الكيتوني: الركائز الأربع.","b":"إعادة الحجم (محلول ملحي 0.9%)، أنسولين وريدي، تعويض البوتاسيوم (ينخفض مع العلاج)، البحث عن المحرض (إنتان/إيقاف أنسولين)."},{"f":"الحالة فرط الأسمولية HHS: الفروق عن DKA.","b":"سكر شديد الارتفاع (>600) + أسمولية عالية + تجفاف شديد دون حماض كيتوني يُذكر — عند مسنين نمط 2؛ الوفيات أعلى من DKA. العلاج: سوائل غزيرة + أنسولين بحذر."},{"f":"نقص سكر الدم: ثالوث ويبل والعلاج.","b":"أعراض + سكر <70 ملغ/دل + زوالها بالسكر. الواعي: غلوكوز فموي؛ اللاواعي: غلوكاغون/غلوكوز وريدي. الأسباب: أنسولين/سلفونيل يوريا زائد."},{"f":"الميتفورمين: آليته ومحاذيره.","b":"يخفض إنتاج الكبد للغلوكوز — الخط الأول لنمط 2 (لا يسبب نقص سكر ولا زيادة وزن). يُوقف عند GFR <30 وقبل الظليل (خطر حماض لبني)؛ قد يسبب عوز B12."},{"f":"مثبطات SGLT2: الفائدة والخطر المميز.","b":"تطرح الغلوكوز بالبول: حماية قلبية كلوية وإنقاص وزن. الخطر: حماض كيتوني بسكر طبيعي Euglycemic DKA + إنتانات تناسلية فطرية."},{"f":"منبهات GLP-1: الفائدة.","b":"تحفز الأنسولين المعتمد على الغلوكوز + تثبط الغلوكاغون + تبطئ إفراغ المعدة: إنقاص وزن وحماية قلبية — خيار ممتاز للبدينين."},{"f":"اعتلال الشبكية السكري: التحري.","b":"تنظير قاع عين سنوي منذ التشخيص (نمط 2) أو بعد 5 سنوات (نمط 1) — بقع قطنية ونزفات ثم تكاثر أوعية؛ العلاج: تخثير ليزري/مضاد VEGF."},{"f":"القدم السكرية: الوقاية.","b":"فحص قدم سنوي (نبض + إحساس وحيدة بواسطة الخيط)، أحذية مناسبة، علاج أي جرح فورًا — اعتلال أعصاب + نقص تروية = بتر."},{"f":"اعتلال الأعصاب السكري: النمط والعلاج العرضي.","b":"قفاز-جورب حسي مؤلم (وخز/حرق ليلي). العلاج: دولوكسيتين/غابابنتين/بريغابالين — مع ضبط السكر."},{"f":"هدف HbA1c لمعظم البالغين.","b":"<7% لمعظم البالغين (أشد <6.5% للشاب دون نقص سكر، وأرخى <8% للمسن الهش)."},{"f":"السكري الحملي: التحري والعلاج.","b":"تحمّل فموي 24–28 أسبوعًا. العلاج: حمية ± أنسولين (الأفضل) أو ميتفورمين؛ يُتابع الوليد (نقص سكر/ضخامة)."},{"f":"لماذا يُمنع التدخين بشدة عند السكري؟","b":"يضاعف الخطورة القلبية الوعائية والاعتلال الكلوي وبتر الأطراف — الإقلاع من أهم التدخلات."}]}]},{"s":"الدموية","topics":[{"t":"فقر الدم","cards":[{"f":"فقر دم بعوز الحديد: الصورة المخبرية والسبب الأشيع.","b":"صغير الخلايا ناقص الصباغ: فيريتين منخفض + حديد مصل منخفض + سعة رابطة TIBC مرتفعة. أشيع سبب عند البالغ: فقد دم مزمن (طمث غزير/نزف هضمي خفي — ابحث عن السبب)."},{"f":"عوز B12 مقابل عوز الفولات: الفروقات العصبية والمخبرية.","b":"كلاهما ضخم الخلايا (MCV مرتفع + عدلات مفرطة التقطع). B12: أعراض عصبية (تنكس نخاعي تحت حاد + اعتلال أعصاب) ولا يُعطى الفولات وحده (يُخفي الدم ويُفاقم العصب). الفولات: بلا أعراض عصبية — يُعوَّض حملًا."},{"f":"فقر الدم الانحلالي: الثلاثية المخبرية.","b":"LDH مرتفع + بيليروبين غير مباشر مرتفع + هابتوغلوبين منخفض ± شبكيات مرتفعة. الكومبس المباشر يفرق المناعي."},{"f":"الثلاسيميا بيتا الكبرى: السمات والعلاج.","b":"صغير الخلايا (MCV منخفض جدًا) + خلايا هدفية + HbF مرتفع. تظهر بعد 6 أشهر (تحول HbF→HbA). العلاج: نقل دم مزمن + استخلاب الحديد (ديفيراسيروكس)."},{"f":"فقر الدم المنجلي: الأزمات والوقاية.","b":"أزمات انسداد وعائي مؤلمة + انحلال + استئصال طحال وظيفي (خطر المكورات — لقاحات + بنسلين وقائي). العلاج: هيدروكسي يوريا (ترفع HbF وتقلل الأزمات)."},{"f":"عوز G6PD: المحرضات والعلامة.","b":"أدوية مؤكسدة (بريماكين/سلفا/نيتروفورانتوين)، الفول، الإنتانات — انحلال حاد مع أجسام هاينز وخلايا مقضومة Bite cells. مرتبط بالصبغي X."},{"f":"فقر الدم اللاتنسجي Aplastic: السمات.","b":"نقص شامل (كريات بيض + حمر + صفيحات) مع شبكيات منخفضة ونقي ناقص الخلايا — يُفرَّق عن الابيضاض (لا أرومات). العلاج: مثبطات مناعة أو زرع نقي."},{"f":"فقر الدم الالتهابي المزمن: الصورة المخبرية.","b":"حديد مصل منخفض لكن فيريتين مرتفع/طبيعي (حديد محبوس) + TIBC منخفضة — يُفرَّق عن عوز الحديد بالفيريتين. العلاج: علاج المرض الأصلي."},{"f":"كثرة الكريات الحمر الحقيقية PV: السمات.","b":"JAK2 إيجابية + هيموغلوبين/هيماتوكريت مرتفعان + EPO منخفض. خطر خثار. العلاج: فصد ± هيدروكسي يوريا + أسبرين."},{"f":"فقر الدم المنجلي: لماذا لقاح المكورات الرئوية؟","b":"الاحتشاءات الطحالية المتكررة → طحال وظيفيًا غائب → خطر إنتان بالمكورات المحفظة (رئوية/مستدمية/سحائية) — لقاحات + بنسلين وقائي عند الأطفال."},{"f":"الشبكيات: ماذا تعني المرتفعة والمنخفضة؟","b":"مرتفعة: نقي يستجيب (انحلال/نزف حاد/علاج عوز). منخفضة: قصور إنتاج (لاتنسجي/عوز مبكر/قصور كلوي)."},{"f":"فقر دم + MCV طبيعي: الأسباب.","b":"نزف حاد/انحلال (شبكيات مرتفعة) أو مرض مزمن/قصور كلوي/قصور درق (شبكيات طبيعية-منخفضة)."},{"f":"التسمم بالرصاص: علامة فقر الدم.","b":"صغير الخلايا مع تنقيط قاعدي Basophilic stippling + خطوط لثوية — يُفرَّق عن الثلاسيميا."},{"f":"نقل الدم في فقر الدم المزمن المستقر: القاعدة.","b":"الأعراض لا الرقم هي المؤشر — غالبًا عتبة Hb ~7 غ/دل عند المستقر؛ صحح العوز (حديد/B12/فولات) أولًا."},{"f":"فقر الدم الانحلالي المناعي الدوائي: مثال.","b":"ميثيل دوبا، بنسلين، كينين — كومبس مباشر إيجابي؛ العلاج: إيقاف الدواء ± ستيروئيد."}]},{"t":"التظاهرات والفحص السريري","cards":[{"f":"تعداد الدم الكامل CBC: ماذا يشمل؟","b":"خضاب + هيماتوكريت + MCV/MCH + كريات بيض مع تفريقية + صفيحات + (شبكيات عند الحاجة)."},{"f":"كثرة البيض: متى تقلق من ابيضاض؟","b":"كريات بيض >50 ألف أو أرومات باللطاخة أو فقر دم/نقص صفيحات مرافق — اللطاخة المحيطية هي الخطوة الأولى دائمًا."},{"f":"نقص العدلات: العتبة الخطرة والتدبير.","b":"عدلات <500: خطر إنتان شديد. حمى عند نقص العدلات = إسعاف: زرع دم + مضاد حيوي واسع فوري (لا تنتظر الحمى أن تزول)."},{"f":"كثرة الصفيحات: أولية مقابل ثانوية.","b":"ثانوية (تفاعلية): إنتان/حديد/استئصال طحال — عابرة. أولية (أساسية): JAK2 + خطر خثار — تحتاج علاجًا نوعيًا."},{"f":"نقص الصفيحات: الأسباب الدوائية الشائعة.","b":"هيبارين (HIT)، كينين، سلفا، مضادات الصرع — راجع الأدوية دائمًا قبل التوسع."},{"f":"اللطاخة المحيطية: ماذا تكشف؟","b":"شكل الخلايا: كريات منجلية/هدفية/مقضومة، أرومات، خلايا لطخة (CLL)، عدلات مفرطة التقطع (ضخامة الأرومات)."},{"f":"تضخم الطحال الضخم: الأسباب الأربعة.","b":"تشمع كبدي (فرط ضغط بابي)، ابيضاض نخاعي مزمن CML، لمفوما، ملاريا/كالازار — كل ضخامة طحال محسوسة تستحق تقييمًا."},{"f":"اعتلال عقد لمفية معمم: متى تُخزَع العقدة؟","b":"عقدة >1 سم صلبة ثابتة >4 أسابيع أو أعراض B (حمى/تعرق ليلي/نقص وزن) — الخزعة الاستئصالية الكاملة هي المعيار (لا الرشفة)."},{"f":"سرعة التثفل ESR: ماذا ترفعها؟","b":"إنتان، التهاب، خباثة، حمل، فقر دم — غير نوعية؛ CRP أسرع استجابة وأكثر نوعية للالتهاب الحاد."},{"f":"فرط لزوجة الدم: التظاهر والإسعاف.","b":"والدنشتروم/ورم نقوي: صداع + اضطراب بصري + نزف مخاطي. الإسعاف: فصد بلازما (بلازمافيريز)."},{"f":"خزعة نقي العظم: دواعيها.","b":"نقص شامل غير مفسر، أرومات بالدم، اشتباه ابيضاض/لمفوما/نقوي، كثرة/نقص خلايا غير مفسرة."},{"f":"كثرة الحمضات Eosinophilia: الأسباب.","b":"طفيليات (الأشيع عالميًا)، تحسس/ربو، أدوية، خباثات (لمفوما هودجكن)."},{"f":"كثرة اللمفاويات عند الأطفال: القاعدة.","b":"طبيعية نسبيًا حتى عمر 4 سنوات (لمفاويات > عدلات) — لا تُفسَّر كابيضاض دون أرومات أو أعراض."},{"f":"فقر دم + يرقان + تضخم طحال: التفكير.","b":"انحلال مزمن (كروية وراثية/ثلاسيميا/منجلي) — تحقق: LDH/هابتوغلوبين/شبكيات + لطاخة."}]},{"t":"الاضطرابات النزفية","cards":[{"f":"PT مقابل aPTT: ماذا يقيس كل منهما؟","b":"PT/INR: الطريق الخارجي (العامل VII — وارفارين). aPTT: الطريق الداخلي (VIII/IX/XI/XII — هيبارين/هيموفيليا). تطاولهما معًا: عوامل مشتركة أو مثبط."},{"f":"الناعور A: الوراثة والعامل والتحليل.","b":"مرتبط بالصبغي X (ذكور) — عوز العامل VIII — aPTT متطاول وPT طبيعي. العلاج: مركز العامل VIII (وديزموبريسين في الخفيف)."},{"f":"الناعور B (مرض كريسماس): الفرق عن A.","b":"عوز العامل IX (مرتبط بـX أيضًا) — نفس الصورة السريرية؛ العلاج بمركز العامل IX."},{"f":"داء فون ويليبراند: السمة.","b":"أشيع اضطراب نزفي وراثي — صفيحي + تخثري (يحمل العامل VIII): رعاف ونزف مخاطي وطمث غزير. العلاج: ديزموبريسين/مركز vWF."},{"f":"ITP: السمات والعلاج.","b":"نقص صفيحات معزول مناعي (أطفال بعد فيروسي/بالغين مزمن). العلاج: ستيروئيد ± IVIG؛ المزمن المعند: ريتوكسيماب/استئصال طحال/منبهات TPO."},{"f":"TTP: الخماسية والعلاج الإسعافي.","b":"فقر انحلالي ميكرووعائي + نقص صفيحات + أعراض عصبية + قصور كلوي + حمى (عوز ADAMTS13). الإسعاف: تبادل بلازما فوري — التأخير قاتل."},{"f":"HUS مقابل TTP: الفرق.","b":"HUS: بعد إسهال دموي (إشريكية O157) — قصور كلوي غالب بلا أعراض عصبية بارزة. TTP: أعراض عصبية غالبة — كلاهما: انحلال ميكرووعائي + نقص صفيحات."},{"f":"DIC: متى يُشتبه والعلاج.","b":"إنتان/خباثة/ولادة: نزف + خثار معًا، صفيحات منخفضة + فبرينوجين منخفض + D-dimer مرتفع. العلاج: علاج السبب + دعم (صفيحات/بلازما)."},{"f":"نزف صفيحي مقابل نزف تخثري: الفرق السريري.","b":"الصفيحي: نمشات + نزف مخاطي فوري. التخثري (ناعور): نزف مفصلي/عضلي عميق متأخر بعد رض."},{"f":"مثبط العامل (Acquired hemophilia): متى يُشتبه؟","b":"مسن ينزف فجأة دون سوابق + aPTT متطاول لا يتصحح بالخلط — أضداد مكتسبة ضد العامل VIII."},{"f":"نقص فيتامين K: السياق.","b":"سوء امتصاص/مضادات حيوية طويلة/وارفارين: تطاول PT أولًا (العامل VII أقصر عمرًا) — يُصحح بفيتامين K."}]},{"t":"العلاج بمضادات التخثر","cards":[{"f":"الوارفارين: المراقبة والهدف العلاجي.","b":"يُراقَب بـINR — الهدف 2–3 لمعظم الاستطبابات (2.5–3.5 للصمامات الميكانيكية). مضاد فيتامين K — بداية مفعوله بطيئة (أيام)."},{"f":"عكس الوارفارين في النزف المهدد للحياة.","b":"مركز البروثرومبين PCC + فيتامين K وريدي — الأسرع والأكمل؛ فيتامين K وحده بطيء (ساعات)."},{"f":"الهيبارين غير المجزأ: المراقبة والعكس.","b":"يُراقَب بـaPTT — العكس: سلفات البروتامين. مفعول فوري وريدي — خيار الإسعاف والجراحة والقسطرة."},{"f":"نقص الصفيحات المحرض بالهيبارين HIT: التوقيت والتدبير.","b":"هبوط صفيحات >50% بعد 5–10 أيام من الهيبارين + خثار متناقض. التدبير: إيقاف كل الهيبارين فورًا + مضاد غير هيباريني (أرغاتروبان) — لا تنقل صفيحات."},{"f":"مضادات التخثر الفموية المباشرة DOACs: المزايا.","b":"(ريفاروكسابان/أبيكسابان/دابيغاتران): جرعة ثابتة بلا مراقبة INR وتداخلات أقل — ليست للصمامات الميكانيكية ولا متلازمة أضداد الفوسفوليبيد الشديدة."},{"f":"مضاد التخثر في الحمل: المسموح والممنوع.","b":"المسموح: الهيبارين (لا يعبر المشيمة). الممنوع: الوارفارين (مشوه — متلازمة الوارفارين الجنينية)."},{"f":"الأسبرين: آليته في الوقاية.","b":"تثبيط COX-1 اللاعكوس في الصفيحات → منع تصنيع ثرومبوكسان A2 — مضاد صفيحات (وقاية قلبية) لا مضاد تخثر."},{"f":"كلوبيدوغريل: متى يُضاف للأسبرين؟","b":"بعد المتلازمة الإكليلية الحادة والدعامات التاجية (علاج مزدوج مضاد للصفيحات DAPT) — بحذر من النزف."},{"f":"مدة مضاد التخثر بعد خثار وريدي عميق أول مجهول السبب.","b":"3 أشهر على الأقل؛ يُمدَّد عند استمرار الخطورة أو النكس — القرار فردي بموازنة النزف."}]},{"t":"منتجات الدم ونقل الدم","cards":[{"f":"تفاعل نقل انحلالي حاد: التظاهر والتدبير.","b":"حمى + قشعريرة + ألم خاصرة/صدر + هبوط ضغط أثناء النقل (عدم توافق ABO). التدبير: إيقاف النقل فورًا + سوائل وريدية + إبلاغ بنك الدم."},{"f":"TRALI: التعريف والتدبير.","b":"ضائقة تنفسية حادة خلال 6 ساعات من النقل (أضداد المتبرع) — وذمة رئة غير قلبية. التدبير: إيقاف النقل + دعم تنفسي (أكسجة)."},{"f":"TACO مقابل TRALI: الفرق.","b":"TACO: فرط حجم (مسن/قلبي — وذمة رئة قلبية تستجيب للمدرات). TRALI: إصابة رئة مناعية بلا فرط حجم."},{"f":"التفاعل الحموي غير الانحلالي: التدبير.","b":"حمى وقشعريرة بلا انحلال (أضداد كريات بيض) — إيقاف مؤقت + باراسيتامول؛ يُعاوَد بحذر أو بكريات مُرشَّحة."},{"f":"نقل الصفيحات: العتبات.","b":"نزف فعّال أو <10 آلاف وقائيًا (20 ألف مع حمى/إنتان)؛ قبل الجراحة الكبرى: >50 ألف (>100 ألف لجراحة العصبية/العين)."},{"f":"البلازما الطازجة المجمدة FFP: استطباباتها.","b":"نزف مع اعتلال تخثر (كبد/وارفارين/تبادل بلازما) — ليست موسع حجم ولا تُعطى لتصحيح INR مرتفع بلا نزف."},{"f":"نقل الدم الضخم: المضاعفات الثلاث.","b":"نقص كالسيوم (سترات)، فرط بوتاسيوم، هبوط حرارة — مع اعتلال تخثر تخفيفي."},{"f":"فقر الدم المنجلي ونقل الدم: المحذور.","b":"تجنب رفع الهيموغلوبين >10 غ/دل (فرط لزوجة يفاقم الانسداد) — الهدف خفض HbS لا تطبيع الخضاب."},{"f":"الحديد الوريدي: متى؟","b":"عوز حديد لا يتحمل الفموي أو فقد مستمر أو تحضير لجراحة قريبة — أسرع من الفموي."},{"f":"الغاماغلوبولين الوريدي IVIG: استطباب دموي.","b":"ITP الحاد/النزف الشديد بنقص الصفيحات — يرفع الصفيحات خلال ساعات-أيام."}]},{"t":"خباثات الدم","cards":[{"f":"الابيضاض اللمفاوي الحاد ALL: السمات.","b":"أشيع خباثة عند الأطفال — تعب + نزف + إنتانات + آلام عظمية؛ أرومات لمفاوية. العلاج: كيماوي متعدد المراحل — نسب شفاء عالية عند الأطفال."},{"f":"الابيضاض النقوي الحاد AML: العلامة المميزة.","b":"أجسام أور Auer rods في الأرومات النقوية — تُميزه عن ALL. النمط M3 (برومييلوسيتي): DIC — يُعالَج بحمض الريتينويك ATRA إسعافيًا."},{"f":"الابيضاض النقوي المزمن CML: الواسم والعلاج.","b":"صبغي فيلادلفيا t(9;22) — اندماج BCR-ABL1. العلاج: مثبطات التيروزين كيناز (إيماتينيب) — حولته لمرض مزمن."},{"f":"الابيضاض اللمفاوي المزمن CLL: السمات.","b":"مسنون: لمفاويات مرتفعة + خلايا لطخة Smudge cells باللطاخة + عقد معممة. غالبًا يُراقَب دون علاج حتى تقدم الأعراض."},{"f":"لمفوما هودجكن: الخلية المميزة والأعراض.","b":"خلايا ريد-ستيرنبرغ هي المعيار النسيجي. أعراض B: حمى + تعرق ليلي + نقص وزن. ألم العقد مع الكحول علامة كلاسيكية."},{"f":"الورم النقوي المتعدد: رباعية CRAB.","b":"فرط كالسيوم + قصور كلوي + فقر دم + آفات عظمية حالة (جمجمة مثقبة). الواسم: بروتين M/سلسلة خفيفة (بينس جونز بالبول)."},{"f":"كثرة الحمر الحقيقية والتليف النقوي: الرابط.","b":"أورام تكاثرية نقوية بطفرة JAK2 — التليف: تضخم طحال ضخم + شكل دمعي للكريات."},{"f":"متلازمة انحلال الورم: التوقيت والوقاية.","b":"بعد بدء الكيماوي (أورام سريعة): فرط بوتاسيوم + فرط فوسفات + نقص كالسيوم + فرط حمض بول. الوقاية: إماهة + ألوبيورينول/راسبوريكاز."},{"f":"داء والدنشتروم: السمة.","b":"لمفوما مع IgM أحادي النسيلة → فرط لزوجة (صداع/اضطراب بصري/نزف) — يُعالَج بفصد البلازما إسعافيًا."},{"f":"زرع نقي العظم: المبدأ.","b":"استبدال النقي المريض بعد تكييف كيماوي/شعاعي — ذاتي (لمفوما/نقوي) أو خيفي من متبرع (ابيضاضات) — خطر داء الطعم ضد الثوي GVHD في الخيفي."}]}]},{"s":"العصبية","topics":[{"t":"أخماج الجهاز العصبي","cards":[{"f":"الثلاثية الكلاسيكية لالتهاب السحايا الجرثومي (Bacterial meningitis) — ما حساسيتها؟","b":"حمى + تيبس نقري + نقص الوعي: حساسيتها منخفضة (~44%). عمليًا: ≥2 من 4 أعراض (صداع، تيبس رقبة، نقص وعي، حمى) توجد في 95% من الحالات. عند كبار السن قد تكون الأعراض غير نموذجية (خمول، نقص وعي بلا حمى)."},{"f":"فرّق سريريًا بين المتلازمات الأربع: التهاب السحايا الجرثومي، العقيم (aseptic)، التهاب الدماغ (encephalitis)، خراج الدماغ (brain abscess).","b":"• جرثومي: أعراض سحائية (+) ± قشرية. • عقيم: سحائية (+) بلا قشرية. • التهاب دماغ: قشرية (+) (تغير حالة عقلية > بؤري) ± سحائية. • خراج دماغي: بؤري > تغير الوعي ± سحائية. المشترك: صداع، حمى، تيبس نقري، رهاب ضوء، غثيان/قيء."},{"f":"مريض مشتبه بالتهاب سحايا يحتاج CT قبل البزل القطني — متى يُطلب الـCT وما الإجراء الذي لا يُنتظر؟","b":"يُطلب CT عند: نقص الوعي، اختلاجات، نقص مناعة، فحص عصبي شاذ، وذمة حليمة. القاعدة: اسحب مزارع الدم فورًا وابدأ التغطية الصادّة التجريبية فورًا — لا تنتظر نتيجة البزل."},{"f":"التغطية التجريبية لالتهاب السحايا المكتسب مجتمعيًا بعمر 16–50 سنة وعند >50 سنة — ما الفرق ولماذا؟","b":"16–50: فانكومايسين + سيفالوسبورين جيل ثالث (سيفترياكسون/سيفوتاكسيم) + ديكساميثازون. >50 سنة: يُضاف أمبيسيلين لتغطية الليستيريا (Listeria monocytogenes)."},{"f":"التهاب الدماغ بالهربس البسيط (HSV encephalitis) — العلامات المميزة والتشخيص والعلاج.","b":"أشيع سبب لالتهاب الدماغ المتقطع؛ تغير الحالة العقلية + اختلاجات ± حبسة (إصابة الفص الصدغي). التشخيص: PCR للسائل الدماغي الشوكي. العلاج: أسيكلوفير 10 ملغ/كغ وريدي كل 6 ساعات (يُعدل حسب الكلية)."},{"f":"التهاب السحايا بالمكورات السحائية (N. meningitidis) — العلامات المميزة والمضاعفة الكلاسيكية.","b":"طفح حبري (purpura) مع مكورات سحائية في الدم (meningococcemia)؛ المضاعفة: متلازمة ووترهاوس–فريدركسن (Waterhouse-Friderichsen): قصور كظري نزفي حاد. تُنتقل عبر المفرزات التنفسية وتشيع في الأماكن المزدحمة."},{"f":"الليستيريا (Listeria monocytogenes) — الفئات المعرضة والعلاج المختار.","b":"تسبب التهاب السحايا لدى مثبطي المناعة وحديثي الولادة وكبار السن، والتهاب السلى والإجهاض عند الحوامل. العلاج: أمبيسيلين (ampicillin)."},{"f":"الزهري العصبي (Neurosyphilis) — لماذا يُلقب بـ«المقلد الأعظم» وما الاستقصاء؟","b":"لتنوع تظاهراته (Treponema pallidum). التشخيص المخبري: VDRL للسائل الدماغي الشوكي + RPR مصلي. عند مرضى HIV: يُشتبه أبكر ويُجرى البزل عند CD4 ≤350 أو RPR ≥1:32."},{"f":"العقدية الرئوية (S. pneumoniae) — ما علاقتها بالتهاب السحايا وما أهم عوامل الخطر؟","b":"مكورات ثنائية إيجابية الغرام حالة للدم ألفا؛ تسبب التهاب السحايا (MOPS: التهاب سحايا، أذن وسطى، رئة، جيوب). مرضى انعدام الطحال (التشريحي أو الوظيفي) مهيؤون للعدوى بها."},{"f":"خراج الدماغ (Brain abscess) — الموقع النموذجي والعلاج التجريبي.","b":"موقع نموذجي: ملتقى المادة الرمادية والبيضاء (gray–white junction)، وحيد أو متعدد. العلاج التجريبي: سيفالوسبورين جيل ثالث + فانكومايسين + ميترونيدازول ± شفط جراحي."}]},{"t":"الأمراض الوعائية الدماغية","cards":[{"f":"الألتيبلاز الوريدي (IV alteplase / rt-PA) في السكتة الإقفارية — النافذة والتصوير المطلوب.","b":"النافذة المعتمدة في الدراسات: خلال 3 ساعات (الأثر أفضل <90 دقيقة). التصوير الوحيد المطلوب قبل الإعطاء: CT رأس بدون صبغة لنفي النزف داخل القحف (ICH)."},{"f":"ضغط الدم المسموح قبل إعطاء الألتيبلاز وبعده — ومتى نخفض الضغط عمومًا في السكتة الحادة؟","b":"يُمنع الألتيبلاز إذا الضغط >185/110. بدونه: لا تخفض الضغط إلا إذا >220/120 (أو احتشاء قلبي). بعد الحل: مراقبة ضغط كل 15 دقيقة لساعتين ثم كل 30 دقيقة لـ6 ساعات ثم كل ساعة."},{"f":"فرّق بين السكتة الصمّية (embolic) والخثارية (thrombotic) سريريًا — وتصنيف TOAST.","b":"الصمّية: بداية مفاجئة بأقصى العجز فورًا. الخثارية: قد تسبقها علامات تحذيرية (TIAs) أو مسار متقطع/متدرج على ساعات. TOAST: تصنيف فرعي حسب المسبب (قلبي صمّي، وعاء كبير، وعاء صغير، سبب محدد آخر، غير محدد)."},{"f":"النزف تحت العنكبوتية الأم دم (aSAH) — العرض المميز وخطوات الاستقصاء.","b":"صداع رعدي (thunderclap) يبلغ ذروته خلال ثوانٍ + غثيان/قيء ورهاب ضوء وتيبس رقبة. الاستقصاء: CT بدون صبغة خلال أول 12 ساعة (حساسية 93%)؛ إن كان سلبيًا والاشتباه قائمًا ← بزل قطني (الحساسية تقارب 100% عند 12 ساعة) ثم CTA."},{"f":"النزف داخل المتن (IPH/ICH) — النسبة والوفيات وأفضل منبئات الوفيات خلال 30 يومًا.","b":"يشكل 10–15% من السكتات الأولى؛ الوفيات 35% خلال 30 يومًا (نصفها في أول يومين). أفضل منبئين للوفيات: حجم النزف + مقياس غلاسكو (GCS) عند القبول. تجنب الستيروئيدات."},{"f":"مواقع النزف داخل المتن التوتري (hypertensive) مقابل الفصي (lobar) — ماذا يعني كل منهما؟","b":"التوتري: العقد القاعدية، المهاد، الجسر، المخيخ. النزف الفصي (lobar) يستدعي البحث عن اعتلال الأوعية النشواني (amyloid angiopathy) أو آفة بنيوية."},{"f":"متلازمات الشرايين: MCA مقابل ACA — التظاهر السريري لكل منهما.","b":"MCA (الفرع العلوي، الجانب السائد): ضعف وجه+ذراع أكثر من الساق، انحراف النظر نحو الآفة، حبسة بروكا. ACA: ضعف و فقد حس الساق > الفخذ/الورك ± سلس بولي ولامبالاة (abulia)."},{"f":"تسلخ الشريان السباتي الداخلي (ICA dissection) — الثلاثية السريرية.","b":"ألم رقبة/وجه/رأس + متلازمة هورنر جزئية (<50%: تدلي جفن وتقبض حدقة بلا انعدام تعرق) + إقفار دماغي/شبكي. قد يصيب الأعصاب القحفية السفلية (خاصة XII وVI). التصوير: مظهر «لهب» وتضيق غير منتظم."},{"f":"استئصال باطنة السبات (CEA) — الاستطبابات حسب درجة التضيق.","b":"تضيق عرضي 70–99% مع توقع حياة >5 سنوات. 50–69%: للرجال مع توقع حياة ≥5 سنوات؛ النساء تُدبر طبيًا. اللاعرضي 60–99%: للرجال المستقرين طبيًا مع توقع حياة ≥5 سنوات."},{"f":"النوبة الإقفارية العابرة (TIA) — التعريف والتمييز عن النوبة الصرعية والشقيقة.","b":"عجز عصبي عابر (عادة ~15 دقيقة) بأعراض سلبية تحدث دفعة واحدة عند مريض أكبر سنًا مع عوامل خطر. النوبة الصرعية: أعراض إيجابية ثم سلبية (ما بعد النوبة) بمدة ثوانٍ–دقائق. الشقيقة: تطور بطيء متسلسل (بصري ثم حسي/حركي) 15 دقيقة–ساعات، إناث أصغر مع قصة عائلية."},{"f":"متلازمة التضيق الوعائي الدماغي العكوس (RCVS) — العرض والتشخيص.","b":"صداع رعدي متكرر (أشيع عند النساء 20–50 سنة)؛ محرضات: ما بعد الولادة، أدوية منشطة وعائية (كوكايين، أمفيتامين، تريبتانات، SSRIs). التشخيص: تضيق وعائي بالتصوير يزول خلال 3 أشهر. السائل الدماغي طبيعي أو شبه طبيعي."},{"f":"CADASIL — الجين والتظاهر والتصوير.","b":"اعتلال شرياني دماغي سائد جسدي باحتشاءات تحت قشرية وابيضاض دماغي؛ طفرة NOTCH3. التظاهر: سكتات جوبية (30–50 سنة) + خرف مترقٍ + قصة شقيقة مع نسمة. التصوير: آفات مادة بيضاء واسعة خاصة الفص الصدغي الأمامي والمحفظة الخارجية."},{"f":"استئصال القحف المخفف للضغط (Decompressive craniectomy) — متى في السكتة؟","b":"في احتشاء MCA الخبيث المسبب وذمة دماغية مع انفتاق: إجراء منقذ للحياة (العمر 18–80، تدهور الوعي، <48 ساعة من البدء)."}]},{"t":"الصرع والاختلاجات","cards":[{"f":"تعريف الحالة الصرعية الاختلاجية (Convulsive status epilepticus) — العتبة الزمنية.","b":"اختلاجات مستمرة ≥5 دقائق أو ناكسة دون عودة الوعي الأساسي بينها؛ قد تسبب أذية دماغية. ~7% من الاختلاجات التوترية الرمعية المعممة تتطور إلى حالة صرعية."},{"f":"الخط الأول لعلاج الحالة الصرعية ثم الخط الثاني — الجرعات.","b":"الخط الأول: بنزوديازبين — لورازيبام 0.1 ملغ/كغ وريدي (حتى 4 ملغ) أو ميدازولام 10 ملغ عضلي. الخط الثاني: تحميل فينيتوين/فوسفينيتوين 20 ملغ/كغ، أو فالبروات 30 ملغ/كغ، أو ليفيتيراسيتام 60 ملغ/كغ. المقاومة: مخدر وريدي (بروبوفول/ميدازولام/بنتوباربيتال) + تنبيب ومراقبة EEG مستمرة."},{"f":"نوبة الغياب (Absence seizure) — الصورة السريرية والدواء المختار.","b":"تحديق قصير مع توقف النشاط عند الأطفال، EEG: موجات سنبلة-وموجة 3 هرتز. الدواء المختار: إيثوسكسيميد (ethosuximide) — يُذكر في Pocket Neurology 3e كعلاج مخصص لنوبات الغياب المعممة. تُثار بفرط التنفس."},{"f":"صرع الفص الصدغي (Temporal lobe epilepsy) — الهالة المميزة.","b":"هالة شمية («مطاط محترق») أو ذوقية، déjà vu، أعراض شرسوفية صاعدة. من أشيع بؤر الصرع البؤري عند البالغين."},{"f":"الاختلاجات الحمية (Febrile seizures) — هل هي صرع؟ وما التدبير؟","b":"ليست صرعًا (الصرع = اختلاجات ناكسة غير مستفزة). تحدث عند الأطفال <5 سنوات مع الحمى؛ غالبًا حميدة ولا تحتاج علاجًا وقائيًا مزمنًا. متلازمة GEFS+: طفرات SCN1A مع تاريخ عائلي قوي."},{"f":"أسباب الاختلاجات حسب العمر — القاعدة العامة.","b":"الأطفال <18: وراثية، إنتان (حمى)، رض، خلقية، استقلابية. البالغون: إنتان، رض، أورام، استقلابية، انسحاب كحول/أدوية."},{"f":"أي مضادات الصرع تُمنع في متلازمات الصرع المعممة؟","b":"كاربامازيبين وأوكسكاربازيبين: مضادا استطباب في متلازمات الصرع المعممة (قد تزيد الاختلاجات)."},{"f":"البنزوديازبينات في الحالة الصرعية — الآلية والاستخدامات الأخرى.","b":"تسهل عمل GABA-A بزيادة تواتر فتح قناة الكلور. الاستخدامات: القلق، التشنج، الحالة الصرعية (لورازيبام/ديازيبام/ميدازولام)، الإرجاج، الانسحاب الكحولي تحت إشراف طبي. لورازيبام/أوكسازيبام/تيمازيبام آمنة في أمراض الكبد (لا استقلاب بالمرور الأول يُذكر)."},{"f":"التمييز بين النوبة الصرعية والإغماء بعد النوبة — العلامات الفارقة.","b":"بعد النوبة: استعادة سريعة للوعي (<دقيقة) ← إغماء/نفسي؛ تخليط ما بعد النوبة (دقائق–ساعات) + صداع وألم عضلي وشلل تود (Todd) ← صرع. أثناء النوبة: سقوط رخو ← إغماء؛ تيبس ← صرع."},{"f":"مضادات الصرع المطرحة كلويًا — ولماذا يهم ذلك؟","b":"ليفيتيراسيتام، غابابنتين، بريغابالين، توبيرامات (70%): تحتاج تعديل الجرعة في القصور الكلوي."},{"f":"نوبة الوهن (Atonic / drop attack) — الوصف والتمييز.","b":"اختلاجات «السقوط»: يسقط المريض أرضًا فجأة بفقد التوتر العضلي؛ تُخلط عادة بالإغماء."},{"f":"الوقاية من الاختلاجات بعد رض الرأس الشديد — الدواء والمدة.","b":"فينيتوين أو ليفيتيراسيتام وقائيًا لمدة 7 أيام بعد رض الرأس الشديد؛ كلاهما متكافئ في إيقاف الاختلاجات المبكرة."},{"f":"متلازمة لينوكس–غاستو (Lennox-Gastaut) — أي دواء يُتجنب؟","b":"تُتجنب بعض مضادات الصرع التي قد تزيد الاختلاجات فيها (مثل بريغابالين بحذر)؛ القاعدة العامة: كاربامازيبين/أوكسكاربازيبين قد تفاقم الأنماط المعممة."}]},{"t":"الصداع والشقيقة","cards":[{"f":"جدول الصداع الأولي: التوتري مقابل الشقيقة مقابل العنقودي — الفروق الأساسية.","b":"التوتري: ثنائي «شبيه بالعصابة»، >30 دقيقة (عادة 4–6 ساعات)، بلا غثيان/قيء، أشيع صداع أولي. الشقيقة: أحادي نابض 4–72 ساعة + غثيان ورهاب ضوء/صوت ± نسمة. العنقودي: أحادي شديد حول العين مع أعراض ذاتية (دمع، احتقان أنف)."},{"f":"التريبتانات (Triptans) — الآلية والاستخدام وموانع الاستعمال.","b":"منبهات 5-HT1B/1D: تثبط تفعيل العصب الثلاثي التوائم وتمنع إطلاق الببتيد الوعائي وتقبض الأوعية. الاستخدام: الشقيقة الحادة ونوبات الصداع العنقودي. مضاد الاستطباب: داء الشريان التاجي أو الذبحة الوعائية التشنجية (خطر تشنج تاجي)."},{"f":"علاج نوبة الشقيقة الحادة — التدرج العلاجي.","b":"المعتدل: NSAIDs ± مضاد قيء. المعتدل–الشديد: تريبتانات أو دييتانات أو جيبانتات أو DHE ± NSAIDs. تُعالج مبكرًا (تقل الفعالية بعد 2–4 ساعات). تجنب الأفيونات والباربيتورات (صداع فرط الاستخدام والإدمان)."},{"f":"الصداع العنقودي (Cluster headache) — العلاج المجهض والوقائي.","b":"المجهض: سوماتريبتان تحت الجلد 6 ملغ، زولميتريبتان أنفي، أكسجين عالي التدفق. الوقائي (الخط الأول): فيراباميل (مع مراقبة ECG عند كل زيادة جرعة)."},{"f":"التهاب الشريان ذي الخلايا العملاقة (Giant cell arteritis) — العلامات التحذيرية والعلاج.","b":">50 سنة؛ صداع جديد + إيلام صدغي/فروة + عرج الفك + فقد بصري مفاجئ (عمى سريع إن لم يُعالج بالستيروئيد). التشخيص الذهبي: خزعة الشريان الصدغي. العلاج: بريدنيزون 1 ملغ/كغ (حتى 60 ملغ)؛ عند الأعراض البصرية: ميثيل بريدنيزولون وريدي."},{"f":"النزف تحت العنكبوتية كسبب لصداع ثانوي — متى تشتبه؟","b":"صداع رعدي حاد يبلغ ذروته خلال ثوانٍ. CT بدون صبغة خلال 12 ساعة (حساسية 93%)؛ CT سلبي مع اشتباه ← بزل قطني؛ صداع منذر قد يسبق التمزق."},{"f":"الوقاية من الشقيقة — الأدوية المذكورة.","b":"بروبرانولول (حاصرات بيتا) فعالة للوقاية؛ مضادات الاكتئاب ثلاثية الحلقات (أميتريبتيلين) للوقاية أيضًا. تجنب التريبتانات للوقاية اليومية."},{"f":"صداع فرط استخدام الأدوية (Medication overuse headache) — القاعدة.","b":"الاستخدام المتكرر للمسكنات/التريبتانات يسبب صداعًا مزمنًا؛ العلاج: إيقاف الدواء المفرط. الأفيونات والباربيتورات (فيوريسيت) تُتجنب لارتباطها به."},{"f":"ألم العصب الثلاثي التوائم (Trigeminal neuralgia) — الوصف والعلاج الأول.","b":"ألم وجهي حاد طاعن متقطع في توزع العصب الخامس يُثار باللمس/المضغ. العلاج الأول: كاربامازيبين."},{"f":"التمييز بين الشقيقة والنوبة الإقفارية العابرة (TIA) سريريًا.","b":"الشقيقة: مرضى أصغر، إناث أكثر، قصة عائلية؛ أعراض إيجابية ثم سلبية تتطور ببطء وتتسلسل (بصري ← حسي/حركي) 15 دقيقة–ساعات. TIA: مرضى أكبر مع عوامل خطر؛ أعراض سلبية تحدث دفعة واحدة بمدة قصيرة (~15 دقيقة)."},{"f":"صداع ما بعد البزل (Post-dural puncture headache) — الصفة المميزة.","b":"صداع وضعي: يزداد بالوقوف ويتحسن بالاستلقاء بعد البزل القطني؛ العلاج: الراحة، السوائل، الكافيين، وفي الحالات الشديدة رقعة دموية فوق الجافية."},{"f":"التهاب الجيوب كسبب صداع — متى تشتبه؟","b":"ألم وجهي ضاغط يزداد بالانحناء للأمام مع أعراض تنفسية علوية؛ ليس كل ألم وجهي صداعًا توتريًا."},{"f":"الصداع في الحمل — أي الأنواع يتحسن؟","b":"الصداع التوتري يتحسن غالبًا في الحمل؛ الشقيقة بلا نسمة والطمثية تتحسن غالبًا؛ الشقيقة مع النسمة متغيرة (قاعدة الأثلاث: ثلث يتحسن، ثلث يسوء، ثلث ثابت)."}]},{"t":"الأمراض العصبية التنكسية","cards":[{"f":"داء باركنسون — التشريح المرضي والرباعية السريرية.","b":"فقد عصبونات الدوبامين في المادة السوداء (SNpc). الرباعية: بطء الحركة (bradykinesia)، صلابة، رعاش راحي (pill-rolling)، اضطراب المشية/التوازن. DaTscan شاذ."},{"f":"داء ألزهايمر — التشريح المرضي المميز.","b":"خارج خلوي: لويحات شيخية بنواة أميلويد-بيتا (Aβ من انقسام APP). داخل خلوي: تشابكات ليفية عصبية من بروتين تاو مفرط الفسفرة (عددها يتناسب مع درجة الخرف). العلاج: مثبطات الكولين إستراز (دونبيزيل، ريفاستيغمين، غالانتامين)."},{"f":"داء هنتنغتون — الوراثة والجين والتظاهر.","b":"سائد جسدي؛ توسع CAG في جين هنتنغتين. فقد عصبونات GABAergic من المخطط ← رقص (chorea) + خرف + تنكس النواة المذنبة (ضمورها بالتصوير)."},{"f":"التصلب الجانبي الضموري (ALS) — التعريف والعلاج.","b":"تنكس يجمع علامات UMN (فرط منعكسات، بابنسكي +) وLMN (ضمور، ارتجافات حزمية) معًا؛ متوسط البقاء ~3 سنوات من بدء الأعراض. العلاج: ريلوزول (riluzole) يطيل البقاء أشهرًا؛ إيدارافون يبطئ التدهور الوظيفي."},{"f":"الخرف بأجسام ليوي (Lewy body dementia) — العلامات المميزة.","b":"تذبذب معرفي + هلوسات بصرية + باركنسونية؛ حساسية شديدة لمضادات الذهان. التشريح: أجسام ليوي (ألفا-سينوكلين)."},{"f":"الشلل فوق النووي المترقي (PSP) — العلامة السريرية المميزة.","b":"شلل النظر العمودي (خاصة للأسفل) + عدم استقرار وضعي مع سقوط للخلف + باركنسونية لا تستجيب جيدًا لليفودوبا. التصوير: ضمور سقف الدماغ المتوسط."},{"f":"الضمور متعدد الأنظمة (MSA) — التظاهر المميز.","b":"باركنسونية + فشل ذاتي مبكر وشديد (هبوط ضغط انتصابي، اضطراب تبول) ± علامات مخيخية. التصوير: ضمور زيتوني جسري مخيخي."},{"f":"استسقاء الدماغ سوي الضغط (NPH) — الثلاثية والعلاج.","b":"سلس بولي + تعذر مشية (gait apraxia) + خلل معرفي؛ ضغط السائل طبيعي. العلاج: تحويلة بطينية (shunt) — قابل للعكس."},{"f":"رنح فريدريخ (Friedreich ataxia) — التظاهر والوراثة.","b":"متنحٍّ جسدي (توسع GAA في جين فراتاكسين). مشية مترنحة وسقوط متكرر ورأرأة وأصابع مطرقية + داء سكري + اعتلال عضلة قلبية ضخامي."},{"f":"الخرف الجبهي الصدغي (FTD) — ما يميزه عن ألزهايمر؟","b":"تغيرات سلوكية وشخصية مبكرة (فقد الكبح، اللامبالاة) مع حفظ الذاكرة نسبيًا في البدء؛ ضمور جبهي صدغي غير متناظر؛ سلبي لصبغة الأميلويد (PiB)."}]},{"t":"التصلب اللويحي المتعدد","cards":[{"f":"التصلب المتعدد (MS) — التعريف والفئة العمرية.","b":"التهاب مناعي ذاتي يزيل ميالين الجهاز العصبي المركزي (دماغ + نخاع) مع تلف محوري لاحق. يصيب غالبًا الإناث بعمر 20–40؛ الانتشار أعلى بعيدًا عن خط الاستواء ومع نقص فيتامين D."},{"f":"التهاب العصب البصري (Optic neuritis) كتظاهر للتصلب المتعدد — الصورة.","b":"فقد بصري أحادي حاد مؤلم (يزداد بحركة العين) مع عيب حدقي وارد نسبي (RAPD). أشيع تظاهر أولي؛ تحويله للتصلب المتعدد أقل من التهاب النخاع المستعرض."},{"f":"الشلل العيني بين النوى (INO) — الآفة والسبب الأشيع عند الشباب.","b":"آفة الحزمة الطولانية الأنسية (MLF): شلل نظر أفقي مترافق مع رأرأة العين المبعدة. عند الشباب: تصلب متعدد (ثنائي)؛ عند الكبار: احتشاء (أحادي)."},{"f":"التصوير في التصلب المتعدد — المواقع والعلامات المميزة.","b":"لويحات بيضوية حول البطينات (أصابع داوسون Dawson fingers)، الجسم الثفني، تحت الخيمة، النخاع (<3 قطع). الآفات الحادة تتعزز بالغادولينيوم (حلقي/ناقص)؛ علامة الوريد المركزي نوعية."},{"f":"معايير التشخيص — مفهوما الانتشار المكاني والزماني (McDonald).","b":"الانتشار المكاني (DIS): آفة T2 في ≥2 من 4 مناطق (حول بطيني، قشري/مجاور قشري، تحت خيمة، نخاع). الانتشار الزماني (DIT): آفات معززة وغير معززة معًا، أو آفة جديدة لاحقًا، أو أشرطة قليلة النسائل بالسائل."},{"f":"النمط السريري الأشيع للتصلب المتعدد ونسبته.","b":"الناكس–الهاجع (RRMS): 85–90% من الحالات في البدء. الأولي المترقي (PPMS): 10–15% (مرضى أكبر سنًا، تراكم عجز حركي تدريجي)."},{"f":"علاج الهجمة الحادة للتصلب المتعدد.","b":"ميثيل بريدنيزولون وريدي عالي الجرعة؛ الهجمات الشديدة المقاومة للستيروئيد ← تبادل البلازما."},{"f":"الأدوية المعدلة للمرض (DMTs) — أمثلة وآثار جانبية مميزة.","b":"إنترفيرون بيتا: أعراض شبيهة بالإنفلونزا. ناتاليزوماب: خطر اعتلال بيضاء الدماغ متعدد البؤر المترقي (PML). فينغوليمود: بطء قلب. ميتوكسانترون: اعتلال عضلة قلبية وابضاض."},{"f":"التهاب النخاع والعصب البصري (NMOSD) — ما يميزه عن التصلب المتعدد؟","b":"ضد أكوابورين-4 (AQP4)؛ التهاب نخاع مستعرض طويل (≥3 قطع) + التهاب عصب بصري ثنائي شديد؛ لا يستجيب لإنترفيرون بيتا (قد يسوء)."}]},{"t":"اضطرابات الوصل العصبي العضلي","cards":[{"f":"الوهن العضلي الوبيل (Myasthenia gravis) — الآلية والأعراض.","b":"أضداد ضد مستقبلات الأسيتيل كولين بعد المشبكية (nicotinic AChR)؛ 80–90% إيجابية في المعمم. الأعراض: تدلي جفن، ازدواج، عسر بلع/تلعثم، ضعف أطراف يتفاقم بالجهد ويتحسن بالراحة (تذبذب)."},{"f":"اختبار التخطيط الكهربائي في الوهن العضلي الوبيل مقابل لامبرت–إيتون.","b":"الوبيل (بعد مشبكي): تنبيه عصبي متكرر 3 هرتز ← نقص >10% في سعة CMAP (decrement). لامبرت–إيتون (قبل مشبكي): زيادة >100–160% بعد الجهد (facilitation/increment). تخطيط الألياف المفردة الأكثر حساسية (>95%)."},{"f":"علاج الوهن العضلي الوبيل — العرضي والمناعي.","b":"العرضي: بيريدوستيغمين (مثبط كولين إستراز طويل المفعول، لا يعبر الحاجز الدماغي). المناعي: ستيروئيدات ± آزاثيوبرين/ميكوفينولات؛ استئصال التوتة عند وجود ورم توتي."},{"f":"النوبة الوهنية (Myasthenic crisis) مقابل النوبة الكولينية — الفرق والتدبير.","b":"الوهنية: تفاقم الضعف (بلعمي/تنفسي) يحتاج تنبيبًا؛ العلاج: IVIG أو تبادل بلازما (TPE أفضل في anti-MuSK). الكولينية (نادرة، فرط مثبطات الكولين إستراز): لعاب ودمع وإسهال وبطء قلب ← أوقف/خفّض مثبط الكولين إستراز."},{"f":"متلازمة لامبرت–إيتون (LEMS) — الآلية والارتباط الورمي.","b":"أضداد ضد قنوات الكالسيوم المبوبة بالجهد قبل المشبكية (P/Q VGCC). ثلثا الحالات نظيرة ورمية: سرطان الرئة صغير الخلايا في 90% (قد تسبق الأعراض الورم)."},{"f":"التسمم الوشيقي (Botulism) — الآلية والتظاهر.","b":"ذيفان المطثية الوشيقية: بروتياز يمنع اندماج الحويصلات قبل المشبكية ← يوقف تحرر الأسيتيل كولين. شلل رخو نازل يبدأ بازدواج وأعراض بصلية خلال ساعات–أيام حتى الفشل التنفسي؛ بلا حمى. المصادر: معلبات منزلية، عسل للرضع <سنة."},{"f":"علاج التسمم الوشيقي.","b":"داعم (خاصة التنفسي) + مضاد الذيفان السباعي مبكرًا (الأفضل <48 ساعة)؛ غلوبولين مناعي للرضع. الجرثوم حساس للبنسلين/ميترونيدازول."},{"f":"أدوية تُفاقم الوهن العضلي الوبيل — احذرها.","b":"الأمينوغليكوزيدات: حصار عصبي عضلي (مضاد استطباب مطلق مع الوهن العضلي). أيضًا: حاصرات بيتا، مضادات اضطراب النظم، المغنيزيوم الوريدي."},{"f":"ورم التوتة (Thymoma) وعلاقته بالوهن العضلي.","b":"يرتبط الوهن العضلي الوبيل بأورام التوتة؛ يُطلب CT صدر عند التشخيص، واستئصال التوتة يحسن السير خاصة مع وجود الورم."}]},{"t":"أمراض الأعصاب المحيطية","cards":[{"f":"متلازمة غيّان–باريه (GBS) — الصورة السريرية والسوابق.","b":"ضعف صاعد متناظر سريع (أيام–شهر) + غياب/ضعف المنعكسات الوترية العميقة؛ قد يصل للفشل التنفسي. شلل وجهي ثنائي شائع (>50%). تسبقه عدوى (Campylobacter jejuni، EBV، CMV، مفطورة) بـ1–3 أسابيع."},{"f":"السائل الدماغي في غيّان–باريه — العلامة المميزة.","b":"انفصال ألبوميني خلوي (albuminocytologic dissociation): بروتين مرتفع مع خلايا قليلة (<10) وغلوكوز طبيعي."},{"f":"علاج غيّان–باريه الحاد.","b":"خياران متكافئان: تبادل البلازما (PLEX) أو الغلوبولين المناعي الوريدي (IVIG). الستيروئيدات غير فعالة. مراقبة وظائف تنفسية (FVC، NIF) لخطر التنبيب."},{"f":"متغيرات غيّان–باريه — ميلر فيشر وAMAN.","b":"ميلر فيشر: ثلاثية (رنح، غياب منعكسات، شلل عيني) + ضد GQ1b. AMAN: محوري حركي فقط مرتبط بـCampylobacter jejuni."},{"f":"اعتلال الأعصاب السكري — الأنماط السريرية.","b":"أشيع سبب لاعتلال الأعصاب المحيطية في الدول المتقدمة. الأنماط: متعدد الأعصاب المتناظر القاصي (الأشيع: قفاز–جورب)، ألياف صغيرة، ذاتي، ضمور عضلي سكري (diabetic amyotrophy)."},{"f":"علاج الألم العصبي (Neuropathic pain) — الخطوط العلاجية.","b":"الخط الأول: مضادات الاكتئاب ثلاثية الحلقات/مثبطات امتصاص السيروتونين-نورأدرينالين (دولوكستين)، غابابنتين، بريغابالين، ليدوكائين موضعي. الخط الثاني: غابابنتين/TCAs/SNRIs. الثالث: أفيونات."},{"f":"متلازمة النفق الرسغي (Carpal tunnel) — العصب والاختبارات.","b":"انضغاط العصب المتوسط (median) عند الرسغ: تنمل وخدر في الإبهام والسبابة والوسطى (يوقظ ليلًا)، علامة تينل وفالن. التشخيص: تخطيط الأعصاب (تباطؤ التوصيل)."},{"f":"داء شاركو–ماري–توث (CMT) — التعريف.","b":"اعتلال أعصاب وراثي (الأشيع): إنتاج معيب لبروتينات بنية الأعصاب المحيطية؛ ضعف وضمور قاصٍ تدريجي مع قدم جوفاء."},{"f":"التهاب الأعصاب المزيل للميالين الالتهابي المزمن (CIDP) — الفرق عن GBS.","b":"شبيه GBS لكن مسار مزمن مترقٍّ أو ناكس (>8 أسابيع)؛ يستجيب للستيروئيدات (بعكس GBS الحاد) إضافة لـIVIG وتبادل البلازما."},{"f":"اعتلال الجذور (Radiculopathy) مقابل اعتلال الأعصاب — مفتاح التمييز.","b":"الجذري: ألم جلدي قطاعي (dermatomal) مع ضعف في توزع عضلي جذري محدد ± نقص منعكس واحد. متعدد الأعصاب: توزع قفاز–جورب متناظر طولي."}]},{"t":"شلل العصب الوجهي","cards":[{"f":"شلل بل (Bell palsy) — التعريف والسبب الأشيع.","b":"أشيع سبب للشلل الوجهي المحيطي (LMN)؛ يتطور عادة بعد إعادة تفعيل HSV. العلاج: غلوكوكورتيكويدات ± أسيكلوفير؛ معظم المرضى يستعيدون الوظيفة تدريجيًا."},{"f":"فرّق بين شلل العصب الوجهي المركزي (UMN) والمحيطي (LMN) — إشراك الجبهة.","b":"المحيطي: يشمل عضلات الوجه العلوية والسفلية (الجبهة مصابة — لا يستطيع رفع الحاجب/إغلاق العين). المركزي: يُبقي الجبهة سليمة (تعصيب ثنائي من UMN) ويشمل السفلية فقط."},{"f":"متلازمة رامزي هانت (Ramsay Hunt) — الثلاثية.","b":"شلل وجهي بنفس الجانب + ألم أذن + حويصلات هربسية قرب القناة السمعية (إعادة تفعيل VZV في عقدة الركبة). أسوأ إنذارًا من شلل بل."},{"f":"أسباب أخرى للشلل الوجهي المحيطي — القائمة.","b":"داء لايم (قد يكون ثنائيًا)، الغرناوية (ساركوئيد)، أورام الغدة النكفية، السكري."},{"f":"مضاعفات شلل الوجه المحيطي التي يجب الوقاية منها.","b":"إغلاق غير كامل للعين ← جفاف وتقرح القرنية: حماية العين (دموع صناعية، لاصق ليلي). فرط السمع (hyperacusis) وفقدان الذوق في الثلثين الأماميين للسان قد يرافقان."},{"f":"شلل العصب الوجهي في داء لايم — ما المميز؟","b":"قد يكون ثنائي الجانب (قاعدة حفظ: «فطيرة لايم في الوجه» — شلل وجهي ثنائي)؛ يترافق مع حمامى مهاجرة وحصار أذيني بطيني في المرحلة المبكرة المنتشرة."},{"f":"التجدد الشاذ (aberrant regeneration) بعد شلل بل — مثال.","b":"قد يحدث تجدد شاذ للألياف: مثل ظاهرة «دموع التماسيح» (دمع عند الأكل) أو حركة مترافقة غير طبيعية."},{"f":"شلل بل في الحمل — معلومة وبائية.","b":"أشيع 2–4 مرات أثناء الحمل خاصة في الثلث الأخير؛ الإنذار أقل ملاءمة مقارنة بغير الحوامل."}]},{"t":"التخليط الذهني والهذيان","cards":[{"f":"تعريف الهذيان (Delirium) — السمات الأساسية.","b":"اعتلال دماغي حاد (تخليط) مع اضطراب بارز في الانتباه والوعي، غير مفسر باضطراب معرفي سابق. بدء حاد ومسار متموج (fluctuating) مع تغير عن الخط الأساسي."},{"f":"فرّق بين الهذيان والخرف (Dementia).","b":"الهذيان: بدء حاد (ساعات–أيام)، انتباه مضطرب، مسار متموج، قابل للعكس غالبًا، سببه عضوي/دوائي. الخرف: بدء تدريجي (شهور–سنوات)، انتباه سليم نسبيًا، غير قابل للعكس غالبًا."},{"f":"عوامل الخطورة للهذيان — المؤهبة والمحرضة.","b":"المؤهبة: تقدم العمر، خرف سابق، سوابق هذيان، ضعف سمع/بصر، إدمان كحول. المحرضة: أدوية (بنزوديازبينات، أفيونات، مضادات كولين)، إنتان، جراحة، تجفاف/اضطراب شوارد، قثطرة بولية، إقامة ICU."},{"f":"أدوية عالية الخطورة لإحداث الهذيان عند المسنين.","b":"البنزوديازبينات، الأفيونات، مضادات الهيستامين الجيل الأول، مضادات الكولين (أوكسيبوتينين)، حاصرات H2، الكورتيكوستيروئيدات، ومعظم الصادات تقريبًا."},{"f":"النوعان السريريان للهذيان — أيهما يُفوَّت تشخيصه؟","b":"مفرط النشاط: هياج، هلوسات، أوهام. ناقص النشاط: نقص وعي وحركة وكلام — يُفوَّت تشخيصه أكثر (يُخلط بالخرف/الاكتئاب). قد يكون مختلطًا."},{"f":"تدبير الهذيان — المبادئ.","b":"عالج السبب (إنتان، أدوية، استقلابي). تجنب البنزوديازبينات إلا في الانسحاب الكحولي/المهدئات. للهياج الشديد: هالوبيريدول 0.5–1 ملغ وريدي. تدابير غير دوائية: إضاءة نهارية، نظارات/سماعات، إزالة القثاطر، تنظيم النوم."},{"f":"اختبارات سريرية بسيطة لكشف اضطراب الانتباه في الهذيان.","b":"تسمية أشهر السنة بالعكس (الأكثر حساسية)، أيام الأسبوع بالعكس (الأكثر نوعية)، مدى الأرقام (تكرار سلسلة أرقام — الشاذ: عدم تكرار >5)."},{"f":"اعتلال دماغ فيرنيكه (Wernicke) كسبب تخليط قابل للعكس — الثلاثية والعلاج.","b":"ثلاثية: تخليط + رنح + شلل عيني (رأرأة/شلل نظر). السبب: عوز ثيامين (كحوليون، سوء تغذية). العلاج: ثيامين وريدي فورًا قبل الغلوكوز."}]},{"t":"الغشي وفقد الوعي","cards":[{"f":"الإغماء المبهمي الوعائي (Vasovagal) — المحرضات والبوادر.","b":"المحرضات: وقوف مطول، خوف/ألم، حرارة، حلاقة الرقبة، تبول/تغوط/سعال. البوادر: شحوب وتعرق وغثيان ودوار وتشوش رؤية ثم فقد وعي قصير مع استعادة سريعة (<دقيقة)."},{"f":"الإغماء القلبي — علامات الخطورة التي تستدعي تقييمًا قلبيًا عاجلًا.","b":"يحدث أثناء الجهد، بلا بوادر، قصة عائلية لموت مفاجئ، نفخات قلبية، تطاول QT بالـECG. الأخطر إنذارًا بين أنواع الإغماء."},{"f":"الإغماء الانتصابي (Orthostatic) — التعريف والأسباب.","b":"هبوط ضغط ≥20 ملم زئبق انقباضي خلال 3 دقائق من الوقوف. الأسباب: تجفاف/نزف، أدوية (مدرات، موسعات)، فشل ذاتي (سكري، باركنسون، MSA)."},{"f":"فرّق بين الإغماء والنوبة الصرعية من القصة.","b":"الإغماء: بوادر (شحوب/تعرق)، سقوط رخو، استعادة <دقيقة بلا تخليط. الصرع: هالة/صراخ، تيبس وتشنج، عض لسان جانبي، تخليط ما بعد النوبة وشلل تود."},{"f":"الإغماء الاختلاجي (Convulsive syncope) — لماذا يُخلط بالصرع؟","b":"نقص التروية الدماغية المطول قد يسبب حركات رمعية قليلة تشبه الاختلاج؛ الفارق: بوادر إغمائية واستعادة سريعة بلا طور ما بعد نوبي."},{"f":"نوبات حبس النفس عند الأطفال (Breath-holding spells) — التمييز.","b":"تحدث بعد بكاء/غضب: زرقة ثم فقد وعي قصير مع استعادة سريعة؛ حميدة وتزول مع العمر — ليست صرعًا."},{"f":"فرط الحساسية الجيبية السباتية (Carotid sinus hypersensitivity) — متى تشتبه؟","b":"إغماء عند المسنين يُثار بتدوير الرقبة أو ربطات العنق الضيقة أو الحلاقة؛ يُشخص بتدليك الجيب السباتي بحذر تحت المراقبة."},{"f":"متلازمة تسرع القلب الوضعي (POTS) — التعريف.","b":"زيادة معدل القلب ≥30 نبضة/دقيقة عند الوقوف دون هبوط ضغط انتصابي، مع أعراض (دوار، خفقان)؛ أشيع عند الشابات."},{"f":"تقييم المريض بعد فقد الوعي العابر — ما الأساسي؟","b":"القصة المفصلة (قبل/أثناء/بعد النوبة) هي مفتاح التشخيص + فحص عصبي وقلبي + ECG. معظم الاستقصاءات الإضافية توجهها القصة."},{"f":"نوبات اللاإرادية النفسية (PNES) — علامات توحي بها.","b":"حركات غير نمطية مطولة، مقاومة لفتح العين، بكاء/صراخ أثناء النوبة، سوابق نفسية؛ EEG طبيعي أثناء النوبة."}]},{"t":"عسر البلع والأعراض البصلية","cards":[{"f":"الأعراض البصلية (Bulbar symptoms) — ما هي وما أسبابها العصبية؟","b":"عسر بلع، عسر تلعثم (dysarthria)، بحة، ضعف عضلات الوجه/اللسان. الأسباب: الوهن العضلي (متذبذب)، ALS (علوي+سفلي)، سكتة جذعية، شلل بصلي كاذب، غيّان–باريه (البلع والتنفس)."},{"f":"الشلل البصلي الكاذب (Pseudobulbar palsy) — الآلية والعلامات.","b":"آفة ثنائية في السبيل القشري البصلي (فوق نووية). العلامات: منعكس فكي مفرط (brisk jaw jerk)، لability عاطفية (ضحك/بكاء لا إرادي)، عسر بلع وتلعثم تشنجي."},{"f":"الوهن العضلي كسبب لعسر البلع — ما المميز؟","b":"ضعف بلعمي متذبذب يزداد مساءً وبعد الجهد ويتحسن بالراحة؛ قد يتطور لأزمة وهنية مهددة للتنفس."},{"f":"تدبير عسر البلع الشديد عند مرضى الأعصاب — التدرج.","b":"الخفيف–المتوسط: تعديلات سلوكية (أكل بوضعية قائمة، ثني الرقبة قبل البلع، لقم صغيرة) وسوائل مثخنة + تقييم نطق وبلع. الشديد: أنبوب تغذية حسب رغبة المريض."},{"f":"مضاعفة عسر البلع الأخطر — وكيف تُكشف سريريًا؟","b":"الشفط الرئوي (aspiration pneumonia). الكشف: سعال أثناء البلع، تغير الصوت بعد البلع («مبحوح رطب»)، التهابات صدرية ناكسة؛ دراسة البلع بالفيديو (VFSS) هي الاستقصاء."},{"f":"عسر البلع في ALS — لماذا يتطلب تدخلًا مبكرًا؟","b":"يجمع ضعفًا بصليًا علويًا وسفليًا مترقيًا؛ خطر الشفط وسوء التغذية والفشل التنفسي — يُناقش أنبوب التغذية (PEG) مبكرًا قبل تدهور الوظيفة التنفسية."},{"f":"اختبار السرير لعسر البلع العصبي — ماذا تفحص؟","b":"منعكس التقيؤ (gag)، حركة الحنك، قوة اللسان، الصوت (بحة/أنفية)، السعال الإرادي، ومراقبة البلع بالماء."},{"f":"متلازمة والنبرغ (Wallenberg) الجانبية البصلية — التظاهر.","b":"احتشاء النخاع الوحشي: عسر بلع وبحة (IX/X) + متلازمة هورنر + رنح + فقد حس ألم/حرارة بنفس جهة الوجه وعكس جهة الجسم."}]}]},{"s":"الرثوية","topics":[{"t":"التظاهرات والفحص السريري","cards":[{"f":"قاعدة الفحص: حرارة الركبة مقارنة بالساق — ماذا تعني؟","b":"الركبة الطبيعية أبرد من الجلد فوق الظنبوب (بظهر اليد). إن كانت الركبة أدفأ فهناك التهاب مفصلي جارٍ."},{"f":"التهاب الجراب الزجي (Olecranon bursitis) — الصفة المميزة مقابل انصباب المرفق الحقيقي.","b":"تورم ودفء عند طرف المرفق الباسط («مرفق باباي»)؛ بسط المرفق الكامل والكب/الاستلقاء غير مؤلمين عادة — بعكس الانصباب المفصلي الحقيقي. الأسباب: رض، إنتان، نقرس، داء روماتوئيدي."},{"f":"فحص اليد في الأمراض الرثوية — ما أهميته؟","b":"فحص اليد يعطي معلومات تشخيصية واسعة: الداء الروماتوئيدي، التهاب المفاصل الصدفي، التصلب الجهازي، التهاب العضلات (علامات جلدية ظاهرة على اليد)، الذئبة، التهاب الأوعية."},{"f":"تحليل السائل الزليلي — ماذا ترسل دائمًا وماذا لا ترسل أبدًا؟","b":"أرسل: تعداد الخلايا، فحص البلورات، صبغة غرام، زرع. لا ترسل أبدًا: حمض اليوريك أو LDH. قاعدة تقدير: خلية بيضاء واحدة لكل حقل عالي القوة (40×) = 500 خلية/ميكرولتر."},{"f":"تصنيف السائل الزليلي: المجموعة 2 (التهابية) والمجموعة 3 — ماذا تعني؟","b":"المجموعة 2 (التهابية): الداء الروماتوئيدي، النقرس، النقرس الكاذب، الصدفي، الفقاري، الإنتاني، الذئبة وغيرها. المجموعة 3 (قيحية): تُفترض إنتانية حتى يثبت العكس بالزرع (قد يسببها النقرس/التفاعلي/الروماتوئيدي كالتهاب مفصل كاذب الإنتان)."},{"f":"السائل الزليلي الإنتاني مقابل البلوري — الفرق بعدلات السائل.","b":"كلاهما >90–95% عدلات (PMNs). الكريات الرغوية (ragocytes: عدلات ابتلعت معقدات مناعية) توحي بالروماتوئيدي أو الإنتاني."},{"f":"التهاب مفصل أحادي حاد — القاعدة الذهبية للتشخيص التفريقي.","b":"التهاب مفصل أحادي رضّي: بلوري (75–80%) أو إنتاني (10–15%) حتى يثبت العكس. المفصل الأحمر الساخن ليس نموذجيًا للروماتوئيدي — وجوده يستدعي البزل حتى عند مريض مشخص."},{"f":"المنهجية الشعاعية ABCDES لتفسير صورة التهاب المفاصل — اشرح باختصار.","b":"A: محاذاة (انحراف زندي MCP في الروماتوئيدي) والتحام (الفقاريات). B: تمعدن (هشاشة حول مفصلية في الروماتوئيدي) وتشكل عظمي (التهاب سمحاقي في الفقاريات، مناقير في الفصال). C: تكلسات (تكلس غضروفي في CPPD) ومسافة غضروفية (تضيق متناظر التهابي مقابل بؤري في الفصال). D: توزع (متناظر التهابي) وتشوهات (رقبة بجعة/زر قميص). E: تآكلات (هامشية في الروماتوئيدي، حافة معلقة في النقرس). S: أنسجة رخوة وأظافر."},{"f":"علامة «النورس» (Seagull sign) شعاعيًا — في أي مرض؟","b":"الفصال العظمي التآكلي (erosive OA): نمط التهابي من الفصال (10%) يصيب اليدين (DIP، PIP، CMC الأول)."},{"f":"اختبار عصر المفاصل السنعية السلامية (MCP squeeze) — ماذا يفيد؟","b":"عصر رؤوس المشاشية عند قبضة اليد يكشف إيلام الخط المفصلي؛ إحصاء المفاصل المتورمة والمؤلمة يساعد في تقييم نشاط الداء الروماتوئيدي والصدفي."},{"f":"التهاب مفاصل الكاحلين الثنائي الحاد — ما التشخيص الذي يجب تقييمه دائمًا؟","b":"الغرناوية (ساركوئيد): الحمامى العقدة (erythema nodosum) تصيب الوجه الأمامي للساقين ولا تتقرح أبدًا؛ العقيدات المتقرحة أو الخلفية توحي بالتهاب أوعية أو إنتان."},{"f":"فيبروميالغيا (Fibromyalgia) — التعريف ونقطة تمييزية.","b":"اضطراب معالجة مركزية غير التهابي وغير مناعي: ألم منتشر مزمن + أعراض مرافقة. لا تبدأ أول مرة بعد 55 سنة، ولا تُشخص مع قيم مخبرية شاذة."},{"f":"الحمى مجهولة السبب + ESR >100 وCRP >10 أضعاف — متى تفكر بالتهاب الأوعية؟","b":"بعد نفي الإنتان والخباثة: فكر بالتهاب أوعية أولي عند مريض متعدد الأجهزة بهذه القيم. التهاب الأوعية الأولي لا يترافق مع ANA/RF/انخفاض متممة إيجابية — وجودها يوجه لتشخيص آخر."}]},{"t":"أسس تدبير الاضطرابات العضلية الهيكلية","cards":[{"f":"«عالج حتى الهدف» (Treat to target) في الداء الروماتوئيدي — ما معناه؟","b":"العلاج المبكر بهدف نشاط منخفض أو هدأة؛ لا يهم أي مقياس تستخدم (CDAI، RAPID3...) المهم أن توثق به تحقيق الهدف وتعدل العلاج عليه."},{"f":"الميثوتركسات في الداء الروماتوئيدي — مكانته وقاعدة وصف البيولوجيات.","b":"الميثوتركسات هو الدواء المثبت (anchor drug) الأنجع لكل التوليفات. القاعدة: لا توصف البيولوجيات للروماتوئيدي قبل تجربة الميثوتركسات (أو DMARD تقليدي آخر). ارتفاع MCV بمقدار 5 يرتبط بفعالية جيدة."},{"f":"تكافؤ الستيروئيدات — احفظ المعادلة.","b":"هيدروكورتيزون 20 ملغ = بريدنيزون 5 ملغ = بريدنيزولون 5 ملغ = ميثيل بريدنيزولون 4 ملغ = ديكساميثازون 0.75 ملغ."},{"f":"مضادات الالتهاب غير الستيروئيدية (NSAIDs) — محاذير الاستعمال.","b":"تُستخدم بحذر (إن استُخدمت) عند مرضى الكلية أو القلب والأوعية؛ كلها قد تسبب حساسية ضوئية وقد تتداخل مع الحمل. عند مريض ذئبة بسوء وظيفة كلوية: استبعد NSAIDs المتاحة دون وصفة."},{"f":"حقن حمض الهيالورونيك داخل المفصل — متى لا تُستخدم؟","b":"لا تُستخدم في الفصال العظمي المتقدم للركبة (bone on bone). وكذلك: لا يُستخدم الغسيل بالإبرة (needle lavage) للتخفيف طويل الأمد في الفصال العرضي."},{"f":"الغلوكوزامين والكوندرويتين في فصال الركبة العرضي — هل يُوصى بهما؟","b":"لا: توصية الجمعية الأمريكية لجراحة العظام بعدم استخدامهما لعلاج فصال الركبة العرضي."},{"f":"ألم الظهر غير النوعي — متى لا تطلب رنينًا؟ وكم مدة الراحة بالسرير؟","b":"لا تطلب رنين العمود الفقري خلال أول 6 أسابيع من ألم الظهر غير النوعي. لا توصِ براحة سريرية >48 ساعة."},{"f":"الكولشيسين في النقرس — محذور دوائي مهم.","b":"تجنب الكولشيسين مع سيكلوسبورين/تاكروليموس (خطر اعتلال عضلي) ومع مضادات الفطريات الآزولية."}]},{"t":"أمراض العظام","cards":[{"f":"هشاشة العظام — تعريف التشخيص بالـDEXA وعوامل الخطر.","b":"التشخيص: T-score ≤–2.5 في أي موقع. عوامل الخطر للكسور الهشة: نقص الكتلة العظمية، تقدم العمر، كسور هشة سابقة، استخدام الستيروئيدات، الميل للسقوط (أفضل منبئ للسقوط القادم: سقوط خلال 6 أشهر)."},{"f":"علاج هشاشة العظام — الخيارات الدوائية.","b":"بيسفوسفونات (أليندرونات، ريزدرونات، زوليدرونيك وريدي)، دينوسوماب، تيريباراتيد. استبعد عوز فيتامين D عند كل مريض بنقص كتلة عظمية."},{"f":"داء باجيت العظمي (Paget) — أفضل وسيلة للتشخيص وأفضلها لمدى المرض.","b":"التشخيص: الصورة الشعاعية البسيطة هي الأفضل. تقييم مدى المرض: المسح العظمي بالطب النووي."},{"f":"اعتلال مفاصل داء ترسب الأصبغة الدموية (Hemochromatosis) — الصورة المميزة.","b":"فكر به عند رجل قوقازي <40 سنة بـ«روماتوئيدي سلبي المصل» + تغيرات تنكسية في MCP الثاني والثالث ± قصور غدد تناسلية ونقص كتلة عظمية."},{"f":"التهاب العظم والنقي (Osteomyelitis) الفقري الدموي المنشأ — الصورة الشعاعية.","b":"يبدأ قرب الصفائح الانتهائية (endplates) ثم ينتشر للقرص: تضيق مسافة القرص وتآكل الصفيحة الانتهائية — بعكس الورم الذي يحافظ على القرص."},{"f":"التهاب المفصل الإنتاني — العامل الممرض الأشيع.","b":"المكورات العنقودية الذهبية (S. aureus) هي الأشيع؛ بعد تبديل المفصل فكر بالعنقوديات السلبية التخثر (coagulase-negative) في الإنتانات البطيئة."},{"f":"التهاب المفصل بالمكورات البنية المنتشر (DGI) — الصورة المميزة.","b":"حمى + ألم مفاصل + التهاب غمد وتر (tenosynovitis)؛ يحدث غالبًا خلال أسبوع من بدء الطمث وقد تغيب الأعراض التناسلية."},{"f":"التهاب المفاصل الفيروسي الأشيع.","b":"الفيروس الصغير B19 (parvovirus) هو أشيع التهاب مفاصل فيروسي — فكر به عند حمى + طفح + التهاب مفاصل خاصة مع مخالطة أطفال."},{"f":"التهاب المفاصل السلي — معلومة شعاعية.","b":"الصورة الصدرية طبيعية في 50% من مرضى التهاب المفاصل السلي؛ صبغة العصيات الصامدة إيجابية في 20% فقط."},{"f":"داء ستيل البالغين (Adult Still's disease) — الثلاثية والداعم المخبري.","b":"حمى يومية (quotidian: تهبط للطبيعي أو دونه مرة يوميًا) + طفح + ألم مفاصل. فيريتين >1000 نانوغرام/مل يدعم التشخيص."}]},{"t":"أمراض النسيج الضام","cards":[{"f":"الذئبة الحمامية الجهازية (SLE) — النسبة بين الجنسين والقاعدة المخبرية.","b":"إناث:ذكور 9:1. القاعدة: ليس كل ANA إيجابي لديه ذئبة؛ المتممة المنخفضة (C3، C4) مع أعراض جهازية توحي بمرض معقدات مناعية (ذئبة، غلوبولينات بردية، التهاب وعائي شرّي...)."},{"f":"التهاب مفاصل الذئبة — ما نوعه؟ وما تشوهات جاكو (Jaccoud)؟","b":"التهاب مفاصل غير تآكلي؛ قد يسبب تشوهات قابلة للعكس (انحراف زندي) تُسمى التهاب مفاصل جاكو. طفح الذئبة يجنّب المفاصل ويصيب ما بينها — بعكس التهاب العضلات."},{"f":"الذئبة الدوائية (Drug-induced lupus) — الأدوية والأضداد.","b":"الأدوية: هيدرالازين، بروكائيناميد، مينوسكلين، مضادات TNF. الأضداد: anti-histone (تطور الأضداد الدوائية أشيع من تطور داء ذئبي دوائي)."},{"f":"متلازمة الذئبة الوليدية — الأضداد والخطر.","b":"أي أم لديها anti-Ro (SS-A) و/أو anti-La (SS-B) — بغض النظر عن تشخيصها — معرضة لوليد بمتلازمة ذئبة ولدية وحصار قلبي كامل."},{"f":"متلازمة الأضداد ضد الفوسفوليبيد — قاعدة «واحد من خمسة» والمرضى الأعلى خطرًا.","b":"20% من خثرات الأوردة العميقة و20% من سكتات الشباب (<50) و20% من الإسقاطات الناكسة سببها متلازمة aPL. الأعلى خطرًا للخثرات: «ثلاثيو الإيجابية» (lupus anticoagulant + anticardiolipin + anti-β2GP1)."},{"f":"متلازمة شوغرن (Sjögren) — التعريف والتشخيص.","b":"أشيع داء مناعي ذاتي عند متوسطات العمر من النساء؛ جفاف عين وفم + ANA إيجابي. الأضداد: anti-Ro/anti-La. فكر بها عند أي مريضة بأعراض غير مفسرة وANA إيجابي."},{"f":"النوبة الكلوية في التصلب الجهازي (Scleroderma renal crisis) — المنذرات والعلاج.","b":"ارتفاع ضغط جديد + هبوط صفيحات + فصيمات (schistocytes) عند مريض بتصلب منتشر — خاصة anti-RNA polymerase III إيجابي. العلاج: مثبطات ACE (أفضل من حاصرات مستقبل الأنجيوتنسين)."},{"f":"التصلب الجهازي والرئة — مؤشرا الخطر لفرط ضغط الشريان الرئوي.","b":"تراجع DLCO مع الزمن ونسبة FVC%/DLCO% >1.6 ← خطر عالٍ لفرط ضغط الرئة. تليف >20% بالـHRCT أو FVC <70% = داء خلالي «واسع» (بقيا 5 سنوات 60–65%)."},{"f":"التهاب العضلات والجلد (Dermatomyositis) — العلامات الجلدية المميزة.","b":"حطاطات غوترون (Gottron papules) على اليدين، «يدا الميكانيكي» (mechanic's hands)، طفح هيليوتروبي حول العين. التهاب العضلات عند الأطفال غالبًا التهاب جلد وعضلات لا التهاب عضلات فقط."},{"f":"التهاب العضلات والجلد والخباثة — العلاقة.","b":"ابحث عن خباثة مرافقة عند مريض التهاب العضلات والجلد (متلازمة نظيرة ورمية)."},{"f":"داء النسيج الضام المختلط (MCTD) — التظاهر المميز.","b":"ظاهرة رينو + أصابع منتفخة (puffy fingers) + داء رئوي خلالي + التهاب عضلات + قلس مريئي."},{"f":"التهاب العضلات الأولي — الفرق عن التهاب الجلد والعضلات مخبريًا.","b":"كلاهما ضعف عضلي قريب مع CK مرتفع؛ التهاب الجلد والعضلات يتميز بالعلامات الجلدية (غوترون/هيليوتروب). قصور الدرق (TSH >20 مع T4 حر منخفض) يُستبعد عند أعراض عضلية مع CK مرتفع."},{"f":"التهاب الأوعية الكريات البيض الصغيرة (Leukocytoclastic) — متى تفكر بالخباثة؟","b":"هو أشيع تظاهر التهابي وعائي نظير ورمي، خاصة في متلازمات خلل التنسج النقوي (MDS)."}]},{"t":"التهاب المفاصل مجهول السبب عند اليفعان","cards":[{"f":"التهاب المفاصل اليفعي مجهول السبب (JIA) — عوامل خطر التهاب العنبية المزمن.","b":"ANA إيجابي + جنس أنثى + عمر <6 سنوات تزيد خطر التهاب العنبية المزمن بغض النظر عن نمط JIA — يستلزم مسحًا عينيًا دوريًا."},{"f":"النمط الجهازي لـJIA (داء ستيل الجهازي عند الأطفال) — الصورة.","b":"حمى يومية + طفح سلموني + التهاب مفاصل ± التهاب مصليات؛ فيريتين مرتفع جدًا يدعم التشخيص."},{"f":"داء كاواساكي — متى تفكر به وما العلاج؟","b":"طفل <5 سنوات بحمى مرتفعة مطولة + التهاب ملتحمة. العلاج المختار: غلوبولين مناعي وريدي خلال 10 أيام من بدء المرض (للوقاية من أم الدم التاجية)."},{"f":"التهاب الأوعية الصغيرة الأشيع عند الأطفال.","b":"فرفرية هينوخ–شونلاين (HSP / IgA vasculitis): خزعة الجلد تُظهر التهاب وعائي كريات بيض صغيرة مع ترسب IgA سائد بالمناعة المباشرة."},{"f":"التهاب العضلات والجلد عند الأطفال — معلومة مميزة.","b":"التهاب العضلات عند الأطفال غالبًا التهاب جلد وعضلات (dermatomyositis) لا التهاب عضلات أولي؛ والتصلب عند الأطفال غالبًا خطي (linear scleroderma)."},{"f":"متلازمات الحمى الدورية الذاتية الالتهابية — ما يميزها عن المناعية الذاتية؟","b":"نوب حمى + طفح + التهاب مفاصل + التهاب مصليات/عين مع غياب الأضداد الذاتية وارتفاع معاوضات الطور الحاد التي تتطبع بين النوب. العلاج المختار لمعظمها: تثبيط إنترلوكين-1."},{"f":"الحمى المتوسطية العائلية (FMF) — أقصر نوب الحمى الدورية.","b":"ترتيب مدة النوب من الأطول للأقصر: TRAPS > HIDS > FMF > Muckle-Wells. العلاج: كولشيسين (يقي من الداء النشواني)."},{"f":"لا تطلب لوحة أضداد ذاتية عند طفل بدون ANA إيجابي ودليل مرض رثوي — القاعدة.","b":"من توصيات «Choosing Wisely» لطب الأطفال: لا تطلب لوحات الأضداد الذاتية دون ANA إيجابي ودليل مرض رثوي، ولا صورًا شعاعية دورية لمراقبة نشاط JIA."}]},{"t":"التهاب المفصل المحدث بالبلورات","cards":[{"f":"النقرس — الوبائيات والمفصل الأول.","b":"أشيع التهاب مفاصل التهابي عند الرجال >40 سنة؛ لا يحدث عند ما قبل سن اليأس دون داء كلوي مزمن. القدم هي أول موقع دائمًا في النوبة الأولى (التهاب إبهام القدم الحاد podagra). حمض اليوريك أقل ذوبانًا في البرد ← يصيب المفاصل القاصية الباردة ونادرًا العمود الفقري."},{"f":"بلورات النقرس مقابل النقرس الكاذب تحت المجهر المستقطب.","b":"النقرس: بلورات يورات إبرية الشكل، انكسار ثنائي سلبي، صفراء عند المحاذاة مع المعوض. النقرس الكاذب (CPPD): معينية/مستطيلة، انكسار إيجابي، زرقاء. قاعدة الحفظ ABC: محاذاة–أزرق–كالسيوم = CPPD."},{"f":"هدف خفض حمض اليوريك في النقرس.","b":"<6.0 ملغ/دل عمومًا، و<5.0 ملغ/دل في الداء التوفوسي."},{"f":"أدوية ترفع حمض اليوريك — القائمة.","b":"بيرازيناميد، الثيازيدات، فوروسيميد، نياسين، سيكلوسبورين. (لارتفاع الضغط مع النقرس: تجنب المدرات؛ يُفضل لوسارتان)."},{"f":"خافضات اليورات — متى ألوبيورينول؟","b":"مثبطات أكسيداز الزانثين (ألوبيورينول، فيبوكسوستات) لفرطي الإنتاج. متلازمة فرط الحساسية للألوبيورينول أشيع عند الآسيويين مع داء كلوي وحاملي HLA-B*58:01."},{"f":"داء ترسب بيروفوسفات الكالسيوم (CPPD/النقرس الكاذب) — الوبائيات والمفصل الأشيع.","b":"داء المسنين: يبدأ بعد 55 سنة ويزداد مع العمر؛ قبل ذلك فقط مع طفرات عائلية أو شذوذ استقلابي (ترسب أصبغة دموية، فرط جارات درق). أشيع مفصل: الركبة. شعاعيًا: تكلس الغضروف (chondrocalcinosis)."},{"f":"CPPD المقلد — أي أمراض يحاكيها؟","b":"يحاكي: الروماتوئيدي سلبي المصل، ألم العضلات الروماتزمي (PMR)، والفصال العظمي في مفاصل غير نموذجية (MCP، رسغ، كتف). فكر به عند مسن بالتهاب مفاصل سلبي المصل."},{"f":"التوفات النقرسية المزمنة — الصفة الشعاعية المميزة.","b":"تآكلات بحافة متصلبة وحافة معلقة (overhanging edge) في المفاصل الصغيرة المحيطية."},{"f":"التصوير المقطعي ثنائي الطاقة (Dual-energy CT) — ماذا يكشف؟","b":"يكشف ترسبات اليورات في النقرس لكنه لا يكشف CPPD."},{"f":"نوبة النقرس الحادة — خيارات العلاج.","b":"NSAIDs، كولشيسين (مبكرًا)، ستيروئيدات (فموية أو داخل مفصلية) — الاختيار حسب المريض وموانع الاستعمال. لا تبدأ خافض اليورات أثناء النوبة الحادة."}]},{"t":"التهابات الأوعية","cards":[{"f":"التهاب الشريان ذي الخلايا العملاقة (GCA) — العرض الأكثر نوعية والقاعدة العلاجية.","b":"أشيع التهاب أوعية عند المسنين؛ عرج الفك هو العرض الأكثر نوعية. القاعدة: لا تؤخر البريدنيزون عند الاشتباه — لن يؤثر على نتيجة خزعة الشريان الصدغي لمدة أسبوع على الأقل."},{"f":"التهاب الأوعية الكبير — ماذا تفحص إضافيًا عند الاشتباه بـGCA؟","b":"أصغِ لنفخات تحت الترقوة (قد تكون العلامة الوحيدة) وقس الضغط في الطرفين (عدم تناظر). إصابة الأوعية الكبيرة ترفع خطر تسلخ/أم دم الأبهر 17 ضعفًا."},{"f":"الورم الحبيبي مع التهاب الأوعية (GPA/فاغنر) — متى تفكر به والضد المرافق؟","b":"عند بالغ يصاب بالتهاب أذن وسطى + إصابة السبيل التنفسي العلوي والسفلي والكلى؛ الضد: anti-PR3 (c-ANCA) بنسبة 90%."},{"f":"التهاب الأوعية المجهري (MPA) — الصورة والضد.","b":"متلازمة رئوية–كلوية سريعة الترقّي؛ الضد: anti-MPO (p-ANCA)."},{"f":"التهاب الشرايين العقدي (PAN) — ما يميزه عن التهابات الأوعية الصغيرة؟","b":"التهاب أوعية متوسطة؛ يجنّب الرئتين (بعكس GPA/MPA) ويسبب التهاب أعصاب متعددة أحادي (mononeuritis multiplex)."},{"f":"فرفرية هينوخ–شونلاين (IgA vasculitis) — التشخيص النسيجي.","b":"أشيع التهاب أوعية صغيرة عند الأطفال؛ الخزعة: التهاب وعائي كريات بيض صغيرة مع ترسب IgA سائد بالمناعة المباشرة."},{"f":"التهاب الأوعية البردية المختلط (Cryoglobulinemia) — الثلاثية والسبب الأشيع.","b":"ثلاثية ميلتزر: فرفرية مجسوسة + ألم مفاصل + ضعف/ألم عضلي. أشيع سبب: التهاب الكبد C (50% لديهم غلوبولينات بردية، 5% يصابون بالتهاب وعائي)."},{"f":"التهاب الأوعية الدوائي — الأدوية المتهمة.","b":"p-ANCA: هيدرالازين، بروبيل ثيوراسيل، مينوسكلين، كوكايين (ليفاميزول). ذئبة دوائية: هيدرالازين، مينوسكلين، مضادات TNF، ريفابوتين، بروكائيناميد."},{"f":"التهاب الأوعية الأولي مقابل الثانوي — الفرق المخبري.","b":"الأولي (غير ناجم عن ذئبة أو غلوبولينات بردية): لا يترافق مع ANA/RF/متممة منخفضة أو قلة عدلات/صفيحات إيجابية — وجودها يوجه لتشخيص آخر."}]},{"t":"التهابات المفاصل الفقار سلبي المصل","cards":[{"f":"التهاب المفاصل الفقاري المحوري — العلامة الشعاعية المميزة.","b":"التهاب المفصل العجزي الحرقفي (sacroiliitis) هو العلامة الشعاعية؛ يُرى أفضل بصورة فرغسون (Ferguson) الأمامية الخلفية المعدلة للعجز."},{"f":"HLA-B27 — متى تطلبه وكم نسبة حامليه الذين يصابون؟","b":"لا تطلبه إلا عند الاشتباه بالتهاب فقاري غير متمايز مع صور شعاعية غير مشخصة. فقط 2–6% من حاملي HLA-B27 يصابون بالتهاب فقاري محوري/التهاب فقار مقسط."},{"f":"التهاب المفاصل التفاعلي (Reactive arthritis) — التعريف.","b":"التهاب مفاصل التهابي عقيم يسبقه إنتان هضمي أو بولي تناسلي بـ1–4 أسابيع. يتحسن بالمضادات المطولة فقط إذا كان السبب المتدثرة (Chlamydia)."},{"f":"التهاب المفاصل الصدفي — العلامتان الأكثر تميزًا.","b":"التهاب مفاصل DIP والتهاب الأصبع السجقي (dactylitis) مميزان جدًا للصدفي. التشخيص التفريقي لالتهاب DIP: صدفي، فصال عظمي، وغيرهما."},{"f":"التهاب الفقار المقسط (Ankylosing spondylitis) — الصورة السريرية.","b":"ألم ظهر التهابي (يتحسن بالحركة ويسوء بالراحة، تيبس صباحي >30 دقيقة) عند شاب؛ تقييد توسع الصدر؛ التهاب مفاصل عجزية حرقفية ثنائية."},{"f":"نمط التشكل العظمي التفاعلي (periostitis) شعاعيًا — لأي مجموعة؟","b":"التشكل العظمي التفاعلي (التهاب السمحاق) هو علامة التهابات المفاصل الفقارية سلبية المصل؛ بعكسه: الهشاشة حول المفصلية علامة الروماتوئيدي/الإنتان."},{"f":"التوزع المفصلي: الروماتوئيدي مقابل الفصال العظمي.","b":"التوزع المتناظر يوحي بالتهاب مفاصل التهابي (روماتوئيدي)؛ الفصال العظمي غير متناظر عادة. إصابة DIP شائعة في الفصال والصدفي معًا."},{"f":"التهاب العنبية الأمامي الناكس أحادي الجانب — علاقته بـHLA-B27.","b":"نحو 50% من مرضى التهاب العنبية الأمامي الناكس أحادي الجانب حاملي HLA-B27 لديهم أو سيصابون بالتهاب فقاري."},{"f":"التهاب المفاصل الصدفي — متى يشتبه من القصة؟","b":"التهاب قليل/متعدد مفاصل مزمن مرافق لطفح جلدي متقشر (صدفية)؛ افحص الأظافر (تنقر) وفروة الرأس."},{"f":"التهاب مفاصل الأمعاء الالتهابية — لأي مجموعة ينتمي؟","b":"ينتمي لالتهابات المفاصل الفقارية سلبية المصل (مع التهاب الفقار المقسط والتفاعلي والصدفي)؛ قد يسبق الأعراض الهضمية أو يرافقها."}]},{"t":"خمج العظم والمفصل","cards":[{"f":"التهاب المفصل الإنتاني الحاد — الخطوة التشخيصية الأولى.","b":"بزل المفصل فورًا: المفصل الأحمر الساخن يستدعي البزل حتى عند مريض مشخص بمرض رثوي. البزل آمن حتى INR 4.5، لكن عند الاشتباه بالإنتاني يُبزل مهما كان الـINR."},{"f":"السائل الزليلي الإنتاني — المواصفات.","b":"مجموعة 3 (قيحية): عدلات >90–95%؛ التشخيص الذهبي: زرع السائل. يُفترض إنتانيًا حتى يثبت العكس."},{"f":"التهاب المفصل الإنتاني — العامل الأشيع والعلاج المبدئي.","b":"الأشيع: المكورات العنقودية الذهبية. العلاج: صادّات وريدية فورية بعد أخذ مزارع الدم والسائل + تصريف المفصل؛ لا تنتظر الزرع."},{"f":"التهاب العظم والنقي الفقري — طريقة الانتشار والصورة.","b":"الانتشار الدموي يبدأ قرب الصفائح الانتهائية ثم للقرص: تضيق مسافة القرص وتآكل الصفيحة — بعكس الورم الذي يجنّب القرص."},{"f":"التهاب المفصل السلي — فخّان تشخيصيان.","b":"الصورة الصدرية طبيعية في 50%؛ صبغة العصيات الصامدة إيجابية في 20% فقط — التشخيص يحتاج زرعًا/خزعة."},{"f":"التهاب المفصل بعد تبديل مفصل صناعي — العامل المشتبه.","b":"المفصل الصناعي الملتهب: فكر بالعنقوديات سلبية التخثر (coagulase-negative) في الإنتانات البطيئة بعد الجراحة، والذهبية في الحادة."},{"f":"التهاب غمد الوتر بالمكورات البنية — متى تشتبه؟","b":"حمى + ألم مفاصل + التهاب غمد وتر (tenosynovitis) عند شاب نشط جنسيًا — قيّم للإنتان البني المنتشر (DGI)."},{"f":"التهاب المفاصل بفيروس B19 — الصورة.","b":"أشيع التهاب مفاصل فيروسي: حمى + طفح + التهاب مفاصل (خاصة عند مخالطة أطفال)؛ محدود ذاتيًا."}]},{"t":"الداء الروماتوئيدي","cards":[{"f":"الداء الروماتوئيدي — النمط المفصلي المميز.","b":"التهاب مفاصل متناظر التهابي يصيب المفاصل الصغيرة: MCP وPIP (يجنّب DIP عادة) + MTP؛ تيبس صباحي مطول. نسبة إناث:ذكور 3:1."},{"f":"العامل الروماتوئيدي (RF) وanti-CCP — الحساسية والقاعدة.","b":"متساويان في الحساسية للروماتوئيدي. القاعدة: ليس كل RF إيجابي لديه روماتوئيدي (يُستخدم لتأكيد التشخيص السريري لا لصنعه)."},{"f":"الروماتوئيدي سلبي المصل — ماذا تعيد تقييمه؟","b":"إن كان المريض سلبي المصل أو بإصابة مفاصل كبيرة فقط: أعد التقييم دومًا لنفي تشخيص آخر (خاصة CPPD). التظاهر خارج المفصلي عند سلبي المصل غالبًا ليس من الروماتوئيدي."},{"f":"عدم استقرار C1–C2 في الروماتوئيدي — التشخيص والخطر.","b":"بسبب التهاب وإضعاف الرباط المعترض: يُشخص عندما تتجاوز المسافة بين الناتئ السني وقوس الفهقة 3 ملم بصور الثني/البسط؛ >7–8 ملم تُصاب الأربطة الجناحية وخطر انضغاط النخاع. عوامل الخطر (C-SPINE): ستيروئيدات، إيجابية مصلية، تخرب مفصلي، إصابة رقبية، عقيدات، داء >10 سنوات."},{"f":"التظاهرات خارج المفصلية للروماتوئيدي — القائمة.","b":"عقيدات روماتوئيدية، التهاب صلبة/عنبية، داء رئوي خلالي، التهاب أوعية، متلازمة فيلتي (Felty: قلة عدلات + ضخامة طحال)."},{"f":"تشوهات اليد في الروماتوئيدي — الأسماء.","b":"انحراف زندي في MCP، تشوه رقبة البجعة (swan neck: فرط بسط PIP)، تشوه زر القميص (boutonnière: فرط ثني PIP)."},{"f":"الهشاشة حول المفصلية (periarticular osteopenia) شعاعيًا — لأي مرض؟","b":"نموذجية للروماتوئيدي أو الإنتان؛ نادرة في البلوريات والفقاريات والفصال العظمي."},{"f":"علاج الروماتوئيدي — التدرج.","b":"الخط الأول: ميثوتركسات (لا بيولوجيات قبله). الهدف: نشاط منخفض/هدأة (treat to target). التآكلي المقاوم: بيولوجيات (مضادات TNF وغيرها)."},{"f":"التهاب الأوعية الروماتوئيدي — متى يحدث؟","b":"مضاعفة متأخرة للداء الشديد المزمن المصلي الإيجابي: تقرحات جلدية، التهاب أعصاب متعدد أحادي، إصابة أعضاء."},{"f":"متلازمة النفق الرسغي في الروماتوئيدي — لماذا؟","b":"التهاب غمد الوتر المزمن يضغط العصب المتوسط؛ من أسباب أحاديث الأعصاب الانحشالية عند مرضى الروماتوئيدي."},{"f":"التهاب مفاصل الروماتوئيدي والرئة — الفحص الدوري.","b":"الداء الخلالي الرئوي من التظاهرات خارج المفصلية؛ راقب الأعراض التنفسية وصورة الصدر عند المرضى المزمنين."},{"f":"العقيدات الروماتوئيدية — أين تظهر؟","b":"على السطوح الباسطة (المرفق خاصة) عند مرضى مصليي الإيجابية بالداء المزمن؛ قد تظهر أيضًا في الرئة."},{"f":"الروماتوئيدي والحمل — معلومة دوائية.","b":"الميثوتركسات والليفلونوميد مضادا استطباب في الحمل (ماسخان)؛ يُوقفان قبل الحمل المخطط."},{"f":"التهاب الصلبة (Scleritis) في الروماتوئيدي — لماذا مهم؟","b":"احمرار عيني مؤلم عميق قد يهدد البصر ويعكس نشاطًا جهازيًا — يستدعي تقييمًا عاجلًا."}]},{"t":"الفصال العظمي","cards":[{"f":"الفصال العظمي — المفاصل النموذجية للإصابة الأولية.","b":"DIP (عقد هيبردن Heberden)، PIP (عقد بوشار Bouchard)، CMC الأول، الورك، الركبة، MTP الأول، العمود الرقبي والقطني العجزي."},{"f":"إصابة مفاصل غير نموذجية بالفصال (MCP، رسغ، مرفق، كتف، كاحل) — ماذا تفعل؟","b":"قيّم لأسباب ثانوية: داء CPPD، أمراض استقلابية، وغيرها."},{"f":"الفرق الشعاعي: فقد الغضروف في الفصال مقابل الالتهابي.","b":"الفصال: فقد بؤري غير منتظم في منطقة الجهد الأعظم من المفاصل الحاملة. الالتهابي: تضيق متناظر منتظم."},{"f":"فصال الركبة — معلومة وبائية مهمة للتشخيص.","b":">50% ممن تجاوزوا 65 سنة لديهم فصال ركبة شعاعي لكن 25% فقط عرضيون — لا تعتمد على الصورة وحدها لتشخيص سبب ألم الركبة."},{"f":"استطبابات تبديل مفصل الورك/الركبة الكامل.","b":"ألم يعيق المشي أو صعود الدرج أو لبس الحذاء/الجوارب رغم العلاج المحافظ — مؤشر لتبديل المفصل."},{"f":"تدبير فصال الركبة المحافظ — ما الموصى به؟","b":"إنقاص الوزن، تقوية العضلات، NSAIDs موضعية/فموية، حقن ستيروئيد داخل مفصلية عند الحاجة. لا يُوصى بالغلوكوزامين/كوندرويتين ولا بحمض الهيالورونيك في المتقدم."},{"f":"الفصال العظمي التآكلي — ما يميزه؟","b":"نمط التهابي من الفصال (10%) يصيب اليدين (DIP، PIP، CMC الأول) مع علامة «النورس» شعاعيًا؛ أكثر إعاقة من الأولي."},{"f":"التهاب الجراب المدوري (Trochanteric bursitis) المعند — ماذا تستبعد؟","b":"استبعد: تفاوت طول الساقين، إبهام أروح مع مشية شاذة (hallux rigidus)."},{"f":"التهاب اللقيمة الوحشي (Tennis elbow) — العلاج الفعال وغير الموصى به.","b":"الفعال: التمطيط اللامركزي (flex bar). تجنب حقن الستيروئيد (فائدة محدودة وخطر نوبة ما بعد الحقن)."},{"f":"الفصال العظمي مقابل الروماتوئيدي — الفروق السريرية الأساسية.","b":"الفصال: غير التهابي/ميكانيكي، ألم يزداد بالاستعمال ويتحسن بالراحة، تيبس <30 دقيقة، DIP مصابة. الروماتوئيدي: التهابي، تيبس صباحي مطول، تحسن نسبي بالحركة، MCP/PIP متناظرة."}]}]},{"s":"الطب النفسي","topics":[{"t":"البنزوديازبينات والمنومات","cards":[{"f":"البنزوديازيبينات — آلية العمل والترياق.","b":"تعزز عمل GABA على مستقبل GABA-A (تزيد تكرار فتح قناة الكلور). الترياق: فلومازينيل (flumazenil) — بحذر عند المدمنين (قد يثير نوبات)."},{"f":"انسحاب البنزوديازيبينات — الصورة.","b":"قلق، أرق، رعاش، نوبات، هذيان — قد تكون مهددة للحياة (كالكحول)؛ التنقيص التدريجي إلزامي بعد الاستعمال المطول."},{"f":"البنزوديازيبينات طويلة مقابل قصيرة المفعول — أمثلة.","b":"طويلة: ديازيبام، كلونازيبام، كلورديازيبوكسيد. قصيرة/متوسطة: لورازيبام، أوكسازيبام، تيمازيبام (آمنة في القصور الكبدي والمسنين — لا مستقلبات فعالة)."},{"f":"أدوية الـ«Z» للأرق (زولبيديم Zolpidem) — الميزة والمحذور.","b":"منومات انتقائية لمستقبل البنزوديازيبين (أقل إدمانية)؛ محذور: سلوكيات نوم معقدة (قيادة/أكل أثناء النوم)."},{"f":"علاج الأرق المزمن — الخط الأول غير الدوائي.","b":"العلاج المعرفي السلوكي للأرق (CBT-I): تقييد النوم، ضبط المنبهات، نظافة النوم — يتفوق على الأدوية طويلة الأمد."},{"f":"البوسبيرون (Buspirone) — الاستعمال والميزة.","b":"مزيل قلق (ناهض جزئي 5HT-1A) للقلق المعمم؛ لا يسبب تخديرًا أو إدمانًا لكنه بطيء المفعول (أسابيع)."},{"f":"الباربيتورات — لماذا تراجعت؟","b":"نافذة علاجية ضيقة، جرعة زائدة قاتلة (تثبيط تنفس)، إدمانية عالية — حلت محلها البنزوديازيبينات."},{"f":"التسمم الحاد بالبنزوديازيبينات — الترياق ومحذوره.","b":"فلومازينيل؛ محذور عند المدمنين المزمنين أو متناولي TCAs (يثير نوبات)."}]},{"t":"مضادات الذهان","cards":[{"f":"مضادات الذهان اللانمطية مقابل التقليدية — الفرق الدوائي.","b":"التقليدية (هالوبيريدول): حصر D2 قوي ← أعراض خارج هرمية أكثر. اللانمطية (ريسبيريدون، أولانزابين): حصر D2 + 5HT2 ← أعراض خارج هرمية أقل لكن استقلابية أكثر (وزن، سكري)."},{"f":"الكلوزابين (Clozapine) — متى يُستخدم والخطر الرئيسي؟","b":"للفصام المقاوم بعد فشل تجارب متعددة من التقليدية واللانمطية. الخطر: ندرة المحببات (agranulocytosis) — مراقبة تعداد دم دورية إلزامية؛ يُشتبه بها بحمى/التهاب حلق/تعب."},{"f":"ندرة المحببات مع مضادات الذهان — متى وأي دواءين؟","b":"تحدث عادة في أول 8–16 أسبوعًا من العلاج؛ خاصة مع كلوربرومازين وكلوزابين."},{"f":"خلل الحركة المتأخر (Tardive dyskinesia) — الدواء المُوصى به.","b":"حركات فموية-وجهية لا إرادية مزمنة من مضادات الذهان التقليدية؛ الدواء الموصى به عند حدوثها: الكلوزابين."},{"f":"الباركنسونية الدوائية — الصورة والعلاج.","b":"صلابة، سيلان لعاب، وجه قناعي، رعاش، بطء حركي. العلاج: مضادات الكولين (بنزتروبين) أو أمانتادين؛ إنقاص الجرعة/تبديل الدواء."},{"f":"عسر التوتر الحاد (Acute dystonia) — متى يحدث والعلاج.","b":"تشنجات عضلية مؤلمة (رقبة، عين للأعلى) في الساعات–الأيام الأولى من مضاد الذهان خاصة عند الشباب. العلاج: بنزتروبين/ديفينهيدرامين حقنًا."},{"f":"الأكاتيزيا مقابل القلق الذهاني — الفرق والعلاج.","b":"الأكاتيزيا: قلق حركي لا يُسيطر عليه المريض، تسوء بزيادة جرعة مضاد الذهان وتستجيب لمضادات باركنسون/لورازيبام/حاصرات بيتا؛ القلق الذهاني يتحسن بزيادة الجرعة."},{"f":"متلازمة الخباثة الدوائية (NMS) — الصورة والمميزات.","b":"فرط حرارة + صلابة عضلية + عدم استقرار ذاتي + تغيم وعي؛ 0.2% من متناولي مضادات الذهان خاصة الذكور <40 سنة؛ الهالوبيريدول أكثرها إحداثًا؛ CPK مرتفع؛ الوفيات 20%."},{"f":"مضادات الذهان والقلب — المحذور.","b":"إطالة QT (خاصة ثيوريدازين، زيبراسيدون) ← خطر تورساد؛ راقب الـECG."}]},{"t":"مضادات الاكتئاب","cards":[{"f":"SSRIs — الآثار الجانبية الشائعة.","b":"غثيان، خلل جنسي (تأخر قذف/ضعف انتصاب)، زيادة وزن، أرق/نعاس، متلازمة التوقف عند الإيقاف المفاجئ (خاصة باروكستين)."},{"f":"متلازمة السيروتونين — الثلاثية والسبب.","b":"تغير حالة عقلية + فرط نشاط ذاتي (حمى، تعرق) + فرط منعكسات/رمع عضلي (clonus) — تحدث بالجمع بين منبهات السيروتونين (SSRI + MAOI مثلًا). العلاج: إيقاف الأدوية + بنزوديازيبينات + سيبروهيبتادين."},{"f":"مضادات الاكتئاب ثلاثية الحلقات — خطر الجرعة الزائدة.","b":"الثلاثية القاتلة: اختلاجات + غيبوبة + سمية قلبية (اتساع QRS، إطالة QT، لانظميات). العلاج: NaHCO₃ للانظميات + فحم منشط + دعم."},{"f":"مثبطات MAO — التفاعل الغذائي الخطير.","b":"الجمع مع أطعمة غنية بالتيرامين (أجبان معتقة) ← نوبة ارتفاع ضغط خطيرة. تتطلب حمية صارمة وفترة غسل قبل/بعد SSRIs."},{"f":"متلازمة التوقف عن SSRIs — أي دواء أشهر؟","b":"باروكستين وفينلافاكسين (قصيرا نصف العمر): دوار، تنميل «صدمات كهربائية»، قلق، أعراض شبيهة بالإنفلونزا عند الإيقاف المفاجئ."},{"f":"علاج النهام العصابي — الدواء المُعتمد.","b":"فلوكستين (SSRI) هو مضاد الاكتئاب المعتمد للنهام + CBT. البوبروبيون مضاد استطباب (يخفض عتبة النوبات)."},{"f":"علاج الاكتئاب الكبير — الخط الأول والبدائل.","b":"الخط الأول: CBT + SSRIs. البدائل: SNRIs، ميرتازابين، بوبروبيون، ECT، كيتامين."},{"f":"سرعة القذف — العلاج الدوائي.","b":"SSRIs (باروكستين/دابوكستين) + تقنيات سلوكية (توقف–بدء، عصر)."}]},{"t":"الليثيوم ومثبتات المزاج","cards":[{"f":"الليثيوم — النافذة العلاجية والمراقبة.","b":"نافذة ضيقة: المستوى العلاجي 0.6–1.2 مEq/ل. راقب: وظيفة كلوية ودرقية ومستوى الدواء؛ الأدوية المؤثرة على التصفية (مثبطات ACE، ثيازيدات، NSAIDs) ترفع مستواه."},{"f":"تسمم الليثيوم — الأعراض والعلاج.","b":"غثيان/تقيؤ، تلعثم كلام، فرط منعكسات، رعاش خشن، رنح، نوبات، سكري كلوي المنشأ. العلاج: إيقاف الدواء + إماهة عدوانية بمحلول ملحي متساوي التوتر + غسيل كلى عند الشديد."},{"f":"الليثيوم والحمل — المحذور.","b":"ماسخ: يسبب تشوه إبشتاين القلبي (Ebstein anomaly) — تجنبه في الثلث الأول خاصة."},{"f":"الليثيوم والانتحار — معلومة وقائية.","b":"الليثيوم (والكلوزابين في الفصام) يقللان خطر الانتحار — من أسباب تفضيله في ثنائي القطب عالي الخطورة."},{"f":"حمض الفالبرويك — الاستعمالات والمحاذير.","b":"مثبت مزاج (هوس حاد، وقاية ثنائي القطب) + مضاد صرع + وقاية شقيقة. محاذير: ماسخ (عيوب أنبوب عصبي)، التهاب كبد/بنكرياس، نقص صفيحات؛ راقب وظيفة الكبد."},{"f":"كاربامازيبين — الاستعمال النفسي والمحذور.","b":"مثبت مزاج بديل (ثنائي القطب المقاوم)؛ محذور: ندرة محببات/فقر دم لاتنسجي — راقب تعداد الدم؛ ماسخ."},{"f":"لاموتريجين — الميزة في ثنائي القطب.","b":"فعال في الوقاية من نوب الاكتئاب في ثنائي القطب أكثر من الهوس؛ خطر: متلازمة ستيفنز-جونسون — زد الجرعة ببطء."},{"f":"مضادات الذهان اللانمطية كمثبتات مزاج — أمثلة.","b":"كويتيابين، أولانزابين، أريبيبرازول: فعالة في الهوس الحاد والوقاية؛ راقب الآثار الاستقلابية."}]},{"t":"الاضطرابات الاكتئابية","cards":[{"f":"الاضطراب الاكتئابي الكبير — معايير التشخيص.","b":"نوبات ≥ أسبوعين مع ≥5 من 9 أعراض تشمل المزاج الاكتئابي أو فقدان اللذة (أو التهيج عند الأطفال): نوم، اهتمام، ذنب، طاقة، تركيز، شهية/وزن، تخلف/هياج نفسي حركي، أفكار انتحارية (SIG E CAPS)."},{"f":"الاكتئاب مع سمات ذهانية — متى تحدث والعلاج؟","b":"هلوسات أو ضلالات (عادة متوافقة مع المزاج: ذنب، عقاب، عدمية) تحدث فقط في سياق النوبة الاكتئابية الكبرى. العلاج: مضاد اكتئاب + مضاد ذهان لانمطي، أو ECT."},{"f":"اضطراب الاكتئاب المستمر (خلل المزاج) — المعايير.","b":"أخف من MDD عادة؛ ≥ عرضين اكتئابيين يستمران ≥ سنتين (≥ سنة عند الأطفال) دون أن تتجاوز أي هدأة شهرين."},{"f":"الاكتئاب ذو السمات اللانمطية — الصورة.","b":"تفاعلية المزاج + زيادة شهية/وزن + فرط نوم + ثقل أطراف (leaden paralysis) + حساسية للرفض."},{"f":"الاكتئاب الموسمي — العلاج المميز.","b":"نوب اكتئابية كبرى في فصل معين (عادة الشتاء) ≥ سنتين متتاليتين. العلاج: علاجات MDD القياسية + العلاج بالضوء."},{"f":"الاكتئاب عند المسنين — لماذا يُفوَّت؟","b":"يتظاهر بشكاوى جسدية (ألم، تعب) واضطراب معرفي (خرف كاذب) أكثر من الحزن الصريح؛ يُخلط مع الخرف."},{"f":"اكتئاب ما بعد الولادة — التوقيت والعلاج.","b":"يبدأ خلال أسابيع–أشهر بعد الولادة؛ حزن شديد، صعوبة ارتباط بالرضيع، أفكار إيذاء. العلاج: SSRIs + دعم؛ الشديدة/الذهانية تستدعي دخولًا."},{"f":"العلاج بالصدمات الكهربائية — متى يُستخدم؟","b":"للاكتئاب الشديد المقاوم أو ذي السمات الذهانية أو المهدد للحياة (انتحار، رفض طعام)؛ فعال وسريع؛ آمن نسبيًا في الحمل."}]},{"t":"الاضطراب ثنائي القطب والهوس","cards":[{"f":"نوبة الهوس — معايير التشخيص.","b":"مزاج مرتفع/متوسع/سريع الانفعال مع زيادة نشاط/طاقة + ضعف وظيفي ملحوظ + ≥3 من أعراض DIG FAST لمدة ≥ أسبوع (أو أي مدة إذا استلزمت دخول المستشفى)."},{"f":"ثنائي القطب I مقابل II.","b":"النوع I: نوبة هوس واحدة (سمات ذهانية ممكنة أثناء الهوس أو الاكتئاب). النوع II: نوبة هوس خفيف واحدة + نوبة اكتئاب كبرى واحدة (الذهان ممكن أثناء الاكتئاب لا الهوس الخفيف)."},{"f":"اضطراب دوروية المزاج — المعايير.","b":"أعراض اكتئابية خفيفة وأعراض هوس خفيف تستمر ≥ سنتين مع وجود الأعراض نصف الوقت على الأقل ودون هدأة تتجاوز شهرين."},{"f":"الهوس مقابل الذهان — كيف تميز؟","b":"الهوس: مزاج مرتفع/سريع انفعال + زيادة طاقة + قلة نوم دون تعب + عظمة؛ الذهان قد يرافق لكن المزاج هو المهيمن. الفصام: أعراض ذهانية دون اضطراب مزاج مهيمن."},{"f":"علاج الهوس الحاد — الخط الأول.","b":"مثبتات المزاج (ليثيوم، فالبروات) + مضاد ذهان لانمطي؛ البنزوديازيبينات للهياج الحاد."},{"f":"مضادات الاكتئاب في ثنائي القطب — المحذور.","b":"قد تُحدث انزياحًا للهوس/تسريع الدورات — لا تُستخدم وحيدة دون مثبت مزاج."},{"f":"الدورات السريعة (Rapid cycling) — التعريف.","b":"≥4 نوب مزاجية في السنة؛ ترتبط بسوء الإنذار؛ تجنب مضادات الاكتئاب وحيدة."},{"f":"ذهان ما بعد الولادة — طوارئ.","b":"بداية حادة خلال أسبوعين من الولادة (هذيان، هلوسات، أفكار إيذاء الرضيع)؛ دخول فوري؛ خطر انتحار/قتل رضيع."}]},{"t":"الفصام والاضطرابات الذهانية","cards":[{"f":"معايير تشخيص الفصام — الأعراض والمدة.","b":"≥ عرضين نشطين (منها ≥1 من الثلاثة الأولى: ضلالات، هلوسات غالبًا سمعية، كلام غير منظم، سلوك غير منظم/كاتاتوني، أعراض سلبية)؛ بداية الأعراض ≥6 أشهر مع ≥ شهر واحد من الأعراض النشطة."},{"f":"فئات أعراض الفصام الثلاث.","b":"إيجابية (هلوسات، ضلالات)، سلبية (تبلد عاطفة، لامبالاة، فقد لذة، قلة كلام، انسحاب اجتماعي)، معرفية (ضعف فهم/تخطيط، ذاكرة عاملة، انتباه)."},{"f":"الفصام — الوبائيات والعلاج.","b":"انتشار مدى الحياة 1.5% (ذكور > إناث)؛ يظهر أبكر عند الذكور (أواخر المراهقة–أوائل العشرينات)؛ خطر انتحار مرتفع. العلاج: مضادات الذهان اللانمطية (كريسبيريدون) خط أول."},{"f":"الاضطراب الفصامي العاطفي — معيار التمييز.","b":"يجب وجود ≥ أسبوعين من الأعراض الذهانية دون نوبة هوس أو اكتئاب — بعكس اضطراب المزاج ذي السمات الذهانية التي تحدث فقط في سياق النوبة."},{"f":"الذهاني الوجيز مقابل الفصامي الشكل.","b":"الوجيز: ≥1 من الأعراض الإيجابية من يوم لشهر (مرتبط بالضغط). الفصامي الشكل: ≥2 من الأعراض 1–6 أشهر."},{"f":"اضطراب الضلال — التعريف.","b":"ضلال واحد > شهر دون اضطراب مزاج أو أعراض ذهانية أخرى؛ الأداء اليومي غير متأثر بخلاف المعتقد. قد يتشاركه أفراد بعلاقات وثيقة (folie à deux)."},{"f":"الضلالات — الأنواع.","b":"اضطهادية، عظمة، شبقية (erotomanic)، غيرة، جسدية، مختلطة؛ معتقدات خاطئة ثابتة تستمر رغم الأدلة المخالفة."},{"f":"العلاج الأسري في الفصام — دوره.","b":"تثقيف الأسرة وخفض التعبير العاطفي المرتفع (نقد/عدائية) يقلل الانتكاسات."}]},{"t":"اضطرابات القلق","cards":[{"f":"اضطراب الهلع — معايير النوبة والتشخيص.","b":"نوبات هلع متكررة تبلغ ذروتها خلال 10 دقائق مع ≥4 أعراض (خفقان، ألم صدري، ضيق تنفس، خوف من الموت/فقدان السيطرة...). التشخيص يتطلب ≥ شهر من الانشغال بنوبات إضافية أو تغير سلوكي."},{"f":"علاج اضطراب الهلع — الخط الأول.","b":"CBT + SSRIs + فينلافاكسين؛ البنزوديازيبينات أحيانًا في الوسط الحاد فقط."},{"f":"اضطراب القلق المعمم — المعايير والعلاج.","b":"قلق وهم مفرطان معظم أيام ≥6 أشهر + ≥3 أعراض للبالغين (تركيز، أرق، تهيج، توتر عضلات، تعب، اضطراب نوم — CRIMES). العلاج: CBT + SSRIs/SNRIs خط أول."},{"f":"الرهابات — المدة والعلاج.","b":"خوف/قلق شديد مستمر ≥6 أشهر من شيء أو موقف معين. العلاج: CBT مع العلاج بالتعرض."},{"f":"اضطراب القلق الاجتماعي — العلاج، وخصوصية النوع الأدائي.","b":"خوف مبالغ من الإحراج في المواقف الاجتماعية. العلاج: CBT + SSRIs/SNRIs. للنوع الأدائي: حاصرات بيتا أو بنزوديازيبين حسب الحاجة."},{"f":"رهاب الخلاء — التعريف.","b":"خوف وتجنب غير عقلاني عند مواجهة ≥2 من المواقف (نقل عام، أماكن مفتوحة/مغلقة، طوابير، وجود وحيد خارج البيت)؛ القلق من عدم توفر المساعدة أو الهرب. مرتبط باضطراب الهلع."},{"f":"رهاب الدم/الحقن — الاستجابة المميزة.","b":"استجابة وعائية مبهمة ثنائية الطور (تسرع ثم بطء قلب وإغماء) — بعكس باقي الرهابات."},{"f":"القلق المعمم عند الأطفال — عدد الأعراض.","b":"عرض واحد من CRIMES يكفي عند الأطفال (مقابل 3 للبالغين) مع قلق ≥6 أشهر."}]},{"t":"اضطراب الوسواس القهري","cards":[{"f":"الوسواس القهري — التعريف والعلاج.","b":"وساوس (أفكار تطفلية متكررة مسببة للكرب) و/أو أفعال قهرية (أفعال متكررة تخفف الكرب). مرتبط باضطرابات العرات. العلاج: CBT + SSRIs خط أول؛ كلوميبرامين وفينلافاكسين خط ثانٍ."},{"f":"العلاج بالتعرض ومنع الاستجابة — لأي اضطراب؟","b":"العلاج النفسي المختار للوسواس القهري: تعرض تدريجي للمنبه المخيف مع منع الطقوس القهرية."},{"f":"اضطراب تشوه الجسم — التعريف والعلاج.","b":"انشغال بعيوب طفيفة أو متخيلة في المظهر مع سلوكيات متكررة (فحص المرآة)؛ شائع في اضطرابات الأكل. العلاج: CBT."},{"f":"هوس نتف الشعر (Trichotillomania) — العلامة المميزة.","b":"نتف الشعر قهريًا؛ الشعر المتبقي بأطوال مختلفة (مقابل الثعلبة)؛ أشيعها فروة الرأس. العلاج: CBT + SSRIs."},{"f":"اضطراب الاكتناز (Hoarding) — التعريف.","b":"صعوبة مستمرة في التخلص من المقتنيات بسبب حاجة ملحة للاحتفاظ بها ← اكتظاظ يعيق الحياة."},{"f":"اضطراب نتف الجلد (Excoriation) — العلاج.","b":"نتف الجلد القهري المسبب لآفات؛ العلاج: CBT (تدريب عكس العادة) + SSRIs."},{"f":"OCD والشخصية الوسواسية (OCPD) — الفرق.","b":"OCD: وساوس/أفعال قهرية مؤلمة متنافرة مع الأنا. OCPD: نمط شخصية (كمالية، عناد) متوافق مع الأنا لا يعاني منه صاحبه."},{"f":"ضعف البصيرة في OCD — دلالته.","b":"ضعف البصيرة في المعتقدات/الأفعال الوسواسية مرتبط بنتائج أسوأ ويستلزم علاجًا أكثر كثافة."}]},{"t":"اضطراب الشدة ما بعد الرض","cards":[{"f":"PTSD — المعايير الأربعة والمدة.","b":"بعد حدث مهدد للحياة: فرط استثارة + تجنب + إعادة اختبار تطفلية (كوابيس، ذكريات اقتحامية) + تغيرات إدراك/مزاج — تستمر > شهر مع كرب/ضعف أداء."},{"f":"علاج PTSD — الخط الأول.","b":"CBT + SSRIs/فينلافاكسين خط أول؛ برازوسين يقلل الكوابيس."},{"f":"اضطراب الكرب الحاد — المدة والعلاج.","b":"يستمر بين 3 أيام وشهر واحد بعد الرض. العلاج: CBT؛ عادة لا يُستطب العلاج الدوائي."},{"f":"اضطراب التكيف (Adjustment) — المعايير.","b":"أعراض عاطفية/سلوكية خلال 3 أشهر من ضاغط نفسي اجتماعي محدد وتستمر <6 أشهر بعد انتهائه؛ لا تستوفي معايير مرض نفسي آخر. العلاج: CBT خط أول."},{"f":"العلاج بالتعرض المطول في PTSD — المبدأ.","b":"تعرض تدريجي متكرر لذكريات/مواقف الرض في بيئة آمنة لإطفاء الاستجابة الخوفية."},{"f":"PTSD المعقد — متى؟","b":"بعد رضوض متكررة مطولة (أسر، اعتداء مزمن): أعراض PTSD + اضطراب تنظيم عاطفة + صورة ذاتية سلبية + صعوبات علاقات."},{"f":"عوامل خطر PTSD — ما هي؟","b":"شدة الرض ومدته، رض سابق، دعم اجتماعي ضعيف، سوابق نفسية، جنس أنثى."}]},{"t":"الإدمان واضطرابات تعاطي المواد","cards":[{"f":"متلازمة انسحاب الكحول — التدرج والعلاج.","b":"ارتعاش 6–12 ساعة، نوبات انسحاب 12–48 ساعة، هذيان الارتعاش 48–96 ساعة. العلاج: بنزوديازيبينات + ثيامين."},{"f":"هذيان الارتعاش — الصورة.","b":"هلوسات بصرية + هياج + فرط نشاط ذاتي (حمى، تعرق، تسرع قلب) + تذبذب وعي؛ حالة إسعافية مهددة للحياة."},{"f":"انسحاب الأفيونات — الصورة والعلاج.","b":"شبيه بالإنفلونزا الشديدة (دمع، سيلان أنف، توسع حدقة، إسهال، ألم عضلي) — غير مهدد للحياة عادة. العلاج: ميثادون، بوبرينورفين، كلونيدين."},{"f":"التسمم بالكوكايين — الصورة والعلاج.","b":"فرط نشاط ودي: هياج، فرط حرارة، تسرع قلب، ارتفاع ضغط، توسع حدقة، ذهان. العلاج: بنزوديازيبينات؛ تجنب حاصرات بيتا."},{"f":"التسمم بالقنب — الصورة.","b":"نشوة، زيادة شهية، جفاف فم، احمرار ملتحمة، ضعف ذاكرة قصيرة الأمد؛ الاستعمال المكثف في المراهقة يرتبط بزيادة الاضطرابات الذهانية."},{"f":"الديسلفيرام — آلية العمل.","b":"يثبط ألدهيد ديهيدروجيناز ← تراكم أسيتالدهيد مع الكحول (احمرار، غثيان، خفقان) — علاج رادع للإدمان الكحولي."},{"f":"متلازمة الامتناع الوليدية — السبب.","b":"وليد أم مدمنة أفيونات: بكاء عالي النبرة، رعشة، إسهال، تقيؤ؛ تُعالج بالمورفين/ميثادون بالتنقيص التدريجي."},{"f":"علاج إدمان النيكوتين — الخيارات.","b":"بدائل النيكوتين، فارينيكلين، بوبروبيون."}]},{"t":"الطب النفسي عند الأطفال والمراهقين","cards":[{"f":"اضطراب طيف التوحد — السمات الأساسية.","b":"بداية مبكرة (<3 سنوات): ضعف تواصل اجتماعي وتفاعل، سلوكيات/اهتمامات نمطية متكررة، مقاومة التغيير."},{"f":"ADHD — العلاج الدوائي الأول.","b":"الخط الأول: المنبهات (ميثيلفينيديت، أمفيتامينات)؛ آثار جانبية: أرق، نقص شهية، تفاقم العرات."},{"f":"متلازمة توريت — التعريف والعلاج.","b":"عرات حركية وصوتية متعددة تبدأ في الطفولة وتستمر > سنة. العلاج: مضادات ذهان أو كلونيدين/غوانفاسين."},{"f":"اضطراب التحدي المعارض مقابل اضطراب السلوك.","b":"ODD: عناد وتحدٍّ للسلطة دون انتهاك حقوق الآخرين. اضطراب السلوك: انتهاك حقوق الآخرين (عدوانية، تخريب، سرقة) <18 سنة — قد يتطور لشخصية معادية للمجتمع."},{"f":"قلق الانفصال — متى يكون مرضيًا؟","b":"خوف مفرط من الانفصال عن مقدم الرعاية > شهر يعيق المدرسة/الحياة."},{"f":"الصمت الانتقائي — التعريف.","b":"رفض الكلام في مواقف اجتماعية معينة (كالمدرسة) رغم الكلام الطبيعي في البيت؛ مرتبط بقلق اجتماعي شديد."},{"f":"اضطراب خلل تنظيم المزاج التخريبي (DMDD) — السمات.","b":"نوبات غضب شديدة متكررة + مزاج سريع الانفعال مزمن بين النوبات عند الأطفال (6–18 سنة)؛ يُشخص بدل ثنائي القطب عند الأطفال."},{"f":"تقييم الطفل نفسيًا — المصادر والأدوات.","b":"معلومات من الأهل والمعلمين + ملاحظة مباشرة ولعب؛ اللعب والرسم أدوات تقييم لأن الطفل قد لا يعبر لفظيًا."},{"f":"متلازمة X الهش — السمات.","b":"أشيع سبب موروث للإعاقة الذهنية؛ وجه طويل، أذنان كبيرتان، خصيتان كبيرتان بعد البلوغ."}]},{"t":"الطب النفسي عند كبار السن","cards":[{"f":"الاكتئاب عند المسنين — لماذا يُفوَّت؟","b":"يتظاهر بشكاوى جسدية (ألم، تعب) واضطراب معرفي (خرف كاذب) أكثر من الحزن الصريح؛ يُخلط مع الخرف."},{"f":"مضادات الكولين عند المسنين — الخطر.","b":"تسبب هذيانًا واحتباس بول وإمساكًا وتدهورًا معرفيًا؛ تجنبها عند المسنين."},{"f":"الخرف الكاذب — العلاج.","b":"اكتئاب شديد يحاكي الخرف عند مسن؛ يتحسن بمضادات الاكتئاب — لا تفوّت تشخيصه."},{"f":"الذهان المتأخر عند مسن — فكر عضويًا أولًا.","b":"ذهان يبدأ بعد 60 سنة: استبعد هذيانًا، أدوية، خرف أجسام ليوي، ورمًا — قبل تشخيص فصام."},{"f":"أرق المسنين — النهج.","b":"نظافة نوم + CBT-I أولًا؛ تجنب البنزوديازيبينات (سقوط، تدهور معرفي، إدمان)."},{"f":"إيذاء المسنين — الأشكال والواجب.","b":"جسدي، نفسي، مالي، إهمال؛ المُعنِف غالبًا مقدم الرعاية؛ التبليغ واجب عند الاشتباه."},{"f":"الانتحار عند المسنين — الخصوصية.","b":"معدل إتمام أعلى (وسائل قاتلة، عزلة)؛ الرجال المسنون الأرامل الأعلى خطرًا."},{"f":"خرف أجسام ليوي — ما يميزه؟","b":"هلوسات بصرية مبكرة + باركنسونية + تذبذب معرفي + حساسية شديدة لمضادات الذهان."}]},{"t":"اضطرابات الأكل","cards":[{"f":"فقد الشهية العصابي — المعايير والعلامات.","b":"تقييد طعام + خوف شديد من زيادة الوزن + اضطراب صورة الجسم + BMI منخفض جدًا. علامات: لانوغو، انقطاع طمث، بطء قلب، هشاشة عظام. أعلى وفيات بين الاضطرابات النفسية."},{"f":"النهام العصابي — الصورة والمضاعفات.","b":"نوبات شره + سلوكيات تعويضية (تقيؤ، مسهلات) مع وزن طبيعي غالبًا. المضاعفات: نقص بوتاسيوم، تآكل ميناء الأسنان، تضخم غدد نكفية، علامة راسل."},{"f":"اضطراب الشره مقابل النهام — الفرق.","b":"نوبات شره دون سلوكيات تعويضية منتظمة ← سمنة؛ بعكس النهام الذي يحافظ على وزن طبيعي بالتعويض."},{"f":"نقص البوتاسيوم في النهام — لماذا؟ والخطر.","b":"التقيؤ المتكرر ← قلاء استقلابي + نقص K ← ضعف عضلي ولانظميات قلبية (أخطر المضاعفات)."},{"f":"متلازمة إعادة التغذية — المحذور.","b":"هبوط فوسفور/بوتاسيوم/مغنيزيوم مع بدء التغذية في فقد الشهية الشديد ← لانظميات؛ ابدأ ببطء مع مراقبة الشوارد."},{"f":"اضطراب تجنب/تقييد تناول الطعام (ARFID) — الفرق عن فقد الشهية.","b":"تقييد طعام دون خوف من زيادة الوزن أو اضطراب صورة جسم (نفور حسي أو خوف من الاختناق)."},{"f":"الوحم (Pica) — التعريف.","b":"أكل مواد غير غذائية (تراب، طباشير) ≥ شهر؛ مرتبط بعوز الحديد والحوامل والأطفال."},{"f":"اضطراب تشوه الجسم وعلاقته باضطرابات الأكل.","b":"الانشغال بعيوب المظهر شائع في اضطرابات الأكل؛ العلاج: CBT."}]},{"t":"اضطرابات النوم","cards":[{"f":"الخدار — الرباعية والسبب.","b":"نوبات نوم نهارية + جمود (فقدان مقوية مفاجئ مع الضحك) + هلوسات نومية + شلل نوم. السبب: نقص هيبوكريتين الوطائي."},{"f":"علاج الخدار — الدوائان.","b":"نوبات النوم: منبهات (مودافينيل خط أول). الجمود: مضادات اكتئاب أو أوكسيبات الصوديوم ليلًا."},{"f":"انقطاع النفس الانسدادي النومي — الصورة والعلاج.","b":"شخير عالٍ + توقفات تنفس + نعاس نهاري عند بدين/رقبة قصيرة. العلاج: CPAP هو الذهبي؛ إنقاص الوزن؛ تجنب المهدئات."},{"f":"الكوابيس مقابل الرعب الليلي — الفرق.","b":"الكوابيس: نوم REM، استيقاظ كامل مع تذكر الحلم. الرعب الليلي: نوم عميق NREM، صراخ وهياج دون استيقاظ كامل ولا تذكر — عند الأطفال غالبًا."},{"f":"المشي أثناء النوم — النصيحة الأهم.","b":"يحدث في النوم العميق NREM عند الأطفال؛ أمّن البيئة ولا توقظه بعنف — أعده للسرير بهدوء."},{"f":"متلازمة تململ الساقين — العلاج.","b":"رغبة ملحة بتحريك الساقين مساءً تتحسن بالحركة؛ مرتبطة بعوز الحديد. العلاج: ناهضات الدوبامين + تعويض الحديد."},{"f":"اضطراب طور النوم المتأخر — الفئة والعلاج.","b":"نوم واستيقاظ متأخران (بومة ليلية) عند المراهقين غالبًا. العلاج: علاج ضوئي صباحي + ميلاتونين مسائي."},{"f":"البرازوسين (Prazosin) — استعماله في النوم.","b":"يقلل الكوابيس في PTSD (حاصر ألفا)."}]},{"t":"الانتحار","cards":[{"f":"عوامل خطر الانتحار — القائمة.","b":"ذكر، مسن، أعزب/مطلق، محاولة سابقة، اضطراب نفسي (اكتئاب، ثنائي قطب، فصام)، تعاطي مواد، مرض مزمن/ألم، فقد حديث، وصول لوسيلة قاتلة."},{"f":"السؤال عن الانتحار — القاعدة.","b":"اسأل مباشرة وبصراحة عن الأفكار والخطط والوسائل؛ السؤال لا «يزرع» الفكرة. قيّم: فكرة/خطة/نية/وسيلة/محاولة سابقة."},{"f":"المريض الانتحاري في الإسعاف — الإجراء.","b":"لا تتركه وحيدًا؛ أزل الوسائل؛ دخول طوعي/قسري حسب الخطورة."},{"f":"الأدوية المقللة لخطر الانتحار.","b":"الليثيوم في ثنائي القطب والكلوزابين في الفصام يقللان خطر الانتحار."},{"f":"الانتحار عند المراهقين — علامات الخطر.","b":"انسحاب، توزيع مقتنيات، كتابات وداعية، تعاطي مواد، تنمر؛ اسأل مباشرة عن الأفكار الانتحارية."},{"f":"الجرعة الزائدة من الباراسيتامول — لماذا خطيرة؟","b":"قصور كبدي حاد متأخر بعد تحسن مبدئي؛ الترياق: N-أسيتيل سيستئين خلال 8 ساعات."},{"f":"اضطراب الهلع وخطر الانتحار — العلاقة.","b":"اضطراب الهلع يحمل مكونًا وراثيًا قويًا وزيادة في خطر الانتحار — قيّم دائمًا."}]},{"t":"الحداد وارتكاسات الفقد","cards":[{"f":"الحزن الطبيعي — السمات.","b":"شعور طبيعي بعد وفاة عزيز؛ يختلف المسار بين الأفراد ولا يتبع مراحل ثابتة؛ قد يشمل أعراضًا جسدية وهلوسات بالمتوفى وتمني الموت معه عابرًا؛ التكيف عادة خلال 6 أشهر."},{"f":"اضطراب الحزن المطول — المعايير.","b":"يُشخص إذا بقي الحزن شديدًا ومستمرًا ≥6–12 شهرًا مع ضعف وظيفي ملحوظ وغير متسق مع المعايير الثقافية/الدينية، ولم يستوفِ معايير اضطراب آخر كالاكتئاب الكبير."},{"f":"الحزن مقابل الاكتئاب الكبير — الفروق.","b":"الحزن: موجات مرتبطة بالفقد، احترام الذات محفوظ، يتحسن مع الوقت. الاكتئاب: مزاج منخفض مستمر، شعور بالذنب/عدم قيمة، أفكار انتحارية، ضعف وظيفي شامل."},{"f":"كآبة النفاس مقابل اكتئاب ما بعد الولادة.","b":"كآبة النفاس: تقلب مزاج خفيف في أول أسبوعين يزول تلقائيًا. الاكتئاب: أشد وأطول ويعيق الأداء ويحتاج علاجًا."},{"f":"ارتكاس الفقد عند الأطفال — كيف يظهر؟","b":"قد يظهر بتراجع سلوكي (تبول لاإرادي)، شكاوى جسدية، غضب، صعوبة مدرسية — لا يعبر لفظيًا كالبالغ."},{"f":"الدعم في الحداد الطبيعي — ما المطلوب؟","b":"تطبيع المشاعر، تشجيع التعبير، دعم اجتماعي؛ لا أدوية routinely — التدخل الدوائي للحزن المطول أو الاكتئاب المرافق فقط."},{"f":"الفقد المفاجئ العنيف — الخصوصية.","b":"الوفاة المفاجئة/العنيفة ترفع خطر PTSD والحزن المطول — راقب وتدخل مبكرًا."}]},{"t":"التمييز بين الأمراض النفسية والعضوية","cards":[{"f":"الهذيان — السمات والسبب.","b":"بداية حادة + وعي «شمعي متذبذب» + نقص انتباه + هلوسات بصرية + اضطراب نوم/يقظة؛ قابل للعكس؛ أشيع سبب لتغير الحالة العقلية في المشفى/ICU. العلاج: تدبير السبب الكامن."},{"f":"الهذيان مقابل الخرف — الفروق.","b":"الهذيان: حاد، متذبذب، اضطراب انتباه ووعي، قابل للعكس. الخرف: مزمن متدرج، اضطراب ذاكرة مع وعي سليم، غير قابل للعكس غالبًا."},{"f":"أسباب عضوية للاكتئاب — القائمة.","b":"قصور درق، كوشينغ، ذئبة، عوز B12، باركنسون وأدويته، ستيروئيدات، أورام — استبعدها قبل تشخيص اكتئاب أولي."},{"f":"أسباب عضوية للقلق — القائمة.","b":"فرط درق، ورم القواتم (pheochromocytoma)، نقص سكر، ربو/COPD، كافيين/منبهات، انسحاب كحول — استبعدها في قلق جديد."},{"f":"أسباب عضوية للهوس — القائمة.","b":"ستيروئيدات، فرط درق، أورام دماغية (جبهية)، ذئبة، منبهات — هوس يبدأ بعد 40 سنة أو بلا سوابق يستدعي بحثًا عضويًا."},{"f":"الذهان بعضوي المنشأ — متى تشتبه؟","b":"بداية بعد 40 سنة، هلوسات بصرية/شمية بارزة، علامات عصبية بؤرية، تذبذب وعي — فكر بهذيان، صرع صدغي، ورم، داء ويلسون عند الشباب."},{"f":"داء ويلسون — التظاهر النفسي.","b":"مرض تراكم النحاس قد يبدأ بأعراض نفسية (تغير شخصية، اكتئاب، ذهان) عند شاب + علامات خارج هرمية وحلقة كايزر-فلايشر."},{"f":"التهاب الدماغ بمضادات NMDA — الصورة النفسية.","b":"شابة بذهان حاد + حركات لا إرادية + خلل ذاتي + نوبات — قد يُخلط بالفصام؛ ابحث عن ورم مبيضي (مسخي)."}]},{"t":"الإسعاف النفسي ونوبات العنف","cards":[{"f":"الهياج الحاد — التدبير الدوائي.","b":"هالوبيريدول + لورازيبام عضليًا؛ أو أولانزابين/أريبيبرازول عضليًا. تجنب القيود الفيزيائية إلا للضرورة القصوى وبمراقبة."},{"f":"تقييم خطر العنف — ماذا تسأل؟","b":"أفكار قتل للآخرين (خطة/نية/وسيلة)، سوابق عنف، تعاطي مواد، أوامر هلوسية، ضعف استبصار، وصول لسلاح."},{"f":"متلازمة الخباثة الدوائية كطوارئ — العلاج الفوري.","b":"إيقاف مضاد الذهان + دعم (تبريد، سوائل) + دانترولين/بروموكريبتين؛ الوفيات 20% دون علاج سريع."},{"f":"ذهان ما بعد الولادة — طوارئ.","b":"بداية حادة خلال أسبوعين (هذيان، هلوسات، أفكار إيذاء الرضيع)؛ دخول فوري."},{"f":"الانسحاب الكحولي الشديد — طوارئ.","b":"هذيان الارتعاش ونوبات الانسحاب مهددة للحياة؛ بنزوديازيبينات + ثيامين فورًا."},{"f":"الدخول القسري — الشروط.","b":"مرض نفسي + خطر على النفس/الآخرين أو عجز شديد عن رعاية الذات + رفض العلاج الطوعي — بقرار طبي/قضائي."},{"f":"السرية — متى تُكسر؟","b":"عند خطر وشيك على المريض أو الآخرين، إيذاء طفل/مسن، أمر قضائي — مع إعلام المريض قدر الإمكان."}]},{"t":"مواضيع متفرقة","cards":[{"f":"الفحص العقلي (MSE) — المكونات.","b":"المظهر والسلوك، الكلام، المزاج والعاطفة، التفكير (محتوى/مسار)، الإدراك (هلوسات)، المعرفة (توجه، ذاكرة)، الاستبصار والحكم."},{"f":"مقياس MMSE — العتبة.","b":"من 30؛ <24 يوحي باضطراب معرفي (مع مراعاة التعليم والعمر)."},{"f":"آليات الدفاع الناضجة — أمثلة وحيلة التذكير.","b":"SASH: تسامي (Sublimation)، إيثار (Altruism)، قمع (Suppression)، فكاهة (Humor)."},{"f":"الإسقاط مقابل الإزاحة.","b":"الإسقاط: نسبة مشاعرك غير المقبولة للآخرين. الإزاحة: نقل المشاعر لهدف أقل تهديدًا."},{"f":"العلاج السلوكي الجدلي (DBT) — لمن؟","b":"العلاج النفسي المختار للشخصية الحدية."},{"f":"اضطراب التحويل — العلامة المميزة.","b":"أعراض عصبية وظيفية بعد ضاغط؛ العلامة: «لا مبالاة جميلة» (la belle indifférence)."},{"f":"المفتعل مقابل التمارض.","b":"المفتعل: يختلق الأعراض لدور المريض دون مكسب خارجي. التمارض: لمكسب خارجي واضح."},{"f":"اضطراب الهوية الانفصامي — السمات.","b":"≥ هويتين متميزتين؛ أشيع عند الإناث؛ مرتبط بسوابق اعتداء جنسي وPTSD والاكتئاب."},{"f":"الأدوية النفسية والحمل — القاعدة.","b":"تجنب قدر الإمكان في الثلث الأول؛ الليثيوم (إبشتاين)، الفالبروات (عيوب أنبوب عصبي)، البنزوديازيبينات عالية الخطر."}]}]},{"s":"الجلدية","topics":[{"t":"الصداف","cards":[{"f":"لويحات حمامية (Erythematous plaques) مغطاة بقشور فضية (Silvery scales) على السطوح الباسطة (المرفقين والركبتين) — التشخيص؟","b":"الصداف اللويحي (Psoriasis vulgaris) — أشيع أنماط الصداف؛ يصيب ~2% ويبلغ ذروتي بدء بعمر 16–22 و57–60 سنة."},{"f":"طفح نقطي (Guttate) مفاجئ بشكل قطرات المطر بعد التهاب بلعوم/لوزتين بالعقديات الحالة للدم بيتا عند مراهق؟","b":"الصداف النقطي (Guttate psoriasis) — يظهر بعد 2–3 أسابيع من الخمج، يشفى عادة خلال 3–4 أشهر وقد يتكرر بعد خموج عقدية لاحقة."},{"f":"ظاهرة كوبنر (Koebner phenomenon) في الصداف؟","b":"ظهور آفات صدافية جديدة في مواضع الرض الجلدي (خدوش، ندبات جراحية)."},{"f":"إصابة الأظافر في الصداف (50% من المرضى)؟","b":"تنقّر الأظافر (Pitting)، بقع زيتية (Oil spots)، فرط تقرّن تحت الظفر؛ قد تكون العلامة الوحيدة للصداف. مقياس الشدة: NAPSI."},{"f":"الصداف البثري المعمم (von Zumbusch): بثور عقيمة منتشرة مفاجئة + حمى وتوعك + جلد مؤلم؟","b":"الصداف البثري المعمم (Generalized pustular psoriasis) — السيتوكين المركزي IL-36؛ يرتفع فيه HLA-B27."},{"f":"النمط الأشيع لالتهاب المفاصل الصدافي (Psoriatic arthritis)؟","b":"التهاب مفاصل قليل غير متناظر (Asymmetric oligoarthritis) بنسبة 70% + التهاب مرتكزات الأوتار (Enthesitis) + إصبع سجقي (Dactylitis) + سلبية العامل الرثياني (Seronegative)."},{"f":"أقوى ارتباط HLA بالصداف الباكر البدء؟","b":"HLA-Cw6 (البدء المبكر)؛ وHLA-B27 لالتهاب المفاصل الصدافي؛ B13/B17 للصداف النقطي."},{"f":"أدوية تُفاقم الصداف؟","b":"الليثيوم، حاصرات بيتا، مضادات الملاريا، مثبطات ACE، مضادات الالتهاب غير الستيروئيدية، وسحب الستيروئيدات الجهازية."},{"f":"العلاج الموضعي الأول للصداف المحدود؟","b":"ستيروئيدات موضعية قوية + نظائر فيتامين D3 (Calcipotriol)؛ والعلاج الضوئي NBUVB/PUVA للمنتشر."},{"f":"العلاجات البيولوجية للصداف المتوسط–الشديد؟","b":"مثبطات TNF-α، مثبطات IL-17 (كـ Secukinumab)، مثبطات IL-23 (كـ Guselkumab)، ومثبط IL-12/23 (Ustekinumab)."},{"f":"أمراض مرافقة للصداف يجب تذكرها؟","b":"المتلازمة الاستقلابية والمرض القلبي الوعائي، التهاب المفاصل الصدافي، داء كرون، القلق والاكتئاب."},{"f":"مقياسا شدة الصداف الجلدي والظفري؟","b":"PASI (شدة ومساحة الصداف) للجلد، وNAPSI للأظافر."}]},{"t":"الحزاز المسطح","cards":[{"f":"حطاطات بنفسجية (Violaceous) مسطحة القمة لامعة متعددة الأضلاع حاكّة على الجهة المثنية للرسغ؟","b":"الحزاز المسطح (Lichen planus) — تُرى على سطح الحطاطات خطوط ويكهام (Wickham striae) البيضاء الشبكية."},{"f":"خطوط ويكهام (Wickham striae) أين تُرى؟","b":"خطوط بيضاء شبكية على سطح حطاطات الحزاز المسطح، وعلى مخاطية الخد لا تُكشط (بعكس المبيضات الفموية)."},{"f":"الصورة النسيجية المميزة للحزاز المسطح؟","b":"ارتشاح لمفاوي شريطي (Band-like lichenoid infiltrate) يعانق الطبقة القاعدية للبشرة + موت مبرمج للخلايا الكيراتينية القاعدية."},{"f":"إصابة الأظافر في الحزاز المسطح؟","b":"تثلّم طولي (Longitudinal ridging)، ضمور الصفيحة الظفرية، تندّب لا رجعة فيه مع ظفرة (Pterygium) وفقدان الأظافر."},{"f":"الحزاز المسطح الضخامي (Hypertrophic LP) أين يتوضع؟","b":"عقيدات حاكّة مفرطة التقرّن بنفسجية على الساقين (الشظية) تشبه الحزاز البسيط المزمن."},{"f":"علاج الحزاز المسطح الجلدي؟","b":"المرض محدود ذاتيًا غالبًا؛ ستيروئيد موضعي قوي/قوي جدًا مرة يوميًا، وتاكروليموس موضعي 0.1% عند عدم الاستجابة، ومضاد هستامين مهدئ للحكة الليلية."},{"f":"الحزاز المسطح الشعري (Lichen planopilaris) ماذا يسبب؟","b":"التهاب حول الجريبات الشعرية مع تخريبها → حاصة ندبية (Scarring alopecia)."}]},{"t":"النخاليات","cards":[{"f":"لطخة منذرة (Herald patch) على الجذع تليها حطاطات وردية بيضوية بقشور ناعمة بتوزع «شجرة عيد الميلاد» على الظهر؟","b":"النخالية الوردية (Pityriasis rosea) — محدودة ذاتيًا تشفى خلال ~8 أسابيع؛ تُعزى لخمج فيروسي (ربما HHV-6/7)."},{"f":"كيف تفرّق النخالية الوردية عن الصداف النقطي والزهري الثانوي؟","b":"الصداف النقطي: قشور فضية أثخن ولا يتبع نمط شجرة عيد الميلاد + قصة التهاب حلق؛ الزهري الثانوي: لطخات نحاسية على الراحتين والأخمصين + ضخامة عقد لمفية."},{"f":"النخالية المبرقشة (Pityriasis versicolor) — العامل والمظهر؟","b":"خمائر المالاسيزية (Malassezia / Pityrosporum)؛ لطخات بنية محمرة أو ناقصة الصباغ متفاوتة الحجم مع غبار من القشور الناعمة على الجذع."},{"f":"فحصا تأكيد النخالية المبرقشة؟","b":"ضوء وود (Wood's light): تألق أصفر للجلد المصاب؛ والكشطات المجهرية: خيوط وأبواغ («سباغيتي وكرات لحم»)."},{"f":"علاج النخالية المبرقشة وماذا تخبر المريض؟","b":"مضاد فطري؛ النكس شائع؛ يبقى الشحوب ظاهرًا حتى يتعرض الجلد للشمس ويتساوى اللون."},{"f":"عوامل خطر النخالية المبرقشة؟","b":"المناخ الحار الرطب، فرط التعرق، الستيروئيدات الموضعية والجهازية، كبت المناعة، متلازمة كوشينغ، سوء التغذية."},{"f":"تدبير النخالية الوردية؟","b":"طمأنة المريض وانتظار الشفاء التلقائي؛ وراجع القصة الدوائية لاستبعاد طفح دوائي شبيه بالنخالية الوردية."},{"f":"التهاب الجريبات بالمالاسيزية (Malassezia folliculitis) أين يُرى؟","b":"التهاب جريبات جذعي تسببه خمائر المالاسيزية عند مرضى التهاب الجلد الدهني."}]},{"t":"العد الشائع (حب الشباب)","cards":[{"f":"الفرق بين الزؤان المفتوح والمغلق؟","b":"الزؤان المفتوح = زؤان أسود (Blackhead)، والزؤان المغلق = زؤان أبيض (Whitehead) — آفتا العد الشائع الأوليتان."},{"f":"علاج العد الشائع المتوسط الشدة؟","b":"صادات فموية 4 أشهر (تتراسيكلين/ليميسيكلين/إريثروميسين) + بنزويل بيروكسيد موضعي لتقليل المقاومة الجرثومية."},{"f":"إيزوتريتينوين (Isotretinoin) — متى والجرعة وأهم تحذير؟","b":"للعد الشديد/الكيسي؛ الجرعة 0.5–1 ملغ/كغ/يوم بجرعة تراكمية 120–150 ملغ/كغ؛ ماسخ (Teratogenic) — منع حمل إلزامي أثناء العلاج وبعده بشهر."},{"f":"أدوية تسبب أو تفاقم العد الشائع؟","b":"الستيروئيدات (حتى المستنشقة)، الليثيوم، البروجستينات، فيتامين B12، الستيروئيدات البنائية، الأيزونيازيد."},{"f":"عقيدات مؤلمة وجيوب وندب في الإبط والمغبن؟","b":"التهاب الغدد العرقية القيحي (Hidradenitis suppurativa): عقيدات مؤلمة تحت الجلد وندب وجيوب في الإبط والمغبن؛ العلاج: إيقاف التدخين، كلينداميسين موضعي 1% للخفيف، تتراسيكلين فموي مطوّل."},{"f":"العد المكيّس الشديد المقاوم؟","b":"العد المتكتل (Acne conglobata): زؤانات متجمعة؛ الاستجابة للعلاجات القياسية مخيبة؛ الإيزوتريتينوين يستحق التجربة."},{"f":"ماذا تخبر مريض العد عن زمن الاستجابة؟","b":"كل علاجات العد تحتاج 3–4 أشهر للأثر الأعظمي، وقد يسوء العد قليلًا قبل أن يتحسن."},{"f":"طفح حطاطي بثري على الوجه بلا زؤانات عند مستخدم ستيروئيد؟","b":"طفح شبيه بالعد بلا زؤانات قد يحدث بالستيروئيدات الجهازية أو الموضعية القوية على الوجه (التهاب الجلد حول الفم)."}]},{"t":"العد الوردي","cards":[{"f":"الفرق السريري الأهم بين العد الوردي والعد الشائع؟","b":"العد الوردي بلا زؤانات (No comedones)؛ يصيب الوجه المركزي ويوفّر الجذع بعكس العد الشائع."},{"f":"الأنف البصلي (Rhinophyma) ما هو؟","b":"تضخم الغدد الدهنية وفرط نمو الأنسجة الرخوة في الأنف — من النمط الضخامي (Phymatous) للعد الوردي."},{"f":"العد الوردي العيني (Ocular rosacea)؟","b":"التهاب ملتحمة، التهاب أجفان، بردة (Chalazion)، شعيرة (Hordeolum)؛ الأعراض: حرقة وحكة واحمرار وإحساس رملي."},{"f":"علاج العد الوردي الحطاطي البثري الخفيف؟","b":"ميترونيدازول 0.75% أو حمض الأزيليك 15% مرتين يوميًا لـ3–4 أشهر؛ كريم إيفرمكتين 1% قد يكون أفعل من الميترونيدازول."},{"f":"علاج الاحمرار في العد الوردي؟","b":"جل بريمونيدين (Brimonidine) مرة يوميًا يخفف الاحمرار (خطر ارتداد)؛ والليزر أو التمويه التجميلي للاحمرار الثابت."},{"f":"مهيجات العد الوردي؟","b":"الكحول، الأطعمة الحارة، تغير الحرارة المفاجئ، المشروبات الساخنة، الشمس، موسعات الأوعية المحيطية."},{"f":"دور الصادات الفموية في العد الوردي؟","b":"صادات فموية 4 أشهر (تتراسيكلين/ليميسيكلين/إريثروميسين) تضبط البثور لكن أثرها ضعيف على الاحمرار."}]},{"t":"الأكزيما والتهاب الجلد","cards":[{"f":"الأكزيما التأتبية (Atopic eczema) — الجين الأهم في إمراضيتها؟","b":"طفرات فقدان الوظيفة في جين الفيلاغرين (Filaggrin) — بروتين الحاجز البشري؛ مع قصة عائلية للتأتب."},{"f":"الثالوث التأتبي (Atopic triad)؟","b":"أكزيما تأتبية + ربو + التهاب أنف تحسسي (حمى القش)."},{"f":"مقاييس شدة الأكزيما التأتبية؟","b":"EASI وSCORAD للمراقبة الموضوعية للاستجابة، وPOEM لرأي المريض."},{"f":"أكزيما نازّة متقشرة + حويصلات مجتمعة مؤلمة وتآكلات محددة؟","b":"الإكزيما الهربسية (Eczema herpeticum) — خمج بالحلأ البسيط فوق الأكزيما؛ طارئ طبي."},{"f":"التهاب الجلد التماسي التحسسي — أشيع مسبب وكيف تشخصه؟","b":"النيكل (مجوهرات) أشيع مسبب؛ التشخيص باختبار الرقعة (Patch test)."},{"f":"التهاب الجلد الدهني (Seborrhoeic dermatitis) — التوزع؟","b":"فروة الرأس (قشرة/نخالية)، الحاجبين، ثنايا الأنف الشفوية، مركز الصدر — حمامى دهنية المظهر قليلة الحكة."},{"f":"المهيج مقابل التحسسي في التهاب الجلد التماسي؟","b":"التهاب الجلد التماسي المهيج أشيع بكثير من التحسسي خاصة عند الأطفال."},{"f":"أساس علاج الأكزيما؟","b":"المرطبات (Emollients) أساس العلاج + ستيروئيدات موضعية + تجنب المهيجات والصوابين."}]},{"t":"الشرى","cards":[{"f":"الشرى (Urticaria) — الآلية والآفة المميزة؟","b":"تفاعل فرط تحسس فوري نمط I؛ انتبار (Wheals) حاكّة مرتفعة ملساء حمامية من وذمة أدمية، تزول خلال 24 ساعة تاركة جلدًا طبيعيًا."},{"f":"الشرى الحاد مقابل المزمن — المحرضات؟","b":"الحاد: أدوية (بنسلين) أو أطعمة (فول سوداني، سمك) والمريض يحدد المحرض غالبًا؛ المزمن: يصعب تحديد المحرض."},{"f":"الوذمة الوعائية (Angioedema) — كيف تختلف عن الشرى؟","b":"وذمة الأدمة العميقة والنسيج تحت الجلد والمخاطيات؛ تورمات كبيرة مفاجئة؛ قد تكون بعوز مثبط C1 إستراز (وهؤلاء بلا شرى)."},{"f":"أمثلة على الشرى الفيزيائي (Inducible urticaria)؟","b":"الجلدية الخطية (Dermographism) بالضغط، الشرى البارد، الشمسي، الكوليني (بالحرارة/الجهد/القلق)."},{"f":"علاج الشرى الأساسي؟","b":"مضادات الهستامين غير المهدئة هي الدعامة الأساسية للعلاج."},{"f":"الشرى المزمن التلقائي — السبب المناعي؟","b":"30% من الشرى المزمن التلقائي سببها مناعي ذاتي (أضداد محررة للهستامين)؛ قد يترافق مع مناعة درقية ذاتية."},{"f":"مقياس متابعة الشرى؟","b":"مقياس فعالية الشرى (UAS) — يُجمع على 4–7 أيام بسبب التباين اليومي."},{"f":"التأق (Anaphylaxis) — العلاج الأول؟","b":"أدرينالين (إبينفرين) 0.5 ملغ عضلي فورًا ضمن مقاربة ABCDE."}]},{"t":"الأمراض المناعية الفقاعية","cards":[{"f":"الفرق بين الفقاع (Pemphigus) والفقاع الفقاعي (Bullous pemphigoid) — مستوى الانشقاق والمستضد؟","b":"الفقاع: داخل البشرة (Intraepidermal) — أضداد ضد الدسموغلين (Desmoglein 1 و3)؛ الفقاعي: تحت البشرة (Subepidermal) — أضداد ضد BP180/BP230 (الهيميدسموسوم)."},{"f":"الفقاع الشائع (Pemphigus vulgaris) — المظهر السريري؟","b":"تآكلات مؤلمة بطيئة الشفاء في مخاطية الفم قد تسبق الجلد بأشهر + فقاعات رخوة هشة تتمزق بسهولة؛ علامة نيكولسكي إيجابية."},{"f":"علامة نيكولسكي (Nikolsky sign)؟","b":"ضغط منزلق ثابت بالإصبع على الجلد يُحدث تآكلًا — إيجابية في الفقاع الشائع وانحلال البشرة السمي."},{"f":"الفقاع الفقاعي (Bullous pemphigoid) — المظهر والمناعة؟","b":"فقاعات متوترة (Tense blisters) وتآكلات وحمامى شرية عند المسنين؛ التألق المناعي: شريط خطي من IgG و/أو C3 عند الوصلة الأدمية البشرية."},{"f":"الفقاع الفقاعي — ارتباطاته؟","b":"أمراض عصبية (خرف، باركنسون، سكتة دماغية)، الاستخدام المزمن لمضادات الذهان والسبيرونولاكتون."},{"f":"الفقاع الورقي (Pemphigus foliaceus) — المستضد والمظهر؟","b":"دسموغلين 1 فقط؛ انشقاق سطحي جدًا فالفقاعات نادرة — تآكلات متقشرة تشبه التهاب الجلد الدهني."},{"f":"كيف تفرّق مناعيًا بين الفقاع الفقاعي وفقاع انحلال البشرة المكتسب؟","b":"التفريق بتقنية الجلد المشقوق بالملح: أضداد الفقاعي ترتبط بجهة البشرة (السقف)، وأضداد المستضدات الأدمية بجهة الأدمة (القاعدة)."},{"f":"متى تكون الفقاعات طارئًا طبيًا؟","b":"التفقع الواسع مع تخرب الحاجز البشري مهدد للحياة ويُعامل كطارئ طبي."}]},{"t":"أمراض النسج الضامة الجلدية","cards":[{"f":"طفح الفراشة (Butterfly rash) في الذئبة؟","b":"طفح الفراشة (Malar rash): حمامى وذمية قليلة القشور متناظرة على الخدين العلويين في SLE النشط؛ لا تندب ولا بثور وتختفي سريعًا."},{"f":"الذئبة القرصية (Discoid LE)؟","b":"لويحات متقشرة مزمنة (تظهر في الأذن مثلًا) — الشكل المزمن من الذئبة الجلدية."},{"f":"طفح الهليوتروب (Heliotrope rash)؟","b":"حمامى بنفسجية (Heliotrope) على الجفنين مع وذمة حول الحجاج — التهاب الجلد والعضل (Dermatomyositis)."},{"f":"حطاطات غوترون (Gottron papules)؟","b":"حطاطات بنفسجية مسطحة متقشرة فوق المفاصل بين السلامية الظهرية — مميزة (Pathognomonic) لالتهاب الجلد والعضل (في ثلث المرضى)."},{"f":"علامة الشال (Shawl sign)؟","b":"حمامى مع قشور ناعمة على أعلى الصدر والرقبة الخلفية وأعلى الظهر والكتفين — التهاب الجلد والعضل."},{"f":"التهاب الجلد والعضل عند البالغين — ما الخطر الذي يستدعي المسح؟","b":"20–25% من البالغين يصابون بخباثة داخلية خلال سنتين من التشخيص (الخطر أعظم في السنة الأولى) — افحص البطن والعقد والثدي والبروستات."},{"f":"أيدي الميكانيكي (Mechanic's hands)؟","b":"فرط تقرن وتقشر وتشقق على الجوانب الوحشية للإبهام والأصابع — التهاب الجلد والعضل (تشبه التهاب الجلد التماسي)."}]},{"t":"الحمامى العقدة","cards":[{"f":"الحمامى العقدة (Erythema nodosum) — ما هي نسيجيًا؟","b":"أشيع التهاب نسيج دهني (Panniculitis)؛ التهاب الحواجز (Septal) بلا التهاب وعائي."},{"f":"مظهر الحمامى العقدة؟","b":"عقيدات حمامية مؤلمة ملساء على قصبتَي الساقين بتوزع متناظر."},{"f":"أسباب الحمامى العقدة؟","b":"العقديات، الساركوئيد، الداء المعوي الالتهابي (كرون > التهاب القولون التقرحي)، الحمل، أدوية (مانعات حمل فموية، بنسلينات)، بهجت؛ وثلث الحالات بلا سبب."},{"f":"متلازمة لوفغرن (Löfgren syndrome)؟","b":"حمامى عقدة + ضخامة عقد نقيرية ثنائية + حمى + التهاب مفاصل كاحل حاد = مشخصة للساركوئيد."},{"f":"الفرق بين الحمامى العقدة والتهاب الأوعية العقيدي (Bazin)؟","b":"العقدة: عقيدات على القصبتين لا تتقرح ولا تترك ندبة؛ التهاب الأوعية العقيدي (Bazin): عقيدات على الربلتين تتقرح وتشفى بندبة مع فقدان دهن — التهاب فصيصي مع التهاب وعائي مرتبط بالسل."},{"f":"سير الحمامى العقدة؟","b":"تشفى عادة دون علاج ودون ترك ندبة أو فقدان دهن."}]},{"t":"الحمامى عديدة الأشكال","cards":[{"f":"الحمامى عديدة الأشكال (Erythema multiforme) — المحرض الأشيع؟","b":"خمج الحلأ البسيط (HSV)؛ الأدوية <10%؛ مرض حاد محدود ذاتيًا يشفى خلال 4 أسابيع."},{"f":"الآفة المميزة للحمامى عديدة الأشكال؟","b":"آفات هدفية (Target lesions): مركز قاتم بنفسجي محاط بمنطقة حمراء خارجية وأحيانًا منطقة بيضاء وسطى؛ قد يتقرح المركز أو يتقشر."},{"f":"الفرق بين الحمامى عديدة الأشكال والشرى؟","b":"آفات EM تستمر ≥7 أيام بنفس الموضع (الشرى يزول خلال 48 ساعة تاركًا جلدًا طبيعيًا)؛ كل آفات EM تظهر خلال 3 أيام؛ مركز الآفة الهدفية قاتم/متقرح بعكس الشرى."},{"f":"التوزع في الحمامى عديدة الأشكال؟","b":"لطخات حمامية مستديرة متناظرة محددة على الركب والمرفقين ± الراحتين تتطور لحطاطات وآفات هدفية؛ تقرحات مخاطية قليلة على سطح واحد غالبًا."},{"f":"علاج الحمامى عديدة الأشكال الناكسة؟","b":"وقاية بأسيكلوفير 400 ملغ مرتين يوميًا للناكس."},{"f":"متلازمة ستيفنز-جونسون (SJS) — السبب والتوقيت؟","b":"دوائية غالبًا؛ البدء بعد 2–3 أسابيع من بدء الدواء؛ طفح دوائي مؤلم + علامات مخاطية = جرس إنذار."}]},{"t":"الأخماج البكتيرية الجلدية","cards":[{"f":"القوباء (Impetigo) — العامل والمظهر؟","b":"عدوى سطحية: S. aureus و/أو S. pyogenes؛ قشور عسلية ذهبية ونزف؛ القوباء الفقاعية بوساطة سموم تقشر (تفكك Desmoglein-1)."},{"f":"التهاب الجريبات — العامل الأشيع؟","b":"التهاب الجريبات (Folliculitis): S. aureus الأشيع؛ بعد الحمامات الساخنة/الدوامات: P. aeruginosa؛ الدمامل (Furunculosis) أعمق وتشفى بندبة وقد تتقدم لالتهاب النسيج الخلوي."},{"f":"الحمرة (Erysipelas) — العامل والمظهر والعلاج؟","b":"S. aureus؛ لويحة حمراء ساطعة محددة الحواف مرتفعة على الوجه أو الساقين مع أعراض بنيوية؛ العلاج المختار: البنسلين."},{"f":"التهاب النسيج الخلوي (Cellulitis) — الموقع والمظهر؟","b":"GAS غالبًا (S. aureus أقل): عدوى الأدمة العميقة والنسج تحت الجلدية؛ منطقة غير محددة الحواف مؤلمة متورمة ± حمى؛ تبدأ غالبًا بكسر في الحاجز الجلدي."},{"f":"التهاب اللفافة الناخر (Necrotizing fasciitis) — العامل والعلاج؟","b":"GAS غالبًا (خمج مختلط عادة)؛ تنخر سريع مترقٍ للنسيج تحت الجلدي واللفافة؛ لويحات متوترة مؤلمة لا تستجيب للمضادات؛ وفيات 30% — العلاج: تنضير جراحي واسع."},{"f":"الاكثيما (Ecthyma)؟","b":"عدوى كاملة السماكة عادة بـ S. aureus أو S. pyogenes مع تقرح وتقشر."},{"f":"التهاب الجلد حول الشرج العقدي (Perianal streptococcal dermatitis)؟","b":"S. pyogenes (المجموعة A) عند أطفال قبل البلوغ؛ حمامى شرجية حمراء ساطعة محددة لا تستجيب لمضادات الفطريات أو الستيروئيدات الموضعية؛ العلاج: أموكسيسيلين فموي 10 أيام."},{"f":"سم Panton-Valentine leukocidin — ما أهميته؟","b":"سلالات S. aureus المكتسبة مجتمعيًا الحاملة لسم Panton-Valentine leukocidin تسبب دمامل عميقة متعددة وخراجات والتهاب نسيج خلوي والتهاب رئة ناخر عند شبان وأطفال أصحاء."}]},{"t":"الأخماج الفيروسية الجلدية","cards":[{"f":"الأكزيما الحلئية (Eczema herpeticum)؟","b":"خمج الحلأ البسيط (HSV) المعمم عند أطفال الأكزيما التأتبية؛ مهدد للحياة عند الأطفال (عدوى أولية غالبًا)؛ قد يعقد الحروق وأمراضًا جلدية نادرة."},{"f":"الحلأ البسيط مقابل الحلأ النطاقي — المظهر؟","b":"حويصلات تتطور لبثور صغيرة؛ النطاقي (VZV) بتوزع جلدي عصبي (Dermatomal)؛ الحلأ البسيط الأولي قد يكون وذميًا مؤلمًا."},{"f":"الخمج الأولي بـ HIV — كيف يتظاهر جلديًا؟","b":"بعد 2–4 أسابيع من التعرض: مرض شبيه بالحمى الغدية (توعك، حمى، التهاب حلق، ضخامة عقد) + طفح حصبي معمم يجنّب الراحتين والأخمصين؛ اختبارات الأضداد سلبية حينها."},{"f":"خموج جلدية توحي بعوز مناعي؟","b":"حلأ بسيط مزمن غير شافٍ، نطاقي شديد منتشر، مليساء كثيرة/كبيرة (وجه/ثنيات)، ثآليل وجهية تناسلية حول الشرج، طلوان مشعر فموي (EBV)؛ 50% من الحالات تُشخص متأخرًا — فكر دائمًا باختبار HIV."},{"f":"الطلوان المشعر الفموي (Oral hairy leukoplakia)؟","b":"على جانبي اللسان بسبب EBV — علامة عوز مناعي."},{"f":"الخمج الجلدي بـ CMV؟","b":"قرحات شرجية/تناسلية، حطاطات، لطخات فرفرية — عادة مع خمج حشوي عند المثبطين مناعيًا."},{"f":"داء اليد والقدم والفم — العامل؟","b":"فيروس كوكساكي A16 — حويصلات (الآفة الأولية حويصلات تتطور لبثور)."},{"f":"الفرق بين آفات الحلأ والقوباء الفقاعية؟","b":"الحلأ: حويصلات تتطور لبثور/حويصلات بثرية؛ القوباء الفقاعية: حويصلات سطحية تتمزق سريعًا تاركة قشورًا ذهبية."}]},{"t":"الأخماج الفطرية","cards":[{"f":"السعفة الجسدية (Tinea corporis)؟","b":"نمط حلقي مع حدود متقشرة محددة بوضوح؛ القشور أوضح على الحافة الخارجية للخاتم."},{"f":"سعفة القدم (Tinea pedis)؟","b":"قشور منقوعة بين الإصبعين الرابع والخامس أو قشور جافة منتشرة على الأخمصين (نمط الموكاسين)."},{"f":"سعفة الرأس (Tinea capitis)؟","b":"عند الأطفال أساسًا؛ تسبب تساقط شعر (بعكس الصداف/الأكزيما)؛ الآفات الالتهابية = كيريون (Kerion)؛ شعر Microsporum يتفلور أخضر ساطع تحت مصباح وود."},{"f":"علاج سعفة الرأس؟","b":"مضاد فطري فموي + شامبو كيتوكونازول؛ Microsporum canis: غريزوفولفين أو إيتراكونازول؛ T. tonsurans: تيربينافين فموي أفضل."},{"f":"علاج سعفة الأظفار (Onychomycosis)؟","b":"صعب الاستئصال؛ الفطريات الجلدية تتطلب مضادًا فمويًا (تيربينافين 3 أشهر أو نبضي تيربينافين/إيتراكونازول)؛ الدهانات الموضعية للعفن السطحي فقط."},{"f":"السعفة المقنعة (Tinea incognito)؟","b":"خمج فطري شُخّص خطأً وعولج بستيروئيد موضعي: قشور أقل وضوحًا، بقع أكثر حطاطية وبثرية مع بقاء الحافة المنشطة محددة."},{"f":"أشيع الفطريات الجلدية؟","b":"البشرية (Anthropophilic) الأشيع: Trichophyton rubrum (قدم، ظفر، مغبن، جسم)؛ الحيوانية (Zoophilic) تسبب طفحًا أكثر التهابًا — اسأل عن التماس مع الحيوانات."},{"f":"المبيضات الفموية (Thrush)؟","b":"خطوط/لويحات بيضاء على الغشاء الشدقي أو اللسان تُمسح تاركة قاعدة حمامية (بعكس الحزاز المسطح)."},{"f":"علامة المبيضات في الثنيات (Candidal intertrigo)؟","b":"حمامى مع بثور سطحية صغيرة على الجلد المجاور (Satellite pustules)."},{"f":"الداحس المزمن (Chronic paronychia)؟","b":"تورم إسفنجي في طية الظفر الدانية مع فقدان الجليدة وتخدد الظفر — مبيضات."},{"f":"خطأ شائع في علاج المبيضات؟","b":"التيربينافين والغريزوفولفين (للفطريات الجلدية) غير فعالين في الخموج الخميرية."},{"f":"عوامل خطر المبيضات الجلدية المخاطية؟","b":"الحمل، السكري، مضادات حيوية مطولة، عوز مناعي (HIV)، نقص الحديد والزنك، الانسداد والتليّن (ثنيات جلدية)."},{"f":"النخالية المبرقشة (Pityriasis versicolor) — العلاج؟","b":"لويحات/لطخات شاحبة متقشرة منتشرة؛ العلاج: شامبو كيتوكونازول 2% غسول للجسم يوميًا 5 أيام (5 دقائق تماس)؛ للمنتشر: إيتراكونازول فموي 200 ملغ/يوم 5–7 أيام؛ النكس شائع."}]},{"t":"الليشمانيا الجلدية","cards":[{"f":"الليشمانيا الجلدية — الناقل والعامل؟","b":"لدغات أنثى ذبابة الرمل؛ طفيليات ليشمانيا داخل البلعمية (21 نوعًا تصيب البشر)؛ المستودع: قوارض، خفافيش، ذئاب، ثعالب."},{"f":"مظهر الليشمانيا الجلدية؟","b":"عقيدة بنية غير مؤلمة (لا تحك عادة) على جلد مكشوف ليليًا (وجه، رقبة، ذراعان) تتضخم ببطء للويحات أو آفات ثؤلولية (عالم قديم) أو عقيدات حمامية تشبه الدمامل تتقشر مركزيًا وتتقرح خلال 1–3 أشهر (عالم جديد)."},{"f":"فترة حضانة الليشمانيا الجلدية؟","b":"وسطيًا شهرين، وقد تتأخر أكثر من سنة بعد لدغة ذبابة الرمل."},{"f":"تشخيص الليشمانيا الجلدية مخبريًا؟","b":"خزعة ثاقبة 4 مم من الحافة المرتفعة (نسيج حبيبي؛ قد يصعب إيجاد الأماستيغوت حتى بصبغة غيمزا)؛ اللطاخة من كشط الجلد أسهل من الخزعة؛ PCR يكشف DNA الطفيلي؛ المصلية غير مفيدة عادة."},{"f":"سير الليشمانيا الجلدية وعلاجها؟","b":"معظم الآفات تشفى دون علاج خلال 3–18 شهرًا تاركة ندبة منخفضة مشوهة؛ العلاج الأساسي: أنتيمون خماسي التكافؤ (ستيبوغلوكونات الصوديوم) داخل الآفة/عضلي/وريدي."},{"f":"خطر الليشمانيا العالم الجديد؟","b":"خطر تطور داء مخاطي: تقرح مخاطي مدمر عميق (أنف، بلعوم)."},{"f":"الليشمانيا الراجعة (Leishmaniasis recidivans)؟","b":"آفة وجهية مركزية مدمرة مزمنة تتضخم على سنوات — تُرى في إيران والعراق؛ بسبب L. tropica."},{"f":"الانتشار السبوروتريكويدي في الليشمانيا؟","b":"عقيدات تابعة حول العقيدة الأولية قد تنتشر على طول اللمفاويات."},{"f":"أسماء مرادفة لليشمانيا الجلدية؟","b":"حبة بغداد، حبة حلب، القرحة الشرقية (Aleppo boil / Baghdad sore / Oriental sore)."}]},{"t":"الجرب والقمل والطفيليات","cards":[{"f":"الجرب (Scabies) — العامل؟","b":"Sarcoptes scabiei var. hominis؛ الحكة من حساسية للعاب السوس وبيوضه وبرازه؛ الأنثى (0.4 مم) تحفر في البشرة وتضع 1–3 بيوض/يوم لـ4–6 أسابيع."},{"f":"الحكة في الجرب؟","b":"شديدة للغاية تزداد بالدفء (ليلًا)؛ الرأس والرقبة يُجنَّبان عادة إلا عند الصغار جدًا أو المسنين أو المثبطين مناعيًا."},{"f":"العلامة المشخصة للجرب؟","b":"الأنفاق (Burrows): خطوط منحنية بشكل فاصلة بطول بضعة مم في الطبقة القرنية — افحص المسافات بين الأصابع والوجه الثني للرسغين والمرفقين والإبطين والثديين والأعضاء التناسلية وحواف القدمين."},{"f":"علامات أخرى للجرب؟","b":"عقيدات على القضيب؛ حويصلات/بثور على الراحتين والأخمصين عند الرضع؛ تقشر بين الأصابع؛ بالمنظار الجلدي: مثلث داكن صغير خلف نهاية النفق مباشرة."},{"f":"الجرب المتقشر (النرويجي)؟","b":"نفس السوس لكن آلافها (>1000 سوسة) عند المنهكين/المسنين/المثبطين (بما فيهم HIV)؛ الحكة أقل وضوحًا؛ قشور سميكة واسعة (يدان، مرفقان، ركبتان، كاحلان) مع إصابة الوجه وفروة الرأس وأسرة الأظافر؛ شديد العدوى."},{"f":"انتقال الجرب؟","b":"تماس جلدي وثيق (15–20 دقيقة على الأقل): مشاركة السرير، مصافحة، جماع؛ السوس لا يقفز ولا يطير."},{"f":"علاج الجرب التقليدي؟","b":"بيرمثرين 5% كريم لكل الجسم 8–14 ساعة ثم يُغسل، يُكرر بعد 7 أيام (وللأطفال <سنتين والمسنين والمثبطين: يشمل فروة الرأس والوجه والأذنين)؛ علاج كل المخالطين بنفس الوقت؛ غسل الملابس والمفارش بماء ساخن أو عزلها 72 ساعة."},{"f":"علاج الجرب المتقشر؟","b":"إيفرمكتين 200 مكغ/كغ أيام 1، 2، 8، 9، 15 + بيرمثرين 5% لكل الجسم يوميًا 7 أيام ثم مرتين أسبوعيًا حتى القضاء على السوس."},{"f":"بعد علاج الجرب — ماذا تتوقع؟","b":"الحكة قد تستمر 2–3 أسابيع بعد العلاج؛ كالامين زيتي أو ستيروئيد موضعي متوسط + مضاد هيستامين مهدئ ليلًا (هيدروكسيزين 25–50 ملغ)."},{"f":"عدد السوس في الجرب التقليدي؟","b":"10–12 سوسة بالغة فقط رغم شدة الحكة المنتشرة والمؤلمة."}]},{"t":"الأمراض المنتقلة بالجنس","cards":[{"f":"الزهري الأولي (1° Syphilis)؟","b":"قرحة وحيدة غير مؤلمة محددة جيدًا صلبة (شانكر) بعد ~3 أسابيع من التماس الجنسي + ضخامة عقد ناحية؛ تشفى بندبة ضامرة منخفضة (~8 أسابيع)."},{"f":"الزهري الثانوي — المظهر الجلدي؟","b":"بعد 1–6 أشهر: طفح متناظر غير حاك على الوجه والجذع؛ لطخات حمراء ملساء ثم حطاطات نحاسية حمراء متقشرة (قد تشبه الصداف)؛ حطاطات متقرنة على الراحتين والأخمصين؛ يزول خلال 1–3 أشهر."},{"f":"اللاطمة العريضة (Condylomata lata)؟","b":"حطاطات مسطحة القمة متضخمة منقوعة في الثنيات الرطبة (حول الشرج، تحت الثدي، الفرج) — زهري ثانوي."},{"f":"العلامات المخاطية للزهري الثانوي؟","b":"بقع بيضاء رمادية بيضاوية وتآكلات على الحنك والغشاء الشدقي أو الشفوي واللسان (قرحات مسار الحلزون)؛ حطاطات مشقوقة في زاوية الفم."},{"f":"تساقط الشعر في الزهري الثانوي؟","b":"تساقط رقعي مأكول العث (Moth-eaten) مع فقدان الحاجبين والرموش."},{"f":"الفرق بين الزهري الثانوي والنخالية الوردية؟","b":"الزهري: لطخات نحاسية على الراحتين والأخمصين + لاطمة عريضة + حمى وضخامة عقد؛ الوردية: بقعة منذرة + نمط شجرة عيد الميلاد بلا إصابة راحية أخمصية."},{"f":"الزهري الثالثي (المتأخر)؟","b":"بعد سنوات من عدم العلاج: زهري عصبي (تابس ظهري، شلل عام)، زهري قلبي وعائي (التهاب أبهر)، أورام حبيبية (Gummata): عقيدات مطاطية غير مؤلمة تتقرح وتتندب (جلد وعظام)."},{"f":"أسباب القرحات التناسلية الخمجية؟","b":"HSV، الزهري (T. pallidum)، القرحة الرخوة (H. ducreyi)، الورم الحبيبي اللمفي التناسلي (C. trachomatis)، الورم الحبيبي الأربي (K. granulomatis)."},{"f":"تشخيص الزهري مخبريًا؟","b":"الأولي: عزل اللولبيات من الشانكر؛ اختبارات لولبية: IgM بعد أسبوعين، IgG بالأسبوع 4–5؛ غير اللولبية تتفاعل ~21 يومًا."},{"f":"ثالوث هتشنسون في الزهري الخلقي المتأخر؟","b":"التهاب القرنية الخلالي + شذوذ القواطع العلوية الدائمة المركزية (أسنان هتشنسون)."}]},{"t":"داء بهجت","cards":[{"f":"معايير تصنيف داء بهجت؟","b":"تقرح فموي ناكس (قلاعي صغير/كبير/حلئي الشكل ≥3 مرات في 12 شهرًا) + اثنان من: قرحات تناسلية، التهاب عيني (عنبية أمامية/خلفية أو التهاب وعائي شبكي)، آفات جلدية (حمامى عقدة، التهاب جريبات، آفات حطاطية بثرية)، اختبار باترجي إيجابي."},{"f":"اختبار الباترجي (Pathergy test)؟","b":"فرط تفاعل الجلد لوخز الإبرة في الساعد (حطاطة أو بثرة خلال 24–48 ساعة)؛ نوعي للغاية لداء بهجت."},{"f":"إصابة العين في داء بهجت؟","b":"التهاب عنبية أمامي/خلفي أو التهاب وعائي شبكي؛ قد يؤدي لنزف شبكي ووذمة حليمة وداء بقعي مع فقدان حدة البصر وتهديد العمى."},{"f":"إصابة المفاصل في داء بهجت؟","b":"50% من المرضى: التهاب مفاصل قليل محيطي غير مشوه وغير مخرّب غالبًا يدوم أسابيع."},{"f":"الإصابة العصبية والوعائية في داء بهجت؟","b":"عصبية (5%): علامات هرمية مخيخية حسية، اضطراب مصرات، تغيرات سلوكية، خثار جيوب أم جافية؛ وعائية (5%): التهاب أوعية كبيرة مع خثار وانسداد."},{"f":"التحاليل في داء بهجت؟","b":"ANA وRF وANCA سلبية؛ الواسمات الالتهابية ليست مؤشرًا جيدًا لنشاط المرض؛ قد يظهر فقر دم مرض مزمن وكثرة بيض."},{"f":"القرحات القلاعية الكبرى (Major aphthae)؟","b":"قرحات >10 مم تشفى خلال أشهر مع تندب وتليف غالبًا (60%) — قد تكون علامة بهجت."},{"f":"القرحات القلاعية الصغرى (Minor aphthae)؟","b":"80% من الحالات: 1–5 قرحات سطحية <10 مم على مخاطية غير متقرنة (أرضية الفم، الغشاء الشدقي/الشفوي) تشفى خلال 7–14 يومًا وتنكس كل 1–4 أشهر."}]},{"t":"الأورام الجلدية","cards":[{"f":"سرطان الخلايا القاعدية (BCC) — الوصف؟","b":"أشيع سرطان جلدي؛ عقدة لؤلؤية مع توسع شعريات سطحي (أوعية متشجرة بالمنظار الجلدي)؛ الأورام القديمة: عقيدات متقرحة (قرحة قارضة Rodent ulcer) بحواف ملفوفة لؤلؤية ملساء."},{"f":"أنواع سرطان الخلايا القاعدية؟","b":"عقدي كيسي (لؤلؤي)، سطحي (لويحات حمامية متقشرة بحواف لؤلؤية مرتفعة — غالبًا الجذع)، مصطبغ (قد يحاكي الميلانوما)، شكلي/ارتشاحي (لويحة شمعية صلبة تشبه الندبة يصعب تحديد حدودها)."},{"f":"سرطان الخلايا الحرشفية (SCC)؟","b":"ثاني أشيع سرطان جلدي (25% من سرطانات الخلايا الكيراتينية)؛ عقيدة متقرنة أو متقرحة بقاعدة محببة وحافة ملفوفة؛ عند المسنين على المواقع المعرضة للشمس وأشيع عند الرجال 3 أضعاف."},{"f":"عوامل الخطورة عالية الخطورة في SCC؟","b":"المواقع عالية الخطورة: الأذن > الأنف = الشفة الجلدية = الجفن = فروة الرأس؛ قطر >20 مم؛ عمق >4 مم؛ غزو حول عصبي أو لمفي وعائي؛ سيئ التمايز؛ تثبيط مناعي."},{"f":"الورم الشوكي القرني (Keratoacanthoma)؟","b":"SCC جيد التمايز: نمو سريع (<6 أسابيع) ثم ثبات 2–3 أشهر ثم تراجع خلال 4–6 أشهر تاركًا ندبة منخفضة؛ عقيدة وردية متناظرة كأسية 1–2 سم بحواف ملفوفة ملساء وسدادة كيراتينية مركزية."},{"f":"الميلانوما الخبيثة — إحصائيات؟","b":"5% من سرطانات الجلد لكنها تسبب 75% من وفيات سرطان الجلد؛ أشيع سرطان عند الشبان 15–34 سنة؛ معظمها ينشأ من جديد (30–50% فقط من وحمات سابقة)."},{"f":"معايير ABCDE للشامة المشبوهة؟","b":"عدم التناظر، الحدود، اللون، القطر، التطور (Asymmetry, Border, Colour, Diameter, Evolution) — للشامات غير منتظمة اللون أو المحيط أو الشكل."},{"f":"النوع الأشيع للميلانوما؟","b":"الميلانوما السطحية المنتشرة (SSM) — الأشيع عند القوقازيين."},{"f":"سرطان الجلد عند متلقي زرع الأعضاء؟","b":"سرطان الجلد أشيع خباثة لدى متلقي زرع الأعضاء؛ SCC > BCC؛ أورام أبكر ومتعددة وأكثر عدوانية؛ الآزاثيوبرين مسرطن ضوئي مباشر."},{"f":"التقرن الشمسي (Solar keratosis) — أهميته؟","b":"آفة محتملة التسرطن (Premalignant)؛ تصلبها أو تقرحها يوحي بتحول لسرطان حرشفي."},{"f":"قرحة تناسلية/جلدية مزمنة غير مفسرة — ما الإجراء؟","b":"خزعة أي قرحة طويلة الأمد غير مفسرة لاستبعاد الخباثة."}]},{"t":"أمراض الشعر والأظافر","cards":[{"f":"التساقط الكربي (Telogen effluvium)؟","b":"أشيع سبب للتساقط المنتشر الحاد: بعد 2–3 أشهر من شدة (مرض شديد/جراحة كبرى)؛ الجريب يتحول من طور النمو للراحة؛ اختبار السحب: ≥10 شعرات في كل سحبة؛ نسبة anagen/telogen الطبيعية 4:1 تنعكس."},{"f":"الثعلبة البقعية (Alopecia areata)؟","b":"بقع فقدان محددة جيدًا؛ فروة ملساء غير متقشرة؛ شعرات علامة التعجب (قصيرة مدببة) مميزة لكنها نادرة؛ الشعر الأبيض يُجنَّب؛ الشعر النامي أولًا غير مصطبغ."},{"f":"الثعلبة الأندروجينية؟","b":"عند الرجال: نمطية (قمة الرأس و/أو الصدغين)؛ عند النساء: ترقق منتشر."},{"f":"الفرق بين الثعلبة المندبة وغير المندبة؟","b":"غير المندبة: الجريبات ما زالت مرئية في المنطقة المصابة؛ المندبة: الجريبات لا تُرى بسهولة."},{"f":"أدوية تسبب تساقط شعر عكوس؟","b":"مضادات التخثر، مضادات الأورام، مضادات الفيروسات القهقرية، موانع الحمل الفموية، الرتينوئيدات/فيتامين A، مضادات الاكتئاب، الإنترفيرونات، مثبطات المناعة."},{"f":"الشعرانية (Hirsutism)؟","b":"نمو زائد لشعر انتهائي عند الأنثى بنمط ذكري معتمد على الأندروجين (وجه، شفاه، صدر، ذراعان، فخذان)؛ بسبب فرط إنتاج الأندروجين أو أدوية أندروجينية أو حساسية الجريب."},{"f":"سعفة الرأس مقابل الثعلبة البقعية؟","b":"سعفة الرأس: فروة حاكة متقشرة قد تلتهب؛ الثعلبة البقعية: فروة ملساء غير متقشرة مع شعرات علامة تعجب."},{"f":"نتف الشعر (Trichotillomania)؟","b":"شعرات قصيرة جذعية (<2 سم)؛ شائع عند الأطفال؛ الثعلبة بالشد: حواف الفروة حيث يُشد الشعر بقوة بلا قشور أو شعرات علامة تعجب."}]},{"t":"اضطرابات التصبغ","cards":[{"f":"البهاق (Vitiligo)؟","b":"فقدان مكتسب للخلايا الميلانينية البشروية: بقع/لطخات بيضاء ملساء (بلا قشور) = إزالة صباغ كاملة (تتفلور أبيض ساطع تحت مصباح وود)؛ متوسط البدء 20 سنة؛ حتى الثلث لديهم قصة عائلية؛ مرتبط بأمراض مناعية ذاتية (درقية)."},{"f":"توزع البهاق؟","b":"غير قطعي: أصابع، رسغان، إبطان، مغبنان، حول الفم والعينين، الأعضاء التناسلية؛ مواقع الضغط/الاحتكاك/الرض (ظاهرة كوبنر) كخط الحزام؛ قطعي: وحيد الجانب بتوزع جلدي عصبي."},{"f":"الوحمة الهالية (Halo naevus)؟","b":"حواف مزالة الصباغ حول وحمات ميلانينية — أشيع 10 أضعاف في البهاق."},{"f":"النخالية المبرقشة — الآلية؟","b":"خميرة Malassezia (متعايشة جلدية) تتكاثر في الطبقة القرنية منتجة حمض الأزيليك الذي يثبط تكوين الميلانين فيمنع اسمرار الجلد في الآفات."},{"f":"النخالية المبرقشة — المظهر والتشخيص؟","b":"لطخات بنية محمرة أو شاحبة متفاوتة الحجم بغبار قشور ناعمة على الجذع غالبًا (اكشط بلطف لرؤية القشور)؛ تحت وود: تتفلور أصفر؛ المجهر: خيوط وأبواغ (سباغيتي وكرات لحم)."},{"f":"الفرق بين المبرقشة والبهاق؟","b":"المبرقشة متقشرة ونقص صباغ جزئي؛ البهاق غير متقشر وإزالة صباغ كاملة."},{"f":"النخالية البيضاء (Pityriasis alba)؟","b":"بقع شاحبة بيضوية بقشور ناعمة خفية على الخدين عند الأطفال قبل البلوغ."},{"f":"الكلف (Melasma) مقابل بهاق الوجه؟","b":"الكلف فرط تصبغ يحيط بجلد طبيعي شاحب المظهر قد يُخلط مع بهاق الوجه."},{"f":"أسباب فرط التصبغ المعمم؟","b":"قصور كظري، متلازمة نلسون، أورام منتجة لـ ACTH خارجية، متلازمة POEMS، داء ترسب الأصبغة الدموية، تشمع صفراوي أولي."},{"f":"البقع البنية الفاتحة (Café au lait spots)؟","b":"الورم الليفي العصبي، متلازمة ماكيون-أولبرايت، متلازمة الأورام العصبية المخاطية المتعددة."},{"f":"نقص الميلانين النقطي مجهول السبب؟","b":"لطخات شاحبة على سواعد بالغين متضررة شمسيًا."},{"f":"نقص التصبغ بعد النخالية المبرقشة؟","b":"نقص صباغ بعد التهابي قد يستمر أشهرًا حتى تُحفَّز الخلايا الميلانينية بالتعرض الشمسي."}]},{"t":"مواضيع متفرقة","cards":[{"f":"أسباب الاحمرار الجلدي المعمم (Erythroderma)؟","b":"أكزيما (تأتبية/دهنية)، صداف، طفح دوائي، لمفوما جلدية تائية — المريض الأحمر المتقشر في كل الجسم طارئ جلدي (فشل جلدي)."},{"f":"الحلأ البسيط — البادرة والنكس؟","b":"بادرة وخز مهيج 4–6 ساعات؛ النكس بنفس المكان مشير للغاية للحلأ؛ القروح الباردة غير المعقدة تشفى بلا ندبة خلال 7–10 أيام."},{"f":"الفرق بين نكس الحلأ والطفح الدوائي الثابت؟","b":"كلاهما ينكس بنفس المكان؛ الحلأ ببادرة وخز، الطفح الدوائي الثابت بلا بادرة."},{"f":"HLA-B*5701 — ما أهميته؟","b":"مرتبط بفرط حساسية أباكافير — يُفحص قبل بدء العلاج عند مرضى HIV."},{"f":"الطفح الدوائي مقابل الطفح الفيروسي؟","b":"الطفح الفيروسي يشبه الطفح الدوائي الحصبي لكنه أشيع عند الأطفال؛ التفاعلات قد تستمر أشهرًا بعد إيقاف الدواء ولا يوجد اختبار حاسم يؤكد التشخيص."},{"f":"التهاب الجلد المفتعل — التشخيص التفريقي؟","b":"إساءة جسدية أو جنسية، التهاب جلد تماسي (تحسسي/تخريشي)، التهاب جلد نباتي ضوئي، خمج (بكتيري/فيروسي/فطري)، طفح دوائي ثابت، تقيح جلدي غنغريني."},{"f":"علاج الحكة النفسية المنشأ؟","b":"مضادات اكتئاب (SSRIs أو ثلاثية الحلقات بجرعات منخفضة كمعدلات عصبية — أميتريبتيلين 10 ملغ ليلًا)؛ الستيروئيدات الموضعية غير مفيدة إلا مع التهاب."},{"f":"الحلأ البسيط عند المثبطين مناعيًا؟","b":"قرحات أكبر/أعمق، آفات تابعة، شفاء مطول، خمج جهازي؛ قد يظهر كقرحات خطية بين الثنيات (علامة قطع السكين)."},{"f":"قرحة البرد (Cold sore) — السير؟","b":"حويصلات تتمزق وتتقشر خلال 2–3 أيام مع ضخامة عقد مؤلمة خفيفة؛ تشفى بلا ندبة خلال 7–10 أيام."},{"f":"تأكيد تشخيص الحلأ عند الشك؟","b":"مسحة للفيروسات في وسط زرع فيروسي مع قليل من سقف الحويصلة أو قاعدتها وسائلها."}]}]},{"s":"الأذنية","topics":[{"t":"أمراض الأذن والسمعيات","cards":[{"f":"التهاب الأذن الخارجية (Otitis externa) — العلامات؟","b":"ألم بعد المفرزات؛ قناة أذن خارجية ضيقة وذمية والغشاء الطبلي طبيعي أو غير مرئي؛ قد ينتشر الخمج من الأذن الوسطى."},{"f":"التهاب الأذن الخارجية الناخر — العلامات؟","b":"ألم قبل المفرزات؛ تحببات في أرضية القناة مع غشاء طبلي طبيعي."},{"f":"التهاب الأذن الوسطى الحاد — العلامات؟","b":"قناة طبيعية + غشاء طبلي منتفخ (Bulging)."},{"f":"الورم الكوليسترولي (Cholesteatoma) — العلامات؟","b":"قناة طبيعية + انكماش علّي/كيراتين في الغشاء الطبلي؛ بلا ألم؛ الأعراض قد تشمل: التهاب أذن وسطى ناكس بمفرزات مخاطية قيحية، نقص سمع، شلل وجهي، دوار."},{"f":"آلية تطور الورم الكوليسترولي؟","b":"ضغط منخفض مزمن في الأذن الوسطى → جيب انكماش في الجزء الرخو (pars flaccida) → تراكم ظهارة حرشفية/كيراتين لا يستطيع الخروج → خمج → إنزيمات حالة → تخرب البنى المجاورة."},{"f":"تدبير الورم الكوليسترولي؟","b":"تنظيف الأذن، مجهر + شفط وتنظيف، قطرات مضاد حيوي/ستيروئيد موضعية 10 أيام، مراجعة بالمجهر بعد شهر، قياس سمع، طبقي للعظم الصدغي (تروية الخشاء، تآكل الجدار العلّي scutum)."},{"f":"التهاب الأذن الوسطى القيحي المزمن بلا ورم كوليسترولي — العلامات؟","b":"قناة طبيعية + غشاء مثقوب أو أنابيب تهوية؛ بلا ألم."},{"f":"وظيفة الأذن الوسطى وبناها؟","b":"نقل الموجات الصوتية وتضخيمها وتمريرها للقوقعة + حماية الأذن من الضجيج؛ البنى: الغشاء الطبلي، السلسلة العظيمية، أعصاب الأذن الوسطى، عضلاتها، خلايا الخشاء الهوائية، نفير أوستاش."},{"f":"تصلب الركاب (Otosclerosis) — العلامات؟","b":"قصة عائلية، نساء/الحمل؛ غشاء طبلي طبيعي؛ ثلمة كارهارت (Carhart's notch) على مخطط السمع."},{"f":"شيخوخة السمع (Presbyacusis)؟","b":"نقص سمع الشيخوخة الشائع: ثنائي الجانب، حسي عصبي، عالي التردد."},{"f":"أذن الغراء (Glue ear) — العلامات؟","b":"عند الأطفال؛ بدء تدريجي؛ انصباب أذن وسطى؛ نقص سمع توصيلي."},{"f":"اختبار رين (Rinne test)؟","b":"يقارن التوصيل الهوائي بالعظمي؛ رين سلبي (العظمي > الهوائي) = نقص سمع توصيلي."},{"f":"اختبار ويبر (Weber test)؟","b":"الشوكة على الخط الناصف للجمجمة؛ يتموضع الصوت نحو جهة نقص السمع التوصيلي وبعيدًا عن جهة نقص السمع الحسي العصبي."},{"f":"لماذا يجب رؤية الغشاء الطبلي بعد علاج التهاب الأذن الخارجية؟","b":"لاستبعاد أمراض خطيرة على مستوى الغشاء الطبلي بعد تنظيف الأذن وعلاج الخمج الموضعي."},{"f":"رؤية الغشاء في التهاب الأذن الخارجية الشديد؟","b":"الشفط المجهري (Microsuction) أو التنشيف الجاف غالبًا ضروري لرؤية الغشاء الطبلي."}]},{"t":"أمراض الأذن العصبية والدوار والعصب الوجهي","cards":[{"f":"التهاب التيه / التهاب العصب الدهليزي (Labyrinthitis)؟","b":"نوبة دوار مفاجئة عند شخص سليم سابقًا؛ ذروة البدء 30–40 سنة؛ تستمر 1–2 يوم وتتحسن خلال أسابيع؛ رأرأة بعيدًا عن الجهة المصابة؛ قد يتلوها BPPV."},{"f":"علاج التهاب العصب الدهليزي الحاد؟","b":"كابت دهليزي للنوبة الحادة (بروكلوربيرازين 5 ملغ)؛ ستيروئيد إذا ترافق بنقص سمع حسي عصبي (بريدنيزولون 1 ملغ/كغ لأسبوع)؛ إعادة تأهيل دهليزي لمن لا يعوّض؛ الكابتات قد تؤخر الشفاء إن أسيء استخدامها."},{"f":"الدوار الموضعي الانتيابي الحميد (BPPV)؟","b":"أشيع سبب للدوار المحيطي؛ يبدأ ~50 سنة؛ نوب دوار قصيرة بتغير الوضعية؛ أسوأ صباحًا ومساءً."},{"f":"داء منيير — المبادئ العلاجية؟","b":"كل العلاجات توازن بين ضبط نوب الدوار وخطر نقص السمع؛ لا يُعالَج للأعراض غير الدوّارية؛ الحذر عند التعامل مع الأذن الأفضل سمعًا."},{"f":"الورم العصبي السمعي (الشواني الدهليزي)؟","b":"شوانوما من العصب الدهليزي (تسمية خاطئة مزدوجة)؛ تشكل 80% من أورام الزاوية المخيخية الجسرية؛ تتظاهر بفقد سمع/طنين أحادي ثم الدوار لاحقًا؛ نمو بطيء (1–2 مم/سنة)."},{"f":"شلل بيل (Bell's palsy) — الإنذار؟","b":"الشلل غير المكتمل دون تنكس محوري يتعافى تمامًا خلال أسابيع؛ ~80% من ذوي الشلل المكتمل يحققون تعافيًا عفويًا كاملًا."},{"f":"أسباب شلل العصب الوجهي؟","b":"شلل بيل (LMN)؛ رامزي هانت؛ التهاب أذن وسطى/ورم كوليسترولي؛ كسر قاعدة القحف؛ ورم زاوية جسرية مخيخية؛ ورم نكفي خبيث؛ UMN: سكتة/ورم؛ الضعف الثنائي: لايم، غيلان-باريه، ساركوئيد."},{"f":"متلازمة رامزي هانت (Ramsay Hunt)؟","b":"حلأ نطاقي للعصب الوجهي: حويصلات في الأذن + ألم أذن + ضعف وجهي معزول."},{"f":"الدوار الوعائي؟","b":"انسداد شريان التيه: دوار مفاجئ + نقص سمع مع تنخر واسع؛ 62% من مرضى النوب الإقفارية العابرة لديهم دوار نوبي؛ التعويض خلال 4–6 أشهر."},{"f":"متى لا حاجة لتحاليل أو تصوير في شلل الوجه؟","b":"إذا كان العرض نموذجيًا لشلل بيل بلا عجوزات عصبية مرافقة ولا مؤشرات لسبب بديل."}]},{"t":"أمراض الأنف والجيوب الأنفية","cards":[{"f":"التهاب الجيوب الأنفية — التعريف الحديث؟","b":"التهاب الجيوب يُعتبر امتدادًا لطيف التهاب الأنف (Rhinosinusitis)."},{"f":"البوليبات الأنفية البسيطة — ما هي؟","b":"جزء من طيف التهاب الجيوب الأنفية: مخاطية جيبية وذمية متدلية تملأ جوف الأنف بدرجات متفاوتة؛ شائعة وسببها مجهول."},{"f":"أعراض البوليبات الأنفية؟","b":"انسداد أو سيلان أنف وعطاس (التهاب أنف)، التهاب جيوب بانسداد المعقد الفوهي الغربالي، ظهور البوليبات عند المنخرين الأماميين."},{"f":"الجراحة الوظيفية التنظيرية للجيوب (FESS)؟","b":"تستهدف المعقد الفوهي الغربالي: إزالة الانسداد في المنطقة الحرجة واستعادة الوظيفة والتصريف الطبيعيين؛ تفيد مرضى التهاب الجيوب غير المستجيبين للعلاج الطبي."},{"f":"انسداد أنفي أحادي حديث البدء مع نزف ورائحة كريهة؟","b":"بوليب أنفي/ورم — افحص التشريح الأنفي بعناية."},{"f":"انسداد أنفي ثنائي دائم مع جريان هوائي جيد واحتقان الصماخ الأوسط؟","b":"التهاب جيوب أنفية."},{"f":"انسداد أنفي ثنائي موسمي/متقطع مع ضخامة قرينات والتهاب مخاطية؟","b":"التهاب أنف (تحسسي)."},{"f":"مضاعفات التهاب الجيوب داخل القحف؟","b":"خمج الجيب الجبهي تحت ضغط → ركودة دموية في الأوردة ثنائية اللوحين → انتشار عبر اللوح الخلفي للجيب الجبهي: تخريش سحائي، وذمة دماغية، خراج فص جبهي."},{"f":"ورم بوت المنتفخ (Pott's puffy tumour)؟","b":"التهاب جيوب جبهي مستمر → التهاب عظم ونقي العظم الجبهي → تورم إسفنجي رخو على جلد الجبهة."},{"f":"تضخم القرينات في التهاب الأنف؟","b":"تتضخم في كل أنواع التهاب الأنف خاصة التحسسي وقد تسد المجرى لدرجة تعذر توصيل الدواء الموضعي؛ التقليل: كي سطحي/تحت مخاطي، تجميد، كسر خارجي، تشذيب (نتائج أطول لكن خطر نزف شديد بعد الجراحة)."},{"f":"انحراف الوتيرة الأنفية؟","b":"انسداد طويل الأمد أحادي يُلاحظ منذ الطفولة؛ قد يحتاج تصحيحًا لتحسين الوظيفة الأنفية وتوصيل الدواء."},{"f":"أعراض ورم الجيب الفكي؟","b":"أسنان مخلخلة، ألم/تقرح الحنك، تورم الخد."},{"f":"أعراض ورم الجيب الغربالي؟","b":"انسداد أحادي، شفع، صداع."},{"f":"استقصاءات أورام الجيوب الأنفية؟","b":"طبقي و/أو رنين، تنظير وخزعة، شفط بإبرة دقيقة عند النقائل العنقية؛ القرار العلاجي في اجتماع متعدد التخصصات للرأس والعنق."}]},{"t":"أورام الأنف والبلعوم الأنفي والرعاف","cards":[{"f":"سرطان البلعوم الأنفي — النوعان؟","b":"غير متمايز غير متقرن (أشيع في جنوب الصين وهونغ كونغ، مرتبط بفيروس EBV)؛ متمايز متقرن (عوامل خطر سرطانات الرأس والعنق المعتادة)."},{"f":"تظاهر سرطان البلعوم الأنفي؟","b":"رعاف (77%)، انسداد أنفي، صداع (73%)، نقائل عقدية (60%)، انصباب أذن وسطى؛ الأورام الواسعة تصيب قاعدة القحف وتسبب شلل أعصاب قحفية."},{"f":"قاعدة مهمة في انصباب الأذن الوسطى أحادي الجانب؟","b":"كل مريض بانصباب أذن وسطى أحادي يجب تصوير الحيز خلف الأنفي لاستبعاد سرطان البلعوم الأنفي."},{"f":"علاج سرطان البلعوم الأنفي؟","b":"علاج شعاعي لكل المراحل؛ تشريح عنق عند النقائل العقدية الواسعة."},{"f":"الورم الوعائي الليفي الأنفي اليافع (JNA)؟","b":"ورم نادر شبه حصري عند الذكور؛ يظهر في العقد الثاني (نادرًا >25 سنة)؛ ينشأ من الثقبة الوتدية الحنكية؛ غازٍ موضعيًا لكن غير خبيث؛ أعراض: انسداد أنفي (80%)، رعاف ناكس (50–60%)، صداع (25%)."},{"f":"الرعاف الأمامي مقابل الخلفي — التدبير؟","b":"أمامي: أوعية منطقة ليتل — كي أنفي؛ خلفي: حشو أنفي."},{"f":"أنواع أورام الجيوب الأنفية الشائعة؟","b":"SCC، ميلانوما خبيثة، سرطان غدي غربالي، ورم عصبي شمي."},{"f":"أعراض أورام الجيوب الأنفية؟","b":"بوليب أنفي مع انسداد، رعاف، شم كريه (Cacosmia)، شلل أعصاب قحفية، جحوظ."},{"f":"رعاف + انسداد أنفي + مفرزات مصلية دموية + تورم وجهي + جحوظ + كتلة عنق؟","b":"أورام جيوب أنفية — قيّم بالتنظير والطبقي/الرنين."},{"f":"التشخيص التفريقي لورم الزاوية المخيخية الجسرية؟","b":"ورم عصبي سمعي (80%)، ورم سحائي، كيسة بشروية، ورم حبيبي كوليسترولي، كيسة عنكبوتية، أم دم الشريان المخيخي الخلفي."},{"f":"علاج الورم العصبي السمعي الصغير؟","b":"جراحة إشعاعية مجسمة (تتجنب الجراحة)؛ أي إجراء يتضمن فتح القحف يحمل خطر وفاة 1%."},{"f":"مخاطر جراحة الورم العصبي السمعي؟","b":"شلل عصب وجهي، فقدان سمع كامل."}]},{"t":"أمراض الفم والبلعوم واللوزتين","cards":[{"f":"علامات التهاب اللوزتين الحاد؟","b":"التهاب حلق، ضخامة اللوزتين، نضح عليهما، صعوبة بلع، حمى، توعك، رائحة فم كريهة، ألم أذن."},{"f":"العوامل الممرضة لالتهاب اللوزتين وعلاجه؟","b":"عقديات حالة للدم بيتا، رئويات، مستدمية نزلية؛ أحيانًا بعد خمج فيروسي؛ العلاج: بنسلين + مسكنات بسيطة منتظمة + سوائل فموية وراحة."},{"f":"خراج حول اللوزة (Quinsy)؟","b":"فشل شفاء التهاب اللوزتين؛ تفاقم بعد 5–7 أيام (قد يتحسن أولًا ثم يتفاقم)؛ تورم الحنك الرخو والنسج الوحشية للوزة مع انزياح اللهاة للجهة المقابلة؛ مريض سام مع رائحة كريهة وتيبس فك وسيلان؛ العلاج: شفط بالإبرة أو شق وتصريف + صادات وريدية."},{"f":"التهاب النسيج الخلوي حول اللوزة؟","b":"مقدمة لخراج حول اللوزة: تفاقم التهاب حلق، ألم، تيبس فك، سيلان أحيانًا؛ غير القادر على البلع يُدخل للصادات الوريدية والإماهة."},{"f":"لماذا يُتجنب الأموكسيسيلين في التهاب اللوزتين؟","b":"قد يكون المريض مصابًا بداء وحيدات النوى (EBV) فيظهر طفح جلدي مزهر."},{"f":"استطبابات استئصال اللوزتين المطلقة؟","b":"اشتباه خباثة؛ انقطاع نفس انسدادي نومي عند الأطفال؛ كجزء من عملية أخرى (UPPP للشخير)."},{"f":"استطبابات استئصال اللوزتين النسبية (الناكس)؟","b":"7 نوب/سنة لسنة واحدة، أو 5 نوب/سنة لسنتين، أو 3 نوب/سنة لثلاث سنوات (مع حمى وضخامة عقد ونضح)؛ أكثر من خرّاج حول لوزة واحد."},{"f":"اللوزتان الكبيرتان بلا أعراض؟","b":"لا حاجة لاستئصالهما."},{"f":"متلازمة لوميير (Lemierre)؟","b":"التهاب بلعوم مع التهاب خثار الوريد الوداجي الباطن وصمات إنتانية/إنتان دم — من الاستطبابات النادرة لاستئصال اللوزتين."},{"f":"خراج جانب البلعوم؟","b":"اختلاط خطير لالتهاب اللوزتين: تورم منتشر في العنق، مريض سام بحمى عالية متذبذبة؛ عند الأطفال صعر لتهيج العضلة القصية الترقوية الخشائية."},{"f":"تقسيم تشريح البلعوم؟","b":"جوف فموي (الشفاه → العمود الأمامي للوزة)؛ بلعوم فموي (العمود الأمامي → الجدار البلعومي الخلفي، يحوي اللوزتين وقاعدة اللسان)؛ بلعوم أنفي (فوق الحنك، يحوي الزوائد، ينفتح فيه نفير أوستاش وحشيًا)."},{"f":"تعصيب اللسان؟","b":"حركي: العصب تحت اللسان؛ حس الثلثين الأماميين: العصب اللساني؛ حس الثلث الخلفي: البلعومي اللساني؛ ألياف التذوق: مع العصب الوجهي (وتر الطبل)."}]},{"t":"أمراض وأورام الغدد اللعابية","cards":[{"f":"أزواج الغدد اللعابية الكبيرة؟","b":"نكفية، تحت فكية، تحت لسانية (+ غدد صغيرة منتشرة في مخاطية الفم والحلق)؛ تنتج اللعاب للهضم وترطيب اللقمة."},{"f":"أورام الغدد اللعابية — قاعدة 80؟","b":"80% من أورام الغدد اللعابية في النكفية؛ 80% منها أورام غدية متعددة الأشكال حميدة؛ 50% من أورام تحت الفكية خبيثة؛ 80% من أورام الغدد الصغيرة خبيثة."},{"f":"الورم الغدي متعدد الأشكال؟","b":"أشيع ورم لعابي (نكفي)؛ حميد لكنه قد يتحول لخبيث إن بقي سنوات طويلة."},{"f":"ورم نكفي مع ضعف وجهي وألم؟","b":"ورم نكفي خبيث؛ الورم النكفي بلا ضعف وجهي: حميد غالبًا."},{"f":"حصيات الغدد اللعابية (Sialolithiasis)؟","b":"شائعة وتُصيب تحت الفكية غالبًا (مفرزات أغنى بالكالسيوم وأثخن)؛ ألم وتورم في الغدة أثناء/بعد الوجبات؛ الغدة متوترة ومؤلمة؛ قد تُجس الحصاة في القناة؛ التشخيص: صورة بسيطة أو تصوير قنوات لعابية."},{"f":"علاج حصيات الغدد اللعابية؟","b":"الحصيات البعيدة تُزال عبر الفم؛ العميقة قد تتطلب استئصال الغدة."},{"f":"فحص تورمات الغدد اللعابية؟","b":"قيّم وظيفة العصب الوجهي (تتأثر في الخبيث)؛ فحص داخل فموي لامتداد الفص العميق (يُدفع اللوزة إنسيًا)؛ فتحة قناة ستينسن مقابل الرحى الثانية العلوية؛ جس ثنائي اليدين للغدة تحت الفكية مع قناة وارتون بحثًا عن حصيات."},{"f":"التهاب الغدد اللعابية الحاد — العلاج؟","b":"إماهة، صادات، عناية بنظافة الفم؛ محفزات اللعاب (قطرات الليمون)؛ التصريف الجراحي عند خراج داخل الغدة."},{"f":"تورم لعابي يتغير مع الأكل؟","b":"حصاة/التهاب نكفي أو تحت فكي."},{"f":"التهاب الغدد اللعابية المزمن الناكس؟","b":"بسبب حصيات أو تضيق في الغدة/القناة؛ ألم وتورم عند الأكل؛ غالبًا في تحت الفكية وقد يتطلب استئصالها."},{"f":"تورم لعابي ثنائي مزمن مع جفاف عينين وفم؟","b":"متلازمة شوغرن."},{"f":"التورم اللعابي الحاد؟","b":"فكّر بالنكاف (Mumps) وHIV."}]},{"t":"أمراض الحنجرة واضطرابات الصوت والأورام","cards":[{"f":"بحة صوت <أسبوعين مع حمى والتهاب حلق وأعراض تنفسية علوية؟","b":"التهاب حنجرة حاد."},{"f":"بحة صوت >3 أسابيع ثابتة مترقية؟","b":"آفة حبل صوتي أحادية — سرطان حنجرة."},{"f":"بحة صوت عند مدخن ± عسر بلع/ألم/ألم أذن؟","b":"أورام حليمية حنجرية (Papillomata)."},{"f":"بحة صوت ثنائية الجانب؟","b":"وذمة رينكه (Reinke's oedema) — وذمة حميدة في الحبال الصوتية بسبب التدخين."},{"f":"بحة متغيرة تأتي وتذهب مع إساءة صوت بلا آفة حبلية؟","b":"عسر صوت توتر عضلي."},{"f":"حبل صوتي غير متحرك؟","b":"شلل حبل صوتي."},{"f":"سرطان الحنجرة — عوامل الخطر؟","b":"التدخين (الأهم)؛ التدخين + الكحول معًا خطر أكبر؛ أشيع خباثة في السبيل الهوائي الهضمي العلوي."},{"f":"سرطان الحنجرة — خطر ورم ثانٍ؟","b":"تغير حقلي واسع في كل مخاطية السبيل: 1–4% ورم متزامن، 5–10% خطر خباثة ثانية في الرأس والعنق خلال الحياة (قد تكون صامتة)."},{"f":"علامات سرطان الحنجرة المتقدم؟","b":"ألم (يُحال للأذن غالبًا)، تغير صوت (مكتوم لا أجش)، صعوبة تنفس وصرير، صعوبة بلع، ضخامة عقد عنقية (غالبًا العرض الوحيد)."},{"f":"استقصاءات سرطان الحنجرة؟","b":"خزعة أساسية (الحليمومات والحبيبومات والبوليبات قد تحاكي السرطان)؛ تنظير شامل للسبيل الهوائي الهضمي العلوي لورم أولي ثانٍ؛ صورة صدر؛ طبقي/رنين للعنق (تآكل الغضروف الدرقي، عقد عميقة)."},{"f":"كل مريض بكتلة في العنق؟","b":"يجب إحالته لفحص أذنية."},{"f":"التشخيص التفريقي لبحة الصوت؟","b":"التهاب حنجرة، شلل العصب الحنجري الراجع، عقيدات المغنين، ورم حنجري."},{"f":"تضيق تحت المزمار؟","b":"غضروف حلقي ضيق جدًا (خلقي أو بعد تنبيب مطول وتهوية مديدة)؛ العلامة: صرير من الولادة حتى سنتين؛ التشخيص بفحص قطر تحت المزمار تحت التخدير العام."},{"f":"درجات كوتون لتضيق تحت المزمار/الرغامى؟","b":"1: 50% انسداد؛ 2: 51–70%؛ 3: 71–99%؛ 4: بلا لمعة."}]},{"t":"إسعافات مجرى الهواء وكتل العنق","cards":[{"f":"كتلة عنقية وحيدة وحشية بقصة طويلة (أشهر/سنوات) بلا أعراض؟","b":"كيسة غلصمية (Branchial cyst)."},{"f":"كتلة خط وسط ترتفع بالبلع؟","b":"كتلة درقية."},{"f":"كتلة خط وسط ترتفع ببروز اللسان؟","b":"كيسة درقية لسانية (Thyroglossal cyst)."},{"f":"كتلة خط وسط لا تتحرك بالبلع؟","b":"كيسة أدمية (Dermoid cyst)."},{"f":"كتلة عنقية + نقص وزن + تعرق ليلي + فقد شهية + حمى؟","b":"لمفوما خبيثة (عقد مطاطية متعددة)."},{"f":"ضخامة عقد عنقية بعد خمج تنفسي علوي حديث؟","b":"ضخامة عقد تفاعلية."},{"f":"كتلة عنقية بعد سفر خارجي؟","b":"سل — ضعها في التفريقي."},{"f":"بزل الحنجرة (Cricothyroidotomy) — الاستطباب؟","b":"انسداد مجرى هوائي علوي عند تعذر التنبيب الرغامي: جسم أجنبي غير قابل للاسترداد، وذمة وجهية (حروق/وذمة وعائية)، رض وجهي فكي، خمج (التهاب لسان المزمار)."},{"f":"إجراء بزل الحنجرة؟","b":"استلقاء ظهري مع بسط العنق (يقرب الرغامى من الجلد)؛ جس ثلمة الغضروف الدرقي ثم انخفاض الغشاء الحلقي الدرقي؛ وخز بإبرة 14G مع سحب هواء للتأكيد؛ الإبرة والميني تراك مؤقتان بانتظار فغر رغامي رسمي."},{"f":"بزل الحنجرة بالإبرة عند الأطفال؟","b":"الطريقة المفضلة <12 سنة؛ تحافظ على الحياة 30–45 دقيقة فقط قبل تراكم CO2."},{"f":"تدبير الصرير الحاد؟","b":"O2، صادات واسعة (كو-أموكسيكلاف)، أدرينالين مرذذ، هيليوكس (أقل كثافة من الهواء — يكسب وقتًا)؛ التنبيب الرغامي خط أول؛ فغر الرغامى عند تعذره."},{"f":"رتق قمع الأنف الخلفي ثنائي عند الوليد؟","b":"الولدان يتنفسون من الأنف حصرًا؛ الفشل التنفسي ونقص الأكسجة قد يكون بسبب رتق قمع الأنف؛ مجرى هوائي فموي قد يعيد التنفس."}]},{"t":"اضطرابات الحنجره الخلقيه تلين الحنجره","cards":[{"f":"تلين الحنجرة (Laryngomalacia)؟","b":"يظهر بعد الولادة مباشرة: صرير شهيقي + صعوبات إرضاع؛ الحالة خفيفة ومحدودة ذاتيًا عادة؛ الشديد: رأب الطية الطرجهالية اللسانية (تقسيم الطيات المشدودة)."},{"f":"لماذا الرضع أكثر عرضة لصعوبات التنفس الحنجرية؟","b":"مجرى هوائي أصغر نسبيًا ومطلقًا؛ مخاطية حنجرية أقل التصاقًا (تتورم بشدة)؛ دعم غضروفي أقل صلابة (ينهار بالشهيق)."},{"f":"صرير ثنائي الطور عند وليد؟","b":"تضيق تحت المزمار."},{"f":"صرير عند طفل بعد خمج تنفسي علوي ببدء سريع مع سيلان؟","b":"خناق (Croup)."},{"f":"طفل متسمم بصوت مكتوم/متغير وحمى وتوعك؟","b":"التهاب لسان المزمار (Epiglottitis)."},{"f":"صرير شهيقي عند بالغ بعد جراحة درق/صدر حديثة؟","b":"شلل حبلين صوتيين ثنائي."},{"f":"صرير شهيقي/مختلط بقصة قصيرة عند طفل سليم سابقًا؟","b":"جسم أجنبي في مجرى الهواء."},{"f":"تلين الرغامى (Tracheomalacia) عند وليد؟","b":"مشاكل إرضاع وفشل نمو."}]}]},{"s":"العينية","topics":[{"t":"أمراض الملحقات والقطعة الأمامية","cards":[{"f":"الظفرة (Pterygium)؟","b":"نمو داخلي تحت ظهاري لنسيج ملتحمة بصلي تنكسي فوق الحوف إلى القرنية؛ شائعة في البلدان المشمسة (استجابة للأشعة فوق البنفسجية)؛ تغزو طبقة بومان؛ قد تسبب لابؤرية أو تعيق المحور البصري."},{"f":"الظفرة الكاذبة (Pseudopterygium)؟","b":"شريط ملتحمة ملتصق بمنطقة قرنية متأذية عند قمته بعد حادث التهابي حاد (حرق كيميائي، قرحة قرنية هامشية، رض)."},{"f":"مضاعفات الوردية العينية؟","b":"تحدث عند 6–18% من المرضى: تآكلات ظهارية نقطية سفلية، توعية محيطية، التهاب قرنية هامشي، ترقق قرني (سفلي غالبًا)."},{"f":"الحلأ النطاقي العيني؟","b":"بادرة وخز وجهي/جفني ~24 ساعة ثم حويصلات جفنية وحول عينية أحادية الجانب محددة؛ قرح قرنية متشعبة (Dendritic)؛ التهاب ملتحمة حليمي."},{"f":"جفاف العين — صبغة البنغال الوردي؟","b":"تصبغ الظهارة المريضة يدل على غياب الطبقتين المخاطيتين (عبر الغشائية والهلامية) وانكشاف سطح الخلية."},{"f":"أسباب نقص الدمع المائي؟","b":"ارتشاح الغدة الدمعية، انسداد قنواتها (تراخوما، فقاع ندبي، حروق كيميائية، SJS)، نقص إفراز منعكس حسي (سكري، عدسات لاصقة، جراحة انكسارية) أو حركي (أذية العصب السابع)."},{"f":"جفاف العين التبخري؟","b":"نقص غدد ميبوم (التهاب جفن خلفي، وردية)؛ اضطرابات فتحة الجفن (بروز، تراجع جفن)."},{"f":"القرنية المخروطية (Keratoconus)؟","b":"أشيع في التهاب الملتحمة والقرنية الربيعي (VKC) — يُعتقد بسبب فرك العين المستمر."},{"f":"التهاب القرنية الهربسي البسيط في VKC؟","b":"أشيع من المتوسط وقد يكون عدوانيًا وثنائيًا أحيانًا."},{"f":"التراخوما (Trachoma)؟","b":"خمج متدثرة؛ جريبات وحليمات على الجفن مع مفرزات مخاطية قيحية؛ العلاج: أزيثروميسين فموي أو تتراسيكلين موضعي."},{"f":"متلازمة الجفن المرن (Floppy eyelid)؟","b":"جفن علوي رخو للغاية؛ مرتبطة strongly بانقطاع النفس الانسدادي النومي (OSA)."}]},{"t":"أمراض العدسة والزرق","cards":[{"f":"البيلوكاربين في زرق إغلاق الزاوية — الآلية؟","b":"التقبض يسحب القزحية المحيطية بعيدًا عن الشبكة التربيقية فاتحًا الزاوية؛ ويخفض الضغط أيضًا بتقلص العضلة الهدبية (زيادة تسهيل الجريان عبر الشبكة)."},{"f":"الآثار الجانبية للبيلوكاربين؟","b":"موضعية: تقبض حدقة، ألم حاجب، انزياح حسر بصري، تفاقم أعراض الساد، عيوب ساحة أعمق؛ جهازية (نادرة): تخليط، بطء قلب، تشنج قصبي، أعراض هضمية."},{"f":"الزرق المحرض بالستيروئيد؟","b":"ثلث الأفراد يرتفع ضغطهم مع ستيروئيد موضعي قوي (مستجيبون/غير مستجيبين)؛ إيقاف الستيروئيد وحده غالبًا يخفض الضغط سريعًا."},{"f":"زرق حالّ العدسة (Phacolytic glaucoma)؟","b":"زرق ثانوي مفتوح الزاوية مع ساد مفرط النضج؛ انسداد تربيقي ببروتينات عدسية عالية الوزن الجزيئي."},{"f":"مثبطات ROCK في الزرق؟","b":"صنف جديد موضعي يزيد الجريان عبر الشبكة التربيقية؛ مرة يوميًا؛ فعالة بالمشاركة مع لاتانوبروست؛ أكثر فعالية قليلًا من لاتانوبروست وحده."},{"f":"مثبطات أنهيدراز الكربونيك الجهازية؟","b":"قصيرة الأمد خاصة في الزرق الحاد؛ الاستخدام الطويل محفوظ لمرضى خطر فقد البصر العالي؛ حساسية السلفا مضاد استطباب نسبي."},{"f":"بضع القزحية المحيطي بالليزر الوقائي؟","b":"تجربة ZAP: تأثير وقائي صغير على 6 سنوات — يُعرض فقط على الأعلى خطرًا لتطور إغلاق زاوية حاد احتقاني."},{"f":"العدسية المخروطية الأمامية؟","b":"متلازمة ألبورت (بيلة دموية وبروتينية + داء كلوي + فقد سمع حسي عصبي عالي النغمة) — انتفاخ العدسة بفحص المصباح الشقي."},{"f":"الساد السكري؟","b":"شكل ندفة الثلج اليافع أو الشيخي المبكر؛ التغيرات الانكسارية المحرضة بفرط سكر الدم الحاد تنعكس بضبط السكر (انتظر قبل شراء النظارات)."},{"f":"احمرار القزحية (Rubeosis iridis)؟","b":"أوعية جديدة على القزحية تحدث متأخرًا في اعتلال الشبكية السكري وقد تؤدي للزرق."},{"f":"علامة قطرة الزيت (Oil droplet sign)؟","b":"عدسية مخروطية (Lenticonus) — من شذوذات شكل العدسة."},{"f":"الخط الأول في زرق مفتوح الزاوية؟","b":"مشتقات البروستاغلاندين (لاتانوبروست)."}]},{"t":"أمراض العنبة والشبكية والجسم الزجاجي","cards":[{"f":"اعتلال الشبكية السكري الخلفي؟","b":"تمددات أوعية دقيقة (نقاط)، نزوف (لطخات)، نضحات صلبة (ترسبات شحمية)."},{"f":"اعتلال الشبكية قبل التكاثري؟","b":"IRMA، تخرز وريدي، تضاعف وريدي، نزوف لطخية متعددة."},{"f":"اعتلال الشبكية التكاثري (PDR)؟","b":"أوعية جديدة: على/ضمن قطر قرص من القرص البصري (NVD) و/أو في مواضع أخرى (NVE)؛ يحتاج إحالة عاجلة."},{"f":"التكاثري عالي الخطورة؟","b":"نزف زجاجي/أمام شبكي، أو أي تولد أوعية فعال، أو موقعه على/ضمن قطر قرص من القرص، أو NVD >ثلث مساحة القرص أو NVE >نصف مساحة القرص."},{"f":"الداء العيني السكري المتقدم؟","b":"انفصال شبكية شّدي، نزف زجاجي مستمر معنوي."},{"f":"علاج التكاثري: مضاد VEGF مقابل PRP؟","b":"رانيبيزوماب داخل الزجاجي فعال كالتخثير الضوئي الشامل حتى 5 سنوات (Protocol S)؛ نصف المرضى سيصابون بنزف زجاجي أيًا كان العلاج."},{"f":"الحمل واعتلال الشبكية السكري؟","b":"قد يتسارع؛ ~5% من الخفيف وثلث المتوسط يتطور للتكاثري أثناء الحمل؛ الخطر مرتبط بشدة الاعتلال في الثلث الأول."},{"f":"علامة هتشينسون (Hutchinson's sign)؟","b":"آفة في ذروة/جانب الأنف = إصابة الفرع الأنفي الهدبي لـ V1 وارتفاع فرصة إصابة العين في الهربس النطاقي العيني."},{"f":"علاج الهربس النطاقي العيني؟","b":"فامسيكلوفير/فالاسيكلوفير فموي أو أسيكلوفير جهازي خلال 72 ساعة من الأعراض تقلل الاختلاطات."},{"f":"متلازمة VKH — الطور النقاهي؟","b":"ثعلبة موضعة، شيب، بهاق، قاع غروب الشمس (Sunset glow)، علامة سوغيورا عند المصطبغين (خاصة اليابانيين)."},{"f":"الساركوئيد العيني؟","b":"رواسب قرنية حبيبية كبيرة (دهن ضأن)، عقيدات قزحية كبيرة، كرات ثلج زجاجية؛ صورة الصدر: ضخامة عقد نقيرية ثنائية (90% شذوذ)."},{"f":"استطبابات استئصال الزجاجي في التهاب العنبة؟","b":"انفصال شبكية شّدي، غشاء أمام شبكي، وذمة بقعية كيسية معندة، عتامة زجاجية كثيفة، نزف زجاجي، تولد أوعية محيطي معنوي."},{"f":"المقوسات العينية — العلاج؟","b":"بيريميثامين + سلفاديازين + حمض فولينيك (+ ستيروئيدات قشرية لالتهاب العين)."},{"f":"التحري الشبكي السكري؟","b":"سنوي إلزامي لكل المرضى؛ العمى قابل للمنع؛ التخثير الضوئي الليزري يوقف إنتاج العوامل المولدة للأوعية من الشبكية الإقفارية."},{"f":"أسباب وذمة البقعة الكيسية؟","b":"جراحة عينية/ليزر، أمراض وعائية شبكية (سكري، انسداد وريدي)، التهاب (عنبة)، أدوية (بروستاغلاندين موضعي)، تنكسات شبكية (التهاب شبكية صباغي)، شد زجاجي بقعي."}]},{"t":"أمراض العصب البصري وحركية العين","cards":[{"f":"اختبار الضوء المتأرجح (عيب حدقي وارد نسبي)؟","b":"الضوء في العين السليمة → تقبض حدقي ثنائي؛ عند نقله للعين المريضة تتوسع الحدقتان متناقضًا — يكشف مرضًا لا متناظرًا."},{"f":"شلل العصب الثالث؟","b":"العين تنظر للأسفل والخارج؛ تدلي جفن؛ حدقة كبيرة إذا انضغطت/تأذت الألياف نظيرة الودية الخارجية."},{"f":"شلل العصب الرابع؟","b":"شفع عند النظر للأسفل والداخل (يُلاحظ غالبًا عند نزول الدرج)؛ إمالة رأس تعويضية (صعر عيني)."},{"f":"شلل العصب السادس؟","b":"ضعف إبعاد العين (الحركة الوحشية) — شفع أفقي."},{"f":"العمى الشقي الصدغي (Bitemporal hemianopia)؟","b":"انضغاط التصالب البصري: ورم غدي نخامي، ورم قحفي بلعومي، أم دم الشريان السباتي الباطن."},{"f":"العمى الشقي المتجانس (Homonymous hemianopia)؟","b":"آفات ما بعد التصالب (سكتة، خراج، ورم) — يصيب نصف الساحة البصرية المقابل للآفة."},{"f":"التهاب العصب البصري؟","b":"ألم مع حركة العين، فقد رؤية مركزية، عيب حدقي وارد نسبي، تورم القرص (Papillitis) — أسباب: التصلب المتعدد، الزهري، اضطرابات الأوعية الكولاجينية."},{"f":"الوذمة الحليمية (Papilloedema)؟","b":"أشيع بسبب ارتفاع الضغط داخل القحف (ورم، خراج، التهاب دماغ، استسقاء رأس، فرط ضغط مجهول السبب)."},{"f":"ضمور العصب البصري — أسباب؟","b":"التصلب المتعدد، أورام الجبهة، رنح فريدريخ، التهاب الشبكية الصباغي، الزهري، الزرق، ضمور ليبر، انضغاط العصب المزمن."},{"f":"التكيف الحسي للحول؟","b":"كبت وحشية العين المنحرفة لتجنب الشفع (إن كان ثابتًا أحاديًا أدى للحول الكسول)؛ أو مراسلة شبكية شاذة (تكيف إيجابي في حول صغير الزاوية)."},{"f":"وضعية الرأس التعويضية في الحول الشللي؟","b":"المريض يدير رأسه باتجاه حقل عمل العضلة الضعيفة (حيث لا تستطيع العين النظر) فيختفي الشفع."},{"f":"الحول الإنسي عند الأطفال — متى تكيفي؟","b":"البدء المتأخر (18–36 شهرًا) يرجح مكونًا تكيفيًا؛ وكلما طال الحول في الطفولة المبكرة زاد خطر الكسل ما لم يكن التثبيت متناوبًا بحرية."}]},{"t":"الرضوض والأورام العينية","cards":[{"f":"الدم في الغرفة الأمامية (Hyphaema)؟","b":"شائع في الرض الكليل؛ المصدر جذر القزحية أو وجه الجسم الهدبي؛ الدم يترسب سفليًا بمستوى سائل؛ ارتفاع الضغط غير المضبوط → اعتلال عصب بصري إقفاري وتصبغ القرنية."},{"f":"تصوير الرض العيني: طبقي مقابل رنين؟","b":"الرنين أدق لكشف أذيات المقلة نفسها (تمزق خلفي خفي)؛ ممنوع عند الاشتباه بجسم أجنبي معدني حديدي."},{"f":"محاكيات الورم الأرومي الشبكي؟","b":"اعتلال الشبكية الخداجي (خداج ونقص وزن ولادة)، داء المقوسات (ورم حبيبي قطبي خلفي يحاكي الداخلي النمو)، التهاب عنبية/التهاب باطن المقلة."},{"f":"الورم الشبكي (Retinoma)؟","b":"متغير حميد السلوك من الورم الأرومي الشبكي؛ قبة بيضاء ملساء تتراجع لكتلة متكلسة؛ نادرًا يتحول متأخرًا لأرومي سريع النمو."},{"f":"غزو الحجاج من الأورام؟","b":"من خباثات الجفن (قاعدي، حرشفي، غدة دهنية)، ميلانوما الملتحمة، أورام داخل العين (ميلانوما مشيمية، أرومي شبكي)؛ ومن داخل القحف: ورم سحائي من حافة الوتد يسبب جحوظًا."},{"f":"الزرق الثانوي في أورام داخل العين؟","b":"~5% من العيون؛ الآليات: حصار تربيقي (غزو الزاوية بميلانوما قزحية)، زرق ميلانيني (بلاعم محملة بالصباغ)، زرق وعائي جديد (الأشيع في الميلانوما المشيمية/الأرومي)."},{"f":"البقعة الكرزية الحمراء (Cherry-red spot)؟","b":"انسداد الشريان الشبكي المركزي."},{"f":"متلازمة الجيب الصامت؟","b":"انخفاض العين (Enophthalmos) وتدلي جفن بسبب عتامة وفقدان حجم الجيب الفكي."},{"f":"تمزقات غشاء ديسميه؟","b":"عمودية عادة؛ أشيع بسبب رض الولادة."},{"f":"التهاب العين الودي (Sympathetic ophthalmia)؟","b":"بعد رض شديد — خطره قد يفوق أي أمل باستعادة البصر فيستدعي استئصال المقلة."},{"f":"الورم النجمي الشبكي؟","b":"قد يكون متعدد البؤر وثنائي الجانب."}]},{"t":"أسواء الانكسار والتشخيص والفحوص العينية","cards":[{"f":"مد البصر عند الأطفال — متى يُصحح؟","b":"حتى 4D لا يُصحح بلا حول إلا مع مشاكل رؤية قريبة؛ >4D يُعطى ثلثا التصحيح؛ مع حول إنسي: التصحيح الكامل بالشلل الهدبي حتى تحت سنتين."},{"f":"اللابؤرية عند الأطفال؟","b":"أسطوانة 1.50D أو أكثر تُصحح غالبًا خاصة في اللابؤرية اللامتناظرة بعد 18 شهرًا."},{"f":"قصر البصر عند الأطفال؟","b":"تحت سنتين: −5.00D أو أكثر يُصحح؛ 2–4 سنوات: −3.00D؛ الأكبر سنًا حسب الحاجة."},{"f":"تنظير القاع الموسع في الحول؟","b":"إلزامي لاستبعاد أمراضية عينية كامنة (تندب بقعي، نقص تنسج قرص، ورم أرومي شبكي) كسبب للانحراف."},{"f":"الشلل الهدبي في قياس الانكسار؟","b":"أشيع خطأ انكساري مسبب للحول هو مد البصر؛ القياس الدقيق يتطلب شلل العضلة الهدبية لتحييد التأثير المموّه للمطابقة."},{"f":"قياس التوتر بغولدمان؟","b":"القراءة على الميناء ×10 = الضغط مم زئبقي؛ ضغط الإصبع على المقلة أو عصر الجفنين يعطي قراءة مرتفعة كاذبة."},{"f":"القرنية الكبيرة (Megalocornea)؟","b":"نادرة، ثنائية، غير مترقية، غالبًا متنحية مرتبطة بـ X (90% ذكور)؛ قطر قرني أفقي ≥13 مم مع حجرة أمامية عميقة جدًا؛ عادة قصر بصر ولابؤرية عاليان."},{"f":"تصحيح مد البصر الكامل عند طفل طبيعي؟","b":"قد يقلل التقوّم البصري الفيزيولوجي (Emmetropization)."},{"f":"علامة نقص الخلايا الجذعية الحوفية؟","b":"استعمار القرنية بالخلايا الكأسية — تُكشف بالطباعة الخلوية (Impression cytology)."},{"f":"جراحة الانكسار — الفئة المستهدفة؟","b":"خطأ انكساري مستقر يرغب بتحسين حدة البصر بعد التصحيح الجراحي؛ تصحيح طول النظر الشيخي غير مُرضٍ باستمرار بعد."}]}]},{"s":"جراحة الأوعية","topics":[{"t":"رضوض الشرايين والانسدادات الحادة","cards":[{"f":"تعريف الإقفار الحاد في الطرف (Acute limb ischaemia) والنافذة الزمنية لإنقاذ الطرف؟","b":"أي نقص مفاجئ في تروية الطرف يهدد حياته؛ حالة إسعافية جراحية تتطلب إعادة التوعية خلال 4–6 ساعات، والتلف النسيجي اللانعكاسي يبدأ خلال 6 ساعات."},{"f":"العلامات الست «P» للإقفار الحاد في الطرف؟","b":"شاحب (pale)، بلا نبض (pulseless)، مؤلم (painful)، مشلول (paralysed)، مخدَّر (paraesthetic)، وبارد حتى الموت (perishingly cold)."},{"f":"أسباب الإقفار الحاد في الطرف ونسبها؟","b":"الخثار الحاد على تصلب عصيدي سابق ~60%، والصمّات ~30% (80% منها قلبية المنشأ: رجفان أذيني، احتشاء، خثرة جدارية)، وأسباب نادرة: تسلخ الأبهر، الرض، أذية علاجية المنشأ."},{"f":"أشيع مواضع انحشار الصمّة الشريانية؟","b":"الشريان العضدي، والفخذي الأصلي، والمأبضي، وتفرّع الأبهر («الصمّة السرجية» saddle embolus)."},{"f":"كيف تفرّق سريريًا بين الخثار الموضعي والصمّة في الإقفار الحاد؟","b":"الخثار: قصة عرج متقطع سابقة + غياب مصدر واضح للصمّات + نقص النبضات في الطرف المقابل. الصمّة: بدء مفاجئ بلا قصة عرج + وجود رجفان أذيني أو احتشاء حديث."},{"f":"التدبير الفوري للإقفار الحاد في الطرف؟","b":"هيبارين غير مجزَّأ 5000 وحدة IV دفعة واحدة ثم تسريب 1000 وحدة/ساعة (ما لم يوجد مضاد استطباب)، أكسجين، وريد، ECG وتروبونين، ثم دوبلر/تصوير أوعية عاجل وإحالة لجراح الأوعية."},{"f":"علامات اللانعكاسية (irreversible) في الطرف المصاب؟","b":"تبقّع جلدي ثابت، نزوف نقطية جلدية، عضلات صلبة خشبية — هنا البتر هو الخيار الجراحي الوحيد."},{"f":"اختلاط إعادة التروية بعد جراحة الإقفار الحاد؟","b":"متلازمة الحَيِّز (compartment syndrome) بعد إعادة التروية — تُعالَج ببضع اللفافات (fasciotomies) للحَيِّزات الأربعة في الساق."},{"f":"العلامات «الصلبة» (hard signs) لإصابة وعائية في رضوض الأطراف؟","b":"نزف خارجي ضخم، ورم دموي متوسّع أو نابض، غياب/ضعف النبضات البعيدة، رعدة (thrill) أو نفخة مستمرة مسموعة — تستلزم تدخلًا جراحيًا فوريًا."},{"f":"العلامات «اللينة» (soft signs) لإصابة وعائية؟","b":"قصة نزف فعّال في مكان الحادث، قرب الرض النافذ/الكليل من شريان رئيسي، ورم دموي صغير غير نابض، عجز عصبي."},{"f":"ما قيمة مؤشر ضغط الدوبلر البعيد في رض الأوعية؟","b":"مقارنة الضغط الانقباضي البعيد بالذراع السليمة؛ مؤشر <1.0 مُنبئ بإصابة شريانية."},{"f":"مبدأ ترتيب التدبير عند اجتماع إصابة وعائية وكسر عظمي؟","b":"يُجرى الإصلاح الشرياني أولًا لاستعادة الدوران قبل التثبيت العظمي، مع توقع متلازمة الحيز وبضع اللفافات."}]},{"t":"التصلب العصيدي ونقص التروية المزمن","cards":[{"f":"تعريف العرج المتقطع (Intermittent claudication) وانتشاره؟","b":"ألم عضلي متشنج في الطرف يظهر مع المشي لمسافة معينة ويزول بالراحة؛ يصيب ~4% ممن فوق 55 سنة (أغلبهم ذكور)، وأشيع موضع: الربلة."},{"f":"تصنيف فونتين (Fontaine) لنقص تروية الطرف السفلي؟","b":"الدرجة I: لاعرضي، II: عرج متقطع، III: ألم الراحة، IV: قرحات/غنغرينا — الدرجتان III وIV = إقفار حرج للطرف."},{"f":"معايير الإقفار الحرج للطرف (Critical limb ischaemia)؟","b":"ألم راحة >أسبوعين لا يستجيب للمسكنات البسيطة، أو ضغط كاحل بالدوبلر <50mmHg (أصابع <30mmHg عند السكري)، أو نخر نسيجي (قرحة/غنغرينا)."},{"f":"عرج الربلة يوحي بداء أي مستوى؟ وعرج الألية؟","b":"عرج الربلة يوحي بداء فخذي (femoropopliteal)، وعرج الألية ± عنانة (impotence) مع غياب النبض الفخذي يوحي بمتلازمة ليريش (داء سادّ أبهري حرقفي)."},{"f":"الاستقصاء الأول لمريض يشتبه بإصابة شريانية مسدودة مزمنة؟","b":"التشخيص سريري أساسًا؛ مؤشر الضغط الكاحلي-العضدي (ABPI) مع هبوطه بعد الجهد قد يكون مشخّصًا، والتصوير (دوبلر/DSA/CTA/MRA) فقط عند التخطيط لتداخل."},{"f":"الخط الأول في تدبير العرج المتقطع الوعائي؟","b":"تعديل عوامل الخطورة بقوة: إيقاف التدخين، ستاتين، تمارين منتظمة (برنامج مشي)، ضبط الضغط والسكر، مضاد صفيحات (أسبرين/كلوبيدوغريل)."},{"f":"لماذا يُعالَج الداء الشرياني المحيطي بقوة رغم أن خطورة فقد الطرف منخفضة في العرج؟","b":"لأن الخطورة الرئيسية قلبية وعائية: حتى 50% من المرضى (حتى اللاعرضيين) سيعانون وفيات قلبية وعائية أو احتشاءً أو سكتة خلال 5 سنوات."},{"f":"نتائج الرأب الوعائي (angioplasty) حسب القطعة؟","b":"ممتازة في القطعة الأبهرية الحرقفية (>90% نجاح)، وجيدة في الفخذية السطحية (90% نجاح و60-80% سالكية لسنتين)؛ نادرًا في المأبضية والظنبوبية لخطورة الانسداد."},{"f":"مبدأ جراحة الإقفار الحرج للطرف؟","b":"بذل كل الجهود لإعادة التوعية إن سمحت الحالة العامة؛ المبدأ: معالجة الداء الأقرب (proximal) أولًا ثم النزول للبعيد فقط إذا بقي الإقفار الحرج."},{"f":"التشخيص التفريقي للعرج المتقطع غير الوعائي؟","b":"تضيق القناة الشوكية (ألم عصبي المنشأ يزداد بالوقوف/المشي ويتحسن بالجلوس/الانحناء)، التهاب مفصل الورك، انحباس الجذر العصبي (عرق النسا)."}]},{"t":"تسلخ الأبهر وأمهات الدم الشريانية","cards":[{"f":"تعريف أم الدم الشريانية؟ والفرق بين الحقيقية والكاذبة؟","b":"توسع موضعي شاذ >50% من القطر الأصلي للشريان. الحقيقية: تشمل كل طبقات الجدار (مغزلية كمعظم أم الدم الأبهرية البطنية، أو كيسية كأمهات دم التوتة). الكاذبة: تجمع دم في البرانية فقط يتواصل مع اللمعة (بعد الرض عادة)."},{"f":"تعريف أم الدم الأبهرية البطنية (AAA) وانتشارها؟","b":"قطر >3cm؛ تصيب ~3% ممن فوق 50 سنة، ذكور:إناث ~3:1، أقل شيوعًا لدى السكريين."},{"f":"أشيع سبب لأمهات الدم الشريانية؟ وأشيع موضع؟","b":"الأشيع: التنكس العصيدي (ابحث عن عوامل الخطورة الوعائية). المواضع: الأبهر (تحت الكلية أشيع — 95% تبدأ تحت منشأ الكلويتين)، وشرايين الحرقفة والفخذ والمأبض."},{"f":"أخطر اختلاط لأم الدم الأبهرية البطنية؟ ووفيات المتمزقة؟","b":"التمزق هو الاختلاط الرئيسي؛ الوفيات نحو 90% إجمالًا و50% لمن يصل المستشفى حيًا."},{"f":"الثلاثية السريرية الكلاسيكية لأم الدم الأبهرية البطنية المتمزقة؟","b":"ألم بطني/ظهر (يتشعع للحفرتين الحرقفيتين أو المغبنين)، انهيار/صدمة، كتلة بطنية نابضة متوسعة — فكّر بها دائمًا لدى أي ذكر >65 سنة بألم ظهر/خاصرة غير مفسّر."},{"f":"برنامج المسح (screening) لأم الدم الأبهرية البطنية؟","b":"كل الذكور بعمر 65 سنة يُدعَون للمسح بالإيكو (في المملكة المتحدة)؛ يُنقص الوفيات من المتمزقة."},{"f":"استطبابات الإصلاح الانتخابي لأم الدم الأبهرية البطنية؟","b":"قطر ≥5.5cm، أو توسّع بمعدل >1cm/سنة، أو أم دم عرضية — خطورة التمزق تحت 5.5cm أقل من 1%/سنة مقابل ~15%/سنة فوق 6cm."},{"f":"التدبير الإسعافي لأم الدم الأبهرية البطنية المتمزقة؟","b":"استدعاء جراح وعائي ومخدّر خبير وإنذار غرفة العمليات؛ قنيتان وريديتان واسعتا التجويف؛ دم O Rh- إن لم يُطابَق؛ إبقاء الضغط الانقباضي ≤100mmHg؛ CT أبهرية فورية للتخطيط؛ EVAR الخيار الأول إذا كان مناسبًا تشريحيًا."},{"f":"العرض الكلاسيكي لتسلخ الأبهر الصدري؟","b":"ألم صدري مُمزِّق مفاجئ ± امتداد إلى الظهر؛ وقد ينسدّ فروع الأبهر بالتتابع مسببًا: شلل نصفي، نبضًا وضغطًا غير متساويين في الذراعين، إقفارًا حادًا في الطرف، قصور الصمام الأبهري."},{"f":"تصنيف ستانفورد لتسلخ الأبهر؟","b":"النوع A (~70%): يشمل الأبهر الصاعد أو القوس — حالة إسعافية (وفيات ~30% في أول 24 ساعة، >1%/ساعة) تتطلب إحالة فورية لجراحة القلب والصدر. النوع B: لا يشمل الصاعد/القوس — يُعالَج تحفظيًا أولًا إذا غير مختلط."},{"f":"التدبير الدوائي لتسلخ الأبهر من النوع B؟","b":"ضبط صارم لضغط الدم في العناية المشددة خلال أول 48 ساعة: لابيتالول أو إسمولول (نصف عمر فائق القصر) بالتسريب الوريدي؛ التشخيص بـCT أو تخطيط صدى عبر المريء (TOE)."},{"f":"أم دم المأبضية (popliteal): ما اختلاطها الرئيسي؟","b":"الخثار (متظاهرًا كطرف حاد الإقفار) أو الصمّات الخثارية البعيدة — لا التمزق (عكس الأبهرية البطنية)."},{"f":"كتلة نابضة مجسوسة بعد أسابيع من جرح قاطع في الفخذ — التشخيص؟","b":"أم دم كاذبة (pseudoaneurysm) — تجمع دم في البرانية يتواصل مع اللمعة بعد الرض."}]},{"t":"المتلازمات الوعائية والتهابات الشرايين","cards":[{"f":"داء برغر (Buerger's disease): الصورة النموذجية؟","b":"التهاب وخثار غير عصيدي في الأوردة والشرايين متوسطة الحجم، مرتبط بالتدخين، يسبب التهاب وريد خثاري وإقفارًا (قرحات/غنغرينا)؛ عادة ذكور 20-45 سنة؛ الإقلاع عن التدخين حيوي."},{"f":"تعريف النوبة الإقفارية العابرة (TIA)؟","b":"نوبة حادة من عجز عصبي بؤري (دماغي أو بصري) تزول خلال 24 ساعة."},{"f":"العمى الأحادي العابر (amaurosis fugax): الوصف والآلية؟","b":"فقد بصري أحادي عابر يوصف «كستارة تنزل على العين» لثوانٍ أو دقائق — انسداد الشريان الشبكي المركزي بصمّة من لويحة السباتي (قد يؤدي لعمى دائم)."},{"f":"خطورة السكتة بعد TIA؟","b":"~18% في السنة الأولى، 10% في أول 90 يومًا، 4% في أول 24 ساعة — و80% من الـTIAs في الإقليم السباتي."},{"f":"استطباب استئصال باطنة الشريان السباتي (CEA)؟","b":"مرضى عرضيون بتضيق >70% في السباتي الباطن (أو >50% مع TIA/سكتة حديثة وABCD2 عالٍ)؛ يُجرى عاجلًا خلال أسبوعين من الحدث."},{"f":"الاستقصاء الأول في نقص التروية الدماغية المشتبه بمنشأ سباتي؟","b":"مسح دوبلر ملوّن لجميع مرضى TIA/سكتة خلال 6 أشهر؛ ثم MRA أو CTA عند عدم حسم الدوبلر أو صعوبته."},{"f":"العلاج الدوائي الأمثل لداء السباتي؟","b":"مضاد صفيحات (أسبرين ± ديبيريدامول)، إيقاف التدخين، ضبط الضغط والسكر، ستاتين (سيمفاستاتين 40mg يوميًا) بغض النظر عن الكولسترول الأساسي."},{"f":"اختبار برغر وزاويته: ماذا يقيسان؟","b":"اختبار برغر: رفع الساقين 45° فوق الأفقي دقيقة فيشحب لون الساقين. زاوية برغر: الزاوية فوق الأفقي التي يحدث عندها الشحوب — <20° تعني إقفارًا شديدًا."},{"f":"التهاب الشريان ذو الخلايا العملاقة (GCA): الثلاثية السريرية والتدبير؟","b":"صداع صدغي + عرج الفك (ألم المضغ) + إيلام الفروة، مع ESR مرتفع — حالة إسعافية: ستيروئيدات عاجلة (خطر العمى)."},{"f":"متلازمة سرقة تحت الترقوة (Subclavian steal): الآلية والأعراض؟","b":"تضيق الشريان تحت الترقوة قريبًا من منشأ الفقرية؛ عرج الذراع يعكس الجريان في الشريان الفقري → نقص تروية الدماغ الخلفي (دوار/إغماء)."}]},{"t":"أمراض الأوردة والأوعية اللمفية","cards":[{"f":"ثالوث فيرخاو (Virchow's triad) لتشكل الخثار الوريدي؟","b":"شذوذ جدار الوريد + ركودة/بطء الجريان (الجمود، الرض، الجراحة، السفر الطويل) + فرط التخثر (وراثي: عامل V لايدن، نقص بروتين C/S أو أنتي ثرومبين؛ مكتسب: خباثة، حبوب منع الحمل، تدخين، تجفاف)."},{"f":"الأعراض والعلامات السريرية للخثار الوريدي العميق (DVT)؟","b":"قد تكون غائبة؛ تورم الطرف، ألم، احمرار وسخونة باللمس، حمى خفيفة وتسرع قلب؛ علامة هومان (ألم الربلة بالثني الظهري) غير موثوقة ويجب عدم إجرائها."},{"f":"الاستقصاء المختار لتشخيص DVT؟ وللاشتباه بالصمّة الرئوية؟","b":"الدوبلر (duplex) هو استقصاء الاختيار لـDVT (يُظهر التشريح ومدى الخثار وقابلية انضغاط الوريد). للصمّة الرئوية: CT تصوير الأوعية الرئوية (CTPA) الأكثر حساسية ونوعية."},{"f":"علاج DVT غير المختلط؟","b":"هيبارين منخفض الوزن الجزيئي (LMWH) أولًا ثم مضاد تخثر فموي (وارفارين) لمدة 3-6 أشهر؛ مع الرفع والترطيب الجيد."},{"f":"استطبابات مرشح الوريد الأجوف (IVC filter)؟","b":"صمّات رئوية ناكسة رغم العلاج، أو خطر صمّة مركزية كبيرة مع مضاد استطباب للتمييع، أو حاجة لجراحة كبرى عاجلة، أو DVT كبير مع إصابة CNS أو كسور كبرى."},{"f":"أخطر اختلاطين للخثار الوريدي العميق؟","b":"الصمّة الرئوية (PE)، والغنغرينا الوريدية (phlegmasia caerulea dolens — خثار إربي فخذي شديد)."},{"f":"آلية تشكل الدوالي (varicose veins) وعوامل الخطورة؟","b":"قصور صمامات الأوردة السطحية → قلس الدم من العميق → ارتفاع الضغط الوريدي وتوسع السطحية. عوامل الخطورة: الوقوف المطوّل، البدانة، الحمل، القصة العائلية، حبوب منع الحمل."},{"f":"علامات القصور الوريدي المزمن الجلدية؟","b":"وذمة، أكزيما، تصبغ بالهيموسيدرين، تصلّب الجلد الشحمي (lipodermatosclerosis)، ضمور أبيض (atrophie blanche)، قرحات (الأشيع أنسية فوق الكعب)."},{"f":"أشيع موضع للقرحة الوريدية؟ وشرط الضماد الضاغط؟","b":"الجانب الأنسي فوق الكعب الداخلي. الضماد متعدد الطبقات (أربع طبقات) إذا كان ABPI >0.85 — حتى 75% شفاء خلال 12 أسبوعًا."},{"f":"الوذمة اللمفية المزمنة (الفيلية): ما العلاج الجراحي؟","b":"لا توجد عملية مُرضية؛ يُستأصل النسيج تحت الجلدي الشاذ ويُغطَّى الجزء بطُعم جلدي مشقوق — النتائج مقبولة لكنها غير تجميلية."},{"f":"هل الدوالي وحدها تسبب DVT؟","b":"لا — الدوالي وحدها لا تسبب DVT (إلا ربما التهاب الوريد الخثاري السطحي المنتشر قرب الصافن الطويل)."},{"f":"التدبير التحفظي للدوالي؟","b":"تجنّب الوقوف المطوّل، رفع الساقين، الجوارب الداعمة، إنقاص الوزن، مشي منتظم (عمل العضلة الربلية يساعد العود الوريدي)."}]}]},{"s":"الجراحة البولية","topics":[{"t":"إنتانات الجهاز البولي، سل السبيل البولي، وزرع الكلية","cards":[{"f":"الفرق بين البيلة الجرثومية وإنتان المسالك البولية؟","b":"البيلة الجرثومية: جراثيم في البول قد تكون لاعرضية — وهي ليست مرضًا. إنتان المسالك: بيلة جرثومية + سمات سريرية (التهاب مثانة/بروستات = سفلي، التهاب حويضة وكلية = علوي)."},{"f":"أشيع جرثوم مسبب لالتهاب المسالك البولية المجتمعي؟","b":"الإشريكية القولونية E. coli (70-95% في المجتمع)، ثم المكورات العنقودية الرمّية Staphylococcus saprophyticus (5-10%)."},{"f":"الأعراض الكلاسيكية لالتهاب الحويضة والكلية الحاد؟","b":"حمى وقشعريرة وإقياء، ألم/إيلام الخاصرة وألم ضلعي فقري، مع أعراض التهاب مثانة مرافقة — وقد يتطور لصدمة إنتانية."},{"f":"الاستقصاء الأدق لتشخيص التهاب الحويضة والكلية؟","b":"التقييم السريري + زرع البول (MSU)؛ زرع الدم إيجابي في 10-25% فقط. يُفكَّر بالتصوير (USS/CT) عند عدم الاستجابة أو النكس غير المفسّر أو جرثوم غير معتاد."},{"f":"التهاب مثانة مزمن مُعند على المعالجة الصحيحة مع بيلة قيحية عقيمة — التشخيص الأكثر احتمالًا؟","b":"سل المسالك البولية: بيلة قيحية عقيمة + عسر تبول وتكرار وألم فوق العانة مع زرع قياسي سلبي؛ اسأل عن التوعك والحمى والتعرق الليلي ونقص الوزن."},{"f":"كيف يُشخَّص سل المسالك البولية؟ وعلاجه؟","b":"بالمجهر بتقنيات الصبغ المقاوم للحمض وزرع المتفطرات لعينة MSU صباحية باكرة و/أو نسيج السبيل البولي. العلاج: ريفامبيسين + إيزونيازيد 6 أشهر مع بيرازيناميد + إيثامبوتول أول شهرين."},{"f":"اختلاطات السل البولي التناسلي المزمن؟","b":"تليّف وتضيّقات (قد تسبب انسدادًا)، عقم، تقرّح تناسلي — الورم الحبيبي يسبب تليفًا."},{"f":"أي كلية تُؤخذ أشيع في زراعة الكلية من متبرع حي؟ ولماذا؟","b":"الكلية اليسرى — لأن وريدها الكلوي أطول (قاعدة حرف L: Left في Living donor transplantation لأنها ذات وريد Longer)."}]},{"t":"الحصيات البولية، انسداد الطرق البولية، والأسر البولي","cards":[{"f":"المواضع النموذجية الثلاثة لترسّب حصيات السبيل البولي؟","b":"الملتقى الحويضي الحالبي، حافة الحوض (الأوعية الحرقفية)، والملتقى المثاني الحالبي."},{"f":"أنماط حصيات الكلية ونسبها؟","b":"أكسالات الكالسيوم 75% (شائك، كثيف للأشعة)، فوسفات الأمونيوم المغنيزيوم (ستروفيت) 15% (قرن الوعل، مع خمج بالمتقلبة Proteus)، حمض البول 5% (أملس، شفاف للأشعة)، سيستين 1%."},{"f":"وصف ألم المغص الكلوي وما يميزه؟","b":"تشنجات مبرحة «من الخاصرة إلى المغبن» (± الأعضاء التناسلية/الفخذ الأنسي) مع غثيان/إقياء؛ المريض لا يستطيع الاستلقاء بسكون (يميز عن التهاب الصفاق)."},{"f":"استقصاء الخيار الأول لتصوير الحصيات البولية؟","b":"الطبقي المحوري (CT) دون حقن — 99% من الحصيات مرئية ويساعد في استبعاد التشخيصات التفريقية للبطن الحاد."},{"f":"التسكين الأولي للمغص الكلوي؟","b":"ديكلوفيناك 75mg وريديًا/عضليًا أو 100mg شرجيًا (أفيونات إذا مضاد استطباب) + سوائل وريدية إذا لم يتحمّل فمويًا."},{"f":"حصاة <5mm في أسفل الحالب: ما مصيرها؟","b":"~90-95% تعبر عفويًا؛ يُشجَّع الإكثار من السوائل + معالجة دوائية طاردة (تامسولوسين 0.4mg/يوم أو نيفيديبين) — معظمها يعبر خلال 48 ساعة."},{"f":"أفضل علاج لحصيات الكلية الكبيرة >2.5cm؟","b":"استخراج حصيات الكلية عبر الجلد (PCNL) — جراحة ثقب مفتاح للحصيات الكبيرة أو المتعددة أو المعقدة (كحصاة قرن الوعل)."},{"f":"تفتيت الحصاة بالموجات الصادمة خارج الجسم (ESWL): متى؟ وآثاره الجانبية؟","b":"للحصيات <1cm؛ آثار جانبية: أذية كلوية، وقد تسبب ارتفاع ضغط وDM."},{"f":"استطبابات التدخل العاجل في الحصيات البولية؟","b":"خمج + انسداد (التأخير يقتل الكبيبات — يلزم فغر كلية عبر الجلد أو دعامة حالبية)، إنتان بولي (urosepsis)، ألم/إقياء مستعصٍ، قصور كلوي حاد وشيك، انسداد في كلية وحيدة، حصيات سادّة ثنائية."},{"f":"الوقاية النوعية من حصيات الكالسيوم وحمض البول والسيستين؟","b":"الكالسيوم: ثيازيد في فرط كالسيوم البول. حمض البول: ألوبورينول + قلونة البول. السيستين: إماهة قوية (نتاج بول >3L/يوم) + قلونة البول + بنسيلامين."},{"f":"انسداد أسفل الحالب: ما أعراضه المميزة؟","b":"أعراض تهيّج مثانة + ألم في الصفن أو ذروة القضيب أو الشفرين الكبيرين."},{"f":"تقيّح الكلية (pyonephrosis): ما هو؟","b":"استسقاء كلوي مُخمَج — خمج + انسداد = حالة إسعافية تستلزم تخفيف الانسداد عاجلًا."}]},{"t":"رضوض وأذيات السبيل البولي (الكلية، الحالب، المثانة، والإحليل)","cards":[{"f":"نسبة رضوض الكلية بين كل الرضوض؟ ومعظمها يُدبَّر كيف؟","b":"حتى 5% من كل الرضوض (أشيع لدى الذكور الشباب)؛ معظم الإصابات يمكن تدبيرها تحفظيًا مع حفظ العضو بنجاح."},{"f":"تصنيف AAST لرض الكلية: ما الدرجات العالية؟","b":"الدرجة 4: تمزق متنية يمتد لجهاز التجميع مع تسرّب بولي، أو إصابة وعائية قطعية. الدرجة 5: كلية مهشّمة، أو تمزق/اقتلاع الشريان أو الوريد الكلوي الرئيسي."},{"f":"البيلة الدموية في رض الكلية: هل غيابها ينفي إصابة كبرى؟","b":"لا — البيلة الدموية (مرئية أو لا) هي الموجودة المفتاحية، لكن إصابات كبرى كتمزق الوصل الحويضي الحالبي أو إصابات السويقة أو الخثار الشرياني القطعي قد لا تترافق ببيلة دموية."},{"f":"أسهل وسيلة تشخيصية أولية في رضوض الكلية؟","b":"شريط البول (dipstick) يقيّم البيلة الدموية بسرعة (لكن نتائج سلبية كاذبة 3-10%)؛ والتقييم النهائي للمريض المستقر بالطبقي المحوري (CT) وفق بروتوكول الرضوض."},{"f":"علامات أذية الإحليل الرضية؟","b":"دم عند الصماخ، بيلة دموية مرئية، ألم عند التبول أو عجز عن التبول، تورم العجان وورم دموي يشمل الصفن؛ بالفحص الشرجي قد تكون البروستات والمثانة مزاحتين للأعلى (في أذية الإحليل الغشائي)."},{"f":"الاستقصاء الشعاعي المطلوب عند الاشتباه بأذية إحليلية؟","b":"تصوير الإحليل الراجع (retrograde urethrogram) يشمل كامل طول الإحليل وعنق المثانة."},{"f":"ممنوع في أذية الإحليل المشتبهة؟","b":"لا تُدخِل قثطرة إحليلية عمياء — إذا لم تمر بسهولة أجرِ تصوير الإحليل الراجع فورًا؛ البديل الآمن: تحويل بولي فوق العانة."},{"f":"تكثر أذيات الإحليل بعد ماذا؟","b":"كسور الحوض (الإحليل الخلفي/الغشائي) ورضوض العجان الشديدة (إصابة امتطاء straddle للإحليل البصلي)."},{"f":"تدبير أذية الإحليل البصلي (straddle injury)؟","b":"تحفظي عادة بقثطرة إحليلية — الخيار الأفضل لمنع نزف الإحليل والألم عند التبول."}]},{"t":"ضخامة البروستات الحميدة والمثانة العصبية","cards":[{"f":"ضخامة البروستات الحميدة (BPH): أي منطقة تتضخم؟ وما الفرق عن السرطان؟","b":"تتضخم المنطقة الانتقالية (الباطنة) بتكاثر عقدي/منتشر حميد للطبقات العضلية الليفية والغدية — مقابل توسع الطبقة المحيطية في سرطان البروستات."},{"f":"أعراض السبيل البولي السفلي (LUTS) في BPH؟","b":"بوال ليلي، تواتر، إلحاح، تقطير بعد التبول، ضعف تيار/جريان، تردد، سلس فيضي، بيلة دموية، حصيات مثانة، UTI."},{"f":"تقييم مريض BPH: ما الاختبارات؟","b":"MSU، U&E، أمواج فوق صوتية (حجم البروستات + المتبقي)، تحرّي استسقاء الكلية، PSA قبل الفحص الشرجي، US عبر المستقيم ± خزعة عند الاشتباه."},{"f":"الخط الأول الدوائي في BPH؟","b":"حاصرات ألفا (تامسولوسين 400mcg/يوم، ألفوزوسين، دوكسازوسين، تيرازوسين) — تُرخي العضلات الملساء في البروستات والمثانة."},{"f":"مثبطات 5α-ريدوكتاز في BPH: مثال وآلية وفائدة؟","b":"فيناسترايد 5mg/يوم: يمنع تحويل التستوستيرون إلى ثنائي هيدروتستوستيرون؛ يُنقص حجم البروستات خلال 3-6 أشهر ويُنقص خطورة الاحتباس طويل الأمد — ويُخفّض PSA (تذكّر عند التفسير)."},{"f":"متلازمة ما بعد TURP: الآلية والتظاهر؟","b":"امتصاص سائل الغسل أثناء استئصال البروستات عبر الإحليل → اضطراب عصبي مركزي وقلبي وعائي + نقص صوديوم الدم وانخفاض الحرارة."},{"f":"متى يُفضَّل شق البروستات عبر الإحليل (TUIP) على TURP؟","b":"للغدد الصغيرة <30g — تخريب أقل وخطورة أقل على الوظيفة الجنسية مع فائدة مشابهة."},{"f":"اختلاطات TURP التي يجب ذكرها في الموافقة؟","b":"نزف/بيلة دموية، خمج، ضعف انتصاب ~10%، سلس ≤10%، تضيق إحليلي، احتباس خثري، متلازمة ما بعد TURP."},{"f":"المثانة العصبية الرخوة: الآلية والصفات؟","b":"إصابة القوس الانعكاسية العجزية (S2-S4) → غياب تام لتقلصات العضلة الدافعة (areflexia) مع سعة كبيرة وجدار رقيق وركودة بولية — تُدبَّر بالقثطرة المتقطعة النظيفة."},{"f":"تدبير المثانة العصبية التشنجية؟","b":"فرط نشاط الدافعة: تفريغ دائم بالقثطرة + صادات للإنتانات البولية المتكررة + خزع المعصرة عند الذكور لتخفيف الضغط وحماية الكلى، أو توسيع المثانة بعروة معوية."},{"f":"لماذا يُمنع خزع المعصرة عند الإناث في المثانة التشنجية؟","b":"لأنه يسبب سلسًا بوليًا تامًا دائمًا — إذ يستحيل وضع كيس تجميع خارجي لديهن؛ يُجرى عند الذكور فقط."}]},{"t":"التشوهات الخلقية البولية وأمراض الكلية الكيسية","cards":[{"f":"صمامات الإحليل الخلفية (PUV): ما هي؟","b":"بقايا غشائية في الإحليل الخلفي (البروستاتي) عند الذكور؛ أشيع سبب لانسداد مخرج المثانة عند الرضع الذكور — تُشخَّص قبل الولادة بموه كلية ثنائي ومثانة متوسعة/سميكة الجدار بالإيكو."},{"f":"نتائج انسداد صمامات الإحليل الخلفية على السبيل البولي؟","b":"توسع الإحليل القريب، تضخم وتشقق جدار المثانة، جزر مثاني حالبي مرافق، ودرجات متفاوتة من خلل تنسج الكلية — والانسداد الشديد في الجنين مرتبط بقلة السائل الأمنيوسي."},{"f":"صمامات الإحليل الخلفية حسب غولدمان-سيسيل: الآلية؟","b":"أشيع سبب لانسداد مخرج المثانة عند الرضع الذكور مع موه كلية ثنائي وحالبين ضخمين؛ الانسداد ناتج عن خلل امتصاص الطيات المخاطية في الإحليل الخلفي قاصيًا للحديبة المنوية."},{"f":"الجزر المثاني الحالبي (VUR): التعريف والآلية؟","b":"جريان راجع للبول من المثانة نحو المسالك البولية العليا؛ أولي بسبب إدخال شاذ للحالب في جدار المثانة (الوصلة الحالبية المثانية) أو ثانوي لضغط مثاني مرتفع شاذ — يزيد خطر إنتانات المسالك المتكررة."},{"f":"نظام التجميع المزدوج (Duplex): ما ارتباطاته؟","b":"تشعب البرعم الحالبي قبل دخوله الأرومة الكلوية؛ مرتبط بشدة بالجزر المثاني الحالبي و/أو انسداد الحالب، وزيادة خطر إنتان المسالك — يظهر غالبًا بموه الكلية."},{"f":"أشيع سبب لالتهاب بولي ناكس مزمن عند طفلة ~5 سنوات؟","b":"الجزر المثاني الحالبي (VUR) — يُشتبه به عند كل إنتان بولي ناكس في الأطفال ويُقيَّم بالتصوير."},{"f":"متلازمة برون-بيللي (prune-belly): الثلاثية؟","b":"غياب/نقص خلقي في عضلات جدار البطن + توسع حالبي ضخم وتثخن جدار المثانة + نقص تنسج البروستات وخصيتان غير نازمتين ثنائيًا — تُعبَّر كاملة لدى الذكور فقط."},{"f":"جزر المثانة الخارجي (bladder exstrophy): ما هو؟","b":"خلل إغلاق خط وسطي يشمل جدار البطن السفلي والمثانة والأعضاء التناسلية الخارجية؛ نجاح إعادة بناء المثانة يرتبط بحفظ الوظيفة الكلوية طويل الأمد."},{"f":"تضيق الوصل الحويضي الحالبي (UPJ): متى تستطب الجراحة المبكرة؟","b":"عند تدهور الوظيفة الكلوية أو أعراض مستمرة (ألم/إنتان) أو توسع متفاقم — التقييم بالتصوير الوظيفي (الومضاني)."},{"f":"الكلية متعددة الكيسات أحادية الجانب: ما مصيرها؟","b":"كلية غير عاملة متعددة الكيسات؛ معظمها تضمر تلقائيًا وتُتابَع بالتصوير — الاستئصال عند الشك أو الاختلاطات."}]},{"t":"أورام الجهاز البولي والأعضاء التناسلية الذكرية","cards":[{"f":"سرطانة الخلايا الكلوية (RCC): المنشأ والوبائيات؟","b":"تنشأ من ظهارة النبيبات الكلوية الدانية؛ تشكل 90% من سرطانات الكلية؛ متوسط العمر 65 سنة؛ ذكور:إناث ~2:1."},{"f":"التظاهر الكلاسيكي لسرطانة الخلايا الكلوية؟","b":"50% تُكتشَف عرضًا؛ بيلة دموية + ألم خاصرة + كتلة بطنية (± فقد وزن وحمى مجهولة السبب) — غالبًا منفردة لا ثلاثية كاملة؛ 25% لديهم نقائل عند التظاهر."},{"f":"علامة مميزة: قيلة دوالية يسارية حديثة عند مسن — فكّر بماذا؟","b":"سرطانة خلايا كلوية يسرى: غزو الوريد الكلوي الأيسر يضغط الوريد الخصوي الأيسر مسببًا قيلة دوالية لا تفرغ بالاستلقاء."},{"f":"علاج سرطانة الخلايا الكلوية الموضعة؟","b":"استئصال كلية جذري (جراحة الحفاظ على النفرون بجودته لأورام T1 وتحفظ الوظيفة الكلوية) — الورم مقاوم عمومًا للشعاعية والكيميائية."},{"f":"سرطان البروستات: النسيج الأشيع والانتشار؟","b":"أشيع خباثة ذكرية؛ معظمها سرطانات غدية ناشئة في المنطقة المحيطية؛ الانتشار اللمفي/الدموي يعطي آفات عظمية مُصلِّبة (sclerotic)."},{"f":"نقائل عظمية من سرطان بروستات: الإجراء الأول؟","b":"المعالجة الهرمونية (ناهضات LHRH كغوسيريلين — مع مضاد أندروجين أولًا لمنع التوهج الورمي) ± معالجة شعاعية موضعية للألم/انضغاط النخاع."},{"f":"ما الذي يرفع PSA غير السرطان؟","b":"تضخم البروستات الحميد، القذف الحديث، الفحص الشرجي، التهاب البروستات، UTI — وتخفضه مثبطات 5α-ريدوكتاز (فيناسترايد). ~76% من الـPSA المرتفع ليست سرطانًا."},{"f":"النسيج الأشيع لسرطان المثانة؟ والتظاهر؟","b":">90% سرطانات خلايا انتقالية (TCC)؛ التظاهر: بيلة دموية غير مؤلمة + التهابات بولية متكررة + تهيّج تبولي."},{"f":"علاج سرطان المثانة غير الغازي للعضلة (Ta/T1/Tis)؟","b":"استئصال ورم المثانة عبر الإحليل (TURBT) + BCG داخل المثانة للأورام المتعددة أو عالية الدرجة (يحرّض استجابة مناعية)؛ البقيا 5 سنوات ~95%."},{"f":"علاج سرطان المثانة الغازي للعضلة (T2-T3)؟","b":"استئصال المثانة الجذري هو «المعيار الذهبي»؛ المعالجة الشعاعية تحفظ المثانة لكن ببقيا أسوأ؛ الكيميائية المساعدة (M-VAC أو GC) تحسّن البقيا."},{"f":"عوامل خطورة سرطان المثانة؟","b":"التدخين، الأمينات العطرية (صناعة المطاط)، التهاب المثانة المزمن، البلهارسيا (↑ سرطانة الخلايا الشائكة)، تشعيع الحوض."},{"f":"ورم ويلمز: ما هو؟","b":"ورم أرومي كلوي طفولي من النبيبات الكلوية البدائية؛ أشيع خباثة بطنية لدى الأطفال (1:100,000)؛ يتظاهر بكتلة بطنية وبيلة دموية."}]},{"t":"آفات الخصية وكيس الصفن، العقم الذكري، واعتلالات الذكورة","cards":[{"f":"التواء الخصية: النافذة الزمنية للإنقاذ؟","b":"جراحة عاجلة: إذا أُجريت خلال <6 ساعات فمعدل الإنقاذ 90-100%؛ وإذا تجاوزت 24 ساعة فهو 0-10% — عند أي شك يلزم الاستكشاف الجراحي."},{"f":"التظاهر الكلاسيكي لالتواء الخصية؟","b":"بداية مفاجئة لألم في إحدى الخصيتين يجعل المشي مزعجًا + ألم بطن وغثيان/إقياء؛ الخصية مؤلمة جدًا وساخنة ومتورمة، قد تستلقي عاليًا وبشكل مستعرض؛ أشيع بين 11-30 سنة."},{"f":"التشخيص التفريقي الرئيسي لالتواء الخصية؟","b":"التهاب البربخ والخصية: المريض أكبر سنًا عادة، أعراض إنتان بولي مرافقة، بداية ألم أكثر تدرجية."},{"f":"دور الدوبلر في التواء الخصية؟","b":"دوبلر US قد يُظهر غياب الجريان الدموي — يُجرَى فقط إذا كان التشخيص ملتبسًا، ولا يجوز أن يؤخر الاستكشاف الجراحي."},{"f":"علاج التواء الخصية جراحيًا؟","b":"كشف الخصية وفك الالتواء؛ إذا بدا لونها جيدًا أُعيدت للصفن مع تثبيت ثنائي (orchidopexy) للخصيتين — مع الموافقة على استئصال محتمل."},{"f":"بعد فشل الرد اليدوي لانفتال الخصية: المعالجة؟","b":"استكشاف جراحي عاجل + تثبيت — الرد اليدوي محاولة أولية فقط ولا يغني عن التثبيت الجراحي."},{"f":"اختلاطات الخصية غير النازلة؟","b":"العقم، ↑ خطورة سرطان الخصية ~40 ضعفًا (تبقى بعد الجراحة لكن التشخيص أسهل)، ↑ خطورة الرض والالتواء، وترتبط بالفتوق (بقاء الناتئ الغمدي >90%)."},{"f":"أشيع مكان للخصية الهاجرة (ectopic)؟","b":"الجيب المغبني العلوي (أمام سفاق العضلة المائلة الظاهرة) — وقد تكون بطنية أو عجانية أو قضيبية أو في المثلث الفخذي."},{"f":"علاج الخصية غير النازلة؟","b":"تثبيت الخصية (orchidopexy) جراحيًا في الرضاعة (جيب دارتي) — يعيد إمكانية تكوين النطاف ويجعل تشخيص الخباثة أسهل."},{"f":"كتلة صفنية: كيف تفرّق بين القيلة المائية وورم الخصية بالفحص؟","b":"الشفوفية (transillumination): القيلة المائية تُنير بالضوء، ورم الخصية الصلب لا يُنير؛ US الصفن هو الاستقصاء المختار لتمييز الكتل داخل الخصية عن خارجها."},{"f":"كتلة خصية صلبة مشتبهة: ما الممنوع؟ والعلاج؟","b":"ممنوع الخزعة عبر الصفن! الاستئصال الجذري للخصية عبر المغبن + زرع بدلة."},{"f":"الواصمات الورمية في أورام الخصية/الخلايا الجرثومية؟","b":"αFP وhCG — للتشخيص ومراقبة استجابة العلاج وكشف النكس والإنذار."}]}]},{"s":"جراحة الأورام","topics":[{"t":"جراحة أورام الغدة الدرقية وجارات الدرق","cards":[{"f":"أنماط سرطان الدرق ونسبها؟","b":"الحليمي 60% (الأشيع، في الأصغر سنًا)، الجرابي ≤25% (منتصف العمر)، اللبي 5%، اللمفوما 5%، الكشمي نادر (مسنون، استجابة ضعيفة لأي علاج)."},{"f":"سرطان الدرق الحليمي: الانتشار والعلاج؟","b":"ينتشر للعقد اللمفاوية والرئة (نقيلة العقدة الوداجية ذات البطنين تُسمى «الدرقية الشاذة الجانبية»). العلاج: استئصال درق كلي ± استئصال عقد ± يود مشع 131I لاجتثاث الخلايا المتبقية + ليفوثيروكسين لكبت TSH."},{"f":"سرطان الدرق الجرابي: ما يميزه؟","b":"ينتشر مبكرًا عبر الدم (العظام والرئتان) لا اللمف؛ متمايز جيدًا. العلاج: استئصال درق كلي + كبت T4 + اجتثاث باليود المشع."},{"f":"سرطان الدرق اللبي: الواسم الورمي والتحذيران الجراحيان؟","b":"ينتج الكالسيتونين (واسم ورمي)؛ لا يقبط اليود. ⚠ قبل الجراحة: مسح لورم القواتم (pheochromocytoma) — فرادي 80% أو جزء من MEN2. العلاج: استئصال درق + تنظيف عقد."},{"f":"الدراسة المخبرية في العقدة الدرقية الوحيدة: متى يُستطب FNA موجه بالإيكو؟","b":"في كل عقدة ≥1cm صلبة/مختلطة مع قصة سابقة لسرطان درق أو تشعيع عنق أو قصة عائلية لسرطان لبي، وفي كل عقدة مع عقد لمفاوية عنقية شاذة — لا يُستطب في الآفات الكيسية الصرفة أو العقد <1cm."},{"f":"بعد 36 ساعة من استئصال درق تام: تكزز شديد — العلاج الإسعافي؟","b":"غلوكونات الكالسيوم 10% وريديًا: 10mL (2.25mmol) خلال 30 دقيقة وتُكرر حسب الحاجة ± تسريب وريدي — السبب: قصور الدريقات بعد الجراحة."},{"f":"بعد ساعات من استئصال الدرق: ضيق تنفس شديد + تورم عنق — أول إجراء؟","b":"فتح الجرح وإخلاء الورم الدموي العنقي فورًا عند السرير (ورم دموي ضاغط على الرغامى) — حالة إسعافية قبل أي تصوير."},{"f":"استطبابات استئصال الدرق؟","b":"أعراض انضغاطية، نكس فرط الدرقية بعد كورس فاشل من العلاج الدوائي، السرطانة، أسباب تجميلية، مريضات عرضيات يخططن للحمل."},{"f":"في داء غريفز: متى تُوصَف الجراحة؟","b":"عند نكس فرط الدرقية بعد فشل العلاج الدوائي، أو الأعراض الانضغاطية (دراق كبير)، أو عدم تحمل/مضاد استطباب اليود المشع — مع جعل المريض سوي الدرقية قبل الجراحة بمضادات الدرق."},{"f":"البنى المعرضة للأذية في جراحة الدرق؟","b":"العصب الحنجري الراجع (بحة/صوت أجش)، العصب الحنجري العلوي، الغدد جارات الدرق (قصور الدريقات → تكزز)، الرغامى، الشريان السباتي الأصلي، الوريد الوداجي الباطن."},{"f":"فرط نشاط الدريقات الأولي: السبب الأشيع والتظاهر؟","b":"ورم غدي وحيد ~80% (فرط تنسج كل الغدد ~20%). التظاهر: غالبًا لاعرضي مع فرط كالسيوم مكتشف روتينيًا؛ حصيات كلوية، ألم بطني/قرحات، ألم وكسور عظمية، ضعف وتعب واكتئاب وبوال."},{"f":"تشخيص فرط نشاط الدريقات الأولي مخبريًا؟","b":"فرط كالسيوم الدم + PTH مرتفع أو طبيعي بشكل غير مناسب مع فيتامين D طبيعي + نقص فوسفات الدم ± ارتفاع ALP — مسح MIBI قبل الجراحة يحدد الورم الغدي."},{"f":"استطبابات استئصال الدريقات في فرط نشاطها الأولي؟","b":"فرط كالسيوم دم عرضي، أو كالسيوم مصلي >2.85، أو هشاشة عظام، أو حصيات كلوية، أو تدهور وظيفة كلوية، أو عمر ≤50 سنة، أو فرط كالسيوم البول."},{"f":"اختلاطات استئصال الدريقات؟","b":"قصور الدريقات، أذية العصب الحنجري الراجع (بحة)، نقص كالسيوم عرضي (متلازمة العظام الجائعة)."},{"f":"علامتا تروسو وشفوستك: ماذا تدلان؟","b":"علامتا نقص كالسيوم الدم: تروسو = تشنج رسغي قدمي عند ضغط الشريان العضدي؛ شفوستك = ارتجاف عضلات الوجه بالنقر فوق النكفة (العصب الوجهي)."}]},{"t":"متفرقات الكارسينوييد","cards":[{"f":"الورم السرطاوي (carcinoid): التعريف والمواضع الأشيع؟","b":"ورم عصبي صماوي جيد التمايز من الخلايا المعوية أليفة الكروم، قادر على إنتاج 5HT. المواضع: الزائدة 45%، اللفائفي 30%، المستقيم 20% — وأيضًا القصبات والمبيض والخصية."},{"f":"المتلازمة السرطاوية: متى تحدث؟","b":"تحدث لدى ~5% فقط وتعني إصابة كبدية نقيلية (>90% من المواد الفعالة المفرزة في الدوران البابي تُعطَّل كبديًا — فلا تظهر المتلازمة إلا مع النقائل الكبدية)."},{"f":"أعراض المتلازمة السرطاوية النموذجية؟","b":"تقبض قصبي، احمرار انتيابي خاصة أعلى الجسم (± شرى مهاجر)، إسهال، داء قلبي سرطاوي (قصور ثلاثي الشرف + تضيق رئوي من تليف محرض بـ5HT)."},{"f":"الاختبار التشخيصي للمتلازمة السرطاوية؟","b":"↑ حمض 5-هيدروكسي إندول الخليك البولي 24 ساعة (5-HIAA — مستقلب 5HT) + كروموغرانين A البلازمي (يعكس كتلة الورم)."},{"f":"علاج المتلازمة السرطاوية؟","b":"أوكتريوتيد (نظير السوماتوستاتين) يحصر تحرر وسطاء الورم ويعاكس التأثيرات المحيطية؛ البديل طويل المفعول لانريوتيد؛ لوبراميد للإسهال."},{"f":"النوبة السرطاوية (carcinoid crisis): المحرض والعلاج؟","b":"تفيض الوسطاء عندما يتجاوز الورم ترويته أو يُعالَج كثيرًا أثناء الجراحة → توسع وعائي مهدد للحياة وهبوط ضغط وتسرع قلب وتقبض قصبي. العلاج: أوكتريوتيد عالي الجرعة + تدابير داعمة."},{"f":"علاج الورم السرطاوي نفسه؟","b":"الاستئصال هو الشفاء الوحيد — من الحيوي إيجاد الموقع الأولي؛ الأورام صفراء شديدة أثناء الجراحة؛ مع تغطية أوكتريوتيد لتجنب نوبة سرطاوية هائلة."},{"f":"أي الأعراض ليس نموذجيًا للورم السرطاوي في غياب المتلازمة؟","b":"في غياب المتلازمة السرطاوية الأعراض قليلة: أورام السبيل الهضمي قد تسبب التهاب زائدة أو انغلافًا أو انسدادًا فقط — الاحمرار والإسهال والتقبض القصبي أعراض المتلازمة (مع نقائل كبدية)."}]},{"t":"أسئلة متفرقة","cards":[{"f":"برامج المسح السرطاني السكاني المعتمدة (UK)؟","b":"سرطان الثدي: تصوير شعاعي (mammography) كل 3 سنوات للنساء 50-70 سنة. عنق الرحم: مسحة عنقية كل 3 سنوات (25-50 سنة) وكل 5 سنوات (50-64). القولون: اختبار الدم الخفي بالبراز (FOB) منزليًا 60-75 سنة."},{"f":"أي مما يلي ليس فحصًا مسحيًا للكشف المبكر عن السرطان؟","b":"الفحوص التشخيصية العرضية ليست مسحًا: المسح يُجرى على سكان لاعرضيين (ماموغرافي/مسحة عنق الرحم/FOB) — أما الخزعة أو التصوير لاستقصاء عرض فهو تشخيصي لا مسحي."},{"f":"الكيسة الدرقية اللسانية: العلامة المميزة؟","b":"كتلة خط متوسط تحت العظم اللامي تتحرك للأعلى مع إبراز اللسان (والبلع) — كيس مملوء بالسائل من عدم اكتمال انغلاق مسار هجرة الدرق؛ أشيع كيسة عنقية خلقية؛ العلاج جراحي."},{"f":"كتلة خط متوسط عنقية عند <20 سنة لا تتحرك مع اللسان — الأرجح؟","b":"كيسة جلدانية (dermoid cyst) — أما إذا تحركت للأعلى مع إبراز اللسان فهي درقية لسانية، وإذا >20 سنة فكتلة برزخ الدرق."},{"f":"لماذا يُعد المسح السكاني بـPSA غير موصى به؟","b":"لعدم توازن الخطر/الفائدة: ~76% من الـPSA المرتفع ليست سرطانًا، والمسح يكشف سرطانات لن تسبب أعراضًا (تشخيص مفرط ~40%) مع مخاطر علاج (سلس/ضعف انتصاب) — يُترَك القرار للمريض بعد معلومات كاملة."},{"f":"الواسمات الورمية: αFP وhCG لأي أورام؟","b":"أورام الخلايا الجرثومية/الخصية — للتشخيص ومراقبة استجابة العلاج وكشف النكس والإنذار."},{"f":"الكالسيتونين وασم لأي ورم؟","b":"سرطان الدرق اللبي (medullary) — يُنتَج من الخلايا C ويمكن استخدامه كواسم ورمي للتشخيص والمتابعة."},{"f":"البقيا الوسطية للورم السرطاوي النقيلي؟","b":"5-8 سنوات (~3 سنوات مع النقائل، وقد تصل 20 سنة) — لا تستسلم بسهولة حتى في الداء النقيلي."}]}]},{"s":"الجراحة العامة","topics":[{"t":"أمراض المريء الجراحية","cards":[{"f":"الأكالازيا (achalasia): التعريف والتشخيص الشعاعي؟","b":"فشل استرخاء المصرة المريئية السفلية مع فقد التمعج؛ عسرة بلع مترقية (للسوائل أولًا ثم الصلب) + قلس طعام غير مهضوم. اللقمة الباريتية: توسع المريء مع تضيق أسفله بشكل «منقار الطير» (bird beak)."},{"f":"الاستقصاء المؤكد للأكالازيا؟","b":"قياس ضغط المريء (manometry): منطقة ضغط عالٍ مفرطة التوتر في المصرة السفلية مع فشل الاسترخاء الطبيعي بالبلع — مع تنظير لاستبعاد التضيقات الحميدة والخبيثة."},{"f":"علاج الأكالازيا؟","b":"التوسيع بالبالون تحت التوجيه التنظيري (ناجح حتى 80%)، حقن ذيفان الوشيقية، أو بضع العضلة الجراحي (Heller's cardiomyotomy) تنظيريًا — للحالات المقاومة خاصة الشباب."},{"f":"داء القلس المعدي المريئي (GERD): العملية المختارة ومتى؟","b":"تثنية قاع نيسن (Nissen fundoplication) تنظيريًا — تُستطب عند: أعراض مستمرة رغم العلاج الدوائي الأقصى، قلس حجمي كبير مع خطر ذات رئة استنشاقية، أو اختلاطات (تضيق/تقرح شديد)."},{"f":"سرطان المريء: النسيجان ومواضعهما وعوامل الخطورة؟","b":"الغدي: الثلث السفلي، مرتبط بالـGERD وحؤول باريت، ♂:♀ 5:1. الشائك: أي مكان، مرتبط بالتدخين والكحول والأكالازيا المزمنة والتضيقات الكاوية، ♂:♀ 3:1."},{"f":"عسرة بلع مترقية عند مسن مدخن — التشخيص الأول؟","b":"سرطان المريء حتى يثبت العكس — أي عسرة بلع جديدة خاصة فوق 45 سنة تُعزى للورم حتى نفيه؛ التشخيص بالتنظير المرن + خزعة."},{"f":"متلازمة بورهاف (Boerhaave): الآلية والعلامات؟","b":"تمزق المريء بسبب إقياء عنيف (ضد لسان مزمار مغلق). العلامات: ألم بلع، ضيق نفس، حمى، صدمة، نفاخ جراحي (إحساس بالفرقعة عند جس العنق/الصدر)."},{"f":"تمزقات المريء: أشيع سبب؟ والتدبير؟","b":"الأشيع: علاجية المنشأ (تنظير/خزعة/توسيع 85-90% من الانثقابات) — تُدبَّر محافظًا (أنبوب NG + PPI + صادات). غيرها: إنعاش + صادات + جراحة (تنضير المنصف ووضع أنبوب T)."},{"f":"مريض كحولي مزمن بنزف هضمي صاعق غزير — التشخيص والتدبير الإسعافي؟","b":"نزف دوالي مريئية: دم وريدي غامق غزير سريع البدء. التدبير: إنعاش + OGD عاجل (ربط/تصليب الدوالي حتى 90% نجاح) + تيرليبريسين/أوكتريوتيد وريديًا؛ أنبوب سنغستاكن-بلاكمور مناورة إنقاذية."},{"f":"وفيات أول نزف دوالي مع فرط ضغط بابي مثبت؟","b":"~30% — النزوف الدوالية قد تتدهور بسرعة فائقة (أخبِر HDU/ITU دائمًا)."},{"f":"تشريح المريء: الثلثان العلويان مقابل الثلث السفلي؟","b":"الثلثان العلويان: ظهارة شائكية (سرطان شائك)، عضلات مخططة، تصريف لمفي للعنق والمنصف. الثلث السفلي: ظهارة عمودية (سرطان غدي)، عضلات ملساء، تصريف للعقد المعدية وجانب الأبهر."},{"f":"مفاغرة بابية جهازية عند الموصل المعدي المريئي؟","b":"بين المعدي الأيسر والفرد (hemi-azygous) — قد تتطور دوالٍ مريئية أو معدية عند فرط ضغط الباب."}]},{"t":"أمراض المعدة والعفج الجراحية","cards":[{"f":"سرطان المعدة: العوامل المؤهبة؟","b":"حمية غنية بالنيتروزامينات (سمك مدخن/مخلل)، التهاب المعدة الضموري المزمن، زمرة الدم A، قرحة معدية مزمنة مرتبطة بالملوية البوابية H. pylori."},{"f":"أشيع موضع لنقائل سرطان المعدة؟","b":"العقد اللمفاوية ثم الكبد (نقائل كبدية) والصفاق — علامة تروازييه (عقدة فوق ترقوة يسرى) توحي بانتشار."},{"f":"التظاهر السريري لسرطان المعدة؟","b":"عسر هضم جديد فوق 45 سنة (يُعزى للسرطان حتى نفيه)، نقص وزن وشهية وخمول، فقر دم بعوز الحديد، أحيانًا نزف هضمي علوي حاد."},{"f":"شاب مدخن بألم طاعن شرسوفي مفاجئ + بطن مدافع — التشخيص والتدبير؟","b":"انثقاب قرحة عفجية (أشيع) أو معدية: بطن خشبي (صلابة معممة) + هلال غازي تحت الحجاب على صورة الصدر القائمة. التدبير: إنعاش + إغلاق بالخياطة مع رقعة ثربية + علاج ثلاثي للملوية البوابية."},{"f":"الطريقة المفضلة لتشخيص انثقاب حشا أجوف؟","b":"صورة الصدر القائمة (تبحث عن غاز حر — هلال غازي تحت الحجاب)؛ إذا غير مشخّصة: صورة بطن بالوضع الجانبي الاضطجاعي أو طبقي محوري."},{"f":"تدبير انثقاب القرحة العفجية مقابل المعدية؟","b":"العفجية: إغلاق بالخياطة + رقعة ثربية. المعدية: إغلاق بالخياطة + رقعة إذا قبل بوابية، أو استئصال موضعي + إغلاق إذا في الجسم (لنفي الخباثة)."},{"f":"أورام اللحمة الهضمية (GIST): المنشأ والتظاهر؟","b":"من النسيج المتوسطي لجدار الأمعاء (خلايا العضلات الملساء/الأرومات الليفية)؛ 10% من أورام الأمعاء الدقيقة. التظاهر: كتلة بطنية بطيئة النمو، ألم مبهم، أو نزف هضمي خفي بتقرح الورم."},{"f":"الملوية البوابية (H. pylori) تؤهب لكل مما يلي عدا؟","b":"تؤهب: قرحات المعدة/العفج، سرطان المعدة/اللمفوما (MALT)، — العلاج الثلاثي التجريبي بعد إغلاق انثقاب القرحة العفجية."},{"f":"متى يُلجأ للجراحة النهائية (قطع مبهم/استئصال معدة جزئي) في القرحة؟","b":"فقط عند: انثقاب ناكس، فشل العلاج الدوائي الملتزم تمامًا، أو مريض غير ملتزم متهوّر — الجراحة لم تعد الخط الأول."},{"f":"تصنيف TNM لسرطان المعدة (مبسط)؟","b":"T: عمق الغزو (T1 تحت مخاطية، T2 عضلية، T3 مصلية، T4 أعضاء مجاورة). N: عقد ضمن 3cm (N1) أو أبعد (N2). M: صفاقية P وكبدية H."},{"f":"استطبابات جراحة المعدة؟","b":"سرطان المعدة، القرحات الهضمية المثقوبة/النازفة — والمعالجة الطبية جعلت الجراحة نادرة للقرحة غير المختلطة."}]},{"t":"أمراض الأمعاء الدقيقة الجراحية","cards":[{"f":"العرض الأساسي في التهاب الزائدة الدودية؟","b":"ألم بطني يبدأ مركزيًا (حول السرة) ثم يتوطن في الحفرة الحرقفية اليمنى + فقد شهية وغثيان وحمى خفيفة — العرض الأساسي: الألم."},{"f":"سيدة 25 سنة: ألم حول السرة منذ 10 ساعات تركّز في الحفرة الحرقفية اليمنى — العلامات؟","b":"إيلام نقطة ماكبرني، علامة روفسينغ (جس الحفرة اليسرى يثير ألمًا في اليمنى)، ألم بالسعال والحركة، حمى وتسرع قلب — التشخيص سريري."},{"f":"التشخيص التفريقي لالتهاب الزائدة عند النساء في سن الإنجاب؟","b":"حمل منتبذ، كيسة مبيض، التهاب حوض (PID)، ألم طمثي — يُستطب إيكو حوضي عند الاشتباه بمرض مبيضي."},{"f":"تدبير كتلة/خراج الزائدة (appendix mass)؟","b":"صادات وريدية (سيفيوروكسيم + ميترونيدازول)؛ إذا هدأت الأعراض: استئصال زائدة متأخر (interval) بعد 6 أسابيع؛ الخراج قد يُصرَّف بتوجيه CT."},{"f":"أشيع أسباب انسداد الأمعاء الدقيقة؟","b":"الالتصاقات (حتى 90% ممن لديهم جراحة بطنية سابقة)، ثم الفتوق، ثم الأورام — لهذا لا نتسرع لجراحة انسداد الأمعاء الدقيقة الالتصاقي."},{"f":"السمات الأساسية لانسداد الأمعاء؟","b":"إقياء وغثيان وفقد شهية، مغص مبكر، إمساك مطلق (لا براز ولا ريح) في الانسداد البعيد، انتفاخ يزداد مع أصوات أمعاء نشطة «رنانة»."},{"f":"انسداد أمعاء دقيقة أم غليظة؟","b":"الدقيقة: إقياء مبكر، انتفاخ أقل، ألم أعلى البطن. الغليظة: إمساك مطلق وانتفاخ أبرز (لا غاز في المستقيم على AXR)."},{"f":"التدبير الفوري لانسداد الأمعاء («تسريب وشفط»)؟","b":"أنبوب أنفي معدي + سوائل وريدية لإعادة الإماهة وتصحيح الشوارد + تسكين + NBM (الأمعاء قد تنتج حتى 9L سائل/يوم)."},{"f":"متى تكون الجراحة إسعافية في انسداد الأمعاء؟","b":"عند الاختناق (تأثر التروية): ألم/إيلام ثابت موضّع، ↑WBC، علامات التهاب صفاق وSIRS — أما انسداد الأمعاء الدقيقة الالتصاقي غير المختنق فيُدبَّر محافظًا أولًا."},{"f":"الاحتشاء المساريقي الحاد: الثلاثية السريرية؟","b":"⚠ ألم بطني حاد شديد + علامات بطنية معدومة/دنيا + نقص حجم دموي سريع ← صدمة — خاصة مع رجفان أذيني (انصمام SMA ~35% أو خثار ~35%)."},{"f":"أهم علامة سريرية للإقفار المساريقي الحاد مخبريًا؟","b":"حماض استقلابي مستمر (لاكتات عالٍ) + ↑WBC + أميلاز مرتفع باعتدال — مبكرًا صورة البطن «بطن بلا غاز»."},{"f":"الذبحة المعوية (الإقفار المساريقي المزمن): الثلاثية؟","b":"ألم بطني مغصي شديد بعد الوجبات («عرج الأمعاء») + نقص وزن (الأكل مؤلم) + نفخة بطنية علوية — 95% بسبب تصلب عصيدي في الشرايين المساريقية الثلاثة."},{"f":"أشيع استطباب للجراحة في داء كرون؟","b":"انسداد الأمعاء الدقيقة (من التضيقات) — مع الخراجات والنواسير؛ الداء: التهاب حبيبومي عبر الجدار يصيب أي جزء (اللفائفي الانتهائي ~70%) بآفات متقطعة."},{"f":"داء كرون مقابل التهاب القولون التقرحي (جراحيًا)؟","b":"كرون: عبر الجدار، متقطع (skip)، أي جزء من الفم للشرج، نواسير وخراجات — الجراحة للاختلاطات فقط (النكس شائع). التقرحي: مخاطي مستمر من المستقيم قريبًا — استئصال القولون شافٍ."},{"f":"التهاب القولون الإقفاري: التظاهر والتدبير؟","b":"ألم بطني أيسر سفلي ± إسهال مدمى (منطقة IMA). التشخيص: تنظير سفلي هو المعيار الذهبي. التدبير: محافظ عادة (سوائل + صادات)؛ الغنغريني: استئصال + فغرة."}]},{"t":"أمراض الكولون والمستقيم الجراحية","cards":[{"f":"داء البوليبات العائلي (FAP): الجين والتدبير؟","b":"عيب صبغي سائد في جين APC على الصبغي 5؛ عشرات إلى آلاف البوليبات الغدية في القولون والمستقيم — خطر التحول السرطاني مؤكد تقريبًا. العلاج: استئصال القولون والمستقيم الوقائي (proctocolectomy) عادة مع مفاغرة لفائفية شرجية."},{"f":"متلازمة غاردنر: ما هي؟","b":"FAP + أورام دسيمويدية (خاصة في أنسجة البطن) + أورام عظمية وليفية متعددة والتهاب درقي."},{"f":"سرطان القولون الوراثي دون سليلات (HNPCC/لينش): الآلية؟","b":"شذوذات في جينات إصلاح عدم التطابق (MMR) تُسرّع تحول الغدومات لسرطان — معدل تشكل الغدومات كالطبيعي لكن التقدم أسرع."},{"f":"داء الرتوج: الآلية والموضع؟","b":"بروزات مكتسبة للمخاطية والنسيج الضام عبر جدار القولون على خطوط اختراق الشرايين القولونية بين الشريطيات — بسبب تقلصات قولونية عالية الضغط؛ ذروة العمر 50-70 سنة؛ لا يحدث في المستقيم."},{"f":"التهاب الرتوج الحاد: التظاهر والعلاج؟","b":"ألم حفرة حرقفية يسرى سريع البدء + غثيان وحمى ± إسهال؛ إيلام LIF. العلاج: صادات وريدية (أموكسيسيلين + ميترونيدازول + جنتاميسين)؛ الاستقصاء المختار للاختلاطات: CT."},{"f":"ناسور قولوني مثاني: العلامة المميزة؟","b":"إنتانات بولية ناكسة بجراثيم معوية + فقاعات وحطام في البول (pneumaturia) — أشيع بعد التهاب رتوج حاد."},{"f":"انفتال السيني: الصورة والتدبير؟","b":"يلتف السيني على مساريقه لدى المسنين الممسكين → انسداد مختنق سريع. AXR: عروة «U مقلوبة» كحبة القهوة. التدبير: أنبوب ريحي أو تنظير سيني لتخفيف الضغط؛ أحيانًا استئصال السيني."},{"f":"الاستقصاء المطلوب لتحديد المرحلة في سرطان الثلث السفلي للمستقيم؟","b":"الرنين المغناطيسي (MRI) للحوض — يقيّم عمق الغزو وعلاقته باللفافة المساريقية والعقد؛ مع CT صدري بطني للنقائل البعيدة."},{"f":"جراحة سرطان المستقيم المنخفض (≤8cm من الشرج)؟","b":"الاستئصال البطني العجاني (AP resection): فغر قولون دائم مع إزالة المستقيم والشرج."},{"f":"دور المعالجة الشعاعية في سرطان المستقيم؟","b":"تُستخدم قبل الجراحة (neoadjuvant) في المستقيم المتقدم موضعيًا للسماح بالاستئصال؛ وبعد الجراحة فقط لعاليي خطورة النكس الموضعي."},{"f":"انتشار سرطان القولون والمستقيم؟","b":"موضعي، لمفاوي، دموي (كبد، رئة، عظم)، أو عبر الجوف (transcoelomic). التصنيف بـTNM مفضل على ديوكس."},{"f":"العوامل المؤهبة لسرطان القولون؟","b":"البوليبات الغدية، داء الأمعاء الالتهابي المزمن، FAP/HNPCC، حمية غنية بالدهون فقيرة بالألياف، تدخين، كحول."},{"f":"نزف شرجي حاد: كيف تفرّق حسب اللون؟","b":"أحمر فاتح على سطح البراز والورق بعد التغوط: شرجي مستقيمي (بواسير/شق/تدلي). أحمر داكن مع خثرات مخلوط: مستقيمي سيني (أورام/رتوج). أحمر داكن مخلوط بالبراز: قولون دانٍ (أورام/التهاب/خلل تنسج وعائي)."}]},{"t":"أمراض القناة المغبنية","cards":[{"f":"البواسير: التعريف والمواضع النموذجية؟","b":"توسع الوسائد الشرجية الطبيعية (مخاطية + تحت مخاطية + أوعية). المواضع: 3 و7 و11 (وضعية الاستلقاء) — مواضع السويقات الوعائية الشرجية الرئيسية."},{"f":"الطريقة المثلى لتشخيص البواسير الداخلية؟","b":"التنظير الشرجي الصلب (proctoscopy) مع التنظير السيني الصلب — التشخيص بالرؤية المباشرة."},{"f":"نزف البواسير: صفاته؟","b":"نزف بعد التغوط أحمر فاتح غير مخلوط بالبراز — على الورق أو يرش في المرحاض."},{"f":"علاج البواسير حسب العرض؟","b":"تجنب الإمساك والشد + ملينات. الربط (banding) للتدلي، حقن الفينول المخفف للنزف، استئصال البواسير للكبيرة الخارجية أو الفاشلة تحفظيًا."},{"f":"الاختلاط الأكثر شيوعًا بعد استئصال البواسير؟","b":"الألم والنزف؛ مع خطر صغير لضعف التحكم وتضيق الشرج."},{"f":"الشق الشرجي: الألم المميز والتدبير؟","b":"ألم حاد «كالسكية» أثناء التغوط + ألم نابض عميق بعده لدقائق/ساعات (تشنج عضلات القاع) + دم قليل على الورق. التدبير: تسكين + مرخيات المصرة (مرهم نيتروغليسرين 0.2% أو ديلتيازيم 2%)."},{"f":"تدبير الشق الشرجي المزمن؟","b":"مرخيات المصرة الموضعية أولًا؛ الجراحة (بضع المصرة الداخلية الجانبي) عند الفشل — تحفظ المصرة قدر الإمكان."},{"f":"الناسور الشرجي: الآلية الأشيع؟","b":"نظرية الغدد الخفية: إنتان في غدة شرجية يشق طريقه عبر أنسجة الشرج للجلد حول الشرج — يبدأ غالبًا كخراج حول شرجي حاد."},{"f":"تقييم مسار الناسور الشرجي: الاستقصاء الأكثر حساسية؟","b":"الرنين المغناطيسي (MRI) — الأكثر حساسية لتحديد مسار الناسور وكشف الإنتان الخفي حول الشرج/الحوض."},{"f":"مبادئ جراحة الناسور الشرجي؟","b":"تصريف أي إنتان حاد؛ الناسور المنخفض: فتح المسار (fistulotomy)؛ الناسور العالي: استئصال المسار + إغلاق الفتحة الداخلية أو سيتون قاطع تدريجي — الهدف منع النكس مع حفظ التحكم."}]},{"t":"أمراض الكبد الجراحية","cards":[{"f":"الكيسة المائية الكبدية (hydatid): العامل المسبب والتشخيص؟","b":"المشوكة الحبيبية E. granulosus (المضيف المعتاد: الكلب). التشخيص: USS/CT/MRI (كيسات مملوءة بسائل لا وعائية ± تكلس) + مصلية (مستضد المشوكة إيجابي)."},{"f":"علاج الكيسة المائية الكبدية؟","b":"ألبيندازول مطوّل (أشهر/سنوات) + PAIR (بزل وشفط وحقن محلول ملحي مفرط التوتر وإعادة شفط) أو جراحة — ⚠ احذر انسكاب محتويات الكيسة (صدمة تحسسية)."},{"f":"مريضة 22 سنة: كيسة كبدية 2cm جدار رقيق محتوى رائق دون حجب — التدبير؟","b":"كيسة كبدية بسيطة: مراقبة فقط (لا تحتاج تدخلًا) — الكيسات البسيطة شائعة وحميدة؛ التدخل عند الأعراض أو الشك."},{"f":"الورم الغدي الكبدي (hepatic adenoma): الصورة النموذجية؟","b":"ورم ظهاري حميد يُكتشَف لدى شابات/متوسطات العمر، مرتبط بحبوب منع الحمل عالية الإستروجين. الاختلاطات (خاصة >5cm): نزف وتمزق عفوي؛ التحول الخبيث أشيع لدى الرجال وطفرة β-catenin."},{"f":"أسباب خراجات الكبد القيحية؟","b":"انسداد صفراوي (خبث أو حميد) 50-60%، تقيح بابي (التهاب زائدة/رتوج) ~20%، تجرثم دموي جهازي — السكري يضاعف الخطر 3 مرات."},{"f":"تشخيص خراج الكبد؟","b":"CT هو المفضل (حساسية >90%): تجمع سائل بحدود غير منتظمة ووذمة جدار الجوف؛ ~50% متعددة — والعلاج: تصريف عبر الجلد + صادات."},{"f":"سرطان الخلية الكبدية (HCC): عوامل الخطورة والواسم؟","b":"التشمع (خاصة التهاب كبد فيروسي مزمن HBV/HCV أو كحول)، الأفلاتوكسين. الواسم: AFP >500ng/mL مشخّص بقوة حتى مع التشمع."},{"f":"أشيع أورام الكبد؟","b":"النقائل (بنكرياس، قولون، معدة، مريء، ثدي) — 35% ممن يموتون بخباثة لديهم نقائل كبدية."},{"f":"ورم كلاتسكين (Klatskin): ما هو؟","b":"سرطان أقنية صفراوية (cholangiocarcinoma) عند ملتقى القناتين الكبديتين — يسبب يرقانًا انسداديًا."},{"f":"الاختلاط الأول لرضوض الكبد النافذة؟","b":"النزف (الصدمة النزفية) — الكبد عضو غني بالتروية؛ التدبير: إنعاش + إرقاء جراحي (تعبئة/خياطة) أو محافظ عند الاستقرار."},{"f":"سرطان المرارة الغدي: العلاقة بالحصيات؟","b":"الحصيات موجودة في 70% من الحالات؛ مرتبط بالتهاب القولون التقرحي والتهاب الأقنية الصلب الأولي — يُشخَّص غالبًا عرضًا أثناء/بعد استئصال المرارة."}]},{"t":"أمراض الطرق الصفراوية والمرارة","cards":[{"f":"أنماط حصيات المرارة؟","b":"الكولسترول: كبيرة وغالبًا وحيدة (إناث، عمر، بدانة). الصباغية: صغيرة هشة غير منتظمة (انحلال الدم). المختلطة: مسطحة (أملاح كالسيوم + صباغ + كولسترول)."},{"f":"ألم RUQ + يرقان + حرارة — التشخيص؟","b":"التهاب الأقنية الصفراوية (cholangitis): ثالوث شاركو (ألم RUQ + يرقان + عرواءات/حمى) — العلاج: صادات وريدية (بيبراسيلين/تازوباكتام) + تخفيف الانسداد (ERCP)."},{"f":"الفرق بين المغص الصفراوي والتهاب المرارة الحاد؟","b":"المغص: ألم RUQ متقطع (يتشعع للظهر) ± يرقان دون مكون التهابي. التهاب المرارة: ألم RUQ مستمر + حمى + ↑WBC + التهاب صفاق موضعي + علامة مورفي إيجابية."},{"f":"علامة مورفي؟","b":"إصبعان فوق RUQ + شهيق عميق → ألم وتوقف الشهيق عند اصطدام المرارة الملتهبة بالإصبعين — إيجابية في التهاب المرارة الحاد."},{"f":"الاستقصاء الأول لالتهاب المرارة الحاد؟","b":"الأمواج فوق الصوتية: مرارة سميكة الجدار منكمشة + سائل حول المرارة + حصيات ± توسع CBD (>6mm)."},{"f":"علاج التهاب المرارة الحاد؟","b":"NBM + تسكين + سوائل وريدية + صادات (co-amoxiclav)؛ استئصال المرارة بالتنظير هو المختار للائقين — الجراحة المفتوحة عند انثقاب المرارة."},{"f":"مريض 65 سنة: حكة + ألم بطني + بول غامق + يرقان — الخطوة التشخيصية التالية؟","b":"الأمواج فوق الصوتية أولًا (تبحث عن توسع القناة الجامعة)؛ إذا توسع CBD: MRCP لتحديد حصيات CBD ثم ERCP + قطع مصرة قبل استئصال المرارة."},{"f":"قانون كورفوازييه (Courvoisier's law)؟","b":"مرارة مجسوسة غير مؤلمة مع يرقان = خباثة (سرطان رأس بنكرياس/أمبولة) لا حصيات — لأن الالتهاب المزمن من الحصيات يجعل المرارة متليفة غير قابلة للتمدد."},{"f":"العلوص الحصوي (gallstone ileus): الآلية والعلامات الشعاعية؟","b":"حصاة تتآكل عبر المرارة إلى العفج ثم تسد اللفائفي الانتهائي. AXR: هواء في CBD (استرواح صفراوي) + مستويات سائلة في الأمعاء الدقيقة + حصاة منتبذة."},{"f":"متلازمة ميريزي (Mirizzi)؟","b":"حصاة في عنق المرارة/القناة الكيسية تضغط على القناة الصفراوية مسببة يرقانًا انسداديًا."},{"f":"الحصيات المرارية اللاعرضية: متى تُستأصل انتخابيًا؟","b":"90% تبقى لاعرضية — لا جراحة روتينية؛ تُستأصل عند: فقر الدم المنجلي، تثبيط المناعة، المرارة المتكلسة/الخزفية (خطر سرطان)."},{"f":"المرارة الخزفية (porcelain): ما أهميتها؟","b":"مرارة متكلسة الجدار — مرتبطة بخطورة سرطان المرارة → استئصال انتخابي."},{"f":"سرطان الأمبولة (ampullary): ما يميزه؟","b":"صغير عادة ويتظاهر مبكرًا بيرقان انسدادي غير مؤلم — أفضل إنذار بين سرطانات الكبد الصفراوية بسبب التظاهر المبكر."}]},{"t":"آفات البنكرياس الجراحية","cards":[{"f":"سرطان رأس البنكرياس: التظاهر الكلاسيكي؟","b":"يرقان انسدادي (90%) بسبب انضغاط/غزو CBD + مرارة مجسوسة (قانون كورفوازييه) + ألم شرسوفي/ربع علوي أيسر يتشعع للظهر (70%) + نقص وزن وحكة."},{"f":"النسيج الأشيع لسرطان البنكرياس؟","b":"سرطانة غدية قنوية 90%؛ عوامل الخطورة: تدخين، عمر، حمية دهنية، سكري، كحول مفرط، التهاب بنكرياس مزمن."},{"f":"أي الحالات لا تُعد مضاد استطباب للاستئصال الشافي في سرطان البنكرياس؟","b":"مضادات الاستطباب: نقائل بعيدة، غزو وعائي كبير (شريان مساريقي علوي/جذع بطني)، اعتلال عقدي واسع، حالة عامة سيئة — أما اليرقان وحده فليس مضاد استطباب (يُخفَّف بالدعامة)."},{"f":"تخفيف اليرقان الانسدادي في سرطان البنكرياس غير القابل للاستئصال؟","b":"دعامة صفراوية بالتنظير عبر ERCP (الأولى)، أو تصريف عبر الجلد PTC، أو مفاغرة جراحية (مرارة-صائم/قناة-صائم)."},{"f":"أشيع سببي التهاب البنكرياس الحاد؟","b":"الحصيات الصفراوية 60%، الكحول 30% — ثم: فرط شحوم، فرط كالسيوم، أدوية (أزاثيوبرين، ثيازيدات)، ERCP، إنتانات فيروسية."},{"f":"المظاهر السريرية لالتهاب البنكرياس الحاد النخري؟","b":"ألم شرسوفي شديد يتشعع للظهر + غثيان/إقياء شديد + حمى وتسرع قلب وهبوط ضغط؛ علامتا غراي-تيرنر (كدمة الخاصرة اليسرى) وكولن (كدمة حول السرة) في النزفي (1-3%)."},{"f":"المقاربة الأولى لالتهاب بنكرياس حاد حصوي مع يرقان وتوسع القناة الجامعة؟","b":"ERCP عاجل + قطع مصرة لاستخراج حصاة CBD — مع إنعاش وسوائل وصادات."},{"f":"رجل 50 سنة: التهاب بنكرياس حاد متكرر + كتلة شرسوفية مجسوسة — التشخيص؟","b":"كيسة بنكرياسية كاذبة (pseudocyst): تجمع سائل حول بنكرياسي بعد التهاب حاد — قد تُصرف بتوجيه EUS عند الأعراض/الاختلاطات."},{"f":"طفل 12 سنة: كتلة أعلى البطن بعد رض دراجة قبل شهرين — التشخيص؟","b":"كيسة بنكرياسية كاذبة تالية لرض البنكرياس — الرض سبب مهم للكيسات الكاذبة عند الأطفال."},{"f":"معايير غلاسكو-إيمري لشدة التهاب البنكرياس؟","b":"≥3 معايير خلال 48 ساعة = هجمة شديدة (PANCREAS): PaO2<8kPa، عمر>55، WBC>15,000، كالسيوم مصحح<2، يوريا>16، إنزيمات (AST>200/LDH>600)، ألبومين<32، سكر>10."}]},{"t":"النزف الهضمي وآفات الطحال","cards":[{"f":"أشيع سبب للنزف الهضمي العلوي؟","b":"القرحة الهضمية (معدية أو عفجية) الحميدة 50% — دم أحمر طازج مع خثرات أحيانًا مخلوط بالطعام."},{"f":"مريض كحولي بإقياء دموي — الاستقصاء الأفضل؟","b":"التنظير الهضمي العلوي العاجل (OGD خلال 24 ساعة): يشخّص الدوالي ويسمح بالتداخل العلاجي (ربط/تصليب/حقن أدرينالين/تخثير)."},{"f":"تمزق مالوري-فايس: الآلية والتظاهر؟","b":"تمزق مخاطي مريئي بعد إقياء/تقوع عنيف مطوّل — كميات صغيرة من دم أحمر طازج."},{"f":"تدبير النزف الهضمي العلوي عند شاب: الخطوات؟","b":"إنعاش (وريد واسع + بلوريات + دم عند الحاجة) + PPI وريدي (أوميبرازول 40mg) + إيقاف NSAIDs + OGD عاجل علاجي؛ الجراحة عند: نزف ضخم مستمر، فشل التنظير، نكس غير قابل لإعادة التنظير."},{"f":"مريض 60 سنة: هبوط ضغط انتصابي + دم أحمر داكن غزير من الشرج — الخطوة التشخيصية التالية؟","b":"النزف الهضمي السفلي: تنظير شرجي مستقيمي صلب أولًا لاستبعاد سبب شرجي بسيط، ثم تنظير سيني/قولون عاجل (قد يسمح بالتداخل)؛ تصوير أوعية مساريقي انتقائي للنزف المستمر الخفي."},{"f":"اختلاطات استئصال الطحال؟","b":"النزف، الخمج (أخطرها: إنتان ما بعد استئصال الطحال بالعضيات المغلفة: رئوية/نزلية/سحائية — خطورة مدى الحياة)، خثار (↑ صفيحات عابر)، أذية أعضاء مجاورة (بنكرياس/معدة)."},{"f":"الوقاية من خمج ما بعد استئصال الطحال؟","b":"لقاح المكورات الرئوية (قبل الجراحة بأسبوعين أو بأسرع ما يمكن بعد الإسعافية + إعادة كل 5-10 سنوات) + لقاح Hib + لقاحات السحائية (Men B/C/ACWY) + لقاح أنفلونزا سنوي."},{"f":"معايير فرط الطحالية البدئية؟","b":"ضخامة طحال + قلة خلية دموية (فقر دم/قلة صفيحات/قلة كريات بيض) + نقي عظم مفرط التنسج + تحسن بعد استئصال الطحال."},{"f":"أفضل علاج لأعراض داء الكريات الحمر المكورة الوراثي (hereditary spherocytosis)؟","b":"استئصال الطحال (يحد انحلال الدم) — مع حمض الفوليك؛ الأجسام المميزة بعد الاستئصال: هاول-جولي وبابنهايمر والخلايا الهدفية."}]},{"t":"أمراض البريتوان والبطن الحاد","cards":[{"f":"ألم بطني مفاجئ شديد + بطن خشبي + هلال غازي تحت الحجاب — التشخيص والتدبير؟","b":"انثقاب حشا أجوف (قرحة عفجية/معدية أشيع). التدبير: إنعاش + صادات + جراحة عاجلة (إغلاق بالخياطة + رقعة ثربية) — ما لم يكن المريض رافضًا أو غير محتمل للجراحة."},{"f":"تعريف التهاب الصفاق الحاد؟","b":"التهاب حاد في جوف الصفاق — يتظاهر بألم بطني + صلابة/دفاع + حمى وتسرع قلب؛ أشيع أسبابه الجراحية: انثقاب حشا أجوف، التهاب زائدة مثقوب، التهاب رتوج مثقوب."},{"f":"حالات غير جراحية مقلدة للبطن الحاد الجراحي؟","b":"احتشاء عضلة قلبية سفلي، التهاب رئة سفلي، حماض كيتوني سكري، مغص كلوي/صفراوي، التهاب حوض، داء منجلي — يجب نفيها قبل الجراحة."},{"f":"التشخيص التفريقي لألم شرسوفي حاد؟","b":"انثقاب قرحة، التهاب بنكرياس حاد، مغص صفراوي/التهاب مرارة، احتشاء سفلي، تسلخ أبهر — صورة الصدر القائمة والأميلاز والـECG توجه."},{"f":"مريضة 50 سنة بحبن متوسط منذ شهرين — ما المهم تشخيصيًا؟","b":"بزل الحبن التشخيصي: مظهر السائل، بروتين/ألبومين (SAAG)، خلايا، زرع، سيتولوجي — يفرّق بين فرط ضغط الباب والخباثة والسل."},{"f":"كتلة حوضية يمنى عند شابة 25 سنة: التشخيص التفريقي؟","b":"حمل (داخل/خارج رحم)، كيسة مبيض/انفتالها، خراج حوضي/بوقي، التهاب زائدة (كتلة زائدية)، داء كرون لفائفي، ورم."},{"f":"التهاب الصفاق الموضعي مقابل المعمم؟","b":"الموضعي: دفاع موضّع (مثل التهاب مرارة/رتج/زائدة مبكر) — قد يُدبَّر محافظًا أحيانًا. المعمم: صلابة معممة «بطن خشبي» — يستلزم جراحة عاجلة عادة."},{"f":"لماذا يستجيب هبوط الضغط في انثقاب القرحة للسوائل بسرعة؟","b":"بسبب التفاعل الذاتي (autonomic reaction) مع الألم الشديد — الهبوط غالبًا عميق لكنه يستجيب بسرعة لإنعاش معتدل بالسوائل."},{"f":"التدبير المحافظ لانثقاب حشا أجوف: متى؟","b":"دور محدود جدًا: فقط إذا التأم الانثقاب وقت التظاهر + لا عدم استقرار دوراني + لا علامات التهاب صفاق — PPI وريدي + صيام + علاج طبيعي نشط."},{"f":"خراج حول شرجي: التدبير؟","b":"شق وتصريف إسعافي جراحي — خاصة لدى السكريين أو مثبطي المناعة."},{"f":"التهاب الرتوج المثقوب: التظاهر والتدبير؟","b":"ألم LIF + حمى عالية + ألم شديد ودفاع معمم (التهاب صفاق برازي عند الانثقاب المباشر). التدبير: إنعاش + صادات واسعة + جراحة (استئصال +/− فغرة)."}]},{"t":"الصدمة ورضوض البطن","cards":[{"f":"أفضل تعريف للصدمة؟","b":"قصور الدوران عن تلبية الاحتياجات الأيضية للأنسجة — نقص تروية نسيجية مع حماض لبني."},{"f":"أسباب صدمة نقص الحجم في الرضوض؟","b":"نزف (رضوض، تمزق AAA، حمل منتبذ ممزق، نزف بعد جراحة)، تجفاف عميق، حروق، التهاب بنكرياس — العلاج: سوائل بلورية سريعة 500mL + دم عند الحاجة."},{"f":"في صدمة نقص الحجم بعد حادث سير: أقل المحاليل فائدة للإنعاش؟","b":"محاليل الغلوكوز (الدكستروز) — تتوزع داخل الخلايا بسرعة ولا تبقى داخل الأوعية؛ الأفضل: بلوريات (رينغر/ملحي) ثم دم."},{"f":"الحشا الأكثر إصابة في الرضوض المغلقة للبطن؟","b":"الطحال — ثم الكبد؛ الكلية أقل."},{"f":"في طعنات السكين النافذة للبطن: أخطر إصابة حشوية؟","b":"إصابة الأوعية الكبيرة (الأبهر/الأجوف) — النزف القاتل؛ ثم الكبد والطحال والأمعاء."},{"f":"مريض متعدد الرضوض: ما الإصابة التي تُعالَج أولًا؟","b":"الأولوية لمجرى الهواء والتنفس والدوران (ABC) — النزف المهدد للحياة أولًا (ضغط مباشر/عاصبة)، ثم إصابات الرأس والصدر قبل البطن."},{"f":"مبادئ تدبير رضوض الأوعية في المسح الأولي؟","b":"ضغط مباشر على الجرح النازف، إنعاش سوائل عدواني، الورم الدموي سريع التوسع يوحي بإصابة وعائية مهمة، ردّ الكسر وتجبيره، استشارة جراحية."},{"f":"شظايا طلق ناري بفوهة دخول يمين السرة + علامات حيوية مستقرة + مضض خفيف — الإجراء؟","b":"تقييم منهجي: FAST/CT للبحث عن إصابة حشوية — الاستقرار لا ينفي إصابة الأمعاء/المساريقا؛ المراقبة الدقيقة أو تنظير استكشافي حسب البروتوكول."},{"f":"الصدمة الإنتانية مقابل نقص الحجم سريريًا؟","b":"الإنتانية مبكرًا: محموم، متورد، نبضات قافزة (bounding) — ثم انهيار دوراني كالنزفية. العلاج: صادات واسعة + سوائل + دعم."},{"f":"تدبير النزف الخارجي في الطرف بعد حادث سير (الخطة الأولى)؟","b":"ضغط مباشر على الجرح؛ إذا فشل: عاصبة (tourniquet) قريبة — مع إنعاش وريدي وتقييم ABC."}]},{"t":"الفتوق وجدار البطن","cards":[{"f":"تعريف الفتق؟ والفرق بين: غير قابل للرد/مسدود/مختنق/محتبس؟","b":"بروز حشا عبر عيب في جداره الحاوي. غير قابل للرد: لا يُدفَع. مسدود: لا تعبر محتويات الأمعاء (انسداد). مختنق: إقفار — جراحة عاجلة. محتبس: محتويات عالقة بالالتصاقات."},{"f":"الفتق الأشيع عند النساء؟","b":"الفتق الأربي (أشيع نمط لدى الجنسين، لكن الذكور >> الإناث) — أما الفتق الفخذي فأشيع لدى الإناث نسبةً ويسهل تفويته."},{"f":"أكثر فتوق جدار البطن عرضة للغصص والاختناق؟","b":"الفتق الفخذي — بسبب صلابة حدود القناة الفخذية؛ مرجح أن يكون غير قابل للرد وأن يختنق."},{"f":"امرأة 30 سنة: انتباج وحشي وأسفل حديبة العانة — التشخيص؟","b":"فتق فخذي: كتلة أعلى الفخذ الأنسي تتجه أسفل الساق (بخلاف الأربي الذي يتجه للمغبن)."},{"f":"صفات الفتق المختنق؟","b":"كتلة مؤلمة متوترة غير قابلة للرد + أعراض انسداد ± علامات إقفار (ألم شديد مستمر، حمى، تسرع قلب) — جراحة إسعافية."},{"f":"الفتق الجراحي (incisional): التعريف والنسبة؟","b":"فتق مكان ندبة العمل الجراحي — يلي تفكك إغلاق العضلات بعد الجراحة (11-20%)؛ إصلاح الشبكة ↓ النكس لكن ↑ الخمج."},{"f":"فتق ريختر (Richter): ما يميزه؟","b":"يشمل جدار الأمعاء فقط لا اللمعة كلها — قد يختنق دون انسداد معوي واضح."},{"f":"فتق لتره (Littré)؟","b":"كيس فتقي يحوي رتج ميكل مختنقًا."},{"f":"العوامل المؤهبة للفتق؟","b":"↑ الضغط داخل البطن (سعال مزمن، إمساك، حمل، بدانة، استسقاء)، ضعف جدار البطن (عمر، جراحة سابقة)، تدخين."},{"f":"⚠ تحذير عند رد الفتق المحتبس؟","b":"يمكن دفع فتق محتبس إلى الجوف معطيًا مظهر رد ناجح كاذب — الرد القسري لفتق مختنق ممنوع."},{"f":"الفتق السدادي (obturator): الصورة؟","b":"عبر القناة السدادية — ألم على الجانب الأنسي للفخذ لدى امرأة نحيلة مسنة + انسداد أمعاء دقيقة."}]},{"t":"أمراض الثدي الجراحية","cards":[{"f":"التقييم الثلاثي (triple assessment) لكتلة الثدي؟","b":"الفحص السريري + النسيج/الخلايا (خزعة) + التصوير (ماموغرافي/أمواج فوق صوتية) — يجب أن تخضع له جميع الكتل."},{"f":"الخطوة الأولى في مقاربة كتلة ثدي 3cm عند سيدة 55 سنة؟","b":"التقييم الثلاثي الكامل — لا تُشخَّص الكتلة سريريًا فقط؛ الخطوة الأولى: فحص سريري + تصوير + خزعة."},{"f":"الطريقة المثلى لتشخيص دقيق لكتلة مشتبهة؟","b":"الخزعة اللبية (core biopsy) — تعطي النسيج والدرجة والمستقبلات؛ مع التقييم الثلاثي."},{"f":"السبب الأكثر شيوعًا للنز الدموي من الحلمة؟","b":"الحليموم داخل الأقنية (intraductal papilloma) — ورم حميد داخل القنوات اللبنية بنز دموي تلقائي من قناة واحدة غالبًا."},{"f":"سيدة 25 سنة: كتل عديدة مجسوسة مؤلمة قبل الدورة — التشخيص؟","b":"داء الثدي الليفي الكيسي (fibrocystic): ألم دوري وتورم و«تكتل» بين البلوغ وسن اليأس (15-55 سنة) — حميد، العلاج: طمأنة ومضادات التهاب."},{"f":"الورم الغدي الليفي (fibroadenoma): الصفات؟","b":"فرط نمو حميد لفصيص واحد؛ كتلة غير مؤلمة متحركة محددة — الأشيع تحت 30 سنة؛ التشخيص: الأمواج فوق الصوتية غالبًا حاسمة."},{"f":"النسيج الأشيع لسرطان الثدي الغازي؟","b":"السرطانة القنوية الغازية ~70%، ثم الفصيصية الغازية 10-15% — و60-70% إيجابية مستقبلات الإستروجين (إنذار أفضل)."},{"f":"يُستطب استئصال الثدي الربعي (quadrantectomy/WLE) متى؟","b":"للداء الموضعي (المرحلة 1-2): استئصال موضعي واسع + معالجة شعاعية — مع خزعة العقدة الحارسة؛ أما الداء المتقدم موضعيًا فيحتاج كيميائية مساعدة جديدة أولًا."},{"f":"علامات سرطان الثدي المتقدم موضعيًا بالفحص؟","b":"كتلة قاسية غير منتظمة مثبتة، جلد البرتقالة (peau d'orange)، انكماش الحلمة، عقد إبطية متلاصقة/مثبتة — المرحلة 3: مثبت على العضلة + عقد متلاصقة."},{"f":"المسح السكاني لسرطان الثدي؟","b":"ماموغرافي بمنظرين كل 3 سنوات للنساء 50-70 سنة — أنقص الوفيات ~30% لدى النساء >50 سنة."},{"f":"التهاب الثدي الإرضاعي: العلاج؟","b":"إنتان عنقودي حاد في أقنية الثدي — صادات فموية + (شفط متكرر عند الخراج) — لا حاجة لإيقاف الإرضاع."},{"f":"نخر الشحم الرضي في الثدي: الصورة؟","b":"كتلة جديدة مؤلمة/غير مؤلمة سيئة التحديد بعد رض (القصة قد تغيب) — قد يصعب تمييزها حتى بالتقييم الثلاثي؛ الاستئصال عند الشك."},{"f":"علاج الداء إيجابي HER2؟","b":"~30% تفرط التعبير عن HER2 (داء عدواني) — تُعطى معالجة مضادة لـHER2 (تراستوزوماب) مع الكيميائية إذا الورم >2cm أو إصابة عقدية."}]},{"t":"الجراحة التنظيرية وجراحة البدانة والعناية حول الجراحية","cards":[{"f":"مزايا الجراحة التنظيرية؟","b":"شقوق أصغر، ألم أقل، إقامة أقصر، عودة أسرع للنشاط — مع نفس سلامة الجراحة المفتوحة في سرطان القولون (لا فرق في البقيا أو النكس)."},{"f":"استطبابات جراحة البدانة (NICE)؟","b":"BMI ≥40 (أو ≥35 مع اعتلالات مهمة تتحسن بنقص الوزن) + فشل التدبير غير الجراحي 6 أشهر + لياقة للجراحة والتخدير + تدبير مكثف مستوى 3."},{"f":"الاختلاط الأكثر خطورة لجراحة البدانة؟","b":"تسرّب المفاغرة/الخياطة (anastomotic leak) — ثم النزف والخثار الوريدي والانصمام الرئوي."},{"f":"أنماط عمليات البدانة؟","b":"مقيِّدة (ربط المعدة القابل للتعديل — الأشيع)، أو سوء امتصاص، أو مختلطة (تحويل مسار المعدة)."},{"f":"العامل الأقل احتمالية لزيادة نسبة الإنتان في الجراحة الانتخابية الكبيرة؟","b":"عوامل تزيد الإنتان: سكري، تدخين، بدانة، تثبيط مناعة، مدة جراحة طويلة — أما الصادات الوقائية المناسبة فتُنقصه."},{"f":"العلامة الأكثر أهمية في التفاعل الانحلالي لنقل الدم لدى المريض اليقظ؟","b":"الحمى + ألم قطني/صدر + قشعريرة — أوقف النقل فورًا وأبقِ الوريد مفتوحًا بمحلول ملحي وأخبر بنك الدم."},{"f":"تدبير التفاعل الانحلالي الحاد لنقل الدم؟","b":"إيقاف النقل فورًا + سوائل وريدية غزيرة + مدرات ± دعم — مع إرسال كيس الدم وعينة للمختبر."},{"f":"الوقاية من الخثار الوريدي حول الجراحة؟","b":"تحريك مبكر + جوارب ضاغطة + هيبارين منخفض الوزن الجزيئي وقائي للمرضى عاليي الخطورة."}]}]},{"s":"الجراحة العصبية","topics":[{"t":"رضوض الدماغ والجمجمة والنزوف داخل القحف","cards":[{"f":"الورم الدموي فوق الجافية (Epidural hematoma) — الآلية والوعاء الممزق","b":"تمزق الشريان السحائي الأوسط (middle meningeal artery) غالبًا بعد كسر العظم الصدغي؛ الدم يتجمع بين العظم والأم الجافية؛ على CT شكل عدسي/ثنائي التحدب لا يتجاوز الدروز."},{"f":"الفترة الصاحية (Lucid interval) — في أي نزف داخل قحف تُرى؟","b":"نموذجية للورم الدموي فوق الجافية: فقدان وعي أولي ← فترة صاحية (ساعات لأيام) ← تدهور سريع في الوعي مع توسع حدقة نفس الجهة ثم سبات."},{"f":"الورم الدموي تحت الجافية (Subdural hematoma) — الآلية والفئة الأكثر عرضة","b":"تمزق الأوردة الجسرية (bridging veins) بين القشرة والجيوب الوريدية؛ على CT شكل هلالي (crescent)؛ الأكثر عرضة: المسنون (ضمور الدماغ) ومدمنو الكحول ومن على مضادات التخثر."},{"f":"متى يُستطب الإخلاء الجراحي للورم تحت الجافية؟","b":"سماكة الجلطة >10 مم أو انزياح خط الوسط >5 مم، مع عكس شذوذات التخثر عاجلًا؛ المزمنة الصغيرة قد تُغسل بثقب المثقب."},{"f":"النزف تحت العنكبوتية (SAH) — العرض الكلاسيكي والسبب الأشيع","b":"صداع «قصف الرعد» (thunderclap) — الأسوأ على الإطلاق، عادة قذالي؛ السبب الأشيع: تمزق أم دم (aneurysm) توتية."},{"f":"الصداع الحارس (Sentinel headache) ومتلازمة تيرسون (Terson syndrome)","b":"الصداع الحارس: تسرب تحذيري صغير من أم الدم قبل النزف الكبير (~6% من المرضى)؛ تيرسون: نزوف شبكية/زجاجية مرافقة لـSAH وتزيد الوفيات ×5."},{"f":"تشخيص SAH عندما يكون CT سلبيًا — متى يُجرى البزل القطني؟","b":"CT عاجل يكشف >95% خلال أول 24 ساعة؛ إن كان سلبيًا والقصة موحية: بزل قطني بعد >12 ساعة من بدء الصداع للبحث عن الاصفرار (xanthochromia) الذي يميز دم SAH القديم عن «البزل المدمى»."},{"f":"كسور قاعدة الجمجمة (Basilar skull fracture) — العلامات الكلاسيكية","b":"علامة باتل (Battle sign): كدمة منطقة الخشاء؛ عيون الراكون (raccoon eyes)؛ سيلان السائل الدماغي الشوكي من الأنف أو الأذن (CSF rhinorrhea/otorrhea)."},{"f":"تدبير ارتفاع الضغط داخل القحف (↑ICP) — الإجراءات الأولية","b":"رفع رأس السرير 30° مع إبقاء الرأس بالخط المتوسط، تسكين وتخدير كافٍ، العلاج بالأسمولية (مانيتول أو محلول ملحي مفرط التوتر)؛ راقب ضغط التروية الدماغية."},{"f":"ضغط التروية الدماغية (CPP) — المعادلة والهدف","b":"CPP = الضغط الشرياني الوسطي (MAP) − الضغط داخل القحف (ICP)؛ الهدف 60–70 ملم زئبق."},{"f":"ثالوث كوشينغ (Cushing triad)","b":"ارتفاع الضغط الشرياني (مع اتساع الضغط النبضي) + بطء القلب + اضطراب التنفس — علامة متأخرة لارتفاع ICP الشديد الوشيك الانفتاق."},{"f":"الارتجاج الدماغي (Concussion) مقابل أذية المحور المنتشرة (DAI)","b":"الارتجاج: خلل وظيفي عابر بلا آفة بنيوية؛ DAI: تمزق المحاور بقوى القص (تسارع–تباطؤ)، فقدان وعي مطول وبؤر نزفية دقيقة عند تقاطع المادتين الرمادية والبيضاء."},{"f":"النزف داخل المخ (ICH) — أشيع سبب وأشيع موقع","b":"أشيع سبب: ارتفاع الضغط الشرياني المزمن؛ أشيع موقع: العقد القاعدية/النواة العدسية (الأوعية اللينتيكولو–مخططية الثاقبة)."},{"f":"متى يُمنع البزل القطني في رضوض الرأس؟","b":"مضاد استطباب عند الاشتباه بورم فوق الجافية، وكل علامات ↑ICP أو كتلة بؤرية مع انزياح خط وسط — خشية الانفتاق."},{"f":"الصرع ما بعد الرض — الوقاية والعلاج","b":"النوبات المبكرة (<7 أيام) تُعالج وقائيًا قصير الأمد (ليفيتيراسيتام/فينيتوين)؛ النوبات المتأخرة (>7 أيام) تعني صرعًا ما بعد الرض يحتاج علاجًا طويل الأمد."}]},{"t":"أذيات النخاع الشوكي وأمراض العمود الفقري","cards":[{"f":"الصدمة النخاعية (Spinal shock) مقابل الصدمة عصبية المنشأ (Neurogenic shock)","b":"الصدمة النخاعية: فقدان مؤقت للمنعكسات تحت مستوى الإصابة (أيام–أسابيع)؛ الصدمة عصبية المنشأ: هبوط ضغط + بطء قلب بفقدان المقوية الودية (إصابات فوق T6) — تُعالج بالسوائل ومقبضات الأوعية."},{"f":"متلازمة براون–سيكار (Brown-Séquard) — الصورة السريرية","b":"آفة نصف النخاع: علامات UMN + فقد الحس العميق (العمود الظهري) بنفس الجهة تحت الآفة، وفقد الألم والحرارة بالجهة المقابلة؛ أسبابها: الرضوض أو الآفات الكتلية أو انفتاق القرص."},{"f":"متلازمة الحبل المركزي (Central cord syndrome)","b":"أشيع متلازمات النخاع غير الكاملة: ضعف الطرفين العلويين > السفليين؛ غالبًا بعد رض فرط البسط لدى مسنين بتضيق فقاري."},{"f":"متلازمة الحبل الأمامي (Anterior cord syndrome)","b":"فقد حركي + فقد الألم والحرارة مع حفظ الحس العميق واللمس الدقيق (تروية الشريان النخاعي الأمامي)؛ الإنذار الحركي سيئ."},{"f":"متلازمة ذنب الفرس (Cauda equina) — الصورة والتدبير","b":"ألم جذري ثنائي + تخدير سرجي (saddle anesthesia) + احتباس بولي — إسعاف جراحي عاجل (تخفيف الضغط خلال ساعات)."},{"f":"الانزلاق الغضروفي القطني — المستوى الأشيع والعلامات","b":"الأشيع L4-L5 وL5-S1؛ ألم عرق النسا (sciatica) يزداد بالسعال والعطاس، اختبار رفع الساق المستقيمة (SLR) إيجابي، وضعف منعكسات حسب الجذر."},{"f":"تضيق القناة الشوكية القطنية — العرض المميز","b":"العرج العصبي (neurogenic claudication): ألم/ثقل بالساقين عند المشي والوقوف يتحسن بالجلوس والانحناء للأمام (وضعية عربة التسوق)."},{"f":"كسور العمود الرقبي العالية — جيفرسون والمشنقة","b":"كسر جيفرسون (Jefferson): انفجار C1 بعد حمل محوري؛ كسر المشنقة (Hangman's): كسر ثنائي عنق C2 بعد فرط البسط."},{"f":"تقييم إصابة النخاع — مقياس ASIA","b":"يحدد المستوى العصبي (آخر قطعة سليمة حركيًا وحسيًا) والشمولية: A كاملة ← E طبيعية؛ غياب التقلص الشرجي الإرادي = إصابة كاملة."},{"f":"تحرير العمود الرقبي بعد الرض — متى يُنزع الطوق؟","b":"بعد نفي الإصابة سريريًا وشعاعيًا (معايير NEXUS/Canadian C-spine)؛ أي ألم خط وسط أو عجز عصبي = إبقاء الطوق والتصوير."},{"f":"التهاب النخاع المستعرض (Transverse myelitis)","b":"ضعف + مستوى حسي + خلل بولي حاد تحت الآفة؛ غالبًا بعد خمج فيروسي؛ يُفرَّق عن غيلان–باريه بوجود مستوى حسي واضح."},{"f":"تكهف النخاع (Syringomyelia) — الصورة الحسية المميزة","b":"فقد منفصل للألم والحرارة (dissociated sensory loss) بتوزيع «العباءة» مع حفظ اللمس الدقيق؛ مرتبط بتشوه آرنولد–خياري."}]},{"t":"إصابات الأعصاب المحيطية والضفائر العصبية","cards":[{"f":"تصنيف سيدون (Seddon) لإصابات الأعصاب المحيطية","b":"عصاب عملي (neuropraxia): انقطاع توصيل عابر — شفاء كامل؛ تمزق المحور (axonotmesis): المحور متأذٍ والغمد سليم — تجدد ممكن؛ تمزق العصب (neurotmesis): انقطاع كامل — يحتاج جراحة."},{"f":"علامة تينيل (Tinel's sign) — ماذا تعني؟","b":"وخز/تنميل عند النقر فوق العصب = علامة تجدد المحاور؛ تقدم نقطة تينيل نحو المحيط مؤشر على الشفاء."},{"f":"شلل العصب الكعبري (Radial nerve) — الآلية والمظهر","b":"«شلل ليلة السبت» (Saturday night palsy) بانضغاطه في الميزابة الحلزونية مع كسر عظم العضد؛ هبوط الرسغ (wrist drop) + ضعف بسط الأصابع."},{"f":"متلازمة النفق الرسغي (Carpal tunnel) — العصب والاختبارات","b":"انضغاط العصب الناصف (median)؛ اختبارا تينيل وفالن (Phalen)؛ ضمور الراحة (thenar) في الحالات المتقدمة؛ العلاج الجراحي: تحرير الرباط الرسغي."},{"f":"إصابة العصب الزندي (Ulnar nerve) — المظهر الكلاسيكي","b":"يد المخلب (claw hand) بضمور بين العظام؛ اختبار فرومنت (Froment)؛ يُصاب عند اللقيمة الإنسية للعضد أو النفق الزندي."},{"f":"شلل إرب–دوشين (Erb-Duchenne) مقابل شلل كلمبكه (Klumpke)","b":"إرب (C5-C6): «نادل يطلب البقشيش» (waiter's tip) — ذراع ممدودة مدورة داخليًا؛ كلمبكه (C8-T1): يد مخلبية + متلازمة هورنر."},{"f":"إصابة العصب الشظوي الأصلي (Common peroneal nerve) — المظهر","b":"هبوط القدم (foot drop) مع ضعف البسط الظهري؛ يُصاب عند رأس الشظية (كسور/جبائر ضاغطة/وضعيات مطولة)."},{"f":"شلل العصب الوجهي المحيطي (Bell's palsy) — العلامة المميزة","b":"شلل وجهي محيطي يصيب الجبهة أيضًا (بعكس المركزي الذي يحفظها)؛ العلاج: ستيروئيدات باكرة ± مضاد فيروس مع حماية العين."},{"f":"إصابة العصب بين العظام الأمامي (Anterior interosseous nerve)","b":"فرع من الناصف؛ عدم القدرة على تشكيل حرف O بالإبهام والسبابة (علامة الدائرة)؛ يُصاب مع كسور فوق اللقمتين."},{"f":"متلازمة مخرج الصدر (Thoracic outlet syndrome)","b":"انضغاط الضفيرة العضدية/الأوعية بين الترقوة والضلع الأول؛ ألم وخدر بالطرف العلوي يزداد برفع الذراع؛ اختبار أدسون (Adson)."},{"f":"سرعة تجدد العصب المحيطي بعد الإصلاح الجراحي","b":"~1 مم/يوم (≈1 إنش/شهر)؛ تُقدَّر مدة التعافي بالمسافة من موقع الإصلاح إلى العضلة الهدف."},{"f":"اعتلال الأعصاب السكري — النمط الأشيع","b":"اعتلال حسي حركي متناظر قفازي–جوربي (stocking-glove) يبدأ بالقدمين؛ فقد الاهتزاز والألم أولًا."}]},{"t":"التشوهات العصبية الخلقية واستسقاء الدماغ","cards":[{"f":"الاستسقاء الدماغي — النوعان الرئيسيان","b":"انسدادي (غير مواصل): انسداد جريان CSF (تضيق المسال)؛ مواصل (communicating): خلل الامتصاص (بعد نزف أو خمج)."},{"f":"استسقاء الضغط السوي (NPH) — الثلاثية والعلاج","b":"ثلاثية «المبلل المترنح الخرف»: سلس بولي + ترنح مشية (gait apraxia) + خرف؛ العلاج: تحويلة (shunt)؛ تحسن المشية بعد البزل التشخيصي منبئ جيد."},{"f":"تشوه آرنولد–خياري النمط الثاني (Chiari II)","b":"انزياح اللوزتين المخيخيتين + تشوهات مرتبطة بالقيلة النخاعية السحائية (myelomeningocele)؛ يسبب استسقاء انسداديًا."},{"f":"القيلة النخاعية السحائية — الوقاية","b":"عيب إغلاق الأنبوب العصبي؛ الوقاية: حمض الفوليك حول الحمل (4 ملغ يوميًا لذوات الخطورة العالية)."},{"f":"متلازمة داندي–ووكر (Dandy-Walker)","b":"توسع الكيسة الخلفية + عدم تنسج الدودة المخيخية؛ تسبب استسقاء انسداديًا بالطفولة المبكرة."},{"f":"تعظم الدروز الباكر (Craniosynostosis) — الأشيع","b":"الأشيع: الدرز السهمي (sagittal) ← جمجمة زورقية (scaphocephaly)؛ الخطر: ارتفاع ICP وتأخر النمو."},{"f":"علامات الاستسقاء الدماغي عند الرضع","b":"زيادة محيط الجمجمة، توتر اليافوخ الأمامي، توسع أوردة الفروة، علامة «غروب الشمس» (sunset eyes)."},{"f":"اختلاطات تحويلة الاستسقاء (VP shunt)","b":"الانسداد (أشيع)، الخمج (المكورات العنقودية البشروية)، فرط التصريف (ورم تحت الجافية) أو نقصه."},{"f":"تضيق مسال سيلفيوس (Aqueduct stenosis)","b":"أشيع سبب للاستسقاء الانسدادي الخلقي؛ قد يكون مرتبطًا بالوراثة المرتبطة بـX."}]},{"t":"أورام الجهاز العصبي المركزي","cards":[{"f":"أشيع ورم داخل قحف بالمطلق وأشيع ورم أولي خبيث","b":"بالمطلق: النقائل (metastases)؛ أشيع ورم أولي خبيث: الورم الأرومي الدبقي (glioblastoma)."},{"f":"الورم الأرومي الدبقي (Glioblastoma) — الصورة الشعاعية","b":"آفة «فراشية» (butterfly) عابرة للجسم الثفني مع تعزز حلقي ونخر مركزي؛ إنذار سيئ رغم الجراحة والتشعيع."},{"f":"الورم السحائي (Meningioma) — العلامة الشعاعية المميزة","b":"أشيع ورم أولي سليم؛ كتلة ملتصقة بالأم الجافية مع «ذيل جافوي» (dural tail) وتعزز متجانس."},{"f":"ورم الغدة النخامية — العرض البصري الكلاسيكي","b":"عمى شقي صدغي مزدوج (bitemporal hemianopia) بانضغاط التصالب البصري؛ البرولاكتيني: ثر اللبن وانقطاع الطمث."},{"f":"الورم الشفاني الدهليزي (Vestibular schwannoma)","b":"ورم الزاوية الجسرية المخيخية؛ فقد سمع حسي عصبي أحادي + طنين؛ العلاج: جراحة أو جراحة شعاعية (gamma knife)."},{"f":"الورم الأرومي النخاعي (Medulloblastoma)","b":"أشيع ورم خبيث بالحفرة الخلفية لدى الأطفال؛ ينتشر عبر CSF (زرع قطرات/drop metastases)؛ العلاج: جراحة + تشعيع قحفي نخاعي."},{"f":"الورم الدبقي قليل التغصن (Oligodendroglioma) — العلامتان المميزتان","b":"نسيجيًا «بيض مقلي» (fried egg) مع تكلسات؛ حذف 1p/19q يستجيب للعلاج الكيميائي."},{"f":"الورم القحفي البلعومي (Craniopharyngioma)","b":"من جيب راتكه؛ أشيع ورم داخل قحف لدى الأطفال؛ تكلس في 50%؛ يسبب قصور نخامية واضطرابات بصرية."},{"f":"لمفوما الجهاز العصبي المركزي الأولية — المرتبط والعلاج","b":"مرتبطة بنقص المناعة (EBV)؛ حساسة للميثوتريكسات؛ تجنب الستيروئيدات قبل الخزعة (تخفي الورم وتضلل التشخيص)."},{"f":"الوذمة حول الورم الدماغي — العلاج الطبي","b":"ديكساميتازون لتخفيف الوذمة وعائية المنشأ حول الأورام؛ مضادات الاختلاج عند حدوث نوبات فقط لا وقائيًا."}]},{"t":"الحوادث الوعائية الدماغية والتقييم العصبي","cards":[{"f":"السكتة الإقفارية — نافذة المذيب الوريدي (tPA)","b":"ألتيبلاز (alteplase) خلال 4.5 ساعات من بدء الأعراض بعد نفي النزف بالـCT؛ موانعه: جراحة حديثة أو نزف فعال."},{"f":"استئصال الخثرة الميكانيكي (Thrombectomy) — النافذة","b":"حتى 24 ساعة لانسداد الأوعية الكبيرة الأمامية مع لب إقفاري صغير (معايير DAWN/DEFUSE)."},{"f":"متلازمة الشريان الدماغي الأوسط (MCA)","b":"شلل نصفي + فقد حسي بالجهة المقابلة (الوجه والذراع > الساق) + حبسة (نصف أيسر) أو إهمال (نصف أيمن) + انحراف النظر نحو الآفة."},{"f":"متلازمة الشريان الدماغي الأمامي (ACA)","b":"ضعف الساق > الذراع بالجهة المقابلة + سلس بولي + تغيرات سلوكية (فقد المبادرة/abulia)."},{"f":"متلازمة الشريان الدماغي الخلفي (PCA)","b":"عمى شقي مماثل (homonymous hemianopia) مقابل ± متلازمة أنطون (إنكار العمى)؛ قد يصيب المهاد."},{"f":"متلازمة الانحباس (Locked-in syndrome)","b":"إصابة الجسر البطني: شلل رباعي + فقد الكلام مع حفظ الوعي وحركات العين العمودية والرمش."},{"f":"النوبة الإقفارية العابرة (TIA) ودرجة ABCD2","b":"عجز عصبي عابر <24 ساعة (غالبًا دقائق)؛ ABCD2 (العمر، الضغط، السريرية، المدة، السكري) ≥4 = خطورة عالية لسكتة خلال أيام."},{"f":"الوقاية الثانوية بعد السكتة الإقفارية","b":"مضاد صفيحات (أسبرين/كلوبيدوغريل) + ستاتين عالي الشدة + ضبط الضغط والسكري؛ عند الرجفان الأذيني: مضاد تخثر فموي."},{"f":"مضادات استطباب البزل القطني","b":"علامات ↑ICP (وذمة حليمة، تدهور وعي)، كتلة بؤرية/انزياح خط وسط، خمج جلدي موضعي، شذوذ تخثر شديد."},{"f":"معايير تشخيص موت الدماغ","b":"سبات عميق لا رجعة فيه + غياب منعكسات جذع الدماغ + اختبار انقطاع النفس إيجابي، بعد نفي المثبطات وانخفاض الحرارة."},{"f":"التهاب الشريان الصدغي (Giant cell arteritis) — العلامة والعلاج الإسعافي","b":">50 سنة + صداع صدغي + عرج الفك + اضطراب بصري؛ الخطر: عمى دائم؛ العلاج: ستيروئيدات عالية فور الاشتباه قبل الخزعة."},{"f":"خثار الجيب الوريدي الدماغي — الأشيع والعلاج","b":"الأشيع: الجيب السهمي العلوي (47%)؛ العلاج: هيبارين/مضاد تخثر حتى مع وجود نزف (مفارقة علاجية مقبولة)."},{"f":"فرط ضغط القحف مجهول السبب (IIH) — النمط والعلاج","b":"شابات بدينات + صداع + وذمة حليمة + شلل العصب السادس الكاذب الموضع؛ العلاج: إنقاص الوزن + أسيتازولاميد."},{"f":"الفحص العصبي للسبات — تنفس تشين–ستوكس يدل على؟","b":"آفة/انضغاط جذع الدماغ أو خلل قشري ثنائي؛ التنفس الشهيقي المتقطع (apneustic): أذية جسرية بإنذار سيئ."},{"f":"النزف تحت العنكبوتية — الاختلاط المتأخر الأشيع","b":"التشنج الوعائي (vasospasm) في الأيام 4–14؛ الوقاية: نيموديبين؛ ومن الاختلاطات أيضًا الاستسقاء وعودة النزف."}]},{"t":"اصابه العصبون المحرك","cards":[{"f":"التصلب الجانبي الضموري (ALS) — التعريف السريري","b":"إصابة مترقية للعصبونين المحركين العلوي والسفلي معًا؛ ضعف + ضمور + ارتجافات حزمية + منعكسات نشطة بلا اضطراب حسي."},{"f":"علامات العصبون المحرك العلوي (UMN) مقابل السفلي (LMN)","b":"علوي: ضعف + فرط منعكسات + تشنج + بابنسكي؛ سفلي: ضعف + ضمور + ارتجافات حزمية + نقص/غياب منعكسات."},{"f":"شلل الأطفال (Polio) — نمط الإصابة الحركية","b":"إصابة العصبون المحرك السفلي فقط (القرون الأمامية): شلل رخو غير متناظر بلا اضطراب حسي."},{"f":"ضمور العضلات الشوكي (SMA) — الوراثة والنمط","b":"وراثة جسدية متنحية (SMN1)؛ ضعف قريب متناظر يبدأ بالطفولة؛ النمط 1 (فيردنيغ–هوفمان) الأشد."},{"f":"الشلل البصلي التقدمي (Progressive bulbar palsy)","b":"إصابة العصبونات المحركة البصلية: عسر بلع + عسر تلفظ + ضعف لسان مع ارتجافات؛ خطر الاستنشاق عالٍ."},{"f":"التصلب الجانبي الأولي (PLS) — ما يميزه عن ALS","b":"إصابة العصبون المحرك العلوي فقط (تشنج وفرط منعكسات بلا ضمور)؛ إنذار أفضل وتطور أبطأ."},{"f":"علاج ALS المعتمد","b":"ريلوزول (riluzole) يبطئ التطور قليلًا؛ الدعم التنفسي والتغذوي أساس التدبير."},{"f":"متلازمة ما بعد شلل الأطفال","b":"ضعف وتعب جديدان بعد عقود من الشلل الأولي في نفس العضلات المصابة سابقًا."}]},{"t":"ملاحظات متفرقه","cards":[{"f":"علامة كيرنيغ وعلامة برودزينسكي","b":"كيرنيغ: ألم/مقاومة عند بسط الركبة مع عطف الورك 90° (تحتاج ~6 ساعات لتتطور)؛ برودزينسكي: عطف لا إرادي للوركين والركبتين عند عطف الرقبة — كلتاهما لتهيج السحايا."},{"f":"وذمة حليمة العصب البصري (Papilledema) — الدلالة","b":"علامة ارتفاع ICP (ثنائية عادة)؛ تستلزم تصويرًا للدماغ قبل البزل القطني."},{"f":"شلل العصب الثالث (CN III) — الصورة الكاملة","b":"هبوط الجفن + توسع الحدقة غير المستجيبة + العين «للأسفل والخارج»؛ في السكري غالبًا تُحفظ الحدقة (إقفار دقيق)."},{"f":"شلل العصب السادس الكاذب الموضع (False localizing VI)","b":"شلل العصب المبعد (lateral rectus) قد يحدث بأي سبب لارتفاع ICP لطول مساره — لا يوطن الآفة."},{"f":"متلازمة هورنر (Horner syndrome) — الثلاثية","b":"هبوط جفن جزئي + تقبض حدقة (miosis) + جفاف الوجه (anhidrosis)؛ أسباب: تسلخ السباتي، ورم بانكوست، إصابة C8-T1."},{"f":"الصرع الرمعي العضلي الحدثي (JME) — العلاج الممنوع","b":"تجنب الكاربامازيبين والفينيتوين (يزيدان النوبات)؛ الخط الأول: فالبروات/ليفيتيراسيتام/لاموتريجين."},{"f":"الحالة الصرعية (Status epilepticus) — التعريف والخط الأول","b":"نوبة >5 دقائق أو نوبات متكررة بلا استعادة وعي؛ الخط الأول: بنزوديازيبين (لورازيبام وريدي)."},{"f":"الصداع العنقودي (Cluster headache) — الصورة والعلاج الحاد","b":"ألم وحشي شديد حول العين + أعراض ذاتية (دمعان، احتقان أنف) بنوب ليلية؛ العلاج الحاد: أكسجين عالي التدفق أو سوماتريبتان."}]},{"t":"سلم تقييم الوعي","cards":[{"f":"مكونات مقياس غلاسكو (GCS) والدرجة العظمى","b":"عينية E (4) + لفظية V (5) + حركية M (6) = 15؛ تُسجل أفضل استجابة في كل فئة."},{"f":"درجات GCS — متى يُنبَّب المريض؟","b":"GCS ≤8 (شديد): فكر بحماية المجرى الهوائي (تنبيب)؛ 9–12 متوسط؛ 13–15 طفيف."},{"f":"الاستجابة الحركية الأسوأ في GCS","b":"M1 = لا استجابة؛ M2 = بسط (منزوع المخ)؛ M3 = عطف شاذ (منزوع القشر) — كلما انخفضت ساء الإنذار."},{"f":"الوضعية منزوعة القشر مقابل منزوعة المخ","b":"منزوعة القشر: عطف الذراعين وبسط الساقين (آفة فوق النواة الحمراء)؛ منزوعة المخ: بسط الكل مع تقوس (آفة تحت النواة الحمراء) — أسوأ إنذارًا."},{"f":"مقياس AVPU","b":"A يقظ (Alert)، V يستجيب للصوت (Vocal)، P يستجيب للألم (Pain)، U غير مستجيب (Unresponsive) — أداة تقييم سريعة أولية."},{"f":"حدقة هاتشنسون (Hutchinson pupil)","b":"توسع حدقة أحادية ثابتة بانفتاق صدغي (انضغاط العصب الثالث) — علامة إنذار جراحي عاجل."},{"f":"أنواع الانفتاق الدماغي","b":"صدغي (uncal) تحت الخيمة، مركزي عبر الخيمة، لوزي (tonsillar/coning) — الأخير يضغط البصلة ويهدد التنفس."},{"f":"تقييم GCS لدى الأطفال الصغار","b":"يُستخدم مقياس غلاسكو المعدل للأطفال (لفظية وحركية مكيفة عمريًا)؛ انظر جداول الأطفال المرجعية."}]},{"t":"أسئلة متفرقة","cards":[{"f":"التهاب السحايا الجرثومي — الثلاثية والبزل","b":"حمى + تيبس رقبة + تغير وعي؛ البزل: ضغط مرتفع، بروتين مرتفع، سكر منخفض، عدلات — ابدأ المضادات قبل البزل إن تأخر."},{"f":"خراج الدماغ — المصدر الأشيع والعلاج","b":"الأشيع: انتشار من التهاب أذن/جيوب أو تجرثم دموي؛ العلاج: مضادات واسعة + تصريف جراحي للخراجات الكبيرة."},{"f":"التهاب الدماغ بالهربس البسيط — الموقع والعلاج","b":"يصيب الفصين الصدغيين؛ العلاج الإسعافي: أسيكلوفير وريدي فور الاشتباه."},{"f":"الوهن العضلي الوبيل (Myasthenia gravis) — الاختبار والعلاج","b":"ضعف يتفاقم بالجهد ويتحسن بالراحة؛ أضداد مستقبل الأستيل كولين؛ العلاج: بيريدوستغمين ± مثبطات مناعة؛ مرتبط بورم التوتة."},{"f":"متلازمة غيلان–باريه (GBS) — الصورة والعلاج","b":"ضعف صاعد متناظر بعد خمج (كامبيلوباكتر) مع غياب منعكسات؛ العلاج: غلوبولين وريدي أو فصل البلازما؛ راقب وظيفة التنفس."},{"f":"التصلب المتعدد (MS) — المعايير الشعاعية","b":"آفات منفصلة زمانيًا ومكانيًا؛ أصابع داوسون (Dawson's fingers) حول البطينات؛ شرائط قليلة النسيلة بالـCSF."},{"f":"داء باركنسون — الرباعية والعلاج الأول","b":"رعاش راحي + صمل + بطء حركة + اضطراب مشية؛ الخط الأول: ليفودوبا (مع كاربيدوبا)."},{"f":"الصرع — متى يُشخَّص بعد نوبة واحدة؟","b":"بعد نوبة واحدة غير مستفزة إذا كان خطر النكس >60% (آفة بنيوية أو شذوذ EEG أو نوب ليلية) — يُبدأ العلاج."}]}]},{"s":"الجراحة العظمية","topics":[{"t":"مبادئ الرضوض والتقييم وتدبير الكسور واختلاطاتها العامة","cards":[{"f":"متلازمة الحيز (Compartment syndrome) — العلامة المبكرة والعلاج","b":"ألم غير متناسب مع الإصابة + ألم شديد بالبسط السلبي؛ العلامات المتأخرة (غياب النبض، الشلل) تعني فوات الأوان؛ العلاج: بضع اللفافة (fasciotomy) إسعافي."},{"f":"متلازمة الانصمام الدهني (Fat embolism) — الثلاثية","b":"الثلاثية: نقص أكسجة + تخليط + طفح فرفري (petechiae) بعد 24–72 ساعة من كسر عظم طويل؛ الوقاية: التثبيت المبكر للكسر."},{"f":"انكماش فولكمان (Volkmann's contracture) — الآلية","b":"انكماش فولكمان الإقفاري: تقلص عاطف ثابت لليد بعد إقفار الساعد (اختلاط كسر فوق اللقمتين)؛ العلاج: تحرير جراحي."},{"f":"معايير كوخر (Kocher criteria) لالتهاب المفصل الإنتاني لدى الأطفال","b":"عدم القدرة على تحميل الوزن + ESR >40 + حرارة >38.5 + كريات بيض >12,000 (أُضيف CRP >20 لاحقًا)؛ 4/4 ≈ 99% التهاب مفصل إنتاني."},{"f":"تدبير الكسور المفتوحة — الخطوة الأولى","b":"الكسور المفتوحة: تنظيف وتغطية بمضادات حيوية (سيفالوسبورين ± أمينوغليكوزيد) بأسرع وقت؛ تصنيف غوستيلو (Gustilo) يحدد الخطورة."},{"f":"كسور عنق الفخذ داخل المحفظة مقابل خارجها — الفرق العلاجي","b":"الكسور داخل المحفظة (intracapsular): خطر نخر لاوعائي لرأس الفخذ (AVN) عالٍ؛ خارج المحفظة (intertrochanteric): التثبيت بالبرغي الديناميكي (DHS)."},{"f":"الحثل الودي الانعكاسي (CRPS) بعد الكسور","b":"ضمور سوديك (Sudeck): ألم حارق + تورم + تغيرات جلدية بعد رض/جبيرة؛ العلاج: تحريك مبكر وعلاج فيزيائي."},{"f":"التثبيت المبكر للكسور — الفائدة","b":"التثبيت المبكر (خلال 24–36 ساعة) يقلل الانصمام الدهني والتهاب الرئة وARDS؛ الكسور غير المستقرة بالحوض والفخذ تُثبت باكرًا."},{"f":"هشاشة العظام (Osteoporosis) — الكسور النموذجية","b":"تناقص الكثافة العظمية + ترقق القشر؛ كسور هشاشة نموذجية: عنق الفخذ، الرسغ (كوليس)، الفقرات."},{"f":"عدم التئام الكسر (Nonunion) مقابل الالتئام المعيب","b":"عدم الالتئام: غياب الجسر العظمي بعد 6–9 أشهر؛ الالتئام المعيب (malunion): التئام بوضعية خاطئة؛ العلاج: تثبيت + تطعيم عظمي."},{"f":"النخر اللاوعائي (AVN) — الكسور الأشيع ارتباطًا به","b":"بسبب التشريح الدموي: رأس الفخذ (داخل المحفظة)، القطب القريب للزورقي، جسم عظم الكاحل (talus)."},{"f":"مراحل التئام الكسور","b":"مراحل الالتئام: ورم دموي ← غضروفي لين ← عظمي صلب ← إعادة تشكيل؛ التثبيت الصلب يلغي التكلس الخارجي (primary healing)."}]},{"t":"كسور وخلوع الطرف العلوي والكتف والرسغ","cards":[{"f":"كسر كوليس (Colles fracture) — الآلية والعلاج","b":"سقوط على يد ممدودة (FOOSH) لدى مسنين بهشاشة؛ تشوه «شوكة العشاء» (dinner fork)؛ العلاج: رد مغلق وجبيرة بمعظم الحالات."},{"f":"كسر العظم الزورقي (Scaphoid) — العلامة والاختلاط","b":"زورقي: ألم العلبة التشريحية (snuffbox) + خطر نخر لاوعائي للقطب القريب؛ هلالي: خلع خطير حول الهلالي (perilunate)."},{"f":"كسر فوق اللقمتين (Supracondylar humerus) لدى الأطفال","b":"الأشيع لدى الأطفال (سقوط على مرفق ممدود)؛ الخطر: إصابة الشريان العضدي والعصب بين العظام الأمامي؛ المراقبة لانكماش فولكمان."},{"f":"كسر الترقوة (Clavicle) — التدبير","b":"غالبًا بالثلث المتوسط؛ العلاج محافظ (حمالة/رباط ثمانية)؛ مؤشرات الجراحة: انزياح شديد أو كسر مفتوح أو إصابة وعائية."},{"f":"خلع الكتف الأمامي — العلامة والعصب المهدد","b":"الخلع الأمامي أشيع (95%): ذراع مبعدة مدورة خارجيًا؛ علامة «الكتف المربع»؛ الخطر: إصابة العصب الإبطي (axillary)."},{"f":"خلع الكتف الخلفي — الآلية والفخ التشخيصي","b":"الخلع الخلفي: بعد نوبة صرع أو صعقة كهربائية؛ ذراع ملتصقة مدورة داخليًا؛ يُفوَّت تشخيصه شعاعيًا — اطلب صورة محورية."},{"f":"عدم استقرار الكتف الأمامي المتكرر — التدبير","b":"الأشيع لدى الشباب الرياضيين؛ العلاج الأولي: تثبيت وعلاج فيزيائي؛ الجراحة (Bankart) عند التكرر."},{"f":"آفتا بانكارت وهيل–ساكس","b":"آفة بانكارت (Bankart): تمزق الشفا الأمامي السفلي؛ آفة هيل–ساكس (Hill-Sachs): انخفاض خلفي وحشي برأس العضد."},{"f":"متلازمة النفق الرسغي — التشخيص والعلاج","b":"انضغاط العصب الناصف؛ اختبارا تينيل وفالن؛ العلاج الجراحي: تحرير الرباط الرسغي المستعرض."},{"f":"تمزق الكفة المدورة (Rotator cuff tear)","b":"تمزق الكفة المدورة: ضعف الإبعاد + اختبار Jobe؛ العلاج: علاج فيزيائي أولًا ثم خياطة جراحية عند الفشل."},{"f":"التهاب غمد دي كيرفان (De Quervain)","b":"التهاب غمد دي كيرفان: التهاب غمد المبعدة الطويلة والباسطة القصيرة للإبهام؛ اختبار فينكلشتاين (Finkelstein)."},{"f":"العقدة (Ganglion) على ظهر الرسغ","b":"عقدة: كيسة مملوءة بسائل زلالي على ظهر الرسغ؛ العلاج: مراقبة غالبًا؛ الاستئصال عند الألم أو الضغط العصبي."},{"f":"إصابة الرباط الجانبي الزندي للإبهام","b":"إبهام متزلج (Gamekeeper's thumb): تمزق الرباط الجانبي الزندي للمفصل المشطي السلامي للإبهام؛ يحتاج تثبيتًا/جراحة."},{"f":"كسرا سميث وبارتون","b":"كسر سميث (Smith's): كوليس معكوس (انزياح راحي)؛ كسر بارتون: داخل مفصلي بحافة الكعبرة."},{"f":"كسر رأس الكعبرة (Radial head fracture)","b":"كسر رأس الكعبرة: ألم وحشي المرفق + عدم القدرة على بسطه؛ العلاج: تحريك مبكر؛ الاستئصال عند التفتت الشديد."}]},{"t":"كسور وخلوع الحوض والطرف السفلي والقدم والكاحل","cards":[{"f":"خلع الورك الخلفي — الآلية والعلامات","b":"الأشيع: الخلفي (لوحة القيادة/dashboard)؛ الساق: قصيرة مدورة داخليًا مثنية؛ الخطر: العصب الوركي (sciatic)؛ الرد العاجل خلال 6 ساعات."},{"f":"كسر عنق الفخذ المزاح لدى المسنين — العلاج","b":"داخل المحفظة: خطر AVN — استبدال مفصل (arthroplasty) للمسنين المزاح؛ خارج المحفظة (بين المدورين): برغي ديناميكي (DHS)."},{"f":"كسر ما بين مدوري الفخذ — الصورة والعلاج","b":"كسر بين المدورين: مسنون بعد سقوط بسيط؛ الساق قصيرة مدورة خارجيًا؛ العلاج: برغي ديناميكي أو مسمار نخاعي."},{"f":"كسر جذع الفخذ — العلاج الأمثل","b":"العلاج الذهبي: مسمار نخاعي (intramedullary nail)؛ التثبيت المبكر يقلل الانصمام الدهني والوفيات."},{"f":"كسر الظنبوب المفتوح — التدبير والاختلاط","b":"الكسور المفتوحة للظنبوب: تنظيف عاجل + تثبيت خارجي ثم مسمار؛ متلازمة الحيز اختلاط شائع — راقب الألم بالبسط السلبي."},{"f":"قواعد أوتاوا للكاحل — متى تُطلب الصورة؟","b":"قواعد أوتاوا: ألم الكاحل + عدم القدرة على المشي 4 خطوات أو ألم عظمي موضع → صورة شعاعية."},{"f":"كسور الكاحل غير المستقرة — العلاج","b":"كسر الكاحل ثنائي/ثلاثي الكعبين غير المستقر: تثبيت جراحي (ORIF)؛ الحفاظ على ملقط الكاحل (mortise) أساسي."},{"f":"كسر عظم الكاحل — الاختلاط المميز","b":"كسر عظم الكاحل (Talus): خطر AVN عالٍ (تروية راجعة)؛ علامة هوكينز (Hawkins sign) تنفي النخر."},{"f":"كسر جونز (Jones fracture)","b":"كسر قاعدة المشط الخامس (Jones): منطقة سيئة التروية — تأخر التئام؛ جبيرة بلا تحميل 6–8 أسابيع."},{"f":"كسر العقب — الآلية والزاوية الشعاعية","b":"كسر العقب (Calcaneus): سقوط من ارتفاع؛ زاوية بوهلر (Bohler) تنخفض؛ العلاج: محافظ غالبًا إلا المفصلية المزاحة."},{"f":"كسر الحوض غير المستقر — التدبير الإسعافي","b":"كسور الحوض: اربط الحوض (pelvic binder) إسعافيًا؛ الخطر: نزف خلف الصفاق — تثبيت خارجي عاجل."},{"f":"كسر الحُق — الاستقصاء والعلاج","b":"كسر الحُق (Acetabulum): CT ثلاثي الأبعاد للتخطيط؛ الكسور المفصلية المزاحة: تثبيت جراحي."},{"f":"خلع الرضفة — الرد","b":"خلع الرضفة: انزياح وحشي مع ألم؛ الرد: بسط الركبة ودفع الرضفة إنسيًا؛ التكرر يستدعي تقييم الرباط."},{"f":"كسر الإجهاد لعنق الفخذ","b":"كسر عنق الفخذ الإجهادي لدى الشباب الرياضيين: ألم أربي يزداد بالنشاط؛ MRI للتشخيص المبكر."},{"f":"تمزق وتر أخيل — الاختبار","b":"تمزق وتر أخيل: اختبار طومسون (Thompson) — غياب العطف الأخمصي بالعصر؛ العلاج: جبيرة بوضعية الخيل أو خياطة جراحية."}]},{"t":"أذيات الأوتار والأربطة والغضاريف والمحفظة المفصلية","cards":[{"f":"تمزق الغضروف الهلالي (Meniscal tear) — الأعراض والاختبارات","b":"تمزق الغضروف الهلالي: ألم خط مفصلي + انقفال/تعليق (locking)؛ اختبارا ماكموراي وأبلي (McMurray/Apley)."},{"f":"تمزق الرباط المتصالب الأمامي (ACL) — الصورة والاختبارات","b":"تمزق الرباط المتصالب الأمامي: صوت فرقعة + تورم سريع (hemarthrosis)؛ اختبارا لاكمان والمحور (Lachman/pivot shift)."},{"f":"كسر سيغوند — الدلالة","b":"كسر سيغوند (Segond): قلع عظمي وحشي الظنبوب — علامة شبه مؤكدة لتمزق ACL."},{"f":"تمزق الرباط المتصالب الخلفي (PCL)","b":"تمزق الرباط المتصالب الخلفي: إصابة لوحة القيادة؛ اختبار الدرج الخلفي (posterior drawer)؛ العلاج غالبًا محافظ."},{"f":"التواء الكاحل الوحشي — الرباط الأول المتمزق","b":"التواء الكاحل الوحشي: تمزق الرباط الشظوي الكاحلي الأمامي (ATFL) أولًا؛ العلاج: RICE + تثبيت وظيفي."},{"f":"تمزق الرباط الجانبي الأنسي (MCL)","b":"إصابة الرباط الجانبي الأنسي للركبة: ألم أنسي + اختبار الإجهاد الأروحي (valgus stress)؛ العلاج غالبًا محافظ (دعامة)."},{"f":"الثلاثية التعيسة (Unhappy triad)","b":"الثلاثية التعيسة: ACL + MCL + الغضروف الهلالي الأنسي — بعد رض التوائي شديد."},{"f":"عدم استقرار الكتف — آفة بانكارت","b":"خلع الكتف المتكرر: آفة بانكارت (تمزق الشفا)؛ العلاج الجراحي: إصلاح بانكارت بالمنظار."},{"f":"تمزق الكفة المدورة الكامل — العلامة","b":"تمزق الكفة المدورة الكامل: «ذراع متساقطة» (drop arm)؛ اختبار Jobe للفوق شوكية."},{"f":"التهاب الوتر الرضفي (Patellar tendinopathy)","b":"التهاب الوتر الرضفي (Jumper's knee): ألم القطب السفلي للرضفة لدى القافزين؛ العلاج: علاج فيزيائي وتقليل الحمل."},{"f":"مرفق التنس مقابل مرفق الغولف","b":"مرفق التنس: التهاب مرتكز الباسطات باللقيمة الوحشية؛ مرفق الغولف: مرتكز العاطفات باللقيمة الإنسية."},{"f":"درجات تمزق العضلات","b":"تمزق العضلة: ألم حاد + كدمة + فجوة محسوسة؛ الدرجة الثالثة (كامل): قد تحتاج خياطة جراحية."}]},{"t":"جراحة عظام الأطفال وتشوهات العمود الفقري وصفائح النمو","cards":[{"f":"تصنيف سالتر–هاريس (Salter-Harris) لكسور صفيحة النمو","b":"I: انفصال الصفيحة فقط؛ II: الأشيع — كسر مشاشي؛ III: داخل مفصلي؛ IV: يعبر الصفيحة؛ V: انضغاط — أسوأ إنذار."},{"f":"الكسر الغصني والحيد لدى الأطفال","b":"الكسر الغصني (greenstick): انكسار القشر بعظم مرن؛ الحيد (torus/buckle): انبعاج القشر — كلاهما شائعان لدى الأطفال."},{"f":"خلع الورك الولادي (DDH) — الاختبارات والعلاج","b":"خلع الورك التطوري: اختبارا أورتولاني وبارلو؛ العلاج: حمالة بافليك (Pavlik) 6–12 أسبوعًا للرضع."},{"f":"داء بيرثيز (Legg-Calvé-Perthes)","b":"نخر لاوعائي لرأس الفخذ مجهول السبب (4–8 سنوات، ذكور)؛ عرج + ألم ركبة محوَّل؛ العلاج: احتواء الرأس (containment)."},{"f":"انزلاق مشاشة رأس الفخذ (SCFE)","b":"مراهق بدين + ألم أربي/ركبة + عرج؛ خط كلاين (Klein's line)؛ العلاج: تثبيت برغي واحد — لا ترد الانزلاق."},{"f":"داء أوزغود–شلاتر (Osgood-Schlatter)","b":"التهاب مرتكز الوتر الرضفي لدى المراهقين الرياضيين؛ ألم وتورم الأحدوبة الظنبوبية؛ حميد ويشفى بإغلاق الصفيحة."},{"f":"مرفق المربية (Nursemaid's elbow)","b":"خلع رأس الكعبرة الجزئي بعد شد ذراع الطفل؛ الطفل يرفض استخدام الذراع؛ الرد: كب الساعد مع عطف المرفق."},{"f":"التهاب العظم والنقي لدى الأطفال — الجرثوم الأشيع","b":"التهاب العظم والنقي لدى الأطفال: المكورات العنقودية الذهبية؛ البؤرة: مشاش العظام الطويلة؛ العلاج: مضادات وريدية مطولة."},{"f":"التهاب المفصل الإنتاني لدى الأطفال — التدبير","b":"التهاب المفصل الإنتاني لدى الأطفال: إسعاف جراحي (غسل المفصل) + مضادات؛ التأخر يدمر الغضروف."},{"f":"الجنف مجهول السبب (Adolescent idiopathic scoliosis)","b":"الجنف مجهول السبب لدى المراهقات؛ اختبار الانحناء الأمامي (Adam's)؛ الجراحة عند زاوية كوب >45–50°."},{"f":"داء شويرمان (Scheuermann's disease)","b":"الحداب الشبابي (Scheuermann): تحدب صدري مؤلم لدى المراهقين مع تغيرات مشاشية؛ العلاج محافظ غالبًا."},{"f":"القدم الحنفاء — طريقة بونسيتي","b":"القدم الحنفاء (Clubfoot): حنف فحجي؛ طريقة بونسيتي (Ponseti): جبائر متسلسلة ثم حذاء دينيس براون."},{"f":"انزلاق الفقار — العلامة الشعاعية","b":"انزلاق الفقار (Spondylolisthesis): انزلاق أمامي غالبًا L5-S1؛ علامة الكلب الاسكتلندي (Scotty dog) بالصورة المائلة."},{"f":"التهاب الفقار لدى اليافعين — الصورة","b":"التهاب الفقار المقسط لدى الأطفال: ألم ظهري ليلي يتحسن بالحركة؛ HLA-B27؛ العلاج: مضادات الالتهاب والعلاج الفيزيائي."},{"f":"كسر الترقوة الولادي","b":"كسور الترقوة الولادية: أشيع كسر ولادي؛ تشفى تلقائيًا بلا تداخل غالبًا."}]},{"t":"أمراض المفاصل التنكسية والإنتانات العظمية المفصلية","cards":[{"f":"الفصال العظمي (Osteoarthritis) — المفاصل الأشيع والعلاج","b":"تآكل الغضروف المفصلي؛ الأشيع: الركبة والورك؛ الألم يزداد بالحركة ويتحسن بالراحة؛ العلاج: إنقاص وزن + علاج فيزيائي ثم استبدال مفصل."},{"f":"التهاب المفصل الإنتاني — التشخيص والتدبير","b":"التهاب مفصل إنتاني: مفصل واحد مؤلم متورم + حمى؛ البزل: عكارة وعدلات عالية؛ إسعاف: غسل جراحي + مضادات."},{"f":"التهاب العظم والنقي المزمن — العلامات الشعاعية","b":"التهاب العظم والنقي: المكورات العنقودية الذهبية؛ العلامات الشعاعية: عزل (sequestrum) وغلاف (involucrum) ومنفذ (cloaca)."},{"f":"خراج برودي (Brodie abscess)","b":"خراج برودي (Brodie abscess): التهاب عظم ونقي تحت حاد بآفة حالة متوضعة بالمشاش؛ العلاج: تنظيف + مضادات."},{"f":"التهاب المفاصل الرثياني — الصورة والعلاج","b":"التهاب المفاصل الرثياني: مفاصل صغيرة متناظرة + تيبس صباحي >30 دقيقة؛ العلاج: ميثوتريكسات باكرًا."},{"f":"النقرس — البلورات والعلاج","b":"النقرس: التهاب مفصل وحيد حاد (إبهام القدم) ببلورات يورات؛ العلاج الحاد: كولشيسين/مضاد التهاب؛ المزمن: ألوبورينول."},{"f":"التهاب المفاصل الصدفي — العلامة المميزة","b":"التهاب المفاصل الصدفي: التهاب الأصابع السجقية (dactylitis) + تغيرات الأظافر؛ مرتبط بـHLA-B27 جزئيًا."},{"f":"مفصل شاركو العصبي","b":"مفصل شاركو (Charcot): مفصل لا مؤلم مدمر باعتلال أعصاب (سكري)؛ العلاج: تثبيت وحماية لا جراحة تقويمية."}]},{"t":"أورام العظام السليمة والخبيثة والآفات شبيهة الورم","cards":[{"f":"الساركوما العظمية (Osteosarcoma) — الصورة الشعاعية","b":"ورم خبيث عدواني بالمشاش حول الركبة/العضد القريب؛ شعاعيًا: «أشعة الشمس» (sunburst) ومثلث كودمان (Codman triangle)؛ العلاج: كيميائي + استئصال."},{"f":"ساركوما يوينغ (Ewing sarcoma)","b":"جذع العظام الطويلة لدى الأطفال/المراهقين؛ «قشر البصل» (onion skin)؛ انتقال كروموسومي t(11;22)."},{"f":"ورم الخلايا العملاقة (Giant cell tumour)","b":"آفة مشاشية لدى الشباب؛ «فقاعة الصابون» (soap bubble)؛ سليم لكنه عدواني موضعيًا — يُجرف ويُطعم."},{"f":"الورم العظمي الغضروفي (Osteochondroma)","b":"أشيع ورم عظمي سليم؛ نتوء عظمي بغطاء غضروفي قرب صفيحة النمو؛ يُستأصل عند الأعراض فقط."},{"f":"الساركوما الغضروفية (Chondrosarcoma)","b":"ورم غضروفي خبيث لدى كبار السن؛ مقاوم للكيميائي — العلاج جراحي أساسًا."},{"f":"الكيسة العظمية البسيطة (Simple bone cyst)","b":"كيسة عظمية أم دم بسيطة لدى الأطفال بالمشاش؛ «قطعة ساقطة» (fallen fragment)؛ تشفى تلقائيًا غالبًا."},{"f":"خلل التنسج الليفي (Fibrous dysplasia)","b":"خلل التنسج الليفي: آفة «الزجاج المطحون» (ground glass)؛ قد يترافق مع متلازمة ماكيون–أولبرايت."},{"f":"النقائل العظمية — الأوليات الأشيع","b":"النقائل العظمية: الأشيع (ثدي، بروستات، رئة، كلية، درق)؛ آفات البروستات مصلبة (blastic) والبقية حالة غالبًا."}]}]},{"s":"جراحة الصدر","topics":[{"t":"رضوض الصدر والأذيات الإسعافية","cards":[{"f":"الريح الصدرية الموترة (Tension pneumothorax) — العلامات والتدبير الإسعافي","b":"انحراف الرغامى بعيدًا + أوردة وداجية منتفخة + هبوط ضغط + رنين مفرط؛ العلاج الإسعافي: تخفيف الضغط بإبرة (الورب الثاني خط منتصف الترقوة) ثم أنبوب صدري."},{"f":"المصراع الصدري (Flail chest) — التعريف والتدبير","b":"كسر 3 أضلاع متتالية أو أكثر بكسرين لكل ضلع؛ حركة متناقضة (paradoxical)؛ المشكلة الأساسية: الكدمة الرئوية الكامنة؛ العلاج: تسكين فعال (فوق الجافية) ودعم تنفسي."},{"f":"انصباب الجنب الدموي الضخم (Massive hemothorax) — عتبة بضع الصدر","b":">1500 مل فورًا أو >200 مل/ساعة لـ4 ساعات ← بضع الصدر الإسعافي؛ الأقل: أنبوب صدري كبير."},{"f":"السطام التاموري الرضي (Cardiac tamponade) — الثلاثية","b":"ثالوث بيك (Beck): أصوات قلب خافتة + أوردة وداجية منتفخة + هبوط ضغط؛ نبض متناقض (pulsus paradoxus)؛ العلاج: بزل التامور."},{"f":"تمزق الأبهر الرضي — الآلية والموقع","b":"آلية التباطؤ العنيف (حادث سير)؛ اتساع المنصف بالصورة؛ التمزق غالبًا عند البرزخ (isthmus)؛ التشخيص: طبقي وعائي؛ العلاج: إصلاح عاجل."},{"f":"الريح الصدرية المفتوحة (Open pneumothorax) — التدبير","b":"جرح صدري مفتوح «يمص» الهواء؛ العلاج الإسعافي: ضماد ثلاثي الجوانب ثم أنبوب صدري — لا تغلقه تمامًا."},{"f":"الكدمة الرئوية (Pulmonary contusion) — التوقيت والتدبير","b":"كدمة رئوية: نقص أكسجة متأخر 24–48 ساعة؛ العلاج داعم (أكسجين، تقييد سوائل حكيم) — تجنب فرط الإماهة."},{"f":"تمزق الطريق الهوائي الرضي — العلامة","b":"تمزق القصبة/الشعب: نفاخ تحت الجلد + تسرب هوائي مستمر بأنبوب الصدر؛ التشخيص: تنظير قصبي؛ العلاج جراحي."},{"f":"تمزق الحجاب الحاجز الرضي","b":"تمزق الحجاب: أحشاء بالصدر (أصوات أمعاء صدرية)؛ الأشيع أيسر؛ التشخيص: طبقي؛ العلاج: إصلاح جراحي."},{"f":"أولويات تدبير رضوض الصدر — تسلسل ATLS","b":"أولًا: مجرى هوائي وتنفس ودوران (ABC)؛ أنبوب صدري للنزف/الريح؛ بضع الصدر الإسعافي لغرفة الطوارئ عند توقف القلب بجرح نافذ."},{"f":"النفاخ تحت الجلد الصدري — الدلالة","b":"نفاخ تحت الجلد: فرقعة ملموسة؛ سببه غالبًا تسرب هوائي من الرئة/الأنبوب؛ راقب تطور الريح الموترة."},{"f":"كسور الأضلاع — التدبير وعلامة الخطورة","b":"كسور الأضلاع البسيطة: تسكين كافٍ وتمارين تنفسية (الوقاية من ذات الرئة)؛ كسور الأضلاع 1–3 العالية: ابحث عن إصابة وعائية."},{"f":"خلع المفصل القصي الترقوي الخلفي","b":"خلع المفصل القصي الترقوي الخلفي: قد يضغط المنصف؛ الرد المغلق بحذر أو جراحي."},{"f":"انصباب الجنب الدموي المتخثر — التدبير","b":"النزف الصدري المتأخر: تجمع دموي متخثر (clotted hemothorax) — يحتاج تنظير/بضع صدر للتنظيف لا أنبوب فقط."},{"f":"الجرح القلبي النافذ — التدبير الجراحي","b":"إصابة القلب النافذة: بضع التامور وتخييط الجرح القلبي؛ الأكثر نجاة: إصابات البطين الأيمن الأمامي."}]},{"t":"أمراض وجراحة الجنب","cards":[{"f":"الريح الصدرية العفوية الأولية — النمط والعلاج","b":"شبان طوال نحيلون؛ تمزق فقاعات قمية؛ العلاج: أنبوب صدري؛ التكرر: جراحة (استئصال فقاعات + التصاق الجنب)."},{"f":"الريح الصدرية العفوية الثانوية","b":"مرافقة لأمراض رئوية (COPD/تليف)؛ أخطر وأعلى تكررًا؛ العلاج: أنبوب صدري + معالجة السبب."},{"f":"تقيح الجنب (Empyema) — التدبير","b":"قيح صريح بالجنب (empyema)؛ العلاج: تصريف كامل (أنبوب/تنظير) + مضادات؛ المتأخر المتليف: تقشير الجنب (decortication)."},{"f":"ورم المتوسطة (Mesothelioma) — المرتبط","b":"مرتبط بالأسبستوس؛ انصباب جنبي نازف؛ التشخيص: خزعة جنبية؛ الإنذار سيئ."},{"f":"الانصباب الجنبي الرشحي (Transudate) — الأسباب","b":"بروتين منخفض وLDH منخفض (معايير لايت)؛ الأسباب: قصور قلب، تشمع، نفروز؛ العلاج: معالجة السبب."},{"f":"الانصباب الجنبي النضحي (Exudate) — الأسباب","b":"بروتين/LDH مرتفعان؛ الأسباب: خمج، خباثة، انصمام رئوي؛ التشخيص: بزل ودراسة السائل."},{"f":"انصباب الجنب الكيلوسي (Chylothorax)","b":"انصباب كيلوسي (حليبي) بتمزق القناة الصدرية؛ العلاج: صيام + تغذية وريدية؛ المستمر: ربط القناة جراحيًا."},{"f":"موضع إدخال أنبوب الصدر — مثلث الأمان","b":"مثلث الأمان: أمامي الحافة الأمامية للعريضة، خلفي خط منتصف الإبط، علوي الحلمة/الورب الخامس؛ لتجنب الأوعية والأعصاب."},{"f":"انصباب الجنب الدموي الهوائي (Hemopneumothorax)","b":"دم + هواء معًا؛ العلاج: أنبوب صدري؛ راقب النزف المستمر لاستطباب بضع الصدر."},{"f":"تليف الجنب وحصر الرئة — العلاج","b":"تثخن الجنب الليفي بعد تقيح/انصباب مسببًا حصر الرئة (trapped lung)؛ العلاج: تقشير الجنب (decortication)."},{"f":"التهاب الجنب الفيروسي — الصورة","b":"ألم جنبي + حمى + انصباب؛ غالبًا فيروسي؛ العلاج: مضادات التهاب ومراقبة."},{"f":"إلصاق الجنب (Pleurodesis) — الاستطباب","b":"التصاق الجنب الكيميائي (talc) أو الميكانيكي لمنع تكرر الريح/الانصباب الخبيث."},{"f":"الانصباب الجنبي الخبيث — التدبير التلطيفي","b":"انصباب خبيث: تصريف + إلصاق أو قثطار دائم (PleurX) للراحة التلطيفية."},{"f":"الورم الليفي المنفرد بالجنب","b":"ورم ليفي منفرد بالجنب (solitary fibrous tumour): سليم غالبًا؛ الاستئصال شافٍ."},{"f":"خزعة الجنب — متى تُجرى؟","b":"خزعة الجنب بالإبرة/التنظير عند الاشتباه بالسل أو الخباثة؛ السائل: ADA مرتفع يوحي بالسل."}]},{"t":"سرطان الرئة والنقائل الورمية","cards":[{"f":"أنواع سرطان الرئة النسيجية — الأشيع","b":"الأشيع: الغدية (adenocarcinoma)؛ الحرشفية مركزية؛ صغيرة الخلايا: الأسرع انتشارًا ومرتبطة بالتدخين الشره."},{"f":"ورم بانكوست (Pancoast tumour) — الصورة","b":"ورم الثلم العلوي (Pancoast): ألم كتف/ذراع + هورنر + ضمور يد (T1)؛ T3 بالتعريف؛ العلاج: كيميائي شعاعي ثم استئصال."},{"f":"متلازمة الوريد الأجوف العلوي (SVC syndrome)","b":"انسداد الوريد الأجوف العلوي: تورم وجه ورقبة + أوردة صدرية متوسعة؛ العلاج: دعامة/شعاع إسعافي."},{"f":"المتلازمات نظيرة الورمية في سرطان الرئة","b":"صغيرة الخلايا: SIADH (نقص صوديوم)؛ الحرشفية: فرط كالسيوم (PTHrP)؛ الغدية: التهاب جلد وعضل أحيانًا."},{"f":"النقائل البعيدة لسرطان الرئة — الأشيع","b":"الأشيع: دماغ، عظم، كظر، كبد؛ أي نقائل بعيدة = مرحلة IV غير قابلة للاستئصال الشافي."},{"f":"سرطان الرئة القابل للاستئصال — العلاج","b":"المراحل I–II والـIIIA المحدودة: استئصال جراحي (فص/رئة) + تشريح عقد لمفاوية؛ الهامش السالب أساسي."},{"f":"تشخيص سرطان الرئة — تنظير أم خزعة إبرة؟","b":"التنظير الشعبي: تشخيص الآفات المركزية؛ الخزعة بالإبرة عبر الصدر: للآفات المحيطية."},{"f":"تدريج سرطان الرئة — الاستقصاءات","b":"PET-CT للتدريج البعيد؛ تنظير المنصف (mediastinoscopy) لعقد المنصف المشبوهة."},{"f":"ناسور قصبي جنبي بعد استئصال الرئة","b":"الاختلاط: ناسور قصبي جنبي (bronchopleural fistula) بعد استئصال الرئة؛ الوقاية: تغطية الجذع بعضلة/جنب."},{"f":"العقدة الرئوية المنفردة — متى تُستقصى؟","b":"العقدة الوحيدة الرئوية (SPN): >8 مم + مدخن ← PET/خزعة؛ النمو السريع يوحي بالخباثة."},{"f":"الورم السرطاني الرئوي (Carcinoid)","b":"ورم سرطاني رئوي (carcinoid): سليم نسبيًا؛ متلازمة سرطانية عند النقائل الكبدية؛ العلاج: استئصال محافظ."},{"f":"النقائل الرئوية — الأوليات الأشيع","b":"النقائل الرئوية: الأشيع من (قولون، كلية، ثدي، عظم)؛ الاستئصال الجراحي ممكن عند المحدودة والقابلة."},{"f":"أورام المنصف الخلوية الجنسية — الواسمات","b":"ورم المنصف الأمامي لدى شاب + AFP/β-hCG مرتفعان = ورم خلية جنسية؛ العلاج: كيميائي أولًا."},{"f":"التدخين وجراحة الصدر","b":"التدخين: عامل الخطر الأول؛ الإقلاع قبل الجراحة بـ4 أسابيع يقلل الاختلاطات."},{"f":"تقييم القابلية لاستئصال الرئة — الاختبارات","b":"اختبار وظائف الرئة قبل الاستئصال: FEV1 وDLCO المتوقعان بعد الجراحة يحددان القابلية."}]},{"t":"الآفات الرئوية الإنتانية والخمجية","cards":[{"f":"الكيسة المائية الرئوية (Hydatid cyst) — العامل والاختلاط","b":"المشعرات الإيكينوكوكية؛ سعال + نفث دم + قشع مواد الكيسة؛ تمزقها: صدمة تأقية؛ التشخيص: مصلية + طبقي."},{"f":"الورم الرشاشي (Aspergilloma) — العلامة الشعاعية","b":"علامة الهلال الهوائي (air crescent)؛ لدى مرضى التجاويف (سل قديم)؛ العلاج: مضاد فطري أو استئصال عند النفث الشديد."},{"f":"خراج الرئة — العلاج","b":"خراج الرئة: مستوى سائل–هواء بتجويف؛ الجراثيم: لاهوائية (استنشاق)؛ العلاج: مضادات مطولة؛ الجراحة عند الفشل."},{"f":"توسع القصبات (Bronchiectasis) — الصورة والعلاج","b":"توسع قصبي: سعال مزمن + قشع قيحي + «ترام القطار» شعاعيًا؛ العلاج: تصريف وضعي ومضادات؛ المستعصي: استئصال فص."},{"f":"السل الرئوي — متى تُستطب الجراحة؟","b":"السل الرئوي: تكهفات علوية؛ العلاج: 4 أدوية أولية؛ الجراحة: للنزف المستعصي أو الورم المشبوه."},{"f":"ذات الرئة الاستنشاقية — الفص الأشيع","b":"ذات الرئة الاستنشاقية: الفص السفلي الأيمن (قصبة أقصر وأوسع وأكثر عمودية)؛ الوقاية: حماية مجرى الهواء."},{"f":"الداء الرشاشي الغازي (Invasive aspergillosis)","b":"الداء الرشاشي الغازي لدى مثبطي المناعة؛ العلاج: فوريكونازول."},{"f":"داء النوكارديا الرئوي","b":"النوكارديا: لدى مثبطي المناعة؛ تجاويف رئوية + آفات دماغية؛ العلاج: كوتريموكسازول مطول."},{"f":"ذات الرئة بالمتكيسة الجيروفيسية (PJP)","b":"التهاب رئة بالمتكيسة (PJP) لدى الإيدز: نقص أكسجة + «زجاج مصنفر»؛ العلاج: كوتريموكسازول عالي الجرعة."},{"f":"الدبيلة الجنبية بعد ذات الرئة","b":"الدبيلة تحت الجنب بعد ذات رئة؛ العلاج: تصريف + مضادات؛ المتأخر: تقشير."},{"f":"التهاب شغاف الصمام ثلاثي الشرف — الفئة","b":"التهاب الشغاف الرئوي نادر؛ الأشيع: مدمنو الحقن الوريدية (صمام ثلاثي الشرف)."},{"f":"الورم الحبيبي الحبيبي (GPA) الرئوي","b":"الورم الحبيبي بفيغنر (GPA): تجاويف رئوية + التهاب كبيبات + c-ANCA؛ العلاج: مثبطات مناعة."},{"f":"الساركوئيد الرئوي — العلامة","b":"الساركوئيد: اعتلال عقد لمفاوية سرية ثنائي + عقيدات؛ التشخيص: خزعة بحبيبومات غير متجبنة."},{"f":"التليف الرئوي مجهول السبب — الصورة","b":"التليف الرئوي مجهول السبب: «عسل النحل» (honeycombing) قاعدي؛ العلاج: مضادات تليف؛ النهائي: زرع رئة."},{"f":"نفث الدم الضخم — التدبير","b":"نفث الدم الضخم: >300 مل/24 ساعة؛ التدبير: حماية الرئة السليمة (أنبوب مزدوج) + تنظير/إصمام شرياني."}]},{"t":"تشوهات جدار الصدر وأورام المنصف","cards":[{"f":"تشوهات جدار الصدر — الأشيع","b":"الأشيع: التقعر (excavatum)؛ الجراحة (Nuss/Ravitch) عند الأعراض أو الشدة."},{"f":"أورام المنصف حسب الحيز — قاعدة 4T","b":"المنصف الأمامي: 4T (توتة thymoma، مسخي teratoma، درقية، لمفوما terrible lymphoma)؛ الأوسط: عقد لمفاوية؛ الخلفي: عصبية."},{"f":"ورم التوتة (Thymoma) — المرتبط","b":"ورم التوتة: مرتبط بالوهن العضلي الوبيل (30%)؛ العلاج: استئصال جراحي كامل."},{"f":"الورم المسخي بالمنصف (Teratoma)","b":"الورم المسخي: قد يحتوي أسنانًا/شعرًا؛ السليم يُستأصل؛ الخبيث: كيميائي."},{"f":"لمفوما المنصف — العلاج","b":"اللمفوما بالمنصف: كتلة أمامية لدى شاب + أعراض B؛ التشخيص: خزعة؛ العلاج: كيميائي لا جراحي."},{"f":"أورام المنصف الخلفي — المنشأ","b":"أورام المنصف الخلفي: عصبية المنشأ (شوانوما، نوروبلاستوما لدى الأطفال)."},{"f":"الكيسة التامورية (Pericardial cyst)","b":"الكيسة التامورية: سليمة غالبًا بالزاوية القلبية الحجابية اليمنى؛ مراقبة."},{"f":"الدرقية المنصفية (Substernal goiter)","b":"الدرقية المنصفية: امتداد درقية رقبية؛ قد تسبب انضغاط رغامى؛ العلاج: استئصال."},{"f":"تنظير المنصف — الاستطباب","b":"تنظير المنصف (mediastinoscopy): خزعة عقد المنصف لتدريج سرطان الرئة."}]},{"t":"الإجراءات الصدرية وتدبير الطريق الهوائي","cards":[{"f":"تنظير القصبات مقابل تنظير الصدر (VATS)","b":"تنظير القصبات: تشخيص مركزي + إزالة أجسام أجنبية؛ تنظير الصدر (VATS): خزعة وتدبير الريح والانصباب."},{"f":"بضع الصدر (Thoracotomy) — المدخل الكلاسيكي","b":"بضع الصدر الخلفي الوحشي: المدخل الكلاسيكي لجراحة الرئة؛ الحفاظ على العضلات يقلل الألم."},{"f":"بضع القص المتوسط (Median sternotomy)","b":"بضع القص المتوسط: المدخل لجراحة القلب؛ الاختلاط: التهاب المنصف (mediastinitis) — وقاية صارمة."},{"f":"أنبوب الرغامى مزدوج اللمعة — الغرض","b":"الأنبوب المزدوج اللمعة (double-lumen): تهوية رئة واحدة لجراحة الصدر؛ التأكد: تنظير ليفي."},{"f":"بضع الغشاء الحلقي الدرقي — الاستطباب","b":"بضع الغشاء الحلقي الدرقي (cricothyroidotomy): مجرى هوائي إسعافي عند تعذر التنبيب."},{"f":"فغر الرغامى (Tracheostomy) — الاستطباب","b":"فغر الرغامى: للتهوية المطولة (>14 يومًا)؛ الاختلاط المتأخر: تضيق رغامى."},{"f":"التصريف تحت الختم المائي — قراءة العلامات","b":"تصريف تحت ختم مائي (underwater seal): فقاعات مستمرة = تسرب هوائي؛ توقف التموج = انسداد/توسع."},{"f":"متى يُزال أنبوب الصدر؟","b":"إزالة أنبوب الصدر: عند توقف التصريف (<200 مل/يوم) وتوسع الرئة وغياب التسرب."},{"f":"النزف بعد جراحة الصدر — عتبة إعادة الفتح","b":"النزف بعد بضع الصدر: >200 مل/ساعة أو عدم استقرار ← إعادة فتح إسعافية."},{"f":"التهاب المنصف بعد بضع القص","b":"التهاب المنصف بعد بضع القص: حمى + ألم قصي + عدم استقرار؛ العلاج: تنظيف جراحي عاجل + مضادات."},{"f":"تسكين ما بعد بضع الصدر","b":"الألم بعد بضع الصدر: التسكين فوق الجافية الذهبي؛ الألم المزمن: أذية العصب الوربي."},{"f":"زرع الرئة — الاستطباب والاختلاط","b":"زرع الرئة: للتليف المتقدم وCOPD النهائي؛ الاختلاط: رفض حاد/مزمن (bronchiolitis obliterans)."}]},{"t":"أسئلة متفرقة","cards":[{"f":"الانصمام الرئوي — الثلاثية السريرية","b":"الانصمام الرئوي: ألم جنبي + تسرع تنفس + نقص أكسجة؛ التشخيص: طبقي وعائي؛ العلاج: مضاد تخثر."},{"f":"القاعدة الذهبية للريح الموترة","b":"استرواح الصدر الضاغط يحتاج تخفيفًا فوريًا بلا انتظار الصورة عند الاشتباه السريري."},{"f":"COPD — العلاج الأساسي","b":"الداء الرئوي المسد المزمن: انتفاخ رئة + التهاب قصبات؛ العلاج: موسعات + إقلاع تدخين؛ النهائي: زرع."},{"f":"الربو الحاد الشديد — علامة الخطر","b":"الربو الحاد الشديد: صمت صدري = علامة خطر؛ العلاج: أكسجين + نيبولايزر + ستيروئيد وريدي."},{"f":"ألم ذات الجنب — الصفة","b":"ذات الجنب: ألم يزداد بالتنفس العميق؛ يُفرَّق عن الألم القلبي بالفحص والصفات."},{"f":"التهاب التامور — الصورة","b":"التهاب التامور: ألم يتحسن بالانحناء للأمام؛ احتكاك تاموري؛ تخطيط: ST مرتفع منتشر + PR منخفض."},{"f":"تسلخ الأبهر — وصف الألم","b":"تسلخ الأبهر: ألم صدري «ممزق» مهاجر للظهر؛ العلاج: خفض ضغط ونبض عاجل."},{"f":"النزف السنخي — الأسباب","b":"النزف السنخي: نفث دم + فقر دم + رشاحات؛ الأسباب: متلازمة غودباستشر والتهاب الأوعية."}]}]},{"s":"جراحة القلب","topics":[{"t":"دارة القلب والرئة الاصطناعية","cards":[{"f":"دارة القلب–الرئة الاصطناعية (CPB) — المكونات الأساسية","b":"تحويل الدم عبر مؤكسج خارجي؛ التبريد لخفض الاستقلاب؛ شلل القلب بالمحلول القلبي (cardioplegia) الغني بالبوتاسيوم؛ الهيبارين مع ACT >480 ثانية."},{"f":"المحلول القلبي (Cardioplegia) — الغرض والتركيب","b":"محلول غني بالبوتاسيوم يوقف القلب بالانبساط لحماية العضلة أثناء الجراحة؛ يُعطى أماميًا وخلفيًا."},{"f":"التخثر أثناء الدارة — الهيبارين والبروتامين","b":"الهيبارين بجرعة كاملة ثم البروتامين للعكس بعد الدارة؛ مراقبة ACT كل 20–30 دقيقة."},{"f":"اختلاطات دارة القلب–الرئة","b":"الاختلاطات: نزف، سكتة (هواء/جسيمات)، فشل كلوي، التهاب جهازي، اضطراب إدراكي بعد الجراحة."},{"f":"جراحة المجازات بلا دارة (Off-pump CABG)","b":"جراحة بلا دارة على قلب نابض؛ تُستخدم للمرضى عاليي الخطورة؛ تتطلب مثبتات عضلة القلب."},{"f":"درجة يوروسكور (EuroSCORE) — الغرض","b":"تقييم خطورة جراحة القلب: العمر، الكسر القذفي، القصور الكلوي، الجراحة الإسعافية — يحدد الوفيات المتوقعة."},{"f":"التبريد أثناء جراحة القلب — الفائدة","b":"انخفاض حرارة الجسم: يخفض استهلاك الأكسجين الدماغي ويحمي أثناء توقف الدوران."},{"f":"توقف الدوران بخفض الحرارة العميق (DHCA)","b":"توقف الدوران بخفض الحرارة العميق (DHCA): لجراحة قوس الأبهر؛ حماية دماغية محدودة زمنيًا (~30–40 دقيقة)."}]},{"t":"داء الشرايين الإكليلية وجراحة المجازات","cards":[{"f":"جراحة المجازات (CABG) — الطعم الذهبي","b":"الشريان الثديي الداخلي الأيسر (LIMA) إلى الأمامي النازل (LAD) — الأعلى بقاءً (>90% لعشر سنوات)؛ الوريد الصافن للبقية."},{"f":"استطبابات جراحة المجازات مقابل القثطرة","b":"تضيق الجذع الأيسر، ثلاثي الأوعية (خاصة مع السكري)، فشل القثطرة؛ الأعراض المستعصية رغم العلاج الأمثل."},{"f":"بقاء الطعوم — الوريدي مقابل الشرياني","b":"فشل الطعم الوريدي تدريجي (50% لعشر سنوات) مقابل بقاء الشرياني؛ الأسبرين مدى الحياة بعد الجراحة."},{"f":"الاحتشاء الحاد بارتفاع ST — العلاج الإسعافي","b":"احتشاء حاد: ألم صدري ضاغط + ارتفاع ST؛ العلاج: قثطرة عاجلة (PCI) خلال 120 دقيقة أو مذيب."},{"f":"العلاج الدوائي بعد الاحتشاء (DAPT)","b":"بعد الاحتشاء: أسبرين + مثبط P2Y12 (تيكاغريلور/كلوبيدوغريل) لمدة سنة + ستاتين + مثبط ACE."},{"f":"الاختلاطات الميكانيكية للاحتشاء الحاد","b":"تمزق الحاجز بين البطينين، تمزق العضلة الحليمية (قلس تاجي حاد)، تمزق الجدار الحر — كلها إسعاف جراحي."},{"f":"الذبحة المستقرة — العلاج","b":"الذبحة المستقرة: ألم جهدي يزول بالراحة/النتروغليسرين؛ العلاج: أسبرين + ستاتين + حاصر بيتا."},{"f":"تشخيص داء الشرايين الإكليلية — التسلسل","b":"اختبار الجهد: لتشخيص الإقفار؛ القثطرة التشخيصية: الذهبية لتقييم التشريح قبل القرار."},{"f":"داء الشرايين لدى السكري — مجازات أم قثطرة؟","b":"السكري: المجازات أفضل من القثطرة بثلاثي الأوعية (دراسة FREEDOM) لانخفاض الوفيات والاحتشاء."},{"f":"النزف بعد جراحة المجازات — عتبة إعادة الفتح","b":"النزف بعد المجازات: >200 مل/ساعة ← إعادة فتح؛ الوقاية: إيقاف مضادات التخثر قبل الجراحة بمدة محسوبة."},{"f":"الرجفان الأذيني بعد جراحة القلب","b":"الرجفان الأذيني بعد الجراحة: شائع (يوم 2–3)؛ العلاج: حاصر بيتا وقائيًا + تقويم نظم عند الحاجة."},{"f":"إقفار المساريق بعد جراحة القلب","b":"إقفار المساريق/الأطراف بعد الدارة: ألم بطني + حماض لبني؛ إسعاف جراحي وعائي."}]},{"t":"أمراض صمامات القلب وجراحتها","cards":[{"f":"تضيق الأبهر (Aortic stenosis) — الثلاثية السريرية","b":"ثلاثية SAD: إغماء (syncope) + ذبحة (angina) + ضيق نفس (dyspnea)؛ النفخة: انقباضية قذفية بالحافة اليمنى تنتشر للرقبة."},{"f":"تضيق الأبهر العرضي — العلاج","b":"عند ظهور الأعراض: استبدال الصمام (جراحي SAVR أو قثطاري TAVR)؛ TAVR لكبار السن عاليي الخطورة."},{"f":"قلس الأبهر (Aortic regurgitation) — العلامات","b":"اتساع الضغط النبضي + علامات محيطية (كوريغان، كوينكه)؛ النفخة: انبساطية مبكرة بالحافة اليسرى."},{"f":"تضيق التاجي (Mitral stenosis) — السبب والعلامات","b":"السبب الأشيع: الحمى الرثوية؛ طقة انفتاح + نفخة انبساطية بالذروة؛ الاختلاط: رجفان أذيني وتضخم أذين أيسر."},{"f":"قلس التاجي (Mitral regurgitation) — النفخة","b":"النفخة: انقباضية شاملة (holosystolic) بالذروة تنتشر للإبط؛ السبب الحاد: تمزق حبال/عضلة حليمية."},{"f":"الصمام الميكانيكي مقابل الحيوي","b":"الخيار: ميكانيكي (دائم + وارفارين مدى الحياة) أم حيوي (10–15 سنة بلا تخثر دائم) — حسب العمر والرغبة."},{"f":"التهاب الشغاف الخمجي — التشخيص","b":"التهاب الشغاف: حمى + نفخة جديدة + ظواهر صمية؛ معيار ديوك؛ العلاج: مضادات وريدية مطولة ± جراحة."},{"f":"التهاب الشغاف — متى الجراحة؟","b":"استطبابات جراحة التهاب الشغاف: قصور قلب، خراج حول صمامي، صمة متكررة، جرثوم مقاوم."},{"f":"إصلاح الصمام التاجي مقابل استبداله","b":"إصلاح التاجي أفضل من الاستبدال عند الإمكان (يحفظ البطين)؛ حلقة التقويم (annuloplasty) أساسية."},{"f":"تضيق الصمام ثلاثي الشرف — العلامة","b":"تضيق مثلث الشرف: غالبًا رثوي مرافق للتاجي؛ موجة a عملاقة بالوريد الوداجي."}]},{"t":"تشوهات القلب الخلقية والوالدية","cards":[{"f":"الثقبة بين البطينين (VSD) — الأشيع","b":"الأشيع بالمطلق؛ الثقبة الغشائية؛ النفخة: انقباضية شاملة بالحافة اليسرى؛ الصغير يُغلق تلقائيًا."},{"f":"الثقبة بين الأذينين (ASD) — العلامة السمعية","b":"ثقب بين الأذينين (ostium secundum)؛ انشطار ثابت للصوت الثاني؛ الإغلاق: قثطاري (جهاز) أو جراحي."},{"f":"رباعية فالو (TOF) — المكونات الأربعة","b":"الرباعية: VSD + ركوب الأبهر + تضيق مخرج البطين الأيمن + ضخامة بطين أيمن؛ قلب «حذائي»؛ نوب زراقية تُعالج بوضعية الركبة–الصدر."},{"f":"رباعية فالو — الإصلاح الجراحي","b":"الإصلاح الكامل: إغلاق VSD + توسيع مخرج البطين الأيمن؛ التلطيفية: تحويلة بلالوك–توسيغ."},{"f":"تبدل الشرايين الكبيرة (TGA) — الإصلاح","b":"تبدل الشرايين الكبيرة: الإصلاح: عملية التبديل الشرياني (Jatene) حديثي الولادة؛ البروستاغلاندين يُبقي القناة مفتوحة."},{"f":"تضيق برزخ الأبهر (Coarctation) — العلامات","b":"تضيق برزخ الأبهر: ضغط علوي مرتفع + نبض فخذي ضعيف/متأخر؛ تآكل الأضلاع (rib notching)؛ مرتبط بتيرنر."},{"f":"القناة الشريانية السالكة (PDA) — النفخة والعلاج","b":"القناة الشريانية: نفخة «آلية» مستمرة؛ العلاج: إندوميتاسين/إيبوبروفين؛ المستمرة: ربط جراحي/قثطاري."},{"f":"متلازمة أيزنمنغر (Eisenmenger) — التعريف","b":"انقلاب التحويلة (يمين–يسار) بارتفاع المقاومة الرئوية؛ زرقة + تعجر أصابع؛ الجراحة ممنوعة — العلاج: زرع قلب–رئة."},{"f":"شذوذ إبشتاين (Ebstein's anomaly)","b":"شذوذ إبشتاين: إزاحة الصمام ثلاثي الشرف للأسفل (أذينة بطينية)؛ مرتبط بليثيوم الأم."},{"f":"إصلاحات القلب وحيد البطين — المراحل","b":"الجذع الشرياني والبطين الوحيد: إصلاحات مرحلية (نوروود ← غلين ← فونتان)."},{"f":"الوقاية من التهاب الشغاف — الفئة","b":"الوقاية من التهاب الشغاف: قبل إجراءات الأسنان للمرضى عاليي الخطورة (صمام صناعي، شغاف سابق)."},{"f":"التشوهات القلبية والمتلازمات الصبغية","b":"متلازمة داون: ثقبة أذينية بطينية (AV canal)؛ تيرنر: تضيق برزخ؛ داون أيضًا: VSD."}]},{"t":"آفات التامور والسطام والدعم الدوراني","cards":[{"f":"السطام التاموري (Tamponade) — التشخيص","b":"ثالوث بيك: أصوات خافتة + أوردة وداجية منتفخة + هبوط ضغط؛ نبض متناقض >10 ملم زئبق؛ تخطيط: تناوب كهربائي."},{"f":"السطام التاموري — العلاج الإسعافي","b":"بزل التامور إسعافي (تحت الخنجري بتوجيه إيكو)؛ المستمر/المتكرر: نافذة تامورية جراحية."},{"f":"التهاب التامور الحاد — الصورة","b":"ألم يتحسن بالانحناء للأمام؛ احتكاك تاموري؛ تخطيط: ST مرتفع منتشر + PR منخفض؛ العلاج: مضادات التهاب + كولشيسين."},{"f":"التهاب التامور المضيق (Constrictive) — العلامة والعلاج","b":"علامة كوسماول (ارتفاع JVP بالشهيق) + تكلس تاموري؛ العلاج النهائي: استئصال التامور."},{"f":"الانصباب التاموري الكبير — العلامات","b":"انصباب تاموري كبير: قلب «قاروري» بالصورة؛ الإيكو: انخماص الأذين الأيمن."},{"f":"البالون داخل الأبهر (IABP) — المبدأ ومضاد الاستطباب","b":"بالون داخل الأبهر (IABP): يدعم بالانبساط (يخفض ما بعد الحمل ويحسن تروية إكليلية)؛ مضاد استطباب: قلس أبهر شديد."},{"f":"الدعم الدوراني الميكانيكي — الغرض","b":"الدعم الدوراني الميكانيكي (ECMO/أجهزة مساعدة): جسر للزرع أو للتعافي بعد الصدمة القلبية."},{"f":"الصدمة القلبية — التعريف والتدبير","b":"الصدمة القلبية: هبوط ضغط + علامات نقص تروية رغم امتلاء كافٍ؛ العلاج: مقبضات + دعم ميكانيكي باكر."},{"f":"الورم المخاطي القلبي (Myxoma)","b":"ورم مخاطي أذيني (myxoma): أشيع ورم قلبي أولي سليم؛ ثلاثية: صمة + حمى + نفخة متغيرة؛ العلاج: استئصال."},{"f":"النبض المتناقض (Pulsus paradoxus)","b":"النبض المتناقض: هبوط الضغط الانقباضي >10 ملم زئبق بالشهيق — علامة السطام."}]},{"t":"تسلخ الأبهر وجراحة الأبهر","cards":[{"f":"تسلخ الأبهر — تصنيف ستانفورد والتدبير","b":"ستانفورد A (الصاعد): جراحة إسعافية؛ B (النازل): طبي (خفض ضغط ونبض) إلا الاختلاطات."},{"f":"تسلخ الأبهر — الصورة السريرية","b":"ألم صدري «ممزق» مهاجر للظهر/البطن؛ فرق ضغط بين الذراعين؛ نفخة قلس أبهر جديد."},{"f":"تشخيص تسلخ الأبهر — الاستقصاء الذهبي","b":"الطبقي الوعائي (CT angiography): الذهبية للتشخيص؛ السديلة البطانية (intimal flap) العلامة."},{"f":"متلازمة مارفان والتسلخ الأبهري","b":"مارفان: طول قامة + عدسة منزاحة + تسلخ أبهر؛ العلاج الوقائي: حاصر بيتا + جراحة عند توسع الجذر."},{"f":"تصنيف دي بيكي (DeBakey) للتسلخ","b":"دي بيكي I: الصاعد والقوس والنازل؛ II: الصاعد فقط؛ III: النازل فقط."},{"f":"أم دم الأبهر البطني — عتبة التداخل","b":"أم دم الأبهر البطني: نابض بطني + ألم ظهر؛ العتبة الجراحية: >5.5 سم أو نمو سريع؛ الإصلاح: دعامة (EVAR) أو جراحة."},{"f":"تمزق أم دم الأبهر — الثلاثية","b":"تمزق أم الدم: ألم + هبوط ضغط + كتلة نابضة — إسعاف جراحي فوري."},{"f":"التهاب الأبهر — الأسباب","b":"التهاب الأبهر (aortitis): تكاياسو/خلية عملاقة؛ قد يسبب تضيق فروع أو أم دم."}]},{"t":"الانعاش القلبي الريوي","cards":[{"f":"الإنعاش القلبي الرئوي الأساسي — المعدل والعمق","b":"100–120/دقيقة، عمق 5–6 سم، 30:2 (ضغطة:نفخة)؛ تقليل الانقطاعات."},{"f":"الإيقاعات القابلة للصدمة الكهربائية","b":"الإيقاعات القابلة للصدمة: الرجفان البطيني وتسرع البطين بلا نبض؛ الصدمة: 200 جول ثنائي الطور."},{"f":"الإيقاعات غير القابلة للصدمة","b":"الإيقاعات غير القابلة: الانقباض اللانبضي (PEA) والخط المستقيم (asystole) — العلاج: إنعاش + أدرينالين."},{"f":"الأدرينالين في الإنعاش — الجرعة","b":"أدرينالين 1 ملغ وريدي كل 3–5 دقائق أثناء الإنعاش."},{"f":"الأسباب القابلة للعكس أثناء الإنعاش (4H و4T)","b":"الأسباب القابلة للعكس 4H و4T: نقص حجم/أكسجة/حرارة/شوارد + سطام/ريح موترة/خثار/سموم."},{"f":"العناية بعد عودة الدوران التلقائي","b":"بعد عودة الدوران: تبريد مستهدف (33–36°)؛ تقييم إكليلي عاجل عند الاشتباه باحتشاء."},{"f":"الإنعاش القلبي للحامل","b":"الإنعاش لدى الحامل: إزاحة الرحم يدويًا لليسار + قيصرية إسعافية عند عدم الاستجابة بـ4 دقائق."},{"f":"متى يُنهى الإنعاش؟","b":"إنهاء الإنعاش: بعد 20–30 دقيقة بلا إيقاع قابل ولا سبب قابل للعكس — قرار طبي."}]}]},{"s":"النسائية","topics":[{"t":"انزياحات الرحم والأذيات والهبوطات الرحمية المهبلية","cards":[{"f":"عرّف هبوط الأعضاء الحوضية (Pelvic organ prolapse) واذكر أنماطه.","b":"انفتاق الأعضاء الحوضية إلى جدران المهبل أو ما بعدها. الأنماط: هبوط الحجرة الأمامية — المثانة (قيلة مثانية Cystocele — الأشيع)؛ هبوط الحجرة الخلفية — المستقيم (قيلة مستقيمية Rectocele) أو الأمعاء الدقيقة (قيلة معوية Enterocele)؛ هبوط الحجرة القمية — الرحم أو عنق الرحم أو قبة المهبل؛ تدلّي الرحم (Uterine procidentia) = انفتاق يشمل الحجرات الثلاث معًا."},{"f":"ما عوامل الخطر والأعراض الكلاسيكية لهبوط الأعضاء الحوضية؟","b":"عوامل الخطر: تعدد الولادات، تقدم العمر، السمنة. الأعراض الكلاسيكية: ضغط حوضي، إحساس بالانتفاخ أو بروز نسيج من المهبل، تكرار التبول، إمساك، خلل الوظيفة الجنسية."},{"f":"ما علاقة الرباط الرئيسي (Cardinal ligament) بأذيات استئصال الرحم؟","b":"الرباط الرئيسي (Cardinal ligament) تكاثف عند قاعدة الرباط العريض (Broad ligament) يمتد من عنق الرحم إلى الجدار الحوضي الجانبي؛ ربط الأوعية الرحمية أثناء استئصال الرحم يُخاطر بإيذاء الحالب المجاور — أشيع أذية جراحية في استئصال الرحم."}]},{"t":"الحالات ما قبل السرطانية والسرطانية في السبيل التناسلي الأنثوي","cards":[{"f":"ما ترتيب وقوع الأورام النسائية (بطانة الرحم، المبيض، عنق الرحم)؟","b":"في الولايات المتحدة ترتيب الوقوع: بطانة الرحم > المبيض > عنق الرحم. أما عالميًا فسرطان عنق الرحم هو الأشيع بسبب نقص المسح أو لقاح HPV."},{"f":"رتّب الأورام النسائية حسب الإنذار ومتوسط عمر التشخيص.","b":"عنق الرحم أفضل إنذار (يُشخَّص بعمر ~45 سنة) ← بطانة الرحم (~55 سنة) ← المبيض أسوأ إنذار (~65 سنة)."},{"f":"ما صفات سرطان الفرج (Vulvar carcinoma) ونمطيه؟","b":"سرطان من البطانة الظهارية الحرشفية للفرج، يُرى عادة بعد سن اليأس، يتظاهر بطلاوة (Leukoplakia) والخزعة تميزه عن الأسباب الأخرى. النمط المرتبط بـ HPV (أنماط 16 و18 عالية الخطورة) مقابل النمط غير المرتبط بـ HPV (عادة من حزاز متصلب طويل الأمد)."},{"f":"فرّق بين أنماط أورام المهبل الخبيثة وعلاقتها بـ DES.","b":"سرطان الخلايا الحرشفية المهبلي غالبًا ثانوي لسرطان عنق الرحم الحرشفي؛ السرطان المهبلي الأولي نادر. السرطان الغدي ذو الخلايا الصافية (Clear cell adenocarcinoma) ينشأ من التغدد المهبلي (vaginal adenosis — استمرار الظهارة الغدية العمودية) لدى الإناث المعرضات لثنائي إيثيل ستيلبسترول (DES) داخل الرحم."},{"f":"ما الساركوما العنقودية (Sarcoma botryoides)؟","b":"نمط من الساركوما العضلية المخططة الجنينية (embryonal rhabdomyosarcoma)؛ تصيب الإناث دون 4 سنوات؛ كتلة سليلة شفافة عنقودية تبرز من المهبل؛ خلايا مغزلية الشكل؛ desmin موجب."},{"f":"ما الآلية الجزيئية والعلامة النسيجية لخلل تنسج عنق الرحم المرتبط بـ HPV؟","b":"نمو مضطرب للظهارة الحرشفية يبدأ عند الطبقة القاعدية لمنطقة التحويل (الموصل الحرشفي العمودي squamocolumnar junction) ويمتد للخارج؛ مترافق مع HPV-16 وHPV-18: ناتج الجين E6 يثبط p53 وناتج الجين E7 يثبط Rb. الخلايا المتقرحة (Koilocytes) — ذات نواة متجعدة «زبيبية» وهالة حول نووية — ممرضة نوعية لعدوى HPV."},{"f":"ما اختلاط الغزو الجانبي لسرطان عنق الرحم الغازي؟","b":"غالبًا سرطان الخلايا الحرشفية؛ يُشخَّص بتنظير المهبل (colposcopy) والخزعة. الغزو الجانبي قد يسد الحالبين ← استسقاء الكلية ← فشل كلوي."},{"f":"ما فرط تنسج بطانة الرحم (Endometrial hyperplasia): سببه وعلامته الإنذارية؟","b":"تكاثر شاذ للغدد البطانية، غالبًا ناتج عن زيادة الإستروجين غير المعارَض بالبروجسترون. المترافقات: السمنة، PCOS، اللاإباضة المزمنة، عدم الولادة، العلاج الهرموني المعيض، تاموكسيفين. يتظاهر بنزف رحمي شاذ؛ اللانمطية النووية ⇑ خطر سرطان بطانة الرحم."},{"f":"ما صفات السرطان شبه البطاني (Endometrioid carcinoma)؟","b":"أشيع نمط فرعي لسرطان بطانة الرحم (أشيع سرطان نسائي في البلدان الغنية بالموارد)؛ ينشأ عادة لدى إناث بعد سن اليأس ويتظاهر بنزف رحمي شاذ؛ مترافق مع التعرض طويل الأمد للإستروجين غير المعارَض؛ نسيجيًا: غدد بطانية متلاصقة دون سدى متداخلة."},{"f":"فرّق بين الورم المصلي السليم والخبيث في المبيض.","b":"الورم الغدي الكيسي المصلي (Serous cystadenoma): سليم، أشيع ورم مبيضي، مبطن بظهارة شبيهة بظهارة قناة فالوب. السرطان المصلي (Serous carcinoma): أشيع ورم مبيضي خبيث، يتميز بالأجسام الرملية (psammoma bodies)."},{"f":"ما صفات الأورام المخاطية المبيضية واختلاط السرطان المخاطي؟","b":"الورم الغدي الكيسي المخاطي: سليم، متعدد الحجرات، كبير، مبطن بظهارة مفرزة للمخاط. السرطان المخاطي: خبيث نادر، قد يكون نقيليًا من الزائدة أو أورام هضمية أخرى، وقد يؤدي إلى الورم المخاطي الكاذب الصفاقي (pseudomyxoma peritonei — التكعك الثربي omental caking)."},{"f":"ما صفات المسخية الكيسية الناضجة (Mature cystic teratoma)؟","b":"سليمة، أشيع ورم مبيضي لدى الشابات، تُسمى أيضًا الكيسة الجلدانية (dermoid cyst)؛ كتلة كيسية بعناصر من الطبقات الجرثومية الثلاث (أسنان، شعر، زهم). الشكل أحادي الأديم ذو النسيج الدرقي (struma ovarii) قد يتظاهر بفرط الدرقية. التحول الخبيث نادر (غالبًا إلى سرطان الخلايا الحرشفية)."},{"f":"ما الورم المنمش (Dysgerminoma) وواسماته؟","b":"خبيث، الأشيع لدى المراهقات، مكافئ الورم المنوي الذكري لكنه أنذر (أفضل إنذارًا)؛ صفائح من خلايا منتظمة «بيض مقلي» (fried egg cells). الواسمات الورمية: ⇑ LDH و⇑ hCG."},{"f":"ما ورم كيس المح (Yolk sac tumor) وعلامته المميزة؟","b":"خبيث عدواني، يُسمى أيضًا ورم الجيب الأديمي الباطن (endodermal sinus tumor)؛ كتلة صفراء هشة نازفة لدى الأطفال والشابات؛ نسيجيًا أجسام شيلر-دوفال (Schiller-Duval bodies) تشبه الكبيبات. الواسم الورمي: ⇑ AFP."},{"f":"ما ورم الخلايا الحبيبية (Granulosa cell tumor) وعلاماته؟","b":"أشيع ورم خبيث من أورام الحبل الجنسي السدوية؛ يحدث غالبًا في الخمسينات؛ ينتج إستروجينًا و/أو بروجسترونًا ← يتظاهر بنزف بعد سن اليأس وفرط تنسج بطانة الرحم وبلوغ مبكر (لدى ما قبل المراهقات)؛ نسيجيًا أجسام كال-إكسنر (Call-Exner bodies) — خلايا حبيبية حول تجمعات سائل إيزينوفيلي تشبه الجريبات الأولية. الواسم: ⇑ إنهيبين."},{"f":"ما الورم الليفي المبيضي (Fibroma) وثالوث ميغز؟","b":"سليم، حزم من الخلايا الليفية مغزلية الشكل. ثالوث متلازمة ميغز (Meigs syndrome): ورم ليفي مبيضي + استسقاء + انصباب جنبة."},{"f":"ما الورم الغلافي (Thecoma) وعرضه المميز؟","b":"غالبًا سليم؛ قد ينتج إستروجينًا ← يتظاهر عادة بنزف رحمي شاذ لدى أنثى بعد سن اليأس."},{"f":"ما ورم خلايا سيرتولي-لايديغ (Sertoli-Leydig cell tumor)؟","b":"سليم، كتلة رمادية إلى صفراء بنية تشبه نسيجية الخصية (نبيبات مبطنة بخلايا سيرتولي محاطة بخلايا لايديغ)؛ قد ينتج أندروجينات ← تذكير (شعرانية، صلع أندروجيني، تضخم البظر)."},{"f":"ما عوامل خطر سرطان المبيض وما دور CA-125؟","b":"⇑ الخطر: تقدم العمر، ⇑ عدد الإباضات مدى الحياة (الحيض المبكر، سن اليأس المتأخر، عدم الولادة Nulliparity)، الانتباذ البطاني الرحمي، الاستعداد الوراثي (طفرات BRCA1/BRCA2، متلازمة لينش). ⇓ الخطر: الحمل السابق، الرضاعة الطبيعية، حبوب منع الحمل الفموية، ربط البوقين. CA-125 (مع الأمواج فوق الصوتية والحالة اليائسية) لمراقبة الاستجابة/النكس — ليس للمسح."},{"f":"كيف يتظاهر خلل تنسج عنق الرحم وسرطان عنق الرحم المبكر؟","b":"غالبًا لا عرضي — يُكشَف بمسحة بابانيكولاو (Pap test)؛ أو يتظاهر بنزف مهبلي شاذ (غالبًا بعد الجماع postcoital). قد يتقدم ببطء إلى سرطان غازٍ إذا تُرك دون علاج."}]},{"t":"اضطرابات الدورة الطمثية","cards":[{"f":"ما تصنيف PALM-COEIN لأسباب النزف الرحمي الشاذ؟","b":"بنيوية (PALM): سليلة (Polyp)، عضال غدي (Adenomyosis)، ورم عضلي أملس (Leiomyoma)، خباثة/فرط تنسج (Malignancy/hyperplasia). غير بنيوية (COEIN): اعتلال تخثر (Coagulopathy)، إباضي (Ovulatory)، بطاني (Endometrial)، علاجي المنشأ (Iatrogenic)، غير مصنف بعد (Not yet classified)."},{"f":"ما غشاء البكارة غير المثقوب (Imperforate hymen) وعرضه المتأخر؟","b":"تقهقر غير مكتمل للجزء المركزي من غشاء البكارة؛ تراكم المخاط المهبلي عند الولادة ← انتفاخ ذاتي الزوال؛ إذا تُرك دون علاج: انقطاع طمث أولي + ألم بطني دوري + احتباس دم الحيض في المهبل (hematocolpos) ← غشاء بكارة منتفخ مزرقّ."},{"f":"ما الصورة الهرمونية والسببية لمتلازمة تيرنر في انقطاع الطمث الأولي؟","b":"أنثى 45,XO؛ خلل تكون المبيض (مبيض شريطي)؛ أشيع سبب لانقطاع الطمث الأولي؛ لا يوجد جسم بار؛ ⇑ FSH و⇑ LH و⇓ إستروجين («سن يأس قبل الحيض»)."},{"f":"ما متلازمة كالمان (Kallmann syndrome)؟","b":"قصور المناسل ناقص الموجهات (↓ GnRH) + فقدان الشم (Anosmia) بسبب فشل هجرة العصبونات."},{"f":"ما انقطاع الطمث الوطائي الوظيفي وثالوثه الرياضي؟","b":"يُسمى أيضًا انقطاع الطمث المحرض بالتمارين؛ التقييد الشديد للسعرات و/أو ⇑ صرف الطاقة و/أو التوتر ← خلل إفراز GnRH النبضي ← ⇓ LH وFSH والإستروجين؛ ⇓ اللبتين (بسبب ⇓ الشحم) و⇑ الكورتيزول. مترافق مع «الثالوث الرياضي الأنثوي» (⇓ توافر السعرات/تمارين مفرطة، ⇓ الكثافة المعدنية للعظم، خلل الدورة الشهرية)."},{"f":"ما متلازمة المبيض متعدد الكيسات (PCOS): آليتها وعلاجها؟","b":"سبب مجهول + خلل تنظيم الستيرويدات المبيضية؛ ⇑ نسبة LH:FSH، ⇑ الأندروجينات (تستوستيرون) من خلايا الغلاف (theca)، ⇓ معدل نضج الجريبات ← جريبات غير منفجرة (كيسات)؛ ⇓ الخصوبة. المترافقات: السمنة، مقاومة الأنسولين، الشواك الأسود (acanthosis nigricans)؛ ⇑ خطر سرطان بطانة الرحم من الإستروجين غير المعارَض. العلاج: إنقاص الوزن، حبوب منع الحمل الفموية (للوقاية من فرط التنسج)، تحريض الإباضة، سبيرونولاكتون/فيناسترايد/فلوتاميد للشعرانية."},{"f":"ما القصور المبيضي الأولي (Primary ovarian insufficiency)؟","b":"يُسمى أيضًا الفشل المبيضي المبكر؛ رتق مبكر للجريبات المبيضية قبل عمر 40 سنة؛ تتظاهر بعلامات سن اليأس بعد البلوغ؛ ⇑ FSH و⇑ LH و⇓ إستروجين؛ يلزم مسح النمط النووي (تيرنر، الطفرة الممهدة لمتلازمة X الهش، المناعة الذاتية)."},{"f":"ما أثر فرط البرولاكتين على الوظيفة التناسلية؟","b":"البرولاكتين يحفز الإرضاع ويحافظ عليه، لكنه ⇓ الوظيفة التناسلية (يثبط المحور التناسلي)."},{"f":"ما دلالة اختبار البروجستين (Progestin challenge) الإيجابي؟","b":"وجود نزف السحب يستبعد العيوب التشريحية (مثل متلازمة أشرمان) واللاإباضة المزمنة دون إستروجين."},{"f":"ما العلاقة بين الإرضاع وتأخر الإباضة بعد الولادة؟","b":"بعد الولادة: الانخفاض السريع في الإستروجين والبروجسترون يحرر البرولاكتين من التثبيط ← بدء الإرضاع؛ الرضاعة تحفز ⇑ الأوكسيتوسين والبرولاكتين للحفاظ على إنتاج الحليب. والبرولاكتين ← ⇓ GnRH ← تأخر الإباضة التالية للولادة (منع حمل طبيعي)."},{"f":"ما آلية ذروة LH (LH surge) منتصف الدورة؟","b":"الإستروجين العالي في منتصف الدورة يحفز تحرير LH عابرًا (تغذية راجعة إيجابية) ← ذروة LH ← تمزق الجريب وتحرير الخلية البويضية الثانوية."},{"f":"فرّق بين الطور الجريبي والطور الأصفري في ثبات المدة.","b":"الطور الجريبي (Follicular): تطور الجريبات بتحفيز FSH، وطوله متفاوت. الطور الأصفري (Luteal): تشكل الجسم الأصفر من بقايا الجريب بتحفيز LH، ثابت 14 يومًا."},{"f":"فرّق بين الطور التكاثري والإفرازي لبطانة الرحم.","b":"الطور التكاثري (Proliferative): بتحفيز الإستروجين؛ غدد بطانية مستقيمة ضيقة. الطور الإفرازي (Secretory): بتحفيز البروجسترون؛ غدد بطانية ملتفة متوسعة — تهيئة للانغراس."},{"f":"ما وظائف البروجسترون (Progesterone)؟","b":"أثناء الطور الأصفري: تحفيز المفرزات الغدية وتطور الشرايين الحلزونية؛ مخاط عنقي سميك (يمنع دخول النطاف)؛ منع فرط تنسج بطانة الرحم؛ ⇑ حرارة الجسم؛ ⇓ التعبير عن مستقبلات الإستروجين و⇓ إفراز LH/FSH. أثناء الحمل: الحفاظ على بطانة الرحم، ⇓ استثارية عضلة الرحم."},{"f":"ما عسر الطمث الأولي (Primary dysmenorrhea): آليته وعلاجه؟","b":"حيض مؤلم ناتج عن تقلصات الرحم ← ⇓ فقدان الدم ← ألم إقفاري؛ متوسط بالبروستاغلاندينات. العلاج: مضادات الالتهاب غير الستيرويدية (NSAIDs)، أسيتامينوفين، موانع الحمل الهرمونية."},{"f":"ما متلازمة عدم الحساسية للأندروجين (Androgen insensitivity syndrome)؟","b":"خلل في مستقبلات الأندروجين ← ذكر وراثي (46,XY DSD) بمظهر أنثوي؛ شعر إبط وعانة شحيح، مهبل بدائي؛ الرحم وقناتا فالوب غائبان بسبب استمرار الهرمون المضاد لمولر من الخصيتين؛ خصيتان وظيفيتان طبيعيتان (غالبًا في الشفرين الكبيرين — تُستأصلان جراحيًا للوقاية من الخباثة)؛ ⇑ تستوستيرون وإستروجين وLH."},{"f":"ما آلية الكلوميفين (Clomiphene) وآثاره الضائرة؟","b":"مضاد لمستقبلات الإستروجين في الوطاء؛ يمنع التثبيط الراجع الطبيعي ← ⇑ تحرير FSH وLH من النخامية ← تحريض الإباضة؛ يُستخدم لعلاج العقم الناتج عن اللاإباضة (مثل PCOS). الآثار الضائرة: هبات ساخنة، تضخم المبيض، حمول متعددة متزامنة، اضطرابات بصرية."},{"f":"ما استخدامات ليتروزول (Letrozole)؟","b":"من مثبطات الأروماتاز (تثبط التحويل المحيطي للأندروجينات إلى إستروجين)؛ يُستخدم لسرطان الثدي ER موجب بعد سن اليأس، ويمكن استخدامه لعلاج العقم الناتج عن اللاإباضة (مثل PCOS)."},{"f":"متى تكون اللاإباضة (Anovulation) فيزيولوجية طبيعية؟","b":"اللاإباضة طبيعية أثناء الحمل والرضاعة وقرب الحيض الأول (menarche) وقرب سن اليأس."},{"f":"ما الدليل المخبري على حدوث الإباضة؟","b":"⇑ البروجسترون دليل على حدوث الإباضة."}]},{"t":"سن الإياس","cards":[{"f":"ما تعريف سن اليأس (Menopause) ومتوسط عمر بدئه؟","b":"يُشخَّص بانقطاع الطمث لمدة 12 شهرًا؛ ⇓ إنتاج الإستروجين بسبب التراجع المرتبط بالعمر في عدد الجريبات المبيضية؛ متوسط عمر البدء 51 سنة (أبكر لدى المدخنات)؛ تسبقه عادة 4-5 سنوات من دورات شهرية شاذة."},{"f":"ما التغيرات الهرمونية المميزة لسن اليأس؟","b":"⇓ الإستروجين، ⇑⇑ FSH (نوعي لسن اليأس — فقدان التثبيط الراجع السلبي)، ⇑ LH، ⇑ GnRH (لا ذروة). مصدر الإستروجين (إسترون) بعد سن اليأس يصبح التحويل المحيطي للأندروجينات؛ ⇑ الأندروجينات ← الشعرانية (hirsutism)."},{"f":"ما أعراض وعقابيل سن اليأس (ذاكرة HAVOCS)؟","b":"ذاكرة HAVOCS: الهبات الساخنة (Hot flashes — الأشيع)، ضمور المهبل (Atrophy of the Vagina)، هشاشة العظام (Osteoporosis — ⇑ نشاط ناقضات العظم)، داء الشريان التاجي (Coronary artery disease)، اضطرابات النوم (Sleep disturbances)."},{"f":"ما مخاطر العلاج الهرموني المعيض (HRT)؟","b":"يُستخدم العلاج الهرموني المعيض (HRT) لعلاج أعراض سن اليأس، لكنه قد يترافق مع ⇑ خطر سرطان الثدي وبطانة الرحم والأمراض القلبية الوعائية والسكتة والانصمام الخثاري."},{"f":"ما دلالة سن اليأس قبل عمر 40 سنة؟","b":"سن اليأس قبل عمر 40 سنة يوحي بقصور المبيض الأولي (الفشل المبيضي المبكر)؛ وقد يحدث لدى الإناث اللواتي تلقين علاجًا كيميائيًا و/أو شعاعيًا."},{"f":"ما ميزة رالوكسيفين (Raloxifene) بعد سن اليأس؟","b":"مضاد في الثدي والرحم، ناهض في العظم؛ يُستخدم أساسًا لعلاج هشاشة العظام بعد سن اليأس — دون زيادة خطر سرطان بطانة الرحم (مقابل تاموكسيفين). آثاره: هبات ساخنة، ⇑ خطر الأحداث الانصمامية الخثارية."},{"f":"كيف يتأثر الورم العضلي الأملس بالحمل وسن اليأس؟","b":"الورم العضلي الأملس (Leiomyoma) حساس للإستروجين: ⇑ حجمه مع الحمل و⇓ مع سن اليأس."},{"f":"ما صفات سرطان بطانة الرحم الوبائية والسريرية؟","b":"أشيع سرطان نسائي في البلدان الغنية بالموارد؛ ينشأ عادة لدى إناث بعد سن اليأس؛ العرض الكلاسيكي: نزف رحمي شاذ."}]},{"t":"تشوهات السبيل التناسلي الأنثوي وكيساته وأورامه الحميدة","cards":[{"f":"ما الرحم المحجوب (Septate uterus) وعلاجه؟","b":"ارتسام غير مكتمل للحاجز؛ شذوذ شائع؛ يُعالَج برأب الحاجز (septoplasty)."},{"f":"ما الرحم ثنائي القرن (Bicornuate uterus)؟","b":"اندماج غير مكتمل لقناتي مولر (Müllerian ducts)."},{"f":"ما الرحم المزدوج (Uterus didelphys)؟","b":"فشل كامل في الاندماج ← رحم وعنق ومهبل مزدوجون."},{"f":"ما متلازمة عدم تكون مولر (Müllerian agenesis)؟","b":"متلازمة ماير-روكيتانسكي-كوستر-هاوزر (Mayer-Rokitansky-Küster-Hauser): انقطاع طمث أولي مع غياب الرحم وجيب مهبلي أعمى وأعضاء تناسلية خارجية أنثوية طبيعية وصفات جنسية ثانوية طبيعية (مبيضان وظيفيان)؛ مترافقة مع شذوذات السبيل البولي (مثل عدم تكون الكلية)."},{"f":"ما أثر شذوذات الرحم (قناة مولر) على الحمل؟","b":"⇓ الخصوبة و⇑ خطر الحمل المعقد: الإجهاض التلقائي، الخداج، تقييد نمو الجنين، المجيء الشاذ."},{"f":"ما الكيسة الجريبية (Follicular cyst)؟","b":"كيسة وظيفية (فيزيولوجية)؛ أشيع كتلة مبيضية لدى الشابات؛ ناتجة عن فشل الجريب الناضج في التمزق والإباضة؛ قد تنتج إستروجينًا زائدًا؛ غالبًا تزول تلقائيًا."},{"f":"ما كيسة الجسم الأصفر (Corpus luteal cyst)؟","b":"كيسة وظيفية؛ ناتجة عن فشل الجسم الأصفر في الالتحام بعد الإباضة؛ قد تنتج بروجسترونًا زائدًا؛ غالبًا تزول تلقائيًا."},{"f":"ما كيسات الغلاف الأصفرية (Theca lutein cysts) وسياقها؟","b":"تُسمى أيضًا فرط التفاعل الأصفري (hyperreactio luteinalis)؛ ناتجة عن فرط تحفيز hCG؛ غالبًا ثنائية/متعددة؛ مترافقة مع الداء الأرومي الغاذي الحملي (الرحى العدارية، السرطان المشيمي)."},{"f":"ما اختلاطات كيسات المبيض؟","b":"غالبًا لا عرضية، لكنها قد تتمزق أو تنزف أو تؤدي إلى انفتال ملحقي."},{"f":"ما الانفتال الملحقي (Adnexal torsion): آليته وعرضه؟","b":"التواء المبيض وقناة فالوب حول الرباط القمعي الحوضي (infundibulopelvic) والرباط الرحمي المبيضي ← انضغاط الأوعية المبيضية ← انسداد التصريف اللمفاوي والوريدي؛ استمرار التروية الشريانية ← وذمة مبيضية ← انسداد كامل للتدفق الشرياني ← نخر ونزف موضعي. مترافق مع كتل/كيسات مبيضية؛ يتظاهر بألم حوضي حاد وكتلة ملحقية وغثيان/قيء؛ طارئ جراحي."},{"f":"ما صفات الورم العضلي الأملس (Leiomyoma)؟","b":"ورم سليم في عضلة الرحم (fibroid)؛ أشيع ورم نسائي؛ ينشأ في سن الإنجاب؛ ⇑ الوقوع لدى السكان السود؛ غالبًا متعدد؛ أنماط حسب الموقع: تحت المخاطية أو داخل الجدار أو تحت المصلية؛ غالبًا لا عرضي لكن قد: نزف رحمي شاذ، ضغط/ألم حوضي، خلل وظيفي تناسلي؛ حساس للإستروجين. نسيجيًا: نمط دوامي من حزم العضلات الملساء بحدود واضحة التحديد؛ رحم متضخم بمحيط عقدي بالفحص."},{"f":"ما العضال الغدي (Adenomyosis)؟","b":"وجود نسيج بطاني رحمي (غدد وسدى) في عضلة الرحم؛ قد يكون بسبب انغماد الطبقة القاعدية لبطانة الرحم أو تحول الخلايا السلفية المتبقية؛ يتظاهر بنزف رحمي شاذ وعسر طمث؛ رحم متضخم منتشر («كروي») رخو («إسفنجي») بالفحص."},{"f":"ما ورم برينر (Brenner tumor)؟","b":"غالبًا سليم؛ أعشاش من ظهارة شبيهة بالظهارة البولية (شبيهة بالمثانة) مع نوى «حبة البن» (coffee bean nuclei)."},{"f":"ما الالتصاقات داخل الرحم (Intrauterine adhesions)؟","b":"أشرطة/نسيج ليفي داخل جوف بطانة الرحم؛ ناتجة عن ضرر الطبقة القاعدية لبطانة الرحم غالبًا بعد التوسيع والتجريف؛ تتظاهر بنزف رحمي شاذ (⇓ الحيض) وعقم وفقدان حمل متكرر وعسر طمث؛ تُسمى أيضًا متلازمة أشرمان (Asherman syndrome) عندما تكون عرضية."},{"f":"ما البقية الأنثوية لقناة ولف (Wolffian duct)؟","b":"البقية الأنثوية للقناة الكلوية المتوسطة (ولف) — قناة غارتنر (Gartner duct)."},{"f":"ما البقية الذكرية لقناة مولر؟","b":"البقية الذكرية لقناة مولر — زائدة الخصية (appendix testis)."},{"f":"ما كيسة بارثولين (Bartholin cyst)؟","b":"انسداد قناة غدة بارثولين مسببًا تراكم سائل الغدة؛ قد تؤدي إلى خراج ثانوي للانسداد والالتهاب؛ غالبًا لدى الإناث في سن الإنجاب."},{"f":"ما مشتقات قناة مولر في المهبل؟","b":"القناة جانب الكلوية المتوسطة (مولر) تتطور إلى: قناتي فالوب، الرحم، المهبل القريب — أما المهبل البعيد فمن الجيب البولي التناسلي."},{"f":"ما الموجودات الطبيعية في تصوير الرحم بالصبغة (HSG)؟","b":"يُظهر تصوير الرحم وقناتي فالوب بالصباغ (hysterosalpingogram) للرحم الطبيعي: جوفًا رحميًا طبيعيًا وانسكابًا داخل الصفاق للصباغ (دليل على نفوذية قناتي فالوب)."}]},{"t":"العقم","cards":[{"f":"ما أسباب العقم اللاإباضي (Anovulatory infertility)؟","b":"عقم ثانوي لغياب الإباضة. الأسباب: متلازمة المبيض متعدد الكيسات (الأشيع)، القصور المبيضي الأولي، قصور المناسل ناقص الموجهات، فرط البرولاكتين. (اللاإباضة طبيعية أثناء الحمل والرضاعة وقرب الحيض الأول وسن اليأس)."},{"f":"فرّق بين الكلوميفين والليتروزول في تحريض الإباضة.","b":"كلوميفين: مضاد مستقبلات الإستروجين في الوطاء ← ⇑ FSH/LH ← إباضة؛ آثاره: هبات ساخنة، تضخم مبيض، حمول متعددة، اضطرابات بصرية. ليتروزول: مثبط أروماتاز؛ بديل لتحريض الإباضة في PCOS."},{"f":"ما آلية نظائر GnRH واستخداماتها؟","b":"نظائر GnRH (ليوبروليد، غوسيريلين...): نبضيًا تعمل كناهضات، ومستمرًا تعمل أولًا عابرًا كناهضات (توهج ورمي tumor flare) ثم كمضادات (تنظيم سفلي للمستقبلات ← ⇓ FSH/LH ← ⇓ إستروجين/تستوستيرون). الاستخدامات: الأورام الليفية الرحمية، الانتباذ البطاني الرحمي، البلوغ المبكر، سرطان البروستات، العقم (نبضيًا للحمل، مستمرًا للسرطان)."},{"f":"ما دانازول (Danazol): استخدامه وآثاره؟","b":"أندروجين اصطناعي يعمل كناهض جزئي عند مستقبلات الأندروجين؛ الاستخدام: الانتباذ البطاني الرحمي، الوذمة الوعائية الوراثية. الآثار الضائرة: زيادة الوزن، وذمة، حب شباب، شعرانية، تذكير، ⇓ HDL، سمية كبدية."},{"f":"هل الحمل ممكن في متلازمة تيرنر؟","b":"الحمل ممكن في بعض حالات تيرنر عبر الإخصاب في المختبر (IVF) مع إستروجين وبروجسترون خارجيين."},{"f":"ما متلازمة كلاينفلتر (Klinefelter) وعلاقتها بالعقم؟","b":"ذكر 47,XXY؛ خصيتان صغيرتان صلبتان؛ عقم (انعدام النطاف azoospermia)؛ قامة طويلة بنسب خصيانية (تأخر إغلاق المشاش)؛ توزع شعر أنثوي؛ وجود جسم بار معطل؛ سبب شائع لقصور المناسل يُرى في تقييم العقم؛ ⇑ خطر سرطان الثدي."}]},{"t":"بطانة الرحم الهاجرة (الاندومتريوز) والداء العضلي الغدي (الأدينوميوز)","cards":[{"f":"ما الانتباذ البطاني الرحمي (Endometriosis) ونظريتا حدوثه؟","b":"وجود نسيج بطاني رحمي خارج الرحم؛ قد يكون بسبب انغراس منتبذ (عبر الحيض الراجع أو اللمفاويات أو الأوعية الدموية) أو تحول الخلايا السلفية المتبقية."},{"f":"ما الأعراض الكلاسيكية للانتباذ البطاني الرحمي؟","b":"عسر طمث، عسر جماع، عقم، نزف رحمي شاذ."},{"f":"ما المواقع والآفات المميزة للانتباذ البطاني الرحمي؟","b":"يشمل عادة مواقع حوضية: الصفاق السطحي (آفات «حرق البارود» الصفراء-البنية) والمبيضين (كيسات مملوءة بالدم «شوكولاتية» تُسمى الورم البطاني الرحمي endometrioma)."},{"f":"ما موجودات الفحص في الانتباذ البطاني الرحمي؟","b":"الفحص الفيزيائي غالبًا طبيعي؛ لكن الموجودات قد تشمل: رحمًا غير متحرك، كتلة ملحقية، إيلام رحمي-عجزي و/أو عقدية — لكنها غير تشخيصية."},{"f":"فرّق العضال الغدي (Adenomyosis) عن الانتباذ البطاني.","b":"وجود نسيج بطاني (غدد وسدى) داخل عضلة الرحم بسبب انغماد الطبقة القاعدية أو تحول الخلايا السلفية؛ نزف رحمي شاذ + عسر طمث؛ رحم متضخم منتشر «كروي» رخو «إسفنجي»."},{"f":"أين يقع العضال الغدي في تصنيف PALM-COEIN؟","b":"في تصنيف PALM-COEIN لأسباب النزف الرحمي الشاذ: الحرف A = Adenomyosis (العضال الغدي) — من الأسباب البنيوية."},{"f":"ما الأدوية المستخدمة للانتباذ البطاني الرحمي؟","b":"نظائر GnRH (ليوبروليد) ودانازول من الاستخدامات السريرية المعتمدة للانتباذ البطاني الرحمي."},{"f":"ما علاقة الانتباذ البطاني الرحمي بسرطان المبيض؟","b":"الانتباذ البطاني الرحمي من عوامل ⇑ خطر سرطان المبيض."}]},{"t":"موانع الحمل","cards":[{"f":"ما آلية موانع الحمل الهرمونية (Hormonal contraception)؟","b":"إستروجين مركب مع بروجستينات (أو بروجستين فقط): تمنع الإباضة عبر ⇓ GnRH ← ⇓ LH/FSH (لا ذروة LH)؛ البروجستينات أيضًا تُثخن المخاط العنقي (⇓ دخول النطاف) وتُرقق بطانة الرحم (أقل ملاءمة للانغراس)."},{"f":"ما آلية اللولب النحاسي ومحاذيره؟","b":"اللولب النحاسي (خالٍ من الهرمون) يسبب التهابًا موضعيًا سامًا للنطاف والبويضات مانعًا الإخصاب والانغراس. اللوالب ⇑ خطر النزف الرحمي الشاذ؛ إدخالها مضاد استطباب لدى المريضات ذوات عدوى منقولة جنسيًا نشطة."},{"f":"ما آلية اللولب البروجستروني؟","b":"اللولب البروجستروني يعمل كالبروجستينات (تثخين المخاط العنقي وترقيق بطانة الرحم)."},{"f":"ما وسائل منع الحمل الجراحية؟","b":"الذكور: قطع الأسهر (vasectomy) — لا نطاف في القذف. الإناث: ربط البوقين (tubal ligation) — النطاف لا تصل إلى البويضات. غير قابلة للعكس."},{"f":"ما أشكال البروجستينات (Progestins) لمنع الحمل؟","b":"الأشكال تشمل: الحبوب، اللولب الرحمي، الغرسة، الحقنة المستودعية."},{"f":"ما دور ميفيبريستون وأوليبريستال؟","b":"ميفيبريستون (مضاد بروجستين تنافسي) مع ميزوبروستول (نظير PGE1) لإنهاء الحمل؛ أوليبريستال (ulipristal) لمنع الحمل الطارئ."},{"f":"كيف تمنع الرضاعة الطبيعية الحمل؟","b":"البرولاكتين ← ⇓ GnRH ← تأخر الإباضة التالية للولادة (منع حمل طبيعي أثناء الإرضاع)."},{"f":"ما التفاعل بين لاموتريجين وموانع الحمل الإستروجينية؟","b":"تنخفض تراكيز لاموتريجين (Lamotrigine) مع موانع الحمل الحاوية على الإستروجين — استخدم بديلًا وعايِر الجرعة ببطء."},{"f":"ما علاقة موانع الحمل المركبة بفرط التخثر؟","b":"الحمل/النفاس وموانع الحمل الفموية المركبة من الأسباب الشائعة لتعزيز حالة فرط التخثر (⇑ خطر الخثار الوريدي VTE)."},{"f":"ما فائدة الرضاعة الطبيعية للأم في الأورام؟","b":"الرضاعة الطبيعية ⇓ خطر إصابة الأم بسرطان الثدي والمبيض."},{"f":"ما أشكال موانع الحمل الهرمونية المركبة؟","b":"الأشكال تشمل: الحبوب، اللصاقة عبر الجلد، الحلقة المهبلية."}]},{"t":"إنتانات السبيل التناسلي","cards":[{"f":"ما التهاب المهبل الجرثومي (Bacterial vaginosis): علاماته وعلاجه؟","b":"لا التهاب؛ مفرزات رقيقة بيضاء ذات رائحة سمكية. المختبر: خلايا دليلية (خلايا ظهارية مغلفة بالجراثيم)، pH > 4.5، اختبار النفاث (whiff test) بـ KOH موجب. العلاج: ميترونيدازول أو كليندامايسين. تترافق مع النشاط الجنسي لكنها ليست منقولة جنسيًا."},{"f":"ما التهاب المهبل بالمشعرات (Trichomonas vaginitis)؟","b":"مفرزات رغوية صفراء-خضراء كريهة الرائحة؛ «عنق الفراولة» (strawberry cervix)؛ مشعرات كمثرية متحركة في التحضير الرطب؛ pH > 4.5. العلاج: ميترونيدازول + علاج الشريك الجنسي."},{"f":"ما التهاب الفرج والمهبل بالمبيضات (Candida vulvovaginitis)؟","b":"مفرزات بيضاء سميكة «شبيهة بجبن القريش» (cottage cheese)؛ خيوط كاذبة (pseudohyphae)؛ pH طبيعي (4.0-4.5). العلاج: الآزولات."},{"f":"ما الداء الالتهابي الحوضي (PID): مكوناته وعلاماته؟","b":"عدوى صاعدة تسبب التهاب السبيل التناسلي الأنثوي؛ قد يشمل: التهاب البوق والتهاب بطانة الرحم وموه البوق وخراج البوق والمبيض. العلامات: إيلام تحريك عنق الرحم، إيلام الملحقات، مفرزات عنقية قيحية."},{"f":"ما أهم جراثيم الداء الالتهابي الحوضي؟","b":"المتدثرة التراخومية (تحت حادة، غالبًا غير مشخصة — أشيع عدوى منقولة جنسيًا جرثومية في الولايات المتحدة)، النيسرية البنية (حادة)."},{"f":"ما متلازمة فيتز-هيو-كيرتس (Fitz-Hugh-Curtis)؟","b":"عدوى والتهاب ما حول الكبد من PID؛ التصاقات «أوتار الكمان» (violin string) من الصفاق إلى محفظة الكبد."},{"f":"ما عقابيل التهاب البوق (Salpingitis)؟","b":"التهاب البوق عامل خطر للحمل خارج الرحم والعقم وألم الحوض المزمن والالتصاقات."},{"f":"ما اختلاطات خمج المتدثرة التراخومية (Chlamydia)؟","b":"التهاب الإحليل/مرض التهاب الحوض، الحمل خارج الرحم، ذات رئة الوليد، التهاب المفاصل التفاعلي."},{"f":"ما اللاطئة المشروطة (Condylomata lata)؟","b":"اللاطئة المشروطة (condylomata lata): آفات بيضاء ملساء غير مؤلمة شبيهة بالثآليل على الأعضاء التناسلية — من علامات الزهري."},{"f":"أين قد تظهر عدوى فيروس الهربس التناسلي؟","b":"فيروسا الهربس HSV-1 وHSV-2 قد يحدثان في أي مكان من السطوح المخاطية إلى الجلد الطبيعي؛ تشمل: هربس الشفة، هربس الأعضاء التناسلية، الداحس الهربسي."},{"f":"ما القريح (Chancroid)؟","b":"القريح (Chancroid): قرحة تناسلية مؤلمة."},{"f":"ما خمج الشعيات (Actinomyces) وعلاقته بالتهاب الحوض؟","b":"حبيبات «كبريتية» صفراء؛ يمكن أن تسبب التهاب الحوض (مترافقة مع اللولب الرحمي)."},{"f":"ما برنامج المسح لسرطان عنق الرحم؟","b":"في المملكة المتحدة: يُعرض على المولودين إناثًا اختبار HPV لعنق الرحم كل 3-5 سنوات بعمر 25-64 سنة؛ هدف المسح انتقاء من يحتاجون تحريًا إضافيًا."}]},{"t":"الاضطرابات الفيزيولوجية والفيزيائية للدورة الطمثية","cards":[{"f":"ما الألم المتوسط (Mittelschmerz)؟","b":"«الألم في المنتصف»: ألم مع الإباضة مترافق مع تهيج الصفاق من النزف الطبيعي عند تمزق الجريب؛ غالبًا أحادي الجانب وخفيف، لكنه قد يحاكي التهاب الزائدة الحاد."},{"f":"أي طوري الدورة المبيضية ثابت المدة؟","b":"الطور الجريبي متفاوت الطول (يحفَّز بـ FSH)، بينما الطور الأصفري ثابت 14 يومًا."},{"f":"ما محفز ذروة LH؟","b":"الإستروجين العالي في منتصف الدورة يحفز تحرير LH عابرًا ← ذروة LH ← الإباضة."},{"f":"فرّق نسيجيًا بين طوري الدورة الرحمية.","b":"الطور التكاثري: بتحفيز الإستروجين، غدد بطانية مستقيمة ضيقة. الطور الإفرازي: بتحفيز البروجسترون، غدد بطانية ملتفة متوسعة."},{"f":"ما أثر البروجسترون على حرارة الجسم؟","b":"البروجسترون ⇑ حرارة الجسم؛ و⇑ البروجسترون دليل على حدوث الإباضة."},{"f":"ما وظيفتا البرولاكتين (Prolactin)؟","b":"البرولاكتين يحفز الإرضاع ويحافظ عليه، و⇓ الوظيفة التناسلية."}]},{"t":"الأمراض النسائية في مرحلة الطفولة والمراهقة","cards":[{"f":"ما أشيع سبب لانقطاع الطمث الأولي؟","b":"أنثى 45,XO؛ خلل تكون المبيض (مبيض شريطي)؛ أشيع سبب لانقطاع الطمث الأولي؛ ⇑ FSH/LH و⇓ إستروجين — «سن يأس قبل الحيض»."},{"f":"ما مراحل تانر (Tanner) وأبكر صفة بلوغية؟","b":"يُمنح تقييم النضج الجنسي (Tanner) بشكل مستقل للأعضاء التناسلية/الثدي وشعر العانة؛ أبكر صفة جنسية ثانوية قابلة للكشف: تطور برعم الثدي (thelarche) لدى الإناث وتضخم الخصية لدى الذكور."},{"f":"متى يزداد وقوع الحزاز المتصلب لدى الإناث؟","b":"الحزاز المتصلب (Lichen sclerosus): ⇑ الوقوع لدى الإناث قبل البلوغ وفي الفترة المحيطة بسن اليأس/بعده؛ مرض التهابي مزمن بلويحات بيضاء خزفية؛ يتظاهر بحكة شديدة."}]},{"t":"ترشيح الجهاز التناسلي الأنثوي","cards":[{"f":"ما مكونات الرباط العريض وأين يمر الرباط المدور؟","b":"الرباط العريض (Broad ligament): طية من الصفاق من الرحم إلى الجدار الحوضي الجانبي؛ تضم: المسارحم (mesometrium)، المساريق المبيضية (mesovarium)، المساريق البوقية (mesosalpinx). الرباط المدور (round ligament): من قرن الرحم إلى الشفرين الكبيرين عابرًا القناة الأربية — مشتق من الرباط المرشد (gubernaculum)."},{"f":"ما الرباط الرئيسي والرباط الرحمي العجزي؟","b":"الرباط الرئيسي (Cardinal ligament): من عنق الرحم إلى الجدار الحوضي الجانبي؛ تكاثف عند قاعدة الرباط العريض — ربط الأوعية الرحمية أثناء استئصال الرحم يُخاطر بإيذاء الحالب. الرباط الرحمي العجزي (Uterosacral): من عنق الرحم إلى العجز."},{"f":"ما النسيج الظهاري للسبيل التناسلي الأنثوي؟","b":"سطح المبيض: ظهارة مكعبة بسيطة (الظهارة الجرثومية germinal epithelium). قناة فالوب: ظهارة عمودية بسيطة مهدبة. الرحم: ظهارة عمودية بسيطة مع غدد (مستقيمة في الطور التكاثري، ملتفة في الطور الإفرازي). منطقة التحويل (الموصل الحرشفي العمودي): المنطقة الأشيع لسرطان عنق الرحم وتُؤخذ عينتها في مسحة بابانيكولاو."}]},{"t":"السبيل البولي وعلاقته بالأمراض النسائية","cards":[{"f":"ما السلس البولي الجهدي (Stress incontinence): آليته وعلاجه؟","b":"قصور المخرج (فرط حركة إحليلي أو قصور مصرة جوهري) ← تسرب مع زيادة الضغط داخل البطن (العطاس، حمل الأثقال)؛ اختبار جهد المثانة إيجابي (تسرب مشاهَد من الإحليل عند السعال/فالسالفا). الارتباطات: البدانة، الحمل، الولادة المهبلية. العلاج: تقوية عضلات قاع الحوض (تمارين كيغل)، إنقاص الوزن، الفرزجات (pessaries)."},{"f":"ما السلس البولي الإلحاحي (Urgency incontinence): آليته وعلاجه؟","b":"فرط نشاط الدافعة (detrusor overactivity) ← تسرب مع رغبة ملحة بالتبول فورًا. الارتباطات: تهيج المثانة من عدوى المسالك البولية والحصيات والأورام والتشعيع الحوضي. العلاج: فيزيائي قاع الحوض وتدريب المثانة (تبول موقوت) ومضادات المسكارين (أوكسيبوتينين) وميرابيغرون/فيبيغرون (ناهضات β3)."},{"f":"ما سلس الفيض (Overflow incontinence) وعلاقته بالأمراض النسائية؟","b":"إفراغ غير كامل (قصور الدافعة أو انسداد المخرج) ← تسرب مع الامتلاء الزائد وزيادة البول المتبقي بعد التبول. الارتباطات: احتباس البول، البوال (مثل السكري)، انسداد مخرج المثانة (BPH)، إصابة النخاع الشوكي. العلاج: القسطرة وتخفيف الانسداد. نسائيًا: سرطان عنق الرحم المتقدم موضعيًا قد يسد الحالب ← موه الكلية (hydronephrosis)."}]},{"t":"الحالات الخثلية والضمورية","cards":[{"f":"ما الحزاز المتصلب (Lichen sclerosus)؟","b":"مرض التهابي مزمن متقدم بلويحات بيضاء خزفية قد تكون نازفة أو متآكلة أو متقرحة؛ قد يمتد إلى الشرج منتجًا مظهر «الرقم ثمانية»؛ ⇑ الوقوع قبل البلوغ وحوالي/بعد سن اليأس؛ حكة شديدة وعسر جماع وتبول وتغوط؛ سليم لكن ⇑ طفيف في خطر سرطان الخلايا الحرشفية (SCC)."},{"f":"ما الحزاز البسيط المزمن (Lichen simplex chronicus)؟","b":"فرط تنسج الظهارة الحرشفية الفرجية؛ جلد فرجي سميك جلدي الملمس مع علامات جلدية معززة بسبب الفرك/الحك المزمن؛ سليم — لا خطر لـ SCC."},{"f":"ما داء باجت خارج الثدي (Extramammary Paget disease)؟","b":"سرطان غدي داخل الظهارة (in situ) موضَّع؛ يتظاهر بحكة وحمامى وتقشر وقرح؛ خطر منخفض لسرطان كامن — مقابل داء باجت في الثدي الذي يترافق دائمًا مع سرطان كامن."}]},{"t":"الثدي","cards":[{"f":"ما الورم الغدي الليفي (Fibroadenoma)؟","b":"الأشيع لدى الإناث دون 35 سنة؛ كتلة صغيرة محددة جيدًا متحركة؛ مكوَّن من نسيج ليفي وغدد؛ ⇑ الحجم والإيلام مع ⇑ الإستروجين (الحمل، قبل الحيض)؛ خطر السرطان غالبًا غير مرتفع."},{"f":"ما الورم الحليمي داخل القناة (Intraductal papilloma)؟","b":"ورم ليفي ظهاري صغير داخل القنوات اللبنية غالبًا تحت الهالة؛ أشيع سبب لمفرزات الحلمة (غالبًا أحادية الجانب، مصلية أو دموية)؛ ⇑ طفيف في خطر السرطان."},{"f":"فرّق بين DCIS وLCIS.","b":"السرطان القنوي الموضَّع (DCIS): خباثة مبكرة دون اختراق الغشاء القاعدي؛ عادة لا كتلة؛ يُرى كتكلسات دقيقة بالتصوير الشعاعي للثدي. السرطان الفصيصي الموضَّع (LCIS): ⇓ التعبير عن E-cadherin؛ موجود خزعي عرضي (لا كتلة ولا تكلسات)؛ ⇑ خطر السرطان في أيٍّ من الثديين."}]}]},{"s":"الأطفال 1","topics":[{"t":"الطفل في المجتمع","cards":[{"f":"ما تصنيف IMNCI للحالة التغذوية عند الأطفال من عمر شهرين إلى 5 سنوات؟","b":"سوء تغذية حاد وخيم (Severe acute malnutrition) مع اختلاطات أو بدونها: الوزن للطول (WFL/H) أقل من -3 انحراف معياري، أو محيط منتصف العضد (MUAC) أقل من 11.5 سم، أو وذمة ثنائية في القدمين. الاختلاطات الطبية تشمل: أي علامة خطر عامة، أي تصنيف وخيم، ذات الرئة، إسهال مع تجفاف، ضعف الشهية. سوء تغذية حاد متوسط (Moderate): WFL/H بين -2 و-3 انحراف معياري أو MUAC بين 11.5 و12.4 سم."},{"f":"ما تعريف الرضاعة الطبيعية الخالصة (Exclusive breastfeeding) ومدتها؟","b":"حليب الأم (Breast milk) هو الغذاء الوحيد الذي يحتاجه الرضيع حتى أول 4-6 أشهر من العمر. الرضاعة الخالصة تعني أن الوليد يأخذ حليب الأم فقط دون أي شيء آخر: لا عسل ولا ماء ولا عصائر ولا منشطات ولا أدوية (ما لم تُوصف) ولا أي حليب حيواني."},{"f":"ما علامات التجفاف الشديد (Severe dehydration) حسب إرشادات IMNCI وكيف يُدبَّر؟","b":"أي اثنتين من: خمول أو فقدان وعي (Lethargic/unconscious)، عينان غائرتان (Sunken eyes)، عدم القدرة على الشرب (Inability to drink)، مرونة جلدية منخفضة جدًا (Very low skin turgor). التدبير: سوائل وريدية حسب خطة C من WHO، إحالة عاجلة، محلول الإماهة الفموي (ORS) والرضاعة الطبيعية أثناء النقل، وصادات حيوية فموية عند وجود وباء كوليرا (فوق عمر سنتين)."}]},{"t":"القصة والفحص السريري","cards":[{"f":"ما تعريف الفشل في النمو (Failure to thrive)؟","b":"حالة سريرية لفشل النمو بأي سبب، تُشخَّص بوجود أي مما يلي: (أ) غياب النمو أي الوزن للعمر دون الشريحة المئوية الثالثة (3rd percentile)، (ب) عدم كسب الوزن مع الزمن بالمراقبة المتسلسلة، (ج) تباطؤ سرعة النمو أي هبوط الوزن شريحتين مئويتين كبيرتين على الأقل عن القيم السابقة خلال فترة قصيرة (مثلًا من 75 إلى 25)."},{"f":"ما الأسباب المرضية للفشل في النمو (Failure to thrive)؟","b":"ضعف هضم أو امتصاص المغذيات (متلازمات سوء الامتصاص)، زيادة المتطلبات الاستقلابية (أمراض مزمنة أو التهابات)، زيادة فقد الطعام المتناول (إسهال أو إقياء مزمن)."},{"f":"ما العلامات السريرية المرافقة للفشل في النمو؟","b":"سوء تغذية: فشل نمو، فقر دم، عوز فيتامينات ومعادن. تغيرات سلوكية: لامبالاة (Apathy)، انسحاب اجتماعي، ضعف التواصل البصري أو الاستجابة للاحتضان. تأخر تطور (Developmental retardation)."},{"f":"ما قاعدة المنعكسات البدائية (Primitive reflexes) في الفحص التطوري؟ وما أشيع سبب لتأخر تطور اللغة؟","b":"المنعكسات الوليدية البدائية كمنعكس القبضة (Grasp) أو الخطو (Stepping) يجب أن تختفي قبل الوظيفة الإرادية المقابلة (القبضة الإرادية أو الوقوف). استمرار منعكس وليدي بعد عمر اختفائه المتوقع وحده يدل على مشكلة تطورية كما في الشلل الدماغي. أشيع سبب لتأخر تطور اللغة هو ضعف السمع (Hearing impairment)."}]},{"t":"تطور الطفل الطبيعي","cards":[{"f":"ما المجالات الخمسة للتطور (Developmental domains) عند الطفل؟","b":"1) الحركية الكبيرة (Gross motor): جلوس ووقوف. 2) الحركية الدقيقة (Fine motor): إمساك الأشياء وإطعام النفس. 3) الشخصية-الاجتماعية (Personal-social): التفاعل مع الآخرين والتعبير عن العواطف. 4) التكيفية أو الإدراكية (Adaptive/Cognitive): استكشاف البيئة والتعلم من التجارب. 5) اللغوية (Linguistic): تطور الكلام."},{"f":"ما المعالم الحركية الكبيرة (Gross motor milestones) الأساسية حتى 5 سنوات؟","b":"ثبات الرقبة (Neck holding) بعمر 3 أشهر (أول معلم عملي)، المشي دون دعم بعمر 12 شهرًا، صعود الدرج بقدم واحدة لكل درجة بعمر 36 شهرًا، القفز على قدم واحدة بعمر 48 شهرًا، القفز بالقدمين معًا بعمر 60 شهرًا. التأخر في هذه الوظائف قد يحدث في سوء التغذية الشديد رغم سلامة الوظيفة العصبية."},{"f":"ما المعالم الحركية الدقيقة (Fine motor milestones) الأساسية؟","b":"القبضة الإرادية (Voluntary grasp) بعمر 4 أشهر (بعد اختفاء منعكس القبضة الوليدي وهي أبكر معلم حركي دقيق)، الملقط غير الناضج بعمر 9 أشهر والناضج (Mature pincer grasp) بعمر 10 أشهر، برج من مكعبين بعمر 12 شهرًا و6 مكعبات بعمر سنتين، نسخ الدائرة بعمر 36 شهرًا ونسخ المثلث بعمر 60 شهرًا. هذه المهارات مؤشر أدق على النضج العصبي لأنها لا تتأثر عادة بالاضطرابات التغذوية."},{"f":"ما المعالم الشخصية-الاجتماعية (Personal-social milestones) الأساسية؟","b":"الابتسامة الاجتماعية (Social smile) بعمر 6 أسابيع تقريبًا (أبكر معلم نفسي-اجتماعي)، التعرف على الأم بعمر 3 أشهر، قلق الغرباء (Stranger anxiety) والاستمتاع بلعبة الغميضة بعمر 6 أشهر، التلويح (باي-باي) بعمر 9 أشهر، الجفاف نهارًا بعمر 24 شهرًا، الجفاف ليلًا ومشاركة الألعاب بعمر 36 شهرًا."},{"f":"ما المعالم اللغوية (Linguistic milestones) الأساسية؟","b":"المقاطع أحادية الصوت (ma, da) بعمر 6 أشهر (أبكر معلم لغوي حقيقي)، المقاطع ثنائية (mama, dada) بعمر 9 أشهر، كلمتان ذاتا معنى بعمر 12 شهرًا، جمل من 2-3 كلمات مع استخدام الضمائر (أنا/أنت) بعمر 24 شهرًا، طرح الأسئلة بعمر 36 شهرًا، جمل صحيحة نحويًا بعمر 60 شهرًا."},{"f":"ما المعالم التكيفية/الإدراكية (Adaptive milestones) الأساسية؟","b":"التثبيت البصري على جسم متحرك بعمر 4 أسابيع (أبكر معلم تكيفي)، النظر إلى اليد (Hand-regard) بعمر 4 أشهر ويختفي بحلول 6 أشهر، الاستكشاف الفموي (Mouthing) بعمر 5 أشهر ويتوقف مع نهاية الرضاعة، البحث عن لعبة ساقطة بعمر 6 أشهر، الإشارة إلى 4-6 أجزاء من الجسم بعمر 24 شهرًا، معرفة الاسم والجنس بعمر 36 شهرًا."},{"f":"ما العلامات الحمراء (Red flags) في التقييم التطوري؟","b":"استمرار النظر إلى اليد (Hand-regard) بعد 6 أشهر أو الاستكشاف الفموي (Mouthing) بعد 12 شهرًا يشير لتأخر النمو العصبي. التأخر المعزول في الحركية الدقيقة يشير للشلل الدماغي أو إصابة عصبية محيطية (مثل شلل إرب Erb's palsy). التأخر المعزول في المجال الشخصي-الاجتماعي يشير للتخلف العقلي أو التوحد أو ضعف البصر أو الطفل المحروم عاطفيًا."},{"f":"كيف يُفرَّق بين أسباب التأخر التطوري الشامل؟","b":"التأخر الشامل غير المترقي (Non-progressive global delay) يشير للشلل الدماغي (Cerebral palsy). الانحراف (Deviancy) أو التراجع (Regression) في المجالين الاجتماعي والتواصلي قد يشير لاضطراب طيف التوحد (Autism spectrum disorder). التأخر المنفصل (Dissociation) في مجال أو مجالين يضيّق التشخيص: ضعف السمع لمجال الكلام، وضعف البصر/السمع للمجال الشخصي-الاجتماعي، والاضطرابات العصبية-العضلية للمجال الحركي."},{"f":"ما معالم التسنين الطبيعي؟ وماذا يدل تأخر إغلاق اليافوخ الأمامي؟","b":"عدد الأسنان اللبنية 20 والدائمة 32. يبدأ التسنين اللبني بعمر 5-8 أشهر ببزوغ القاطع المركزي السفلي (أول سن لبني) ويكتمل بعمر 2-2.5 سنة ببزوغ الرحى الثانية. لدى الرضيع نحو 6 أسنان لبنية بعمر سنة، ويبدأ تساقط اللبنية نحو عمر 6 سنوات. اليافوخ الأمامي (Anterior fontanel) عند الولادة مفتوح ولين ومسطح؛ وتأخر إغلاقه علامة على الكساح (Rickets) أو قصور الدرق."}]},{"t":"المشكلات التطورية والطفل ذو الاحتياجات الخاصة","cards":[{"f":"كيف يوجّه التأخر المنفصل (Developmental dissociation) التشخيص السببي؟","b":"التأخر الانتقائي في مجال أو مجالين يضيّق الاحتمالات التشخيصية: ضعف السمع (Hearing impairment) لمجال الكلام/اللغة، وضعف البصر أو السمع للمجال الشخصي-الاجتماعي، والاضطرابات العصبية-العضلية (Neuromuscular disorders) للمجال الحركي."},{"f":"ما الفرق السريري بين الشلل الدماغي واضطراب طيف التوحد في سياق التأخر التطوري؟","b":"التأخر الشامل غير المترقي (Non-progressive global delay) يشير للشلل الدماغي (Cerebral palsy)، بينما الانحراف (Deviancy) أو التراجع (Regression) في المجالين الاجتماعي والتواصلي قد يشير لاضطراب طيف التوحد (Autism spectrum disorder)."},{"f":"ما مكونات برنامج التأهيل للطفل ذي الاحتياجات الخاصة؟","b":"برنامج فردي حسب احتياجات الطفل وإمكاناته بفريق متعدد الاختصاصات: (أ) علاج فيزيائي ومهني (Physiotherapy and occupational therapy) للخلل العصبي-العضلي، (ب) تدبير العجز المرافق كالسمع والبصر وتأخر الكلام والاختلاجات، (ج) علاج نفسي أو تعديل سلوكي، (د) التعليم في مدرسة عادية قدر الإمكان، (هـ) دعم الوالدين وإرشادهم."}]},{"t":"الحالات الإسعافية عند الأطفال","cards":[{"f":"ما تعريف بطء القلب (Bradycardia) عند الأطفال حسب PALS؟","b":"نبض أقل من 60/دقيقة (Bradycardia) مع علامات ضعف التروية (Poor perfusion) رغم الأكسجة والتهوية الكافية — يتطلب البدء بالإنعاش القلبي الرئوي (CPR) لأن مسار التوقف القلبي عند الأطفال يبدأ غالبًا بفشل الجهاز التنفسي وليس باضطراب نظم قلبي أولي كما عند البالغين."},{"f":"ما المسار النموذجي للتوقف القلبي (Cardiac arrest) عند الرضع والأطفال؟","b":"يبدأ غالبًا بفشل الجهاز التنفسي (Respiratory failure) ثم نقص الأكسجة (Hypoxia) ثم بطء القلب ثم التوقف القلبي — لذلك يركّز PALS على التدخل المبكر لمنع التوقف القلبي عبر دعم الأكسجة والتهوية قبل حدوثه."},{"f":"ما جرعة بولوس السوائل (Fluid bolus) في الصدمة عند الأطفال؟","b":"20 مل/كغ من محلول بلوري متساوي التوتر (Normal saline أو Lactated Ringer) وريديًا تُعاد حسب الحاجة. في الصدمة الإنتانية (Septic shock) المشتبهة تُعطى 10-20 مل/كغ بسرعة حسب الاستجابة."},{"f":"ما علامات ذات الرئة الشديدة (Severe pneumonia) حسب IMNCI؟","b":"أي علامة خطر عامة (General danger sign)، أو صرير (Stridor)، أو إشباع أكسجين (SpO2) أقل من 90%. التدبير: أول جرعة صادات حيوية عضلية، وعلاج/وقاية نقص السكر، وجرعة باراسيتامول إذا تجاوزت الحرارة 38.5°م، ثم إحالة عاجلة."}]},{"t":"الحوادث والتسممات","cards":[{"f":"ما آلية وخطورة التسمم بالكيروسين (Kerosene poisoning)؟","b":"أشيع سبب للتسمم العرضي والوفيات المرتبطة بالتسمم عند أطفال ما قبل المدرسة. الكيروسين من المركبات الأليفاتية منخفضة اللزوجة عالية التطاير (Low viscosity-high volatile) التي تحمل خطرًا عاليًا للشفط الرئوي (Aspiration) — والخطر يعتمد على التطاير واللزوجة أكثر من السمية المباشرة للمادة."},{"f":"ما مراحل التسمم بالباراسيتامول (Paracetamol poisoning) وما ترياقه النوعي؟","b":"الجرعة السامة المحتملة أكثر من 140 ملغ/كغ. السمية عبر المستقلب الكبدي N-acetyl-p-benzoquinoneimine (NAPQI) الذي يُعطَّل عادة بالغلوتاثيون (Glutathione). المراحل الأربع: حادة (1-24 ساعة: غثيان/إقياء)، صامتة (24-48 ساعة)، أقصى أذية كبدية (48-96 ساعة: يرقان مترقٍ)، الشفاء (4-14 يومًا). الترياق النوعي: N-acetylcysteine (NAC) — طليعة الغلوتاثيون التي تمنع السمية الكبدية."},{"f":"ما مراحل التسمم بالحديد (Iron poisoning) الخمسة وما علاجه النوعي؟","b":"جرعة ~60 ملغ/كغ من الحديد العنصري سمية خطيرة و>300 ملغ/كغ قاتلة محتملة. المراحل الخمس المتداخلة: حادة (نصف-2 ساعة: إقياء وألم بطني ونزف هضمي)، شفاء ظاهري (1-2 يوم)، فشل دوراني مع حماض استقلابي، فشل كبدي (2-4 أيام)، تندب معدي (2-4 أسابيع) قد يسبب انسدادًا معويًا مزمنًا. العلاج النوعي: Desferrioxamine وريدي 5-15 ملغ/كغ/ساعة إذا تجاوز الحديد الحر 300 مكغ/دل حتى يصبح البول بلون النبيذ (Vinrose urine). الفحم المنشط لا قيمة له هنا."},{"f":"ما العلامة المميزة للتسمم بالفوسفور العضوي (Organophosphorus poisoning)؟","b":"زيادة التعرق واللعاب (Sweating/Salivation) من علامات فرط النشاط الكولينرجي. ملاحظة: المركبات الفوسفورية العضوية قد تكون مضافة لبعض الهيدروكربونات كمركّبات للمبيدات الحشرية، ما يضيف خطرًا إضافيًا عند التسمم بالهيدروكربونات."}]},{"t":"حماية الطفل","cards":[{"f":"ما تعريف إساءة معاملة الأطفال وإهمالهم (Child abuse and neglect) حسب WHO؟","b":"الاستغلال أو الإساءة الجسدية و/أو العاطفية و/أو الجنسية، بقصد أو بإهمال، للأطفال دون 18 سنة، من قبل الوالدين أو مقدمي الرعاية أو أرباب العمل أو غيرهم. الطيف السريري: إساءة جسدية (تشمل عمالة الأطفال)، إساءة عاطفية (الترويع أو الرفض)، إساءة جنسية (مع أو دون اغتصاب/سفاح)، إساءة اجتماعية (تمييز جنس أو طبقة)."},{"f":"ما المؤشرات السريرية لإساءة معاملة الطفل؟","b":"قصة متضاربة (Discordant history) أو متباينة بين الوالدين، إنكار أبوي قاطع للسبب المشتبه، تأخر طلب المساعدة الطبية. علامات غامضة: إصابات سطحية غير مفسرة (حروق/كدمات)، إصابات عميقة غير مفسرة (إصابة رأس — متلازمة الطفل المهزوز Shaken-baby syndrome — أو إصابات هيكلية/خلوع)، صمم مفاجئ أو إصابة عينية (نزف تحت الملتحمة)، إصابات تناسلية، فشل نمو غير مفسر. والتحسن السريع أثناء الاستشفاء أو الانفصال عن المشتبه علامة داعمة."},{"f":"ما دور طبيب الأطفال في تدبير إساءة معاملة الطفل؟","b":"التدبير جهد جماعي (طبيون، أخصائيون اجتماعيون، سلطات قانونية، منظمات). دور الطبيب: التعرف المبكر على الإساءة المحتملة، تحديد العوامل المحرضة، الإبلاغ للسلطات مع المساعدة اللازمة، علاج الإصابات الجسدية، الدعم العاطفي وطلب مساعدة الطبيب النفسي عند الحاجة، عزل الطفل عن البيئة المؤذية (استشفاء)، الرعاية أثناء الإيداع المؤسسي، والمساعدة في جهود التأهيل."}]},{"t":"علم الوراثة","cards":[{"f":"ما السمات السريرية المميزة لمتلازمة داون (Down syndrome - Trisomy 21)؟","b":"أشيع سبب وراثي للتخلف العقلي. السمات: وجه مسطح وجسر أنفي صغير منخفض، آذان صغيرة مشوهة وصمم، لسان متشقق بارز وحنك عالٍ مقوس، رقبة قصيرة مع طيات خلفية رخوة في الرضاعة، يدان/قدمان قصيرتان عريضتان، انحناء الإصبع الخامس (Clinodactyly)، فجوة صندلية (Sandal gap)، ثنية قردية (Simian crease)، وهن عضلي معمم مع فرط مرونة مفاصل وضعف منعكس مورو، تأخر تطور. قلبيًا: عيوب الوسادة الشغافية (Endocardial cushion defects) وغيرها من التشوهات القلبية الخلقية."},{"f":"ما السمات السريرية لمتلازمة تيرنر (Turner syndrome - 45,XO)؟","b":"أشيع اضطراب في الصبغيات الجنسية عند الإناث (نحو 1:2500 ولادة حية أنثوية). السمات: قصر قامة، رقبة قصيرة مكففة (Webbed neck) مع خط شعر منخفض، صدر عريض مع تباعد الحلمتين، زاوية حمل مرفقية واسعة (Cubitus valgus أكثر من 110°)، وذمة ظهر اليد/القدم، خلل تكون الغدد التناسلية (مبيضان شريطيان: تأخر بلوغ/انقطاع طمث/عقم). قلبيًا: تضيق برزخ الأبهر (Coarctation of aorta) وصمام أبهري ثنائي الشرف. كلويًا: كلية حدوة الحصان (Horseshoe kidney)."},{"f":"ما خطر التكرار (Recurrence risk) لمتلازمة داون؟","b":"مع نمط أبوي طبيعي (Normal parental karyotype): عمر الأم أقل من 35 سنة 1%، وعمر الأم أكثر من 35 سنة 1% إضافية فوق خطر العمر. مع نمط أبوي شاذ (Balanced translocation) يكون الخطر أعلى ويستلزم استشارة وراثية."}]},{"t":"الطب حول الولادة","cards":[{"f":"ما عناصر مقياس أبغار (APGAR score) الخمسة ودرجاتها؟","b":"المظهر/اللون (Appearance): أزرق/شاحب 0، جسم وردي وأطراف زرقاء 1، وردي 2. النبض (Pulse): غائب 0، أقل من 100/دقيقة 1، أكثر من 100/دقيقة 2. التكشيرة (Grimace): لا استجابة 0، استجابة بسيطة للتنبيه 1، بكاء أو انسحاب نشط 2. النشاط/التوتر العضلي (Activity): غائب 0، بعض الثني 1، نشط 2. الجهد التنفسي (Respiratory effort): غائب 0، بطيء وغير منتظم 1، بكاء قوي 2."},{"f":"متى يُحسب مقياس أبغار (APGAR)؟","b":"عند الدقيقة 1 والدقيقة 5 من الولادة، ثم كل 5 دقائق بعدها حتى الدقيقة 20 أو حتى تحسن الدرجة — لتقييم التكيف الوليدي والحاجة للإنعاش."},{"f":"ما مظاهر التعرض للكحول أثناء الحمل على الوليد؟","b":"انخفاض وزن الولادة، ارتجاف وعصبية، سوء تغذية وإسهال، تشوهات وجهية مميزة لمتلازمة الكحول الجنينية (Fetal alcohol syndrome): طيات فوق الموق (Epicanthal folds)، جسر أنفي مسطح. التأثير طويل الأمد: متلازمة الكحول الجنينية وعواقب عصبية."},{"f":"ما مظاهر التعرض لـ SSRI/SNRI أثناء الحمل على الوليد وكيف تُدبَّر؟","b":"متلازمة التكيف الوليدي الضعيف (Poor neonatal adaptation): ضائقة تنفسية، ارتجاف/عصبية، صعوبات تغذية، بكاء ضعيف، ونادرًا نقص أكسجة من ارتفاع التوتر الرئوي المستمر (PPHN). التدبير: بيئة هادئة، تقميط (Swaddling)، تلامس جلد-لجلد، تشجيع الرضاعة الطبيعية، وجبات صغيرة متكررة؛ وتتحسن خلال أيام إلى أسابيع."},{"f":"ما فيزيولوجيا متلازمة الضائقة التنفسية (RDS - Hyaline membrane disease) عند الخدج؟","b":"عوز السورفاكتانت الرئوي (Surfactant deficiency). السورفاكتانت يتكون من فوسفوليبيدات (80%) وبروتينات (10%) ودهون محايدة (10%)، تنتجه الخلايا السنخية من النمط الثاني (Type II alveolar cells) بين الأسبوعين 24 و34 من الحمل. وظيفته: خفض التوتر السطحي في السنخ ومنع انخماصه نهاية الزفير؛ وعوزه يؤدي لانخماص سنخي وعدم تطابق تهوية-تروية (VQ mismatch) ونقص أكسجة ونقص تهوية."},{"f":"ما فيزيولوجيا التسارع التنفسي العابر للوليد (TTN) وعوامل خطره وتدبيره؟","b":"وذمة رئوية بسبب تأخر تصفية السائل من الأسناخ (Delayed fluid clearance)؛ الكاتيكولامينات والهرمونات في أواخر الحمل والمخاض تحوّل الظهارة التنفسية من إفرازية إلى امتصاصية، وغياب المخاض (قيصرية) يؤخر الامتصاص. عوامل الخطر: الولادة القيصرية، سكري الأم، الاكتئاب المحيط بالولادة، التخدير الأمومي، الولادة الخاطفة. التدبير: دعم، أكسجين، CPAP."},{"f":"كيف يُفرَّق بين RDS وTTN عند الوليد؟","b":"RDS: عوز سورفاكتانت عند الخدج، الأشعة: مظهر الزجاج الأرضي (Ground glass) مع فقاعات هوائية. TTN: تأخر امتصاص السائل السنخي، أشيع عند مكتملي النمو بعد القيصرية، الأشعة: ارتشاحات حول النقير ثنائية الجانب (Bilateral perihilar infiltrates)."},{"f":"ما منطق إعطاء الستيروئيدات قبل الولادة (Antenatal steroids)؟","b":"تُعطى عند خطر الولادة المبكرة بعمر حملي أقل من 34 أسبوعًا لتحفيز إنتاج السورفاكتانت من الخلايا السنخية من النمط الثاني، فتقلل حدوث وشدة متلازمة الضائقة التنفسية (RDS). كما ثبت أنها تحسّن أعراض التسارع التنفسي العابر (TTN) لأن الغلوكوكورتيكويدات تنظم وظيفة الامتصاص السنخي."}]},{"t":"طب حديث الولادة","cards":[{"f":"ما تعريف الإنتان الوليدي (Neonatal septicemia) وتقسيمه الزمني؟","b":"تشخيص سريري لعلامات الإنتان مع أو دون زرع دم/سائل دماغي شوكي إيجابي خلال الشهر الأول من العمر، وهو أشيع سبب لوفيات الولدان. إنتان مبكر البدء (Early-onset sepsis - EOS): يظهر قبل 72 ساعة من الولادة. إنتان متأخر البدء (Late-onset sepsis - LOS): بعد ذلك — ويختلفان بعوامل الاستعداد والمسببات الجرثومية."},{"f":"ما عوامل خطر الإنتان الوليدي المبكر مقابل المتأخر؟","b":"المبكر (EOS) — أمومية: حمى الأم قبل الولادة بأقل من 14 يومًا، سائل أمنيوسي كريه الرائحة أو ملطخ بالعقي، تمزق أغشية مطول أكثر من 24 ساعة. توليدية: ولادة مطولة أو صعبة أو آلية، فحوص مهبلية متكررة غير نظيفة. المتأخر (LOS) — وليدية: خداج أو صغر الحجم، التهابات سطحية (إنتان سري)، شفط لبن بعد الولادة. مشفوية: إجراءات الإنعاش الوليدي، إجراءات العناية المشددة الغازية، صادات مطولة."},{"f":"ما العلامات السريرية المبكرة للإنتان الوليدي؟","b":"مؤشرات سريرية مبكرة: رفض الرضاعة، خمول أو هياج، بكاء مفرط أو عالي النبرة، ضائقة تنفسية أو نوب انقطاع نفس (Apneic spells)، اختلاجات، إسهال و/أو إقياء."},{"f":"ما علامات الإجهاد الجهازي (Systemic stress) في الإنتان الوليدي؟","b":"نقص حرارة (Hypothermia)، تصلّب الجلد (Sclerema)، شحوب، جلد بارد رطب، زرقة حول الفم (Circumoral cyanosis)، يرقان مبالغ فيه، بقع فرفرية. التروية المحيطية ضعيفة مع زمن امتلاء شعري (Capillary filling time) يتجاوز 3 ثوانٍ."},{"f":"ما معايير شاشة الإنتان (Sepsis screen) عند الوليد؟","b":"نقص الكريات البيض (Leukopenia) أقل من 5000/مم3، نقص العدلات المطلق أقل من 1800/مم3، الخلايا غير الناضجة (Band) أكثر من 20% (نسبة I:T أكثر من 2)، نقص الصفيحات أقل من 100,000/مم3، بروتين C التفاعلي (CRP) أكثر من 8 ملغ/لتر. التشخيص يعتمد على الشك السريري ووجود عوامل خطر عالية."},{"f":"ما اليرقان النووي (Kernicterus) وما العوامل المحددة لخطره؟","b":"أندر وأخطر اختلاط للسمية البيليربينية في فرط البيليربين غير المباشر (Indirect hyperbilirubinemia)، يتميز بعلامات عصبية حادة تصيب الجهاز خارج الهرمي (Extrapyramidal) مع وفيات عالية أو عقابيل طويلة الأمد. العوامل: شدة البيليربينيميا، نوع البيليربين (غير المقترن ذواب بالدهن فيعبر الحاجز الدموي الدماغي ويسبب الأذية؛ المقترن ذواب بالماء فلا يعبر)، ارتباط البيليربين غير المقترن بالألبومين في البلازما."},{"f":"ما عقابيل اليرقان النووي (Kernicterus) المتأخرة وكيف يُدبَّر؟","b":"العقابيل المتأخرة: شلل دماغي رقصي-كنعي (Choreo-athetoid cerebral palsy)، صمم حسي-عصبي، تخلف عقلي أو صعوبات تعلم، تلون الأسنان بالبني. المراحل السريرية: مبكرة ثم المرحلة الثانية (نظرة سفلية مستمرة، تقوس ظهري Opisthotonus، اختلاجات) ثم الثالثة (وهن معمم، غياب بكاء، ذهول). التدبير: الوقاية هي الأساس بالمعالجة الضوئية المبكرة وتبديل الدم (Exchange transfusion)؛ وبعد حدوث الأذية العصبية تصبح غير قابلة للعكس."},{"f":"ما دور المعالجة الضوئية (Phototherapy) في فرط بيليربين الدم الوليدي؟","b":"الدعامة الأساسية للعلاج: تكسّر البيليربين في مناطق الجلد المعرضة للضوء. تُستخدم مع مخطط المعالجة الضوئية (Phototherapy nomogram) لتحديد الحاجة للعلاج حسب تركيز البيليربين الكلي وعمر الوليد بالساعات وعوامل الخطر."},{"f":"كيف يُفرَّق زمنيًا بين التهاب الملتحمة الوليدي بالمكورات البنية والمتدثرة؟","b":"التهاب الملتحمة الوليدي (Ophthalmia neonatorum): المكورات البنية (N. gonorrhoeae) يظهر خلال أول 48 ساعة، والمتدثرة (C. trachomatis) بعد اليوم الخامس (غالبًا أحادي الجانب)، والتهاب الملتحمة المشفوي (Pseudomonas/Staphylococci) في أي عمر. المفرزات اللزجة الخفيفة في الأيام الأولى طبيعية وتزول عفويًا بالتنظيف فقط."},{"f":"ما اختلاطات إنتان السرة (Umbilical sepsis) غير المعالج؟","b":"ثلاثة اختلاطات مهمة: التهاب نسيج خلوي بطني موضعي (Local abdominal cellulitis)، إنتان دم وليدي (Neonatal septicemia)، خثار الوريد البابي (Portal vein thrombosis) مع فرط توتر بابي خارج كبدي (Extrahepatic portal hypertension) في الحياة اللاحقة. الوقاية: نظافة الأم والوليد وغسل الأيدي قبل التعامل مع الطفل."},{"f":"ما مظاهر السلاق الفموي (Oral thrush) عند الوليد وعلاجه؟","b":"لويحات بيضاء ملتصقة (White adherent plaque) بقاعدة حمامية على مخاطية الفم واللسان والحنك تترك نقاط نزف عند إزالتها — تُفرَّق عن بقعة الحليب التي تُزال بسهولة دون نزف. العلاج: مضادات فطرية موضعية (ميكونازول، كلوتريمازول، نيستاتين أو بنفسجية الجنتيانا 0.5%)؛ ولا حاجة لمضاد فطري جهازي في الداء السطحي."},{"f":"ما المظاهر المبكرة لقصور الدرق الخلقي (Congenital hypothyroidism)؟","b":"أشيع سبب لقصور الدرق عند الولدان. المظاهر المبكرة: يافوخ خلفي واسع مفتوح (Wide-open posterior fontanel)، يرقان مطول (Prolonged jaundice)، إمساك، صعوبات رضاعة وتنفس، خمول وضعف بكاء، فتق سري (Umbilical hernia)، نقص حرارة (Hypothermia). الحالة المتقدمة (بعد 8-10 أسابيع): توقف نمو (قامة قصيرة)، ملامح وجهية نموذجية، شعر خشن قليل. العلاج: ليفوثيروكسين مدى الحياة في خلل تكون الدرق؛ والنتيجة تعتمد على عمر التشخيص وبدء العلاج لأن الفترة الوليدية حاسمة عصبيًا."},{"f":"ما مظاهر تقيح الجلد (Pyoderma) عند الوليد وعلاجه؟","b":"عادة منشؤه عنقودي (Staphylococcal)، يُرى فوق الفروة والرقبة والمغبن والظهر والإبط، وقد ينتشر موضعيًا ليشكل خراجًا أو التهاب نسيج خلوي أو فقاع الوليد (Pemphigus neonatorum) أو دمويًا مسببًا إنتانًا وليديًا أو التهاب عظم. العلاج: ثقب البثور غير المعقدة للتلوين والزرع ثم مضاد حيوي موضعي (موبيروسين) 2-3 مرات يوميًا؛ والصادات الجهازية فقط في الآفات الواسعة أو التهاب النسيج الخلوي/الخراج أو الاشتباه بالإنتان."}]},{"t":"التغذية","cards":[{"f":"ما اللبأ (Colostrum) وما فوائده؟","b":"حليب سميك أصفر لزج يُفرز خلال أول 72 ساعة من العمر. رغم كمياته القليلة يكفي حاجة الوليد؛ غني بالبروتينات والعوامل المضادة للعدوى (Anti-infective factors)، ويسهّل نضج السبيل الهضمي. يليه الحليب الانتقالي (3-14 يومًا) ثم الحليب الناضج (من اليوم 15)."},{"f":"ما الفروق التركيبية بين حليب الأم وحليب البقر؟","b":"حليب الأم مقابل البقر (لكل 100 مل): بروتين 1.1 مقابل 3.3 غم لكن نوعيته أعلى — مصل:كازين (Whey:Casein) 75:25 مقابل 22:78؛ أحماض أمينية أساسية كافية مقابل ناقصة؛ لاكتوز 6.5% مقابل 4.5%؛ إنزيم الليباز موجود مقابل غائب؛ حمل ذوابي (Solute load) أقل: صوديوم 0.2 مقابل 0.7 ملغ. الطاقة متقاربة (67 مقابل 70 سعرة)."},{"f":"ما الفرق بين الحليب الأمامي (Fore milk) والخلفي (Hind milk)؟","b":"الحليب الأمامي يتدفق في بداية كل رضعة وهو مائي نسبيًا يروي عطش الطفل، قليل الدهن وغني بالسكريات والفيتامينات والمعادن. الحليب الخلفي يُفرز في الجزء الأخير من الرضعة وهو أسمك وأغنى بالدهن والطاقة."},{"f":"ما تصنيف سوء التغذية الحاد الوخيم (SAM) حسب WHO؟","b":"الوزن للطول (WFH) أقل من -3 انحراف معياري أو MUAC أقل من 11.5 سم أو وجود وذمة متناظرة. كواشيوركور (Kwashiorkor): وذمة موجودة. ماراسموس (Marasmus): وزن للعمر أقل من 60% دون وذمة. كل حالات الوذمة تُعتبر سوء تغذية وخيمًا. سوء التغذية الحاد الوخيم مع اختلاطات (علامة خطر عامة، ذات رئة، إسهال مع تجفاف، ضعف شهية) يحتاج عناية مشفوية."},{"f":"ما المظاهر السريرية والمخبرية للكساح الغذائي (Nutritional rickets)؟","b":"يظهر بعمر 6 أشهر-سنتين بتشوهات عظمية وضعف توتر الأربطة/العضلات. جمجمة: تلين القحف (Craniotabes)، تأخر إغلاق اليافوخ الأمامي، تأخر التسنين. صدر: مسبحة كساحية (Rachitic rosary)، ثلم هاريسون (Harrison sulcus). أطراف: توسع الرسغ/الكاحل، تقوس الساقين (Bow legs) أو الركبة الروحاء (Knock knee)، كسور الغصن الأخضر. مخبريًا: أول تغير ارتفاع الفوسفاتاز القلوية (Alkaline phosphatase)، ثم انخفاض الفوسفور؛ والكالسيوم طبيعي عادة بارتفاع PTH."},{"f":"ما الاختلاطات المبكرة لسوء التغذية البروتيني-الطاقي (PEM)؟","b":"التهابات: شائعة (ARI، إسهال، سل، ديدان)، وخيمة (إنتان بجراثيم سلبية الغرام، صدمة إنتانية، DIC)، انتهازية (داء المبيضات). استقلابية: نقص سكر الدم (Hypoglycemia)، نقص كالسيوم الدم، نقص مغنيزيوم الدم. سوائل وشوارد: تجفاف، نقص بوتاسيوم الدم، فرط صوديوم الدم. وانخفاض حرارة الجسم (Hypothermia)."},{"f":"ما فوائد الرضاعة الطبيعية التغذوية الرئيسية؟","b":"حليب الأم سهل الهضم ويحوي كل المغذيات الأساسية بالكمية والنوعية المناسبة لحاجة الرضيع. الطاقة مشتقة أساسًا من كربوهيدرات سهلة الهضم (اللاكتوز). البروتين أقل كمية من حليب البقر لكنه نوعيًا متفوق (مصل:كازين 75:25). الدهون من نوع PUFA مع أحماض دهنية أساسية عالية وإنزيم ليباز موجود."}]},{"t":"أخطاء الاستقلاب الوراثية","cards":[{"f":"ما بيلة الفينيل كيتون (Phenylketonuria - PKU) سريريًا وعلاجيًا؟","b":"أشيع خطأ استقلابي وراثي: عوز أنزيم فينيل ألانين هيدروكسيلاز (الكلاسيكي) أو العامل المساعد تتراهيدروبيوبترين BH4 (الخبيث). يتراكم الفينيل ألانين في الدم والأنسجة ويتحول لحمض فينيل البيروفيك في البول. الأطفال طبيعيون عند الولادة ويظهرون بعمر 2-3 أشهر: تخلف عقلي مترقٍ، هياج واختلاجات وفرط توتر، بشرة فاتحة وشعر أشقر وعيون زرقاء وأحيانًا أكزيما (لعوز التيروزين الضروري للميلانين)، ورائحة عفنة (Mousy odor). العلاج: تقييد الفينيل ألانين الغذائي، وقد يفيد BH4 أو طلائع النواقل العصبية (L-dopa أو 5-HT)."},{"f":"ما الغالاكتوزيميا الكلاسيكية (Classical galactosemia)؟","b":"عوز أنزيم غالاكتوز-1-فوسفات يوريديل ترانسفيراز (GALT)، وراثة متنحية جسمية (Autosomal recessive) كالأنواع الثلاثة. يتراكم غالاكتوز-1-فوسفات ومستقلباته السامة للكبد والأعضاء الأخرى، مع غالاكتوزوريا (Galactosuria) ونقص سكر الدم — وتُسمى مجتمعة الغالاكتوزيميا."},{"f":"ما داء بول شراب القيقب (Maple syrup urine disease - MSUD)؟","b":"عيب نادر متنحٍ جسمي في نزع كربوكسيل الأحماض الأمينية متفرعة السلسلة (ليوسين/إيزوليوسين/فالين) بسبب عوز معقد أنزيمي: برانشد-تشين-كيتو أسيد ديهيدروجيناز (Branched-chain-ketoacid dehydrogenase). تراكم المستقلبات الوسيطة في سوائل الجسم وإطراحها في البول يؤدي لحماض استقلابي ومظاهر عصبية ورائحة نموذجية كشراب القيقب في البول."}]}]},{"s":"جراحة الأطفال","topics":[{"t":"التشوهات الخلقية في الجهاز الهضمي والحجاب الحاجز","cards":[{"f":"ما أشيع نمط لرتق المريء (Esophageal atresia) حسب تصنيف غروس (Gross)؟","b":"النمط C: رتق المريء مع ناسور رغامي مريئي بعيد (distal TEF) — يشكل نحو 85% من الحالات. النمط A (رتق خالص بلا ناسور) ~7%، والنوع H بلا رتق (Gross E) ~4%، والنمط B (ناسور قريب) ~2%."},{"f":"وليد مع فرط سيلان اللعاب (drooling) واختناق مع أول رضعة وتعذّر تمرير الأنبوب الأنفي المعدي — ما التشخيص والتدبير الأولي؟","b":"رتق المريء (Esophageal atresia): الأنبوب يلتف في الجيب المريئي العلوي ولا يصل المعدة. التدبير: وضعية الرأس مرفوعًا + أنبوب ريبوغل (Replogle) بشفط مستمر في المريء العلوي + نقل لمركز جراحة أطفال."},{"f":"في رتق المريء: ماذا يعني غياب الهواء في البطن (gasless abdomen) على الصورة الشعاعية؟","b":"رتق مريء خالص بلا ناسور بعيد (Gross type A) — لا يمر الهواء من الرغامى إلى المعدة. أما وجود غاز في البطن فيشير إلى ناسور بعيد يمرر الهواء إلى المعدة والأمعاء."},{"f":"ما أشيع الشذوذات المرافقة لرتق المريء؟ وما المتلازمة الأشهر؟","b":"متلازمة VACTERL: شذوذات فقارية (Vertebral)، شرجية مستقيمية (Anorectal)، قلبية (Cardiac)، رغامية مريئية (TE)، كلوية (Renal)، طرفية (Limb). أشيعها القلبية (13–34%) ثم الفقارية (6–21%) والطرفية والشرجية والكلوية."},{"f":"ما العلامة الشعاعية المميزة لرتق العفج (Duodenal atresia)؟","b":"علامة الفقاعة المزدوجة (double-bubble sign): معدة وفقاعة عفجية منتفختان بلا هواء معوي بعيد. السريريًا: إقياء صفراوي خلال الساعات الأولى من الولادة (85% من الانسدادات بعد أمبولة فاتر)."},{"f":"ما أشيع الارتباطات المرافقة لرتق العفج؟","b":"تثلث الصبغي 21 (28–45% من المرضى)، بنكرياس حلقي (~30%)، شذوذات قلبية (11–66%)، سوء دوران (20–30%). العلاج الجراحي: مفاغرة عفجية عفجية (duodenoduodenostomy)."},{"f":"وليد بإقياء غير صفراوي مقابل إقياء صفراوي — ما الدلالة التشريحية لموقع الانسداد؟","b":"غير الصفراوي = انسداد قبل أمبولة فاتر (البواب أو العفج القريب)؛ الصفراوي = انسداد بعدها (رتق عفج بعيد، سوء دوران مع انفتال). ملاحظة: ~10% من رتق العفج قبل الأمبولة فيكون الإقياء غير صفراوي."},{"f":"ما الأساس الجنيني لسوء الدوران المعوي (Malrotation)؟","b":"فشل الدوران الكامل 270° عكس عقارب الساعة للمعي المتوسط حول الشريان المساريقي العلوي؛ تبقى الوصلة العفجية الصائمية يمينًا والأعور عاليًا مع أشرطة لاد (Ladd bands) تعبر العفج — قاعدة مساريقية ضيقة عرضة للانفتال."},{"f":"وليد بإقياء صفراوي مفاجئ — ما الإسعاف الجراحي المشتبه؟ وما العملية؟","b":"انفتال المعي المتوسط (midgut volvulus) على سوء دوران — إسعاف جراحي عاجل لخطر إقفار الأمعاء. العملية: إجراء لاد (Ladd procedure): فك الانفتال وقطع أشرطة لاد وتوسيع قاعدة المساريق."},{"f":"ما الاستقصاء الذهبي لنفي سوء الدوران؟ وما معايير الطبيعي؟","b":"الوجبة الباريتية العلوية (upper GI series). الطبيعي يتطلب: عفجًا خلف الصفاق يعبر الخط الناصف، ووصلة عفجية صائمية (DJJ) ترتفع لمستوى البواب يسار العمود الفقري."},{"f":"ما أشيع أنماط التشوهات الشرجية المستقيمية (Anorectal malformations) حسب الجنس؟","b":"عند الذكور: ناسور مستقيمي إحليلي (rectourethral fistula)؛ عند الإناث: ناسور دهليزي (rectovestibular fistula). المذرق (cloaca) عند الإناث: فتحة واحدة مشتركة للسبيل البولي والبرازي والتناسلي."},{"f":"ما نسبة حدوث التشوهات الشرجية المستقيمية؟ وما ارتباطاتها الوراثية؟","b":"1 من كل 4000–5000 ولادة، أشيع قليلًا عند الذكور. تترافق مع VACTERL وتثلث 21؛ ومن المتلازمات الوراثية: كورارينو (Currarino) وتاونز–بروكس (Townes-Brocks) وباليستر–هول (Pallister-Hall)."},{"f":"ما أشيع أنواع الفتق الحجابي الخلقي (CDH)؟ وما الثلاثية الفيزيولوجية المرضية؟","b":"فتق بوخدالك (Bochdalek) الخلفي الوحشي: 84% أيسر و14% أيمن. الثلاثية: نقص تنسج الرئة (pulmonary hypoplasia) + ارتفاع الضغط الرئوي + خلل وظيفة القلب — والبقاء 65–80%."},{"f":"ما العلامات السريرية والشعاعية للفتق الحجابي الخلقي عند الوليد؟","b":"بطن زورقي (scaphoid abdomen)، أصوات أمعاء مسموعة في الصدر مع نقص أصوات التنفس، انزياح نقطة الذروة القلبية. الصورة: عرى معوية في نصف الصدر + انزياح المنصف للجهة المقابلة + بطن خالٍ من الغاز."},{"f":"ما مميزات فتق مورغاني (Morgagni hernia)؟","b":"فتق حجابي أمامي يشكل 2–5% من الفتوق الحجابية الخلقية؛ عالي الارتباط بالشذوذات القلبية وتثلث الصبغي 21؛ غالبًا لا عرضي ويُكتشف صدفة، وقد يترافق مع خماسية كانتريل (pentalogy of Cantrell)."}]},{"t":"الانسدادات المعوية وآفات جدار البطن والمنطقة المغبنية","cards":[{"f":"رضيع 6 أشهر بنوب ألم بطني مغصي متقطع مع سحب الركب للبطن وبراز هلامي دموي — ما التشخيص؟","b":"الانغلاف المعوي (Intussusception): أشيع سبب لانسداد الأمعاء عند الرضع والأطفال الصغار؛ الذروة 4–9 أشهر وثلثا الحالات ذكور. البراز الهلامي (currant jelly) علامة متأخرة تدل على إقفار مخاطي — لا تُنتظر للتشخيص."},{"f":"ما العلامة الإيكوغرافية المميزة للانغلاف المعوي؟","b":"علامة الهدف/الدونات (target/doughnut sign) بالمقطع العرضي: حلقات متناوبة الصدى لجدار الأمعاء والشحم المساريقي داخل المنغلَف؛ وبالمقطع الطولي علامة الكلية الكاذبة (pseudokidney sign). الإيكو لا إشعاع فيه ويكشف نقطة القيادة."},{"f":"ما الخط الأول لعلاج الانغلاف؟ وما موانعه؟","b":"الردّ بالحقنة الهوائية (pneumatic enema) تحت التنظير — نسبة النجاح ~85%؛ الضغط الأقصى الآمن 80 مم زئبق للرضع الصغار و110–120 للأكبر. الموانع: الانثقاب (هواء حر)، التهاب الصفاق، الصدمة المقاومة للإنعاش."},{"f":"ما أشيع نقطة قيادة (lead point) مرضية للانغلاف؟ وما نسبة النكس؟","b":"رتج ميكل (Meckel diverticulum) أشيع نقطة قيادة؛ وتزداد النقاط القيادية المرضية (زوائد، أورام لمفاوية) مع تقدم العمر. النكس بعد الرد غير الجراحي ~10% ومعظمه خلال 6 أشهر."},{"f":"ما علامة دانس (Dance sign) في الانغلاف المعوي؟","b":"الربع السفلي الأيمن يبدو فارغًا/مسطحًا بالجس لأن الكتلة المنغلقة انجذبت رأسيًا، مع كتلة سجقية الشكل (sausage-shaped mass) مجسوسة في البطن أثناء نوب الألم."},{"f":"وليد لم يخرج العقي خلال 24–48 ساعة مع انتفاخ بطني — ما التشخيص وعلاقته بالتليف الكيسي؟","b":"العلوص العقي (Meconium ileus): عقي لزج يسد اللفائفي الانتهائي، ويُشاهد في سياق التليف الكيسي (cystic fibrosis). العلاج الأول: حقنة الغاستروغرافين (Gastrografin enema) — تشخيصية وعلاجية معًا."},{"f":"ما العلامتان الشعاعيتان المميزتان لالتهاب الأمعاء والقولون الناخر (NEC)؟","b":"هواء جدار الأمعاء (pneumatosis intestinalis) وهواء الوريد البابي (portal venous gas)؛ مع هواء حر داخل الصفاق عند الانثقاب. يصيب الخدج أساسًا (خداج + تغذية معوية + خلل الميكروبيوم)."},{"f":"ما أساس علاج التهاب الأمعاء والقولون الناخر؟ ومتى تُستطب الجراحة؟","b":"داعم: إيقاف التغذية المعوية + سوائل وريدية + صادات واسعة الطيف. الجراحة (33–50% من الحالات) عند: انثقاب الأمعاء، نخر مشتبه، أو فشل العلاج الداعم — استئصال القطعة الميتة مع فغرة."},{"f":"ما سبب الفتق الإربي عند الأطفال؟ وما جهته الأشيع؟","b":"بقاء الناتئ الغمدي (processus vaginalis) سالكًا — الفتق الإربي عند الأطفال غير مباشر دائمًا. أيمن 50–60%، أيسر 30%، ثنائي الجانب 12% (أعلى عند الخدج والإناث)."},{"f":"ما العلاقة بين الخداج والفتق الإربي؟ وما نسبة الانحباس؟","b":"الخداج أشيع ارتباط (9–30% عند الخدج) بسبب اضطراب نزول الخصية. الانحباس 4–12% من الحالات ويرتفع إلى ~30% عند الرضع — لذا يُصلَّح الفتق الإربي عند الأطفال جراحيًا دون انتظار."},{"f":"ما الفرق بين انشقاق البطن (Gastroschisis) والقيلة السرية (Omphalocele)؟","b":"انشقاق البطن: عيب يمين السرة الطبيعية، بلا كيس، عرى حرة في السائل الأمنيوسي، شذوذات مرافقة نادرة (<10%). القيلة السرية: عيب في السرة نفسها مع كيس، شذوذات مرافقة شائعة (50% — قلبية وصبغية)."},{"f":"وليد بانشقاق بطن — ما أشيع شذوذ مرافق؟ وما التدبير الأولي؟","b":"رتق الأمعاء (7–28% من الحالات) أشيع شذوذ مرافق. التدبير: تغطية الأحشاء بشاش دافئ مبلل + كيس بلاستيكي، أنبوب أنفي معدي، سوائل وريدية، ثم الرد الجراحي العاجل."},{"f":"ما السير الطبيعي للفتق السري (Umbilical hernia) عند الأطفال؟","b":"يغلق عفويًا في ~90% قبل عمر 4 سنوات؛ المراقبة آمنة حتى 4–5 سنوات. تُدرس الجراحة بعد هذا العمر أو لأسباب تجميلية؛ الاختلاطات (الانحباس) نادرة (0–7.4%)."},{"f":"ما الصورة السريرية الكلاسيكية لالتهاب الزائدة الحاد عند الأطفال؟","b":"ألم حول السرة يهاجر إلى الربع السفلي الأيمن خلال 24 ساعة (نقطة ماكبرني / McBurney) + حمى وقهم وغثيان وإقياء. الألم البؤري في الربع السفلي الأيمن هو أدق منبئ منفرد."},{"f":"ما فيزيولوجية التهاب الزائدة؟ ومن الأكثر عرضة للانثقاب؟","b":"انسداد اللمعة (براز أو فرط تنسج لمفاوي) ← ارتفاع الضغط داخل اللمعة ← إقفار مخاطي ← غزو جرثومي لجدار الزائدة. الانثقاب أشيع تحت عمر 5 سنوات ويصل ~90% تحت عمر السنة لتأخر التشخيص."}]},{"t":"أورام الأطفال الجراحية ورتق الطرق الصفراوية","cards":[{"f":"ما أشيع ورم صلب خارج القحف عند الأطفال؟ وما منشؤه وأشيع مواقعه؟","b":"الورم الأرومي العصبي (Neuroblastoma): أشيع خباثة عند الرضع؛ ورم جنيني من العرف العصبي (neural crest). 75% في البطن (الكظر أشيع موقع) و20% في المنصف الخلفي. أكثر من 60% لديهم نقائل عند التشخيص (نقي العظم والعقد والعظم القشري)."},{"f":"ما أشيع ورم كلوي عند الأطفال؟ وما مميزاته السريرية والوراثية؟","b":"ورم ويلمز (Wilms tumor): متوسط العمر عند التشخيص 36 شهرًا؛ كتلة بطنية غير مؤلمة تُكتشف عرضًا. شعاعيًا: لا يعبر الخط الناصف ولا يغلف الأوعية (عكس الأرومي العصبي). الارتباطات: WAGR (حذف 11p13 — خطر 50%) ودينيس–دراش (طفرة WT1 — خطر 95%)."},{"f":"وليد بيرقان ركودي مستمر وبراز طيني (acholic) — ما التشخيص والعلاج والإنذار الزمني؟","b":"رتق الطرق الصفراوية (Biliary atresia): انسداد القنوات الصفراوية خارج الكبد (النمط III أشيع). العلاج: مفاغرة كاساي الكبدية المعوية (Kasai portoenterostomy) — تصريف فعال للصفراء في ~50% إذا أُجريت قبل عمر شهرين مقابل 7% فقط بعد 4 أشهر؛ وهو أشيع استطباب لزرع الكبد عند الأطفال."}]},{"t":"التهاب البنكرياس عند الاطفال","cards":[{"f":"ما أشيع أسباب التهاب البنكرياس الحاد (Acute pancreatitis) عند الأطفال؟","b":"مجهول السبب أشيعها؛ ثم: الرض (رضّ مقود الدراجة على العمود الفقري)، الحصيات الصفراوية، الكيسة الصفراوية (choledochal cyst)، الأدوية (asparaginase وحمض الفالبرويك)، الأخماج (كوكساكي، روتا). الوقوع 3.6–13.2 لكل 100,000 طفل."},{"f":"ما أساس علاج التهاب البنكرياس الحاد عند الأطفال؟","b":"داعم: تسكين الألم + إنعاش وريدي قوي (هدف إدرار بولي 2 مل/كغ/ساعة) + راحة البنكرياس + مراقبة الاختلاطات. تُستخدم مضادات H2 لتقليل تحفيز الخلايا المفرزة للسيكريتين في العفج."},{"f":"ما دور الاستقصاءات الشعاعية في التهاب البنكرياس؟ وما علامة كولن (Cullen)؟","b":"الإيكو أولًا (يكشف الحصيات والكيسة الصفراوية والكيسة الكاذبة)؛ الطبقي لاختلاطات الحالات الشديدة (نخر، كيسة كاذبة، تجمعات سائلة)؛ والـMRCP الخيار الأول لتشريح القناة البنكرياسية في الناكس أو مجهول السبب. علامة كولن: كدمة حول السرة في التهاب البنكرياس النزفي."}]},{"t":"رتج ميكل","cards":[{"f":"ما قاعدة الاثنينات (rule of 2s) في رتج ميكل (Meckel diverticulum)؟","b":"2% من السكان، نسبة ذكور:إناث 2:1، يُكتشف غالبًا قبل عمر سنتين، على بعد 2 قدم (60 سم) من الصمام اللفائفي الأعوري، طوله 2 إنش وقطره 2 سم، ويحوي نوعين من المخاطية المنتبذة. وهو رتج حقيقي (كل طبقات الجدار) من بقايا القناة المحّية المساريقية."},{"f":"ما التظاهرات السريرية الثلاثة الأشيع لرتج ميكل عند الأطفال؟","b":"النزف (30–56%: مخاطية معدية منتبذة تسبب تقرحًا ونزفًا مستقيميًا غير مؤلم)، الانسداد (14–42%: انغلاف يكون الرتج نقطة قيادته أو انفتال حول الحبل الليفي)، الالتهاب (6–14%: يحاكي التهاب الزائدة الحاد)."},{"f":"كيف يُشخَّص رتج ميكل النازف؟ وما العلاج الجراحي الأمثل؟","b":"مسح التكنيشيوم-99m (Meckel scan): يكشف المخاطية المعدية المنتبذة (لا الرتج نفسه)؛ الحساسية 89–100% عند الأطفال النازفين والنوعية >95%. العلاج: استئصال قطعي من اللفائفي مع مفاغرة — لا استئصال الرتج وحده — لأن المخاطية المنتبذة قد تمتد إلى قاعدته."}]},{"t":"أسئلة متفرقة","cards":[{"f":"مراهق بألم صفني مفاجئ شديد مع غياب المنعكس المشمري (cremasteric reflex) — ما التشخيص ونافذة الإنقاذ؟","b":"التواء الخصية (testicular torsion): التواء الحبل المنوي يهدد التروية؛ الدوبلر الملون يُظهر غياب الجريان. نافذة الإنقاذ 4–8 ساعات؛ نسبة إنقاذ الخصية <6 ساعات 85–97% وتتدنى كثيرًا بعد 24 ساعة (<10%). إسعاف جراحي مع تثبيت الخصية المقابلة."},{"f":"ما مخاطر الخصية الهاجرة (cryptorchidism)؟ وما مبدأ تدبيرها؟","b":"3% عند مكتملي الحمل و33–45% عند الخدج؛ معظمها يهبط خلال 6–12 شهرًا والهبوط بعد السنة مستبعد. المخاطر: العقم والخباثة. التدبير: تثبيت الخصية الجراحي (orchiopexy) المبكر دون انتظار بعد السنة؛ التصوير نادر الفائدة وقد يؤخر الإحالة الجراحية."},{"f":"ما ثالوث الإحليل التحتي (hypospadias)؟","b":"فتحة إحليلية على السطح البطني للقضيب + انحناء بطني (chordee) + نقص الجلد البطني (قلنسوة ظهرية / dorsal hood). ثاني أشيع شذوذ بولي تناسلي عند الذكور بعد الخصية الهاجرة (1 من 250 ذكرًا)؛ والشكل الشديد مع خصية هاجرة يستدعي نفي اضطرابات التمايز الجنسي."}]}]},{"s":"الجراحة التجميلية","topics":[{"t":"الحروق","cards":[{"f":"صيغة باركلاند (Parkland) لتعويض السوائل في الحروق؟","b":"4 مل × الوزن (كغ) × نسبة الحرق % من رينغر اللاكتات (Lactated Ringer's) خلال 24 ساعة — نصف الكمية في أول 8 ساعات والباقي خلال 16 ساعة؛ تُحسب من وقت الحرق لا من وقت القبول، والهدف نتاج بول ≥0.5 مل/كغ/ساعة."},{"f":"عتبة بدء الإنعاش الوريدي بالسوائل عند مريض الحروق؟","b":"حروق تتجاوز 20% من سطح الجسم عند البالغين (و15% عند الأطفال) — يُعاير التسريب للحفاظ على ضغط شرياني متوسط (MAP) فوق 60 مم زئبق مع نتاج بول كافٍ."},{"f":"مخطط لوند وبراودر (Lund and Browder) في الحروق: ما هو وما أصله؟","b":"المعيار الموثق لتقدير مساحة الحرق وتوثيق عمقه بالتظليل مع تقسيم دقيق لمناطق الجسم؛ وُضع عام 1942 عقب كارثة حريق ملهى ليلي في بوسطن (Cocoanut Grove)."},{"f":"مناطق جاكسون (Jackson's zones) الثلاث في الحرق؟","b":"منطقة التخثر (Coagulation) في المركز — نسيج نخر يحتاج استئصالًا وتطعيمًا؛ منطقة الركودة (Stasis) إقفارية قد تتعمق مع الانتان أو سوء التروية؛ ومنطقة الاحتقان (Hyperemia) المحيطية."},{"f":"سلفاديازين الفضة (Silver sulfadiazine) في الحروق: وقاية أم علاج؟","b":"الأشيع استعمالًا موضعيًا — دوره وقائي ضد انتان جرح الحرق لا علاجًا لانتان قائم؛ رخيص، مهدئ، وامتصاصه الجهازي ضئيل."},{"f":"أسيتات المافينيد (Mafenide acetate): ما ميزته وما خطره؟","b":"فعال حتى بوجود الخشارة (Eschar) — لكنه مثبط لأنزيم الكربونيك أنهيدراز (Carbonic anhydrase) فيسبب حماضًا استقلابيًا، وتطبيقه مؤلم على الحروق جزئية السماكة."},{"f":"الحروق الكيماوية: الحمض أم القلوي أعمق؟ وما خصوصية حمض الهيدروفلوريك؟","b":"القلويات أعمق (نخر تميّعي Liquefactive) مقابل نخر تخثري (Coagulative) للأحماض؛ حمض الهيدروفلوريك (Hydrofluoric acid) استثناء يسبب تميّعًا أيضًا مع نقص كالسيوم الدم — علاجه غلوكونات الكالسيوم، والغسيل بالماء 30 دقيقة على الأقل."},{"f":"حرق كهربائي: متى قد يغني تخطيط القلب الطبيعي عن القبول؟ وما اختلاطاه المتأخران؟","b":"تخطيط أساسي (ECG) للجميع؛ الطبيعي في إصابة منخفضة التوتر (<1000 فولط) قد يغني عن القبول. التوتر العالي: خثرة عضلية تستدعي بضع اللفافة (Fasciotomy) عند الشك المتوسط، ومتأخرًا: ساد (Cataract) وأعراض عصبية — تستدعي استشارة عينية وعصبية."},{"f":"بضع الخشارة (Escharotomy): متى يُجرى؟","b":"حرق محيطي كامل السماكة حول الصدر يمنع تمدده — شقوق طولية للسماح بالتوسع؛ وحول الطرف يعمل كعاصبة (Tourniquet) مهددًا الطرف بالإقفار ما لم يُبضع."},{"f":"إلى أي مدى ترتفع الاستجابة فرط الاستقلابية (Hypermetabolic) بعد الحرق الواسع؟","b":"حتى 200% فوق معدل الاستقلاب الأساسي مع هدم بروتينات العضلات؛ التغذية المعوية المبكرة (لحروق >20%) آمنة — تقلل فقد الكتلة النحيلة وتقصر الإقامة في العناية وتخفض انتان الجروح."},{"f":"الصادات الوقائية في الحروق؟","b":"ممنوعة — لا تُعطى صادات وقائية إطلاقًا عدا لقاح الكزاز (Tetanus vaccination)."},{"f":"المعيار الذهبي لتشخيص أذية الاستنشاق (Inhalation injury)؟","b":"تنظير القصبات الليفي (Fiberoptic bronchoscopy)؛ ومن العلامات المنذرة: جهد تنفسي متزايد، صرير (Stridor)، وبحة صوت."},{"f":"الضمادات الفضية (Silver dressings) في الحروق تغطي أي جراثيم؟","b":"فعالية مضادة للبكتيريا تشمل الزائفة الزنجارية (Pseudomonas aeruginosa) والمكورات العنقودية الذهبية المقاومة للميثيسيلين (MRSA)."},{"f":"الاستئصال والتطعيم المبكر في الحروق العميقة: ما أثره؟","b":"الاستئصال المبكر والتطعيم للحروق كاملة السماكة والعميقة جزئية السماكة يحسّن النتائج ويقلل الانتان."}]},{"t":"الجراحة الترميمية والتجميلية","cards":[{"f":"تعريف الطعم الجلدي (Skin graft) وأنواع النقل حسب المصدر؟","b":"قطعة أدمة وبشرة تُفصل كليًا عن موضعها الأصلي (الموضع المعطي) وتُثبت في السرير المستقبل فتنمو لها تروية جديدة؛ ذاتي (Autograft)، متماثل (Isograft)، خيفي (Allograft)، وأجنبي (Xenograft)."},{"f":"طعم وولف (Wolfe graft) كامل السماكة: ما محتواه وأشيع مواقعه المعطية؟","b":"بشرة + كامل سماكة الأدمة مع الملحقات (كالشعر)؛ يُؤخذ بالاستئصال الإهليجي من مناطق الجلد المترهل: خلف الأذن، فوق الترقوة، أمام الأذن، المغبن، أو أعلى الذراع الأنسي — والموضع المعطي يُخاط إغلاقًا."},{"f":"طعم تيرش (Thiersch graft) جزئي السماكة: من أين يُؤخذ ومتى يُفحص؟","b":"بشرة + جزء متغير من الأدمة، غالبًا من الفخذ (وفير وسهل الوصول)؛ يُثقب أو يُشبّك (Meshed) للتوسع والتموضع على الجرح، يُفحص بعد 5 أيام، والعيب المعطي يلتئم بإعادة التبشّر من ملحقات الجلد."},{"f":"مراحل التحام الطعم الجلدي (Graft take)؟","b":"الالتصاق (Adherence) فوريًا برابطة فيبرين؛ التشرب المصلي (Serum imbibition) في اليوم 2-4؛ إعادة التوعية (Revascularization) بعد اليوم 4 — إما بتدفق مباشر لأوعية الطعم (Inoculation) أو نمو أوعية جديدة."},{"f":"أسباب فشل الطعم الجلدي؟","b":"القص (Shearing) المحرك للطعم، انتان السرير أو الطعم، انفصاله بورم دموي أو مصلي، سرير غير كافٍ (عظم قشري عارٍ أو وتر بلا غلاف)، وضغط ضماد مفرط."},{"f":"فرّق: الشريحة عشوائية النمط (Random pattern) مقابل المحورية (Axial)؟","b":"العشوائية بلا وعاء مغذٍ مهيمن (تعتمد الضفيرة تحت الأدمة)، والمحورية ذات وعاء مغذٍ مهيمن مسمى — وهو أساس تصنيف الشرائح حسب ترويتها."},{"f":"رأب Z‏ (Z-plasty): ماذا يفعل؟","b":"شريحتان مثلثتا التحويل متداخلتان؛ تُطيل الندبة وتعيد توجيهها على خطوط توتر الجلد المرتخي وتكسر خطها لتصبح أقل وضوحًا — تُستخدم لندبات التقلص."},{"f":"التوسع النسيجي (Tissue expansion): كيف يعمل؟","b":"بالون سيليكون تحت الجلد يُنفخ بالمحلول الملحي على فترات منتظمة لتوليد جلد ونسيج رخو إضافي لترميم العيوب المجاورة — يُستخدم مثلًا لعلاج الصلع بعد الحروق."},{"f":"العلاج بالعلق (Leech therapy) في الترميم: ما استطبابه الأساسي؟","b":"الاحتقان الوريدي للشرائح (الشريحة الداكنة) لتحسين التصريف الوريدي؛ لعاب العلقة الطبية يحوي هيرودين (Hirudin مضاد تخثر)، هيالورونيداز، وهيستامين موسع للأوعية."}]},{"t":"أورام الجلد","cards":[{"f":"الشكل السريري النموذجي لسرطان الخلايا القاعدية (BCC)؟","b":"قرحة جلدية بحافة لؤلؤية (Pearly edge) وتوسع شعيرات (Telangiectasia)؛ يصيب 20-40% من ذوي البشرة الفاتحة، ونادر النقائل جدًا لكنه قد يغزو عميقًا فيكون مميتًا."},{"f":"معايير ABCDE للاشتباه بالميلانوما (Melanoma)؟","b":"عدم التناظر (Asymmetry)، عدم انتظام الحدود (Border)، تغير اللون أو تفاوته (Colour)، القطر >6 مم (Diameter)، الارتفاع أو الحكة أو النزف (Elevation) — في شامة سابقة متغيرة أو شامة حديثة."},{"f":"الميلانوما: على ماذا تعتمد هوامش الاستئصال والإنذار؟","b":"هوامش الاستئصال الواسع حسب سماكة بريسلو (Breslow): 1 سم لأقل من 1 مم، 2 سم لـ1-2 مم، 2-3 سم لأكثر من 2 مم؛ والإنذار يعتمد السماكة وتقرح الورم وإصابة العقد اللمفاوية — مع خزعة العقدة الخافرة (Sentinel) للتدريج."},{"f":"الميلانوما العدسية الطرفية (Acral lentiginous): أين تظهر ولدى من؟","b":"الأشيع لدى ذوي البشرة الداكنة (حتى 36% من ميلانومات السود مقابل 2% لدى البيض)؛ تظهر على الراحتين والأخمصين وحول الظفر كلطخة بنية-سوداء غير متناظرة، وتُشخّص خطأً كثؤلول في ثلث الحالات."},{"f":"جراحة موس المجهرية (Mohs micrographic surgery): متى تُفضل؟","b":"الخيار المفضل للآفات الوجهية — استئصال طبقي مع فحص مجهري فوري للحواف لتوفير أكبر قدر من النسيج السليم (مقتصدة للنسيج)."}]}]},{"s":"التوليد","topics":[{"t":"القصة المرضية والفحص السريري","cards":[{"f":"ما العلامات المؤكدة (الإيجابية Positive) للحمل؟","b":"سماع دقات قلب الجنين (Positive sign)، رؤية الجنين/كيس الحمل بالأمواج فوق الصوتية، جسّ أجزاء الجنين عبر البطن."},{"f":"ما أهم معيار سريري لتقدير عمر الحمل في الأسابيع الأولى؟","b":"أول يوم من آخر طمث (LMP — Last Menstrual Period)؛ هو المرجع الأساسي قبل الاعتماد على الإيكو."},{"f":"ما قاعدة نيغل (Naegele) لحساب موعد الولادة المتوقع EDD؟","b":"أول يوم من آخر طمث + 7 أيام − 3 أشهر + سنة واحدة (يُفترض دورة 28 يوماً). مثال: LMP في 1 كانون الثاني ← EDD في 8 تشرين الأول."},{"f":"ما علامة هيغار (Hegar sign)؟ وما تصنيفها؟","b":"ليونة برزخ الرحم بالجسّ (Uterine isthmus) بين الأسبوعين 6-8؛ من العلامات المحتملة (Probable) للحمل."},{"f":"ما العلامات المحتملة (Probable) للحمل؟","b":"علامة هيغار (ليونة البرزخ)، علامة تشادويك (Chadwick — ازرقاق المهبل وعنق الرحم)، علامة غودل (Goodell — ليونة عنق الرحم)، اختبار الحمل الإيجابي، تضخم الرحم."},{"f":"ماذا يعني وصول قعر الرحم (Fundal height) إلى مستوى ارتفاق العانة؟ وإلى مستوى السرة؟","b":"ارتفاق العانة ≈ 12 أسبوعاً (يُصبح الرحم عضواً بطنياً ويُسمع قلب الجنين بالدوبلر)؛ مستوى السرة ≈ 20 أسبوعاً."},{"f":"في فحص الحوض: متى يُمنع استخدام المادة المزلّقة؟","b":"عند أخذ لطاخة عنق الرحم (Pap smear) — المزلّق يشوّه العينة الخلوية؛ تُؤخذ اللطاخة أولاً ثم يُستخدم المزلّق لبقية الفحص."},{"f":"لماذا سُمّي الحمل الكاذب (Pseudocyesis) بهذا الاسم؟","b":"لحدوث انقطاع الطمث فعلاً مع أعراض حمل (غثيان، تضخم بطن) دون وجود جنين — أي أن انقطاع الطمث يحدث فيه حقيقةً."}]},{"t":"الإباضة والدورة الطمثية","cards":[{"f":"ما المحفّز المباشر للإباضة (Ovulation)؟","b":"الذروة المفاجئة للهرمون الملوتن LH (LH surge) في منتصف الدورة؛ الإستروجين العالي في منتصف الدورة يحفّز تحرير LH عابراً (تغذية راجعة إيجابية) ← تمزق الجريب وتحرير الخلية البيضية الثانوية."},{"f":"أي طوري الدورة المبيضية ثابت الطول؟ وما مدته؟","b":"الطور الأصفري (Luteal phase) ثابت = 14 يوماً (من الإباضة إلى أول يوم من الحيض التالي)؛ الطور الجريبي (Follicular) متغير الطول."},{"f":"كيف يُتحرّى عن حدوث الإباضة مخبرياً؟ ومتى؟","b":"بعيار البروجسترون في الدم في اليوم 21-23 من الدورة (ذروة الطور الأصفري) — ارتفاعه دليل على الإباضة؛ عياره في اليوم 14 غير مفيد (الإباضة لم تحدث بعد/تحدث حينها)."},{"f":"ما الدليل المؤكد لحدوث الإباضة؟","b":"حدوث الحمل — هو الدليل القاطع الوحيد؛ أما البروجسترون المرتفع والأعراض فأدلة غير مباشرة."},{"f":"ما العامل الذي يُبقي الجسم الأصفر (Corpus luteum) مستمراً بعد الإخصاب؟","b":"ارتفاع hCG الذي تفرزه الأرومة الغاذية — يُنقذ الجسم الأصفر فينقذه من الانحلال فيستمر بإفراز البروجسترون حتى تتولى المشيمة المهمة (~الأسبوع 8-10)."},{"f":"ما الهرمونات التي ينتجها المبيض؟ وأيها لا ينتجه؟","b":"ينتج: الإستروجين (إستراديول)، البروجسترون (الجسم الأصفر)، الأندروجينات (الخلايا القرابية)، الإنهيبين؛ لا ينتج الأوكسيتوسين (يُفرز من النخامية الخلفية)."},{"f":"هل يساهم الإستروجين في نمو الشعر عند الفتاة؟","b":"لا — نمو الشعر (الإبط والعانة) تابع للأندروجينات الكظرية والمبيضية (Adrenarche)؛ الإستروجين مسؤول عن نمو الثدي وتوزع الشحم الأنثوي ونمو الرحم."}]},{"t":"الإخصاب وتطور المشيمة","cards":[{"f":"متى يحدث الانغراس (التعشيش Implantation) بعد الإخصاب؟","b":"في اليوم 6-7 بعد الإخصاب (الكيسة الأريمية Blastocyst تلتصق في اليوم السادس؛ نافذة الانغراس 6-10 أيام)؛ يبدأ إفراز hCG قرب وقت الانغراس."},{"f":"ما الهرمون الذي يرتفع تركيزه ~1000 ضعف عند الحوامل؟","b":"الإستريول (Estriol — E3)؛ يُصنع في المشيمة من DHEA-S الجنيني الكظري — لذا يعكس سلامة الوحدة الجنينية-المشيمية."},{"f":"ما الهرمونات التي تفرزها المشيمة؟ وأيها لا تفرزه؟","b":"تفرز: hCG، البروجسترون، الإستروجين (إستريول)، اللاكتوجين المشيمي البشري hPL؛ لا تفرز: التستوستيرون ولا LH ولا FSH."},{"f":"ما الهرمون الأساسي المسؤول عن تثبيت الحمل في مراحله الأولى؟","b":"البروجسترون (Progesterone — «مؤيد للحمل pro-gestation»): يهيئ بطانة الرحم للانغراس (الطور الإفرازي: غدد ملتفة متوسعة + شرايين حلزونية) ويثبّط تقلصات الرحم."},{"f":"ما الغلوبولين المناعي الوحيد الذي يعبر المشيمة؟ وما أهميته؟","b":"IgG فقط («IgG يحيّي الجنين النامي») — يمنح الوليد مناعة منفعلة (Passive immunity) تبدأ بالاضمحلال بعد الولادة خلال أشهر."},{"f":"أي هرمون يشابه hCG في بنيته؟","b":"TSH (وكذلك LH وFSH) — تشترك كلها بالوحدة الفرعية ألفا (α-subunit) نفسها؛ لذا ارتفاع hCG الشديد (الحمل العنقودي) قد يسبب فرط درقية عابر."},{"f":"ما اتجاه جريان الدم في أوعية الحبل السري؟","b":"شريانا السرة (Umbilical arteries) يعيدان الدم غير المؤكسج من الجنين إلى المشيمة؛ الوريد السري الوحيد يجلب الدم المؤكسج من المشيمة إلى الجنين."},{"f":"ما خطر التوائم أحادية المشيمة (Monochorionic)؟","b":"تفاغرات شريانية-وريدية غير متوازنة في المشيمة المشتركة ← تدفق دم غير متكافئ بين التوأمين (متلازمة نقل الدم التوأمي TTTS)."},{"f":"ما مصير الخلية البيضية الثانوية إن لم يحدث إخصاب؟","b":"تتدهور خلال يوم واحد؛ الخلية البيضية الثانوية متوقفة في الطور الاستوائي الثاني (Metaphase II) حتى الإخصاب."}]},{"t":"المضغة والجنين","cards":[{"f":"ما الفترة الأكثر حساسية لحدوث التشوهات الجنينية (Teratogenicity)؟","b":"الأسابيع 3-8 من الحمل (فترة التعضّي Organogenesis — تشكّل الأعضاء)؛ قبلها «كل شيء أو لا شيء»، وبعدها التشوهات أقل حدة (اضطراب نمو/وظيفة)."},{"f":"ما طرق تشخيص الاضطرابات الجنينية قبل الولادة؟ وأيها ليس منها؟","b":"الأمواج فوق الصوتية، بزل السلى (Amniocentesis)، أخذ عينات الزغابات المشيمية (CVS)، تحليل دم الأم؛ التصوير الشعاعي الظليل (بالصباغ) ليس من طرق التشخيص الجنيني."},{"f":"متى يُجرى بزل السلى؟ ومتى CVS؟","b":"بزل السلى: الأسابيع 15-20 (الأمثل 16-18)؛ CVS: الأسابيع 10-13 (أبكر لكن خطر الإجهاض أعلى قليلاً وخطر تشوهات الأطراف إن أُجري مبكراً جداً)."},{"f":"ما أسباب قلة السائل السلوي (Oligohydramnios)؟","b":"قصور المشيمة (Placental insufficiency)، عدم تكون الكليتين الثنائي (Bilateral renal agenesis)، تمزق الأغشية المبكر PROM."},{"f":"ما أسباب كثرة السائل السلوي (Polyhydramnios)؟","b":"سكري الأم، انسدادات السبيل الهضمي الجنيني (رتق المري/الاثني عشر — الجنين لا يبتلع السائل)، الشذوذات الصبغية، الحمل المتعدد."},{"f":"ما متلازمة بوتر (Potter syndrome)؟","b":"ناجمة عن عدم تكون الكليتين الثنائي ← قلة السائل الشديدة ← وجه بوتر (أنف مفلطح، ذقن متراجع)، نقص تنسج الرئة (سبب الوفاة)، تشوهات أطراف."}]},{"t":"التغيرات الفيزيولوجية والترشيحية في الحمل","cards":[{"f":"كيف يزداد حجم الرحم في الحمل: بتضخم الخلايا أم بفرط تنسجها؟","b":"بتضخم الخلايا العضلية الملساء (Hypertrophy) أساساً مع بعض فرط التنسج المبكر — وليس بفرط التنسج وحده."},{"f":"ما التغيرات الدموية في الحمل؟ ولماذا يحدث فقر الدم الفيزيولوجي؟","b":"يزداد حجم البلازما (~50%) بنسبة أكبر من زيادة كتلة الكريات الحمر (~25%) ← فقر دم فيزيولوجي (تخفيفي)؛ تزداد عوامل التخثر (حالة فرط تخثر) والكريات البيض."},{"f":"ما تأثير الحمل على حركة الجهاز الهضمي؟","b":"تقلّ الحركة الحوية (Hypomotility) بتأثير البروجسترون ← إمساك، ارتجاع معدي مريئي، بطء إفراغ المعدة؛ تزداد الشهية واللعاب."},{"f":"ما التغيرات الدرقية في الحمل؟","b":"TSH ينخفض (hCG يحاكي TSH)، الغلوبولين الرابط للدرقية TBG يزداد بالإستروجين ← T4 وT3 الكليان يرتفعان بينما الحرّان طبيعيان."},{"f":"كم يزداد حجم الدم والنتاج القلبي في الحمل؟","b":"حجم الدم يزداد ~40-50% (ذروته 32-34 أسبوعاً)، النتاج القلبي يزداد ~30-50%، النبض يزداد 10-20/د، والضغط الانبساطي ينخفض في الثلث الثاني."},{"f":"ما تأثير الحمل على وظيفة الكلية؟","b":"يزداد الترشيح الكبيبي GFR ~50% ← ينخفض كرياتينين المصل (الطبيعي في الحمل ~0.5-0.7)؛ بيلة سكرية وبروتينية خفيفة قد تكون فيزيولوجية."},{"f":"ما تعريف النفاس (Puerperium)؟ وكم مدته؟","b":"عودة الفيزيولوجيا الوالدية (الرحم والأعضاء) إلى الحالة الطبيعية خلال 6 أسابيع من الولادة."},{"f":"هل تُمنع السوائل في النفاس بسبب صعوبة التبول؟","b":"لا — يُشجَّع على الإماهة الجيدة؛ صعوبة التبول التالية للولادة تُدبَّر بالتبول المبكر والقسطرة عند الحاجة لا بمنع السوائل."},{"f":"ما العلامات المفترضة (Presumptive) للحمل؟","b":"انقطاع الطمث، الغثيان والإقياء الصباحي، كثرة التبول، احتقان الثدي، شعور الأم بحركات الجنين (Quickening ~16-18 أسبوعاً) — كلها ذاتية غير مؤكدة."},{"f":"متى يُسمع قلب الجنين بالدوبلر؟ وبالسماعة العادية؟","b":"بالدوبلر: 10-12 أسبوعاً؛ بالسماعة (Fetoscope): 18-20 أسبوعاً؛ النبض الجنيني الطبيعي 110-160/د."}]},{"t":"الرعاية السابقة للولادة","cards":[{"f":"ما الفحوص المطلوبة في الزيارة الأولى للحامل؟ وأيها ليس روتينياً؟","b":"زمرة الدم وعامل Rh، تعداد دم، تحري الزهري والإيدز والتهاب الكبد B، تحري الحصبة الألمانية، تحليل بول، سكر؛ ليس روتينياً: حمض البول (Uric acid)، اللطاخة المهبلية الروتينية، قياس محيط البطن في الثلث الأول."},{"f":"ما اللقاح الآمن في الحمل؟ وأي اللقاحات ممنوعة؟","b":"الآمن: الكزاز (Tetanus)، الأنفلونزا المعطلة، السعال الديكي؛ الممنوعة: اللقاحات الحية (الحصبة، النكاف، الحصبة الألمانية MMR، جدري الماء، BCG)."},{"f":"ما الأدوية الممنوعة في الحمل؟ وما البدائل الآمنة؟","b":"ممنوعة: التتراسايكلين (تلون الأسنان)، الميتوتريكسات، الوارفارين (يعبر المشيمة)، مثبطات ACE؛ آمنة: الهيبارين (لا يعبر المشيمة)، النيتروفيورانتوئين (بعيداً عن الولادة)، البنسلينات."},{"f":"ما جرعة حمض الفوليك للحامل؟ ومتى تُضاعف؟","b":"0.4-0.8 ملغ يومياً قبل الحمل وخلال الثلث الأول للوقاية من عيوب الأنبوب العصبي؛ 4 ملغ يومياً (قبل الحمل بشهر + أول 3 أشهر) عند سوابق طفل بعيب أنبوب عصبي."},{"f":"ما أدق وسيلة لتحديد عمر الحمل في الثلث الأول؟","b":"قياس الطول القمي-العجزي (CRL — Crown-Rump Length) بالأمواج فوق الصوتية (± 5-7 أيام)؛ أدق من LMP عند عدم التأكد."},{"f":"متى يُرى نبض الجنين بالإيكو المهبلي؟","b":"من الأسبوع 6 (بالإيكو المهبلي Transvaginal)؛ بالبطني من 7-8 أسابيع؛ بالدوبلر من 10-12 أسبوعاً."},{"f":"ما الإجراء التشخيصي المؤكد للشذوذات الصبغية؟","b":"بزل السلى (Amniocentesis) أو CVS — التشخيص المؤكد خلوياً؛ أما المسح (AFP، الإيكو) فاحتمالي فقط. بزل فروة الرأس ليس لكشف الصبغيات."},{"f":"ما استطبابات الاستشارة الوراثية؟","b":"عمر الأم >35، سوابق طفل بشذوذ صبغي/عيب أنبوب عصبي، إسقاطات متكررة، قرابة، تعرض لماسخ معروف؛ ليس منها: التعرض للأشعة في حمل سابق وحده."},{"f":"ما المشعر السريري الأدق لوجود إنتان كوريو-أمنيوسي أثناء تدبير تمزق الأغشية الباكر؟","b":"الحمى (Fever) عند الأم — العلامة السريرية الأكثر دقة؛ تليها: تسرع قلب الأم والجنين، ألم رحمي، سائل كريه."},{"f":"ما نسبة الصبيب البولي الواجب الحفاظ عليها أثناء النزف لمنع النخر الأنبوبي الكلوي؟","b":"≥ 30 مل/ساعة (0.5 مل/كغ/ساعة) — مؤشر كافٍ على الإرواء الكلوي أثناء الإنعاش."},{"f":"ما أفضل اختبار لتشخيص قصور عنق الرحم (Cervical insufficiency)؟","b":"الإيكو المهبلي: طول عنق الرحم < 25 مم في الثلث الثاني = قصور؛ يُتابع تسلسلياً عند المشتبهات."},{"f":"كيف تؤثر قاعدة نيغل الصحيحة؟","b":"أول يوم من آخر طمث + 7 أيام − 3 أشهر + سنة (وليس طرح 7 أيام وإضافة 3 أشهر)."},{"f":"ما تأثير التدخين في الحمل؟","b":"يزيد: تحدد النمو داخل الرحم IUGR، انفكاك المشيمة، الولادة المبكرة، موت الجنين؛ لا يسبب الحمل المديد ولا المشيمة الملتصقة."},{"f":"ما فائدة الإيكو في الثلث الأول؟ وما الذي لا يفيده؟","b":"يفيد: تأكيد الحمل الحي، تحديد العمر (CRL)، كشف التوائم والحمل الهاجر؛ لا يفيد: تحديد ارتكاز المشيمة بدقة (المشيمة تهاجر لاحقاً)."}]},{"t":"سير الولادة وتدبيرها","cards":[{"f":"ما مراحل المخاض الثلاث؟","b":"الأولى: من بداية التقلصات المنتظمة حتى الاتساع التام (10 سم)؛ الثانية: من الاتساع التام حتى ولادة الجنين؛ الثالثة: من ولادة الجنين حتى خروج المشيمة (الخلاص)."},{"f":"متى يبدأ الطور الفعّال (Active phase) من المرحلة الأولى؟","b":"من توسع 3-4 سم حتى الاتساع التام 10 سم؛ قبله الطور الكامن (Latent) الذي قد يطول دون أن يكون مرضياً."},{"f":"ما مكونات مشعر بيشوب (Bishop score)؟","b":"خمسة: توسع العنق، إمحاء العنق (Effacement)، مستوى المجيء (Station)، قوام العنق، وضعية العنق — وليس منها: ضربات قلب الجنين ولا سلامة الأغشية ولا لون السائل. مجموع ≥8 = عنق ناضج جاهز للتحريض."},{"f":"ما تعريف التدخّل (Engagement)؟","b":"دخول القطر الأكبر للمجيء (القطر بين الجداريين Biparietal في المجيء القمي) في المضيق العلوي (مدخل الحوض Pelvic inlet)."},{"f":"ما الهرمون المسؤول عن تحريض المخاض وبدء التقلصات؟","b":"الأوكسيتوسين (Oxytocin) — يُفرز من النخامية الخلفية ويُستخدم دوائياً للتحريض وتسريع المخاض."},{"f":"ما صفات التقلصات الرحمية الفعّالة؟","b":"منتظمة، مؤلمة، متزايدة الشدة والمدة والتقارب (كل 2-3 دقائق)، تسبب توسعاً وإمحاءً تقدميين؛ ليست 3 مرات كل نصف ساعة (هذا غير فعّال)."},{"f":"ما الفرق بين المخاض الحقيقي والكاذب؟","b":"الحقيقي: تقلصات منتظمة متزايدة لا تزول بالمسكنات أو الراحة وتسبب توسع العنق؛ الكاذب (براكستون هيكس): غير منتظمة تزول بالراحة/المسكنات ولا توسّع العنق."},{"f":"ماذا يحدث عند انبثاق جيب المياه أثناء المخاض؟","b":"يتسارع المخاض عادة (يزيد فعالية التقلصات)؛ قد يسبب: انسدال الحبل السري (خاصة بالمجيئات المعيبة)، إنتاناً إن طال؛ لا يُبطئ المخاض."},{"f":"ما ميزة خزع الفرج المتوسط (Median) عن الجانبي (Mediolateral)؟","b":"المتوسط: إصلاحه أسهل ونزفه أقل وألمه أقل لكن خطر امتداده للمعصرة أكبر؛ الجانبي: أبعد عن المعصرة لكن إصلاحه أصعب وألمه أكبر."},{"f":"ماذا يجب التأكد منه قبل تخريج الوالدة (النفساء)؟","b":"تقبّض الرحم الجيد، عدم وجود نزف، تبولت (المثانة فارغة لا ممتلئة)، العلامات الحيوية مستقرة، الرضاعة بدأت."},{"f":"ما النقطة الاستكشافية (Denominator) في المجيء القمي الأيسر؟","b":"اليافوخ الخلفي (Occiput) — وليس الجبهة؛ النقطة الاستكشافية هي أقرب نقطة عظمية بارزة من المجيء."},{"f":"ما القطر الذي يتدخل به الرأس في المجيء القمي؟","b":"القطر تحت القفوي-البرغماوي (Suboccipitobregmatic ≈ 9.5 سم) — أصغر أقطار الرأس، يتدخل عند مدخل الحوض."}]},{"t":"النفاس","cards":[{"f":"ما أنواع الهلابة (Lochia) ومددها الطبيعية؟","b":"الحمراء (Rubra): 3-4 أيام؛ المصلية (Serosa): حتى ~10 أيام؛ البيضاء (Alba): حتى 6 أسابيع؛ استمرار الحمراء > أسبوعين غير طبيعي."},{"f":"ما تأثير الإرضاع الطبيعي على انطمار الرحم؟","b":"يُسرّعه — مصّ الطفل يحفّز إفراز الأوكسيتوسين ← تقلصات رحمية (تقلصات ما بعد الولادة Afterpains)؛ لا يسبب نقص الانطمار."},{"f":"نزف تالٍ لولادة مهبلية بلون أحمر فاتح مع تقبّض رحمي جيد — ما السبب الأرجح؟","b":"تمزقات تناسلية (مهبل/عنق/عجان) — النزف الشرياني الفاتح مع رحم متقبّض = مصدره القناة التناسلية لا العطالة."},{"f":"ما أسباب نزوف الخلاص (المرحلة الثالثة)؟ وأيها ليس منها؟","b":"العطالة الرحمية (الأشيع)، احتباس المشيمة/بقايا، تمزقات القناة، انقلاب الرحم، اعتلال التخثر؛ ليس منها: نقص وزن الجنين، هبوط الرحم، قصر الحبل."},{"f":"هل تُنصح النفساء بالإقلال من السوائل لصعوبة التبول؟","b":"لا — تُشجَّع على الإماهة الجيدة؛ صعوبة التبول تُعالج بالتبول المبكر والقسطرة المتقطعة عند الحاجة."},{"f":"ما الذي يُناقش في الزيارة الأولى بعد النفاس؟","b":"منع الحمل، الرضاعة، الحالة النفسية، الفحص السريري؛ لا يُناقش Anti-D (يُعطى عند الولادة مباشرة)."},{"f":"هل الحمل المديد سبب شائع لنزف ما بعد الولادة؟","b":"لا — الأسباب الشائعة: العطالة، التمزقات، احتباس المشيمة، اعتلال التخثر (قاعدة 4T: Tone, Tissue, Trauma, Thrombin)."},{"f":"متى يُستقصى عنق الرحم والمهبل بعد الولادة؟","b":"عند الشك بتمزقات (نزف مع رحم متقبّض)، بعد الولادات الآلية، عند الاشتباه باحتباس — وليس روتينياً لكل عديدة ولادة."}]},{"t":"الاختلاطات الصغرى في الحمل","cards":[{"f":"ما سبب القلس (حرقة الفؤاد) في الحمل؟","b":"البروجسترون يُرخي المصرة المريئية السفلية (LES) + ضغط الرحم الحامل — يتحسن بالوجبات الصغيرة وتجنب الاستلقاء بعد الأكل."},{"f":"ما تدبير الإقياءات الحملية الخفيفة؟ وماذا يُتجنّب؟","b":"وجبات صغيرة متكررة، تجنب الروائح المثيرة، الزنجبيل، فيتامين B6؛ يُتجنّب: شرب الماء أثناء الطعام (يزيد الغثيان)."},{"f":"ما تدبير الإقياء الحملي الشديد (Hyperemesis gravidarum)؟","b":"إماهة وريدية، تعويض الشوارد، فيتامين B1 (الثيامين) قبل الغلوكوز، مضادات الإقياء، الستيروئيدات مفيدة في الحالات الشديدة المعندة."},{"f":"هل ارتفاع الضغط الشرياني من الاختلاطات الصغرى في الحمل؟","b":"لا — ارتفاع الضغط (ما قبل الإرجاج) اختلاط كبير يستدعي التقييم الفوري؛ الصغرى: غثيان، إمساك، حرقة، ألم ظهر، دوالي، بواسير."},{"f":"متى تراجع الحامل الطبيب فوراً؟","b":"نزف مهبلي، سيلان سائل، صداع شديد مستمر، اضطراب رؤية، ألم شرسوفي، نقص حركات الجنين، تقلصات منتظمة مبكرة، حمى؛ الصداع المتقطع الذي يزول بالمسكنات ليس إسعافياً."},{"f":"هل الإمساك حالة إسعافية عند الحامل؟","b":"لا — اختلاط صغير شائع (البروجسترون + الحديد) يُدبَّر بالألياف والسوائل والحركة؛ الإسعافيات: النزف، تمزق الأغشية، ما قبل الإرجاج."},{"f":"ما سبب زيادة النشاط — هل هو من اختلاطات الحمل الصغرى؟","b":"لا — ليست «زيادة النشاط» اختلاطاً حملياً؛ الاختلاطات الصغرى أعراض هضمية وبولية وعضلية هيكلية شائعة."},{"f":"ما سبب ألم الظهر في الحمل؟","b":"ارتخاء الأربطة بتأثير الريلاكسين والبروجسترون + تغير مركز الثقل (قعس قطني) — يُدبَّر بالوضعيات وتمارين الحوض."}]},{"t":"الإجهاض والإسقاط","cards":[{"f":"ما أكثر أسباب الإجهاض العفوي (التلقائي) تواتراً؟","b":"الشذوذات الصبغية (Chromosomal abnormalities) للجنين — مسؤولة عن ~50% من الإسقاطات في الثلث الأول."},{"f":"ما صفات التهديد بالإسقاط (Threatened abortion)؟ وما تدبيره؟","b":"نزف مهبلي خفيف + عنق مغلق + حجم رحم متناسب مع العمر + جنين حي بالإيكو؛ التدبير: طمأنة ومراقبة — قد يتابع الحمل طبيعياً."},{"f":"ما الفرق بين الإسقاط المهدد والحتمي والناقص والكامل والمنسي؟","b":"المهدد: عنق مغلق وجنين حي؛ الحتمي: عنق مفتوح مع نزف (لا مفر)؛ الناقص: خروج جزء وبقاء بقايا؛ الكامل: خروج كل المحتويات؛ المنسي: موت الجنين دون أعراض إسقاط."},{"f":"متى يُجرى تطويق عنق الرحم (Cerclage) في قصور العنق؟","b":"بين الأسبوعين 12-14 (وقائياً عند سوابق) — لا قبل الحمل ولا في الأسبوع 17 روتينياً؛ يُزال عند 37 أسبوعاً أو بدء المخاض."},{"f":"ما أسباب الإسقاطات المتكررة؟ وأيها ليس منها؟","b":"وراثية (صبغية)، تشريحية (حاجز رحمي)، مناعية (أضداد الفوسفولبيد)، صماوية، إنتانية؛ ليس منها: سوابق الحصبة الألمانية ولا سوابق الولادة المبكرة."},{"f":"ما استطبابات الإجهاض الطبي (العلاجي)؟","b":"خطر على حياة الأم (قلبية شديدة، خمج)، تشوه جنيني قاتل، حمل عنقودي؛ ليس منها: ارتفاع التوتر وحده، السكري غير المختلط، قصور الدرق، داء كرون، انسدال التاجي."},{"f":"ما استطبابات الإجهاض الدوائي (الميفيبريستون + ميزوبروستول)؟","b":"الحمل المبكر المرغوب إنهاؤه لسبب طبي ضمن الحدود القانونية؛ مضادات الاستطباب: الحمل الهاجر، اعتلال التخثر، قصور الكظر، اللولب الموجود."},{"f":"حامل 8 أسابيع: نزف خفيف دون ألم + كيس حمل داخل الرحم وجنين نابض — ما التدبير؟","b":"طمأنة ومراقبة (تهديد بالإسقاط) — لا حاجة لتداخل؛ تُعطى Anti-D إن كانت سلبية Rh."},{"f":"ما دور Anti-D في الإسقاط؟","b":"تُعطى الغلوبولين المناعي Anti-D لكل حامل سلبية Rh بعد أي نزف/إسقاط/حمل هاجر لمنع التحسس — خلال 72 ساعة."},{"f":"ما اختلاطات الإسقاط الناقص غير المدبَّر؟","b":"النزف، الإنتان (الإسقاط الإنتاني Septic abortion)، احتباس البقايا — التدبير: تفريغ الرحم (شفط/تجريف) + مضادات حيوية عند الإنتان."}]},{"t":"الحمل خارج الرحم","cards":[{"f":"ما أشيع مكان للحمل الهاجر (Ectopic)؟","b":"البوق (Tubal) — وتحديداً الأمبولة (Ampulla)؛ ثم البرزخ، فالمبيض، فالبطن، فعنق الرحم."},{"f":"ما عوامل خطورة الحمل الهاجر؟ وأيها ليس منها؟","b":"التهاب الحوض PID، جراحة بوقية سابقة، حمل هاجر سابق، التدخين، اللولب، العمر؛ ليس منها: تحريض الإباضة، حبوب منع الحمل المركبة، PCO، سوابق مشيمة منزاحة."},{"f":"ما الثالوث السريري الكلاسيكي للحمل الهاجر؟","b":"ألم بطني/حوضي + نزف مهبلي + انقطاع طمث مع اختبار حمل إيجابي؛ المتمزق: صدمة + بطن حاد + ألم كتف (تهيج الحجاب)."},{"f":"ما أدق فحص لتشخيص الحمل الهاجر؟","b":"الأمواج فوق الصوتية عبر المهبل (Transvaginal US): رحم فارغ + كتلة ملحقات + سائل حر = حمل هاجر حتى يثبت العكس."},{"f":"رحم فارغة بالإيكو + كتلة ملحقات 3.5 سم — ما الخطوة التالية؟","b":"تحليل β-hCG كمي + تقييم الاستقرار الدموي؛ منطقة التمييز (Disciminatory zone): كيس حمل داخل الرحم يُرى عند β-hCG ~1500-2000 بالإيكو المهبلي."},{"f":"هل عدم تضاعف β-hCG كل 48 ساعة يؤكد تشخيص الحمل الهاجر؟","b":"لا — يشير لحمل غير حيوي (هاجر أو إسقاط) لكنه لا يؤكد الهاجر وحده؛ الارتفاع الطبيعي ≥53% كل 48 ساعة."},{"f":"ما شروط العلاج بالميتوتركسات في الحمل البوقي؟","b":"مستقرة دموياً، غير متمزق، كتلة <3.5 سم، β-hCG <5000-10000، لا إرضاع، وظائف كبد/كلية طبيعية، موافقة على المتابعة؛ ليس منها: الحمل المغاير (Heterotopic)."},{"f":"كيف يُعالج الحمل الهاجر المتمزق؟","b":"جراحياً إسعافياً: استئصال البوق (Salpingectomy) عند التمزق والنزف — لا فغر البوق (Salpingostomy) في المتمزق غير المستقر."},{"f":"في الحمل الهاجر: هل حجم الرحم أكبر من العمر المتوقع؟","b":"لا — الرحم أصغر من العمر المتوقع (فارغ)؛ الرحم الأكبر من المتوقع يوحي برحى عدارية أو توائم أو ورم."},{"f":"ما التشخيص التفريقي للحمل الهاجر؟","b":"الإسقاط المهدد، تمزق الجسم الأصفر، التهاب الحوض، التهاب الزائدة، التواء المبيض؛ انفكاك المشيمة الباكر ليس تفريقياً (يحدث في حمل متقدم داخل الرحم)."}]},{"t":"نزف أشهر الحمل الأخيرة","cards":[{"f":"ما الفرق السريري بين المشيمة المنزاحة وانفكاك المشيمة الباكر؟","b":"المنزاحة: نزف غير مؤلم (Painless) في الثلث الثالث؛ الانفكاك: نزف مؤلم (Painful) مع فرط توتر/تقفع الرحم وألم بطني مستمر."},{"f":"ما العرض الأكثر شيوعاً في المشيمة المنزاحة؟","b":"نزف مهبلي غير مؤلم في الثلث الثالث — أحمر فاتح، متكرر، يبدأ خفيفاً."},{"f":"ما الإجراء الممنوع في المشيمة المنزاحة؟","b":"الفحص المهبلي (Digital vaginal exam) — قد يثير نزفاً قاتلاً؛ التشخيص بالإيكو (عبر البطن/المهبلي بحذر)."},{"f":"ما عامل الخطورة الأهم للمشيمة المنزاحة؟","b":"سوابق قيصريات (تتضاعف مع تكرارها)، تعدد الولادات، العمر، التدخين، الحمل المتعدد."},{"f":"ما أشيع اختلاط للمشيمة المنزاحة مع سوابق قيصرية سفلية؟","b":"المشيمة الملتصقة (Accreta spectrum) — ارتكاز المشيمة المعيب فوق الندبة؛ خطر النزف والاستئصال الرحمي."},{"f":"ما عامل الخطورة الأهم لانفكاك المشيمة الباكر؟","b":"ارتفاع التوتر الشرياني/ما قبل الإرجاج (الأهم)، ثم: التوائم، كثرة السائل المفاجئ النقص، الرض، التدخين، سوابق انفكاك."},{"f":"ما التغير المخبري المميز لاعتلال التخثر التالي لانفكاك المشيمة؟","b":"انخفاض الفيبرينوجين (Fibrinogen) — استهلاك عوامل التخثر (DIC استهلاكي)؛ يُعوَّض بالبلازما والفيبرينوجين."},{"f":"ما أفضل إجراء للوقاية من القصور الكلوي الحاد في انفكاك المشيمة؟","b":"تعويض الدم السريع والكافي (استعادة حجم الدم والإرواء الكلوي) — لا المدرات."},{"f":"هل القيصرية استطباب مطلق في انفكاك المشيمة الباكر؟","b":"لا — إن كانت الأم والجنين مستقرين والمخاض متقدماً قد تتم الولادة مهبلياً؛ الاستطباب حسب الحالة (تألم جنيني، صدمة، DIC)."},{"f":"ما أسباب النزف قبل الولادة (Antepartum hemorrhage)؟ وأيها ليس منها؟","b":"المشيمة المنزاحة، انفكاك المشيمة، نزف هامشي؛ ليس منها: الحمل الهاجر (نزف الثلث الأول) ولا الإجهاضات."},{"f":"هل تُشخَّص انفكاك المشيمة بالإيكو؟","b":"التشخيص سريري (ألم + نزف + فرط توتر رحم) — الإيكو قد لا يُظهر الجلطة الحادة (غير نوعي) ولا ينفي الانفكاك."},{"f":"ما أسباب DIC في الحمل؟ وأيها ليس منها؟","b":"انفكاك المشيمة، الإرجاج الشديد، موت الجنين المحتبس، الصمة الأمنيوسية، الإنتان؛ ليس منها: الاندومتريوز ولا المشيمة المنزاحة وحدها."}]},{"t":"ارتفاع الضغط الرئوي عند الحمل","cards":[{"f":"ما تعريف ما قبل الإرجاج (Pre-eclampsia)؟","b":"ارتفاع ضغط ≥140/90 + بيلة بروتينية ≥300 ملغ/بول 24 ساعة بعد الأسبوع 20 من الحمل عند حامل كان ضغطها طبيعياً."},{"f":"ما الفيزيولوجيا المرضية الأساسية لما قبل الإرجاج؟","b":"تشنج وعائي (Vasospasm) مع خلل بطانة الأوعية وقصور انغراس الأرومة الغاذية — وليس زيادة حجم الدم."},{"f":"ما معايير ما قبل الإرجاج الشديد؟ وأيها ليس منها؟","b":"ضغط ≥160/110، بيلة بروتينية ≥2-3+، أعراض عصبية/بصرية، ألم شرسوفي، قلة صفيحات، ارتفاع خمائر الكبد، وذمة رئة؛ ليس منها: وذمات الطرفين السفليين الشديدة ولا بيلة 50 ملغ/24سا."},{"f":"ما سبب الألم في المراق الأيمن في ما قبل الإرجاج؟","b":"تمطط محفظة الكبد (Glisson capsule) بسبب الوذمة/النزف تحت المحفظة — علامة منذرة بخطورة."},{"f":"ما معايير متلازمة HELLP؟","b":"انحلال دم (Hemolysis) + ارتفاع خمائر الكبد (Elevated Liver enzymes) + نقص الصفيحات (Low Platelets)؛ البيلة البروتينية ليست من معاييرها."},{"f":"ما العلاج الوقائي/العلاجي للنوب الاختلاجية في الإرجاج؟ وما مدته؟","b":"سلفات المغنزيوم (MgSO4) وريدياً — وقاية وعلاجاً للنوب؛ تُعطى 24 ساعة بعد الولادة/آخر نوبة؛ آليتها ليست تفعيل الصفيحات."},{"f":"ما الترياق النوعي للانسمام بسلفات المغنزيوم؟","b":"غلوكونات الكالسيوم (Calcium gluconate) وريدياً — عند غياب المنعكسات أو تثبط التنفس؛ سلفات البروتامين لا تعاكس المغنزيوم."},{"f":"ما العلاج الشافي لما قبل الإرجاج الشديد؟","b":"إنهاء الحمل (الولادة) — مثال: حامل 35 أسبوعاً ضغط 160/110 + بيلة 3+ ← إنهاء الحمل؛ المراقبة وحدها لا تكفي في الشديد."},{"f":"هل تُعطى المدرات في ما قبل الإرجاج الشديد؟","b":"لا — المدرات (والكلورتيازيد في الإرجاج) ممنوعة؛ تُعطى فقط عند وذمة الرئة؛ خافضات الضغط: هيدرالازين/لابيتالول/نيفيديبين."},{"f":"ما علامات قرب حدوث الإرجاج (المنذرة)؟","b":"صداع شديد مستمر، اضطراب رؤية ( Scotomata)، ألم شرسوفي، فرط منعكسات؛ الغثيان والإقياء وحدهما ليسا منذرين."},{"f":"ما عوامل خطورة ما قبل الإرجاج؟ وأيها ليس منها؟","b":"خروسية، سوابق ما قبل إرجاج، حمل متعدد، سكري، ارتفاع ضغط مزمن، داء كلوي، السمنة؛ ليس منها: انبثاق الأغشية الباكر ولا العقم الثانوي."},{"f":"ما أشيع اختلاط لارتفاع الضغط المزمن مع الحمل؟","b":"تطور ما قبل الإرجاج المتراكب + انفكاك المشيمة الباكر — يتطلب مراقبة لصيقة."},{"f":"هل تسبق نوبة الإرجاج علامات منذرة دوماً؟","b":"لا — قد تحدث النوبة دون سابق إنذار؛ لذا الوقاية بسلفات المغنزيوم والمراقبة أساسيتان."}]},{"t":"الاضطرابات القلبية الوعائية التنفسية الدموية العصبية والهضمية في الحمل","cards":[{"f":"ما أشيع سبب لفقر الدم في الحمل؟","b":"نقص الحديد (Iron deficiency) — تزداد الحاجة للحديد (~1000 ملغ للحمل كاملاً)؛ يُعطى وقائياً من الثلث الثاني."},{"f":"ما أفضل علاج لالتهاب الوريد الخثري (الخثار الوريدي) عند الحامل؟","b":"الهيبارين منخفض الوزن الجزيئي (LMWH) — لا يعبر المشيمة؛ الوارفارين ممنوع (يعبر المشيمة وماسخ)."},{"f":"كيف تُعاكس تأثير الهيبارين؟","b":"بسلفات البروتامين (Protamine sulfate) — تُعطى وريدياً ببطء عند النزف."},{"f":"متى تُعطى Anti-D للحامل سلبية Rh؟ وهل تُعطى للمتحسسة؟","b":"في الأسبوع 28 وقائياً + بعد الولادة (وبعد أي نزف/إجراء)؛ لا تُعطى للسيدة المتحسسة أصلاً (Anti-D وقائي لا علاجي)."},{"f":"ما معايير تشخيص متلازمة أضداد الفوسفولبيد؟","b":"سريرية: خثار وعائي أو إسقاطات متكررة/موت جنين؛ مخبرية: أضداد الكارديوليبين/β2-glycoprotein/مميع الذئب — وليس ارتفاع الهيموسيستئين."},{"f":"ما الموجودات القلبية الطبيعية في الحمل؟ وأيها غير طبيعي؟","b":"طبيعي: نفخة انقباضية انسيابية، S3، تسرع قلب خفيف؛ غير طبيعي: النفخة الانبساطية (Diastolic murmur) — تستدعي التقييم."},{"f":"ما المحظور في تدبير المريضة القلبية الحامل؟","b":"مضادات الألدوستيرون (سبيرونولاكتون)، مثبطات ACE، الوارفارين؛ المدرات لا تُعطى روتينياً في NYHA 1-2."},{"f":"ما خصوصية التهاب الزائدة الدودية في الحمل؟","b":"ترتفع الزائدة مع الرحم (الألم ينتقل للأعلى)؛ لا يُؤجَّل الاستئصال لما بعد الولادة — الجراحة المبكرة تحمي الأم والجنين."},{"f":"ما صفات الركودة الصفراوية الحملية (Cholestasis)؟","b":"حكة شديدة (راحتين وأخمصين) في الثلث الثالث + ارتفاع الأحماض الصفراوية؛ اضطراب الوظيفة الكبدية خفيف — ليست كبيراً."},{"f":"هل يزداد ضغط الدم في الحمل الطبيعي؟","b":"لا — ينخفض الضغط الانبساطي في الثلث الثاني (بتأثير البروجسترون) ثم يعود؛ ارتفاع الضغط دائماً مرضي."},{"f":"ما عناصر تشخيص DIC أثناء الحمل؟","b":"نقص الصفيحات والفيبرينوجين، تطاول PT/aPTT، ارتفاع منتجات تدرك الفيبرين (FDPs/D-dimer)؛ نقص FDPs ليس مشخصاً."},{"f":"هل يُسبب فقر دم الأم احمرار دم (Polycythemia) تعويضياً عند الوليد؟","b":"لا — فقر دم الأم لا يرفع كريات الوليد تعويضياً؛ الوليد قد يكون ناقص مخزون الحديد."},{"f":"ما أسباب انتقال كريات دم الجنين للأم (Fetomaternal hemorrhage)؟","b":"الولادة، الإسقاط، الحمل الهاجر، بزل السلى، الرض البطني، انفكاك المشيمة؛ تألم الجنين وحده ليس سبباً."}]},{"t":"الاضطرابات الغدية أثناء الحمل","cards":[{"f":"متى يُتحرّى عن السكري الحملي (GDM)؟ وبأي اختبار؟","b":"بين الأسبوعين 24-28: اختبار تحدي الغلوكوز 50غ (GCT) — إن كان إيجابياً (>140) يُتبع باختبار تحمل الغلوكوز التشخيصي OGTT (100غ/3 ساعات أو 75غ/ساعتين)."},{"f":"متى تزداد الحاجة للأنسولين أكثر في حمل السكرية؟","b":"في النصف الثاني (من ~16 أسبوعاً تزداد المقاومة خطياً ~5% أسبوعياً حتى 33-36)؛ في بداية الحمل قد تزداد الحساسية ويُخفَّض الأنسولين 10-20% (خطر نقص السكر)."},{"f":"ما اختلاطات السكري الحملي على الجنين؟ وأيها ليس منها؟","b":"ضخامة الجنين (Macrosomia >4000غ أو >90th percentile)، انعضال الكتفين، نقص سكر الوليد، كثرة السائل، متلازمة الضائقة التنفسية؛ ليس منها: التشوهات الخلقية (خاصة بالسكري السابق للحمل) ولا تحدد النمو."},{"f":"لماذا يسبب السكري السابق للحمل تشوهات خلقية بينما الحملي لا؟","b":"التشوهات تحدث في فترة التعضي (3-8 أسابيع) — السكري السابق موجود حينها؛ السكري الحملي يظهر بعد 24 أسبوعاً (بعد اكتمال التعضي)."},{"f":"ما تأثير قصور الدرق غير المعالج في الحمل؟","b":"يزيد: ما قبل الإرجاج، الولادة المبكرة، انخفاض وزن الولادة، النزف التالي للولادة، ضعف الإدراك لدى الطفل؛ لا يزيد وزن الوليد ولا يسبب موه السلى."},{"f":"هل تحتاج الحامل المصابة بقصور الدرق تعديل جرعة الليفوثيروكسين؟","b":"نعم — غالباً تحتاج زيادة الجرعة ~25-50% في الحمل (يُراقب TSH كل 4-6 أسابيع)؛ الهدف TSH <2.5 في الثلث الأول."},{"f":"ما تغيرات الغدة الدرقية في الحمل؟ (تذكير)","b":"TSH ينخفض (hCG يحاكي TSH)، TBG يرتفع بالإستروجين ← T4/T3 الكليان مرتفعان والحرّان طبيعيان."},{"f":"ما الهدف السكري قبل الحمل (Preconception)؟","b":"HbA1c <6.5% قبل الحمل حسب ADA (<7% مقبول) — الضبط السيئ يرفع التشوهات والإسقاط؛ يُوقف مثبطات ACE والستاتينات."},{"f":"ما أشيع مضاعفات السكري الحملي؟","b":"ضخامة الجنين (Macrosomia) — تليها: انعضال الكتفين أثناء الولادة، نقص سكر الوليد، اليرقان."},{"f":"هل يترافق السكري الحملي مع الإرجاج؟","b":"السكري (خاصة السابق) يرفع خطر ما قبل الإرجاج — لكن الإرجاج ليس اختلاطاً مباشراً نمطياً للسكري الحملي وحده."},{"f":"ما تدبير سكري الحمل؟","b":"الخط الأول: حمية + نشاط فيزيائي ومراقبة سكر؛ إن فشل: الأنسولين (العلاج الدوائي الأول)؛ الميتفورمين مساعد/بديل مقبول."},{"f":"ماذا يُجرى بعد الولادة للمصابة بالسكري الحملي؟","b":"غلوكوز الصيام بعد 6 أسابيع من الولادة — حتى إن كان سلبياً: 50% يتطور لديهن السكري لاحقاً (متابعة دورية)."}]},{"t":"الأخماج أثناء الحمل","cards":[{"f":"ما أشيع خمج خلقي (Congenital infection)؟ وما أشيع عقابيله؟","b":"الفيروس المضخم للخلايا CMV — أشيع خمج خلقي مكتسب؛ أشيع عقابيله: نقص السمع الحسي العصبي (SNHL) — السبب الأول له."},{"f":"ما تظاهرات CMV الخلقي عند الوليد العرضي؟","b":"صغر الحجم للعمر، نقص صفيحات، يرقان، صغر الرأس (Microcephaly — لا كبره)، توسع بطينات، نمشات؛ 10% عرضيون عند الولادة."},{"f":"أي إنتان أولي أم ثانوي بـCMV أخطر على الجنين؟","b":"الإنتان الأولي أخطر: نسبة الانتقال للجنين 40% مقابل أقل في الثانوي؛ الانتقال أعلى في الثلث الثالث (60%)."},{"f":"ما أشيع مسبب للبيلة الجرثومية اللاعرضية عند الحامل؟ وما خطر إهمالها؟","b":"الإشريكية القولونية (E. coli)؛ إهمالها يرفع خطر التهاب الحويضة والكلية (أعلى عند الحوامل) والولادة المبكرة — تُعالج دائماً."},{"f":"متى يُتحرّى عن العقديات B (GBS) عند الحوامل؟","b":"بين الأسبوعين 35-37 (وليس 30-32): مسحة مهبلية-شرجية؛ الإيجابية ← وقاية بنسلينية أثناء المخاض (بنزيل بنسلين)."},{"f":"لماذا تُعطى الوقاية من GBS أثناء المخاض؟","b":"GBS أشيع سبب للإنتان الوليدي الباكر الشديد (Early-onset neonatal sepsis) — الوقاية داخل المخاض تمنعه."},{"f":"ما معنى إيجابية أضداد الحصبة IgG عند الحامل؟","b":"أنها ممنعة ولا خطر عليها خلال الحمل؛ لقاح الحصبة (حي) ممنوع في الحمل — يُعطى بعد الولادة."},{"f":"حامل بضائعات مهبلية بيضاء قشدية + حكة فرجية شديدة — ما التشخيص؟","b":"داء المبيضات (Candida albicans) — شائع في الحمل (السكري والسمنة مؤهبان)؛ العلاج: مضادات فطرية موضعية (آمنة)."},{"f":"أي العوامل الممرضة مشوهة للجنين؟ وأيها ليس؟","b":"مشوهة: الحصبة الألمانية، CMV، المقوسات، الزهري، جدري الماء، زيكا؛ ليست مشوهة نمطياً: العنقوديات المذهبة."},{"f":"هل تسبب CMV إجهاضات متكررة؟","b":"لا — الإجهاضات المتكررة ليست من سمات CMV؛ سماتها: صغر الرأس، نقص السمع، التخلف العقلي."}]},{"t":"أمراض المشيمة وأغشيتها","cards":[{"f":"ما العلامة الواسمة (المميزة) للرحى العدارية (Molar pregnancy)؟","b":"خروج حويصلات (Vesicles) عنبية الشكل مع النزف التناسلي + رحم أكبر من العمر + hCG شديد الارتفاع."},{"f":"ما الفرق بين الرحى التامة والجزئية؟ وأيهما أسوأ إنذاراً؟","b":"التامة: كل الزغابات متكيسة ولا جنين (46XX أبوي)؛ الجزئية: بعض الزغابات + جنين مشوه (ثلاثي الصيغة)؛ الإنذار أسوأ في التامة (خطر خباثة أعلى)."},{"f":"ما أشيع تظاهر سريري للرحى العدارية التامة؟","b":"النزف المهبلي في الثلث الأول — مع غثيان شديد (hCG العالي) ورحم أكبر من المتوقع."},{"f":"هل يمكن أن تتطور الرحى العدارية للخباثة؟","b":"نعم — قد تتطور لداء الأرومة الغاذية الحملي (GTN/Choriocarcinoma)؛ أشيع أماكن الانتقال: الرئتان؛ تُتابع بـhCG بعد التفريغ."},{"f":"ما الكيسات المبيضية المرافقة للرحى العدارية؟","b":"الكيسات اللوتينية القرابية (Theca-lutein cysts) — ثنائية كبيرة بتحفيز hCG العالي؛ تتراجع عفوياً بعد العلاج (لا تُستأصل)."},{"f":"ما عامل خطورة المشيمة الملتصقة (Accreta)؟","b":"ارتكاز المشيمة المعيب (المنزاحة) فوق ندبة قيصرية — الثالوث: منزاحة + ندبة + تقدم العمر/تعدد الولادات."},{"f":"ما تصنيف تنشؤات الطبقة المغذية الحملية (GTN)؟","b":"رحى غازية (Invasive mole)، سرطانة مشيمية (Choriocarcinoma)، ورم الأرومة الغاذية موضع المشيمة PSTT؛ ليست منها: «رحى دموية»."},{"f":"في أي الحالات يرتفع hCG؟ وأيها لا يرتفعه؟","b":"يرتفع: الحمل، الرحى العدارية، سرطانة المشيمة، التوائم؛ لا يرتفع في: الداء السكري."},{"f":"ما سبب انعدام السائل السلوي (Anhydramnios) الأكثر؟","b":"انسداد بولي جنيني (دسام إحليل خلفي Posterior urethral valves) أو عدم تكون الكليتين — الجنين لا ينتج بولاً."},{"f":"هل الكلية عديدة الكيسات عند الجنين تسبب استسقاء أمنيوسياً؟","b":"لا — الكلية عديدة الكيسات (المحافظة على إنتاج البول) لا تسبب قلة السائل عادة؛ المسبب: عدم التكون/الانسداد."},{"f":"ما أفضل وسيلة لتحسين الأعراض الوالدية في موه السلى الشديد؟","b":"بزل السلى التفريغي (Amnioreduction) — يخفف الضغط والأعراض؛ مع تدبير السبب (سكري الأم مثلاً)."},{"f":"هل للحبل السري الطويل أهمية سريرية؟","b":"لا — الطول الزائد وحده بلا أهمية؛ المهم سريرياً: الحبل القصير جداً، العقد الحقيقية، التفافه حول العنق، الارتكاز الهامشي/الغشائي."},{"f":"هل المشيمة المنزاحة تسبب اضطراب السائل الأمنيوسي؟","b":"لا — اضطرابات السائل أسبابها: جنينية (بول/بلع)، مشيمية (قصور)، سكري؛ المنزاحة تسبب نزفاً لا اضطراب سائل."}]},{"t":"الاختلافات في مدة الحمل","cards":[{"f":"ما تعريف الحمل المديد (Post-term)؟","b":"≥ 294 يوماً (42 أسبوعاً كاملة من LMP)؛ الممتد (Late term): 41-41+6."},{"f":"ما مخاطر الحمل المديد؟ وأيها ليس منها؟","b":"ندرة السائل السلوي، ضخامة الجنين، قصور المشيمة، إفراغ العقي؛ ليس منها: ارتفاع التوتر الشرياني؛ الوليد: جلد متقشر متجعد (ليس ناعماً)."},{"f":"حامل 42 أسبوعاً و3 أيام: عنق 1 سم وإمحاء 20% — ما التدبير؟","b":"قيصرية (عنق غير ناضج + حمل مديد) — أو تحريض إن أمكن؛ المراقبة وحدها غير كافية بعد 42 أسبوعاً."},{"f":"ما المشعر الأهم في المفرزات العنقية لتحري الولادة الباكرة؟","b":"الفيبرونكتين الجنيني (Fetal fibronectin): إيجابيته بين 24-34 أسبوعاً تنبئ بالولادة المبكرة؛ سلبيته تنفيها بقوة."},{"f":"ما السبب الرئيسي لوفيات الولدان؟","b":"الخداج (Prematurity) ومضاعفاته (الضائقة التنفسية، النزف داخل البطينات، التهاب الأمعاء النخري)."},{"f":"ما شروط المعالجة الموقفة للمخاض (Tocolysis)؟","b":"مخاض باكر حقيقي، توسع <5 سم، أغشية سليمة أو مبثوقة دون إنتان، جنين حي دون تألم؛ مضاد الاستطباب: ما قبل إرجاج شديد، إنتان أمنيوسي، تألم جنيني."},{"f":"ما أدوية إيقاف المخاض؟ وأيها ليس منها؟","b":"نيفيديبين (الأول)، أتوسيبان، إندوميتاسين (قصيراً)، سلفات المغنزيوم؛ ليست منها: حاصرات بيتا."},{"f":"متى تُعطى الستيروئيدات القشرية في التهديد بالولادة المبكرة؟","b":"بين 24-34 أسبوعاً (بيتاميتازون): إنضاج رئة الجنين؛ لا تُعطى روتينياً بعد 34 أسبوعاً."},{"f":"هل الإنتان من مسببات المخاض الباكر؟","b":"نعم — إنتان السائل الأمنيوسي/التهاب المشيماء من أهم مسببات الولادة المبكرة (الإنتان سبب لا نافٍ)."},{"f":"ما تدبير إنتان السائل الأمنيوسي (Chorioamnionitis)؟","b":"إنهاء الحمل فوري (تحريض/قيصرية حسب الحالة) + مضادات حيوية واسعة — لا يُؤخَّر خوفاً من الخداج."},{"f":"حامل 32 أسبوعاً: سيلان سائل منذ 5 ساعات دون أعراض — هل يُنهى الحمل فوراً؟","b":"لا — بين 32-34 أسبوعاً: تدبير ترقبي (مراقبة + ستيروئيدات + وقاية GBS) ما لم يوجد إنتان/تألم/مخاض فعال."},{"f":"ما الذي يفيد في تشخيص انبثاق الأغشية الباكر؟ وأيها لا يفيد؟","b":"يفيد: رؤية السيلان بالمنظار، اختبار النترازين (pH)، التسرخ (Ferning)، الإيكو (قلة السائل)؛ لا يفيد: اختبار كليهور (Kleihauer — للكريات الجنينية)."},{"f":"من أسباب الخداج؟ وأيها ليس منها؟","b":"الإنتان، الحمل المتعدد، تمزق الأغشية، ما قبل الإرجاج، قصور العنق؛ ليس منها: ضيق الحوض (يسبب عسر مخاض لا خداجاً)."}]},{"t":"الجنين المعرض للخطورة","cards":[{"f":"هل تحدد النمو داخل الرحم (IUGR) استطباب دائم للقيصرية؟","b":"لا — ليس استطباباً بحد ذاته؛ يُراقب بـCTG أثناء المخاض (ضعف تحمل الاختناق) والقيصرية عند تألم الجنين."},{"f":"ما عامل الخطورة الأهم لتحدد نمو الجنين؟","b":"الشذوذات الصبغية والتشوهات، قصور المشيمة (ما قبل إرجاج)، التدخين، الإنتانات الخلقية؛ السكري الحملي يسبب ضخامة لا تحدداً."},{"f":"ما دلالة إفراغ العقي (Meconium) في السائل السلوي؟","b":"تألم الجنين الحاد (نقص الأكسجة) — خاصة العقي الثخين؛ يستدعي تقييماً فورياً لوضع الجنين."},{"f":"ما استطبابات CTG أثناء المخاض؟ وأيها ليس منها؟","b":"الحمول عالية الخطورة: IUGR، ما قبل إرجاج، سكري، حمل متعدد، مخاض معزز؛ ليس منها: ارتكاز مشيمة مركزي تام (استطباب قيصرية أصلاً)."},{"f":"ما اختبارات تقييم سلامة الجنين؟ وأيها ليس منها؟","b":"NST (اختبار اللاشدة)، اختبار الجهد (CST)، المشعر الفيزيائي (BPP)، دوبلر الشريان السري؛ ليس منها: البزل السلوي (تشخيصي لا تقييمي)."},{"f":"ما دلالات تباطؤات قلب الجنين؟","b":"المبكر: ضغط رأس الجنين (حميد)؛ المتأخر: قصور مشيمي (خطير)؛ المتغير: انضغاط الحبل السري (وليس ضغط الرأس)."},{"f":"ما مكونات المشعر الفيزيائي الحيوي (BPP)؟","b":"خمسة (كل 2 نقطة): NST، حركات الجنين، توتر الجنين، حركات التنفس، حجم السائل السلوي — 8-10 طبيعي."},{"f":"ما سبب تسرع قلب الجنين؟","b":"حمى الأم/إنتان، أدوية (أتروبين)، فقر دم جنيني، تسرع أمومي؛ يُقيَّم مع السياق السريري."}]},{"t":"المجيئات المعيبة","cards":[{"f":"ما أسوأ أنواع المجيئات؟","b":"المجيء الجبهي (Brow presentation) — قطر التدخل الأكبر (ذقني-قفوي ~13.5 سم) لا يتدخل؛ يتحول لوجهي أو قمي أو قيصرية."},{"f":"ما قطر التدخل في المجيء الوجهي؟","b":"القطر تحت الذقني-البرغماوي (Submentobregmatic ≈ 9.5 سم) — الولادة المهبلية ممكنة في الوجهي الذقني الأمامي فقط."},{"f":"هل يمكن الولادة المهبلية العفوية في المجيء الذقني الخلفي؟","b":"لا — الذقني الخلفي (Persistent mentoposterior) لا يولد مهبلياً (يستدعي قيصرية)؛ الذقني الأمامي قد يولد."},{"f":"ما تدبير المجيء المعترض (Transverse lie)؟","b":"قيصرية — المجيء المعترض المفرد لا يولد مهبلياً أبداً (خطر تمزق الرحم وانسدال الحبل)."},{"f":"مجيء معترض + انبثاق أغشية في الأسبوع 37 — ما طريقة الولادة؟","b":"قيصرية فورية — لا تحويل ولا انتظار بعد انبثاق الأغشية."},{"f":"ما أسباب المجيء الوجهي؟","b":"التشوهات الخلقية (انعدام الدماغ)، ورم درقي جنيني، تشنج الرقبة، تعدد الولادات، كثرة السائل."},{"f":"ما اختلاطات الحمل المتعدد؟ وأيها ليس منها؟","b":"الولادة المبكرة، ما قبل الإرجاج، فقر الدم، سوء المجيء، نزف ما بعد الولادة؛ ليس منها: الحمل المديد ولا تمزق العجان."},{"f":"هل تحدث متلازمة نقل الدم التوأمي في التوائم ثنائية البيضة؟","b":"لا — TTTS خاصة بالتوائم أحادية المشيمة (مشيمة مشتركة)؛ ثنائية البيضة لكل مشيمته."},{"f":"في التوأم رأسي-معترض: هل هو استطباب قيصرية؟","b":"لا بالضرورة — التوأم الأول رأسي قد يولد مهبلياً ثم يُقيَّم الثاني؛ المعترض المفرد وحده هو المطلق."},{"f":"ما عوامل خطورة المجيئات المعيبة؟","b":"تعدد الولادات، كثرة/قلة السائل، الحمل المتعدد، ورم رحمي/حوضي، ضيق الحوض، المشيمة المنزاحة؛ ليست الخروسات بحد ذاتها."},{"f":"ما النقطة الاستكشافية في المجيء القمي الأيسر؟ (تذكير)","b":"اليافوخ الخلفي (Occiput) — وليست الجبهة."}]},{"t":"المجيئات الجنينية المعيبة","cards":[{"f":"انسدال الحبل السري النابض متقدماً على المجيء + أغشية سليمة — ما التدبير؟","b":"قيصرية فورية — انسدال الحبل إسعاف (خطر انضغاط الحبل وموت الجنين)؛ لا يُعاد الحبل ولا يُنتظر."},{"f":"ما العوامل المؤهبة لانسدال الحبل السري؟ وأيها ليس منها؟","b":"المجيئات المعيبة، كثرة السائل، الخداج، الحمل المتعدد، الحبل الطويل؛ ليس منها: ارتكاز المشيمة المعيب المركزي."},{"f":"ما أسباب المجيء المقعدي (Breech)؟ وأيها ليس منها؟","b":"الخداج، الحمل المتعدد، كثرة السائل، المشيمة المنزاحة، التشوهات؛ ليس منها: صغر سن الأم."},{"f":"ما شروط الولادة المهبلية للمجيء المقعدي؟","b":"مقعدي صريح/كامل (ليس قدمياً Footling)، وزن تقديري مناسب، حوض كافٍ، رأس غير مفرط الانبساط، مخاض متقدم — وإلا قيصرية."},{"f":"هل فرط انبساط رأس الجنين (Stargazing) يسهّل ولادة المقعدي؟","b":"لا — يصعّبها ويمنع الولادة المهبلية (خطر انحشار الرأس) ← قيصرية."},{"f":"هل التوأم ثنائي الكوريون ثنائي الأمنيون دائماً ثنائي البيضة؟","b":"لا — قد يكون أحادي البيضة انقسم مبكراً (≤3 أيام)؛ القاعدة: أحادي الكوريون = أحادي البيضة دائماً."},{"f":"هل التوائم ثنائية البيضة دائماً من نفس الجنس؟","b":"لا — قد تكون مختلفة الجنس (كأي أخوين)؛ أحادية البيضة دائماً نفس الجنس."},{"f":"خروس بمجيء معترض في بداية المخاض — ما أفضل تدبير؟","b":"قيصرية — المجيء المعترض استطباب مطلق للقيصرية."},{"f":"ما أشيع مجيء مقعدي؟","b":"المقعدي الصريح (Frank breech): الوركان مثنيان والركبتان ممدودتان — أفضل أنواع المقعدي للولادة المهبلية."}]},{"t":"المخاض الشاذ (عسر المخاض)","cards":[{"f":"ما التشخيص الأدق والقطعي لعدم التناسب الحوضي-الجنيني (CPD)؟","b":"تجربة المخاض (Trial of labor) — القياسات الحوضية الشعاعية لا تثبت CPD؛ التشخيص الحقيقي بمراقبة تقدم المخاض."},{"f":"في انعضال الكتفين (Shoulder dystocia): هل يُضغط على قعر الرحم؟","b":"لا — الضغط على القعر (Fundal pressure) ممنوع (يزيد الانعضال)؛ التدبير: مناورة ماكروبرتس، ضغط فوق العانة، مناورات داخلية، شق عجاني."},{"f":"ما عوامل خطورة تمزق الرحم أثناء المخاض؟ وأيها ليس منها؟","b":"سوابق قيصرية/جراحة رحمية، تعدد الولادات، تحريض مفرط بالأوكسيتوسين، المجيء المعترض المهمل؛ ليس منها: وهن العضلة الرحمية ولا سوابق الإسقاط العفوي ولا المخاض السريع."},{"f":"ما علامات تمزق الرحم؟","b":"ألم شديد مفاجئ ثم زواله، توقف التقلصات، تباطؤ قلب الجنين الحاد، نزف مهبلي، صدمة؛ مثال: سوابق قيصرية + ألم شديد + تباطؤ حاد + زوال التقلصات = تمزق رحم."},{"f":"هل التهاب المشيماء والسلى (Chorioamnionitis) مضاد استطباب لتحريض المخاض؟","b":"لا — بل هو استطباب لإنهاء الحمل (التحريض)؛ مضادات التحريض: المشيمة المنزاحة المركزية، المجيء المعترض، انسدال الحبل، سوابق قيصرية كلاسيكية."},{"f":"هل المجيء القمي الخلفي استطباب للقيصرية؟","b":"لا — القمي الخلفي (Occiput posterior) قد يولد مهبلياً (مخاض أطول ومؤلم)؛ الاستطبابات المطلقة: المعترض، المنزاحة المركزية، انسدال الحبل."},{"f":"ما أسباب عسر المخاض (Dystocia) الثلاثة (3P)؟","b":"القوة (Power: تقلصات ضعيفة)، الممر (Passage: ضيق حوض)، الراكب (Passenger: ضخامة/سوء مجيء)."},{"f":"ما تدبير توقف تقدم المخاض في الطور الفعّال؟","b":"تقييم 3P: تمزق الأغشية + أوكسيتوسين إن كانت التقلصات ناقصة؛ قيصرية عند عدم التناسب أو تألم الجنين."},{"f":"ما اختلاطات انعضال الكتفين على الجنين؟","b":"شلل إرب (Erb's palsy — C5-C6)، كسر الترقوة/العضد، اختناق — تُقلَّل بالتدبير الصحيح دون شدّ على الرأس."}]},{"t":"اضطرابات النفاس","cards":[{"f":"ما أشيع سبب لنزف ما بعد الولادة (PPH)؟","b":"العطالة الرحمية (Uterine atony) — الرحم لا يتقبض بعد خروج المشيمة؛ قاعدة 4T: Tone (الأشيع)، Tissue، Trauma، Thrombin."},{"f":"مريضة بما قبل الإرجاج أصيبت بعطالة رحم — بماذا تُدبَّر؟","b":"بالأوكسيتوسين — الإرغوتامين (ميتيل إرغومترين) ممنوع في ارتفاع الضغط (يرفع الضغط وقد يسبب اختلاجاً)."},{"f":"ما تأثير حقن ميتيل إرغومترين وريدياً؟","b":"ارتفاع ضغط الدم (تشنج وعائي) — يُعطى عضلياً ببطء؛ ممنوع وريدياً سريعاً وفي ارتفاع الضغط."},{"f":"ما أخطر اختلاط لتوليد المشيمة بالشد على الحبل السري؟","b":"انقلاب الرحم (Uterine inversion) — إسعاف: إعادة يدوية فورية تحت التخدير + أوكسيتوسين بعد الرد."},{"f":"ما تعريف الحمى النفاسية (Puerperal fever)؟","b":"حرارة ≥38° في يومين من الأيام العشرة الأولى بعد الولادة باستثناء أول 24 ساعة — ليست خلال أول 24 ساعة."},{"f":"ما أشيع سبب لاستمرار ارتفاع الحرارة بعد الولادة؟","b":"التهاب باطن الرحم النفاسي (Endometritis) — حمى + ألم رحمي + هلابة كريهة؛ العلاج: مضادات واسعة (جنتاميسين + كلينداميسين)."},{"f":"ما عوامل خطورة خمج باطن الرحم النفاسي؟ وأيها ليس منها؟","b":"القيصرية، تمزق الأغشية المديد، فحوص مهبلية متكررة، مخاض مديد؛ ليس منها: المخاض السريع ولا قصور الدرق."},{"f":"متى يحدث التهاب الثدي الحاد (Mastitis) عادة؟","b":"في الأسابيع 2-3 بعد الولادة (لا نهاية الأسبوع الثاني حصراً) — احتقان + ألم + حمى؛ المسبب: العنقوديات؛ لا يُوقف الإرضاع."},{"f":"ما العوامل المؤهبة للعطالة الرحمية؟","b":"فرط تمدد الرحم (توائم، كثرة سائل، ضخامة)، مخاض مديد/سريع، تعدد الولادات، إنتان، سكري حملي؛ ضعف التقلصات هو الآلية."},{"f":"ما عوامل خطورة اكتئاب ما بعد الولادة؟ وأيها ليس منها؟","b":"سوابق اكتئاب، دعم اجتماعي ناقص، حمل غير مرغوب، إجهاد؛ ليس منها: تعدد الولادات بحد ذاته."},{"f":"هل نسبة التهاب الوريد الخثري في النفاس أقل منها في الحمل؟","b":"لا — أعلى في النفاس (خاصة بعد القيصرية)؛ الخثار الوريدي من أهم أسباب وفيات الأمهات — الوقاية بالحركة المبكرة."},{"f":"ما الزمر الجرثومية الشائعة في الإنتانات النفاسية؟ وأيها ليس منها؟","b":"العقديات (A وB)، الإشريكية القولونية، اللاهوائيات، الكلاميديا؛ ليست منها: العصيات الزرق (Pseudomonas)."},{"f":"نزف خلاص باكر: هل الإنتان من أسبابه؟","b":"لا — نزف الخلاص الباكر (أول 24 ساعة) أسبابه: عطالة، تمزقات، احتباس؛ الإنتان يسبب نزفاً ثانوياً متأخراً (Subinvolution)."}]},{"t":"العمليات التوليدية","cards":[{"f":"ما الاستطبابات المطلقة للقيصرية؟","b":"المشيمة المنزاحة المركزية، المجيء المعترض، انسدال الحبل السري، عدم التناسب الشديد، تمزق الرحم؛ ليس منها: القمي الخلفي ولا تأخر النمو وحده ولا تطاول الطور الكامن."},{"f":"أي القيصرية أشيع؟ العلوية (كلاسيكية) أم السفلية؟","b":"السفلية المستعرضة (Lower segment) — ندبة أقوى ونزف أقل وتمزق أقل في الحمول التالية؛ العلوية لحالات خاصة (معترض، خداج شديد)."},{"f":"ما شروط تطبيق ملقط الجنين (Forceps)؟ وأيها ليس منها؟","b":"اتساع تام، أغشية مبثوقة، رأس متدخل، مجيء قمي، جنين حي، مثانة فارغة؛ ليس منها: اتساع 7 سم (ناقص) ولا وفاة الجنين."},{"f":"ما شروط التحويل الرأسي الخارجي (ECV)؟","b":"حمل مفرد، مجيء مقعدي غير متدخل، أغشية سليمة، سائل كافٍ، لا موانع للولادة المهبلية؛ مضاد الاستطباب المطلق: الحمل التوأمي."},{"f":"ما استطبابات تحريض المخاض؟ وأيها ليس منها؟","b":"ما قبل الإرجاج، الحمل المديد، تمزق الأغشية، سكري، موت الجنين؛ ليس منها: حالة الجنين غير المطمئنة (استطباب قيصرية) ولا الجنين العرطل وحده."},{"f":"ما الأدوية المستخدمة لتحريض المخاض؟ وأيها ليس منها؟","b":"الأوكسيتوسين، البروستاغلاندينات (ميزوبروستول/دينوبروستون)، تمزق الأغشية؛ ليس منها: الإرغومترين (للنزف لا للتحريض)."},{"f":"ما استطبابات الأوكسيتوسين؟ وأيها ليس منها؟","b":"تحريض/تسريع المخاض، الوقاية من نزف ما بعد الولادة، تدبير الإسقاط الناقص؛ ليس منها: اختبار اللاشدة (NST)."},{"f":"ما اختلاطات الملقط التوليدي؟ وأيها ليس منها؟","b":"تمزقات مهبلية/عجانية، أذية عصب وجهي للجنين، سحجات؛ ليست منها: الحاصّة (فقد الشعر)."},{"f":"ما الذي يدخل في تقييم بيشوب؟ (تذكير بالمستبعدات)","b":"المستبعدات: سلامة الأغشية، لون السائل السلوي، ضربات قلب الجنين — المكونات خمسة فقط (توسع، إمحاء، مستوى، قوام، وضعية)."},{"f":"ما مضادات استطباب تثبيط (إيقاف) المخاض؟","b":"تألم الجنين، إنتان أمنيوسي، نزف شديد، توسع >5 سم، تشوه جنيني قاتل؛ انبثاق الأغشية وحده ليس مضاد استطباب."},{"f":"الشد على الحبل بعد ولادة الجنين يؤهب لـ؟","b":"انقلاب الرحم (Uterine inversion) — لا يُشد الحبل قبل انفصال المشيمة وعلاماتها."},{"f":"ما تدبير المجيء المعترض عند خروس في بداية المخاض؟","b":"قيصرية — الخيار الأفضل والأسرع؛ لا تحويل خارجي بعد بدء المخاض الفعال."},{"f":"هل تطاول الطور الكامن استطباب للقيصرية؟","b":"لا — الطور الكامن قد يطول (خاصة عند الخروسات)؛ يُدبَّر بالراحة والمراقبة لا بالقيصرية الفورية."},{"f":"ما الفرق بين التحريض والتعزيز (Augmentation)؟","b":"التحريض: بدء المخاض اصطناعياً قبل بدئه؛ التعزيز: تسريع مخاض بدأ عفوياً لكنه بطيء — كلاهما بالأوكسيتوسين/تمزق الأغشية."}]},{"t":"الوبائيات في التوليد","cards":[{"f":"ما أسباب الوفيات الوالدية المباشرة؟ وأيها ليس منها؟","b":"النزف، ما قبل الإرجاج/الإرجاج، الإنتان، الصمة الأمنيوسية، الخثار؛ ليست مباشرة: أمراض القلب (غير مباشرة) ولا اكتئاب النفاس ولا انسدال التاجي."},{"f":"ما معدل وفيات الأمهات (MMR)؟ وكيف يُحسب؟","b":"وفيات الأمهات لكل 100,000 ولادة حية — خلال الحمل أو 42 يوماً بعده لأسباب متعلقة بالحمل."},{"f":"ما وفيات حول الولادة (Perinatal mortality)؟","b":"موت الأجنة (≥28 أسبوعاً/≥1000غ) + وفيات الولدان المبكرة (أول 7 أيام) لكل 1000 ولادة — مؤشر جودة الرعاية التوليدية."},{"f":"ما مخاطر حمل المسنات (≥35 سنة)؟ وأيها ليس منها؟","b":"تزيد: ما قبل الإرجاج، سكري حملي، شذوذات صبغية، قيصرية؛ لا يزيد: المخاض الباكر (ليس نمطياً)."},{"f":"ما استقصاءات وفيات حول الولادة؟","b":"تشريح الجنين، فحص المشيمة، زرع، صبغيات؛ التهاب الكبد A ليس من الاستقصاءات النمطية."},{"f":"هل إنهاء الحمل يتطلب موافقة الزوجين؟","b":"الإنهاء الطبي قرار طبي-قانوني بموافقة المرأة (واللجان المختصة) — موافقة الزوج ليست شرطاً طبياً نمطياً."},{"f":"ما العوامل المؤثرة على وفيات الولدان؟","b":"الخداج (الأهم)، انخفاض الوزن، الإنتانات، التشوهات، جودة الإنعاش الوليدي والعناية المركزة."}]},{"t":"حديث الولادة","cards":[{"f":"ما مكونات مشعر أبغار (Apgar)؟ وأيها ليس منها؟","b":"خمسة (0-2 لكل): اللون، النبض، المنعكسات (التهيج)، التوتر العضلي، التنفس — ليس منها: التبول ولا الوزن؛ يُقيَّم في الدقيقة 1 و5."},{"f":"ما تفسير أبغار 7-10 و4-6 و0-3؟","b":"7-10 طبيعي؛ 4-6 متوسط (يحتاج تحفيز/أكسجة)؛ 0-3 شديد (إنعاش كامل) — الأهم أبغار الدقيقة 5."},{"f":"أي الشذوذات الخلقية تستدعي جراحة فورية بعد الولادة؟","b":"رتق المري مع ناسور، فتق الحجاب الحاجز، انسداد معوي؛ لا تستدعي فورية: فتحة بين البطينين VSD (تُتابع)."},{"f":"زرقة مركزية منذ الولادة لا تتحسن بالأكسجين + قلب طبيعي + ظل محيطي بالرئة — ما التشخيص؟","b":"ناسور شرياني-وريدي رئوي خلقي (Pulmonary AVM) — تحويلة يمين-يسار خارج القلب لا تستجيب للأكسجين."},{"f":"ما الخطوة الأولى في إنعاش الوليد؟","b":"التدفئة والتجفيف والتحفيز ووضعية مجرى الهواء — ثم تقييم التنفس والنبض؛ الأكسجة قبل الضغطات."},{"f":"متى يُعطى الأدرينالين في إنعاش الوليد؟","b":"عند نبض <60 رغم التهوية الفعالة والضغطات الصدرية 30 ثانية — وريدياً/داخل العظم."},{"f":"ما سبب الزرقة المركزية المستجيبة للأكسجين مقابل غير المستجيبة؟","b":"المستجيبة: رئوية (ضائقة، ذات رئة)؛ غير المستجيبة: قلبية (تحويلة يمين-يسار) أو ناسور رئوي."}]},{"t":"الوليد ناقص الوزن","cards":[{"f":"ما تعريف الوليد ناقص الوزن (LBW)؟","b":"وزن <2500غ أياً كان العمر الحملي؛ ناقص جداً VLBW <1500غ؛ ناقص بشدة ELBW <1000غ."},{"f":"ما أسباب تحدد النمو داخل الرحم؟ وأيها ليس منها؟","b":"قصور المشيمة، الشذوذات الصبغية، الإنتانات الخلقية، التدخين، ما قبل الإرجاج؛ ليس منها: السكري الحملي (يسبب ضخامة) ولا الخروسات ولا المشيمة المنزاحة."},{"f":"ما الفرق بين الخديج وصغير الحجم للعمر (SGA)؟","b":"الخديج: ولادة <37 أسبوعاً (قد يكون وزنه طبيعياً لعمره)؛ SGA: وزن <10th percentile لعمره (قد يكون تاماً)."},{"f":"ما مضاعفات الخداج؟","b":"متلازمة الضائقة التنفسية (نقص السورفاكتانت)، النزف داخل البطينات، التهاب الأمعاء النخري NEC، اعتلال الشبكية، القناة الشريانية السالكة."},{"f":"متى يُعطى السورفاكتانت؟","b":"للخدج المصابين بمتلازمة الضائقة التنفسية (وقائياً لأقل من 28 أسبوعاً وعلاجياً عند الحاجة) — داخل الرغامى."},{"f":"ما تدبير القناة الشريانية السالكة عند الخديج؟","b":"إندوميتاسين/إيبوبروفين للإغلاق الدوائي؛ الجراحة عند الفشل أو مضاد الاستطباب."},{"f":"ما سبب التهاب الأمعاء والقولون النخري (NEC)؟","b":"الخداج + التغذية المعوية المبكرة + إقفار معوي — بطن منتفخ مدمى + هواء في جدار الأمعاء (Pneumatosis)."},{"f":"كيف تُوقى مضاعفات الخداج قبل الولادة؟","b":"ستيروئيدات قبل الولادة (إنضاج الرئة)، سلفات المغنزيوم (حماية عصبية <32 أسبوعاً)، تأخير قطع الحبل، الولادة في مركز مجهز."}]},{"t":"أسئلة منوعة","cards":[{"f":"في الحمل التوأمي رأسي-معترض: هل هو استطباب قيصرية؟","b":"لا بالضرورة — الأول رأسي يولد مهبلياً ثم يُدبَّر الثاني (تحويل/ولادة مقعدية)؛ القيصرية عند تعذر الولادة المهبلية."},{"f":"ما العرض الأشيع للحصيات البولية في الحمل؟","b":"ألم الخاصرة/البطن مع بيلة دموية — تُدبَّر تحفظياً غالباً (سوائل + مسكنات آمنة)؛ الإنتان المرافق إسعاف."},{"f":"رحم صغير نسبة لعمر الحمل — ما الأسباب؟ وأيها ليس منها؟","b":"خطأ تقدير العمر، IUGR، قلة السائل، موت الجنين؛ ليس منها: الرحى العدارية (تكبّر الرحم)."},{"f":"رحم أكبر من العمر المقدر — ما الأسباب؟ وأيها ليس؟","b":"توائم، كثرة سائل، ضخامة، رحى، ورم ليفي؛ ليس منها: موت محصول الحمل (يصغّر الرحم)."},{"f":"ما أسباب نزوف أشهر الحمل الأولى؟ وأيها ليس منها؟","b":"التهديد بالإسقاط، الحمل الهاجر، الرحى العدارية؛ ليس منها: المشيمة المنزاحة ولا انفكاك المشيمة (نزوف متأخرة)."},{"f":"أي استقصاء يحتاج استشفاءً (تنويماً)؟","b":"تنظير جوف البطن التشخيصي (تخدير عام) — أما الإيكو والتحاليل فخارجية."},{"f":"ما الورم المبيضي الذي يمتاز بكبر حجمه عادة؟","b":"الورم المخاطي (Mucinous) — قد يبلغ أحجاماً ضخمة؛ عكس المصلي."},{"f":"هل العمر >38 سنة مضاد استطباب للولب؟","b":"لا — اللولب آمن وفعال في كل الأعمار؛ مضاداته: حمل، إنتان حوضي، نزف مجهول، تشوه رحمي."},{"f":"ما الفرق بين التوأم أحادي وثنائي البيضة في المشيمية؟","b":"أحادي المشيمة = أحادي البيضة دائماً؛ ثنائي المشيمة قد يكون أحادياً (انقسام ≤3 أيام) أو ثنائياً."}]},{"t":"مواضيع أخرى","cards":[{"f":"ما العرض الأشيع للحصيات البولية في الحمل؟ (تذكير)","b":"ألم مع بيلة دموية (Hematuria) — مع غثيان/إقياء أحياناً؛ يُنفى الإنتان المرافق."},{"f":"ما المسكن الآمن للمغص الكلوي في الحمل؟","b":"الباراسيتامول أولاً؛ تُتجنب مضادات الالتهاب غير الستيروئيدية (خاصة في الثلث الثالث — إغلاق القناة الشريانية)."},{"f":"متى تُحال حصيات الحمل للتداخل؟","b":"عند الإنتان المرافق غير المستجيب، انسداد وحيد الكلية، ألم معند — بدعامة حالبية مؤقتة غالباً حتى الولادة."},{"f":"هل البيلة الدموية المجهرية وحيدة تستدعي القلق في الحمل؟","b":"تستدعي التقييم (زرع بول + إيكو) — الإنتان البولي الصامت شائع ويُعالج لمنع التهاب الحويضة."}]}]},{"s":"الأطفال 2","topics":[{"t":"النمو والبلوغ","cards":[{"f":"متى يبدأ الطفل بالابتسام اجتماعيًا، ومتى يُتقن المشي المستقل، ومتى يجلس بدون دعم؟","b":"الابتسام الاجتماعي: حوالي 6–8 أسابيع؛ الجلوس بدون دعم: حوالي 6–8 أشهر؛ المشي المستقل: حوالي 12–15 شهرًا. التأخر عن هذه المعالم يوجّه لتقييم النمو الحركي والعصبي."},{"f":"طفل 18 شهرًا لا ينطق أي كلمة مفهومة: ما التقييم الأول؟","b":"غياب أي كلمة بعمر 18 شهرًا تأخر لغوي → التقييم الأول هو فحص السمع (Audiometry)، ثم تقييم التواصل الاجتماعي (استبعاد طيف التوحد)."},{"f":"طفل 6 سنوات: ما الذي يقيّم التطور اللغوي والإدراكي معًا بشكل عملي؟","b":"القدرة على رسم رجل من 6 أجزاء وتقليد مربع، ومعرفة الاتجاهات (يمين/يسار)، ورواية قصة متماسكة. تأخر النمو الحركي الدقيق مع اللغوي يوجّه لاضطراب نمائي شامل."},{"f":"تتابع تطور البلوغ عند الذكور والإناث: ما أول علامة عند كل منهما؟","b":"الإناث: نمو الثدي (Thelarche) حوالي 8–13 سنة؛ الذكور: تضخم الخصيتين (حجم >4 مل) حوالي 9–14 سنة. تسلسل مارشال-تانر: الثدي ثم شعر العانة ثم الحيض (حوالي 12–13 سنة)."},{"f":"تعريف البلوغ المبكر (Precocious puberty): العمر القاطع عند الجنسين؟","b":"ظهور علامات البلوغ قبل 8 سنوات عند الإناث وقبل 9 سنوات عند الذكور. الأكثر شيوعًا: مبكر مركزي مجهول السبب عند البنات؛ عند الذكور يجب دائمًا البحث عن سبب عضوي (ورم CNS)."},{"f":"طفل 10 سنوات: طوله تحت الشريط الثالث، سرعة النمو طبيعية، العمر العظمي متأخر: التشخيص؟","b":"قصر قامة بنيوي/تأخر النمو البنيوي (Constitutional growth delay): نمو طبيعي السرعة مع تأخر عمر عظمي وبلوغ متأخر — إنذار جيد والطول النهائي طبيعي عادة. يُفرَّق عن عوز هرمون النمو (سرعة نمو منخفضة)."},{"f":"ما الفرق بين قصر القامة العائلي وقصر القامة البنيوي في العمر العظمي؟","b":"العائلي (Familial): العمر العظمي مساوٍ للعمر الزمني، والوالدان قصيران. البنيوي: العمر العظمي متأخر عن الزمني مع بلوغ متأخر. كلاهما سرعة نمو طبيعية — يختلفان عن الأسباب المرضية (سرعة نمو منخفضة)."},{"f":"في أي عمر يُغلق اليافوخ الأمامي عادة، ومتى يصبح عدم إغلاقه مرضيًا؟","b":"يُغلق بين 9–18 شهرًا (عادة ~12–15 شهرًا). بقاؤه مفتوحًا بعد 18–24 شهرًا يوجّه ل: كساح، قصور درق خلقي، استسقاء دماغ، خلل التنسج الترقوي القحفي."},{"f":"طفل عمره 4 سنوات: وزنه على الشريط 95 والطول على الشريط 50 — كيف تُفسَّر؟","b":"بدانة طفولة: الوزن مرتفع نسبة للطول (BMI ≥ الشريط 95 للعمر والجنس = بدانة). عند الأطفال يُستخدم شريط BMI العمري الجنسي لا القيمة المطلقة."},{"f":"متى يُشتبه بقصور الدرق الخلقي سريريًا قبل نتيجة المسح؟","b":"رضيع خامل: بطء رضاعة، إمساك، يرقان مطوّل، بكاء أجش، فتق سري، جفاف جلد، يافوخ واسع. القاعدة الذهبية: برامج المسح الوليدي — العلاج المبكر بالثيروكسين يمنع التخلف العقلي."},{"f":"رضيع 9 أشهر لا يجلس ولا يتدحرج: ما الخطوة الأولى؟","b":"تأخر حركي جسيم (لا جلوس بعمر 9 أشهر) → إحالة عصبية نمائية عاجلة + تقييم شامل (سمع، بصر، درق، استقلاب). لا تُؤجَّل بذريعة «كل طفل وتيرته»."},{"f":"طفلة 7 سنوات: نمو ثدي أحادي الجانب مؤلم منذ شهرين فقط: التشخيص والتدبير؟","b":"غالبًا Thelarche مبكر معزول/حميد (Premature thelarche): أحادي، بلا علامات بلوغ أخرى، لا تسارع نمو → مراقبة فقط. التحويل للغدد إذا: ثنائي متقدم، شعر عانة، تسارع نمو/عمر عظمي."}]},{"t":"أمراض الجهاز الهضمي","cards":[{"f":"رضيع 3 أسابيع: إقياءات قذفية غير صفراوية بعد كل رضعة + كتلة زيتونية بالشرسوف: التشخيص والاضطراب الشاردي؟","b":"تضيق البواب الضخامي الخلقي (CHPS): إقياء قذفي غير صفراوي بعمر 2–6 أسابيع. الشوارد: قلاء استقلابي ناقص الكلور مع نقص بوتاسيوم (فقدان حمض المعدة) — يُصحَّح قبل الجراحة."},{"f":"رضيع 8 أشهر: نوب بكاء متقطعة + براز هلام الكشمش الأحمر + كتلة بطنية: التشخيص والعلامة الشعاعية؟","b":"انغلاف معوي (Intussusception): ثلاثية (ألم متقطع، براز مدمى مخاطي، كتلة). الإيكو: علامة الدونات/Bull's eye؛ الحقنة الشرجية: علامة المخلب (Claw sign) — وهي علاجية أيضًا بالرد الهوائي."},{"f":"وليد: إقياء صفراوي + انتفاخ بطن + عدم خروج العقي خلال 24 ساعة: التشخيص الأول؟","b":"انسداد معوي ولادي — داء هيرشسبرونغ (غياب العقد العصبية): تأخر خروج العقي >24–48 ساعة + إقياء صفراوي. التشخيص: خزعة مستقيم (غياب الخلايا العقدية)."},{"f":"طفل 5 سنوات: ألم بطني حول السرة متكرر صباح أيام المدرسة فقط، فحص سوي: التشخيص؟","b":"ألم بطني وظيفي (Functional abdominal pain): نمط مدرسي، بلا علامات خطر (لا نقص وزن، لا إقياء، لا دم، لا ألم ليلي يوقظ) → طمأنة ومتابعة، لا استقصاءات موسعة."},{"f":"ما علامات الخطر (Red flags) في الألم البطني المزمن عند الأطفال؟","b":"نقص وزن/فشل نمو، ألم يوقظ من النوم، دم بالبراز، إقياء متكرر، ألم بعيد عن السرة، التهاب مفاصل، قصة عائلية IBD. وجودها = استقصاء عضوي (داء بطني/IBD/قرحة)."},{"f":"طفل 3 سنوات: إسهال مائي حاد + تجفاف متوسط: ما أساس التدبير؟","b":"محلول الإماهة الفموي (ORS) منخفض الأسمولية هو حجر الأساس؛ يُستأنف الإرضاع/التغذية فورًا. الصادات فقط للكوليرا/شيغيلا/أميبا. مضادات الحركة (لوبراميد) ممنوعة عند الأطفال."},{"f":"رضيع: إقياءات متكررة بلا فشل نمو والفحص سوي: التشخيص والتدبير؟","b":"قلس معدي مريئي فيزيولوجي (GER): شائع، يتحسن بعمر 12–18 شهرًا. التدبير: تقليل حجم الرضعات، التجشؤ، إبقاء الرضيع مرفوعًا — لا أدوية ولا استقصاء بلا علامات خطر."},{"f":"طفل 8 سنوات: إسهال مزمن + فشل نمو + فقر دم بعوز حديد: أول استقصاء؟","b":"الداء البطني (Celiac): أضداد anti-tTG-IgA + IgA كلي أولًا (بعمر >2–3 سنوات على حمية تحوي الغلوتين). التأكيد: خزعة عفج (ضمور زغابات)."},{"f":"ما الفرق السريري بين داء كرون والتهاب القولون التقرحي عند الأطفال؟","b":"كرون: أي جزء من الفم للشرج، ألم بطني، فشل نمو/تأخر بلوغ، آفات حول الشرج، التهاب transmural. التقرحي: قولون فقط، إسهال مدمى هو الغالب، التهاب مخاطي سطحي."},{"f":"وليد أم مصابة بالتهاب كبد B (HBsAg+): التدبير الأمثل؟","b":"الغلوبولين المناعي الخاص (HBIG) + لقاح التهاب الكبد B خلال 12 ساعة من الولادة — يمنع الانتقال العمودي بنسبة عالية. لا يُمنع الإرضاع الوالدي."},{"f":"رضيع 6 أسابيع: يرقان + براز طيني (أكولي) + بول داكن + ضخامة كبد: التشخيص؟","b":"رتق القنوات الصفراوية (Biliary atresia): يرقان انسدادي بعمر 2–6 أسابيع. التشخيص المبكر حاسم — عملية كاساي قبل 60 يومًا تحسّن الإنذار."},{"f":"طفل: ألم شرسوفي ليلي يتحسن بالطعام + قصة عائلية قرحة: التشخيص والعلاج؟","b":"قرحة عفجية (غالبًا H. pylori): التشخيص بتنظير + خزعة/اختبار يورياز. العلاج: ثلاثي (مثبط مضخة + كلاريثروميسين + أموكسيسيلين) 14 يومًا."},{"f":"ما الاستطبابات المطلقة لتنظير الجهاز الهضمي العلوي عند الأطفال؟","b":"نزف هضمي، ابتلاع جسم أجنبي/مادة كاوية، فشل نمو مع شك عضوي، تأكيد الداء البطني/IBD، دوالي مريء مشتبهة. القلس البسيط بلا علامات خطر ليس استطبابًا."}]},{"t":"الأمراض الخمجية والمناعة","cards":[{"f":"وليد 10 أيام: حرارة + هياج + يافوخ متوتر: ما الجرثومان الأكثر احتمالًا، وما التدبير الإسعافي؟","b":"العقديات B (GBS) ثم E. coli هما الأشيع بعمر <شهر. التدبير: بزل قطني + زرع دم + صادات وريدية فورية (أمبيسيلين + سيفوتاكسيم/أمينوغليكوزيد) — لا يُنتظر الزرع."},{"f":"ما الوقاية من خمج الوليد الباكر بالعقديات B (GBS)؟","b":"مسح مهبلي-مستقيمي بعمر 35–37 أسبوعًا؛ الأم الإيجابية → بنسلين وريدي أثناء المخاض (Penicillin G). يقي من الخمج الباكر (<7 أيام) لا المتأخر."},{"f":"طفل 3 سنوات: حرارة 5 أيام + التهاب ملتحمة + شفاه فراولية + عقد لمفاوية رقبية + طفح: التشخيص والعلاج؟","b":"داء كاوازاكي: المعايير (حرارة ≥5 أيام + 4 من 5: ملتحمة، شفاه/فم، طفح، وذمة/تقشر أطراف، عقدة رقبية). العلاج: IVIG خلال 10 أيام + أسبرين — يمنع أم الدم التاجية."},{"f":"طفل 6 سنوات: التهاب بلعوم + طفح قرمزي + لسان فراولة: العامل المسبب والاختلاط المتأخر؟","b":"العقديات المقيحة A (الحمى القرمزية). الاختلاطات المتأخرة: الحمى الرثوية (2–4 أسابيع) والتهاب الكبب والكلية (1–3 أسابيع). العلاج: بنسلين/أموكسيسيلين 10 أيام."},{"f":"ما الفرق الزمني بين التهاب الكبب والكلية التالي للعقديات والحمى الرثوية؟","b":"الكبب والكلية: 1–3 أسابيع بعد التهاب البلعوم/الجلد، مع نقص C3. الحمى الرثوية: 2–4 أسابيع بعد البلعوم فقط، معايير جونز. كلاهما تالٍ للعقديات A — لا يعالَج بالصادات بعد حدوثهما."},{"f":"رضيع 4 أشهر: سعال نوبي تشنجي + شهقة (Whoop) + إقياء بعد السعال: التشخيص والوقاية؟","b":"السعال الديكي (Bordetella pertussis): الصادات (أزيثروميسين) تُقلل العدوى لا السعال. الوقاية: لقاح DTP بعمر 2-4-6 أشهر؛ التمنيع الحلقي للمخالطين."},{"f":"طفل 5 سنوات: طفح حويصلي حاك معمم يبدأ من الجذع: التشخيص ومتى يعود للمدرسة؟","b":"الحماق (Varicella): حويصلات بمراحل مختلفة (زهرة النجوم). العودة للمدرسة بعد جفاف كل الحويصلات وتقشرها (~5–7 أيام). الأسبرين ممنوع (متلازمة راي)."},{"f":"ما أشيع اختلاط عصبي للحماق عند الأطفال؟","b":"التهاب المخيخ (Ataxia) — يظهر بعد أيام من الطفح، رنح واضطراب مشية، غالبًا حميد ويشفى عفويًا. الأخطر: التهاب الدماغ (نادر)."},{"f":"طفل 7 سنوات: حرارة + ألم أذن + غشاء طبل محتقن منتفخ: أشيع جرثوم والعلاج؟","b":"العقديات الرئوية (ثم المستدمية النزلية): التهاب أذن وسطى حاد. العلاج: أموكسيسيلين جرعة عالية 7–10 أيام؛ الأموكسيسيلين-كلافولانات عند الفشل أو التهاب متكرر."},{"f":"رضيع 20 يومًا: حرارة 38.5 بلا بؤرة: ما التدبير؟","b":"وليد محموم <28 يومًا = إنتان خطير حتى يثبت العكس: قبول + زرع دم وبول + بزل قطني + صادات وريدية فورية. لا يُكتفى بالمراقبة."},{"f":"طفل: عضة كلب سائبة: ما تدبير الجرح والوقاية من الكلب؟","b":"غسل الجرح بالماء والصابون 15 دقيقة + لقاح الكلب (4–5 جرع) + غلوبولين مناعي حول الجرح للحالات الشديدة. تقييم الكزاز أيضًا."},{"f":"ما اللقاحات الحية الممنوعة عند الطفل مثبط المناعة؟","b":"كل اللقاحات الحية المضعفة: MMR، الحماق، شلل الأطفال الفموي (OPV)، BCG، الحمى الصفراء. المسموحة: المعطلة (DTP، شلل عضلي IPV، التهاب كبد، رئويات)."},{"f":"طفل 4 سنوات: إسهال مدمى بعد 5 أيام من إسهال مائي + شحوب + قلة صفيحات: التشخيص؟","b":"المتلازمة الانحلالية اليوريميائية (HUS) التالية لـ E. coli O157:H7: ثلاثية (فقر دم انحلالي ميكرووعائي، نقص صفيحات، قصور كلوي حاد). الصادات ومضادات الحركة تزيد الخطر — ممنوعة."},{"f":"ما الفرق بين HUS النموذجية واللانموذجية (aHUS)؟","b":"النموذجية: تالية لإسهال (شيغا توكسين)، أطفال صغار، إنذار أفضل. اللانموذجية: بلا إسهال، خلل بالمتممة، نكسات، قد تحتاج إيكيوليزوماب — إنذار أسوأ."},{"f":"طفل: لدغة عقرب مع ألم شديد وتعرق وهياج: التدبير؟","b":"التهدئة + تسكين قوي + مراقبة قلبية تنفسية؛ المصل المضاد عند العلامات الجهازية الشديدة. معظم اللدغات موضعية وتُدبَّر تحفظيًا."}]},{"t":"التحسس","cards":[{"f":"طفل 8 سنوات: عطاس + حكة أنف وعين موسمية كل ربيع: التشخيص والعلاج الأول؟","b":"التهاب أنف تحسسي موسمي: العلاج الأول مضاد هيستامين فموي (سيتريزين/لوراتادين) + ستيروئيد أنفي موضعي عند الشدة. تجنب المحرض."},{"f":"ما الفرق بين الشرى الحاد والشرى المزمن عند الأطفال؟","b":"الحاد: <6 أسابيع، غالبًا تالٍ لخمج فيروسي أو دواء/غذاء — يشفى عفويًا. المزمن: >6 أسابيع، غالبًا مجهول السبب — مضاد هيستامين يومي طويل، ونادرًا ما يكون تحسسًا غذائيًا."},{"f":"رضيع 6 أشهر: أكزيما وجه + إسهال مدمى بعد حليب البقر: التشخيص والتدبير؟","b":"تحسس بروتين حليب البقر (CMPA): إيقاف حليب البقر → حليب مهدرج كليًا (extensively hydrolyzed). معظم الحالات تتحسن بعمر 2–3 سنوات — يُعاد التحدي لاحقًا."},{"f":"طفل: شرى + وذمة شفاه + أزيز بعد فول سوداني بدقائق: التدبير الإسعافي؟","b":"تأق (Anaphylaxis): أدرينالين عضلي فوري (0.01 ملغ/كغ حتى 0.5 ملغ) بالفخذ — لا يُؤجَّل. ثم أكسجين، سوائل، مضاد هيستامين وستيروئيد كعلاج مساعد فقط."},{"f":"ما الأطعمة الأكثر تسببًا بالتحسس الغذائي عند الأطفال؟","b":"حليب البقر، البيض، الفول السوداني، المكسرات، الصويا، القمح، السمك، المحار. حليب/بيض/صويا/قمح غالبًا عابرة؛ الفول السوداني/المكسرات/السمك غالبًا دائمة."},{"f":"طفل 10 سنوات: ربو + حساسية أنف: ما دور العلاج المناعي (Desensitization)؟","b":"يُفيد في التهاب الأنف التحسسي والربو التحسسي المثبت باختبار وخز إيجابي لمحرض وحيد (عث الغبار/حبوب لقاح) — 3–5 سنوات. لا يُستخدم في التأق الغذائي الشديد."},{"f":"رضيع: أكزيما شديدة معممة + إنتانات جلدية متكررة: ما المشتبه؟","b":"التهاب جلد تأتبي شديد — ابحث عن: تحسس غذائي مرافق، نقص مناعة (متلازمة فرط IgE/جوب) عند الإنتانات المتكررة الغريبة. الأساس: ترطيب + ستيروئيد موضعي."}]},{"t":"الاضطرابات التنفسية","cards":[{"f":"رضيع 9 أشهر: سعال وزلة بعد رشح بأيام + خراخر منتشرة + تطاول زفير: التشخيص؟","b":"التهاب القصيبات الشعرية (Bronchiolitis) — RSV الأشيع بعمر <2 سنة. التدبير داعم (أكسجين، إماهة)؛ الصادات والستيروئيدات لا تفيد روتينيًا."},{"f":"متى يُقبَل الرضيع المصاب بالتهاب القصيبات في المستشفى؟","b":"نوب توقف تنفس، سوء رضاعة/تجفاف، أكسجة <90–92%، عمر <6–12 أسبوعًا، خمج مرافق. الوزيز المنتشر وحده ليس استطباب قبول."},{"f":"طفل سنتان: سعال نباحي ليلي + صرير شهيقي + حرارة خفيفة بلا إلعاب: التشخيص والعلاج؟","b":"كروب فيروسي (التهاب حنجرة ورغامى): ديكساميتازون فموي جرعة وحيدة (0.15–0.6 ملغ/كغ) — الخط الأول. الإبينفرين الإرذاذي للحالات المتوسطة-الشديدة فقط."},{"f":"ما الفرق السريري بين الكروب الفيروسي والتهاب لسان المزمار؟","b":"الكروب: سعال نباحي، بلا إلعاب، طفل غير سام. لسان المزمار (H. influenzae): إلعاب، صعوبة بلع، وضعية شم رائحة، طفل سام محموم — لا يُفحص البلعوم، يُنقَل للعناية فورًا."},{"f":"طفل 7 سنوات: سعال ليلي + أزيز مع الجهد والدخان: التشخيص وعلاج النوب الخفيفة المتقطعة؟","b":"ربو قصبي: النوب الخفيفة المتقطعة → منبه بيتا-2 قصير إنشاقي (سالبوتامول) وقت الحاجة فقط. التشخيص: أزيز متكرر قابل للعكس + قصة عائلية/تأتب."},{"f":"ما علاج هجمة الربو الحادة المتوسطة عند الطفل؟","b":"سالبوتامول إرذاذي متكرر + ستيروئيد جهازي مبكر (بريدنيزولون فموي) + أكسجين. الإبينفرين العضلي للتأق لا للربو؛ السالميترول (طويل الأمد) ليس للهجمة."},{"f":"ما علامات الربو الشديد المهدد للحياة عند الطفل؟","b":"صمت صدري (غياب الوزيز)، صعوبة كلام، زرقة، إنهاك/اضطراب وعي، نبض متناقض، أكسجة <90%. الصمت الصدري أخطر من الوزيز الشديد."},{"f":"طفل 4 سنوات: استنشاق جسم أجنبي + وزيز أحادي الجانب: أول استقصاء؟","b":"صورة صدر بوضعية الزفير (تُظهر انحباس الهواء/انزياح المنصف). الجسم غير الظليل لا يظهر — التشخيص سريري. العلاج: تنظير قصبي صلب لاستخراجه."},{"f":"طفلة 7 سنوات: سعال 3 أيام + حرارة 38.5 + خراخر منتشرة + صورة: ذات رئة وقصبات: العامل الأرجح؟","b":"الميكوبلازما الرئوية (ذات رئة لانموذجية بعمر المدرسة): سعال جاف مستمر، حالة عامة حسنة نسبة للصورة. العلاج: ماكروليد (أزيثروميسين)."},{"f":"طفل 3 سنوات: إنتانات رئوية متكررة + فشل نمو + براز دهني ضخم: التشخيص؟","b":"الداء الليفي الكيسي (CF): عوز قناة الكلور CFTR — رئة (إنتانات متكررة) + بنكرياس (سوء امتصاص دهون). التشخيص: اختبار العرق (كلور >60) + وراثي."},{"f":"ما التظاهر الوليدي الأشيع للداء الليفي الكيسي؟","b":"العقي العقيقي (Meconium ileus) — انسداد معوي ولادي. كل وليد بعقي عقيقي يُفحص للداء الليفي الكيسي."},{"f":"رضيع 3 أشهر: سعال نوبي تشنجي + صورة صدر طبيعية + وزيز خفيف: التشخيص؟","b":"السعال الديكي بعمر صغير قد يأتي بلا شهقة واضحة — سعال نوبي + إقياء/زرقة. التشخيص: PCR مسحة أنفية. العزل والماكروليد للمخالطين."},{"f":"ما الذي يميز التهاب القصيبات عن الربو عند الرضيع؟","b":"القصيبات: أول نوبة بعمر <2 سنة بعد رشح فيروسي، خراخر + وزيز، لا تستجيب لموسعات القصبات عادة. الربو: نوب متكررة قابلة للعكس، قصة تأتب عائلية، استجابة للسالبوتامول."},{"f":"طفل: توقف تنفس انسدادي نومي + شخير + تنفس فموي نهارًا: السبب الأشيع والعلاج؟","b":"ضخامة الناميات (Adenoid hypertrophy): الأشيع بعمر 2–6 سنوات. العلاج: استئصال الناميات عند الشدة/التهابات متكررة/سوء إطباق."},{"f":"ما لقاحات الوقاية من ذات الرئة الجرثومية عند الأطفال؟","b":"لقاح الرئويات المقترن (PCV) ولقاح المستدمية النزلية B (Hib) ضمن التمنيع الروتيني — خفّضا ذات الرئة والتهاب السحايا جذريًا."}]},{"t":"الاضطرابات القلبية","cards":[{"f":"ما مكونات رباعي فالو الأربعة، وما منظر القلب على الصورة؟","b":"تضيق رئوي + VSD + تراكب الأبهر + ضخامة بطين أيمن. الصورة: قلب بشكل الحذاء (Boot-shaped/Sabot) مع نقص التوعية الرئوية."},{"f":"طفل رباعي فالو: نوبة زرقة شديدة (Tet spell): التدبير الإسعافي؟","b":"وضعية الركبة-الصدر + أكسجين + مورفين + سوائل؛ عند الشدة: فينيل إفرين/إسمولول. العلاج الجذري: إصلاح جراحي كامل."},{"f":"وليد: زرقة مركزية من اليوم الأول لا تتحسن بالأكسجين: التشخيص الأرجح؟","b":"تبادل منشأ الأوعية الكبيرة (TGA): زرقة لا تستجيب للأكسجين 100% (اختبار فرط الأكسجة سلبي) — بعكس الزرقة الرئوية التي تتحسن."},{"f":"ما العلامة السمعية المميزة لعيب الحاجز الأذيني (ASD)؟","b":"انقسام الصوت الثاني ثابت لا يتأثر بالتنفس (Fixed split S2) + نفخة انقباضية دفعية بالورب الثاني الأيسر. معظم الحالات لا عرضية حتى البلوغ."},{"f":"ما صفات نفخة عيب الحاجز البطيني (VSD)، ومتى تكون أشد؟","b":"نفخة انقباضية شاملة (Pansystolic) بالورب الثالث-الرابع الأيسر. المفارقة: النفخة أشد كلما كان العيب أصغر (فرق ضغط أكبر) — العيب الكبير قد يكون بلا نفخة مسموعة."},{"f":"ما الدواء الذي يغلق القناة الشريانية السالكة عند الخدج؟","b":"الإيبوبروفين (أو الإندوميتاسين) — مثبطات COX تغلق القناة. البروستاغلاندين E1 يُبقيها مفتوحة (للآفات المعتمدة على القناة)."},{"f":"أي آفة قلبية ولادية لا تحتاج وقاية من التهاب الشغاف؟","b":"عيب الحاجز الأذيني الثانوي المعزول (ASD) — خطر التهاب الشغاف فيه ضئيل. الوقاية (أموكسيسيلين قبل إجراءات الأسنان) للآفات عالية الخطر: صمامات صنعية، سوابق شغاف، آفات مزرقة."},{"f":"ما معايير جونز الكبرى الخمسة للحمى الرثوية؟","b":"التهاب قلب، التهاب مفاصل متنقل، رقص سيدنهام، حمامى هامشية، عقيدات تحت جلدية. (الألم المفصلي وCRP وASLO ليست كبرى)."},{"f":"طفل 10 سنوات: نفخة انقباضية بالورب الثاني الأيمن تنتشر للعنق + نبض ضعيف: التشخيص؟","b":"تضيق الصمام الأبهري: نفخة دفعية بالورب الثاني الأيمن + انتشار للسباتيين + نبض ضعيف متأخر. قد يسبب غشي جهدي — الأخطر بين الآفات غير المزرقة."},{"f":"وليد أم مصابة بذأب حمامي جهازي: ما الخطر القلبي؟","b":"حصار قلب تام ولادي (أضداد anti-Ro/La تعبر المشيمة وتصيب العقدة). يُكشف ببطء قلب جنيني — قد يحتاج ناظمة دائمة."},{"f":"ما صفات النفخة البريئة عند الأطفال؟","b":"ناعمة، انقباضية، قصيرة، تتغير بالوضعية، بلا هرير، بلا أعراض، طفل نامٍ طبيعيًا. الهرير أو النفخة الانبساطية أو المستمرة = عضوية حتى يثبت العكس."},{"f":"طفل متلازمة داون: ما الآفة القلبية الأشيع؟","b":"تشوه الوسادة الشغافية (Endocardial cushion defect / AV canal) — الأشيع في داون. يُمسح كل وليد داون بإيكو قلب."},{"f":"ما الآفات القلبية المعتمدة على القناة الشريانية؟","b":"التضيقات الشديدة اليسرى (تضيق أبهر حرج، متلازمة القلب الأيسر ناقص التنسج) واليمنى (رتق رئوي) وTGA — تتدهور عند إغلاق القناة → بروستاغلاندين E1 إسعافي."},{"f":"طفل: قصور قلب — ما علاماته عند الرضع؟","b":"سوء رضاعة، تعرق مع الرضاعة، تسرع تنفس، فشل نمو (الوزن يتأثر قبل الطول)، ضخامة كبد. الوذمات متأخرة عند الرضع بعكس البالغين."}]},{"t":"اضطرابات الكلية والمسالك البولية","cards":[{"f":"طفل 6 سنوات: وذمات + بيلة بروتينية ضخمة + ألبومين منخفض + شحوم مرتفعة: التشخيص والعلاج؟","b":"التناذر النفروزي (أشيع: قليل التبدلات بعمر 2–8 سنوات): العلاج الأول بريدنيزولون 2 ملغ/كغ/يوم. المستجيب للستيروئيد: ضغط طبيعي، بلا بيلة دموية عيانية، عمر >1 سنة."},{"f":"ما علامات الإنذار السيئ في التناذر النفروزي عند الطفل؟","b":"ارتفاع ضغط، بيلة دموية عيانية، نقص C3، عمر <1 سنة أو >10 سنوات، قصور كلوي — توجّه لنفروز غير قليل التبدلات (يحتاج خزعة)."},{"f":"طفل 8 سنوات: بيلة دموية + وذمات خفيفة + ارتفاع ضغط بعد أسبوعين من التهاب بلعوم: التشخيص والعلامة المخبرية؟","b":"التهاب كبب وكلية حاد تالٍ للعقديات (PSGN): نقص C3 المميز (يعود طبيعيًا خلال 8 أسابيع). العلاج داعم؛ الصادات لا تفيد بعد حدوثه."},{"f":"طفل: بيلة دموية عيانية تتزامن مع كل رشح (خلال أيام): التشخيص؟","b":"اعتلال الكلية بـ IgA (داء برغر): بيلة دموية متزامنة مع الإنتان التنفسي (بعكس PSGN المتأخرة 1–3 أسابيع)، ضغط وحالة عامة عادة سويّة."},{"f":"رضيع 7 أشهر: حرارة 4 أيام بلا بؤرة: ما التشخيص الذي يجب البحث عنه؟","b":"خمج السبيل البولي — الأشيع كسبب خفي للحرارة بلا بؤرة عند الرضع. التشخيص: زرع بول (قسطرة/وخز فوق عاني عند الرضع، عينة وسطى عند الأكبر)."},{"f":"ما العلامة البولية التي تثبت إنتانًا جرثوميًا (وليست تلوثًا)؟","b":"النتريت إيجابي (جراثيم تحوّل النترات لنتريت) + إستراز الكريات البيض. الزرع هو الذهبي: >50,000 مستعمرة/مل بعينة قسطرة عند الرضيع."},{"f":"طفل 4 سنوات: ألم بطني ماغص + بيلة دموية + فرفرية مجسوسة على الأليتين والساقين: التشخيص؟","b":"فرفرية هينوخ-شونلاين (التهاب وعائي بـ IgA): رباعية (فرفرية مجسوسة، ألم بطني، التهاب مفاصل، إصابة كلوية). المراقبة الكلوية لشهور إلزامية."},{"f":"هل تُعطى الستيروئيدات لكل مرضى هينوخ-شونلاين؟","b":"لا — للستيروئيدات دور في الألم البطني/المفصلي الشديد فقط، ولا تمنع الإصابة الكلوية ولا تُعطى روتينيًا لكل المرضى."},{"f":"ما السبب الأشيع للداء الكلوي المزمن عند الأطفال؟","b":"التشوهات البنيوية الخلقية (عسرة تصنع/انسدادات بولية خلقية) — بعكس البالغين (سكري/ضغط). لذلك: كل خمج بولي متكرر عند طفل = تصوير كلية وسبيل بولي."},{"f":"طفلة 7 سنوات: سلس بولي ليلي ثانوي (كانت جافة ثم عادت): الخطوة الأولى؟","b":"فحص بول وراسب أولًا — السلس الثانوي يستوجب نفي: خمج بولي، سكري (بيلة سكرية)، إمساك، اضطراب نفسي. لا يُعالَج كسلس أولي قبل ذلك."},{"f":"ما استطبابات التحال (الديلزة) عند الطفل المصاب بقصور كلوي حاد؟","b":"فرط بوتاسيوم مقاوم، حماض شديد مقاوم، فرط سوائل (وذمة رئة)، اعتلال دماغي يوريميائي، pericarditis يوريميائية. القلاء الاستقلابي وحده ليس استطبابًا."},{"f":"طفل: فتق إربي مختنق لا يُرَد يدويًا: التدبير؟","b":"جراحة إسعافية فورية — لا يُنتظَر زوال الوذمة عند فشل الرد اليدوي (خطر اختناق الأمعاء/الخصية). الفتق الإربي عند الأطفال يُصلَّح جراحيًا دائمًا."},{"f":"ما الفرق بين البيلة البروتينية العابرة والدائمة عند الطفل؟","b":"العابرة: بعد حرارة/جهد/تجفاف — تختفي بالإعادة صباحًا. الدائمة أو النفروزية (>40 ملغ/م²/ساعة) = مرض كببي يستوجب تقييمًا."},{"f":"طفل بعد خمج بولي علوي (التهاب حويضة وكلية): ما التصوير اللاحق؟","b":"إيكو كلية وسبيل بولي للجميع؛ تصوير المثانة الإحليلي (VCUG) عند: عمر <2 سنة، خمج متكرر، إيكو شاذ — لنفي الجزر المثاني الحالبي."}]},{"t":"اضطرابات الأعضاء التناسلية","cards":[{"f":"في أي عمر يكون اختناق الفتق الإربي أشيع: الرضع أم الأطفال الكبار؟","b":"الرضع (خاصة الخدج) — القناة الإربية ضيقة والحلقة واسعة نسبيًا. أي فتق إربي عند طفل = إصلاح جراحي اختياري قريب، والإسعافي عند الاختناق."},{"f":"هل جراحة الإحليل التحتي إسعافية؟ ومتى تُجرى؟","b":"ليست إسعافية — تُجرى اختياريًا بعمر 6–18 شهرًا. ممنوع الختان قبل الإصلاح (القلفة تُستخدم في الترميم)."},{"f":"طفل 12 سنة: ألم صفن حاد مفاجئ + خصية مرتفعة عرضية: التشخيص والتدبير؟","b":"انفتال الخصية: إسعاف جراحي خلال 6 ساعات (تفقد الخصية بعدها). علامة Prehn سلبية (الألم لا يخف برفع الصفن) — بعكس التهاب البربخ."},{"f":"ما الذي يُفرِّق انفتال الخصية عن التهاب البربخ سريريًا؟","b":"الانفتال: ألم مفاجئ شديد، خصية مرتفعة/عرضية، غياب منعكس المشمرة، Prehn سلبي. البربخ: ألم تدريجي، حرارة، Prehn إيجابي (يخف الألم برفع الصفن)."},{"f":"طفل 3 سنوات: قيلة مائية (Hydrocele) غير متوترة: التدبير؟","b":"مراقبة — معظمها تتراجع بعمر 1–2 سنة (قيلة اتصالية). الجراحة عند: استمرارها بعد سنتين، ضخامتها، أو الشك بفتق مرافق."},{"f":"وليد: خصية غير نازلة (Cryptorchidism) ثنائية + صغر قضيب: ما الاستقصاء الأول؟","b":"نفي اضطراب التمايز الجنسي/عوز هرموني: كاريوتايب + هرمونات (تستوستيرون، LH/FSH). الخصية غير النازلة الأحادية: مراقبة حتى 6 أشهر ثم تثبيت جراحي بعمر 6–12 شهرًا."}]},{"t":"اضطرابات الكبد","cards":[{"f":"ما العلاج النوعي لداء ويلسون؟","b":"البنسيلامين (مخلّب النحاس) — أو التريينتين/الزنك. التشخيص: سيرولوبلازمين منخفض + نحاس بول مرتفع + حلقة كايزر-فلايشر."},{"f":"في أي عمر يظهر داء ويلسون عادة، ولماذا لا يسبب قصور كبد حاد تحت السنتين؟","b":"يظهر بعد 5 سنوات (تراكم النحاس يحتاج سنوات). قصور الكبد الحاد تحت السنتين أسبابه: إنتانية/استقلابية/مناعية — لا ويلسون."},{"f":"ما أسباب قصور الكبد الحاد عند الرضع دون السنتين؟","b":"أخماج فيروسية (هربس)، اضطرابات استقلابية (غالاكتوزيميا، تيروزينيميا)، التهاب كبد مناعي، سموم. التشخيص السريع حاسم (أمونيا، سكر، تخثر)."},{"f":"هل التهاب الكبد A يسبب مرضًا كبديًا مزمنًا عند الأطفال؟","b":"لا — التهاب الكبد A حاد self-limited ولا يتطور لمرض مزمن أبدًا (بعكس B وC). الوقاية: لقاح + نظافة."},{"f":"طفل: مرض كبدي مزمن + سوء امتصاص: أي فيتامين يُمتص بسوء؟","b":"الفيتامينات الذوابة بالدهون (A, D, E, K) — الركودة الصفراوية تعيق امتصاص الدهون. البروتين يُمتص طبيعيًا (سوء الامتصاص البروتيني ليس من سمات المرض الكبدي المزمن)."},{"f":"ما علامات فرط توتر وريد الباب عند الطفل المصاب بتشمع؟","b":"ضخامة طحال + قلة صفيحات (فرط طحالية)، دوالي مريء (نزف)، رأس مدوسة، استسقاء. النزف الدوالي أخطر اختلاط حاد."},{"f":"وليد: يرقان مطوّل + براز طبيعي اللون + أم HBsAg سلبية: ما الأسباب؟","b":"يرقان غير انسدادي مطوّل: حليب الأم (Breast milk jaundice)، قصور درق خلقي، إنتان بولي، انحلال (ABO/G6PD). البراز الملون ينفي الرتق الصفراوي."},{"f":"طفل 10 سنوات: ALT مرتفع مزمن + بدانة: التشخيص الأرجح؟","b":"الكبد الدهني غير الكحولي (NAFLD) — الأشيع بعصر البدانة. التشخيص: إيكو + نفي أسباب أخرى؛ العلاج: إنقاص وزن."}]},{"t":"الأمراض الخبيثة","cards":[{"f":"ما التظاهر الأشيع لورم ويلمز (النفروبلاستوما)؟","b":"كتلة بطنية عند طفل لا عرضي (تكتشفها الأم أثناء الاستحمام) — بعمر 2–5 سنوات. الألم نادر. لا تُجس بعنف (خطر تمزق المحفظة)."},{"f":"طفل 4 سنوات: كتلة بطنية + ارتفاع ضغط: ويلمز أم نوروبلاستوما؟","b":"نوروبلاستوما: كتلة بطنية + ارتفاع ضغط (كاتيكولامينات) + قد تعبر الخط الناصف. ويلمز: كلوي المنشأ، لا يعبر الناصف، ضغط غالبًا طبيعي."},{"f":"ما السبب الأشيع لكتلة بطنية عند حديث الولادة؟","b":"النوروبلاستوما — أشيع ورم صلب خارج القحف عند الأطفال وأشيع كتلة بطنية ولادية. الواسم: حمض الفانيليل مندليك (VMA) بالبول."},{"f":"في أي ورم يرتفع ألفا فيتو بروتين (AFP)؟","b":"أورام الكبد (الهيباتوبلاستوما) وأورام الكيس المحي (Yolk sac). بيتا-hCG يرتفع في المشيمائي والورم المنوي."},{"f":"ما عوامل سوء الإنذار في الابيضاض اللمفاوي الحاد (ALL)؟","b":"ارتفاع الكريات البيض عند التشخيص (>50,000)، عمر <1 سنة أو >10 سنوات، نمط T، إصابة CNS/خصية، استجابة بطيئة للعلاج. نقص البيض ليس سيئًا."},{"f":"طفل: ضخامة عقد رقبية 4 سم قاسية غير مؤلمة بطيئة التطور: التشخيص؟","b":"لمفوما هودجكن: عقد مطاطية غير مؤلمة (الألم بالجس ينفيها غالبًا)، قد تترافق بأعراض B (حرارة، تعرق ليلي، نقص وزن). التشخيص: خزعة عقدة (خلايا ريد-شترنبرغ)."},{"f":"ما ذروة عمر حدوث الابيضاض اللمفاوي الحاد؟","b":"2–5 سنوات — أشيع خباثة عند الأطفال. التظاهر: حرارة، شحوب، نزف/فرفرية، آلام عظمية، ضخامة كبد طحال وعقد."},{"f":"ما الآثار الجانبية الباكرة للعلاج الكيماوي عند الأطفال؟","b":"غثيان/إقياء، تساقط شعر، التهاب مخاطية، نقص عدلات (إنتانات)، فقر دم ونقص صفيحات. قصور الدرق ليس باكرًا (متأخر بعد إشعاع)."},{"f":"طفل ALL: متى يُشتبه بإصابة الجهاز العصبي؟","b":"صداع، إقياء صباحي، شلل أعصاب قحفية — البزل القطني للتشخيص + حقن ميتوتركسات داخل القراب وقائيًا/علاجيًا."},{"f":"ما الفرق بين اللوكيميا الحادة والمزمنة بعمر الطفولة؟","b":"عند الأطفال الغالبية العظمى حادة (ALL ثم AML)؛ اللوكيميا المزمنة (CML) نادرة جدًا. أي لوكيميا طفولة تُعامَل كحادة حتى يثبت العكس."},{"f":"طفل: ألم عظمي ليلي + عرج + صورة: آفة عظمية: ما المشتبه؟","b":"ساركوما (عظمية/يوينغ) بعمر المراهقة: ألم ليلي متفاقم + كتلة. الخزعة قبل أي تدخل. الألم الليلي الموقظ علامة خطر دائمًا."},{"f":"ما أشيع ورم دماغي عند الأطفال ومكانه؟","b":"الورم النجمي المخيخي (Astrocytoma) — الحفرة الخلفية: رنح، صداع صباحي، إقياء. بعكس البالغين (نصف الكرة المخي)."}]},{"t":"الاضطرابات الدموية","cards":[{"f":"ما العلامة السريرية المميزة لفقر الدم بعوز الحديد الشديد؟","b":"شهوة الطين/أكل مواد غير غذائية (PICA). مخبريًا: حديد ومخزون (فيريتين) منخفض، سعة رابطة مرتفعة، كريات صغيرة ناقصة الصباغ."},{"f":"طفل سنتان: فقر دم + يرقان + شبكيات مرتفعة قليلًا منذ يومين: التشخيص؟","b":"هجمة فوال (G6PD): انحلال حاد بعد الفول/عدوى/دواء مؤكسد. هينز بوديز؛ العلاج داعم + تجنب المحرض. الباراسيتامول آمن (ليس من المحرضات)."},{"f":"ما الذي يؤكد فقر الدم الانحلالي مخبريًا؟","b":"ارتفاع الشبكيات + ارتفاع بيليروبين غير مباشر + LDH مرتفع + هابتوغلوبين منخفض. نقص طلائع النقي ينفي الانحلال (يوجّه لنقص تصنع)."},{"f":"طفل: تكور كريات وراثي — ما نتيجة كومبس؟","b":"كومبس سلبي (انحلال غير مناعي — عيب غشائي/سبكترين). كومبس إيجابي = انحلال مناعي (ABO/Rh، مناعي ذاتي)."},{"f":"ما الفرق بين التلاسيميا الكبرى وفقر الدم المنجلي في ضخامة الطحال؟","b":"التلاسيميا الكبرى: ضخامة طحال مستمرة (فرط تصنع). المنجلي: ضخامة باكرة ثم ضمور ذاتي (احتشاءات متكررة) — بلا طحال وظيفي بعمر المدرسة (خطر المكورات)."},{"f":"ما محرضات النوب الألمية في الداء المنجلي؟","b":"التجفاف، البرد، الإنتان، نقص الأكسجة، الجهد. الإماهة علاج لا محرض. الوقاية: هيدروكسي يوريا + بنسلين وقائي + لقاحات."},{"f":"ما الفرق المخبري بين الناعور A وداء فون ويلبراند؟","b":"الناعور A: PTT متطاول، PT طبيعي، نزف مفصلي/عضلي، وراثة مرتبطة بـ X. فون ويلبراند: نزف مخاطي/جلدي (رعاف، غزارة طمث)، زمن نزف متطاول، وراثة جسمية سائدة غالبًا."},{"f":"ما العامل الذي يقيمه زمن البروثرومبين (PT)؟","b":"الطريق الخارجي والمشترك — خاصة العامل VII (الأقصر عمرًا فيتأثر أولًا). PTT يقيم الداخلي (VIII, IX, XI, XII)."},{"f":"وليد 4 أيام: نزف من السرة + كدمات + PT وPTT متطاولان: التشخيص؟","b":"الداء النزفي الوليدي (عوز فيتامين K): ولادة منزلية بلا فيتامين K + إرضاع والدي. العلاج: فيتامين K وريدي + بلازما عند النزف الشديد. الوقاية: 1 ملغ عضلي عند الولادة."},{"f":"طفل 5 سنوات: فرفرية وكدمات معزولة بعد خمج فيروسي + صفيحات منخفضة: التشخيص؟","b":"نقص الصفيحات المناعي (ITP): بلا ضخامة حشوية، بلا فقر دم. غالبًا self-limited؛ العلاج عند النزف الشديد: IVIG/ستيروئيد."},{"f":"ما العرض الأقل حدوثًا في نقص الصفيحات؟","b":"النزف داخل المفصل (سمة الناعور لا نقص الصفيحات) والنزف الدماغي نادر. الغالب: فرفرية، كدمات، رعاف، نزف لثوي."},{"f":"طفل: حرارة + شحوب + فرفرية منذ 4 أسابيع: ما التشخيص المشتبه قبل كل شيء؟","b":"ابيضاض الدم الحاد (ALL) — ثلاثية قصور النقي: فقر دم + نقص عدلات (حرارة) + نقص صفيحات (نزف). التشخيص: تعداد + مسحة + بزل نقي."},{"f":"ما الفرق بين فقر الدم بعوز الحديد والتلاسيميا الصغرى مخبريًا؟","b":"كلاهما صغير ناقص الصباغ؛ التلاسيميا الصغرى: HbA2 مرتفع + تعداد كريات مرتفع نسبيًا + RDW طبيعي؛ عوز الحديد: فيريتين منخفض + RDW مرتفع. الحديد لا يفيد التلاسيميا."},{"f":"متى يظهر فقر الدم الفيزيولوجي عند الرضيع؟","b":"بعمر 6–12 أسبوعًا (نادرًا قبل ذلك): هبوط فيزيولوجي للخضاب مع تحول HbF→HbA. ليس مرضًا — لا يُعالَج بالحديد روتينيًا."}]},{"t":"الداء السكري واضطرابات الغدد الصم","cards":[{"f":"وليد 10 أيام: أعضاء تناسلية مبهمة + صوديوم منخفض + بوتاسيوم مرتفع: التشخيص والعلاج الدائم؟","b":"فرط تنسج الكظر الخلقي (عوز 21-هيدروكسيلاز): العلاج الدائم هيدروكورتيزون (يُعوَّض الكورتيزول ويكبح ACTH) + فلودروكورتيزون للصوديوم. حالة إسعافية عند الشك."},{"f":"طفل: نوب نقص سكر متكررة + اسمرار لحف وتصبغ ثنيات: التشخيص؟","b":"قصور كظر أولي (أديسون): ارتفاع ACTH يسبب التصبغ + نقص كورتيزول يسبب نقص السكر ونقص الصوديوم. الثانوي (نخامي) بلا تصبغ."},{"f":"ما العلامة السريرية الثابتة في متلازمة كوشينغ عند الأطفال؟","b":"البدانة (جذعية/وجه قمري) — العلامة الثابتة. يرافقها: توقف/تباطؤ النمو الطولي (يميزها عن البدانة البسيطة)، ارتفاع ضغط، شعر زائد."},{"f":"طفلة 9 سنوات: نقص وزن + جحوظ + نشاط زائد + تراجع دراسي: التشخيص والواسم؟","b":"داء غريفز (فرط درق مناعي): أضداد مستقبل TSH إيجابية. العلاج: كاربيمازول؛ اليود المشع/الجراحة عند النكس. زيادة الشهية مع نقص وزن (لا زيادة وزن)."},{"f":"طفل 12 سنة: تباطؤ سرعة النمو + درق متضخم: التشخيص الأرجح؟","b":"داء هاشيموتو (التهاب درق مناعي مزمن): أشيع سبب لقصور الدرق المكتسب عند الأطفال — أضداد anti-TPO. العلاج: ثيروكسين مدى الحياة غالبًا."},{"f":"رضيع: اختلاجات + تراجع فك سفلي + غياب التيموس بالصورة: ما التحليل الموجِّه للعلاج؟","b":"متلازمة دي جورج (حذف 22q11): نقص جارات الدرق → نقص كلس الدم يسبب الاختلاجات. العلاج: كالسيوم + فيتامين D؛ وتقييم مناعي وقلبي."},{"f":"ما معايير تشخيص الداء السكري عند الأطفال؟","b":"سكر صيامي ≥126، أو عشوائي ≥200 مع أعراض، أو OGTT ساعتين ≥200، أو HbA1c ≥6.5%. البيلة السكرية وحدها ليست معيارًا."},{"f":"ما الأعراض الباكرة للداء السكري نمط 1 عند الطفل؟","b":"بوال، عطاش، نقص وزن، تعب — أسابيع. الألم البطني والتنفس الحماضي (كوسماول) من علامات الحماض الكيتوني المتأخرة لا الباكرة."},{"f":"ما أساس علاج الحماض الكيتوني السكري عند الطفل؟","b":"سوائل وريدية + أنسولين وريدي مستمر + تعويض بوتاسيوم — بعد التأكد من التبول. لا بيكربونات روتينيًا؛ مراقبة وذمة دماغية (صداع/تدهور وعي)."},{"f":"متى يُشتبه بالسكري نمط 2 (لا نمط 1) عند الطفل؟","b":"مراهق بدين + شواك أسود (Acanthosis) + قصة عائلية قوية + بداية تدريجية. الترافق مع هاشيموتو يوجّه للنمط 1 (مناعي)."},{"f":"ما النظام الغذائي الصحي للطفل السكري نمط 1؟","b":"وجبات منتظمة محسوبة الكربوهيدرات + زيادة الألياف + دهون صحية؛ لا حرمان كامل من السكريات بل توزيتها مع الأنسولين. التثقيف الغذائي أساس الضبط."},{"f":"ما استطبابات العلاج بهرمون النمو؟","b":"عوز هرمون النمو المثبت، قصر القامة البنيوي الشديد المختار، متلازمة تيرنر، قصور كلوي مزمن، صغير الحجم الوليدي بلا لحاق. يُعطى قبل انغلاق المشاشات."},{"f":"ما المشترك بين قصور الدرق وفرط نشاطها عند الأطفال؟","b":"اضطرابات التعلم والتركيز قد تُشاهد في الحالتين. القصور: خمول وإمساك وبطء؛ الفرط: هياج ونقص وزن ورجفان."}]},{"t":"الاضطرابات العضلية الهيكلية","cards":[{"f":"ما مفتاح تشخيص التهاب العظم والنقي عند الطفل المحموم؟","b":"رفض تحريك الطرف (Pseudoparalysis) + ألم موضعي + حرارة. الصورة الباكرة قد تكون طبيعية — التشخيص سريري + مخبري (CRP/ESR)."},{"f":"ما صفات آلام النمو عند الأطفال؟","b":"ألم ساقين مسائي/ليلي يوقظ الطفل، بلا عرج نهاري، فحص سوي، ثنائي. التشخيص بالاستبعاد — الألم النهاري أو الأحادي أو مع عرج = عضوي."},{"f":"طفل: مفصل واحد ساخن متورم مؤلم + حرارة: التشخيص والتدبير؟","b":"التهاب مفصل إنتاني (أحادي غالبًا — الركبة/الورك): بزل مفصلي إسعافي + صادات وريدية. التأخر = تخرب غضروفي دائم."},{"f":"ما المفاصل التي يصيبها التهاب المفصل الارتكاسي غالبًا؟","b":"الكاحلان والركبتان (مفاصل كبيرة سفلية) — تالٍ لإنتان معوي/بولي (ثالوث رايتر: مفاصل + ملتحمة + إحليل)."},{"f":"طفل 3 سنوات: عرج صباحي + تيبس >30 دقيقة يتحسن بالحركة: التشخيص؟","b":"التهاب المفصل مجهول السبب اليفعي (JIA): تيبس صباحي مطوّل + التهاب مفاصل >6 أسابيع بعمر <16 سنة. يُحال لروماتيزم أطفال."},{"f":"مراهق: ألم ركبة أمامي مع صعود الدرج بلا رض: التشخيص؟","b":"متلازمة الألم الفخذي الرضفي (Patellofemoral): شائعة بالمراهقة، تتحسن بالعلاج الفيزيائي وتقوية رباعية الرؤوس. لا جبيرة مطوّلة."}]},{"t":"الاضطرابات العصبية","cards":[{"f":"ما العلامة المميزة للاستسقاء الدماغي (Hydrocephalus) عند الرضع؟","b":"علامة غروب الشمس (Sunset eyes) + تضخم محيط الرأس + يافوخ متوتر + أوردة فروة بارزة. العلاج: تحويلة بطينية."},{"f":"طفل 4 سنوات: رنح واضطراب مشية بعد أسبوع من طفح حويصلي حاك: التشخيص؟","b":"التهاب المخيخ التالي للحماق: أشيع اختلاط عصبي للحماق — رنح حاد حميد يشفى عفويًا خلال أسابيع."},{"f":"ما الذي يميز غيلان-باريه عن شلل الأطفال؟","b":"غيلان-باريه: شلل صاعد متناظر + افتراق ألبوميني خلوي بالبزل (بروتين مرتفع/خلايا طبيعية) + تحسن عفوي هو القاعدة. شلل الأطفال: شلل رخو غير متناظر غير مؤلم."},{"f":"هل تُسرّع الستيروئيدات الشفاء في غيلان-باريه؟","b":"لا — البردنيزولون لا يسرّع الشفاء (قد يضر). العلاج: IVIG أو فصادة بلازما للحالات الشديدة + دعم تنفسي."},{"f":"ما علامة التسلق (Gower) وفي أي مرض تُشاهد؟","b":"الطفل يتسلق على فخذيه بيديه للنهوض من الأرض — ضعف الحزام الحوضي في حثل دوشين العضلي (وراثة مرتبطة بـ X، غياب الديستروفين)."},{"f":"ما الصحيح في داء ويردينغ-هوفمان (SMA type 1)؟","b":"تقلصات حزمية باللسان + ضعف عضلي شديد + غياب منعكسات — يظهر بعمر الرضاعة. إصابة الحجاب الحاجز متأخرة (التنفس بالحجاب محفوظ باكرًا)."},{"f":"ما صفات الاختلاج الحروري البسيط؟","b":"عمر 6 أشهر–5 سنوات، معمم، <15 دقيقة، مرة واحدة/24 ساعة، شفاء تام سريع. الزرقة المرافقة لا تسبب أذية دماغية؛ ولا يزيد خطر الصرع اللاحق."},{"f":"ما الذي يستبعد تشخيص الاختلاج الحروري البسيط؟","b":"الاختلاج الموضعي (بؤري)، أو المطوّل >15 دقيقة، أو المتكرر خلال 24 ساعة، أو خارج عمر 6 أشهر–5 سنوات، أو شلل تالٍ (Todd)."},{"f":"طفل: اختلاج مستمر >5 دقائق: الخط الأول؟","b":"ديازيبام شرجي/وريدي (أو ميدازولام) — الحالة الصرعية: بنزوديازيبين أولًا، ثم فينيتوين/ليفيتيراسيتام. لا يُنتظَر."},{"f":"ما أشيع سبب لتشنجات الطفولة (Infantile spasms) الذي يجب البحث عنه؟","b":"التصلب الحدبي (Tuberous sclerosis): بقع ناقصة الصباغ + شمعات شبكية + تشنجات. العلاج: فيغاباترين أولًا."},{"f":"ما صفات نوب الغياب (Absence)؟","b":"توقف وعي ثوانٍ (لا 1–2 دقيقة)، تحديث متكرر يوميًا، تخطيط: موجة-شوكة 3/ثانية. العلاج: إيثوسوكسيميد. تُثار بفرط التنفس."},{"f":"ما علامات الصداع المنذرة بآفة شاغلة للحيز عند الطفل؟","b":"صداع صباحي مع إقياء، يوقظ من النوم، متفاقم تدريجيًا، علامات عصبية بؤرية، تغير سلوك/مدرسة. رهاب الضوء وحده ليس منذرًا (سمة الشقيقة)."},{"f":"متى يكون البزل القطني مضاد استطباب، ومتى يكون مستطبًا رغم ارتفاع الضغط؟","b":"مضاد استطباب: علامات انفتاق/آفة شاغلة (وذمة حليمة + بؤرية)، إنتان جلدي موضعي، اعتلال تخثر شديد. مستطب: ارتفاع التوتر القحفي مجهول السبب (IIH) — تشخيصي وعلاجي."},{"f":"ما الصحيح في الصرع الرولاندي (الحميد برولاندي)؟","b":"صرع طفولة حميد: نوب وجهية-فموية ليلية، يشفى بالبلوغ غالبًا، سوابق عائلية شائعة. لا يحتاج علاجًا مطوّلًا بعد نوبة وحيدة."}]}]}];